export interface GenesisRequest {
  originalIdea: string;
  clarifiedSpecs: {
    platform: 'web' | 'mobile_react_native' | 'electron';
    coreFeatures: string[];
    uiStyle: 'modern' | 'minimalist' | 'corporate';
    backendType: 'firebase' | 'node_custom' | 'supabase';
    constraints: string[];
  };
  status: 'idea' | 'defining' | 'architecting' | 'coding' | 'testing' | 'deployed';
}

export interface SystemBlueprint {
  techStack: {
    language: string;
    frameworks: string[];
    database: string;
    thirdPartyAPIs: string[];
  };
  architectureDiagram: string;
  fileStructure: string[];
  modules: ModuleDefinition[];
}

export interface ModuleDefinition {
  id: string;
  type: 'backend' | 'frontend_ui' | 'logic';
  assignedAgent: 'Developer' | 'UXDesigner';
  dependencies: string[];
  prompt: string;
  acceptanceCriteria: string[];
}

export default class ArchitectAgent implements IAgent {
  name = 'Architect';
  description =
    'Rendszerarchitektúra tervezés - SystemBlueprint, tech stack és modul definíciók generálása';
  role = 'architect';
  capabilities = [
    'architecture_design',
    'tech_stack_selection',
    'module_decomposition',
    'dependency_mapping',
    'blueprint_generation',
    'requirement_interview',
    'human_in_the_loop',
  ];

  // Phase 1: interview + approval állapot
  private _currentBlueprint: SystemBlueprint | null = null;
  private _isApproved = false;
  private _interviewAnswers: Record<string, string> = {};

  get currentBlueprint() { return this._currentBlueprint; }
  get isApproved() { return this._isApproved; }

  async execute(
    task: string,
    context?: { swarm?: ISwarmContext; [key: string]: unknown }
  ): Promise<AgentResponse> {
    setAgentStatus(this.name, 'working', task.slice(0, 50));

    try {
      const taskLower = task.toLowerCase();

      // ── Human-in-the-Loop: Jóváhagyás ───────────────────────────────────
      if (taskLower.includes('jóváhagyom') || taskLower.includes('approve') || taskLower.includes('elfogadom')) {
        if (!this._currentBlueprint) {
          return { status: 'error', error: 'Nincs generált blueprint. Először hívd "tervezd meg: <leírás>".' };
        }
        this._isApproved = true;
        logInfo(this.name, `Blueprint jóváhagyva: ${this._currentBlueprint.modules.length} modul`);
        return {
          status: 'success',
          data: this._currentBlueprint,
          message: `✅ Blueprint jóváhagyva! ${this._currentBlueprint.modules.length} modul kész fejlesztésre. Delegálom a DeveloperAgent-nek.`,
          nextStep: 'developer',
        };
      }

      // ── Blueprint státusz ────────────────────────────────────────────────
      if (taskLower.includes('státusz') || taskLower.includes('status')) {
        if (!this._currentBlueprint) {
          return { status: 'success', data: null, message: 'Nincs aktív blueprint.' };
        }
        const approvalStatus = this._isApproved ? '✅ Jóváhagyva' : '⏳ Jóváhagyásra vár';
        return {
          status: 'success',
          data: { blueprint: this._currentBlueprint, is_approved: this._isApproved },
          message: `📐 Blueprint: ${approvalStatus} | Modulok: ${this._currentBlueprint.modules.length}`,
        };
      }

      // ── Tervezés (Phase 1 fő feladat) ────────────────────────────────────
      logInfo(this.name, `Architecture design task: ${task}`);
      const request = this.parseRequest(task, context as { swarm?: ISwarmContext });
      if (!request.clarifiedSpecs || request.clarifiedSpecs.coreFeatures.length === 0) {
        return {
          status: 'error',
          error: 'GenesisRequest must have clarifiedSpecs with core features',
        };
      }

      logInfo(this.name, `Designing architecture for ${request.clarifiedSpecs.platform} app with ${request.clarifiedSpecs.coreFeatures.length} features`);
      const blueprint = await this.generateBlueprint(request);
      this._currentBlueprint = blueprint;
      this._isApproved = false;

      logInfo(this.name, `Blueprint generated: ${blueprint.modules.length} modules`);

      return {
        status: 'success',
        data: blueprint,
        message: `📐 SystemBlueprint generálva: ${blueprint.modules.length} modul, ${blueprint.techStack.frameworks.join(', ')}.\n✋ Hívd "jóváhagyom" a fejlesztés indításához.`,
        handoff: {
          type: 'handoff',
          targetAgent: 'specwriter',
          instruction: 'Break down modules into detailed task definitions',
          reason: 'SystemBlueprint complete, ready for task engineering',
        },
      };
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError(this.name, `Architecture design failed: ${error}`);
      return { status: 'error', error: `Architecture design failed: ${error}` };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  private parseRequest(task: string, context?: { swarm?: ISwarmContext }): GenesisRequest {
    if (context?.swarm?.artifacts?.['genesisRequest']) {
      return context.swarm.artifacts['genesisRequest'] as GenesisRequest;
    }

    // Fallback: extract from task
    return {
      originalIdea: task,
      clarifiedSpecs: {
        platform: 'web',
        coreFeatures: ['feature1', 'feature2'],
        uiStyle: 'modern',
        backendType: 'node_custom',
        constraints: [],
      },
      status: 'architecting',
    };
  }

  private async generateBlueprint(request: GenesisRequest): Promise<SystemBlueprint> {
    const { platform, backendType, coreFeatures } = request.clarifiedSpecs;

    // Select tech stack based on specs
    const techStack = this.selectTechStack(platform, backendType);

    // Generate architecture diagram
    const architectureDiagram = this.generateArchitectureDiagram(techStack, coreFeatures);

    // Generate file structure
    const fileStructure = this.generateFileStructure(platform, techStack);

    // Decompose into modules
    const modules = await this.decomposeModules(request, techStack);

    return {
      techStack,
      architectureDiagram,
      fileStructure,
      modules,
    };
  }

  private selectTechStack(
    platform: string,
    backendType: string
  ): SystemBlueprint['techStack'] {
    const stacks: Record<string, SystemBlueprint['techStack']> = {
      web: {
        language: 'TypeScript',
        frameworks: ['React', 'Vite', 'Express'],
        database: backendType === 'firebase' ? 'Firestore' : 'PostgreSQL',
        thirdPartyAPIs: [],
      },
      mobile_react_native: {
        language: 'TypeScript',
        frameworks: ['React Native', 'Expo'],
        database: backendType === 'firebase' ? 'Firestore' : 'Supabase',
        thirdPartyAPIs: [],
      },
      electron: {
        language: 'TypeScript',
        frameworks: ['Electron', 'React', 'Vite'],
        database: 'SQLite',
        thirdPartyAPIs: [],
      },
    };

    return stacks[platform] || stacks['web'];
  }

  private generateArchitectureDiagram(
    techStack: SystemBlueprint['techStack'],
    features: string[]
  ): string {
    return `
# System Architecture

\`\`\`
┌─────────────────────────────────────┐
│     Frontend (${techStack.frameworks[0]})     │
├─────────────────────────────────────┤
│  - UI Components                    │
│  - State Management                 │
│  - API Client                       │
└──────────────┬──────────────────────┘
               │
               ▼
┌─────────────────────────────────────┐
│      Backend (${techStack.frameworks[2] || 'API'})        │
├─────────────────────────────────────┤
│  - REST API Endpoints               │
│  - Business Logic                   │
│  - Authentication                   │
└──────────────┬──────────────────────┘
               │
               ▼
┌─────────────────────────────────────┐
│      Database (${techStack.database})       │
└─────────────────────────────────────┘

Core Features:
${features.map((f, i) => `${i + 1}. ${f}`).join('\n')}
\`\`\`
`.trim();
  }

  private generateFileStructure(
    platform: string,
    techStack: SystemBlueprint['techStack']
  ): string[] {
    const structures: Record<string, string[]> = {
      web: [
        'src/app.ts',
        'src/components/',
        'src/pages/',
        'src/api/',
        'src/utils/',
        'src/types/',
        'server/index.ts',
        'server/routes/',
        'server/middleware/',
        'server/db/',
        'package.json',
        'tsconfig.json',
        'vite.config.ts',
      ],
      mobile_react_native: [
        'src/App.tsx',
        'src/screens/',
        'src/components/',
        'src/navigation/',
        'src/services/',
        'src/utils/',
        'app.json',
        'package.json',
        'tsconfig.json',
      ],
      electron: [
        'src/main.ts',
        'src/renderer/',
        'src/preload.ts',
        'src/components/',
        'src/pages/',
        'package.json',
        'electron-builder.json',
      ],
    };

    return structures[platform] || structures['web'];
  }

  private async decomposeModules(
    request: GenesisRequest,
    techStack: SystemBlueprint['techStack']
  ): Promise<ModuleDefinition[]> {
    const modules: ModuleDefinition[] = [];
    const { coreFeatures } = request.clarifiedSpecs;

    // Frontend modules
    for (let i = 0; i < coreFeatures.length; i++) {
      modules.push({
        id: `module_frontend_${i + 1}`,
        type: 'frontend_ui',
        assignedAgent: 'UXDesigner',
        dependencies: [],
        prompt: `Create UI component for "${coreFeatures[i]}" using ${techStack.frameworks[0]}`,
        acceptanceCriteria: [
          'Component renders correctly',
          'Responsive design',
          'Accessibility compliance',
        ],
      });
    }

    // Backend modules
    for (let i = 0; i < coreFeatures.length; i++) {
      modules.push({
        id: `module_backend_${i + 1}`,
        type: 'backend',
        assignedAgent: 'Developer',
        dependencies: [`module_frontend_${i + 1}`],
        prompt: `Implement backend API for "${coreFeatures[i]}" using ${techStack.frameworks[2] || 'Express'}`,
        acceptanceCriteria: [
          'API endpoint functional',
          'Input validation',
          'Error handling',
          'Unit tests pass',
        ],
      });
    }

    return modules;
  }
}

/**
 * BaseAgent - Alaposztály az AgentContext/AgentResult használó ügynököknek
 * EdgeProxyAgent, ProjectConductorAgent öröklik
 *
 * IAgent-kompatibilis: az execute(task, context?) bridge automatikusan
 * átalakítja az IAgent hívást AgentContext formátumra.
 */

import { IAgent, ISwarmContext, AgentHandoff, AgentResponse } from './types.js';
import { formatAgentResult } from '../utils/responseFormatter.js';
import { searchRAG, addToIndex } from '../utils/rag.js';
import { logInfo, logError } from '../utils/logger.js';
import { validateAgentResult } from './middleware/validateOutput.js';
import { calculateConfidence } from './scoring/confidenceCalculator.js';
import { wrapWithSpan } from '../utils/otelTracing.js';
import { safeRedactAgentOutput } from '../security/redactor.js';
import { checkPattern } from '../core/patternReuse.js';
import { queryMemory as queryStructuredMemory, saveMemory as saveStructuredMemory, type StoredAgentMemory } from '../core/structuredMemory.js';

export interface AgentContext {
  task?: string;
  swarm?: ISwarmContext;
  payload?: {
      bankCsvPath?: string;
      [key: string]: unknown;
  };
  [key: string]: unknown;
}

export interface AgentResult {
  success: boolean;
  message: string;
  status?: string;       // Opcionális státusz (pl. 'success', 'error' - teszt kompatibilitás)
  data?: unknown;
  handoff?: AgentHandoff;
  thoughts?: string;
  contextUsed?: string[];
  metadata?: Record<string, unknown>;        // Egyéb metaadatok (pl. source, confidence)
}

export abstract class BaseAgent implements IAgent {
  abstract name: string;
  abstract description: string;
  abstract role: string;
  capabilities: string[] = [];

  // Opcionális Swarm Context (ha az AgentManager/SwarmManager átadja)
  protected swarmContext?: ISwarmContext;

  protected isTestMode(): boolean {
    return (
      process.env.NODE_ENV === 'test' ||
      process.env.VITEST === 'true' ||
      process.env.VITEST_WORKER_ID !== undefined
    );
  }

  /**
   * Belső végrehajtás – a leszármazottak ezt implementálják.
   */
  abstract executeTask(context: AgentContext): Promise<AgentResult>;

  private toStructuredExperience(memory: StoredAgentMemory): { text: string; score?: number } {
    const resultRecord = typeof memory.result === 'object' && memory.result !== null
      ? memory.result as Record<string, unknown>
      : null;
    const message = resultRecord && typeof resultRecord.message === 'string'
      ? resultRecord.message
      : JSON.stringify(memory.result);

    return {
      text: `StructuredMemory | Task: ${memory.rawTask} | Result: ${message}`,
      score: memory.confidence,
    };
  }

  private normalizeCachedResult(cached: unknown): AgentResult {
    if (typeof cached === 'object' && cached !== null) {
      const record = cached as Record<string, unknown>;
      const success = typeof record.success === 'boolean'
        ? record.success
        : record.status === 'success';
      const message = typeof record.message === 'string'
        ? record.message
        : 'Találat a strukturált memóriában.';

      return {
        success,
        message,
        status: typeof record.status === 'string' ? record.status : success ? 'success' : 'error',
        data: record.data,
        handoff: record.handoff as AgentHandoff | undefined,
        thoughts: typeof record.thoughts === 'string' ? record.thoughts : undefined,
        contextUsed: Array.isArray(record.contextUsed)
          ? record.contextUsed.filter((item): item is string => typeof item === 'string')
          : undefined,
        metadata: typeof record.metadata === 'object' && record.metadata !== null
          ? { ...(record.metadata as Record<string, unknown>) }
          : {},
      };
    }

    return {
      success: true,
      message: 'Találat a strukturált memóriában.',
      data: cached,
      metadata: {},
    };
  }

  /**
   * IAgent-kompatibilis execute bridge.
   * Az AgentManager és az MCP eszközök egységesen hívhatják:
   *   agent.execute(task, context?)
   *
   * Magyar nyelvű válaszokat ad vissza az AgentResult formázásával.
   */
  async execute(task: string, context?: AgentContext): Promise<AgentResponse> {
    const testMode = this.isTestMode();

    if (!testMode) {
      const cachedPattern = await wrapWithSpan(
        'bas-base-agent', `${this.name}::pattern-reuse`,
        { 'bas.agent.name': this.name, 'bas.operation': 'pattern_reuse' },
        async () => checkPattern<AgentResult>(this.name, task),
      );

      if (cachedPattern.matched && cachedPattern.memory) {
        const cachedResult = this.normalizeCachedResult(cachedPattern.memory.result);
        if (!cachedResult.metadata) {
          cachedResult.metadata = {};
        }
        cachedResult.metadata.confidence = cachedPattern.memory.confidence;
        cachedResult.metadata.fromCache = true;
        cachedResult.metadata.cachedAt = cachedPattern.memory.updatedAt;
        cachedResult.metadata.reuseCount = cachedPattern.memory.reuseCount;

        validateAgentResult(cachedResult, this.name);

        const formattedMessage = formatAgentResult(cachedResult, this.name, { useEmojis: true });
        return safeRedactAgentOutput({
          success: cachedResult.success,
          status: cachedResult.success ? 'success' : 'error',
          message: formattedMessage,
          data: cachedResult.data,
          error: cachedResult.success ? undefined : cachedResult.message,
          handoff: cachedResult.handoff,
        }, this.name);
      }
    }

    // 1. Kognitív memória lekérdezése végrehajtás előtt (OTel sub-span)
    const pastExperiences = testMode ? [] : await wrapWithSpan(
      'bas-base-agent', `${this.name}::rag-query`,
      { 'bas.agent.name': this.name, 'bas.operation': 'rag_query' },
      () => this.queryMemory(task, 3),
    );
    
    const agentContext: AgentContext = {
      task,
      pastExperiences, // Átadjuk az ügynöknek a múltbeli tapasztalatokat
      ...(context || {})
    };

    const result = await this.executeTask(agentContext);

    // 2. Guardrails: AgentResult validáció
    validateAgentResult(result, this.name);

    // 3. Confidence scoring
    const confidence = calculateConfidence(result);
    if (!result.metadata) result.metadata = {};
    result.metadata.confidence = confidence.score;
    result.metadata.confidenceFactors = confidence.factors;

    // 4. Tapasztalat mentése a memóriába (OTel sub-span)
    // Teszt módban kihagyjuk a perzisztens RAG IO-t a stabilitás/gyorsaság miatt.
    if (!testMode) {
      saveStructuredMemory({
        agentName: this.name,
        task,
        result,
        confidence: confidence.score,
        status: result.success ? 'success' : 'error',
      });

      const outcome = result.success ? 'SIKER' : 'HIBA';
      const experienceContent = `Feladat: "${task}" | Eredmény: ${outcome} | Üzenet: ${result.message}`;
      await wrapWithSpan(
        'bas-base-agent', `${this.name}::memory-save`,
        { 'bas.agent.name': this.name, 'bas.operation': 'memory_save', 'bas.confidence': confidence.score },
        () => this.saveToMemory(experienceContent, {
          status: result.success ? 'success' : 'error',
          taskId: context?.taskId
        }),
      );
    }

    // Format result as Hungarian human-readable text
    const formattedMessage = formatAgentResult(result, this.name, { useEmojis: true });

    // 5. PII/Secret redakció az output-on
    const response: AgentResponse = {
      success: result.success,
      status: result.success ? 'success' : 'error',
      message: formattedMessage,
      data: result.data,
      error: result.success ? undefined : result.message,
      handoff: result.handoff,
    };

    return safeRedactAgentOutput(response, this.name);
  }

  /**
   * Helper a végrehajtás átadásához
   */
  protected createHandoff(targetAgent: string, instruction: string, reason: string): AgentResult {
    return {
      success: true, // A handoff maga sikeres művelet
      message: `Handoff to ${targetAgent}: ${reason}`,
      handoff: {
        type: 'handoff',
        targetAgent,
        instruction,
        reason
      }
    };
  }

  /**
   * Query the agent's cognitive memory (LanceDB)
   */
  protected async queryMemory(query: string, limit = 5): Promise<Array<{ text: string; score?: number }>> {
    logInfo(this.name, `Memória lekérdezése: "${query.substring(0, 50)}..."`);
    try {
      const structured = queryStructuredMemory({
        agentName: this.name,
        task: query,
        limit,
      }).map((memory) => this.toStructuredExperience(memory));

      const results = await searchRAG(query, limit);
      const vectorResults = results.map(r => ({ text: r.text, score: r.score }));
      return [...structured, ...vectorResults].slice(0, limit);
    } catch (e) {
      logError(this.name, `Memória lekérdezés hiba: ${e}`);
      return [];
    }
  }

  /**
   * Save an experience to the cognitive memory
   */
  protected async saveToMemory(content: string, metadata: any = {}): Promise<void> {
    const memoryContent = `[${this.name}] ${content}`;
    const memoryId = metadata.id || `${this.name.toLowerCase()}_${Date.now()}`;
    
    logInfo(this.name, `Tapasztalat mentése a memóriába: ${memoryId}`);
    try {
      await addToIndex(memoryId, memoryContent);
    } catch (e) {
      logError(this.name, `Memória mentési hiba: ${e}`);
    }
  }
}

