      }

      // 3. Automated Outreach for critical opportunities
      const outreachResults = [];
      for (const opp of opportunities) {
        if (opp.potential_score >= 0.8) {
          logInfo(this.name, `🔥 High potential found! Triggering outreach for: ${opp.title}`);
