import { getPendingTransactions, updateTransaction } from '../data/bookkeeping_db.js';
// src/agents/MatchingAgent.ts
import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { BookkeepingTransaction, NavInvoiceData, MatchedResult, TransactionStatus, BankTransactionData } from '../types/bookkeeping.d.js';
import { logError, logWarn } from '../utils/logger.js';

export class MatchingAgent extends BaseAgent {
    name = "MatchingAgent";
    description = "Matches bank transactions with pending invoices.";
    role = "The Brain";
    capabilities = ["hybrid_matching"];

    findMatch(bankTxData: BankTransactionData, pendingInvoices: NavInvoiceData[]): MatchedResult | null {
        if (!bankTxData || !bankTxData.reference || typeof bankTxData.amount !== 'number') {
            logWarn("MatchingAgent", "Invalid bank transaction data for matching:", bankTxData);
            return null;
        }

        // Level 1: Hard Match (Reference Number)
        for (const inv of pendingInvoices) {
            if (bankTxData.reference.includes(String(inv.invoiceNumber))) {
                // Verify amount
                if (bankTxData.amount === inv.amount) {
                    return {
                        invoice: inv,
                        confidence: 100,
                        type: 'HARD_MATCH'
                    };
                }
            }
        }
        return null;
    }

    async executeTask(context: AgentContext): Promise<AgentResult> {
        try {
            const pendingInvoicesFromDB: BookkeepingTransaction[] = getPendingTransactions("NAV");
            const pendingInvoices: NavInvoiceData[] = pendingInvoicesFromDB
                .map(tx => tx.data as NavInvoiceData) // Assuming NAV transactions always have NavInvoiceData
                .filter(data => data.invoiceNumber && typeof data.amount === 'number'); // Basic validation

            const pendingBankTxs: BookkeepingTransaction[] = getPendingTransactions("BankAgent");

            for (const bankTx of pendingBankTxs) {
                if (!bankTx.data) {
                    logWarn("MatchingAgent", "Skipping bank transaction due to missing data:", bankTx.id);
                    updateTransaction(bankTx.id, { status: 'ERROR' as TransactionStatus });
                    continue;
                }
                const match = this.findMatch(bankTx.data as BankTransactionData, pendingInvoices);
                if (match) {
                    updateTransaction(bankTx.id, { status: 'COMPLETED' as TransactionStatus, matchedInvoice: match.invoice.invoiceNumber });
                } else {
                    updateTransaction(bankTx.id, { status: 'UNMATCHED' as TransactionStatus });
                }
            }

            return { success: true, message: "Matching process completed", data: null };
        } catch (error) {
            logError("MatchingAgent", "executeTask failed:", error);
            const errorMsg = error instanceof Error ? error.message : String(error);
            return { success: false, message: errorMsg, data: null };
        }
    }
}

import { IAgent, AgentResponse } from './types.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';
import fs from 'fs/promises';
import path from 'path';

/**
 * NavAgent
 * - Feladata: NAV Online Számla API lekérések és XML normalizálás
 * - Implementáció: helyi mintafájlokból normalizálás, NAV API placeholder
 */
export class NavAgent implements IAgent {
  name = 'NavAgent';
  role = 'NAV Online Számla integráció';
  description = 'Lekéri és normalizálja a NAV XML adatokat';
  capabilities = ['nav_fetch', 'xml_normalize'];

  private samplesDir() {
    return path.join(process.cwd(), 'conductor', 'tracks', 'konyveles_automatizalas', 'resources', 'samples');
  }

  private async listLocalNavSamples() {
    try {
      const dir = this.samplesDir();
      const files = await fs.readdir(dir);
      return files.filter((f) => f.endsWith('.xml')).map((f) => path.join(dir, f));
    } catch (e) {
      logError(this.name, `listLocalNavSamples failed: ${String(e)}`);
      return [] as string[];
    }
  }

  private xmlToJson(xml: string) {
    // Very small, brittle XML->JSON extraction for known invoice tags in samples
    const extract = (tag: string) => {
      const re = new RegExp(`<${tag}>([\s\S]*?)<\/${tag}>`, 'i');
      const m = xml.match(re);
      return m ? m[1].trim() : undefined;
    };

    return {
      invoice_number: extract('invoice_number'),
      net_amount: Number(extract('net_amount') || 0),
      vat_amount: Number(extract('vat_amount') || 0),
      gross_amount: Number(extract('gross_amount') || 0),
      issue_date: extract('issue_date'),
      partner_taxid: extract('partner_taxid'),
      payment_method: extract('payment_method')
    };
  }

  // Placeholder: NAV API fetch (delegated) if credentials exist
  private async fetchFromNavApi() {
    const apiKey = process.env.NAV_API_KEY;
    if (!apiKey) return null;
    logInfo(this.name, 'NAV API key detected - API client not implemented in this agent (placeholder)');
    return null;
  }

  async execute(task: string, _context?: Record<string, unknown>): Promise<AgentResponse> {
    setAgentStatus(this.name, 'working', task.slice(0, 50));
    try {
      logInfo(this.name, `execute: ${task}`);

      // If NAV_API_KEY exists, indicate delegated implementation
      if (process.env.NAV_API_KEY) {
        const apiResult = await this.fetchFromNavApi();
        return { status: 'delegated', message: 'NAV API client not implemented in-agent', metadata: { api: !!apiResult } };
      }

      // Else: parse local sample XML files
      const xmlFiles = await this.listLocalNavSamples();
      const parsed = [] as unknown[];
      for (const f of xmlFiles) {
        try {
          const txt = await fs.readFile(f, 'utf-8');
          parsed.push(this.xmlToJson(txt));
        } catch (e) {
          logError(this.name, `Failed to read/parse ${f}: ${String(e)}`);
        }
      }

      return { status: 'success', data: parsed, metadata: { files: xmlFiles.length } };
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError(this.name, `execute error: ${error}`);
      return { status: 'error', error };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }
}

