export class OrchestratorAgent implements IAgent {
  name = "Orchestrator";
  role = "Planner & Dispatcher";
  description =
    "The central intelligence that plans and delegates tasks to other agents.";
  capabilities = ["plan", "delegate", "analyze_intent"];

  private logger: Logger;
  private failedDuringSession: Set<string> = new Set();
  private currentMachine: AgentStateMachine<OrchestratorState> | null = null;

  getCurrentState(): OrchestratorState {
    return this.currentMachine?.getState() ?? 'IDLE';
  }

  constructor() {
    this.logger = new Logger("orchestrator.log");
    this.initPhoenixListeners();
  }

  /**
   * Phoenix Protocol: Listen for agent failures and log them
   * so future routing can avoid recently-failed agents.
   * Kiterjesztve: Automatikus javítási ciklus (Self-healing loop)
   */
  private initPhoenixListeners(): void {
    phoenixEventBus.subscribe('phoenix:agent_failed', async (evt) => {
      this.failedDuringSession.add(evt.agentName.toLowerCase());
      this.logger.info(
        `Phoenix: Agent '${evt.agentName}' failed. Orchestrator attempting self-healing...`,
      );

      // Ha nem a Developer Agent bukott el, kérjük meg a Developert, hogy javítsa ki
      if (evt.agentName.toLowerCase() !== 'developer') {
        const fixTask = `HIBA JAVÍTÁSA: A(z) ${evt.agentName} ügynök hibát jelzett: "${evt.error}". Elemezd a hiba okát és javítsd ki a kódot vagy konfigurációt.`;
        try {
          const id = await agentManager.queueTask(fixTask, 'developer', {
            originalError: evt.error,
            failedAgent: evt.agentName,
            autoFix: true
          });
          this.logger.info(`Self-healing: Fix task queued for Developer (ID: ${id})`);
        } catch (e) {
          this.logger.error(`Self-healing: Failed to queue fix task: ${e}`);
        }
      }
    });

    phoenixEventBus.subscribe('phoenix:failover_result', (evt) => {
      if (evt.success) {
        // Clear from failed set — agent was rescued by failover
        this.failedDuringSession.delete(evt.originalAgent.toLowerCase());
        this.logger.info(`Phoenix: Agent '${evt.originalAgent}' successfully recovered via failover.`);
      }
    });
  }

  // -------------------------------------------------------------------------
  // FAST PATH: keyword pre-routing without LLM
  // -------------------------------------------------------------------------
  private keywordRoute(task: string): { agent: string; hits: number } | null {
    const lower = task.toLowerCase();

    // 1. Explicit delegation: "Delegate X to AgentY"
    const delegateMatch =
      lower.match(/delegat\w*\s+.*?\bto\s+(\w+)/i) ??
      lower.match(/have\s+(\w+)\s+(?:agent\s+)?do/i);
    if (delegateMatch) {
      const targetName = delegateMatch[1];
      const agents = agentManager.listAgentDefinitions();
      const found = agents.find(
        (a) => a.name.toLowerCase() === targetName.toLowerCase(),
      );
      if (found) return { agent: found.name, hits: 99 };
    }

    // 2. Keyword table scan — pick route with most keyword hits
    let best: { agent: string; hits: number } | null = null;
    for (const route of KEYWORD_ROUTES) {
      const hits = route.keywords.filter((kw) => lower.includes(kw)).length;
      if (hits > 0 && (!best || hits > best.hits)) {
        best = { agent: route.agent, hits };
      }
    }
    return best;
  }

  /**
   * Szekvenciális chain pipeline: minden lépés outputja a következő lépés kontextusa.
   * Ha bármely lépés status: 'error' → a chain leáll, hibaüzenettel tér vissza.
   */
  async executeChain(
    steps: ChainStep[],
    metadata: Record<string, unknown> = {},
  ): Promise<AgentResponse> {
    this.logger.info(`[Chain] Indítás: ${steps.length} lépés`);
    const accumulated: AgentResponse[] = [];

    for (let i = 0; i < steps.length; i++) {
      const step = steps[i];

      const chainContext: ChainContext = {
        steps,
        currentStep: i,
        accumulated: [...accumulated], // snapshot — nem mutálható referencia
        metadata,
      };

      setAgentStatus(
        "OrchestratorAgent",
        "working",
        `Chain ${i + 1}/${steps.length}: ${step.agentName}`,
      );
      this.logger.info(
        `[Chain] Step ${i + 1}/${steps.length}: ${step.agentName} → "${step.task.slice(0, 60)}"`,
      );

      let result: unknown;
      try {
        result = await agentManager.delegate(step.agentName, step.task, {
          chainContext: chainContext as unknown as Record<string, unknown>,
          ...metadata,
        });
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        logError("OrchestratorAgent", `[Chain] Step ${i + 1} kivétel: ${msg}`);
        setAgentStatus("OrchestratorAgent", "idle");
        return {
          status: "error",
          error: `Chain leállt a(z) ${i + 1}. lépésnél (${step.agentName}): ${msg}`,
          data: { accumulated, failedStep: i },
        };
      }

      // AgentResponse-ként kezeljük az eredményt
      const response = (
        result && typeof result === "object" && "status" in result
          ? result
          : { status: "success", data: result }
      ) as AgentResponse;

      accumulated.push(response);

      if (response.status === "error") {
        this.logger.error(
          `[Chain] Step ${i + 1} hiba (${step.agentName}): ${response.error}`,
        );
        setAgentStatus("OrchestratorAgent", "idle");
        return {
          status: "error",
          error: `Chain leállt a(z) ${i + 1}. lépésnél (${step.agentName}): ${response.error}`,
          data: { accumulated, failedStep: i },
        };
      }

      this.logger.info(`[Chain] Step ${i + 1} kész ✓`);
    }

    setAgentStatus("OrchestratorAgent", "idle");
    this.logger.info(`[Chain] Kész: ${steps.length} lépés sikeresen végrehajtva`);

    return {
      status: "success",
      message: `Chain kész: ${steps.length} lépés sikeresen végrehajtva.`,
      data: {
        stepsCount: steps.length,
        results: accumulated,
        finalOutput: accumulated[accumulated.length - 1],
      },
    };
  }

  async execute(
    task: string,
    context?: Record<string, unknown>,
  ): Promise<unknown> {
    this.logger.info(`Orchestrating task: ${task}`);

    const taskId = `orch-${Date.now()}`;
    const machine = new AgentStateMachine<OrchestratorState>(
      ORCH_STATES,
      ORCH_TRANSITIONS,
      'IDLE',
      taskId,
    );
    this.currentMachine = machine;
    machine.updateContext({ task, retryCount: 0 });
    setAgentStatus('OrchestratorAgent', 'working', task.slice(0, 50));

    try {
      await machine.transition('taskReceived');  // IDLE → ANALYZING

      // === STUDIO MODE ===
      if (context?.studioMode && context?.rootDir) {
        this.logger.info(`Studio mode detected — routing to developer agent (rootDir: ${context.rootDir})`);
        machine.updateContext({ agentName: 'developer' });
        await machine.transition('analysisComplete'); // ANALYZING → ROUTING
        await machine.transition('agentSelected');    // ROUTING → EXECUTING
        const studioTaskId = await agentManager.queueTask(task, 'developer', context);
        await machine.transition('executionComplete'); // EXECUTING → DONE
        return { status: 'success', message: 'Studio feladat kiosztva a Fejlesztő ügynöknek.', taskId: studioTaskId };
      }

      // === FAST PATH: keyword pre-routing (no LLM needed) ===
      const kwMatch = this.keywordRoute(task);
      const isCompound =
        /\b(?:and|then|after that|also|plus|meg |aztán|majd|valamint|utána)\b/i.test(task);

      await machine.transition('analysisComplete'); // ANALYZING → ROUTING

      if (kwMatch && (kwMatch.hits >= 99 || !isCompound)) {
        this.logger.info(`Keyword pre-route → ${kwMatch.agent} (hits: ${kwMatch.hits})`);
        machine.updateContext({ agentName: kwMatch.agent });
        await machine.transition('agentSelected');   // ROUTING → EXECUTING
        const id = await agentManager.queueTask(task, kwMatch.agent, context ?? undefined);
        const quickReply = QUICK_REPLIES[kwMatch.agent] || `Delegálom a feladatot a(z) ${kwMatch.agent} ügynöknek.`;
        socketService.broadcastChatter('Brunella', quickReply, 'user');
        await machine.transition('executionComplete'); // EXECUTING → DONE
        return {
          success: true,
          status: 'success',
          message: quickReply,
          taskIds: [id],
          routing: 'keyword',
        };
      }

      // === REACT PATH: LLM-based Tool Calling Loop ===
      this.logger.info('Starting ReAct Execution Loop');
      machine.updateContext({ agentName: 'llm-react' });
      await machine.transition('agentSelected');   // ROUTING → EXECUTING

      const agents = agentManager
        .listAgentDefinitions()
        .filter((a) => a.name !== 'Orchestrator')
        .map((a) => `- ${a.name}: ${a.description} (Role: ${a.role})`)
        .join('\n');

      const systemPrompt = `
Te vagy Brunella, a Brunella Agent System (BAS) intelligens, proaktív központi "agya" és Orchestrator ügynöke. Te vagy a rendszer elsődleges kapcsolattartója a Mesterrel (a felhasználóval).

A feladatod kettős:
1. **Intelligens Társalgópartner:** Bármiről cseveghetsz a felhasználóval (időjárás, tech hírek, filozófia, stb.) teljesen természetes, emberi módon. Te egy okos, segítőkész és barátságos entitás vagy.
2. **Központi Diszpécser:** Ha a felhasználó egy technikai vagy végrehajtandó feladatot kér (pl. "keress rá erre a neten", "írj egy kódot", "nyisd meg a böngészőt"), a feladatod, hogy a megfelelő ügynökök mozgósításával ELVÉGEZD a feladatot a rendelkezésedre álló eszközök (tools) segítségével.

**Személyiség és Stílus:**
- Professzionális, udvarias, de határozott mérnöki vezető (Senior Systems Architect / Dispatcher).
- Csevegés esetén légy közvetlen és érdeklődő.
- Nem csak "tervezel", hanem azonnal **cselekedsz** is az eszközök meghívásával.
- Ha egy feladatot háttérbe küldesz, azonnal tájékoztasd a felhasználót a 'send_message_to_user' eszközzel, vagy a végső válaszodban (pl. "Értettem. Elindítottam a RobotkezV2-t a háttérben. Szólok, ha végzett.").
- **SOHA** ne adj vissza nyers JSON feladatlistát vagy markdown formázott JSON-t válaszként. Csak természetes nyelven kommunikálj!
- **SOHA** ne generálj Markdown execution planeket (pl. 'design', 'implementation', 'test' fázisokkal), ha a felhasználó egy azonnali, futtatható parancsot kér (pl. 'Nyisd meg a böngészőt').
- **Azonnali Cselekvés:** Ha a kérés egyértelmű (pl. "Nyisd meg a böngészőt"), AZONNAL hívd meg a 'delegate_task' eszközt a 'robotkezv2' ügynökkel, 'start_browser' vagy 'navigate' instrukcióval, felesleges feladatbontás nélkül.

**Elérhető Ügynökök (akiknek delegálhatsz a 'delegate_task' eszközzel ha kell):**
${agents}

**Specifikus Tudásbázis:**
- **Böngészés / Web Interakciók:** Ha a felhasználó böngészni akar vagy információt letölteni, mindig a 'robotkezv2' ügynöknek delegálj.
- **n8n / Langflow:** Canvas-alapú UI rendszerek. Az összetett feladatokat a 'robotkezv2' ügynöknek kell kiadnod. Bontsd le a kérést kis lépésekre a 'delegate_task' használatakor.

**ReAct Működés (Hogyan használd az eszközeidet):**
1. Kapod a kérést. Döntsd el, hogy ez egy egyszerű kérdés/csevegés, vagy egy feladat, amit delegálni kell.
2. Ha feladatot kell kiosztani, használd a 'delegate_task' eszközt. Ezt többször is megteheted különböző ügynökök felé.
3. Ha állapotra van szükséged a rendszerben futó ügynökökről, használd a 'get_agent_status' eszközt.
4. Ha üzenetet akarsz küldeni a Dashboardra folyamat közben, használd a 'send_message_to_user'-t.
5. Ha minden szükséges eszközt meghívtál, vagy ha a feladat csak egy kérdés volt, adj egy végső, emberi választ.
`;

      const messages: unknown[] = [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: task }
      ];

      const gateway = getBifrostGateway();
      const MAX_ITERATIONS = 5;
      let finalMessage = 'A feladatot feldolgoztam.';
      const taskIds: number[] = [];

      for (let i = 0; i < MAX_ITERATIONS; i++) {
        this.logger.info(`ReAct iteráció ${i + 1}/${MAX_ITERATIONS}`);

        const response = await gateway.generate({
          prompt: task,
          taskType: 'general',
          model: 'gpt-4.1',
          tools: ORCHESTRATOR_TOOLS,
          messages: messages as any,
          userId: context?.userId as string | undefined,
        });

        if (!response.success) {
          this.logger.error(`LLM Gateway hiba: ${response.error}`);
          try {
            await machine.transition('errorOccurred');
          } catch {
            // ignore if transition not valid from current state
          }
          return { status: 'error', error: 'Hiba az LLM kommunikációban.' };
        }

        const replyContent = response.content || '';
        const toolCalls = response.toolCalls;

        const assistantMessage: any = { role: 'assistant', content: replyContent };
        if (toolCalls && toolCalls.length > 0) {
          assistantMessage.tool_calls = toolCalls;
        }
        messages.push(assistantMessage);

        if (replyContent && !toolCalls) {
          finalMessage = replyContent;
          socketService.broadcastChatter('Brunella', finalMessage, 'user');
          break;
        }

        if (toolCalls && toolCalls.length > 0) {
          for (const toolCall of toolCalls) {
            const name = toolCall.function.name;
            const args = JSON.parse(toolCall.function.arguments);
            let toolResult = '';

            this.logger.info(`Tool meghívva: ${name} paraméterekkel: ${JSON.stringify(args)}`);

            try {
              if (name === 'delegate_task') {
                const id = await agentManager.queueTask(args.instruction, args.agent_name, context ?? undefined);
                taskIds.push(id);
                toolResult = `Feladat sikeresen delegálva. Task ID: ${id}`;
              } else if (name === 'get_agent_status') {
                const statuses = agentManager.listAgentStatuses();
                const status = statuses.find(s => s.name.toLowerCase() === args.agent_name.toLowerCase());
                toolResult = status ? JSON.stringify(status) : `Ügynök nem található: ${args.agent_name}`;
              } else if (name === 'send_message_to_user') {
                socketService.broadcastChatter('Brunella', args.message, 'user');
                toolResult = 'Üzenet sikeresen elküldve.';
              } else {
                toolResult = `Ismeretlen eszköz: ${name}`;
              }
            } catch (toolErr: unknown) {
              const errMsg = toolErr instanceof Error ? toolErr.message : String(toolErr);
              this.logger.error(`Tool error (${name}): ${errMsg}`);
              toolResult = `Hiba az eszköz futtatása közben: ${errMsg}`;
            }

            messages.push({
              role: 'tool',
              tool_call_id: toolCall.id,
              name: name,
              content: toolResult
            });
          }
        } else {
          break;
        }
      }

      await machine.transition('executionComplete'); // EXECUTING → DONE
      return {
        success: true,
        status: 'success',
        message: finalMessage,
        taskIds,
        steps: taskIds,
      };

    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      logError('OrchestratorAgent', `State machine error: ${msg}`);
      // Attempt to move machine to ERROR state for observability
      try {
        await machine.transition('errorOccurred');
      } catch {
        // ignore — machine might already be in an invalid state
      }
      return { status: 'error', error: msg };
    } finally {
      setAgentStatus('OrchestratorAgent', 'idle');
      this.currentMachine = null;
      clearCheckpoints(taskId).catch(() => {/* ignore cleanup errors */});
    }
  }
}

export default OrchestratorAgent;

import { IAgent, AgentResponse } from './types.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';

/**
 * Price Intelligence Data Point
 */
interface PriceDataPoint {
  productId: string;
  productName: string;
  source: 'auction' | 'competitor' | 'market_avg' | 'historical';
  price: number;
  currency: string;
  date: Date;
  confidence: number; // 0-100 percentage
  marketTrendDirection: 'up' | 'down' | 'stable';
  historicalComparison: { percentChange: number; timeFrame: string };
}

/**
 * Pricing Recommendation
 */
interface PricingRecommendation {
  productId: string;
  currentPrice: number;
  recommendedPrice: number;
  priceAdjustmentPercent: number;
  reasoning: string;
  marketContext: {
    averageMarketPrice: number;
    competitorRange: { min: number; max: number };
    trendDirection: 'up' | 'down' | 'stable';
  };
  confidence: number; // 0-100
  suggestedAction: 'increase' | 'decrease' | 'maintain';
}

/**
 * Market Intelligence Report
 */
interface MarketIntelligenceReport {
  reportDate: Date;
  marketTrends: Array<{
    category: string;
    trend: string;
    trendDirection: 'up' | 'down' | 'stable';
    impactLevel: 'high' | 'medium' | 'low';
  }>;
  competitorAnalysis: Array<{
    competitorName: string;
    productsTracked: number;
    averagePricePoint: number;
    priceStrategy: 'premium' | 'competitive' | 'discount';
  }>;
  opportunities: string[];
  threats: string[];
  recommendations: PricingRecommendation[];
}

/**
 * PricingAgent - Dinamikus Árazó & Piaci Hírszerző
 * Responsibility: Market price tracking, competitive analysis, pricing recommendations
 * 
 * Features:
 * - Real-time auction price monitoring
 * - Competitor price tracking
 * - Historical trend analysis
 * - Dynamic pricing recommendations
 * - Market sentiment analysis
 */
export class PricingAgent implements IAgent {
  name = 'PricingAgent';
  role = 'Market Intelligence & Dynamic Pricing';
  description = 'Dinamikus Árazó & Piaci Hírszerző - Analyzes market trends, competitor pricing, generates recommendations';
  capabilities = ['market_analysis', 'competitor_tracking', 'price_optimization', 'trend_forecasting', 'sentiment_analysis'];
  
  private priceHistory: Map<string, PriceDataPoint[]> = new Map();
  private competitorData: Map<string, { name: string; prices: number[] }> = new Map();
  private marketTrends: Array<{ category: string; direction: 'up' | 'down' | 'stable' }> = [];

  /**
   * Execute market intelligence workflow
   */
  async execute(task: string, _context?: unknown): Promise<AgentResponse> {
    setAgentStatus(this.name, 'working', task.slice(0, 50));
    const startTime = Date.now();

    try {
      logInfo(this.name, `Starting market intelligence analysis: ${task.slice(0, 40)}`);

      // Step 1: Gather market data from multiple sources
      const marketData = await this.gatherMarketData();
      logInfo(this.name, `Gathered market data from ${marketData.sources.length} sources`);

      // Step 2: Analyze competitor pricing
      const competitorAnalysis = this.analyzeCompetitorPricing();
      logInfo(this.name, `Analyzed ${competitorAnalysis.length} competitors`);

      // Step 3: Detect market trends
      const trends = this.detectMarketTrends();
      logInfo(this.name, `Detected ${trends.length} market trends`);

      // Step 4: Generate pricing recommendations
      const recommendations = this.generatePricingRecommendations(marketData.pricePoints);
      logInfo(this.name, `Generated ${recommendations.length} pricing recommendations`);

      // Step 5: Compile intelligence report
      const report: MarketIntelligenceReport = {
        reportDate: new Date(),
        marketTrends: trends,
        competitorAnalysis: competitorAnalysis,
        opportunities: this.identifyOpportunities(trends),
        threats: this.identifyThreats(trends),
        recommendations: recommendations
      };

      logInfo(this.name, `Market intelligence report generated successfully`);

      return {
        status: 'success',
        data: report,
        metadata: {
          dataPointsAnalyzed: marketData.pricePoints.length,
          competitorsTracked: competitorAnalysis.length,
          trendsDetected: trends.length,
          recommendationsGenerated: recommendations.length,
          processingTimeMs: Date.now() - startTime
        }
      };
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError(this.name, `Market intelligence analysis failed: ${error}`);
      return {
        status: 'error',
        error: error,
        metadata: { dataPointsAnalyzed: this.priceHistory.size }
      };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  /**
   * Gather market data from multiple sources (mock)
   */
  private async gatherMarketData(): Promise<{
    sources: string[];
    pricePoints: PriceDataPoint[];
  }> {
    // Mock sources: auction sites, competitor websites, market databases
    const sources = ['eBay', 'Amazon', 'Competitor A', 'Competitor B', 'Market Aggregator'];
    
    // Mock price data points
    const pricePoints: PriceDataPoint[] = [
      {
        productId: 'PROD-001',
        productName: 'Premium Widget',
        source: 'auction',
        price: 4500,
        currency: 'HUF',
        date: new Date(),
        confidence: 95,
        marketTrendDirection: 'up',
        historicalComparison: { percentChange: 12, timeFrame: '30 days' }
      },
      {
        productId: 'PROD-001',
        productName: 'Premium Widget',
        source: 'competitor',
        price: 4200,
        currency: 'HUF',
        date: new Date(),
        confidence: 90,
        marketTrendDirection: 'up',
        historicalComparison: { percentChange: 8, timeFrame: '30 days' }
      },
      {
        productId: 'PROD-002',
        productName: 'Standard Widget',
        source: 'market_avg',
        price: 2800,
        currency: 'HUF',
        date: new Date(),
        confidence: 85,
        marketTrendDirection: 'stable',
        historicalComparison: { percentChange: 0, timeFrame: '30 days' }
      }
    ];

    // Store for future analysis
    pricePoints.forEach(point => {
      const existing = this.priceHistory.get(point.productId) || [];
      this.priceHistory.set(point.productId, [...existing, point]);
    });

    return { sources, pricePoints };
  }

  /**
   * Analyze competitor pricing
   */
  private analyzeCompetitorPricing(): Array<{
    competitorName: string;
    productsTracked: number;
    averagePricePoint: number;
    priceStrategy: 'premium' | 'competitive' | 'discount';
  }> {
    // Mock competitor data
    const competitors = [
      { competitorName: 'Competitor A', productsTracked: 45, averagePricePoint: 4100, priceStrategy: 'competitive' as const },
      { competitorName: 'Competitor B', productsTracked: 38, averagePricePoint: 3800, priceStrategy: 'discount' as const },
      { competitorName: 'Competitor C', productsTracked: 52, averagePricePoint: 4800, priceStrategy: 'premium' as const }
    ];

    competitors.forEach(comp => {
      this.competitorData.set(comp.competitorName, {
        name: comp.competitorName,
        prices: [comp.averagePricePoint]
      });
    });

    return competitors;
  }

  /**
   * Detect market trends
   */
  private detectMarketTrends(): Array<{
    category: string;
    trend: string;
    trendDirection: 'up' | 'down' | 'stable';
    impactLevel: 'high' | 'medium' | 'low';
  }> {
    return [
      {
        category: 'Digital Transformation',
        trend: 'Cloud-based solutions gaining market share',
        trendDirection: 'up',
        impactLevel: 'high'
      },
      {
        category: 'Supply Chain',
        trend: 'Shortage of semiconductors affecting availability',
        trendDirection: 'up',
        impactLevel: 'high'
      },
      {
        category: 'Consumer Behavior',
        trend: 'E-commerce adoption stabilizing',
        trendDirection: 'stable',
        impactLevel: 'medium'
      },
      {
        category: 'Labor Market',
        trend: 'Wage inflation continuing in tech sector',
        trendDirection: 'up',
        impactLevel: 'medium'
      }
    ];
  }

  /**
   * Generate pricing recommendations
   */
  private generatePricingRecommendations(pricePoints: PriceDataPoint[]): PricingRecommendation[] {
    return pricePoints
      .filter((p, i, arr) => arr.findIndex(x => x.productId === p.productId) === i) // Unique products
      .map(point => {
        const avgMarketPrice = this.calculateAveragePrice(point.productId);
        const competitorRange = this.getCompetitorRange(point.productId);
        const trend = point.marketTrendDirection;

        // Calculate recommended price
        let recommendedPrice = avgMarketPrice;
        if (trend === 'up') {
          recommendedPrice = avgMarketPrice * 1.05; // Increase 5% in upward trend
        } else if (trend === 'down') {
          recommendedPrice = avgMarketPrice * 0.98; // Decrease 2% in downward trend
        }

        return {
          productId: point.productId,
          currentPrice: point.price,
          recommendedPrice: Math.round(recommendedPrice),
          priceAdjustmentPercent: Math.round(((recommendedPrice - point.price) / point.price) * 100),
          reasoning: `Market average is ${avgMarketPrice} HUF. Current trend is ${trend}. Competitors priced between ${competitorRange.min}-${competitorRange.max} HUF.`,
          marketContext: {
            averageMarketPrice: avgMarketPrice,
            competitorRange: competitorRange,
            trendDirection: trend
          },
          confidence: 85,
          suggestedAction: recommendedPrice > point.price ? 'increase' : (recommendedPrice < point.price ? 'decrease' : 'maintain')
        };
      });
  }

  /**
   * Calculate average price for a product
   */
  private calculateAveragePrice(productId: string): number {
    const history = this.priceHistory.get(productId) || [];
    if (history.length === 0) return 0;
    const sum = history.reduce((acc, p) => acc + p.price, 0);
    return Math.round(sum / history.length);
  }

  /**
   * Get competitor price range for a product
   */
  private getCompetitorRange(productId: string): { min: number; max: number } {
    // Mock implementation
    return { min: 3500, max: 5000 };
  }

  /**
   * Identify business opportunities from trends
   */
  private identifyOpportunities(trends: Array<{ category: string; trend: string; trendDirection: string }>): string[] {
    const upwardTrends = trends
      .filter(t => t.trendDirection === 'up')
      .map(t => `Leverage ${t.category} trend: ${t.trend}`);

    return [
      ...upwardTrends,
      'Expand into emerging markets showing growth',
      'Invest in automation to reduce operational costs'
    ];
  }

  /**
   * Identify market threats
   */
  private identifyThreats(trends: Array<{ category: string; trend: string; trendDirection: string }>): string[] {
    const downwardTrends = trends
      .filter(t => t.trendDirection === 'down')
      .map(t => `Monitor ${t.category} decline: ${t.trend}`);

    return [
      ...downwardTrends,
      'Increasing competitive pressure from low-cost alternatives',
      'Regulatory changes affecting market accessibility'
    ];
  }
}

/**
 * Export for registry
 */
export const createPricingAgent = (): PricingAgent => new PricingAgent();

export default PricingAgent;

import { IAgent, AgentResponse } from './types.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';

/**
 * Insurance Claim
 */
interface InsuranceClaim {
  claimId: string;
  policyNumber: string;
  claimType: 'property' | 'health' | 'auto' | 'liability' | 'loss';
  claimDate: Date;
  submitDate: Date;
  status: 'open' | 'under_review' | 'approved' | 'rejected' | 'paid' | 'pending_documents';
  amount: number;
  description: string;
  documents: Array<{ documentId: string; type: string; uploadDate: Date }>;
  assignedAdjuster?: string;
  lastUpdate: Date;
  riskAssessment: number; // 0-100, higher = more risky
}

/**
 * Risk Factor
 */
interface RiskFactor {
  factorId: string;
  factorType: string; // 'location', 'history', 'frequency', 'severity'
  description: string;
  riskLevel: 'low' | 'medium' | 'high' | 'critical';
  score: number; // 0-100
  metadata: Record<string, unknown>;
}

/**
 * Proactive Intervention
 */
interface ProactiveIntervention {
  interventionId: string;
  claimId: string;
  type: 'prevention' | 'early_settlement' | 'fraud_check' | 'document_request';
  description: string;
  probability: number; // 0-100
  recommendedAction: string;
  estimatedOutcome: 'positive' | 'negative' | 'neutral';
  timestamp: Date;
  priority: 'low' | 'medium' | 'high' | 'critical';
}

/**
 * ProactiveClaimsAgent - Proaktív Biztosítási Ügyek Kezelő
 * Manages insurance claims, risk assessment, fraud detection, and proactive interventions
 */
export class ProactiveClaimsAgent implements IAgent {
  name = 'ProactiveClaimsAgent';
  role = 'Insurance & Risk Management';
  description = 'Proaktív Biztosítási Ügyek Kezelő - Biztosítási ügyek, kockázatfelmérés, csalások felderítése';
  capabilities = [
    'claims_processing',
    'risk_assessment',
    'fraud_detection',
    'document_analysis',
    'proactive_intervention',
    'settlement_recommendations',
    'compliance_check'
  ];

  private claimsDatabase: Map<string, InsuranceClaim> = new Map();
  private riskFactors: Map<string, RiskFactor> = new Map();
  private interventions: ProactiveIntervention[] = [];

  /**
   * Execute agent task
   */
  async execute(task: string, context?: unknown): Promise<AgentResponse> {
    setAgentStatus(this.name, 'working', task.slice(0, 50));
    try {
      logInfo(this.name, `Feladat indítása: ${task.slice(0, 40)}...`);

      if (task.toLowerCase().includes('claim') || task.toLowerCase().includes('ügy')) {
        return await this.processClaims(task, context);
      }

      if (task.toLowerCase().includes('risk') || task.toLowerCase().includes('kockázat')) {
        return await this.assessRisks(task, context);
      }

      if (task.toLowerCase().includes('fraud') || task.toLowerCase().includes('csalás')) {
        return await this.detectFraud(task, context);
      }

      if (task.toLowerCase().includes('proactive') || task.toLowerCase().includes('preaktív')) {
        return await this.identifyInterventions(task, context);
      }

      // Default: process claims
      return await this.processClaims(task, context);
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError(this.name, error);
      return { status: 'error', error };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

