// PropertyAnalystAgent
// ─────────────────────────────────────────────────────────────────────────────

export class PropertyAnalystAgent extends BaseAgent {
  name = "PropertyAnalyst";
  description =
    "Ingatlan dokumentumokat (PDF/JPG/PNG) elemez Gemini Vision OCR-rel. Kinyeri a HRSZ-t, alapterületet, közműveket, és alapértékelést végez.";
  role = "Ingatlan Elemző";
  capabilities = ["property_ocr", "document_ingestion", "property_valuation", "hrsz_extraction"];

  private _analyzed: PropertyAsset[] = [];

  get analyzedAssets(): PropertyAsset[] { return this._analyzed; }

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = (context.task ?? "").toLowerCase();

    // ── Dokumentum elemzés ───────────────────────────────────────────────────
    if (task.includes("elemezd") || task.includes("analyze") || context.file_path) {
      const filePath = (context.file_path as string) ?? this._extractFilePath(context.task ?? "");
      if (!filePath) {
        return {
          success: false,
          message: "Hiányzó fájl elérési út. Adj meg 'file_path'-t a context-ben, vagy írd a feladatba: 'elemezd: <fájl>'.",
        };
      }

      const mock = (context.mock as boolean) ?? task.includes("mock");
      logInfo(this.name, `Dokumentum elemzés: ${filePath} (mock=${mock})`);

      let visionResp: VisionResponse;
      try {
        visionResp = await callVisionWorker(filePath, mock);
      } catch (e: unknown) {
        const err = e instanceof Error ? e.message : String(e);
        logError(this.name, `vision_worker hiba: ${err}`);
        return { success: false, message: `OCR worker hiba: ${err}` };
      }

      if (!visionResp.success || !visionResp.asset) {
        return { success: false, message: visionResp.error ?? "Vision worker ismeretlen hiba" };
      }

      const asset = visionResp.asset;
      this._analyzed.push(asset);
      const valuation = estimateValue(asset);
      const actionItems = buildActionItems(asset, valuation);
      const city = asset.address?.city || "–";

      const result: PropertyAnalysisResult = {
        asset,
        valuation,
        action_items: actionItems,
        market_summary:
          `${city}-i ${asset.property_type} ingatlan. ` +
          `Kért ár: ${valuation.asking_price_eur?.toLocaleString("hu-HU") ?? "–"} EUR, ` +
          `becsült érték: ${valuation.estimated_value_eur?.toLocaleString("hu-HU") ?? "–"} EUR. ` +
          `Ajánlás: ${valuation.recommendation}.`,
        generated_at: new Date().toISOString(),
      };

      return {
        success: true,
        message: `✅ Elemzés kész: ${asset.hrsz || asset.source_file} | ${valuation.recommendation} | ${valuation.estimated_value_eur?.toLocaleString("hu-HU")} EUR`,
        data: result,
        metadata: { hrsz: asset.hrsz, confidence: asset.confidence },
      };
    }

    // ── Értékelés (utolsó analysált asset) ──────────────────────────────────
    if (task.includes("értékeld") || task.includes("valuate") || task.includes("cma")) {
      if (this._analyzed.length === 0) {
        return { success: false, message: "Nincs elemzett ingatlan. Először hívd 'elemezd: <fájl>'." };
      }
      const asset = this._analyzed[this._analyzed.length - 1];
      const mock = (context.mock as boolean) ?? task.includes("mock");

      logInfo(this.name, `CMA piacelemzés indítása: ${asset.address?.city}, ${asset.area_sqm} m²`);

      try {
        const cmaReport = await callCMAWorker(
          asset.address?.city || asset.address?.formatted || "Budapest",
          asset.property_type || "apartment",
          asset.area_sqm || 0,
          mock
        );

        return {
          success: true,
          message: `📊 CMA Piacelemzés kész: ${cmaReport.estimate.value_eur.toLocaleString("hu-HU")} EUR | Score: ${cmaReport.investment_score}/10\n${cmaReport.recommendation}`,
          data: cmaReport,
        };
      } catch (e: unknown) {
        const err = e instanceof Error ? e.message : String(e);
        logError(this.name, `CMA hiba: ${err}. Visszalépés alapértékelésre.`);
        const valuation = estimateValue(asset);
        return {
          success: true,
          message: `📊 Alapértékelés (CMA hiba): ${valuation.recommendation} | ${valuation.estimated_value_eur?.toLocaleString("hu-HU")} EUR`,
          data: valuation,
        };
      }
    }

    // ── Összegzés ─────────────────────────────────────────────────────────────
    if (task.includes("összegzés") || task.includes("list") || task.includes("summary")) {
      const results: PropertyAnalysisResult[] = this._analyzed.map((asset) => ({
        asset,
        valuation: estimateValue(asset),
        generated_at: new Date().toISOString(),
      }));
      return {
        success: true,
        message: `📋 ${results.length} ingatlan elemzése elérhető.`,
        data: results,
      };
    }

    return {
      success: false,
      message: `Ismeretlen feladat: "${context.task}". Próbáld: "elemezd: fájl.pdf", "értékeld", "összegzés".`,
    };
  }

  private _extractFilePath(task: string): string {
    const m = task.match(/elemezd[:\s]+(.+)$/i) ?? task.match(/analyze[:\s]+(.+)$/i);
    return m ? m[1].trim() : "";
  }
}

export default PropertyAnalystAgent;

import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError, setAgentStatus } from '../utils/logger.js';
import { generateResponse } from '../core/llm_client.js';
import { updateBusinessJobStatus, saveBusinessLead } from '../utils/db.js';
import { socketService } from '../server/SocketService.js';
import { agentManager } from './AgentManager.js';
import { v4 as uuidv4 } from 'uuid';

export class PropertyVisionaryAgent extends BaseAgent {
  name = 'PropertyVisionary';
  role = 'Real Estate Strategy & Buyer Discovery';
  description = 'Ingatlan és iparterület vevővadász: potenciális vevők felkutatása, stratégiaalkotás és megkeresés vezénylése';
  capabilities = [
    'buyer_discovery',
    'real_estate_valuation',
    'outreach_strategy',
    'investment_analysis'
  ];

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = context.task || '';
    const jobId = (context as any).jobId;
    const propertyInfo = (context as any).propertyInfo || task;

    if (jobId) {
        await updateBusinessJobStatus(jobId, 'running');
        socketService.emit('business_job:updated', { jobId, status: 'running' });
    }

    setAgentStatus(this.name, 'working', `Vevővadászat: ${propertyInfo.slice(0, 40)}...`);

    try {
      logInfo(this.name, `Ingatlan elemzés és vevőkutatás indítása: ${propertyInfo}`);

      // 1. Mélyelemzés és Vevőprofil Generálása
      const profilePrompt = `
        Te egy elit ingatlanbefektetési tanácsadó vagy. 
        Adott egy projekt leírása: "${propertyInfo}".
        
        Készíts egy minden részletre kiterjedő ideális vevőprofilt. 
        Térj ki:
        - Befektetői típus (pl. Family Office, Institutional, HNWI)
        - Földrajzi fókusz (pl. DACH régió, belföldi tőke)
        - Motiváció (pl. ESG megfelelés, yield-vadászat, lifestyle asset)
        
        Válaszolj JSON-ben: { 
            "buyerProfile": "...", 
            "targetSectors": ["...", "..."],
            "usp": ["...", "..."],
            "riskProfile": "low/medium/high"
        }
      `;
      const profileRes = await generateResponse(profilePrompt, 'gemini', 'gemini-2.0-flash');
      const profileJson = JSON.parse(profileRes.match(/\{[\s\S]*\}/)![0]);

      // 2. Intelligens Vevőfelkutatás (Researcher + Robotkez)
      logInfo(this.name, "Beruházási trendek és tőkeerős célpontok keresése...");
      const searchInstruction = `
        Keress konkrét befektetési alapokat, ingatlanfejlesztőket vagy vagyonkezelőket, 
        akik a következő területeken aktívak: ${profileJson.targetSectors.join(', ')}.
        Kiemelten keresd a magyarországi és közép-európai piacot ismerő szereplőket.
        Adj vissza egy JSON listát: [ { "companyName": "...", "reason": "...", "contactRole": "...", "linkedinHint": "..." } ]
      `;
      const searchResponse = await agentManager.delegate('researcher', searchInstruction) as any;
      
      let potentialBuyers = [];
      if (searchResponse && searchResponse.success) {
          const content = searchResponse.message || "";
          const jsonMatch = content.match(/\[[\s\S]*\]/);
          if (jsonMatch) potentialBuyers = JSON.parse(jsonMatch[0]);
      }

      if (potentialBuyers.length === 0) {
          // Ha a keresés nem hoz eredményt, generáljunk szektor-specifikus mintákat
          potentialBuyers = profileJson.targetSectors.map((sector: string) => ({
              companyName: `${sector} Investment Group`,
              reason: `Aktív ${profileJson.riskProfile} kockázati profilú projektekben.`,
              contactRole: "Befektetési Igazgató",
              linkedinHint: "Search for Expansion Manager"
          }));
      }

      // 3. Megkeresési Stratégia (Innovation Bridge stílusú transzferrel)
      logInfo(this.name, "Személyre szabott értékesítési stratégia alkotása...");
      const finalLeads = [];
      for (const buyer of potentialBuyers.slice(0, 5)) {
          const strategyPrompt = `
            Készíts egy "Visszautasíthatatlan Ajánlat" (Irresistible Offer) stratégiát a(z) ${buyer.companyName} részére.
            Projekt: ${propertyInfo}
            Fő előnyök (USP): ${profileJson.usp.join(', ')}
            
            Válaszolj JSON-ben: { 
                "openingLine": "Azonnal figyelemfelkeltő nyitómondat magyarul",
                "valueProposition": "A konkrét üzleti érték leírása",
                "outreachChannel": "LinkedIn / Email / Telefon"
            }
          `;
          const strategyRes = await generateResponse(strategyPrompt, 'gemini', 'gemini-2.0-flash');
          const strategyJson = JSON.parse(strategyRes.match(/\{[\s\S]*\}/)![0]);
          
          finalLeads.push({
              ...buyer,
              ...strategyJson,
              status: 'ready_to_contact'
          });
      }

      const finalResult = {
          propertyDescription: propertyInfo,
          analysis: profileJson,
          leads: finalLeads
      };

      // 4. Mentés a Pipeline-ba (egyéni leadek)
      if (jobId) {
          logInfo(this.name, `Populating pipeline with ${finalLeads.length} leads for job ${jobId}`);
          for (const lead of finalLeads) {
              await saveBusinessLead({
                  id: uuidv4(),
                  job_id: jobId,
                  company_name: lead.companyName,
                  contact_person: lead.contactRole,
                  metadata: JSON.stringify(lead)
              });
          }
      }

      // 5. Mentés és lezárás (összesített riport)
      if (jobId) {
          await updateBusinessJobStatus(jobId, 'completed', JSON.stringify(finalResult));
          socketService.emit('business_job:updated', { jobId, status: 'completed' });
      }

      return {
        success: true,
        message: `Sikeresen azonosítottam ${finalLeads.length} potenciális vevőjelöltet és kidolgoztam a stratégiát.`,
        data: finalResult
      };

    } catch (error: any) {
      logError(this.name, `Property Visionary hiba: ${error.message}`);
      if (jobId) {
          await updateBusinessJobStatus(jobId, 'failed', JSON.stringify({ error: error.message }));
          socketService.emit('business_job:updated', { jobId, status: 'failed' });
      }
      return { success: false, message: error.message };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }
}

