import { BaseAgent, AgentContext, AgentResult } from "./BaseAgent.js";
import { AgentHandoff, ISwarmContext } from "./types.js";
import { logInfo, logError } from "../utils/logger.js";

interface RAGResult {
  text: string;
  source: string;
  page_num: number;
  score: number;
}

export class ResearcherAgent extends BaseAgent {
  name = "Researcher";
  description =
    "Webes keresésre és információgyűjtésre specializálódott ügynök. Képes a belső tudásbázis (RAG) és a világháló keresésére.";
  role = "researcher";
  capabilities = ["web_search", "rag_search", "information_gathering"];

  private async queryRAG(query: string): Promise<RAGResult[]> {
    try {
      logInfo("ResearcherAgent", `Querying RAG Knowledge Base: ${query}`);
      const response = await fetch("http://127.0.0.1:8000/rag/query", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ query: query, limit: 5 }),
      });

      if (!response.ok) {
        throw new Error(`RAG API error: ${response.statusText}`);
      }

      const data = await response.json();
      return data.results || [];
    } catch (error) {
      logError("ResearcherAgent", `RAG query failed: ${error}`);
      return [];
    }
  }

  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = context.task || "";
    const taskLower = task.toLowerCase();
    const swarmContext = context.swarm;

    // 1. RAG Search (Priority if explicitly requested or context implies internal knowledge)
    if (
      taskLower.includes("tudásbázis") ||
      taskLower.includes("rag") ||
      taskLower.includes("belső") ||
      taskLower.includes("internal")
    ) {
      logInfo("ResearcherAgent", `RAG Search activated for: ${task}`);
      const ragResults = await this.queryRAG(task);

      if (ragResults.length > 0) {
        const formattedResults = ragResults
          .map(
            (r) =>
              `- **${r.source}** (Page ${r.page_num}): "${r.text.substring(0, 150)}..."`,
          )
          .join("\n");

        if (swarmContext) {
          swarmContext.artifacts["ragResults"] = ragResults;
          swarmContext.history.push({
            role: "assistant",
            agent: this.name,
            content: `Tudásbázis találatok:\n${formattedResults}`,
          });
        }

        return {
          success: true,
          message: `Találtam ${ragResults.length} releváns elemet a tudásbázisban.`,
          data: {
            source: "rag",
            results: ragResults,
            summary: `Találtam ${ragResults.length} releváns elemet a tudásbázisban.`,
          },
          contextUsed: ragResults.map((r) => r.source),
        };
      } else {
        return {
          success: true,
          message: "Nem találtam releváns információt a tudásbázisban.",
          data: {
            source: "rag",
            results: [],
            summary: "Nem találtam releváns információt a tudásbázisban.",
          },
        };
      }
    }

    // 2. Mock Web Search (Fallback)
    if (
      taskLower.includes("keress") ||
      taskLower.includes("search") ||
      taskLower.includes("web")
    ) {
      logInfo("ResearcherAgent", `Web Searching for: ${task}`);

      // Simulate finding data
      const searchResults = [
        { title: "Result 1", snippet: "Information about " + task },
        { title: "Result 2", snippet: "More details on " + task },
      ];

      // Store in Swarm Context if available
      if (swarmContext) {
        swarmContext.artifacts["searchResults"] = searchResults;
        swarmContext.history.push({
          role: "assistant",
          agent: this.name,
          content: `Found ${searchResults.length} results for "${task}". Saved to artifacts.`,
        });
      }

      // Handoff to Data Scientist for analysis if needed
      if (taskLower.includes("elemz") || taskLower.includes("analyze")) {
        return this.createHandoff(
          "DataScientist",
          `Analyze the search results for: ${task}`,
          "Search complete, analysis required.",
        );
      }

      return {
        success: true,
        message: `Webes keresés sikeres: ${searchResults.length} találat`,
        data: searchResults,
      };
    }

    return {
      success: false,
      message:
        'Nem tudom értelmezni a kutatási feladatot. Használj kulcsszavakat: "rag", "tudásbázis", "keress", "web".',
    };
  }
}

export default ResearcherAgent;

/**
 * RobotkezAgent.ts - Browser-Use AI Operator
 * 
 * Ez az ügynök felelős a böngésző alapú automatizációért a Python alrendszeren keresztül.
 * Támogatja a kattintásokat, gépelést és képernyőképek lekérését.
 */

import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logError } from '../utils/logger.js';
import { v4 as uuidv4 } from 'uuid';

export class RobotkezAgent extends BaseAgent {
    name = 'Robotkez'; // Corrected name to match routing
    role = 'Böngésző Operátor';
    description = 'Böngésző alapú feladatokat hajt végre (kattintás, keresés, form kitöltés)';
    capabilities = ['browser_automation', 'web_scraping', 'ui_interaction', 'screenshots'];

    private pythonApiUrl: string;

    constructor() {
        super();
        this.pythonApiUrl = process.env.BRUNELLA_PYTHON_API_URL || 'http://127.0.0.1:8000';
    }

    async executeTask(context: AgentContext): Promise<AgentResult> {
        const instruction = context.task || '';
        logInfo('RobotkezAgent', `Végrehajtás: ${instruction.slice(0, 100)}...`);

        try {
            const taskId = `robotkez-task-${uuidv4()}`;
            
            // Construct the payload for the Python server's /api/task endpoint
            const requestBody = {
                taskId: taskId,
                type: "browser",
                payload: {
                    instruction: instruction,
                    context: context.context || {} // Pass the nested context object
                }
            };

            const response = await fetch(`${this.pythonApiUrl}/api/task`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify(requestBody),
            });

            if (!response.ok) {
                const errorText = await response.text();
                logError('RobotkezAgent', `Python API hiba (${response.status}): ${errorText}`);
                throw new Error(`Python API hiba: ${response.status} ${response.statusText} - ${errorText}`);
            }

            const result: any = await response.json();

            return {
                success: result.status === 'ok',
                message: result.result?.summary || 'A böngésző művelet befejeződött.',
                data: result.result, // Pass the whole result object back
                thoughts: `A feladatot a Python browser_worker hajtotta végre. Állapot: ${result.status}`
            };

        } catch (error: any) {
            logError('RobotkezAgent', `Hiba: ${error.message}`);
            return {
                success: false,
                message: `Nem sikerült végrehajtani a böngésző műveletet: ${error.message}`
            };
        }
    }
}

export default RobotkezAgent;

/**
 * RobotkezV2Agent - Hybrid Browser Automation (Playwright + Browser-Use)
 *
 * Bridge between TypeScript (MCP agent) and Python hybrid engine
 * (myai/agents/robotkez_v2_hybrid.py)
 *
 * Modes:
 * - auto: Complexity analyzer decides (keyword-based)
 * - playwright: Fast, fixed selectors (screenshot, PDF, navigate)
 * - browser-use: AI-powered, flexible (Gemini 2.0 Flash)
 *
 * @author Claude Code + Pohánka Péter
 * @track robotkezv2-hybrid-20260217
 */

import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { logInfo, logWarn, logError, setAgentStatus } from '../utils/logger.js';
import { backgroundTaskManager } from '../utils/backgroundTaskManager.js';
import { BrowserCommand } from '../utils/persistentBrowser.js';
import { getRobotkezBrowserEngine } from '../utils/browserEngine.js';
import { generateExecutionPlan, ExecutionPlan, ExecutionStep } from '../utils/llmPlanner.js';
import { socketService } from '../server/SocketService.js';
import { robotkezPro, UIAction } from '../services/RobotkezProService.js';

export interface RobotkezV2Options {
  mode?: 'auto' | 'playwright' | 'browser-use';
  headless?: boolean;
  screenshot_path?: string;
  pdf_path?: string;
  selector?: string;
  timeout?: number;
  url?: string;
}

export class RobotkezV2Agent extends BaseAgent {
  name = 'RobotkezV2';
  role = 'Magyar Agentic Browser (Comet Stílus)';
  description = 'Folyékonyan kommunikáló, proaktív böngésző ügynök vizuális visszajelzéssel.';
  capabilities = [
    'browser_automation',
    'screenshot',
    'pdf_generation',
    'web_scraping',
    'ai_browsing',
    'multi_step_workflow',
    'magyar_nyelv',
    'agentic_browsing'
  ];

  private chatEndpoint = process.env.BROWSER_CHAT_ENDPOINT || 'http://localhost:8000/browser/chat';
  private screenshotEndpoint = process.env.BROWSER_SCREENSHOT_ENDPOINT || 'http://localhost:8000/browser/screenshot';

  async chat(message: string, sessionId?: string): Promise<string> {
    logInfo(this.name, `Chat request: ${message}`);

    try {
      const importAxios = await import('axios');
      const axios = importAxios.default;
      const response = await axios.post(this.chatEndpoint, {
        message,
        sessionId: sessionId || this.generateSessionId()
      });

      const data = response.data;

      if (data.screenshot) {
        await this.saveScreenshot(sessionId, data.screenshot);
      }

      return data.response;
    } catch (error) {
      logError(this.name, `Chat error: ${error}`);
      return 'Hiba történt a böngésző interakcióban. Kérlek próbáld újra.';
    }
  }

  async takeScreenshot(sessionId?: string): Promise<string> {
    try {
      const importAxios = await import('axios');
      const axios = importAxios.default;
      const response = await axios.get(this.screenshotEndpoint, {
        responseType: 'arraybuffer'
      });

      const screenshot = Buffer.from(response.data, 'binary').toString('base64');
      await this.saveScreenshot(sessionId, screenshot);

      return screenshot;
    } catch (error) {
      logError(this.name, `Screenshot error: ${error}`);
      throw error;
    }
  }

  private async saveScreenshot(sessionId: string | undefined, screenshot: string): Promise<void> {
    const sessionDir = sessionId
      ? `data/screenshots/${sessionId}`
      : `data/screenshots/${Date.now()}`;

    try {
      const fs = await import('fs/promises');
      // Mappa létrehozása (ha nem létezik)
      await fs.mkdir(sessionDir, { recursive: true });

      // Screenshot mentése
      const filename = `screenshot_${Date.now()}.png`;
      await fs.writeFile(
        `${sessionDir}/${filename}`,
        Buffer.from(screenshot, 'base64')
      );

      logInfo(this.name, `Screenshot mentve: ${sessionDir}/${filename}`);
    } catch (err) {
      logError(this.name, `Failed to save screenshot: ${err}`);
    }
  }

  private generateSessionId(): string {
    return `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
  }

  /**
   * Internal execution logic - implements BaseAgent.executeTask
   */
  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = (context.task || '').trim();
    setAgentStatus(this.name, 'working', task.slice(0, 50));

    try {
      const browserEngine = getRobotkezBrowserEngine();

      // 1. Simple Intent Parsing (Phase 2 compatibility for tests)
      let plan: ExecutionPlan | null = null;
      
      const taskLower = task.toLowerCase();
      
      if (taskLower.includes('nyisd meg a böngészőt') || taskLower.includes('indítsd el a böngészőt')) {
        plan = {
          plan: [{ action: 'navigate', url: 'about:blank', description: 'Böngésző megnyitása üres lappal' }],
          estimatedDuration: 3000,
          backgroundEligible: false
        };
      } else if (taskLower.includes('navigálj') || taskLower.includes('frissíts')) {
        let url = task.match(/https?:\/\/[^\s]+/)?.[0];
        if (!url && !taskLower.includes('frissíts')) {
           const domainMatch = task.match(/([a-z0-9]+\.)+[a-z]{2,}/i);
           if (domainMatch) url = `https://${domainMatch[0]}`;
        }
        
        if (url || taskLower.includes('frissíts')) {
          plan = {
            plan: [
              { 
                action: url ? 'navigate' : 'screenshot', 
                url: url, 
                description: url ? `Navigálás a(z) ${url} weboldalra` : 'Oldal frissítése és szinkronizálása' 
              }
            ],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        } else {
          // Fallback to search if "navigálj" but no URL
          const query = task.replace(/navigálj/i, '').trim();
          plan = {
            plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(query)}`, description: `Keresés indítása: ${query}` }],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        }
      } else if (taskLower.includes('keress rá')) {
        const query = task.replace(/keress rá a? /i, '').trim();
        plan = {
          plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(query)}`, description: `Google keresés: ${query}` }],
          estimatedDuration: 5000,
          backgroundEligible: false
        };
      } else if (taskLower.includes('kattints')) {
        const selector = task.match(/['"]([^'"]+)['"]/)?.[1] || (taskLower === 'kattints' ? '.primary-button' : null);
        if (selector) {
          plan = {
            plan: [{ action: 'click', selector, description: `Kattintás a(z) '${selector}' elemre` }],
            estimatedDuration: 3000,
            backgroundEligible: false
          };
        }
      } else if (taskLower.includes('írj be') || taskLower.includes('gépelj')) {
        const text = task.match(/['"]([^'"]+)['"]/)?.[1] || 'Hello World';
        const selector = task.match(/a '([^']+)' mezőbe/)?.[1] || 'input';
        plan = {
          plan: [{ action: 'type', selector, text, description: `Szöveg beírása a(z) '${selector}' mezőbe: "${text}"` }],
          estimatedDuration: 4000,
          backgroundEligible: false
        };
      } else if (taskLower.includes('képernyőkép')) {
        plan = {
          plan: [{ action: 'screenshot', description: 'Pillanatkép készítése a jelenlegi oldalról' }],
          estimatedDuration: 3000,
          backgroundEligible: false
        };
      }

      // 2. LLM Plan Generation (if not already parsed or for Phase 3+)
      if (!plan) {
        try {
          // Get current browser state if possible
          let browserState;
          try {
             const stateResponse = await browserEngine.sendCommand({ action: 'state' });
             if (stateResponse.status === 'success') {
                browserState = {
                  url: stateResponse.url || '',
                  title: stateResponse.title
                };
             }
          } catch {
             // Ignored
          }

          plan = await generateExecutionPlan(task, {
            history: context.swarm?.history,
            browserState: browserState
          });
        } catch {
          // Final fallback
          plan = {
            plan: [{ action: 'navigate', url: `https://www.google.com/search?q=${encodeURIComponent(task)}`, description: 'Általános keresés indítása' }],
            estimatedDuration: 5000,
            backgroundEligible: false
          };
        }
      }

      // EMIT PLAN to Dashboard (Comet-style)
      socketService.emit('robotkez:plan', { taskId: `rk-${Date.now()}`, plan });

      // 3. Background Delegation (Phase 4.4)
      if (context.backgroundEligible || plan.estimatedDuration > 30000 || plan.backgroundEligible) {
        const taskId = await backgroundTaskManager.startTask(task, plan);
        return {
          success: true,
          message: `Rendben, elindítottam a feladatot a háttérben. A folyamatot a "Background Tasks" panelen követheted nyomon. (Task ID: ${taskId})`,
          data: { taskId, background: true }
        };
      }

      // 4. Sequential execution via selected browser engine
      logInfo(this.name, `Executing plan: ${plan.plan.length} steps`);
      const completedSteps: unknown[] = [];

      for (let i = 0; i < plan.plan.length; i++) {
        const step = plan.plan[i];
        logInfo(this.name, `Step: ${step.description} (${step.action})`);
        
        // EMIT STEP START
        socketService.emit('robotkez:step', { index: i, status: 'working', description: step.description });

        try {
          // VISION ACTION: If action is explicitly vision-click
          if (step.action === 'vision-click') {
            const visionRes = await robotkezPro.executeAction(step as unknown as UIAction);
            completedSteps.push({ ...step, status: 'completed', result: visionRes });
            socketService.emit('robotkez:step', { 
                index: i, 
                status: 'completed', 
                description: step.description,
                coords: (visionRes as any).coords 
            });
            continue;
          }

          // DYNAMIC SELECTOR: If selector is missing but description exists
          if (['click', 'type', 'wait', 'extract'].includes(step.action) && !step.selector && step.description) {
            logInfo(this.name, `Dynamic vision query for: ${step.description}`);
            const queryResp = await browserEngine.sendCommand({
                action: 'query',
                description: step.description
            } as any);
            
            if (queryResp.status === 'success') {
                const queryData = queryResp.data as Record<string, unknown>;
                if (queryData.selector) {
                    step.selector = String(queryData.selector);
                    logInfo(this.name, `Resolved selector: ${step.selector}`);
                } else {
                    throw new Error(`Nem találtam meg a következő elemet: "${step.description}"`);
                }
            } else {
                throw new Error(`Nem találtam meg a következő elemet: "${step.description}"`);
            }
          }

          // Strip description and other non-command properties for browser compatibility
          // eslint-disable-next-line @typescript-eslint/no-unused-vars
          const { description: _desc, ...command } = step as unknown as Record<string, unknown>;
          const browserCommand = command as unknown as BrowserCommand;
          let response = await browserEngine.sendCommand(browserCommand);
          
          // SELF-HEALING: If standard action failed, try Vision fallback
          if (response.status === 'error' && ['click', 'type'].includes(step.action)) {
            logWarn(this.name, `Step failed, attempting self-healing with Vision for: ${step.description}`);
            socketService.emit('robotkez:vision_thought', { message: "Hiba történt, megpróbálom vizuálisan azonosítani az elemet..." });
            
            const visionStep: UIAction = {
                action: 'vision-click',
                target: step.description,
                description: `Self-healing: ${step.description}`
            };
            const visionRes = await robotkezPro.executeAction(visionStep) as Record<string, unknown>;
            if (visionRes['status'] === 'success') {
                response = visionRes as any;
            }
          }

          completedSteps.push({
            ...step,
            status: response.status === 'success' ? 'completed' : 'error',
            result: response
          });

          // EMIT STEP SUCCESS/RESULT
          socketService.emit('robotkez:step', { 
            index: i, 
            status: response.status === 'success' ? 'completed' : 'error', 
            screenshot: response.screenshot,
            coords: (response as any).coords
          });

          if (response.status === 'error') {
            throw new Error(response.message || 'Browser action failed');
          }

        } catch (stepError: unknown) {
          const msg = stepError instanceof Error ? stepError.message : String(stepError);
          const action = step.action;
          logError(this.name, `Step failed: ${step.description} - ${msg}`);
          
          // Stop on critical error
          if (['navigate', 'click', 'type'].includes(action)) {
             return {
               success: false,
               message: `Sajnos nem sikerült végrehajtani a következő lépést: "${step.description}". Hibaüzenet: ${msg}`
             };
          }
        }
      }

      // 5. Auto-Screenshot (Phase 2 expectation)
      let screenshotResult;
      try {
        screenshotResult = await browserEngine.sendCommand({ action: 'screenshot' });
      } catch {
        // Ignored
      }

      const isScreenshotTask = taskLower.includes('képernyőkép');
      const baseMessage = isScreenshotTask
        ? 'Elkészítettem a kért képernyőképet.'
        : `Sikeresen végrehajtottam a feladatot: "${task}".`;

      return {
        success: true,
        message: baseMessage,
        data: {
           completedSteps,
           screenshot: screenshotResult?.screenshot,
           success: true // Legacy support
        }
      };

    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      logError(this.name, `Execution failed: ${msg}`);
      return {
        success: false,
        message: `Hiba történt a végrehajtás során: ${msg}`
      };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  // Phase 4.4 Background Task Methods
  async executeInBackground(task: string): Promise<{ taskId: string; plan?: ExecutionPlan }> {
    const plan = await generateExecutionPlan(task);
    const taskId = await backgroundTaskManager.startTask(task, plan);
    return { taskId, plan };
  }

  getBackgroundTaskStatus(taskId: string) {
    return backgroundTaskManager.getTaskStatus(taskId);
  }

  cancelBackgroundTask(taskId: string) {
    return backgroundTaskManager.cancelTask(taskId);
  }

  listBackgroundTasks() {
    return backgroundTaskManager.getAllTasks();
  }

  /**
   * Execute with explicit mode (convenience method)
   *
   * @param task - Instruction
   * @param mode - Execution mode
   * @param options - Additional options
   */
  async executeWithMode(
    task: string,
    mode: 'auto' | 'playwright' | 'browser-use',
    options?: Partial<RobotkezV2Options>
  ): Promise<unknown> {
    return this.execute(task, { ...options, mode });
  }

  /**
   * Screenshot convenience method
   *
   * @param url - Target URL
   * @param screenshotPath - Output path (default: screenshot.png)
   */
  async screenshot(url: string, screenshotPath?: string): Promise<unknown> {
    return this.execute(`screenshot ${url}`, {
      mode: 'playwright', // Force Playwright (fast)
      url,
      screenshot_path: screenshotPath || 'screenshot.png'
    });
  }

  /**
   * PDF generation convenience method
   *
   * @param url - Target URL
   * @param pdfPath - Output path (default: page.pdf)
   */
  async generatePdf(url: string, pdfPath?: string): Promise<unknown> {
    return this.execute(`pdf ${url}`, {
      mode: 'playwright', // Force Playwright (fast)
      url,
      pdf_path: pdfPath || 'page.pdf'
    });
  }

  /**
   * AI-powered complex task (force Browser-Use)
   *
   * @param instruction - Natural language instruction
   */
  async aiTask(instruction: string): Promise<unknown> {
    return this.execute(instruction, {
      mode: 'browser-use' // Force AI mode
    });
  }
}

export default RobotkezV2Agent;

/**
 * Sales Hunter Agent - Automata Értékesítő Gép
 * 
 * Automated lead generation with LinkedIn scraping, email drafting,
 * and CRM integration (Google Sheets).
 * 
 * Features:
 * - LinkedIn profile discovery and scraping
 * - Decision-maker identification
 * - Automated email draft generation
 * - Lead scoring (0-100 relevance)
 * - Rate limiting (max 50 profiles/hour)
 * - Google Sheets export
 * 
 * @module SalesHunterAgent
 * @version 1.0.0
 */

import { BaseAgent, AgentContext, AgentResult } from './BaseAgent.js';
import { AgentResponse } from './types.js';
import { logInfo, logError, logWarn, setAgentStatus } from '../utils/logger.js';
import { getWorkspaceClient } from '../tools/unifiedWorkspace.js';
import { agentManager } from './AgentManager.js';
import type { LeadGenerationData, LeadRecord } from '../types/enterprise.js';

// ============================================================================
// Types
// ============================================================================

interface LeadProfile {
  companyName: string;
  decisionMaker: string;
  contactInfo: string;
  linkedinUrl: string;
  industry: string;
  companySize: string;
  location: string;
  score: number; // 0-100 relevance score
  notes?: string;
}

interface EmailDraftResult {
  to: string;
  subject: string;
  body: string;
  linkedinContext?: string;
}

interface SalesHunterResult {
  leads: LeadProfile[];
  draftEmails: EmailDraftResult[];
  sheetsUrl?: string;
  stats: {
    leadsFound: number;
    emailsGenerated: number;
    averageScore: number;
  };
}

// ============================================================================
// Sales Hunter Agent Implementation
// ============================================================================

export class SalesHunterAgent extends BaseAgent {
  name = 'SalesHunter';
  role = 'Automated Lead Generation & CRM Integration';
  description = 'LinkedIn-based lead discovery with automated email drafting and CRM integration';
  capabilities = [
    'linkedin_scraping',
    'lead_scoring',
    'email_generation',
    'crm_export',
    'decision_maker_identification'
  ];

  private readonly MAX_PROFILES_PER_HOUR = 50;
  private readonly RATE_LIMIT_WINDOW_MS = 60 * 60 * 1000; // 1 hour
  private rateLimitTracker: Map<string, number[]> = new Map();

  protected override isTestMode(): boolean {
    return (
      process.env.NODE_ENV === 'test' ||
      process.env.VITEST === 'true' ||
      process.env.VITEST_WORKER_ID !== undefined
    );
  }

  /**
   * Execute lead generation task (BaseAgent interface implementation)
   */
  async executeTask(context: AgentContext): Promise<AgentResult> {
    const task = (context.task || '').trim();
    if (!task) return { success: false, message: 'Üres feladat leírás' };

    setAgentStatus(this.name, 'working', `Lead generálás: ${task.substring(0, 50)}...`);

    // Memory awareness: Check for past failures
    const failures = (context.pastExperiences as any[])?.filter(e => e.text.includes('HIBA')) || [];
    if (failures.length > 0) {
      logWarn(this.name, `Figyelem: ${failures.length} korábbi hiba észlelve hasonló feladatnál. Óvatos végrehajtás...`);
    }

    try {
      logInfo(this.name, 'Lead generálási folyamat indítása...');

      // Parse input
      const params = this.parseLeadRequest(task);
      logInfo(this.name, `Cél: ${params.industry}, ${params.location}, ${params.companySize}`);

      // Check rate limits
      if (!this.checkRateLimit(params)) {
        return {
          success: false,
          message: `Sebességkorlát túllépve. Max ${this.MAX_PROFILES_PER_HOUR} profil/óra.`,
        };
      }

      // Execute lead generation pipeline
      const result = await this.generateLeads(params);

      // Export to Google Sheets if requested
      if (context.exportToSheets) {
        result.crmExportUrl = await this.exportToSheets(result.leads);
      }

      logInfo(this.name, `✅ Lead generálás kész: ${result.leads.length} lead találva`);

      return {
        success: true,
        status: 'success',
        message: `Találtam ${result.leads.length} új leadet és elkészítettem az email sablonokat. Átlagos relevancia: ${result.stats.avgScore.toFixed(1)}%`,
        data: result,
      };

    } catch (error: unknown) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      logError(this.name, `Lead generálási hiba: ${errorMsg}`);
      
      return {
        success: false,
        message: errorMsg,
      };
    } finally {
      setAgentStatus(this.name, 'idle');
    }
  }

  // Remove the old execute method as it's now handled by executeTask and BaseAgent bridge


  // ==========================================================================
  // Core Pipeline Methods
  // ==========================================================================

  /**
   * Main lead generation pipeline
   */
  private async generateLeads(params: LeadGenerationData): Promise<any> {
    // Step 1: Discover companies (simulated - in production would use LinkedIn scraper)
    const companies = await this.discoverCompanies(params);
    
    // Step 2: Score leads based on relevance
    const scoredLeads = this.scoreLeads(companies, params);

    // Step 3: Generate email drafts for top leads
    const topLeads = scoredLeads
      .sort((a, b) => b.score - a.score)
      .slice(0, params.targetCount || 20);

    const emailDrafts = await this.generateEmailDrafts(topLeads, params);

    // Map leads to format expected by tests
    const formattedLeads = topLeads.map((l, index) => ({
      ...l,
      name: l.decisionMaker,
      email: l.contactInfo,
      company: l.companyName,
      role: 'Decision Maker',
      emailDraft: emailDrafts[index]
    }));

    // Step 4: Calculate stats
    const stats = {
      totalLeads: formattedLeads.length,
      highQuality: formattedLeads.filter(l => l.score >= 80).length,
      avgScore: formattedLeads.reduce((sum, lead) => sum + lead.score, 0) / formattedLeads.length || 0,
    };

    return {
      leads: formattedLeads,
      emailDrafts,
      crmExportUrl: '', // Default to empty string for test compatibility
      stats,
    };
  }

  /**
   * Discover companies matching criteria using RobotkezV2 (Real-world discovery)
   */
  private async discoverCompanies(params: LeadGenerationData): Promise<LeadProfile[]> {
    if (this.isTestMode()) {
      logInfo(this.name, 'Test mode: using mock leads (skip RobotkezV2).');
      return this.generateMockLeads(params);
    }

    logInfo(this.name, `Discovering real companies in ${params.industry} via RobotkezV2...`);

    const instruction = `
      Navigálj a LinkedIn Sales Navigator vagy kereső oldalra.
      Keress rá a következőre: ${params.industry} vállalatok, helyszín: ${params.location}, méret: ${params.companySize}.
      Azonosítsd a döntéshozókat (CEO, CTO, Sales Director).
      Gyűjts össze ${params.targetCount || 5} profilt.
      Add vissza az adatokat JSON formátumban a következő mezőkkel: companyName, decisionMaker, contactInfo, linkedinUrl, industry, companySize, location.
      Csak a JSON tömböt add vissza.
    `;

    try {
      const response = await agentManager.delegate('RobotkezV2', instruction) as any;
      
      if (response && response.success && response.data) {
        logInfo(this.name, `✅ Real discovery successful via RobotkezV2`);
        
        // Extract JSON from response data (might be in a message or nested in data)
        let leads: LeadProfile[] = [];
        try {
          const content = response.message || response.data.message || '';
          const jsonMatch = content.match(/\[[\s\S]*\]/);
          if (jsonMatch) {
            leads = JSON.parse(jsonMatch[0]);
          } else if (Array.isArray(response.data)) {
            leads = response.data;
          }
        } catch (e) {
          logError(this.name, `Failed to parse RobotkezV2 JSON response: ${e}`);
        }

        if (leads.length > 0) {
          return leads.map(l => ({
            ...l,
            score: 0 // Will be scored later
          }));
        }
      }
      
      logWarn(this.name, 'RobotkezV2 discovery returned no data, falling back to basic mock for stability');
    } catch (error) {
      logError(this.name, `RobotkezV2 delegation failed: ${error}`);
    }

    // Fallback to mock (only if real fails)
    return this.generateMockLeads(params);
  }

  /**
   * Generate mock leads (Fallback mechanism)
   */
  private generateMockLeads(params: LeadGenerationData): LeadProfile[] {
    const mockLeads: LeadProfile[] = [];
    const companySizes = {
      startup: ['5-20', '10-50'],
      sme: ['50-200', '100-500'],
      enterprise: ['500-1000', '1000+'],
    };

    const sizeRanges = companySizes[params.companySize] || ['50-200'];
    const keywords = params.keywords || [];

    for (let i = 0; i < (params.targetCount || 5); i++) {
      mockLeads.push({
        companyName: `${params.industry} Company ${i + 1} (MOCK)`,
        decisionMaker: `${this.generateName()} ${this.generateSurname()}`,
        contactInfo: `contact${i}@example.com`,
        linkedinUrl: `https://www.linkedin.com/in/mock-profile-${i}`,
        industry: params.industry,
        companySize: sizeRanges[i % sizeRanges.length],
        location: params.location,
        score: 0,
        notes: `Keywords: ${keywords.join(', ')}`,
      });
    }

    return mockLeads;
  }

  /**
   * Score leads based on relevance (0-100)
   * 
   * Scoring algorithm:
   * - Industry match: 30 points
   * - Location match: 20 points
   * - Company size match: 20 points
   * - Keyword presence: 30 points
   */
  private scoreLeads(leads: LeadProfile[], params: LeadGenerationData): LeadProfile[] {
    return leads.map(lead => {
      let score = 0;

      // Industry match (30 points)
      if (lead.industry.toLowerCase().includes(params.industry.toLowerCase())) {
        score += 30;
      }

      // Location match (20 points)
      if (lead.location.toLowerCase().includes(params.location.toLowerCase())) {
        score += 20;
      }

      // Company size match (20 points)
      const sizeMap: Record<string, string[]> = {
        startup: ['5-20', '10-50'],
        sme: ['50-200', '100-500'],
        enterprise: ['500-1000', '1000+'],
      };
      if (sizeMap[params.companySize]?.includes(lead.companySize)) {
        score += 20;
      }

      // Keyword match (30 points max, 10 per keyword)
      const keywords = params.keywords || [];
      const keywordMatches = keywords.filter(kw =>
        lead.companyName.toLowerCase().includes(kw.toLowerCase()) ||
        lead.notes?.toLowerCase().includes(kw.toLowerCase())
      );
      score += Math.min(keywordMatches.length * 10, 30);

      lead.score = score;
      return lead;
    });
  }

  /**
   * Generate personalized email drafts for leads
   */
  private async generateEmailDrafts(
    leads: LeadProfile[],
    params: LeadGenerationData
  ): Promise<EmailDraftResult[]> {
    logInfo(this.name, `Generating email drafts for ${leads.length} leads...`);

    const drafts: EmailDraftResult[] = [];

    for (const lead of leads) {
      const draft = this.createEmailDraft(lead, params);
      drafts.push(draft);
    }

    return drafts;
  }

  /**
   * Create personalized email draft
   */
  private createEmailDraft(lead: LeadProfile, params: LeadGenerationData): EmailDraftResult {
    const subject = `Együttműködési lehetőség - ${params.industry}`;
    const keywords = params.keywords || [];

    const body = `Tisztelt ${lead.decisionMaker}!

Péter vagyok a [Cég neve] képviseletében és azért keresem Önt, mert a ${lead.companyName} kiemelkedő szakértelme felkeltette a figyelmünket a ${params.industry} területén.

Tapasztalatunk alapján számos hasonló vállalkozás számára sikerült növekedést elérni a következő területeken:
${keywords.map(kw => `  • ${kw}`).join('\n')}

Szeretném megbeszélni, hogy milyen módon tudnánk együttműködni a ${lead.companyName} további fejlődése érdekében.

Tudnánk rövid egyeztetést tartani a következő hetekben?

Üdvözlettel,
[Név]
[Cég]

---
LinkedIn profil alapján: ${lead.linkedinUrl}
Relevancia pontszám: ${lead.score}/100`;

    return {
      to: lead.contactInfo,
      subject,
      body,
      linkedinContext: lead.linkedinUrl,
    };
  }

  /**
   * Export leads to Google Sheets
   */
  private async exportToSheets(leads: LeadProfile[]): Promise<string> {
    try {
      logInfo(this.name, 'Exporting leads to Google Sheets...');

      const workspace = await getWorkspaceClient();

      // Create new spreadsheet
      const { spreadsheetId, url } = await workspace.createSpreadsheet(
        `Sales Leads - ${new Date().toISOString().split('T')[0]}`
      );

      // Prepare data rows
      const headers = [
        'Company Name',
        'Decision Maker',
        'Contact',
        'LinkedIn',
        'Industry',
        'Size',
        'Location',
        'Score',
        'Notes',
      ];

      const rows = leads.map(lead => [
        lead.companyName,
        lead.decisionMaker,
        lead.contactInfo,
        lead.linkedinUrl,
        lead.industry,
        lead.companySize,
        lead.location,
        lead.score.toString(),
        lead.notes || '',
      ]);

      // Write to sheet
      await workspace.performSheetOperation({
        spreadsheetId,
        range: 'A1',
        values: [headers, ...rows],
        operation: 'update',
      });

      logInfo(this.name, `✅ Exported ${leads.length} leads to: ${url}`);
      return url;

    } catch (error: unknown) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      logError(this.name, `Sheets export failed: ${errorMsg}`);
      throw new Error(`Failed to export to Sheets: ${errorMsg}`);
    }
  }

  // ==========================================================================
  // Helper Methods
  // ==========================================================================

  /**
   * Parse lead generation request from natural language or JSON
   */
  private parseLeadRequest(task: string): LeadGenerationData {
    try {
      // Try parsing as JSON first
      const parsed = JSON.parse(task);
      if (parsed.industry) {
        return parsed as LeadGenerationData;
      }
    } catch {
      // Not JSON, extract from natural language
    }

    // Simple keyword extraction (in production, would use LLM)
    const lowerTask = task.toLowerCase();

    return {
      industry: this.extractIndustry(task) || 'general',
      location: this.extractLocation(task) || 'Hungary',
      companySize: this.extractCompanySize(lowerTask),
      keywords: this.extractKeywords(task),
      targetCount: this.extractTargetCount(task) || 20,
    };
  }

  private extractIndustry(task: string): string {
    const industries = [
      'industrial equipment',
      'automation',
      'manufacturing',
      'tech',
      'software',
      'consulting',
      'logistics',
    ];

    for (const industry of industries) {
      if (task.toLowerCase().includes(industry)) {
        return industry;
      }
    }

    return 'general';
  }

  private extractLocation(task: string): string {
    const locations = ['Hungary', 'Budapest', 'Europe', 'Germany', 'Austria'];
    
    for (const loc of locations) {
      if (task.toLowerCase().includes(loc.toLowerCase())) {
        return loc;
      }
    }

    return 'Hungary';
  }

  private extractCompanySize(lowerTask: string): 'startup' | 'sme' | 'enterprise' {
    if (lowerTask.includes('startup') || lowerTask.includes('kis')) {
      return 'startup';
    }
    if (lowerTask.includes('enterprise') || lowerTask.includes('nagy')) {
      return 'enterprise';
    }
    return 'sme';
  }

  private extractKeywords(task: string): string[] {
    // Extract words longer than 4 characters as potential keywords
    const words = task.split(/\s+/)
      .filter(w => w.length > 4)
      .map(w => w.replace(/[^\w]/g, ''))
      .filter(w => w.length > 4);

    return words.slice(0, 5); // Max 5 keywords
  }

  private extractTargetCount(task: string): number | undefined {
    const match = task.match(/(\d+)\s*(leads?|companies|vállalat)/i);
    return match ? parseInt(match[1], 10) : undefined;
  }

  /**
   * Rate limiting check
   */
  private checkRateLimit(params: LeadGenerationData): boolean {
    const now = Date.now();
    const userId = 'default'; // In production, extract from context

    if (!this.rateLimitTracker.has(userId)) {
      this.rateLimitTracker.set(userId, []);
    }

    const userRequests = this.rateLimitTracker.get(userId)!;
    
    // Remove requests older than 1 hour
    const recentRequests = userRequests.filter(
      timestamp => now - timestamp < this.RATE_LIMIT_WINDOW_MS
    );

    // Calculate profiles from params
    const requestedProfiles = params.targetCount || 20;

    // Check if adding this request would exceed limit
    const totalProfiles = recentRequests.length + requestedProfiles;
    
    if (totalProfiles > this.MAX_PROFILES_PER_HOUR) {
      logError(this.name, `Rate limit exceeded: ${totalProfiles}/${this.MAX_PROFILES_PER_HOUR}`);
      return false;
    }

    // Add current request
    for (let i = 0; i < requestedProfiles; i++) {
      recentRequests.push(now);
    }

    this.rateLimitTracker.set(userId, recentRequests);
    return true;
  }

  /**
   * Generate random first name (for mock data)
   */
  private generateName(): string {
    const names = ['János', 'Péter', 'István', 'László', 'Gábor', 'Tamás', 'András', 'Zoltán'];
    return names[Math.floor(Math.random() * names.length)];
  }

  /**
   * Generate random surname (for mock data)
   */
  private generateSurname(): string {
    const surnames = ['Nagy', 'Kovács', 'Tóth', 'Szabó', 'Horváth', 'Kiss', 'Molnár', 'Varga'];
    return surnames[Math.floor(Math.random() * surnames.length)];
  }
}

