// FILE: src/agents/developerPipeline.ts
// PURPOSE: Task Pipeline architecture for DeveloperAgent 3.0
// VERSION: 3.0

import { logInfo, logError } from '../utils/logger.js';
import { developerMetrics } from '../utils/developerMetrics.js';
import { activityFeed } from '../utils/activityFeed.js';
import { EventEmitter } from 'events';

// ==================== Types ====================

export type PipelinePhaseId = 'plan' | 'generate' | 'validate' | 'save' | 'test';

export type PipelinePhaseStatus = 'pending' | 'running' | 'done' | 'error' | 'skipped';

export interface PipelinePhase {
    id: PipelinePhaseId;
    label: string;
    status: PipelinePhaseStatus;
    startedAt?: number;
    completedAt?: number;
    error?: string;
    output?: unknown;
}

export type TaskStatus = 'queued' | 'planning' | 'generating' | 'validating' | 'saving' | 'testing' | 'done' | 'error';

export interface TaskPipeline {
    taskId: string;
    task: string;
    status: TaskStatus;
    phases: PipelinePhase[];
    createdAt: number;
    completedAt?: number;
    result?: unknown;
    error?: string;
}

export interface ProgressEvent {
    taskId: string;
    phaseId: PipelinePhaseId;
    status: PipelinePhaseStatus;
    overallStatus: TaskStatus;
    progress: number; // 0-100
    message: string;
    timestamp: number;
}

// Phase definitions in order
const PHASE_DEFINITIONS: Array<{ id: PipelinePhaseId; label: string }> = [
    { id: 'plan', label: 'Planning' },
    { id: 'generate', label: 'Generating' },
    { id: 'validate', label: 'Validating' },
    { id: 'save', label: 'Saving' },
    { id: 'test', label: 'Testing' },
];

// Map phase ID to task status
const PHASE_TO_STATUS: Record<PipelinePhaseId, TaskStatus> = {
    plan: 'planning',
    generate: 'generating',
    validate: 'validating',
    save: 'saving',
    test: 'testing',
};

// ==================== PipelineRunner ====================

/**
 * PipelineRunner manages task execution through phases with progress events.
 * Emits 'progress' events for real-time streaming (Socket.IO).
 */
export class PipelineRunner extends EventEmitter {
    private pipelines: Map<string, TaskPipeline> = new Map();
    private taskCounter = 0;

    /**
     * Create a new pipeline for a task
     */
    createPipeline(task: string): TaskPipeline {
        const taskId = `dev-${Date.now()}-${++this.taskCounter}`;
        const pipeline: TaskPipeline = {
            taskId,
            task,
            status: 'queued',
            phases: PHASE_DEFINITIONS.map(def => ({
                id: def.id,
                label: def.label,
                status: 'pending',
            })),
            createdAt: Date.now(),
        };

        this.pipelines.set(taskId, pipeline);
        logInfo('PipelineRunner', `Pipeline created: ${taskId} → "${task.slice(0, 60)}"`);
        
        activityFeed.addActivity(
            'info',
            'pipeline',
            `Pipeline started: ${taskId}`,
            { taskId, task }
        );

        return pipeline;
    }

    /**
     * Get pipeline by task ID
     */
    getPipeline(taskId: string): TaskPipeline | undefined {
        return this.pipelines.get(taskId);
    }

    /**
     * Get recent pipelines (for history)
     */
    getHistory(limit = 20): TaskPipeline[] {
        const all = Array.from(this.pipelines.values());
        return all
            .sort((a, b) => b.createdAt - a.createdAt)
            .slice(0, limit);
    }

    /**
     * Start a phase
     */
    startPhase(taskId: string, phaseId: PipelinePhaseId): void {
        const pipeline = this.pipelines.get(taskId);
        if (!pipeline) return;

        const phase = pipeline.phases.find(p => p.id === phaseId);
        if (!phase) return;

        phase.status = 'running';
        phase.startedAt = Date.now();
        pipeline.status = PHASE_TO_STATUS[phaseId];

        this.emitProgress(pipeline, phaseId, 'running', `${phase.label}...`);
    }

    /**
     * Complete a phase
     */
    completePhase(taskId: string, phaseId: PipelinePhaseId, output?: unknown): void {
        const pipeline = this.pipelines.get(taskId);
        if (!pipeline) return;

        const phase = pipeline.phases.find(p => p.id === phaseId);
        if (!phase) return;

        phase.status = 'done';
        phase.completedAt = Date.now();
        phase.output = output;

        this.emitProgress(pipeline, phaseId, 'done', `${phase.label} complete`);
    }

    /**
     * Fail a phase (and entire pipeline)
     */
    failPhase(taskId: string, phaseId: PipelinePhaseId, error: string): void {
        const pipeline = this.pipelines.get(taskId);
        if (!pipeline) return;

        const phase = pipeline.phases.find(p => p.id === phaseId);
        if (!phase) return;

        phase.status = 'error';
        phase.completedAt = Date.now();
        phase.error = error;

        pipeline.status = 'error';
        pipeline.error = error;
        pipeline.completedAt = Date.now();

        // P10: Record metrics
        developerMetrics.recordTask(taskId, false, pipeline.completedAt - pipeline.createdAt).catch(err => 
            console.error('Failed to record metrics:', err)
        );

        this.emitProgress(pipeline, phaseId, 'error', `Error: ${error.slice(0, 100)}`);
        logError('PipelineRunner', `Pipeline ${taskId} failed at ${phaseId}: ${error}`);

        activityFeed.addActivity(
            'error',
            'pipeline',
            `Pipeline failed at ${phaseId}: ${error.slice(0, 100)}`,
            { taskId, phaseId, error }
        );
    }

    /**
     * Skip a phase
     */
    skipPhase(taskId: string, phaseId: PipelinePhaseId): void {
        const pipeline = this.pipelines.get(taskId);
        if (!pipeline) return;

        const phase = pipeline.phases.find(p => p.id === phaseId);
        if (!phase) return;

        phase.status = 'skipped';
        this.emitProgress(pipeline, phaseId, 'skipped', `${phase.label} skipped`);
    }

    /**
     * Mark pipeline as done
     */
    completePipeline(taskId: string, result?: unknown): void {
        const pipeline = this.pipelines.get(taskId);
        if (!pipeline) return;

        pipeline.status = 'done';
        pipeline.completedAt = Date.now();
        pipeline.result = result;

        const totalMs = pipeline.completedAt - pipeline.createdAt;
        
        // P10: Record metrics
        developerMetrics.recordTask(taskId, true, totalMs).catch(err => 
            console.error('Failed to record metrics:', err)
        );

        logInfo('PipelineRunner', `Pipeline ${taskId} done in ${totalMs}ms`);

        activityFeed.addActivity(
            'success',
            'pipeline',
            `Pipeline completed successfully: ${taskId}`,
            { taskId, duration: totalMs }
        );

        this.emitProgress(pipeline, 'test', 'done', `Task completed (${totalMs}ms)`);
    }

    /**
     * Calculate progress percentage (0-100)
     */
    private calculateProgress(pipeline: TaskPipeline): number {
        const total = pipeline.phases.length;
        const completed = pipeline.phases.filter(p => p.status === 'done' || p.status === 'skipped').length;
        const running = pipeline.phases.filter(p => p.status === 'running').length;
        return Math.round(((completed + running * 0.5) / total) * 100);
    }

    /**
     * Emit a progress event
     */
    private emitProgress(
        pipeline: TaskPipeline,
        phaseId: PipelinePhaseId,
        status: PipelinePhaseStatus,
        message: string
    ): void {
        const event: ProgressEvent = {
            taskId: pipeline.taskId,
            phaseId,
            status,
            overallStatus: pipeline.status,
            progress: this.calculateProgress(pipeline),
            message,
            timestamp: Date.now(),
        };

        this.emit('progress', event);
    }

    /**
     * Cleanup old pipelines (keep last N)
     */
    cleanup(keepLast = 50): number {
        const all = Array.from(this.pipelines.entries())
            .sort((a, b) => b[1].createdAt - a[1].createdAt);

        let removed = 0;
        for (let i = keepLast; i < all.length; i++) {
            this.pipelines.delete(all[i][0]);
            removed++;
        }
        return removed;
    }
}

// Singleton instance
export const pipelineRunner = new PipelineRunner();

/**
 * EvolutionaryAgent — Sandboxed agent mutation and evolution
 * Phase 6: Evolutionary Collective Intelligence
 *
 * Wraps agents with evolutionary capabilities: prompt mutation,
 * tool variation, parameter tuning — all in a safe sandbox.
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn } from '../../utils/logger.js';

export interface AgentGenome {
  id: string;
  agentId: string;
  generation: number;
  systemPrompt: string;
  tools: string[];
  parameters: Record<string, number>;
  fitness: number;          // 0–1 measured performance
  parentId?: string;
  mutationLog: string[];
  createdAt: number;
}

export type MutationType = 'prompt_tweak' | 'tool_add' | 'tool_remove' | 'param_adjust' | 'crossover';

export interface MutationResult {
  original: AgentGenome;
  mutated: AgentGenome;
  mutationType: MutationType;
  description: string;
}

export class EvolutionaryAgent extends EventEmitter {
  private genomes = new Map<string, AgentGenome>();
  private genomeCounter = 0;

  /** Create an initial genome for an agent */
  createGenome(config: {
    agentId: string;
    systemPrompt: string;
    tools: string[];
    parameters?: Record<string, number>;
  }): AgentGenome {
    const genome: AgentGenome = {
      id: `genome-${++this.genomeCounter}-${Date.now()}`,
      agentId: config.agentId,
      generation: 0,
      systemPrompt: config.systemPrompt,
      tools: [...config.tools],
      parameters: { ...config.parameters },
      fitness: 0,
      mutationLog: ['initial'],
      createdAt: Date.now(),
    };

    this.genomes.set(genome.id, genome);
    this.emit('genome:created', genome);
    return genome;
  }

  /** Mutate a genome to produce a variant */
  mutate(genomeId: string, mutationType: MutationType): MutationResult | null {
    const original = this.genomes.get(genomeId);
    if (!original) return null;

    const mutated: AgentGenome = {
      ...original,
      id: `genome-${++this.genomeCounter}-${Date.now()}`,
      generation: original.generation + 1,
      parentId: original.id,
      fitness: 0,
      mutationLog: [...original.mutationLog, mutationType],
      tools: [...original.tools],
      parameters: { ...original.parameters },
      createdAt: Date.now(),
    };

    let description = '';
    switch (mutationType) {
      case 'prompt_tweak':
        mutated.systemPrompt = this.tweakPrompt(original.systemPrompt);
        description = 'System prompt variation applied';
        break;
      case 'tool_add':
        mutated.tools.push(`tool_${Date.now()}`);
        description = `Added new tool (${mutated.tools.length} total)`;
        break;
      case 'tool_remove':
        if (mutated.tools.length > 1) {
          const removed = mutated.tools.pop();
          description = `Removed tool ${removed}`;
        } else {
          description = 'No tools to remove (kept minimum)';
        }
        break;
      case 'param_adjust': {
        const keys = Object.keys(mutated.parameters);
        if (keys.length > 0) {
          const key = keys[Math.floor(Math.random() * keys.length)];
          const delta = (Math.random() - 0.5) * 0.2;
          mutated.parameters[key] = Math.max(0, Math.min(1, (mutated.parameters[key] ?? 0.5) + delta));
          description = `Adjusted ${key} by ${delta.toFixed(3)}`;
        } else {
          description = 'No parameters to adjust';
        }
        break;
      }
      case 'crossover':
        description = 'Crossover (requires two parents — single-parent fallback)';
        break;
    }

    this.genomes.set(mutated.id, mutated);
    logInfo('EvolutionaryAgent', `Mutation: ${mutationType} on ${genomeId} → ${mutated.id}`);

    const result: MutationResult = { original, mutated, mutationType, description };
    this.emit('genome:mutated', result);
    return result;
  }

  /** Crossover two genomes */
  crossover(parentA: string, parentB: string): AgentGenome | null {
    const a = this.genomes.get(parentA);
    const b = this.genomes.get(parentB);
    if (!a || !b) return null;

    const child: AgentGenome = {
      id: `genome-${++this.genomeCounter}-${Date.now()}`,
      agentId: a.agentId,
      generation: Math.max(a.generation, b.generation) + 1,
      systemPrompt: Math.random() > 0.5 ? a.systemPrompt : b.systemPrompt,
      tools: [...new Set([...a.tools.slice(0, Math.ceil(a.tools.length / 2)), ...b.tools.slice(Math.ceil(b.tools.length / 2))])],
      parameters: this.mergeParameters(a.parameters, b.parameters),
      fitness: 0,
      parentId: a.id,
      mutationLog: [...a.mutationLog, `crossover_with_${b.id}`],
      createdAt: Date.now(),
    };

    this.genomes.set(child.id, child);
    this.emit('genome:crossover', child);
    return child;
  }

  /** Set fitness score after evaluation */
  setFitness(genomeId: string, fitness: number): void {
    const genome = this.genomes.get(genomeId);
    if (genome) {
      genome.fitness = Math.max(0, Math.min(1, fitness));
    }
  }

  /** Get a genome */
  getGenome(id: string): AgentGenome | undefined {
    return this.genomes.get(id);
  }

  /** Get all genomes for an agent, sorted by fitness */
  getGenomesForAgent(agentId: string): AgentGenome[] {
    return Array.from(this.genomes.values())
      .filter(g => g.agentId === agentId)
      .sort((a, b) => b.fitness - a.fitness);
  }

  /** Get the best genome for an agent */
  getBest(agentId: string): AgentGenome | undefined {
    return this.getGenomesForAgent(agentId)[0];
  }

  /** Simple prompt tweak: add variation markers */
  private tweakPrompt(prompt: string): string {
    const tweaks = [
      'Be more concise.',
      'Provide step-by-step reasoning.',
      'Focus on accuracy over speed.',
      'Use structured output format.',
      'Prioritize user intent detection.',
    ];
    const tweak = tweaks[Math.floor(Math.random() * tweaks.length)];
    return prompt + ` [Evolved: ${tweak}]`;
  }

  /** Merge parameters from two parents (average) */
  private mergeParameters(a: Record<string, number>, b: Record<string, number>): Record<string, number> {
    const merged: Record<string, number> = {};
    const allKeys = new Set([...Object.keys(a), ...Object.keys(b)]);
    for (const key of allKeys) {
      merged[key] = ((a[key] ?? 0.5) + (b[key] ?? 0.5)) / 2;
    }
    return merged;
  }
}

/**
 * P8: Git Workflow Automatizáció
 * Git operations manager for Developer Agent 3.0
 * Provides: status, diff, commit, push, branch management
 */

import { exec } from 'node:child_process';
import { promisify } from 'node:util';
import { logInfo, logError, logWarn } from '../utils/logger.js';

const execAsync = promisify(exec);

// ==================== Types ====================

export type GitFileStatus = 'modified' | 'added' | 'deleted' | 'renamed' | 'untracked' | 'conflicted';

export interface GitStatusResult {
    branch: string;
    remote?: string;
    ahead: number;
    behind: number;
    files: GitFileInfo[];
    staged: GitFileInfo[];
    unstaged: GitFileInfo[];
    untracked: string[];
    hasChanges: boolean;
}

export interface GitFileInfo {
    path: string;
    status: GitFileStatus;
    staged: boolean;
}

export interface GitDiffResult {
    file: string;
    diff: string;
    additions: number;
    deletions: number;
    hunks: DiffHunk[];
}

export interface DiffHunk {
    oldStart: number;
    oldLines: number;
    newStart: number;
    newLines: number;
    lines: string[];
}

export interface GitCommitResult {
    hash: string;
    message: string;
    filesChanged: number;
    insertions: number;
    deletions: number;
}

export interface GitPushResult {
    success: boolean;
    branch: string;
    remote: string;
    message: string;
}

export interface GitBranchInfo {
    name: string;
    current: boolean;
    remote?: string;
    lastCommit?: string;
}

export interface GitLogEntry {
    hash: string;
    author: string;
    date: string;
    message: string;
}

// ==================== Git Manager ====================

export class GitManager {
    private cwd: string;

    constructor(workspaceRoot: string) {
        this.cwd = workspaceRoot;
    }

    /**
     * Execute a git command and return output.
     */
    private async execGit(command: string): Promise<string> {
        try {
            const { stdout, stderr } = (await execAsync(`git ${command}`, {
                cwd: this.cwd,
                encoding: 'utf-8',
                timeout: 30000, // 30s timeout
            })) as { stdout: string; stderr: string };

            if (stderr && !stderr.includes('warning')) {
                logWarn('GitManager', `Git stderr: ${stderr.trim()}`);
            }

            // Use trimEnd() to preserve leading spaces (important for git status --porcelain)
            return stdout.trimEnd();
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            logError('GitManager', `Git command failed: git ${command} — ${msg}`);
            throw new Error(`Git command failed: ${msg}`);
        }
    }

    /**
     * Get current git status (branch, files, staged/unstaged changes).
     */
    async getStatus(): Promise<GitStatusResult> {
        logInfo('GitManager', 'Getting git status...');

        // Get branch and remote info
        const branch = await this.execGit('rev-parse --abbrev-ref HEAD');
        const remoteBranch = await this.execGit(`rev-parse --abbrev-ref ${branch}@{upstream}`).catch(() => '');
        
        // Get ahead/behind count
        let ahead = 0;
        let behind = 0;
        if (remoteBranch) {
            const counts = await this.execGit(`rev-list --left-right --count ${branch}...${remoteBranch}`).catch(() => '0\t0');
            const [aheadStr, behindStr] = counts.split('\t');
            ahead = parseInt(aheadStr, 10) || 0;
            behind = parseInt(behindStr, 10) || 0;
        }

        // Get file status (porcelain format)
        const statusOutput = await this.execGit('status --porcelain');
        const lines = statusOutput.split('\n').filter(l => l.trim());

        const files: GitFileInfo[] = [];
        const staged: GitFileInfo[] = [];
        const unstaged: GitFileInfo[] = [];
        const untracked: string[] = [];

        for (const line of lines) {
            const statusCode = line.substring(0, 2);
            const filePath = line.substring(3).trim();

            // Parse status codes (XY format: X=staged, Y=unstaged)
            const stagedCode = statusCode[0];
            const unstagedCode = statusCode[1];

            let status: GitFileStatus = 'modified';
            if (stagedCode === 'A' || unstagedCode === 'A') status = 'added';
            else if (stagedCode === 'D' || unstagedCode === 'D') status = 'deleted';
            else if (stagedCode === 'R' || unstagedCode === 'R') status = 'renamed';
            else if (stagedCode === 'U' || unstagedCode === 'U') status = 'conflicted';
            else if (stagedCode === '?' && unstagedCode === '?') status = 'untracked';

            const fileInfo: GitFileInfo = { path: filePath, status, staged: stagedCode !== ' ' && stagedCode !== '?' };

            files.push(fileInfo);

            if (stagedCode === '?' && unstagedCode === '?') {
                untracked.push(filePath);
            } else if (stagedCode !== ' ') {
                staged.push(fileInfo);
            }

            if (unstagedCode !== ' ' && unstagedCode !== '?') {
                unstaged.push({ ...fileInfo, staged: false });
            }
        }

        const result: GitStatusResult = {
            branch,
            remote: remoteBranch || undefined,
            ahead,
            behind,
            files,
            staged,
            unstaged,
            untracked,
            hasChanges: files.length > 0,
        };

        logInfo('GitManager', `Status: ${branch}, ${files.length} files changed, ${staged.length} staged`);
        return result;
    }

    /**
     * Get diff for a specific file or all staged changes.
     */
    async getDiff(filePath?: string, staged = false): Promise<GitDiffResult[]> {
        logInfo('GitManager', `Getting diff${filePath ? ` for ${filePath}` : ''}${staged ? ' (staged)' : ''}...`);

        const command = staged
            ? `diff --cached${filePath ? ` -- "${filePath}"` : ''}`
            : `diff${filePath ? ` -- "${filePath}"` : ''}`;

        const diffOutput = await this.execGit(command);
        if (!diffOutput) {
            return [];
        }

        return this.parseDiff(diffOutput);
    }

    /**
     * Parse unified diff output.
     */
    private parseDiff(diffOutput: string): GitDiffResult[] {
        const results: GitDiffResult[] = [];
        const fileDiffs = diffOutput.split(/^diff --git /gm).filter(Boolean);

        for (const fileDiff of fileDiffs) {
            const lines = fileDiff.split('\n');
            const firstLine = lines[0]; // a/path b/path
            const match = firstLine.match(/a\/(.+?) b\/(.+)/);
            if (!match) continue;

            const file = match[2]; // Use "b/" path (new file)
            let additions = 0;
            let deletions = 0;
            const hunks: DiffHunk[] = [];

            let currentHunk: DiffHunk | null = null;
            for (const line of lines) {
                if (line.startsWith('@@')) {
                    // Hunk header: @@ -old_start,old_lines +new_start,new_lines @@
                    const hunkMatch = line.match(/@@ -(\d+),?(\d+)? \+(\d+),?(\d+)? @@/);
                    if (hunkMatch) {
                        if (currentHunk) hunks.push(currentHunk);
                        currentHunk = {
                            oldStart: parseInt(hunkMatch[1], 10),
                            oldLines: parseInt(hunkMatch[2] || '1', 10),
                            newStart: parseInt(hunkMatch[3], 10),
                            newLines: parseInt(hunkMatch[4] || '1', 10),
                            lines: [],
                        };
                    }
                } else if (currentHunk && (line.startsWith('+') || line.startsWith('-') || line.startsWith(' '))) {
                    currentHunk.lines.push(line);
                    if (line.startsWith('+') && !line.startsWith('+++')) additions++;
                    if (line.startsWith('-') && !line.startsWith('---')) deletions++;
                }
            }

            if (currentHunk) hunks.push(currentHunk);

            results.push({
                file,
                diff: fileDiff,
                additions,
                deletions,
                hunks,
            });
        }

        logInfo('GitManager', `Parsed ${results.length} file diffs`);
        return results;
    }

    /**
     * Stage files (git add).
     */
    async stageFiles(files: string[]): Promise<void> {
        if (files.length === 0) {
            throw new Error('No files to stage');
        }

        logInfo('GitManager', `Staging ${files.length} files...`);
        const fileArgs = files.map(f => `"${f}"`).join(' ');
        await this.execGit(`add ${fileArgs}`);
        logInfo('GitManager', `Staged ${files.length} files`);
    }

    /**
     * Unstage files (git reset).
     */
    async unstageFiles(files: string[]): Promise<void> {
        if (files.length === 0) {
            throw new Error('No files to unstage');
        }

        logInfo('GitManager', `Unstaging ${files.length} files...`);
        const fileArgs = files.map(f => `"${f}"`).join(' ');
        await this.execGit(`reset HEAD ${fileArgs}`);
        logInfo('GitManager', `Unstaged ${files.length} files`);
    }

    /**
     * Commit staged changes.
     */
    async commit(message: string): Promise<GitCommitResult> {
        if (!message.trim()) {
            throw new Error('Commit message cannot be empty');
        }

        logInfo('GitManager', `Committing with message: "${message.substring(0, 50)}..."`);

        // Escape message for shell
        const escapedMsg = message.replace(/"/g, '\\"');
        const output = await this.execGit(`commit -m "${escapedMsg}"`);

        // Parse output: [branch hash] message
        // X files changed, Y insertions(+), Z deletions(-)
        const hashMatch = output.match(/\[.+?\s+([a-f0-9]{7,})\]/);
        const hash = hashMatch ? hashMatch[1] : '';

        const statsMatch = output.match(/(\d+) files? changed(?:, (\d+) insertions?\(\+\))?(?:, (\d+) deletions?\(-\))?/);
        const filesChanged = statsMatch ? parseInt(statsMatch[1], 10) : 0;
        const insertions = statsMatch?.[2] ? parseInt(statsMatch[2], 10) : 0;
        const deletions = statsMatch?.[3] ? parseInt(statsMatch[3], 10) : 0;

        const result: GitCommitResult = {
            hash,
            message,
            filesChanged,
            insertions,
            deletions,
        };

        logInfo('GitManager', `Committed: ${hash} — ${filesChanged} files, +${insertions}/-${deletions}`);
        return result;
    }

    /**
     * Push current branch to remote.
     */
    async push(remote = 'origin', branch?: string): Promise<GitPushResult> {
        const currentBranch = branch || (await this.execGit('rev-parse --abbrev-ref HEAD'));
        logInfo('GitManager', `Pushing ${currentBranch} to ${remote}...`);

        try {
            const output = await this.execGit(`push ${remote} ${currentBranch}`);
            logInfo('GitManager', `Push successful: ${currentBranch} → ${remote}`);

            return {
                success: true,
                branch: currentBranch,
                remote,
                message: output || 'Push completed',
            };
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            logError('GitManager', `Push failed: ${msg}`);
            return {
                success: false,
                branch: currentBranch,
                remote,
                message: msg,
            };
        }
    }

    /**
     * List all branches (local and remote).
     */
    async listBranches(includeRemote = false): Promise<GitBranchInfo[]> {
        logInfo('GitManager', `Listing branches${includeRemote ? ' (including remote)' : ''}...`);

        const command = includeRemote ? 'branch -a -vv' : 'branch -vv';
        const output = await this.execGit(command);
        const lines = output.split('\n').filter(l => l.trim());

        const branches: GitBranchInfo[] = [];

        for (const line of lines) {
            const isCurrent = line.startsWith('*');
            const cleaned = line.replace(/^\*?\s+/, '');
            const parts = cleaned.split(/\s+/);

            if (parts.length < 2) continue;

            let name = parts[0];
            const lastCommit = parts[1];

            // Skip remote HEAD pointers
            if (name.includes('HEAD ->')) continue;

            // Parse remote tracking info [remote/branch]
            let remote: string | undefined;
            const remoteMatch = cleaned.match(/\[(.+?)\]/);
            if (remoteMatch) {
                remote = remoteMatch[1];
            }

            // If this is a remote branch (remotes/origin/...)
            if (name.startsWith('remotes/')) {
                name = name.replace('remotes/', '');
            }

            branches.push({
                name,
                current: isCurrent,
                remote,
                lastCommit,
            });
        }

        logInfo('GitManager', `Found ${branches.length} branches`);
        return branches;
    }

    /**
     * Create a new branch.
     */
    async createBranch(branchName: string, checkout = false): Promise<void> {
        logInfo('GitManager', `Creating branch: ${branchName}${checkout ? ' (checkout)' : ''}...`);

        const command = checkout ? `checkout -b ${branchName}` : `branch ${branchName}`;
        await this.execGit(command);

        logInfo('GitManager', `Branch created: ${branchName}`);
    }

    /**
     * Checkout an existing branch.
     */
    async checkoutBranch(branchName: string): Promise<void> {
        logInfo('GitManager', `Checking out branch: ${branchName}...`);
        await this.execGit(`checkout ${branchName}`);
        logInfo('GitManager', `Checked out: ${branchName}`);
    }

    /**
     * Delete a branch (local only).
     */
    async deleteBranch(branchName: string, force = false): Promise<void> {
        logInfo('GitManager', `Deleting branch: ${branchName}${force ? ' (force)' : ''}...`);
        const flag = force ? '-D' : '-d';
        await this.execGit(`branch ${flag} ${branchName}`);
        logInfo('GitManager', `Branch deleted: ${branchName}`);
    }

    /**
     * Get recent commit log.
     */
    async getLog(limit = 10): Promise<GitLogEntry[]> {
        logInfo('GitManager', `Getting last ${limit} commits...`);

        const format = '%H|%an|%ad|%s'; // hash|author|date|subject
        const output = await this.execGit(`log -${limit} --pretty=format:"${format}" --date=short`);
        const lines = output.split('\n').filter(l => l.trim());

        const entries: GitLogEntry[] = [];

        for (const line of lines) {
            const parts = line.split('|');
            if (parts.length < 4) continue;

            entries.push({
                hash: parts[0].substring(0, 8), // Short hash
                author: parts[1],
                date: parts[2],
                message: parts[3],
            });
        }

        logInfo('GitManager', `Retrieved ${entries.length} commits`);
        return entries;
    }

    /**
     * Fetch from remote (update remote tracking branches).
     */
    async fetch(remote = 'origin'): Promise<void> {
        logInfo('GitManager', `Fetching from ${remote}...`);
        await this.execGit(`fetch ${remote}`);
        logInfo('GitManager', `Fetch completed: ${remote}`);
    }

    /**
     * Pull from remote (fetch + merge).
     */
    async pull(remote = 'origin', branch?: string): Promise<void> {
        const currentBranch = branch || (await this.execGit('rev-parse --abbrev-ref HEAD'));
        logInfo('GitManager', `Pulling ${currentBranch} from ${remote}...`);
        await this.execGit(`pull ${remote} ${currentBranch}`);
        logInfo('GitManager', `Pull completed: ${currentBranch} ← ${remote}`);
    }
}

// ==================== Singleton ====================

let gitManager: GitManager | null = null;

export function getGitManager(workspaceRoot?: string): GitManager {
    if (!gitManager) {
        if (!workspaceRoot) {
            throw new Error('GitManager not initialized. Provide workspaceRoot on first call.');
        }
        gitManager = new GitManager(workspaceRoot);
    }
    return gitManager;
}

/**
 * Guardrails Middleware: Agent output validáció Zod schemákkal.
 * Track: guardrails_evaluation_20260323 — Phase 1
 *
 * Soft-fail by default: validáció hiba → logWarn + eredeti eredmény továbbítás.
 * GUARDRAILS_STRICT=true → error ha validáció nem sikerül.
 */
import { ZodSchema, ZodError } from 'zod';
import { logWarn, logInfo } from '../../utils/logger.js';
import { AgentResponseSchema, AgentResultSchema } from '../schemas/agentOutput.js';
import type { AgentResponse } from '../types.js';
import type { AgentResult } from '../BaseAgent.js';

export interface ValidationResult<T> {
  valid: boolean;
  data: T;
  errors?: string[];
}

const STRICT_MODE = () => process.env.GUARDRAILS_STRICT === 'true';

/**
 * Validálja az agent eredményét a megadott Zod schema ellen.
 * Soft-fail: logol és visszaadja az eredetit. Strict: Error-t dob.
 */
export function validateWithSchema<T>(
  data: unknown,
  schema: ZodSchema<T>,
  context: string,
): ValidationResult<T> {
  const result = schema.safeParse(data);

  if (result.success) {
    return { valid: true, data: result.data };
  }

  const errors = formatZodErrors(result.error);
  logWarn('Guardrails', `[${context}] Validáció hiba: ${errors.join('; ')}`);

  if (STRICT_MODE()) {
    throw new GuardrailsValidationError(context, errors);
  }

  return { valid: false, data: data as T, errors };
}

/** AgentResult validáció (BaseAgent.executeTask() output) */
export function validateAgentResult(result: unknown, agentName: string): ValidationResult<AgentResult> {
  return validateWithSchema(result, AgentResultSchema, `${agentName}:AgentResult`);
}

/** AgentResponse validáció (BaseAgent.execute() output) */
export function validateAgentResponse(response: unknown, agentName: string): ValidationResult<AgentResponse> {
  return validateWithSchema(response, AgentResponseSchema, `${agentName}:AgentResponse`);
}

function formatZodErrors(error: ZodError): string[] {
  return error.issues.map(issue => {
    const path = issue.path.length > 0 ? issue.path.join('.') : 'root';
    return `${path}: ${issue.message}`;
  });
}

export class GuardrailsValidationError extends Error {
  public readonly context: string;
  public readonly validationErrors: string[];

  constructor(context: string, errors: string[]) {
    super(`Guardrails validáció hiba [${context}]: ${errors.join('; ')}`);
    this.name = 'GuardrailsValidationError';
    this.context = context;
    this.validationErrors = errors;
  }
}

#!/usr/bin/env node
/**
 * Brunella Edge CLI - Cloudflare Worker Integration
 *
 * Használat:
 *   brunella edge submit "Generate code for user auth"
 *   brunella edge status <taskId>
 *   brunella edge health
 */

import { Command } from 'commander';
import chalk from 'chalk';
import ora from 'ora';

const program = new Command();

const WORKER_URL = process.env.CLOUDFLARE_WORKER_URL || 'https://bas-orchestrator.iam-dd1.workers.dev';

program
  .name('brunella-edge')
  .description('Cloudflare Worker Edge Integration CLI')
  .version('1.0.0');

// Health Check
program
  .command('health')
  .description('Check Cloudflare Worker health')
  .action(async () => {
    const spinner = ora('Checking worker health...').start();

    try {
      const response = await fetch(WORKER_URL);
      const data = await response.json();

      spinner.stop();
      console.log(chalk.bold.green('\n✅ Worker Status: ONLINE\n'));
      console.log(chalk.cyan('Service:'), data.service);
      console.log(chalk.cyan('Version:'), data.version);
      console.log(chalk.cyan('Architecture:'), data.architecture);
      console.log(chalk.cyan('Status:'), data.status);

      console.log(chalk.bold('\nAvailable Endpoints:'));
      Object.entries(data.endpoints).forEach(([key, value]) => {
        console.log(chalk.gray(`  ${key}:`), value);
      });
    } catch (error: any) {
      spinner.fail(chalk.red('Worker offline or unreachable'));
      console.error(chalk.red('Error:'), error.message);
      process.exit(1);
    }
  });

// Submit Task
program
  .command('submit <instruction>')
  .description('Submit a task to Cloudflare Worker (AI auto-routing)')
  .option('--context <json>', 'Context as JSON string')
  .action(async (instruction: string, options: { context?: string }) => {
    const spinner = ora('Submitting task to edge...').start();

    try {
      const payload: any = {
        instruction,
        context: options.context ? JSON.parse(options.context) : {}
      };

      const response = await fetch(`${WORKER_URL}/task`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      });

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      spinner.stop();
      console.log(chalk.bold.green('\n✅ Task Submitted!\n'));
      console.log(chalk.cyan('Task ID:'), data.taskId);
      console.log(chalk.cyan('Type:'), data.type);
      console.log(chalk.cyan('Status:'), data.message);

      console.log(chalk.gray('\nCheck status with:'));
      console.log(chalk.yellow(`  brunella edge status ${data.taskId}`));
    } catch (error: any) {
      spinner.fail(chalk.red('Task submission failed'));
      console.error(chalk.red('Error:'), error.message);
      process.exit(1);
    }
  });

// Get Task Status
program
  .command('status <taskId>')
  .description('Get task status from Cloudflare KV')
  .action(async (taskId: string) => {
    const spinner = ora('Fetching task status...').start();

    try {
      const response = await fetch(`${WORKER_URL}/status/${taskId}`);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const data = await response.json();

      spinner.stop();
      console.log(chalk.bold('\n📊 Task Status\n'));
      console.log(chalk.cyan('Task ID:'), data.taskId);
      console.log(chalk.cyan('Type:'), data.type);
      console.log(chalk.cyan('Status:'), data.status);

      if (data.result) {
        console.log(chalk.bold('\nResult:'));
        console.log(JSON.stringify(data.result, null, 2));
      }
    } catch (error: any) {
      spinner.fail(chalk.red('Failed to fetch status'));
      console.error(chalk.red('Error:'), error.message);
      process.exit(1);
    }
  });

program.parse();

#!/usr/bin/env node
// FILE: src/cli-jules-interactive.ts
// PURPOSE: Interaktív Jules menü - slash commands + választható opciók

import inquirer from 'inquirer';
import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const REPO_ROOT = path.resolve(__dirname, '..');

interface JulesSession {
    session_id: string;
    prompt: string;
    branch?: string;
    created_at: string;
    status: 'running' | 'completed' | 'failed';
}

interface JulesBranch {
    name: string;
    commits: number;
}

// ====== HELPERS ======

function log(message: string, type: 'info' | 'success' | 'error' | 'warn' = 'info') {
    const icons = {
        info: '📋',
        success: '✅',
        error: '❌',
        warn: '⚠️'
    };
    console.log(`${icons[type]} ${message}`);
}

function runCommand(cmd: string): string {
    try {
        return execSync(cmd, { cwd: REPO_ROOT, encoding: 'utf-8' });
    } catch (e: any) {
        return '';
    }
}

function loadJulesSessions(): JulesSession[] {
    const sessionsFile = path.join(REPO_ROOT, '.jules', 'sessions.json');
    if (!fs.existsSync(sessionsFile)) {
        return [];
    }
    return JSON.parse(fs.readFileSync(sessionsFile, 'utf-8'));
}

function getJulesBranches(): JulesBranch[] {
    const output = runCommand('git branch -r');
    const branches: JulesBranch[] = [];

    for (const line of output.split('\n')) {
        const trimmed = line.trim();
        if (trimmed.includes('jules-') || trimmed.includes('robotkez-')) {
            const branchName = trimmed.replace('origin/', '');

            // Get commit count ahead of main
            const commitsAhead = runCommand(`git rev-list --count main..origin/${branchName}`).trim();
            const commits = parseInt(commitsAhead) || 0;

            branches.push({ name: branchName, commits });
        }
    }

    return branches;
}

// ====== JULES COMMANDS ======

async function julesNew() {
    console.clear();
    log('🤖 Új Jules Task', 'info');
    console.log('');

    const answers = await inquirer.prompt([
        {
            type: 'list',
            name: 'taskType',
            message: 'Mit szeretnél Jules-nak delegálni?',
            choices: [
                { name: '🐛 Bug fixing', value: 'bug' },
                { name: '✨ Feature implementation', value: 'feature' },
                { name: '🧪 Write tests', value: 'tests' },
                { name: '📦 Dependency update', value: 'deps' },
                { name: '📝 Custom prompt', value: 'custom' }
            ]
        }
    ]);

    let prompt = '';

    if (answers.taskType === 'custom') {
        const customAnswer = await inquirer.prompt([
            {
                type: 'input',
                name: 'prompt',
                message: 'Add meg a task leírását:',
                validate: (input: string) => input.length > 0 || 'A prompt nem lehet üres!'
            }
        ]);
        prompt = customAnswer.prompt;
    } else {
        // Pre-defined prompts
        const templates: Record<string, string> = {
            bug: 'Fix all linting errors and type issues in the codebase',
            feature: 'Implement the feature described in the latest GitHub issue',
            tests: 'Write comprehensive tests for all scripts/robotkez_*.py files',
            deps: 'Update all npm and Python dependencies to latest stable versions'
        };
        prompt = templates[answers.taskType];

        const confirmAnswer = await inquirer.prompt([
            {
                type: 'confirm',
                name: 'useTemplate',
                message: `Használod ezt a promptot?\n   "${prompt}"`,
                default: true
            }
        ]);

        if (!confirmAnswer.useTemplate) {
            const customAnswer = await inquirer.prompt([
                {
                    type: 'input',
                    name: 'prompt',
                    message: 'Add meg a saját promptot:',
                    default: prompt
                }
            ]);
            prompt = customAnswer.prompt;
        }
    }

    // API vagy CLI?
    const methodAnswer = await inquirer.prompt([
        {
            type: 'list',
            name: 'method',
            message: 'Jules trigger metódus:',
            choices: [
                { name: '🔌 REST API (ajánlott)', value: 'api' },
                { name: '💻 CLI (natív jules command)', value: 'cli' }
            ],
            default: 'api'
        }
    ]);

    console.log('');
    log('🚀 Jules task indítása...', 'info');

    try {
        let sessionId = '';

        if (methodAnswer.method === 'api') {
            // Python API client
            const output = runCommand(`python scripts/jules_api_client.py create "${prompt}"`);
            console.log(output);

            // Parse session ID
            const match = output.match(/ID: (\d+)/);
            if (match) {
                sessionId = match[1];
            }
        } else {
            // Jules CLI
            const output = runCommand(`python scripts/jules_cli_wrapper.py new "${prompt}"`);
            console.log(output);

            // Parse session ID
            const match = output.match(/Session ID: (\S+)/);
            if (match) {
                sessionId = match[1];
            }
        }

        if (sessionId) {
            log(`Session létrehozva: ${sessionId}`, 'success');

            // Watch?
            const watchAnswer = await inquirer.prompt([
                {
                    type: 'confirm',
                    name: 'watch',
                    message: 'Watch mode indítása? (vár amíg kész)',
                    default: false
                }
            ]);

            if (watchAnswer.watch) {
                console.log('');
                log('⏳ Watch mode - várakozás a session befejezésére...', 'info');
                if (methodAnswer.method === 'api') {
                    runCommand(`python scripts/jules_api_client.py watch ${sessionId}`);
                } else {
                    runCommand(`python scripts/jules_cli_wrapper.py watch ${sessionId}`);
                }
            }
        }
    } catch (e: any) {
        log(`Hiba: ${e.message}`, 'error');
    }

    await mainMenu();
}

async function julesSync() {
    console.clear();
    log('🔄 Jules Sync - GitHub branch-ek pullolása', 'info');
    console.log('');

    log('Ellenőrzés...', 'info');
    const branches = getJulesBranches();

    if (branches.length === 0) {
        log('Nincs Jules branch a GitHub-on.', 'warn');
        await mainMenu();
        return;
    }

    console.log('');
    log(`${branches.length} Jules branch találva:`, 'success');
    branches.forEach((b, i) => {
        console.log(`  ${i + 1}. ${b.name} (${b.commits} új commit)`);
    });
    console.log('');

    const answer = await inquirer.prompt([
        {
            type: 'list',
            name: 'action',
            message: 'Mit szeretnél csinálni?',
            choices: [
                { name: '📥 Pull all (összes branch)', value: 'pull_all' },
                { name: '🔍 Review specific branch', value: 'review' },
                { name: '🔀 Merge specific branch', value: 'merge' },
                { name: '🔙 Vissza', value: 'back' }
            ]
        }
    ]);

    if (answer.action === 'back') {
        await mainMenu();
        return;
    }

    if (answer.action === 'pull_all') {
        log('Pullolás...', 'info');
        runCommand('python scripts/jules_sync_watchdog.py --once');
        log('Kész!', 'success');
    } else if (answer.action === 'review' || answer.action === 'merge') {
        const branchAnswer = await inquirer.prompt([
            {
                type: 'list',
                name: 'branch',
                message: 'Melyik branch?',
                choices: branches.map(b => ({
                    name: `${b.name} (${b.commits} commits)`,
                    value: b.name
                }))
            }
        ]);

        const selectedBranch = branchAnswer.branch;

        if (answer.action === 'review') {
            console.log('');
            log(`Review: ${selectedBranch}`, 'info');
            console.log('');
            runCommand(`git log origin/${selectedBranch} -5 --oneline --stat`);
        } else {
            // Merge
            const confirmAnswer = await inquirer.prompt([
                {
                    type: 'confirm',
                    name: 'confirm',
                    message: `Biztos merge-elni szeretnéd: ${selectedBranch}?`,
                    default: false
                }
            ]);

            if (confirmAnswer.confirm) {
                log('Merge...', 'info');
                runCommand(`git fetch origin && git merge origin/${selectedBranch} --no-edit`);
                log('Merge kész!', 'success');
            }
        }
    }

    console.log('');
    await mainMenu();
}

async function julesStatus() {
    console.clear();
    log('📊 Jules Status', 'info');
    console.log('');

    // Sessions (helyi)
    const sessions = loadJulesSessions();
    if (sessions.length > 0) {
        log(`Helyi sessions (${sessions.length}):`, 'info');
        sessions.slice(-5).forEach((s, i) => {
            const statusIcon = s.status === 'completed' ? '✅' : s.status === 'running' ? '⏳' : '❌';
            console.log(`  ${statusIcon} ${s.session_id}`);
            console.log(`     ${s.prompt.slice(0, 60)}...`);
        });
        console.log('');
    }

    // GitHub branches
    const branches = getJulesBranches();
    if (branches.length > 0) {
        log(`GitHub Jules branches (${branches.length}):`, 'info');
        branches.forEach((b, i) => {
            console.log(`  ${i + 1}. ${b.name} (${b.commits} commits)`);
        });
        console.log('');
    }

    // API sessions (opcionális)
    const apiAnswer = await inquirer.prompt([
        {
            type: 'confirm',
            name: 'showApi',
            message: 'Lekérdezzem a Jules API sessions-t is?',
            default: false
        }
    ]);

    if (apiAnswer.showApi) {
        console.log('');
        log('API sessions lekérdezése...', 'info');
        runCommand('python scripts/jules_api_client.py list 10');
    }

    console.log('');
    await mainMenu();
}

async function julesHelp() {
    console.clear();
    log('📖 Jules Help', 'info');
    console.log('');
    console.log('Elérhető parancsok:');
    console.log('');
    console.log('  /jules new      - Új Jules task létrehozás');
    console.log('  /jules sync     - GitHub Jules branch-ek pullolása');
    console.log('  /jules status   - Jules sessions és branch-ek státusza');
    console.log('  /jules help     - Ez a súgó');
    console.log('  /exit           - Kilépés');
    console.log('');
    console.log('Interaktív használat:');
    console.log('  1. Indítsd: node build/cli-jules-interactive.js');
