import { Command } from 'commander';
import chalk from 'chalk';
import ora from 'ora';

const API_BASE = process.env.BRUNELLA_API_URL || 'http://localhost:3000';

type SessionMode = 'observe' | 'guide' | 'auto';
type EnginePreference = 'auto' | 'chrome-acp' | 'robotkez';

async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const response = await fetch(`${API_BASE}/api/v1/browser-copilot${path}`, {
    headers: { 'Content-Type': 'application/json' },
    ...options,
  });
  const text = await response.text();
  const data = text ? JSON.parse(text) as T : {} as T;
  if (!response.ok) {
    const errorRecord = typeof data === 'object' && data !== null ? data as Record<string, unknown> : undefined;
    const message = typeof errorRecord?.error === 'string' ? errorRecord.error : `HTTP ${response.status}`;
    throw new Error(message);
  }
  return data;
}

function printSession(session: Record<string, unknown>) {
  console.log(chalk.bold.cyan('\n🧭 Browser Copilot session\n'));
  console.log(`Állapot: ${chalk.green(String(session.status ?? 'n/a'))}`);
  console.log(`Mód: ${chalk.yellow(String(session.mode ?? 'n/a'))}`);
  console.log(`Viewport: ${chalk.magenta(String(session.viewportEngine ?? 'n/a'))}`);
  console.log(`Action engine: ${chalk.blue(String(session.actionEngine ?? 'n/a'))}`);
  console.log(`Chrome ACP: ${session.chromeAcpReachable ? chalk.green('elérhető') : chalk.gray('offline')}`);
  console.log(`Paused: ${session.paused ? chalk.red('igen') : chalk.green('nem')}`);
  if (typeof session.currentInstruction === 'string' && session.currentInstruction) {
    console.log(`Aktuális instrukció: ${session.currentInstruction}`);
  }
  if (typeof session.pendingInstruction === 'string' && session.pendingInstruction) {
    console.log(`Pending guide: ${session.pendingInstruction}`);
  }
}

export function registerBrowserCopilotCommands(program: Command) {
  const root = program
    .command('browser-copilot')
    .alias('bc')
    .description('Chrome ACP + Robotkéz élő session coordinator kezelése');

  root
    .command('status')
    .description('A Browser Copilot session aktuális állapota')
    .action(async () => {
      const spinner = ora('Browser Copilot session lekérdezése...').start();
      try {
        const result = await apiFetch<{ success: boolean; session: Record<string, unknown> }>('/session');
        spinner.succeed('Session betöltve');
        printSession(result.session);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        spinner.fail(message);
        process.exit(1);
      }
    });

  root
    .command('send')
    .argument('<instruction>', 'Magyar nyelvű browser copilot instrukció')
    .description('Instrukció küldése a közös Browser Copilot sessionnek')
    .action(async (instruction: string) => {
      const spinner = ora('Instrukció küldése...').start();
      try {
        const result = await apiFetch<{ success: boolean; session: Record<string, unknown> }>('/message', {
          method: 'POST',
          body: JSON.stringify({ instruction }),
        });
        spinner.succeed('Instrukció feldolgozva');
        printSession(result.session);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        spinner.fail(message);
        process.exit(1);
      }
    });

  root
    .command('confirm')
    .description('Guide módban függő terv megerősítése és végrehajtása')
    .action(async () => {
      const spinner = ora('Guide feladat megerősítése...').start();
      try {
        const result = await apiFetch<{ success: boolean; session: Record<string, unknown> }>('/confirm', { method: 'POST' });
        spinner.succeed('Guide feladat kezelve');
        printSession(result.session);
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        spinner.fail(message);
        process.exit(1);
      }
    });

  root
    .command('pause')
    .description('Session szüneteltetése')
    .action(async () => {
      const result = await apiFetch<{ success: boolean; session: Record<string, unknown> }>('/pause', { method: 'POST' });
      printSession(result.session);
    });

  root
    .command('resume')
    .description('Session folytatása')
    .action(async () => {
      const result = await apiFetch<{ success: boolean; session: Record<string, unknown> }>('/resume', { method: 'POST' });
      printSession(result.session);
    });

  root
    .command('reset')
    .description('Új Browser Copilot session indítása')
    .action(async () => {
      const result = await apiFetch<{ success: boolean; session: Record<string, unknown> }>('/reset', { method: 'POST' });
      printSession(result.session);
    });

  root
    .command('configure')
    .description('Browser Copilot mód és viewport preference beállítása')
    .requiredOption('--mode <mode>', 'observe | guide | auto')
    .requiredOption('--engine <engine>', 'auto | chrome-acp | robotkez')
    .option('--overlay <overlay>', 'true | false', 'true')
    .action(async (options: { mode: SessionMode; engine: EnginePreference; overlay: string }) => {
      const overlayEnabled = options.overlay !== 'false';
      const result = await apiFetch<{ success: boolean; session: Record<string, unknown> }>('/session/configure', {
        method: 'POST',
        body: JSON.stringify({
          mode: options.mode,
          enginePreference: options.engine,
          overlayEnabled,
        }),
      });
      printSession(result.session);
    });
}

import { spawn, spawnSync } from 'child_process';
import { existsSync } from 'fs';
import { resolve } from 'path';
import { Command } from 'commander';
import chalk from 'chalk';
import inquirer from 'inquirer';

const ACP_URL = 'http://localhost:9315';
const INSTALL_ARGS = ['install', '-g', '@chrome-acp/proxy-server', '@anthropic-ai/claude-code', '@zed-industries/claude-code-acp'];
const INSTALL_COMMAND = `npm ${INSTALL_ARGS.join(' ')}`;
const WINDOWS_START_SCRIPT = resolve(process.cwd(), 'scripts', 'start-chrome-acp.bat');

interface ChromeAcpDoctorReport {
  proxyInstalled: boolean;
  adapterInstalled: boolean;
  claudeInstalled: boolean;
  startScriptExists: boolean;
  uiReachable: boolean;
  adapterEntryPoint?: string;
}

function hasBinary(binaryName: string): boolean {
  const locator = process.platform === 'win32' ? 'where' : 'which';
  const result = spawnSync(locator, [binaryName], {
    stdio: 'ignore',
    shell: false,
  });

  return result.status === 0;
}

async function isChromeAcpReachable(): Promise<boolean> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 1500);

  try {
    const response = await fetch(ACP_URL, { signal: controller.signal });
    return response.status < 500;
  } catch {
    return false;
  } finally {
    clearTimeout(timeout);
  }
}

async function collectDoctorReport(): Promise<ChromeAcpDoctorReport> {
  const npmPrefix = spawnSync('npm', ['prefix', '-g'], {
    encoding: 'utf-8',
    shell: process.platform === 'win32',
  });

  const prefix = npmPrefix.status === 0 ? npmPrefix.stdout.trim() : '';
  const adapterEntryPoint = prefix
    ? resolve(prefix, 'node_modules', '@zed-industries', 'claude-code-acp', 'dist', 'index.js')
    : undefined;

  return {
    proxyInstalled: hasBinary('acp-proxy'),
    adapterInstalled: Boolean(adapterEntryPoint && existsSync(adapterEntryPoint)),
    claudeInstalled: hasBinary('claude'),
    startScriptExists: existsSync(WINDOWS_START_SCRIPT),
    uiReachable: await isChromeAcpReachable(),
    adapterEntryPoint,
  };
}

function printDoctorReport(report: ChromeAcpDoctorReport): void {
  console.log(chalk.bold.cyan('\n🌐 Chrome ACP állapot\n'));
  console.log(`  acp-proxy:       ${report.proxyInstalled ? chalk.green('OK') : chalk.red('HIÁNYZIK')}`);
  console.log(`  claude-code-acp: ${report.adapterInstalled ? chalk.green('OK') : chalk.red('HIÁNYZIK')}`);
  console.log(`  claude:          ${report.claudeInstalled ? chalk.green('OK') : chalk.yellow('nem található')}`);
  console.log(`  start script:    ${report.startScriptExists ? chalk.green('OK') : chalk.red('HIÁNYZIK')}`);
  console.log(`  UI (${ACP_URL}): ${report.uiReachable ? chalk.green('ELÉRHETŐ') : chalk.yellow('nem elérhető')}`);
  if (report.adapterEntryPoint) {
    console.log(chalk.gray(`  adapter entry:   ${report.adapterEntryPoint}`));
  }

  if (!report.proxyInstalled || !report.adapterInstalled) {
    console.log(chalk.yellow('\nTelepítés szükséges:'));
    console.log(chalk.gray(`  ${INSTALL_COMMAND}`));
  }

  if (!report.uiReachable) {
    console.log(chalk.gray('\nIndítás után nyisd meg: http://localhost:9315'));
  }
}

function startChromeAcp(): void {
  if (process.platform !== 'win32') {
    console.log(chalk.yellow('Automatikus start jelenleg Windows scriptre van előkészítve.'));
    console.log(chalk.gray('Futtasd kézzel: acp-proxy --no-auth claude-code-acp'));
    return;
  }

  if (!existsSync(WINDOWS_START_SCRIPT)) {
    console.log(chalk.red(`Hiányzó start script: ${WINDOWS_START_SCRIPT}`));
    return;
  }

  const child = spawn('cmd', ['/c', 'start', '', WINDOWS_START_SCRIPT], {
    detached: true,
    stdio: 'ignore',
    windowsHide: false,
  });
  child.unref();

  console.log(chalk.green('Chrome ACP indítás elindítva külön ablakban.'));
  console.log(chalk.gray(`UI: ${ACP_URL}`));
}

function runInstall(): void {
  console.log(chalk.cyan('Chrome ACP csomagok globális telepítése...'));
  const result = spawnSync('npm', INSTALL_ARGS, {
    stdio: 'inherit',
    shell: process.platform === 'win32',
  });

  if (result.status !== 0) {
    console.log(chalk.red('A globális telepítés hibával állt le.'));
    return;
  }

  console.log(chalk.green('Globális Chrome ACP telepítés kész.'));
}

export function registerChromeAcpCommands(program: Command): void {
  const chromeAcp = program
    .command('chrome-acp')
    .description('Chrome ACP lokális proxy és dashboard integráció kezelése');

  const runDoctor = async (): Promise<void> => {
    printDoctorReport(await collectDoctorReport());
  };

  chromeAcp
    .command('doctor')
    .description('Binárisok, start script és localhost UI ellenőrzése')
    .action(async () => {
      await runDoctor();
    });

  chromeAcp
    .command('status')
    .description('Gyors állapotlekérdezés a Chrome ACP UI-ról')
    .action(async () => {
      const reachable = await isChromeAcpReachable();
      console.log(reachable ? chalk.green(`Chrome ACP elérhető: ${ACP_URL}`) : chalk.yellow(`Chrome ACP nem érhető el: ${ACP_URL}`));
    });

  chromeAcp
    .command('start')
    .description('A Windows start script segítségével elindítja a Chrome ACP proxyt')
    .action(() => {
      startChromeAcp();
    });

  chromeAcp
    .command('install')
    .description('Megmutatja vagy lefuttatja a szükséges globális npm telepítést')
    .option('--run', 'Azonnal lefuttatja a globális npm install parancsot')
    .action((options: { run?: boolean }) => {
      if (options.run) {
        runInstall();
        return;
      }

      console.log(chalk.bold.cyan('\nChrome ACP telepítés\n'));
      console.log(chalk.gray(INSTALL_COMMAND));
    });

  chromeAcp.action(async () => {
    const { action } = await inquirer.prompt<{ action: string }>([
      {
        type: 'list',
        name: 'action',
        message: 'Chrome ACP művelet kiválasztása',
        choices: [
          { name: '🩺 Doctor — binárisok és localhost ellenőrzése', value: 'doctor' },
          { name: '▶ Start — proxy indítása külön ablakban', value: 'start' },
          { name: '📦 Install — globális npm parancs megjelenítése', value: 'install' },
          { name: '🌍 Status — UI elérhetőség ellenőrzése', value: 'status' },
          { name: '❌ Kilépés', value: 'cancel' },
        ],
      },
    ]);

    switch (action) {
      case 'doctor':
        await runDoctor();
        return;
      case 'start':
        startChromeAcp();
        return;
      case 'install':
        console.log(chalk.gray(INSTALL_COMMAND));
        return;
      case 'status':
        console.log((await isChromeAcpReachable()) ? chalk.green(`Chrome ACP elérhető: ${ACP_URL}`) : chalk.yellow(`Chrome ACP nem érhető el: ${ACP_URL}`));
        return;
      default:
        console.log(chalk.gray('Chrome ACP művelet megszakítva.'));
    }
  });
}

