export function registerConductorCommands(conductorCmd: Command): void {
  // brunella conductor rescan
  conductorCmd
    .command('rescan')
    .description('Rescan all tracks (active + archived) and update project_state.json')
    .option('--watch', 'Start file watcher after sync')
    .action(async (options) => {
      console.log(chalk.blue('🔄 Track State Manager - Full Sync\n'));

      try {
        console.log(chalk.gray('Scanning conductor/tracks/ and conductor/archive/...\n'));

        await trackStateManager.fullSync();

        const state = trackStateManager.getState();

        console.log(chalk.green('✅ Sync complete!\n'));
        console.log(chalk.white('📊 Statistics:'));
        console.log(chalk.white(`  Total tracks: ${state.stats.total}`));
        console.log(chalk.cyan(`  Active: ${state.stats.active}`));
        console.log(chalk.yellow(`  Proposed: ${state.stats.proposed}`));
        console.log(chalk.green(`  Completed: ${state.stats.completed}`));
        console.log(chalk.gray(`  Archived: ${state.stats.archived}`));

        console.log(chalk.white(`\n📁 Files updated:`));
        console.log(chalk.gray(`  conductor/project_state.json`));
        console.log(chalk.gray(`  conductor/tracks.md`));

        if (options.watch) {
          console.log(chalk.blue('\n👀 Starting file watcher (realtime sync)...'));
          trackStateManager.startWatcher();
          console.log(chalk.green('✅ File watcher active. Press Ctrl+C to stop.'));
          // Keep process alive
          await new Promise(() => {});
        }
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        console.error(chalk.red(`❌ Sync failed: ${msg}`));
        process.exit(1);
      }
    });

  // brunella conductor state (renamed to avoid conflict)
  conductorCmd
    .command('state')
    .description('Show current project status (tracks summary)')
    .action(async () => {
      console.log(chalk.blue('📊 Project Status Report\n'));

      const state = trackStateManager.getState();

      console.log(chalk.white(`Last Updated: ${state.lastUpdated}\n`));

      console.log(chalk.cyan('🚀 Active Tracks:'));
      const active = state.tracks.filter(t => t.status === 'active');
      if (active.length === 0) {
        console.log(chalk.gray('  (none)'));
      } else {
        active.slice(0, 10).forEach(t => {
          const progressBar = '█'.repeat(Math.floor(t.progress / 10)) + '░'.repeat(10 - Math.floor(t.progress / 10));
          console.log(chalk.white(`  [${progressBar}] ${t.progress}% - ${t.name} (${t.priority})`));
        });
        if (active.length > 10) {
          console.log(chalk.gray(`  ... and ${active.length - 10} more`));
        }
      }

      console.log(chalk.yellow('\n📝 Proposed Tracks:'));
      const proposed = state.tracks.filter(t => t.status === 'proposed');
      if (proposed.length === 0) {
        console.log(chalk.gray('  (none)'));
      } else {
        proposed.slice(0, 5).forEach(t => {
          console.log(chalk.white(`  - ${t.name} (${t.priority})`));
        });
        if (proposed.length > 5) {
          console.log(chalk.gray(`  ... and ${proposed.length - 5} more`));
        }
      }

      console.log(chalk.green('\n✅ Completed (Not Archived):'));
      const completed = state.tracks.filter(t => t.status === 'completed' && !t._isArchived);
      console.log(chalk.white(`  ${completed.length} tracks`));

      console.log(chalk.gray('\n📦 Archived:'));
      console.log(chalk.white(`  ${state.stats.archived} tracks`));

      console.log(chalk.white(`\n📊 Total: ${state.stats.total} tracks`));
    });

  // brunella conductor list
  conductorCmd
    .command('list')
    .description('List all tracks with details')
    .option('-s, --status <status>', 'Filter by status (active|proposed|completed|archived)')
    .option('-p, --priority <priority>', 'Filter by priority (low|medium|high|critical)')
    .action(async (options) => {
      let tracks = trackStateManager.getState().tracks;

      // Filter by status
      if (options.status) {
        tracks = tracks.filter(t => t.status === options.status);
      }

      // Filter by priority
      if (options.priority) {
        tracks = tracks.filter(t => t.priority === options.priority);
      }

      console.log(chalk.blue(`📋 Track List (${tracks.length} tracks)\n`));

      if (tracks.length === 0) {
        console.log(chalk.gray('No tracks found.'));
        return;
      }

      tracks.forEach(t => {
        const statusColor =
          t.status === 'active' ? chalk.cyan :
          t.status === 'completed' ? chalk.green :
          t.status === 'proposed' ? chalk.yellow :
          chalk.gray;

        const priorityBadge =
          t.priority === 'critical' ? chalk.red('[P0]') :
          t.priority === 'high' ? chalk.yellow('[P1]') :
          t.priority === 'medium' ? chalk.blue('[P2]') :
          chalk.gray('[P3]');

        console.log(statusColor(`${t.status.toUpperCase().padEnd(10)} ${priorityBadge} ${t.progress}% - ${t.name}`));
        console.log(chalk.gray(`           ID: ${t.id}`));
        if (t.assignee) {
          console.log(chalk.gray(`           Assignee: ${t.assignee}`));
        }
        console.log('');
      });
    });
}

/**
 * Crawl4AI CLI Commands — Magyar nyelvű web crawling CLI
 *
 * Parancsok:
 *   brunella crawl4ai crawl <url>     — Egyedi URL crawlolása
 *   brunella crawl4ai batch           — Több URL interaktív crawlolása
 *   brunella crawl4ai status          — Crawl4AI szolgáltatás állapota
 */

import { Command } from "commander";
import chalk from "chalk";
import ora from "ora";
import inquirer from "inquirer";

const API_BASE = process.env.BRUNELLA_API_URL || "http://localhost:3000";

async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const url = `${API_BASE}${path}`;
  const response = await fetch(url, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  const text = await response.text();
  if (!text) throw new Error(`Üres válasz: ${path}`);
  return JSON.parse(text) as T;
}

export function registerCrawl4aiCommands(program: Command): void {
  const crawl4ai = program
    .command("crawl4ai")
    .description("🕷️ Intelligens web crawling — Crawl4AI");

  // brunella crawl4ai status
  crawl4ai
    .command("status")
    .alias("állapot")
    .description("Crawl4AI szolgáltatás állapotának ellenőrzése")
    .action(async () => {
      const spinner = ora("Crawl4AI állapot ellenőrzése...").start();
      try {
        const data = await apiFetch<{
          available: boolean;
          python_api: string;
          error?: string;
        }>("/api/v1/crawl4ai/status");

        if (data.available) {
          spinner.succeed(chalk.green("✅ Crawl4AI elérhető"));
          console.log(chalk.dim(`   Python API: ${data.python_api}`));
        } else {
          spinner.warn(chalk.yellow("⚠️  Crawl4AI nem elérhető"));
          console.log(chalk.dim(`   Python API: ${data.python_api}`));
          if (data.error) {
            console.log(chalk.red(`   Hiba: ${data.error}`));
          }
          console.log(chalk.dim("   Indítsd el: cd myai && uvicorn server:app --port 8000"));
        }
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  // brunella crawl4ai crawl <url>
  crawl4ai
    .command("crawl")
    .alias("begyűjt")
    .description("Egyedi URL crawlolása és tartalom kinyerése")
    .argument("[url]", "Crawlolandó URL")
    .option("-s, --selector <selector>", "CSS selector, amire várakozik")
    .option("--schema <json>", "Struktúrált kinyerés JSON séma")
    .action(async (url: string | undefined, options: { selector?: string; schema?: string }) => {
      if (!url) {
        const answers = await inquirer.prompt([
          {
            type: "input",
            name: "url",
            message: "🌐 Crawlolandó URL:",
            validate: (input: string) => input.startsWith("http") || "Érvényes URL-t adj meg (http...)",
          },
        ]);
        url = answers.url;
      }

      const spinner = ora(`Crawling: ${chalk.cyan(url!)}`).start();
      try {
        const body: Record<string, unknown> = { url };
        if (options.selector) body.wait_for_selector = options.selector;
        if (options.schema) body.extract_schema = options.schema;

        const result = await apiFetch<{
          success: boolean;
          data?: { markdown?: string; title?: string; url?: string };
          error?: string;
        }>("/api/v1/crawl4ai/crawl", {
          method: "POST",
          body: JSON.stringify(body),
        });

        if (result.success && result.data) {
          spinner.succeed(chalk.green("✅ Crawl sikeres!"));
          console.log(chalk.blue("\n╔════════════════════════════════════╗"));
          console.log(chalk.blue("║") + chalk.bold("  CRAWL4AI EREDMÉNY                ") + chalk.blue("║"));
          console.log(chalk.blue("╚════════════════════════════════════╝\n"));
          if (result.data.title) {
            console.log(chalk.cyan(`  📄 Cím: ${result.data.title}`));
          }
          console.log(chalk.cyan(`  🔗 URL: ${result.data.url || url}`));
          const markdown = result.data.markdown || "";
          console.log(chalk.cyan(`  📊 Méret: ${markdown.length} karakter\n`));
          // Preview: első 500 karakter
          if (markdown.length > 0) {
            const preview = markdown.substring(0, 500);
            console.log(chalk.dim("  --- Előnézet (első 500 karakter) ---"));
            console.log(chalk.gray(`  ${preview.replace(/\n/g, "\n  ")}...`));
          }
        } else {
          spinner.fail(chalk.red(`Crawl hiba: ${result.error || "Ismeretlen hiba"}`));
        }
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  // brunella crawl4ai batch
  crawl4ai
    .command("batch")
    .alias("csoportos")
    .description("Több URL párhuzamos crawlolása")
    .option("-u, --urls <urls...>", "URL-ek szóközzel elválasztva")
    .action(async (options: { urls?: string[] }) => {
      let urls = options.urls;

      if (!urls || urls.length === 0) {
        const answers = await inquirer.prompt([
          {
            type: "input",
            name: "urls",
            message: "🌐 URL-ek (vesszővel elválasztva):",
            validate: (input: string) => input.length > 5 || "Adj meg legalább egy URL-t",
          },
        ]);
        urls = (answers.urls as string).split(",").map((u: string) => u.trim()).filter(Boolean);
      }

      const spinner = ora(`Batch crawl: ${urls.length} URL...`).start();
      try {
        const result = await apiFetch<{
          success: boolean;
          data?: { results?: Array<{ url: string; status: string }> };
          error?: string;
        }>("/api/v1/crawl4ai/batch", {
          method: "POST",
          body: JSON.stringify({ urls }),
        });

        if (result.success && result.data?.results) {
          spinner.succeed(chalk.green(`✅ Batch crawl kész! ${result.data.results.length} eredmény`));
          result.data.results.forEach((r, i) => {
            const statusColor = r.status === "success" ? chalk.green : chalk.red;
            console.log(`  ${chalk.bold(`#${i + 1}`)} ${statusColor(r.status)} | ${r.url}`);
          });
        } else {
          spinner.fail(chalk.red(`Batch hiba: ${result.error || "Ismeretlen hiba"}`));
        }
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });
}

import { Command } from 'commander';
import { fetchWithTimeout } from '../dashboard/lib/apiService.js';
import { logInfo, logError } from '../utils/logger.js';

// Define the structure of the dashboard status response
interface DashboardStatusResponse {
  status: string;
  components: {
    backendHealth: { status: string; services: any; timestamp: string };
    agents: Array<{ name: string; status: string; description: string; }>;
    mcp: Array<{ name: string; status: string; tools: any[] }>;
    database: { status: string };
    uiRender: { status: string; message: string };
    socket: { status: string; message: string };
  };
  timestamp: string;
  error?: string;
}

export function dashboardCommand(program: Command) {
  const runDashboardStatus = async () => {
    logInfo('CLI', 'Lekérdezem a Dashboard állapotát...');
    try {
      const response = await fetchWithTimeout(`${process.env.API_BASE || 'http://localhost:3000'}/api/dashboard/status`);
      const data: DashboardStatusResponse = await response.json();

      console.log('\n✨ Brunella Dashboard Státusz ✨');
      console.log('---------------------------------');
      console.log(`Összesített állapot: ${data.status}`);
      console.log(`Utolsó frissítés: ${new Date(data.timestamp).toLocaleString()}`);
      console.log('\nKomponensek:');
      console.log(`  Backend Health: ${data.components.backendHealth.status}`);
      console.log(`  Adatbázis: ${data.components.database.status}`);
      console.log(`  UI Render Check: ${data.components.uiRender.status} (${data.components.uiRender.message})`);
      console.log(`  Socket Csatlakozás: ${data.components.socket.status} (${data.components.socket.message})`);

      console.log('\nÜgynökök:');
      if (data.components.agents && data.components.agents.length > 0) {
        data.components.agents.forEach(agent => {
          console.log(`  - ${agent.name}: ${agent.status} (${agent.description.slice(0, 50)}...)`);
        });
      } else {
        console.log('  Nincs regisztrált ügynök.');
      }

      console.log('\nMCP Szerverek:');
      if (data.components.mcp && data.components.mcp.length > 0) {
        data.components.mcp.forEach(server => {
          console.log(`  - ${server.name}: ${server.status} (${server.tools.length} eszköz)`);
        });
      } else {
        console.log('  Nincsenek konfigurált MCP szerverek.');
      }

      if (data.error) {
        logError('CLI', `Hiba: ${data.error}`);
      }

    } catch (e: any) {
      logError('CLI', `Hiba a Dashboard állapotának lekérdezésekor: ${e.message}`);
    }
  };

  const dashboard = program
    .command('dashboard')
    .description('Manage and view dashboard status')
    .action(() => {
      program.help(); // Show subcommands by default
    });

  dashboard
    .command('status')
    .description('Get current status of the Mission Control Dashboard and its components')
    .action(runDashboardStatus);

  // Backward compatibility: allow old `brunella status` usage for now.
  program
    .command('status')
    .description('Alias of `brunella dashboard status`')
    .action(runDashboardStatus);
}

/**
 * Developer CLI Commands (P2)
 *
 * `brunella dev` alparancs-csoport a Developer Agent 3.0-hoz
 *
 * Parancsok:
 *  - brunella dev generate <prompt>    # Kód generálás
 *  - brunella dev test <file>          # Teszt generálás
 *  - brunella dev fix [--auto]         # Hiba javítás
 *  - brunella dev heal                 # Self-heal futtatás
 *  - brunella dev review <file>        # Kód review (Fázis 2)
 *  - brunella dev status               # Pipeline állapot
 *  - brunella dev history              # Feladat történet
 */

import { Command } from 'commander';
import chalk from 'chalk';
import ora from 'ora';
import inquirer from 'inquirer';
import { BrunellaClient } from '../utils/mcpClient.js';
import { logInfo, logError } from '../utils/logger.js';

const API_BASE = process.env.BRUNELLA_API_URL || 'http://localhost:3000';

/**
 * Simple fetch helper for CLI → REST API calls
 */
async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
    const url = `${API_BASE}/api/v1/developer${path}`;
    const response = await fetch(url, {
        headers: { 'Content-Type': 'application/json' },
        ...options,
    });

    const text = await response.text();
    if (!text) throw new Error(`Empty response from ${path}`);

    const data = JSON.parse(text) as T;

    if (!response.ok) {
        throw new Error((data as Record<string, string>).error || `HTTP ${response.status}`);
    }

    return data;
}

/**
 * Execute a developer task via the REST API
 */
async function executeDevTask(task: string, context?: Record<string, unknown>): Promise<{ taskId: string; status: string }> {
    return apiFetch('/execute', {
        method: 'POST',
        body: JSON.stringify({ task, context }),
    });
}

/**
 * Poll pipeline status until done or error
 */
async function pollPipeline(taskId: string, spinner: ReturnType<typeof ora>): Promise<void> {
    const maxAttempts = 120; // 2 minute timeout at 1s intervals
    for (let i = 0; i < maxAttempts; i++) {
        await new Promise(resolve => setTimeout(resolve, 1000));

        try {
            const result = await apiFetch<{ pipeline: { status: string; phases: Array<{ id: string; label: string; status: string }> } }>(`/pipeline/${taskId}`);
            const { pipeline } = result;

            // Update spinner with current phase
            const activePhase = pipeline.phases.find((p: { status: string }) => p.status === 'running');
            if (activePhase) {
                spinner.text = `${chalk.cyan(activePhase.label)}...`;
            }

            if (pipeline.status === 'done') {
                spinner.succeed(chalk.green('Task completed successfully'));
                // Show phase summary
                for (const phase of pipeline.phases) {
                    const icon = phase.status === 'done' ? '✅' :
                        phase.status === 'skipped' ? '⏭️' :
                            phase.status === 'error' ? '❌' : '⏳';
                    console.log(`  ${icon} ${phase.label}: ${phase.status}`);
                }
                return;
            }

            if (pipeline.status === 'error') {
                spinner.fail(chalk.red('Task failed'));
                for (const phase of pipeline.phases) {
                    const icon = phase.status === 'done' ? '✅' :
                        phase.status === 'error' ? '❌' : '⏳';
                    console.log(`  ${icon} ${phase.label}: ${phase.status}`);
                }
                return;
            }
        } catch {
            // Ignore polling errors, keep trying
        }
    }

    spinner.warn(chalk.yellow('Polling timeout — check status manually'));
}

/**
 * Register `brunella dev` subcommands
 */
export function registerDevCommands(program: Command): void {
    const dev = program.command('dev').description('Developer Agent commands (code gen, test, fix, heal)');

    // brunella dev generate <prompt>
    dev
        .command('generate <prompt...>')
        .description('Generate code from a natural language prompt')
        .option('-f, --file <path>', 'Save generated code to file')
        .option('--no-test', 'Skip test phase')
        .option('--context <mode>', 'Context gathering: auto | none (default: none)')
        .action(async (promptParts: string[], opts: { file?: string; test?: boolean; context?: string }) => {
            const prompt = promptParts.join(' ');
            const spinner = ora(`Generating code...`).start();

            try {
                const context: Record<string, unknown> = {};
                if (opts.file) context.filePath = opts.file;
                if (opts.test === false) context.skipTests = true;
                if (opts.context === 'auto' && opts.file) {
                    spinner.text = 'Gathering context...';
                    try {
                        const ctxResult = await apiFetch<{ context: { files: Array<{ relativePath: string; size: number }> } }>('/context', {
                            method: 'POST',
                            body: JSON.stringify({ filePath: opts.file }),
                        });
                        context.contextFiles = ctxResult.context.files.map(f => f.relativePath);
                        spinner.text = `Context: ${ctxResult.context.files.length} files. Generating code...`;
                    } catch {
                        // Context gathering failed, continue without context
                        spinner.text = 'Generating code (no context)...';
                    }
                }

                const { taskId } = await executeDevTask(
                    `generate code: ${prompt}`,
                    context
                );

                spinner.text = `Pipeline started: ${chalk.dim(taskId)}`;
                await pollPipeline(taskId, spinner);
            } catch (e: unknown) {
                const msg = e instanceof Error ? e.message : String(e);
                spinner.fail(chalk.red(`Generation failed: ${msg}`));
                process.exit(1);
            }
        });

    // brunella dev test <file>
    dev
        .command('test <file>')
        .description('Generate tests for a source file')
        .option('-o, --output <path>', 'Output test file path')
        .action(async (file: string, opts: { output?: string }) => {
            const spinner = ora(`Generating tests for ${chalk.cyan(file)}...`).start();

            try {
                const context: Record<string, unknown> = {
                    filePath: file,
                };
                if (opts.output) context.testFilePath = opts.output;

                const { taskId } = await executeDevTask(
                    `generate vitest tests for ${file}`,
                    context
                );

                spinner.text = `Pipeline started: ${chalk.dim(taskId)}`;
                await pollPipeline(taskId, spinner);
            } catch (e: unknown) {
                const msg = e instanceof Error ? e.message : String(e);
                spinner.fail(chalk.red(`Test generation failed: ${msg}`));
                process.exit(1);
            }
        });

    // brunella dev fix [--auto]
    dev
        .command('fix')
        .description('Fix build or test errors')
        .option('--auto', 'Auto-detect and fix all errors')
        .option('-f, --file <path>', 'File to fix')
        .option('-e, --error <message>', 'Error message to fix')
        .action(async (opts: { auto?: boolean; file?: string; error?: string }) => {
            const spinner = ora('Fixing errors...').start();

            try {
                const context: Record<string, unknown> = {};
                if (opts.file) context.filePath = opts.file;
                if (opts.error) context.error = opts.error;
                if (opts.auto) context.autoFix = true;

                const task = opts.auto
                    ? 'fix all build errors automatically'
                    : `fix error${opts.file ? ` in ${opts.file}` : ''}${opts.error ? `: ${opts.error}` : ''}`;

                const { taskId } = await executeDevTask(task, context);

                spinner.text = `Pipeline started: ${chalk.dim(taskId)}`;
                await pollPipeline(taskId, spinner);
            } catch (e: unknown) {
                const msg = e instanceof Error ? e.message : String(e);
                spinner.fail(chalk.red(`Fix failed: ${msg}`));
                process.exit(1);
            }
        });

    // brunella dev heal
    dev
        .command('heal')
        .description('Run self-healing build cycle')
        .action(async () => {
            const spinner = ora('Running self-heal...').start();

            try {
                const { taskId } = await executeDevTask(
                    'self-heal: fix all build errors and ensure npm run build succeeds'
                );

                spinner.text = `Pipeline started: ${chalk.dim(taskId)}`;
                await pollPipeline(taskId, spinner);
            } catch (e: unknown) {
                const msg = e instanceof Error ? e.message : String(e);
                spinner.fail(chalk.red(`Self-heal failed: ${msg}`));
                process.exit(1);
            }
        });

    // brunella dev ai-interpreter
    dev
        .command('ai-interpreter')
        .alias('ai')
        .description('AI-powered persistent Python interpreter (Comet-style)')
        .option('-m, --model <name>', 'Preferred model (gpt-4o, qwen2.5-coder)')
        .action(async (opts: { model?: string }) => {
            console.log(chalk.cyan.bold('\n🧠 Brunella AI-Interpreter (Comet Mode)'));
            console.log(chalk.dim('Utasításaidat Python kódra fordítom és azonnal futtatom.'));
            console.log(chalk.dim('Kilépés: "exit" vagy "quit"\n'));

            const client = new BrunellaClient();
            try {
                await client.connect();
                
                // Conversational context (RULE-OB2: History tracking)
                const history: Array<{ role: 'user' | 'assistant', content: string }> = [];

                while (true) {
                    const { instruction } = await inquirer.prompt([
                        {
                            type: 'input',
                            name: 'instruction',
                            message: chalk.green('AI ❯'),
                        }
                    ]);

                    if (['exit', 'quit'].includes(instruction.toLowerCase().trim())) break;
                    if (!instruction.trim()) continue;

                    const spinner = ora('Gondolkozom...').start();

                    try {
                        // Special mode for the developer agent: interpreter
                        const { taskId } = await executeDevTask(instruction, {
                            mode: 'interpreter',
                            model: opts.model,
                            persist: true,
                            history: history.slice(-10) // Keep last 10 messages for context
                        });

                        spinner.text = 'Kód futtatása...';
                        
                        // We poll the pipeline, but we want the ACTUAL output once done
                        await pollPipeline(taskId, spinner);
                        
                        // After polling, fetch the pipeline result
                        const { pipeline } = await apiFetch<{ pipeline: { result?: any, error?: string } }>(`/pipeline/${taskId}`);
                        
                        if (pipeline.result && pipeline.result.status === 'success') {
                            const output = pipeline.result.data.output;
                            const generatedCode = pipeline.result.data.code;

                            console.log(chalk.white('\n--- Kimenet ---'));
                            console.log(output || chalk.dim('(nincs szöveges kimenet)'));
                            console.log(chalk.white('---------------\n'));

                            // Add to history
                            history.push({ role: 'user', content: instruction });
                            history.push({ role: 'assistant', content: `Kód futtatva. Kimenet: ${output}` });

                        } else if (pipeline.error) {
                            console.log(chalk.red(`\n❌ Hiba: ${pipeline.error}\n`));
                        }

                    } catch (e: any) {
                        spinner.fail(chalk.red('Hiba történt.'));
                        console.error(chalk.red(e.message));
                    }
                }
            } catch (e: any) {
                console.error(chalk.red(`Kapcsolati hiba: ${e.message}`));
            } finally {
                await client.close();
                process.exit(0);
            }
        });

    // brunella dev review <file>
    dev
        .command('review <file>')
        .description('Review code quality with AI-powered analysis')
        .option('--json', 'Output raw JSON')
        .action(async (file: string, opts: { json?: boolean }) => {
            const spinner = ora(`Reviewing ${chalk.cyan(file)}...`).start();

            try {
                const result = await apiFetch<{
                    review: {
                        filePath: string;
                        fileName: string;
                        language: string;
                        score: number;
                        summary: string;
                        findings: Array<{
                            severity: string;
                            line?: number;
                            message: string;
                            rule?: string;
                            suggestion?: string;
                        }>;
