        .option('--json', 'Output as JSON')
        .action(async (options: { json?: boolean }) => {
            const spinner = ora('Fetching templates...').start();
            try {
                const result = await apiFetch<{ templates: any[] }>('/scaffold/templates');
                const templates = result.templates;
                
