        .action(async (template: string, options: { dryRun?: boolean; force?: boolean; var?: string[] }) => {
            const spinner = ora('Generating code...').start();
            try {
                // Parse variables
                const variables: Record<string, string> = {};
                if (options.var) {
                    for (const v of options.var) {
                        const [key, value] = v.split('=');
                        if (key && value) {
                            variables[key] = value;
                        }
                    }
                }

                const result = await apiFetch<{ message: string; files: any[] }>('/scaffold', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        template,
                        variables,
                        preview: options.dryRun,
                        overwrite: options.force
                    })
                });

                spinner.succeed(chalk.green(result.message));

                if (result.files && result.files.length > 0) {
                    console.log(`\n${chalk.bold('Generated Files:')}`);
                    for (const file of result.files) {
                        console.log(`  ${chalk.cyan(file.path)}`);
                        if (options.dryRun) {
                            console.log(chalk.dim('\nPreview:'));
                            console.log(chalk.gray(file.content.substring(0, 200) + '...'));
                            console.log(chalk.dim('---'));
                        }
                    }
                }

            } catch (e: unknown) {
                const msg = e instanceof Error ? e.message : String(e);
                spinner.fail(chalk.red(`Failed to generate code: ${msg}`));
                
                // Hint for missing variables
                if (msg.includes('Required variable missing')) {
                    console.log(chalk.yellow('\nTip: Provide variables using -v flag:'));
                    console.log(chalk.gray('  brunella dev scaffold generate react-component -v ComponentName=MyButton'));
                }
                
                process.exit(1);
            }
        });

    // ==================== P11: Approval Commands ====================

    const approval = dev.command('approval').description('Manage approval requests');

    approval
        .command('list')
        .description('List pending approval requests')
        .action(async () => {
            const spinner = ora('Fetching approval requests...').start();
            try {
                const result = await apiFetch<{ requests: any[] }>('/approval?status=pending');
                const { requests } = result;
                spinner.stop();

                if (requests.length === 0) {
                    console.log(chalk.dim('\nNo pending requests.'));
                    return;
                }

                console.log(chalk.bold('\nPending Approvals:\n'));
                for (const req of requests) {
                    console.log(`${chalk.cyan(req.id)} [${req.type}]`);
                    console.log(`  ${req.description}`);
                    const age = Math.round((Date.now() - req.createdAt) / 1000);
                    console.log(`  ${chalk.dim(`Created ${age}s ago`)}`);
                    console.log('');
                }
            } catch (e: unknown) {
                 const msg = e instanceof Error ? e.message : String(e);
                spinner.fail(chalk.red(`Failed: ${msg}`));
                process.exit(1);
            }
        });

    approval
        .command('approve <id>')
        .description('Approve a request')
        .action(async (id: string) => {
            const spinner = ora(`Approving ${id}...`).start();
            try {
                const result = await apiFetch<{ success: boolean; status: string }>(`/approval/${id}/respond`, {
                    method: 'POST',
                    body: JSON.stringify({ action: 'approve' })
                });
                spinner.succeed(chalk.green(`Request approved`));
            } catch (e: unknown) {
                const msg = e instanceof Error ? e.message : String(e);
                 spinner.fail(chalk.red(`Failed: ${msg}`));
                process.exit(1);
            }
        });

    approval
        .command('reject <id>')
        .description('Reject a request')
        .action(async (id: string) => {
             const spinner = ora(`Rejecting ${id}...`).start();
            try {
                const result = await apiFetch<{ success: boolean; status: string }>(`/approval/${id}/respond`, {
                     method: 'POST',
                    body: JSON.stringify({ action: 'reject' })
                });
                spinner.succeed(chalk.red(`Request rejected`));
            } catch (e: unknown) {
                 const msg = e instanceof Error ? e.message : String(e);
                spinner.fail(chalk.red(`Failed: ${msg}`));
                 process.exit(1);
            }
        });

    // ==================== P12: Activity Feed Commands ====================

    dev
        .command('feed')
        .description('Show activity feed')
        .option('-l, --limit <count>', 'Limit entries', '20')
        .option('--json', 'Output raw JSON')
        .option('-w, --watch', 'Watch mode (poll for new events)')
        .action(async (opts: { limit: string; json?: boolean; watch?: boolean }) => {
            try {
                const limit = parseInt(opts.limit) || 20;

                const fetchAndShow = async (lastId?: string) => {
                    const result = await apiFetch<{ activities: any[] }>(`/feed?limit=${limit}`);
                    // If watching, filter out old ones
                    const newItems = lastId 
                        ? result.activities.filter(a => a.id > lastId) // Simple lexicographical check or timestamp check needed? ID is random. 
                        // Actually ID is act-{timestamp}-{random}, so lexicographical might work for timestamp part, but safe to filter by timestamp or known IDs.
                        // For simplicity in CLI, just showing snapshot unless we implement smart dedupe.
                        // Let's rely on timestamp if watching.
                        : result.activities;

                    if (opts.json) {
                        console.log(JSON.stringify(newItems, null, 2));
                        return result.activities[0]?.id; // Return latest ID
                    }
                    
                    if (!lastId && !opts.watch) {
                        console.log(chalk.bold('\n📡 Activity Feed:\n'));
                    }

                    // Reverse to show oldest first in log stream, but for snapshot usually newest first
                    const itemsToShow = opts.watch ? newItems.reverse() : newItems;

                    for (const item of itemsToShow) {
                        const time = new Date(item.timestamp).toLocaleTimeString();
                        let badge = chalk.blue('INFO');
                        if (item.type === 'success') badge = chalk.green('DONE');
                        if (item.type === 'warning') badge = chalk.yellow('WARN');
                        if (item.type === 'error') badge = chalk.red('ERR ');
                        if (item.type === 'approval') badge = chalk.magenta('ASK ');

                        const source = chalk.dim(`[${item.source}]`);
                        console.log(`${chalk.dim(time)} ${badge} ${source} ${item.message}`);
                    }
                    
                    return result.activities[0]?.id || lastId; // Latest ID
                };

                const latestId = await fetchAndShow();

                if (opts.watch) {
                    console.log(chalk.dim('\nWatching for new activities... (Ctrl+C to stop)'));
                    // Use a simple Set to track seen IDs for deduplication in watch mode
                    const seenIds = new Set<string>();
                    // Prime with initial fetch
                    // (Actually the logic above is a bit simplistic for proper watch, 
                    // let's just re-fetch and filter by seenIds)
                    
                    // Reset seenIds with initial batch
                    // (We can't easily access the initial batch variable here due to scope, let's just start fresh loop)
                }
                
                if (opts.watch) {
                    const seen = new Set<string>();
                    // Add initial batch to seen
                    // We need to re-fetch to simplify logic or change structure.
                    // Let's keep it simple: just poll.
                    
                    setInterval(async () => {
                        const result = await apiFetch<{ activities: any[] }>(`/feed?limit=20`);
                        const newActivities = result.activities.filter(a => !seen.has(a.id)).reverse(); // Oldest first for streaming
                        
                        for (const item of newActivities) {
                             seen.add(item.id);
                             // ... print ...
                             const time = new Date(item.timestamp).toLocaleTimeString();
                             let badge = chalk.blue('INFO');
                             if (item.type === 'success') badge = chalk.green('DONE');
                             if (item.type === 'warning') badge = chalk.yellow('WARN');
                             if (item.type === 'error') badge = chalk.red('ERR ');
                             if (item.type === 'approval') badge = chalk.magenta('ASK ');
     
                             const source = chalk.dim(`[${item.source}]`);
                             console.log(`${chalk.dim(time)} ${badge} ${source} ${item.message}`);
                        }
                    }, 2000);
                    
                    // Prime the set with recent ones so we don't dump 20 old ones
                    const initial = await apiFetch<{ activities: any[] }>(`/feed?limit=${limit}`);
                    initial.activities.forEach(a => seen.add(a.id));
                }

            } catch (e: unknown) {
                 const msg = e instanceof Error ? e.message : String(e);
                console.error(chalk.red(`Failed: ${msg}`));
                 process.exit(1);
            }
        });

}

import { Command } from "commander";
import chalk from "chalk";
import ora from "ora";
import { cloudflareClient } from "../utils/cloudflareClient.js";

const API_BASE = process.env.BRUNELLA_API_URL || "http://localhost:3000";

function getErrorMessage(error: unknown): string {
  if (error instanceof Error) return error.message;
  return String(error);
}

export function registerEdgeCommands(program: Command) {
  const edgeGroup = program
    .command("edge")
    .description("Manage Cloudflare Edge integration (Tasks, Status)");

  edgeGroup
    .command("status")
    .description("Check Edge Worker status")
    .action(async () => {
      const spinner = ora("Checking Edge status...").start();
      try {
        // Perform a simple check by fetching history with limit 1
        await cloudflareClient.fetchHistory(1);
        spinner.succeed(chalk.green("Edge Worker is Online"));
        console.log(
          chalk.dim(
            `URL: ${cloudflareClient.getResolvedBaseUrl()}`,
          ),
        );
      } catch (error: unknown) {
        spinner.fail(chalk.red("Edge Worker is Offline or Unreachable"));
        console.error(chalk.red(getErrorMessage(error)));
      }
    });

  edgeGroup
    .command("submit <instruction>")
    .description("Submit a task to the Edge")
    .option("-c, --context <json>", "Context JSON string")
    .action(async (instruction: string, options: { context?: string }) => {
      const spinner = ora("Submitting task to Edge...").start();
      try {
        let context = {};
        if (options.context) {
          try {
            context = JSON.parse(options.context);
          } catch {
            console.warn(chalk.yellow("Invalid JSON context, ignoring."));
          }
        }

        const result = await cloudflareClient.submitTask(instruction, context);
        spinner.succeed(chalk.green("Task Completed"));

        console.log(chalk.bold("\nResult:"));
        if (typeof result.result === "string") {
          console.log(result.result);
        } else {
          console.log(JSON.stringify(result.result, null, 2));
        }
        console.log(chalk.dim(`\nTask ID: ${result.taskId}`));
      } catch (error: unknown) {
        spinner.fail(chalk.red("Task Failed"));
        console.error(chalk.red(getErrorMessage(error)));
      }
    });

  edgeGroup
    .command("submit-worker <workerId> <instruction>")
    .description("Submit a task to a specific Cloudflare worker")
    .option("-c, --context <json>", "Context JSON string")
    .action(
      async (
        workerId: string,
        instruction: string,
        options: { context?: string },
      ) => {
        const spinner = ora(`Submitting task to worker '${workerId}'...`).start();

        try {
          let context = {};
          if (options.context) {
            try {
              context = JSON.parse(options.context);
            } catch {
              console.warn(chalk.yellow("Invalid JSON context, ignoring."));
            }
          }

          const response = await fetch(
            `${API_BASE}/api/cloudflare/agents/${encodeURIComponent(workerId)}/task`,
            {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify({ instruction, context }),
            },
          );

          const data = (await response.json()) as {
            success: boolean;
            workerId: string;
            workerName: string;
            endpoint?: string;
            result?: unknown;
            error?: string;
          };

          if (!response.ok || !data.success) {
            throw new Error(data.error || `HTTP ${response.status}`);
          }

          spinner.succeed(
            chalk.green(`Task dispatched to ${data.workerName} (${data.workerId})`),
          );

          if (data.endpoint) {
            console.log(chalk.dim(`Endpoint: ${data.endpoint}`));
          }
          if (typeof data.result === "string") {
            console.log(chalk.bold("\nResult:"));
            console.log(data.result);
          } else if (typeof data.result !== "undefined") {
            console.log(chalk.bold("\nResult:"));
            console.log(JSON.stringify(data.result, null, 2));
          }
        } catch (error: unknown) {
          spinner.fail(chalk.red("Worker task dispatch failed"));
          console.error(chalk.red(getErrorMessage(error)));
        }
      },
    );

  edgeGroup
    .command("history")
    .description("View task history")
    .option("-l, --limit <number>", "Number of tasks to show", "10")
    .action(async (options: { limit: string }) => {
      const limit = parseInt(options.limit);
      const spinner = ora(`Fetching last ${limit} tasks...`).start();
      try {
        const data = await cloudflareClient.fetchHistory(limit);
        spinner.stop();

        if (!data.tasks || data.tasks.length === 0) {
          console.log(chalk.yellow("No history found."));
          return;
        }

        console.log(chalk.bold(`\nEdge Task History (${data.tasks.length}):`));
        data.tasks.forEach((task: any) => {
          const date = new Date(task.created_at).toLocaleString();
          const statusColor =
            task.status === "completed"
              ? chalk.green
              : task.status === "failed"
                ? chalk.red
                : chalk.yellow;
          console.log(
            `${chalk.dim(task.id.slice(0, 8))} [${statusColor(
              task.status,
            )}] ${date} - ${task.instruction.slice(0, 50)}${
              task.instruction.length > 50 ? "..." : ""
            }`,
          );
        });
      } catch (error: unknown) {
        spinner.fail(chalk.red("Failed to fetch history"));
        console.error(chalk.red(getErrorMessage(error)));
      }
    });

  edgeGroup
    .command("audit")
    .description("Audit all configured Cloudflare workers")
    .action(async () => {
      const spinner = ora("Running Cloudflare workers audit...").start();

      try {
        const response = await fetch(`${API_BASE}/api/cloudflare/agents`);
        const data = (await response.json()) as {
          status: "connected" | "degraded" | "error";
          summary: { total: number; online: number; offline: number; unknown: number };
          workers: Array<{
            id: string;
            name: string;
            url?: string;
            kind: "public" | "internal";
            status: "online" | "offline" | "unknown";
            latencyMs?: number;
            statusCode?: number;
            error?: string;
          }>;
          error?: string;
        };

        if (!response.ok) {
          throw new Error(data.error || `HTTP ${response.status}`);
        }

        spinner.succeed(chalk.green(`Audit completed: ${data.status.toUpperCase()}`));

        console.log(
          chalk.dim(
            `\nSummary: total=${data.summary.total}, online=${data.summary.online}, offline=${data.summary.offline}, unknown=${data.summary.unknown}`,
          ),
        );

        for (const worker of data.workers) {
          const statusColor =
            worker.status === "online"
              ? chalk.green
              : worker.status === "offline"
                ? chalk.red
                : chalk.yellow;
          const latencyText =
            typeof worker.latencyMs === "number" ? ` (${worker.latencyMs}ms)` : "";
          const kindText = worker.kind === "public" ? "public" : "internal";

          console.log(
            `${statusColor(worker.status.toUpperCase())} ${chalk.bold(worker.name)} [${kindText}]${latencyText}`,
          );
          console.log(chalk.dim(`  url: ${worker.url || "(not configured)"}`));
          if (typeof worker.statusCode === "number") {
            console.log(chalk.dim(`  http: ${worker.statusCode}`));
          }
          if (worker.error) {
            console.log(chalk.dim(`  note: ${worker.error}`));
          }
        }
      } catch (error: unknown) {
        spinner.fail(chalk.red("Cloudflare workers audit failed"));
        console.error(chalk.red(getErrorMessage(error)));
      }
    });

  edgeGroup
    .command("tunnel")
    .description("Show tunnel and Cloudflare runtime configuration")
    .action(async () => {
      const spinner = ora("Loading Cloudflare tunnel config...").start();

      try {
        const response = await fetch(`${API_BASE}/api/cloudflare/config`);
        const data = (await response.json()) as {
          edge: { enabled: boolean; workerUrl: string };
          chat: { url: string };
          tunnel: {
            enabled: boolean;
            apiUrl: string | null;
            n8nUrl: string | null;
            browserUrl: string | null;
            dashboardUrl: string | null;
          };
          auth: {
            hasCloudflareApiToken: boolean;
            hasCeanApiKey: boolean;
          };
          error?: string;
        };

        if (!response.ok) {
          throw new Error(data.error || `HTTP ${response.status}`);
        }

        spinner.succeed(chalk.green("Cloudflare runtime config loaded"));

