import { BrunellaClient } from "../utils/mcpClient.js";
import { logError } from "../utils/logger.js";

type ToolResponse<T> = {
  success: boolean;
  data?: T;
  error?: string;
  stats?: Record<string, unknown>;
  count?: number;
  invoices?: T;
  duplicates_skipped?: number;
  row_count?: number;
  health?: Record<string, unknown>;
};

export type InvoiceSyncOptions = {
  sinceDate?: string;
  limit?: number;
  forceRefresh?: boolean;
  includeUnpaidOnly?: boolean;
  getOverdue?: boolean;
  append?: boolean;
  clearFirst?: boolean;
  skipDuplicates?: boolean;
  batchSize?: number;
  dryRun?: boolean;
};

export type InvoiceSyncResult = {
  success: boolean;
  fetched: number;
  written: number;
  duplicatesSkipped: number;
  source?: string;
  message?: string;
  fetchStats?: Record<string, unknown>;
  writeResult?: Record<string, unknown>;
};

function getToolText(result: unknown): string | null {
  if (!result || typeof result !== "object") return null;
  const content = (result as { content?: Array<{ text?: string }> }).content;
  if (!Array.isArray(content) || !content[0]?.text) return null;
  return content[0].text ?? null;
}

function parseToolJson<T>(result: unknown, toolName: string): T {
  const text = getToolText(result);
  if (!text) {
    throw new Error(`MCP tool '${toolName}' returned empty response`);
  }
  try {
    return JSON.parse(text) as T;
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    throw new Error(`MCP tool '${toolName}' JSON parse error: ${msg}`);
  }
}

export async function runInvoiceSync(
  client: BrunellaClient,
  options: InvoiceSyncOptions,
): Promise<InvoiceSyncResult> {
  const fetchResult = await client.callTool("get_szamlazz_invoices", {
    since_date: options.sinceDate || undefined,
    limit: options.limit,
    force_refresh: options.forceRefresh,
    include_unpaid_only: options.includeUnpaidOnly,
    get_overdue: options.getOverdue,
  });

  const fetchParsed = parseToolJson<ToolResponse<Record<string, unknown>[]>>(
    fetchResult,
    "get_szamlazz_invoices",
  );

  if (!fetchParsed.success) {
    const error = fetchParsed.error || "Számla lekérés sikertelen";
    logError("InvoiceSync", error);
    return {
      success: false,
      fetched: 0,
      written: 0,
      duplicatesSkipped: 0,
      message: error,
    };
  }

  const invoices = fetchParsed.data || fetchParsed.invoices || [];
  const fetched = Array.isArray(invoices) ? invoices.length : 0;
  const source =
    (fetchParsed.stats?.health as Record<string, unknown> | undefined)?.source ||
    (fetchParsed.health as Record<string, unknown> | undefined)?.source ||
    "API";

  if (options.dryRun || fetched === 0) {
    return {
      success: true,
      fetched,
      written: 0,
      duplicatesSkipped: 0,
      source: typeof source === "string" ? source : "API",
      message: options.dryRun ? "Dry-run: nincs írás" : "Nincs új számla",
      fetchStats: fetchParsed.stats,
    };
  }

  const writeResult = await client.callTool("write_sheets_invoices", {
    invoices,
    append: options.append,
    clear_first: options.clearFirst,
    skip_duplicates: options.skipDuplicates,
    batch_size: options.batchSize,
  });

  const writeParsed = parseToolJson<ToolResponse<Record<string, unknown>>>(
    writeResult,
    "write_sheets_invoices",
  );

  if (!writeParsed.success) {
    const error = writeParsed.error || "Google Sheets írás sikertelen";
    logError("InvoiceSync", error);
    return {
      success: false,
      fetched,
      written: 0,
      duplicatesSkipped: 0,
      source: typeof source === "string" ? source : "API",
      message: error,
      fetchStats: fetchParsed.stats,
    };
  }

  const writeData = writeParsed.data || {};
  const written =
    typeof writeData.row_count === "number" ? writeData.row_count : fetched;
  const duplicatesSkipped =
    typeof writeData.duplicates_skipped === "number"
      ? writeData.duplicates_skipped
      : 0;

  return {
    success: true,
    fetched,
    written,
    duplicatesSkipped,
    source: typeof source === "string" ? source : "API",
    fetchStats: fetchParsed.stats,
    writeResult: writeData,
  };
}

/**
 * Lead Mining CLI Commands (Master Track 1 - Phase 4)
 *
 * Parancsok:
 *  - brunella leads run <query>   — Lead mining indítása
 *  - brunella leads status        — Utolsó job státusza
 *  - brunella leads list          — Legutóbbi leadek listája
 */

import { Command } from "commander";
import chalk from "chalk";
import ora from "ora";

const API_BASE = process.env.API_BASE_URL || "http://localhost:3000";

export function registerLeadCommands(program: Command): void {
  const leads = program
    .command("leads")
    .description("B2B Lead Mining parancsok (LeadMiningAgent)");

  leads
    .command("run")
    .description("Lead mining indítása — Google Maps scraping + icebreaker + email validáció")
    .argument("[query]", 'Keresési lekérdezés (pl. "fogorvos Budapest")', "fogorvos Budapest")
    .option("--limit <number>", "Maximum lead szám", "10")
    .action(async (query: string, opts: { limit: string }) => {
      const spinner = ora(`Lead mining indítása: "${query}"...`).start();

      try {
        const res = await fetch(`${API_BASE}/api/v1/business-jobs`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            type: "lead_mining",
            query,
            metadata: { limit: parseInt(opts.limit, 10) },
          }),
        });

        if (!res.ok) {
          const err = await res.text();
          spinner.fail(chalk.red(`API hiba (${res.status}): ${err}`));
          process.exit(1);
        }

        const data = await res.json() as { jobId: string; message: string };
        spinner.succeed(chalk.green(`Lead mining elindítva! Job ID: ${chalk.bold(data.jobId)}`));
        console.log(chalk.dim(`  Lekérdezés: "${query}" | Limit: ${opts.limit}`));
        console.log(chalk.dim(`  Állapot: brunella leads status`));
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  leads
    .command("status")
    .description("Utolsó lead mining job állapota és statisztikái")
    .option("--limit <number>", "Megjelenített jobok száma", "5")
    .action(async (opts: { limit: string }) => {
      const spinner = ora("Job adatok lekérése...").start();

      try {
        const res = await fetch(
          `${API_BASE}/api/v1/business-jobs?type=lead_mining&limit=${opts.limit}`,
        );

        if (!res.ok) {
          spinner.fail(chalk.red(`API hiba (${res.status})`));
          process.exit(1);
        }

        const data = await res.json() as { jobs: Array<{ id: string; query: string; status: string; created_at: string }> };
        spinner.stop();

        if (!data.jobs || data.jobs.length === 0) {
          console.log(chalk.yellow("Nincs korábbi lead mining job. Futtatás: brunella leads run"));
          return;
        }

        console.log(chalk.blue("\n╔═══════════════════════════════════════════════════════════════╗"));
        console.log(chalk.blue("║") + chalk.bold("          LEAD MINING JOB STATISZTIKA                       ") + chalk.blue("║"));
        console.log(chalk.blue("╚═══════════════════════════════════════════════════════════════╝\n"));

        data.jobs.forEach((job, idx) => {
          const statusColor = job.status === "completed" ? chalk.green : job.status === "failed" ? chalk.red : chalk.yellow;
          console.log(`${chalk.bold(`#${idx + 1}`)} ${chalk.dim(job.id.slice(0, 8))}... | ${statusColor(job.status)} | "${job.query}"`);
          console.log(chalk.dim(`   Létrehozva: ${new Date(job.created_at).toLocaleString("hu-HU")}`));
        });
        console.log();

      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  leads
    .command("list")
    .description("Legutóbbi leadek listázása")
    .option("--job-id <id>", "Szűrés job ID szerint")
    .option("--limit <number>", "Megjelenített leadek száma", "20")
    .action(async (opts: { jobId?: string; limit: string }) => {
      const spinner = ora("Leadek lekérése...").start();

