            id: string;
            company_name: string;
            contact_email?: string;
            email_status?: string;
            icebreaker_text?: string;
            created_at: string;
          }>;
        };
        spinner.stop();

        if (!data.leads || data.leads.length === 0) {
          console.log(chalk.yellow("Nincsenek leadek. Futtatás: brunella leads run"));
          return;
        }

        const shown = data.leads.slice(0, parseInt(opts.limit, 10));

