          if (lead.icebreaker_text) {
            const ib = lead.icebreaker_text.slice(0, 80);
            console.log(`   Icebreaker: ${chalk.dim(ib)}${lead.icebreaker_text.length > 80 ? "..." : ""}`);
          }
        });
        console.log();

      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });
}

/**
 * Market Watcher CLI Commands (Master Track 3 - Phase 4)
 *
 * Parancsok:
 *  - brunella market run <kategória>  — Piaci figyelés indítása
 *  - brunella market status           — Aktív figyelések listája
 *  - brunella market alerts           — Ár riasztások megjelenítése
 */

import { Command } from "commander";
import chalk from "chalk";
import ora from "ora";

const API_BASE = process.env.API_BASE_URL || "http://localhost:3000";

export function registerMarketCommands(program: Command): void {
  const market = program
    .command("market")
    .description("Piaci hírszerzés parancsok (MarketIntelAgent)");

  market
    .command("run")
    .description("Piaci figyelés indítása — versenytárs ár scraping + trend elemzés")
    .argument("[category]", 'Termék kategória (pl. "industrial valves")', "general products")
    .option("--competitors <list>", "Versenytársak vesszővel elválasztva")
    .option("--url <url>", "Konkrét URL figyelése")
    .action(async (category: string, opts: { competitors?: string; url?: string }) => {
      const spinner = ora(`Piaci figyelés indítása: "${category}"...`).start();

      try {
        const metadata: Record<string, unknown> = { productCategory: category };
        if (opts.competitors) {
          metadata.competitors = opts.competitors.split(",").map((c) => c.trim());
        }
        if (opts.url) {
          metadata.url = opts.url;
        }

        const res = await fetch(`${API_BASE}/api/agents/MarketIntel/execute`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            task: category,
            context: metadata,
          }),
        });

        if (!res.ok) {
          const err = await res.text();
          spinner.fail(chalk.red(`API hiba (${res.status}): ${err}`));
          process.exit(1);
        }

        const data = await res.json() as { status: string; data?: { summary?: { productsTracked: number; competitorsScraped: number; priceDropsDetected: number } }; message?: string };
        spinner.succeed(chalk.green("Piaci elemzés lefutott!"));

        if (data.data?.summary) {
          const s = data.data.summary;
          console.log(chalk.blue("\n╔═══════════════════════════════════════╗"));
          console.log(chalk.blue("║") + chalk.bold("     PIACI ELEMZÉS ÖSSZEFOGLALÓ      ") + chalk.blue("║"));
          console.log(chalk.blue("╚═══════════════════════════════════════╝\n"));
          console.log(`  Követett termékek:  ${chalk.cyan(s.productsTracked)}`);
          console.log(`  Scraper versenytárs: ${chalk.cyan(s.competitorsScraped)}`);
          console.log(`  Ár esések:          ${s.priceDropsDetected > 0 ? chalk.red(s.priceDropsDetected) : chalk.green("0")}`);
          console.log();
        } else if (data.message) {
          console.log(chalk.dim(`  ${data.message}`));
        }

      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  market
    .command("status")
    .description("Futó és legutóbbi piaci figyelési sessziók")
    .action(async () => {
      const spinner = ora("Piaci hírszerzés állapot lekérése...").start();

      try {
        const res = await fetch(`${API_BASE}/api/agents`);

        if (!res.ok) {
          spinner.fail(chalk.red(`API hiba (${res.status})`));
          process.exit(1);
        }

        const data = await res.json() as {
          agents: Array<{ name: string; status: string; currentTask?: string; lastActive?: string }>;
        };
        spinner.stop();

        const marketAgent = data.agents?.find(
          (a) => a.name === "MarketIntel" || a.name === "market_intel",
        );

        console.log(chalk.blue("\n═══ MARKET WATCHER STÁTUSZ ═══\n"));

        if (marketAgent) {
          const statusColor =
            marketAgent.status === "working" ? chalk.yellow : chalk.green;
          console.log(`  Ügynök:    ${chalk.cyan("MarketIntelAgent")}`);
          console.log(`  Állapot:   ${statusColor(marketAgent.status)}`);
          if (marketAgent.currentTask) {
            console.log(`  Feladat:   ${chalk.dim(marketAgent.currentTask)}`);
          }
          if (marketAgent.lastActive) {
            console.log(
              `  Utoljára:  ${chalk.dim(new Date(marketAgent.lastActive).toLocaleString("hu-HU"))}`,
            );
          }
        } else {
          console.log(chalk.yellow("  MarketIntelAgent nem aktív."));
          console.log(chalk.dim("  Futtatás: brunella market run"));
        }
        console.log();

      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  market
    .command("alerts")
    .description("Legutóbbi ár riasztások megjelenítése (>10% ár változás)")
    .option("--category <name>", "Szűrés termék kategória szerint")
    .action(async (opts: { category?: string }) => {
      const spinner = ora("Riasztások lekérése...").start();

      try {
        const url = opts.category
          ? `${API_BASE}/api/agents/MarketIntel/execute`
          : `${API_BASE}/api/agents/MarketIntel/execute`;

        const res = await fetch(url, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            task: opts.category || "general products",
            context: { taskType: "monitor_market" },
          }),
        });

        if (!res.ok) {
          spinner.fail(chalk.red(`API hiba (${res.status})`));
          process.exit(1);
        }

        const data = await res.json() as {
          data?: { alerts?: Array<{ productName: string; competitor: string; oldPrice: number; newPrice: number; priceChangePercent: number; severity: string; timestamp: string }> };
        };
        spinner.stop();

        const alerts = data.data?.alerts || [];

        if (alerts.length === 0) {
          console.log(chalk.green("\n  Nincs aktív ár riasztás."));
          return;
        }

        console.log(chalk.red(`\n═══ ÁR RIASZTÁSOK (${alerts.length}) ═══\n`));

        alerts.forEach((alert, idx) => {
          const severityColor =
            alert.severity === "critical"
              ? chalk.red
              : alert.severity === "warning"
                ? chalk.yellow
                : chalk.blue;
          const changeStr =
            alert.priceChangePercent > 0
              ? chalk.red(`+${alert.priceChangePercent.toFixed(1)}%`)
              : chalk.green(`${alert.priceChangePercent.toFixed(1)}%`);

          console.log(`${chalk.bold(`${idx + 1}.`)} ${severityColor(`[${alert.severity.toUpperCase()}]`)} ${chalk.cyan(alert.productName)}`);
          console.log(`   Versenytárs: ${alert.competitor}`);
          console.log(`   Ár változás: ${alert.oldPrice.toLocaleString("hu-HU")} → ${alert.newPrice.toLocaleString("hu-HU")} HUF (${changeStr})`);
          console.log(chalk.dim(`   ${new Date(alert.timestamp).toLocaleString("hu-HU")}`));
        });
        console.log();

      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });
}

/**
 * Memória (User Preferences) CLI Commands — Magyar nyelvű preferencia-kezelő
 *
 * Parancsok:
 *   brunella memoria mentés        — Preferencia mentése
 *   brunella memoria lista          — Preferenciák listázása
 *   brunella memoria kontextus      — LLM kontextus lekérdezése
 *   brunella memoria törlés         — Preferencia törlése
 *   brunella memoria takarítás      — Lejárt preferenciák törlése
 */

import { Command } from "commander";
import chalk from "chalk";
import ora from "ora";
import inquirer from "inquirer";

const API_BASE = process.env.BRUNELLA_API_URL || "http://localhost:3000";

async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const url = `${API_BASE}${path}`;
  const response = await fetch(url, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  const text = await response.text();
  if (!text) throw new Error(`Üres válasz: ${path}`);
  return JSON.parse(text) as T;
}

export function registerMemoriaCommands(program: Command): void {
  const memoria = program
    .command("memoria")
    .description("🧠 Felhasználói preferenciák és memória kezelése");

  // brunella memoria mentés
  memoria
    .command("mentés")
    .alias("save")
    .description("Új preferencia mentése")
    .option("-u, --user <userId>", "Felhasználó azonosító", "default")
    .action(async (options: { user: string }) => {
      const answers = await inquirer.prompt([
        {
          type: "input",
          name: "key",
          message: "🔑 Preferencia kulcs:",
          validate: (input: string) => input.length > 0 || "Adj meg egy kulcsot",
        },
        {
          type: "input",
          name: "value",
          message: "📝 Érték:",
          validate: (input: string) => input.length > 0 || "Adj meg egy értéket",
        },
        {
          type: "list",
          name: "memory_type",
          message: "🧠 Memória típus:",
          choices: [
            { name: "📚 Szemantikus (tények, tudás)", value: "semantic" },
            { name: "📖 Epizodikus (események, munkamenetek)", value: "episodic" },
            { name: "⚙️  Procedurális (eljárások, minták)", value: "procedural" },
          ],
          default: "semantic",
        },
        {
          type: "number",
          name: "ttl_days",
          message: "⏳ Lejárat (napokban, 0 = nem jár le):",
          default: 0,
        },
      ]);

      const spinner = ora("Preferencia mentése...").start();
      try {
        const result = await apiFetch<{ success: boolean; message?: string; error?: string }>(
          "/api/v1/preferences",
          {
            method: "POST",
            body: JSON.stringify({
              user_id: options.user,
              key: answers.key,
              value: answers.value,
              memory_type: answers.memory_type,
              ttl_days: answers.ttl_days > 0 ? answers.ttl_days : undefined,
            }),
          },
        );

        if (result.success) {
          spinner.succeed(chalk.green(`✅ Preferencia mentve: "${answers.key}"`));
        } else {
          spinner.fail(chalk.red(`Hiba: ${result.error}`));
        }
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  // brunella memoria lista
  memoria
    .command("lista")
    .alias("list")
    .description("Preferenciák listázása")
    .option("-u, --user <userId>", "Felhasználó azonosító", "default")
    .option("-t, --type <type>", "Memória típus szűrő (episodic/semantic/procedural)")
    .option("-l, --limit <limit>", "Maximum sorok száma", "20")
    .action(async (options: { user: string; type?: string; limit: string }) => {
      const spinner = ora("Preferenciák lekérdezése...").start();
      try {
        let query = `/api/v1/preferences/${options.user}?limit=${options.limit}`;
        if (options.type) query += `&memory_type=${options.type}`;

        const result = await apiFetch<{
          success: boolean;
          count?: number;
          preferences?: Array<{
            key: string;
            value: string;
            memory_type: string;
            confidence: number;
            updated_at: string;
            access_count: number;
          }>;
          error?: string;
        }>(query);

        spinner.stop();

        if (result.success && result.preferences) {
          console.log(chalk.blue("\n╔════════════════════════════════════════╗"));
          console.log(chalk.blue("║") + chalk.bold("  🧠 FELHASZNÁLÓI PREFERENCIÁK         ") + chalk.blue("║"));
          console.log(chalk.blue("╚════════════════════════════════════════╝\n"));
          console.log(chalk.dim(`  Felhasználó: ${options.user} | Összesen: ${result.count}\n`));

          if (result.preferences.length === 0) {
            console.log(chalk.yellow("  Nincsenek preferenciák."));
            return;
          }

          const typeEmoji: Record<string, string> = {
            semantic: "📚",
            episodic: "📖",
            procedural: "⚙️",
          };

          result.preferences.forEach((p, i) => {
            const emoji = typeEmoji[p.memory_type] || "📝";
            console.log(
              `  ${chalk.bold(`#${i + 1}`)} ${emoji} ${chalk.cyan(p.key)} = ${chalk.white(p.value.substring(0, 60))}${p.value.length > 60 ? "..." : ""}`,
            );
            console.log(
              chalk.dim(
                `      Típus: ${p.memory_type} | Bizonyosság: ${(p.confidence * 100).toFixed(0)}% | Hozzáférés: ${p.access_count}x | ${new Date(p.updated_at).toLocaleString("hu-HU")}`,
              ),
            );
          });
          console.log();
        } else {
          console.log(chalk.red(`Hiba: ${result.error || "Ismeretlen hiba"}`));
        }
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  // brunella memoria kontextus
  memoria
    .command("kontextus")
    .alias("context")
    .description("LLM kontextus lekérdezése a felhasználó preferenciáiból")
    .option("-u, --user <userId>", "Felhasználó azonosító", "default")
    .action(async (options: { user: string }) => {
      const spinner = ora("Kontextus lekérdezése...").start();
      try {
        const result = await apiFetch<{
          success: boolean;
          context?: string;
          stats?: {
            total: number;
            by_type: Record<string, number>;
            by_category: Record<string, number>;
          };
          error?: string;
        }>(`/api/v1/preferences/context/${options.user}`);

        spinner.stop();

        if (result.success) {
          console.log(chalk.blue("\n╔════════════════════════════════════════╗"));
          console.log(chalk.blue("║") + chalk.bold("  🧠 LLM KONTEXTUS                    ") + chalk.blue("║"));
          console.log(chalk.blue("╚════════════════════════════════════════╝\n"));

          if (result.stats) {
            console.log(chalk.cyan("  📊 Statisztikák:"));
            console.log(chalk.dim(`     Összes preferencia: ${result.stats.total}`));
            if (result.stats.by_type) {
              Object.entries(result.stats.by_type).forEach(([type, count]) => {
                console.log(chalk.dim(`     ${type}: ${count}`));
              });
            }
            console.log();
          }

          if (result.context) {
            console.log(chalk.cyan("  📝 Kontextus szöveg:"));
            console.log(chalk.gray(`  ${result.context.replace(/\n/g, "\n  ")}`));
          } else {
            console.log(chalk.yellow("  Nincs kontextus (üres preferenciák)."));
          }
          console.log();
        } else {
          console.log(chalk.red(`Hiba: ${result.error}`));
        }
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  // brunella memoria törlés
  memoria
    .command("törlés")
    .alias("delete")
    .description("Preferencia törlése")
    .option("-u, --user <userId>", "Felhasználó azonosító", "default")
    .action(async (options: { user: string }) => {
      const answers = await inquirer.prompt([
        {
          type: "input",
          name: "key",
          message: "🗑️  Törlendő preferencia kulcs:",
          validate: (input: string) => input.length > 0 || "Adj meg egy kulcsot",
        },
        {
          type: "confirm",
          name: "confirm",
          message: "Biztosan törlöd?",
          default: false,
        },
      ]);

      if (!answers.confirm) {
        console.log(chalk.yellow("Törlés megszakítva."));
        return;
      }

      const spinner = ora("Preferencia törlése...").start();
      try {
        const result = await apiFetch<{ success: boolean; deleted?: boolean; error?: string }>(
          `/api/v1/preferences/${options.user}/${encodeURIComponent(answers.key)}`,
          { method: "DELETE" },
        );

        if (result.success && result.deleted) {
          spinner.succeed(chalk.green(`✅ Preferencia törölve: "${answers.key}"`));
        } else if (result.success && !result.deleted) {
          spinner.warn(chalk.yellow(`⚠️  Nem található: "${answers.key}"`));
        } else {
          spinner.fail(chalk.red(`Hiba: ${result.error}`));
        }
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });

  // brunella memoria takarítás
  memoria
    .command("takarítás")
    .alias("purge")
    .description("Lejárt preferenciák törlése")
    .action(async () => {
      const spinner = ora("Lejárt preferenciák törlése...").start();
      try {
        const result = await apiFetch<{ success: boolean; purged?: number; error?: string }>(
          "/api/v1/preferences/purge",
          { method: "POST" },
        );

        if (result.success) {
          spinner.succeed(chalk.green(`✅ Takarítás kész! ${result.purged || 0} lejárt bejegyzés törölve.`));
        } else {
          spinner.fail(chalk.red(`Hiba: ${result.error}`));
        }
      } catch (e: unknown) {
        spinner.fail(chalk.red("Kapcsolódási hiba"));
        console.error(chalk.red(e instanceof Error ? e.message : String(e)));
        process.exit(1);
      }
    });
}

import type { Command } from 'commander';
import { logInfo } from '../utils/logger.js';

export function registerObservabilityCommands(program: Command): void {
  const obs = program
    .command('observability')
    .alias('obs')
    .description('LLM Observability — hívás statisztikák és monitorozás');

  obs
    .command('stats')
    .description('LLM hívás statisztikák megjelenítése')
    .option('-s, --since <date>', 'Időszak kezdete (ISO formátum)')
    .action(async (opts: { since?: string }) => {
      try {
        const { getLlmCallStats } = await import('../utils/globalDb.js');
        const stats = getLlmCallStats(opts.since);

        logInfo('CLI', 'LLM Observability Stats lekérdezve');

        const chalk = (await import('chalk')).default;
        const boxen = (await import('boxen')).default;

        const lines = [
          chalk.bold('📊 LLM Observability Összefoglaló'),
          '',
          `  Összes hívás:    ${chalk.cyan(stats.totalCalls)}`,
          `  Sikerráta:       ${stats.successRate >= 95 ? chalk.green(stats.successRate.toFixed(1) + '%') : chalk.yellow(stats.successRate.toFixed(1) + '%')}`,
          `  Átlag latency:   ${chalk.cyan(stats.avgDurationMs + ' ms')}`,
          `  Összes token:    ${chalk.cyan(stats.totalTokens.toLocaleString())}`,
          `  Költség (USD):   ${chalk.green('$' + stats.totalCostUsd.toFixed(4))}`,
          '',
          chalk.bold('Provider bontás:'),
        ];

        if (stats.byProvider.length > 0) {
          for (const p of stats.byProvider) {
            lines.push(`  ${chalk.blue(p.provider.padEnd(12))} ${String(p.count).padStart(5)} hívás | ${String(Math.round(p.avgDuration)).padStart(5)} ms avg | ${p.tokens.toLocaleString()} token`);
          }
        } else {
          lines.push(`  ${chalk.gray('Még nincs adat')}`);
        }

        if (stats.recentErrors.length > 0) {
          lines.push('', chalk.bold.red('⚠ Legutóbbi hibák:'));
          for (const e of stats.recentErrors.slice(0, 5)) {
            lines.push(`  ${chalk.gray(e.timestamp.slice(0, 19))} [${chalk.yellow(e.provider)}] ${chalk.red(e.error?.slice(0, 80) || 'N/A')}`);
          }
        }

        const output = boxen(lines.join('\n'), {
          padding: 1,
          borderStyle: 'round',
          borderColor: 'blue',
        });
        process.stdout.write(output + '\n');
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        process.stderr.write(`Hiba: ${msg}\n`);
        process.exit(1);
      }
    });

  obs
    .command('calls')
    .description('Legutóbbi LLM hívások listázása')
    .option('-n, --limit <count>', 'Maximum elemszám', '20')
    .option('-p, --provider <name>', 'Szűrés provider-re')
    .action(async (opts: { limit?: string; provider?: string }) => {
      try {
        const { queryLlmCalls } = await import('../utils/globalDb.js');
        const calls = queryLlmCalls({
          provider: opts.provider,
          limit: parseInt(opts.limit || '20', 10),
        });

        const chalk = (await import('chalk')).default;

        if (calls.length === 0) {
          process.stdout.write(chalk.gray('Még nincsenek naplózott LLM hívások.\n'));
          return;
        }

        process.stdout.write(chalk.bold('📋 Legutóbbi LLM hívások:\n\n'));
        process.stdout.write(
          chalk.gray('  Időpont             Provider     Model              ms     Tokenek  Status\n')
        );
        process.stdout.write(chalk.gray('  ' + '─'.repeat(85) + '\n'));

        for (const c of calls) {
          const status = c.success ? chalk.green('✓') : chalk.red('✗');
          const provider = c.provider.padEnd(12);
          const model = (c.model || 'N/A').padEnd(18).slice(0, 18);
          const duration = String(c.duration_ms).padStart(6);
          const tokens = String(c.total_tokens).padStart(8);
          process.stdout.write(
            `  ${chalk.gray(c.timestamp.slice(0, 19))} ${chalk.blue(provider)} ${model} ${duration} ${tokens}  ${status}\n`
          );
        }

        process.stdout.write(`\n  Összesen: ${chalk.cyan(calls.length)} hívás\n`);
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        process.stderr.write(`Hiba: ${msg}\n`);
        process.exit(1);
      }
    });

  obs
    .command('agent-diagnostics <agentName>')
    .description('Agent diagnosztika és legutóbbi feladatok')
    .option('-n, --limit <count>', 'Maximum elemszám', '10')
    .action(async (agentName: string, opts: { limit?: string }) => {
      try {
        const API_BASE = process.env.BRUNELLA_API_URL || 'http://localhost:3000';
        const ora = (await import('ora')).default;
        const spinner = ora(`Lekérdezem agent: ${agentName}`);
        spinner.start();

        const statusRes = await fetch(`${API_BASE}/api/agents/status`);
        const statusJson = statusRes.ok ? await statusRes.json() : { agents: [] };
        const agents = statusJson.agents || [];
        const agent = agents.find((a: any) => a.name?.toLowerCase() === agentName.toLowerCase());

        const diagRes = await fetch(`${API_BASE}/api/agents/diagnostics`);
        const diags = diagRes.ok ? await diagRes.json() : {};

        const tasksRes = await fetch(`${API_BASE}/api/tasks?limit=${opts.limit || '50'}`);
        const tasksJson = tasksRes.ok ? await tasksRes.json() : { tasks: [] };
        const allTasks = tasksJson.tasks || [];
        const agentTasks = allTasks.filter((t: any) => t.agent && t.agent.toLowerCase() === agentName.toLowerCase()).slice(0, parseInt(opts.limit || '10', 10));

        spinner.succeed('Lekérdezés kész');
        const chalk = (await import('chalk')).default;
        console.log(chalk.bold(`\nAgent diagnostics: ${agentName}\n`));
        if (agent) {
          console.log(chalk.gray(JSON.stringify(agent, null, 2)));
        } else {
          console.log(chalk.yellow('Agent nem található a status listában.'));
        }

        console.log(chalk.bold('\nLegutóbbi feladatok:'));
        if (agentTasks.length === 0) {
          console.log(chalk.gray('  Nincs feladat.'));
        } else {
          for (const t of agentTasks) {
            console.log(chalk.gray(`  #${t.id} [${t.status}] ${t.created_at} ${t.completed_at || ''}`));
            if (t.result) console.log(chalk.dim(`     ${JSON.stringify(typeof t.result === 'string' ? t.result : t.result).slice(0,200)}`));
          }
        }
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        console.error('Hiba:', msg);
        process.exit(1);
      }
    });

  obs
    .command('task-logs <taskId>')
    .description('Task részletes naplók és trace megjelenítése')
    .action(async (taskIdStr: string) => {
      try {
        const API_BASE = process.env.BRUNELLA_API_URL || 'http://localhost:3000';
        const taskId = Number(taskIdStr);
        if (Number.isNaN(taskId)) {
          console.error('Érvénytelen taskId');
          process.exit(1);
        }
        const res = await fetch(`${API_BASE}/api/tasks/${taskId}`);
        if (!res.ok) {
          console.error('Task nem található');
          process.exit(1);
        }
        const data = await res.json();
        const task = data.task;
        const chalk = (await import('chalk')).default;
        console.log(chalk.bold(`\nTask #${taskId} — ${task.agent} — ${task.status}\n`));
        if (task.logs && task.logs.length) {
          for (const log of task.logs) {
            const levelColor = log.level === 'error' ? chalk.red : (log.level === 'warn' ? chalk.yellow : chalk.gray);
            console.log(`${chalk.gray(log.timestamp)} ${levelColor(`[${log.level}]`)} ${log.message}`);
          }
        } else {
          console.log(chalk.gray('Nincsenek naplók a taskhoz.'));
        }
        if (task.result) {
          console.log(chalk.bold('\nResult:\n'), JSON.stringify(task.result, null, 2));
        }
      } catch (e: unknown) {
        const msg = e instanceof Error ? e.message : String(e);
        console.error('Hiba:', msg);
        process.exit(1);
      }
    });
  }

/**
 * RobotkezV2 CLI Commands
 *
 * `brunella robotkez` command group for the RobotkezV2 Agent
 *
 * Commands:
 *  - brunella robotkez chat <instruction>       # Natural language browser automation
 *  - brunella robotkez plan <instruction>       # Preview execution plan
 *  - brunella robotkez exec --action <action>   # Direct browser action
 *  - brunella robotkez status                   # Agent & browser status
 *  - brunella robotkez screenshot               # Take screenshot
 *  - brunella robotkez tasks list               # List background tasks
 *  - brunella robotkez tasks status <id>        # Task status by ID
 *  - brunella robotkez tasks cancel <id>        # Cancel task
 *  - brunella robotkez interactive              # REPL mode
 *
 * @track robotkezv2-full-comet-20260215
 * @phase Phase 7 - CLI Commands
 */

import { Command } from 'commander';
import chalk from 'chalk';
import ora from 'ora';
import inquirer from 'inquirer';
import { readFileSync, writeFileSync } from 'fs';
import { homedir } from 'os';
import { join } from 'path';

const API_BASE = process.env.BRUNELLA_API_URL || 'http://localhost:3000';

/**
 * Fetch helper for CLI → REST API calls
 */
async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
    const url = `${API_BASE}/api/v1/robotkez${path}`;
    const response = await fetch(url, {
        headers: { 'Content-Type': 'application/json' },
        ...options,
    });

    const text = await response.text();
    if (!text) throw new Error(`Empty response from ${path}`);

    const data = JSON.parse(text) as T;

    if (!response.ok) {
        throw new Error((data as any).error || `HTTP ${response.status}`);
    }

    return data;
}

/**
 * Format timestamp (human readable)
 */
function formatTime(timestamp: number): string {
    const date = new Date(timestamp);
    return date.toLocaleString('hu-HU');
}

/**
 * Format duration (ms → seconds)
 */
function formatDuration(ms: number): string {
    return `${(ms / 1000).toFixed(1)}s`;
}

/**
 * Status icon helper
 */
function getStatusIcon(status: string): string {
    switch (status) {
        case 'completed': return '✅';
        case 'running': return '⏳';
        case 'error': return '❌';
        case 'cancelled': return '🚫';
        default: return '⚪';
    }
}

export function registerRobotkezCommands(program: Command) {
    const robotkez = program
        .command('robotkez')
        .alias('rk')
        .description('RobotkezV2 - Magyar Agentic Browser (Comet-style)');

    /**
     * brunella robotkez hybrid <instruction>
     * Direct Python hybrid engine execution (Playwright + Browser-Use)
     */
    robotkez
        .command('hybrid')
        .argument('<instruction>', 'Natural language instruction (e.g., "screenshot github.com")')
        .option('-m, --mode <mode>', 'Execution mode: auto, playwright, browser-use', 'auto')
        .option('--headless', 'Run in headless mode', true)
        .option('--url <url>', 'Target URL')
        .option('--screenshot <path>', 'Screenshot output path')
        .option('--pdf <path>', 'PDF output path')
        .description('Hybrid browser automation (Playwright + Browser-Use)')
        .action(async (instruction: string, options: any) => {
            const spinner = ora(`Executing: "${instruction}" (mode=${options.mode})`).start();

            try {
                // Import agent dynamically (avoid top-level import in CLI)
                const { RobotkezV2Agent } = await import('../agents/RobotkezV2Agent.js');
                const agent = new RobotkezV2Agent();

                // Build context
                const context: any = {
                    mode: options.mode,
                    headless: options.headless
                };
                if (options.url) context.url = options.url;
                if (options.screenshot) context.screenshot_path = options.screenshot;
                if (options.pdf) context.pdf_path = options.pdf;

                // Execute
                const result = await agent.execute(instruction, context);

                if (result.status === 'success') {
                    spinner.succeed(chalk.green('Success!'));
                    console.log(chalk.cyan('\n📝 Result:'));
                    const data = result.data as any;
                    if (data?.mode) console.log(chalk.gray(`   Mode: ${data.mode}`));
                    if (data?.duration_ms) console.log(chalk.gray(`   Duration: ${data.duration_ms}ms`));
                    if (data?.screenshot_path) {
                        console.log(chalk.green(`   Screenshot: ${data.screenshot_path}`));
                    }
                    if (result.message) {
                        console.log(chalk.gray(`   ${result.message}`));
                    }
                } else {
                    spinner.fail(chalk.red('Failed'));
                    console.log(chalk.red(`Error: ${result.error}`));
                    process.exit(1);
                }
            } catch (e: any) {
                spinner.fail(chalk.red('Execution error'));
                console.log(chalk.red(e.message));
                if (e.stack) {
                    console.log(chalk.gray(e.stack));
                }
                process.exit(1);
            }
        });

    /**
     * brunella robotkez chat <instruction>
     * Natural language browser automation
     */
    robotkez
        .command('chat')
        .argument('<instruction>', 'Magyar nyelvű utasítás (pl. "Navigálj a google.com-ra")')
        .description('Természetes nyelvű böngésző automatizálás')
        .action(async (instruction: string) => {
            const spinner = ora(`Feldolgozás: "${instruction}"`).start();

            try {
                const result = await apiFetch<{ success: boolean; message: string; data?: any }>('/chat', {
                    method: 'POST',
                    body: JSON.stringify({ instruction }),
                });

                if (result.success) {
                    spinner.succeed(chalk.green('Feladat végrehajtva!'));
                    console.log(chalk.cyan('\n📝 Eredmény:'), result.message);

                    if (result.data?.taskId) {
                        console.log(chalk.yellow('\n🔄 Háttérben fut...'));
                        console.log(chalk.gray(`   Task ID: ${result.data.taskId}`));
                        console.log(chalk.gray(`   Becsült idő: ${formatDuration(result.data.estimatedDuration || 0)}`));
                    }
                } else {
                    spinner.fail(chalk.red('Hiba történt'));
                    console.log(chalk.red(result.message));
                }
            } catch (e: any) {
                spinner.fail(chalk.red('API hiba'));
                console.log(chalk.red(e.message));
                process.exit(1);
            }
        });

    /**
     * brunella robotkez plan <instruction>
     * Preview execution plan without executing
     */
    robotkez
        .command('plan')
        .argument('<instruction>', 'Magyar nyelvű utasítás')
        .description('Végrehajtási terv előnézete (nincs végrehajtás)')
        .action(async (instruction: string) => {
            const spinner = ora('Terv generálása...').start();

