    /**
     * brunella robotkez status
     * Show agent and browser status
     */
    robotkez
        .command('status')
        .description('Ügynök és böngésző státusz')
        .action(async () => {
            const spinner = ora('Státusz lekérése...').start();

            try {
                const result = await apiFetch<{
                    success: boolean;
