                if (task.error) {
                    console.log(chalk.red(`\n❌ Hiba: ${task.error}`));
                }
            } catch (e: any) {
                spinner.fail(chalk.red('API hiba'));
                console.log(chalk.red(e.message));
                process.exit(1);
            }
        });

    /**
