          console.log(`    Agents: ${c.agentCount} | Leader: ${c.leaderId || '—'}`);
          console.log(`    Tasks: ${c.metrics?.tasksCompleted ?? 0}✓ / ${c.metrics?.tasksFailed ?? 0}✗`);
