export function registerTaskCommands(program: Command) {
    const task = program
        .command('task')
        .description('Természetes nyelvű feladat végrehajtás (magyar nyelven is!)');

    /**
     * brunella task <description>
     * Execute task with natural language
     */
    task
        .argument('[description...]', 'Feladat leírása magyarul (pl. "Keress rá az AI hírekre")')
        .description('Természetes nyelvű feladat végrehajtás')
        .option('-c, --context <json>', 'További kontextus JSON formátumban')
        .option('-i, --interactive', 'Interaktív mód')
        .action(async (descriptionArgs: string[], options: any) => {
            // If no args or --interactive flag, start interactive mode
            if (descriptionArgs.length === 0 || options.interactive) {
                await startInteractiveTaskMode();
                return;
            }

            const description = descriptionArgs.join(' ');
            const spinner = ora(`Feladat végrehajtása: "${description}"`).start();

            try {
                let context: any = {};

                if (options.context) {
                    try {
                        context = JSON.parse(options.context);
                    } catch (e) {
                        spinner.fail(chalk.red('Érvénytelen JSON kontextus'));
                        process.exit(1);
                    }
                }

                const result = await apiFetch<{
                    status: string;
                    result: any;
                    executedAt: string;
                }>('/api/enterprise/execute', {
                    method: 'POST',
                    body: JSON.stringify({
                        task: description,
                        context,
                    }),
                });

                if (result.status === 'success') {
                    spinner.succeed(chalk.green('Feladat végrehajtva!'));
                    formatTaskResult(result.result);
                    console.log(chalk.gray(`\n⏱️  Végrehajtva: ${formatTime(result.executedAt)}`));
                } else {
                    spinner.fail(chalk.red('Hiba történt'));
                    console.log(chalk.red(`\n❌ Státusz: ${result.status}`));
                }
            } catch (e: any) {
                spinner.fail(chalk.red('API hiba'));
                console.log(chalk.red(`\n❌ Hiba: ${e.message}`));
                process.exit(1);
            }
        });

    /**
     * brunella task interactive
     * Interactive task menu
     */
    task
        .command('interactive')
        .alias('i')
        .description('Interaktív feladat végrehajtás mód')
        .action(async () => {
            await startInteractiveTaskMode();
        });

    return task;
}

/**
 * Interactive task mode (menu-driven)
 */
async function startInteractiveTaskMode() {
    console.log(chalk.cyan('\n🧠 Brunella - Természetes Nyelvű Feladat Végrehajtás\n'));
    console.log(chalk.gray('   Magyar nyelven írj bármilyen feladatot!'));
    console.log(chalk.gray('   Példák:'));
    console.log(chalk.gray('     - "Keress rá az AI hírekre"'));
    console.log(chalk.gray('     - "Készíts Python scriptet CSV elemzésre"'));
    console.log(chalk.gray('     - "Ellenőrizd a projekt státuszát"\n'));
    console.log(chalk.gray('   Kilépés: exit, quit, vagy Ctrl+C\n'));

    let running = true;

    while (running) {
        try {
            const { choice } = await inquirer.prompt([
                {
                    type: 'list',
                    name: 'choice',
                    message: 'Mit szeretnél csinálni?',
                    choices: [
                        { name: '✍️  Új feladat megadása', value: 'new' },
                        { name: '📋 Előre definiált feladatok', value: 'predefined' },
                        { name: '❌ Kilépés', value: 'exit' },
                    ],
                },
            ]);

            if (choice === 'exit') {
                console.log(chalk.yellow('\n👋 Viszlát!'));
                running = false;
                break;
            }

            if (choice === 'new') {
                const { task } = await inquirer.prompt([
                    {
                        type: 'input',
                        name: 'task',
                        message: 'Írd le a feladatot magyarul:',
                        validate: (input: string) => {
                            if (!input.trim()) {
                                return 'A feladat leírása nem lehet üres!';
                            }
                            return true;
                        },
                    },
                ]);

                await executeTask(task.trim());
            } else if (choice === 'predefined') {
                const { predefined } = await inquirer.prompt([
                    {
                        type: 'list',
                        name: 'predefined',
                        message: 'Válassz egy feladatot:',
                        choices: [
                            {
                                name: '🔍 Projekt státusz ellenőrzése',
                                value: 'Ellenőrizd a projekt státuszát és add meg a track-ek összefoglalóját',
                            },
                            {
                                name: '📊 Tesztek futtatása',
                                value: 'Futtasd le az összes tesztet és készíts összefoglalót',
                            },
                            {
                                name: '🌐 Webes kutatás',
                                value: 'Keress rá az AI fejlesztések legfrissebb híreire',
                            },
                            {
                                name: '💻 Kód generálás',
                                value: 'Készíts Python scriptet CSV fájl beolvasására és elemzésére',
                            },
                            {
                                name: '🔙 Vissza', value: 'back',
                            },
                        ],
                    },
                ]);

                if (predefined !== 'back') {
                    await executeTask(predefined);
                }
            }
        } catch (e: any) {
            if (e.message?.includes('User force closed')) {
                console.log(chalk.yellow('\n👋 Viszlát!'));
                running = false;
            } else {
                console.log(chalk.red(`\n❌ Hiba: ${e.message}`));
            }
        }
    }
}

/**
 * Execute task helper
 */
async function executeTask(taskDescription: string) {
    const spinner = ora(`Feladat végrehajtása...`).start();

    try {
        const result = await apiFetch<{
            status: string;
            result: any;
            executedAt: string;
        }>('/api/enterprise/execute', {
            method: 'POST',
            body: JSON.stringify({
                task: taskDescription,
                context: {},
            }),
        });

        if (result.status === 'success') {
            spinner.succeed(chalk.green('Feladat végrehajtva!'));
            formatTaskResult(result.result);
            console.log(chalk.gray(`\n⏱️  Végrehajtva: ${formatTime(result.executedAt)}`));

            // Pause for user to see result
            await inquirer.prompt([
                {
                    type: 'input',
                    name: 'continue',
                    message: chalk.gray('Nyomj Enter-t a folytatáshoz...'),
                },
            ]);
        } else {
            spinner.fail(chalk.red('Hiba történt'));
            console.log(chalk.red(`\n❌ Státusz: ${result.status}`));
        }
    } catch (e: any) {
        spinner.fail(chalk.red('API hiba'));
        console.log(chalk.red(`\n❌ Hiba: ${e.message}`));

        // Pause to let user see the error
        await inquirer.prompt([
            {
                type: 'input',
                name: 'continue',
                message: chalk.gray('Nyomj Enter-t a folytatáshoz...'),
            },
        ]);
    }
}

/**
 * Tool Discovery CLI Commands — brunella tools list|info|chain|metrics
 * Track #6: MCP Tool Discovery — Phase 4
 */
import { Command } from 'commander';
import chalk from 'chalk';
import { logError } from '../utils/logger.js';

export function registerToolDiscoveryCommands(program: Command) {
  const toolDiscovery = program
    .command('tool-discovery')
    .description('MCP Tool Discovery — dinamikus tool kezelés');

  toolDiscovery
    .command('list')
    .description('Összes regisztrált tool listázása')
    .option('-t, --tag <tag>', 'Szűrés tag alapján')
    .option('--deprecated', 'Deprecated tool-ok mutatása')
    .action(async (opts: { tag?: string; deprecated?: boolean }) => {
      try {
        let url = 'http://localhost:3000/api/v1/tools/registry';
        const params: string[] = [];
        if (opts.tag) params.push(`tag=${opts.tag}`);
        if (opts.deprecated) params.push('deprecated=true');
        if (params.length) url += `?${params.join('&')}`;

        const res = await fetch(url);
        const data = await res.json();
        console.log(chalk.bold.cyan('\n🔧 MCP Tool Registry\n'));
        if (!Array.isArray(data) || data.length === 0) {
          console.log(chalk.gray('  Nincs regisztrált tool.'));
          return;
        }
        for (const t of data) {
          const deprecated = t.deprecated ? chalk.yellow(' [DEPRECATED]') : '';
          console.log(`  ${chalk.bold(t.name)} v${t.version}${deprecated}`);
          console.log(`    ${chalk.gray(t.description)}`);
          if (t.tags?.length) console.log(`    Tags: ${t.tags.map((tg: string) => chalk.blue(tg)).join(', ')}`);
          console.log('');
        }
        console.log(chalk.gray(`  Összesen: ${data.length} tool`));
      } catch (e) {
        logError('ToolsCLI', `list hiba: ${e}`);
        console.log(chalk.red(`Hiba: ${e}`));
      }
    });

  toolDiscovery
    .command('metrics')
    .description('Tool metrikák lekérdezése')
    .option('-i, --id <toolId>', 'Specifikus tool ID')
    .action(async (opts: { id?: string }) => {
      try {
        const url = opts.id
          ? `http://localhost:3000/api/v1/tools/metrics/${opts.id}`
          : 'http://localhost:3000/api/v1/tools/stats';
        const res = await fetch(url);
        const data = await res.json();
        console.log(chalk.bold.cyan('\n📊 Tool Metrics\n'));
        console.log(JSON.stringify(data, null, 2));
      } catch (e) {
        console.log(chalk.red(`Hiba: ${e}`));
      }
    });

  toolDiscovery
    .command('chain')
    .description('Tool chain futtatása')
    .argument('<steps...>', 'Tool ID-k sorrendben (pl. parser transformer formatter)')
    .option('-i, --input <json>', 'Kezdő input JSON')
    .action(async (steps: string[], opts: { input?: string }) => {
      try {
        const input = opts.input ? JSON.parse(opts.input) : {};
        const res = await fetch('http://localhost:3000/api/v1/tools/chain', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ steps, input }),
        });
        const data = await res.json();
        if (data.success) {
          console.log(chalk.green(`✅ Chain sikeresen lefutott (${data.completedSteps}/${data.totalSteps})`));
          console.log(chalk.gray(JSON.stringify(data.result, null, 2)));
        } else {
          console.log(chalk.red(`❌ Chain hiba a ${data.failedAtStep ?? '?'}. lépésnél`));
          console.log(chalk.red(data.error));
        }
      } catch (e) {
        console.log(chalk.red(`Hiba: ${e}`));
      }
    });
}

/**
 * Tracks CLI Commands (Magyar)
