import type { Command } from "commander";
import chalk from "chalk";
import inquirer from "inquirer";

const API_BASE = process.env.BRUNELLA_API_URL || process.env.API_BASE_URL || "http://localhost:3000";

async function fetchJson<T>(pathName: string, options?: RequestInit): Promise<T> {
  const response = await fetch(`${API_BASE}${pathName}`, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  const data = await response.json() as T & { error?: string };
  if (!response.ok) {
    throw new Error(data.error || `HTTP ${response.status}`);
  }
  return data as T;
}

async function previewTask(task: string, defaultAgent = "Developer"): Promise<void> {
  const response = await fetchJson<{
    success: boolean;
    workflow: { id: string; name: string; nodes: Array<{ id: string; label: string; dependsOn?: string[]; agentName?: string }> };
  }>("/api/v1/tasks/workflow/preview", {
    method: "POST",
    body: JSON.stringify({ task, defaultAgent }),
  });

  console.log(chalk.bold.magenta(`\n🔷 Workflow Preview: ${response.workflow.name}\n`));
  response.workflow.nodes.forEach((node) => {
    console.log(`  ${chalk.white(node.id)} ${node.label}`);
    console.log(`    Agent: ${chalk.gray(node.agentName || "auto")} | DependsOn: ${chalk.gray((node.dependsOn || []).join(", ") || "—")}`);
  });
  console.log("");
}

/**
 * Optional Copilot orchestration stub: if enabled, this can notify Copilot CLI about workflow execution.
 */
import { copilotBridgeState } from "../core/copilotBridgeState.js";
let copilotOrchestrationEnabled = false;

async function runTask(task: string, defaultAgent = "Developer", copilotOrchestrate = false): Promise<void> {
  if (copilotOrchestrate) {
    copilotOrchestrationEnabled = true;
    // Dinamikus agent dispatch naplózása Copilot Bridge-be
    copilotBridgeState.addDispatch({
      agentName: defaultAgent,
      task,
      status: 'queued',
      result: undefined
    });
    console.log(chalk.cyan("[Copilot Orchestration] Workflow orchestration enabled. Dispatch naplózva."));
  }
  const response = await fetchJson<{
    success: boolean;
    result: { status: string; durationMs: number; completedNodeIds: string[]; warnings: string[] };
  }>("/api/v1/tasks/workflow/run", {
    method: "POST",
    body: JSON.stringify({ task, defaultAgent }),
  });

  console.log(chalk.bold.green("\n✅ Workflow futás kész\n"));
  console.log(`  Status:      ${response.result.status}`);
  console.log(`  Időtartam:   ${response.result.durationMs} ms`);
  console.log(`  Node-ok:     ${response.result.completedNodeIds.join(", ") || "—"}`);
  console.log(`  Warnings:    ${response.result.warnings.join(" | ") || "nincs"}\n`);
}

async function showStatus(): Promise<void> {
  const response = await fetchJson<{ workflows: Array<{ id: string; name: string; status: string; nodeCount: number; durationMs?: number; startedAt: string }> }>("/api/v1/tasks/workflow/status");
  console.log(chalk.bold.blue("\n📈 Workflow státuszok\n"));
  if (response.workflows.length === 0) {
    console.log(chalk.gray("  Még nincs workflow futás.\n"));
    return;
  }

  response.workflows.forEach((workflow) => {
    console.log(`  ${chalk.bold(workflow.name)} (${workflow.id})`);
    console.log(`    Status: ${workflow.status} | Node-ok: ${workflow.nodeCount} | Duration: ${workflow.durationMs ?? 0} ms`);
    console.log(`    Start:  ${workflow.startedAt}\n`);
  });
}

export function registerWorkflowCommands(program: Command): void {
  const workflow = program.command("workflow").description("DAG workflow orchestráció parancsok");

  workflow
    .command("preview")
    .description("Workflow preview generálása egy taskból")
    .argument("<task>", "Task szöveg")
    .option("--agent <agent>", "Default agent", "Developer")
    .option("--copilot-orchestrate", "Enable Copilot CLI orchestration")
    .action(async (task: string, options: { agent: string; copilotOrchestrate?: boolean }) => {
      await previewTask(task, options.agent);
      if (options.copilotOrchestrate) {
        console.log(chalk.cyan("[Copilot Orchestration] Preview mode: Copilot orchestration would be triggered here."));
      }
    });

  workflow
    .command("run")
    .description("Workflow futtatása egy taskból")
    .argument("<task>", "Task szöveg")
    .option("--agent <agent>", "Default agent", "Developer")
    .option("--copilot-orchestrate", "Enable Copilot CLI orchestration")
    .action(async (task: string, options: { agent: string; copilotOrchestrate?: boolean }) => {
      await runTask(task, options.agent, options.copilotOrchestrate);
    });

  workflow
    .command("status")
    .description("Workflow futási állapotok listája")
    .action(async () => {
      await showStatus();
    });

  workflow.action(async () => {
    const { action } = await inquirer.prompt([
      {
        type: "list",
        name: "action",
        message: "Workflow menü:",
        choices: [
          { name: "🔍 Preview task → DAG", value: "preview" },
          { name: "▶ Workflow futtatás", value: "run" },
          { name: "📈 Futási állapotok", value: "status" },
          { name: "❌ Kilépés", value: "cancel" },
        ],
      },
    ]);

    if (action === "cancel") return;
    if (action === "status") {
      await showStatus();
      return;
    }

    const answers = await inquirer.prompt([
      {
        type: "input",
        name: "task",
        message: "Task leírás:",
        validate: (value: string) => value.trim().length > 0 || "Adj meg egy feladatot.",
      },
      {
        type: "input",
        name: "agent",
        message: "Default agent:",
        default: "Developer",
      },
    ]);

    if (action === "preview") await previewTask(answers.task, answers.agent);
    if (action === "run") await runTask(answers.task, answers.agent);
  });
}

/**
 * Workspace CLI Commands - Google Workspace Integration
 * 
 * Commands for authenticating and managing Google Workspace API access.
 * 
 * @module cli/workspaceCommands
 */

import { Command } from 'commander';
import chalk from 'chalk';
import ora from 'ora';
import inquirer from 'inquirer';
import { google } from 'googleapis';
import * as fs from 'fs/promises';
import * as path from 'path';
import { existsSync } from 'fs';
import open from 'open';
import { logInfo, logError } from '../utils/logger.js';

const SCOPES = [
  'https://www.googleapis.com/auth/gmail.modify',
  'https://www.googleapis.com/auth/spreadsheets',
  'https://www.googleapis.com/auth/drive',
  'https://www.googleapis.com/auth/calendar',
];

const CONFIG_DIR = path.join(process.cwd(), 'config');
const CREDENTIALS_PATH = path.join(CONFIG_DIR, 'google_credentials.json');
const TOKEN_PATH = path.join(CONFIG_DIR, 'google_token.json');

/**
 * Register workspace commands
 */
export function registerWorkspaceCommands(program: Command): void {
  const workspace = program
    .command('workspace')
    .description('Manage Google Workspace integration');

  // brunella workspace auth
  workspace
    .command('auth')
    .description('Authenticate with Google Workspace APIs')
    .action(async () => {
      console.log(chalk.bold('\n🔐 Google Workspace Authentication\n'));

      // Check if credentials file exists
      if (!existsSync(CREDENTIALS_PATH)) {
        console.log(chalk.red('❌ Google credentials not found!'));
        console.log(
          chalk.yellow(
            `\nPlease download your OAuth 2.0 credentials from Google Cloud Console:`
          )
        );
        console.log(chalk.cyan('   1. Go to https://console.cloud.google.com/apis/credentials'));
        console.log(chalk.cyan('   2. Create OAuth 2.0 Client ID (Desktop app)'));
        console.log(chalk.cyan(`   3. Download JSON and save as:\n      ${CREDENTIALS_PATH}\n`));
        console.log(
          chalk.dim('See docs/GOOGLE_WORKSPACE_SETUP.md for detailed instructions.')
        );
        return;
      }

      try {
        // Create config directory if not exists
        await fs.mkdir(CONFIG_DIR, { recursive: true });

        // Load credentials
        const credContent = await fs.readFile(CREDENTIALS_PATH, 'utf-8');
        const credentials = JSON.parse(credContent);
        const { client_secret, client_id, redirect_uris } =
          credentials.installed || credentials.web;

        const oAuth2Client = new google.auth.OAuth2(
          client_id,
          client_secret,
          redirect_uris[0]
        );

        // Generate auth URL
        const authUrl = oAuth2Client.generateAuthUrl({
          access_type: 'offline',
          scope: SCOPES,
        });

        console.log(chalk.bold('📋 Authorization Steps:\n'));
        console.log(chalk.cyan('1. Opening browser for Google authorization...'));
        console.log(chalk.dim(`   ${authUrl}\n`));

        // Open browser
        await open(authUrl);

        // Prompt for authorization code
        const { code } = await inquirer.prompt([
          {
            type: 'input',
            name: 'code',
            message: 'Paste the authorization code from the browser:',
            validate: (input) => input.length > 0 || 'Code cannot be empty',
          },
        ]);

        const spinner = ora('Exchanging code for tokens...').start();

        // Exchange code for tokens
        const { tokens } = await oAuth2Client.getToken(code);
        oAuth2Client.setCredentials(tokens);

        // Save tokens
        await fs.writeFile(TOKEN_PATH, JSON.stringify(tokens, null, 2));

        spinner.succeed('Tokens saved successfully!');

        console.log(chalk.green('\n✅ Google Workspace authentication complete!\n'));
        console.log(chalk.dim(`Token saved to: ${TOKEN_PATH}`));
        console.log(chalk.dim('This token will be used for all Google API operations.\n'));

        logInfo('WorkspaceCLI', 'Google Workspace authentication successful');
      } catch (error: unknown) {
        const errorMsg = error instanceof Error ? error.message : String(error);
        console.log(chalk.red(`\n❌ Authentication failed: ${errorMsg}\n`));
        logError('WorkspaceCLI', `Auth failed: ${errorMsg}`);
      }
    });

  // brunella workspace status
  workspace
    .command('status')
    .description('Check Google Workspace authentication status')
    .action(async () => {
      console.log(chalk.bold('\n📊 Google Workspace Status\n'));

      const hasCredentials = existsSync(CREDENTIALS_PATH);
      const hasToken = existsSync(TOKEN_PATH);

      console.log(`Credentials: ${hasCredentials ? chalk.green('✔ Found') : chalk.red('✘ Missing')}`);
      console.log(`Token:       ${hasToken ? chalk.green('✔ Found') : chalk.red('✘ Missing')}`);

      if (hasCredentials) {
        console.log(chalk.dim(`  ${CREDENTIALS_PATH}`));
      }
      if (hasToken) {
        console.log(chalk.dim(`  ${TOKEN_PATH}`));

        try {
          const tokenContent = await fs.readFile(TOKEN_PATH, 'utf-8');
          const token = JSON.parse(tokenContent);

          if (token.expiry_date) {
            const expiryDate = new Date(token.expiry_date);
            const now = new Date();
            const isExpired = expiryDate < now;

            console.log(
              `\nToken Status: ${isExpired ? chalk.red('⚠ Expired') : chalk.green('✔ Valid')}`
            );
            console.log(
              chalk.dim(`  Expires: ${expiryDate.toLocaleString()}`)
            );

            if (isExpired) {
              console.log(
                chalk.yellow('\n⚠ Token expired. Run `brunella workspace auth` to re-authenticate.\n')
              );
            }
          }
        } catch (error: unknown) {
          console.log(chalk.yellow('\n⚠ Could not read token file.\n'));
        }
      }

      if (!hasCredentials || !hasToken) {
        console.log(
          chalk.yellow(
            '\n⚠ Not authenticated. Run `brunella workspace auth` to get started.\n'
          )
        );
      } else if (hasToken) {
        console.log(chalk.green('\n✅ Ready to use Google Workspace APIs!\n'));
      }
    });

  // brunella workspace test
  workspace
    .command('test')
    .description('Test Google Workspace API connectivity')
    .action(async () => {
      console.log(chalk.bold('\n🧪 Testing Google Workspace APIs\n'));

      if (!existsSync(TOKEN_PATH)) {
        console.log(chalk.red('❌ Not authenticated. Run `brunella workspace auth` first.\n'));
        return;
      }

      try {
        const credContent = await fs.readFile(CREDENTIALS_PATH, 'utf-8');
        const credentials = JSON.parse(credContent);
        const { client_secret, client_id, redirect_uris } =
          credentials.installed || credentials.web;

        const oAuth2Client = new google.auth.OAuth2(
          client_id,
          client_secret,
          redirect_uris[0]
        );

        const tokenContent = await fs.readFile(TOKEN_PATH, 'utf-8');
        const token = JSON.parse(tokenContent);
        oAuth2Client.setCredentials(token);

        console.log(chalk.cyan('Testing Gmail API...'));
        const gmail = google.gmail({ version: 'v1', auth: oAuth2Client });
        const profile = await gmail.users.getProfile({ userId: 'me' });
        console.log(chalk.green(`✔ Gmail: ${profile.data.emailAddress}`));

        console.log(chalk.cyan('Testing Drive API...'));
        const drive = google.drive({ version: 'v3', auth: oAuth2Client });
        const files = await drive.files.list({ pageSize: 1 });
        console.log(chalk.green(`✔ Drive: Access OK (${files.data.files?.length || 0} files)`));

        console.log(chalk.cyan('Testing Calendar API...'));
        const calendar = google.calendar({ version: 'v3', auth: oAuth2Client });
        const calendars = await calendar.calendarList.list();
        console.log(
          chalk.green(`✔ Calendar: Access OK (${calendars.data.items?.length || 0} calendars)`)
        );

        console.log(chalk.green('\n✅ All Google Workspace APIs are working!\n'));
      } catch (error: unknown) {
        const errorMsg = error instanceof Error ? error.message : String(error);
        console.log(chalk.red(`\n❌ Test failed: ${errorMsg}\n`));
        console.log(
          chalk.yellow('Try running `brunella workspace auth` to re-authenticate.\n')
        );
      }
    });
}

import fetch from 'node-fetch';
import { XMLParser } from 'fast-xml-parser';
import { logInfo, logError } from '../utils/logger.js';
import https from 'https';
import fs from 'fs';

export type NavConfig = {
  baseUrl: string;
  apiKey?: string;
  endpointTemplate?: string; // e.g. '/invoices/{number}'
  basicAuth?: { user: string; pass: string };
  mTLS?: { certPath: string; keyPath: string; passphrase?: string };
  oauth?: { tokenUrl: string; clientId: string; clientSecret: string; scope?: string };
};

async function getOAuthToken(oauth: NonNullable<NavConfig['oauth']>): Promise<string | null> {
  try {
    const body = new URLSearchParams({ grant_type: 'client_credentials', client_id: oauth.clientId, client_secret: oauth.clientSecret });
    if (oauth.scope) body.append('scope', oauth.scope);
    const res = await fetch(oauth.tokenUrl, { method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' }, body: body.toString() });
    if (!res.ok) {
      logError('navClient', `OAuth token fetch failed: ${res.status} ${res.statusText}`);
      return null;
    }
    const json: unknown = await res.json();
    if (typeof json === 'object' && json !== null && 'access_token' in json) {
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      return (json as any).access_token ?? null;
    }
    return null;
  } catch (e) {
    logError('navClient', `getOAuthToken error: ${String(e)}`);
    return null;
  }
}

export async function fetchInvoiceXml(config: NavConfig, invoiceNumber: string): Promise<string | null> {
  try {
    const tpl = config.endpointTemplate || '/invoices/{number}';
    const path = tpl.replace('{number}', encodeURIComponent(invoiceNumber));
    const url = new URL(path, config.baseUrl).toString();
    const headers: Record<string, string> = { 'Accept': 'application/xml' };
    if (config.apiKey) headers['X-API-KEY'] = config.apiKey;

    // OAuth precedence over basic auth
    let agent: https.Agent | undefined;
    if (config.mTLS && config.mTLS.certPath && config.mTLS.keyPath) {
      try {
        agent = new https.Agent({ cert: fs.readFileSync(config.mTLS.certPath), key: fs.readFileSync(config.mTLS.keyPath), passphrase: config.mTLS.passphrase, rejectUnauthorized: true });
      } catch (e) {
        logError('navClient', `Failed to load mTLS cert/key: ${String(e)}`);
      }
    }

    if (config.oauth) {
      const token = await getOAuthToken(config.oauth);
      if (token) headers['Authorization'] = `Bearer ${token}`;
    } else if (config.basicAuth) {
      const tok = Buffer.from(`${config.basicAuth.user}:${config.basicAuth.pass}`).toString('base64');
      headers['Authorization'] = `Basic ${tok}`;
    }

    logInfo('navClient', `Fetching invoice XML ${url}`);
    const res = await fetch(url, { headers, agent } as any);
    if (!res.ok) {
      logError('navClient', `NAV fetch failed: ${res.status} ${res.statusText}`);
      return null;
    }
    const xml = await res.text();
    return xml;
  } catch (e) {
    logError('navClient', `fetchInvoiceXml error: ${String(e)}`);
    return null;
  }
}

export function parseInvoiceXml(xml: string): Record<string, unknown> | null {
  try {
    const parser = new XMLParser({ ignoreAttributes: false, attributeNamePrefix: '@_' });
    const json = parser.parse(xml);
    return json as Record<string, unknown>;
  } catch (e) {
    logError('navClient', `parseInvoiceXml error: ${String(e)}`);
    return null;
  }
}

/**
 * PAIOS Unified Configuration System
 * 
 * Zod-validated YAML configuration for all PAIOS-specific settings.
 * Replaces scattered config from .env, registry.json, and hardcoded values.
 * 
 * @track paios_unified_config_20260223
 */

import { z } from 'zod';
import yaml from 'js-yaml';
import fs from 'fs';
import path from 'path';

// ============================================================================
// ZOD SCHEMAS
// ============================================================================

const ProviderSchema = z.object({
  enabled: z.boolean().default(true),
  model: z.string(),
  api_key_env: z.string().optional(),
  base_url_env: z.string().optional(),
  gateway_url_env: z.string().optional(),
});

export const PAIOSConfigSchema = z.object({
  orchestrator: z.object({
    default_model: z.enum(['github', 'gemini', 'local', 'anthropic', 'cloudflare', 'copilot']).default('github'),
    max_tasks_per_request: z.number().int().min(1).max(20).default(5),
  }),
  providers: z.object({
    github: ProviderSchema.optional(),
    gemini: ProviderSchema.optional(),
    local: ProviderSchema.optional(),
    anthropic: ProviderSchema.optional(),
    cloudflare: ProviderSchema.optional(),
    copilot: ProviderSchema.optional(),
  }),
  phoenix: z.object({
    retry_max_attempts: z.number().int().min(1).max(10).default(3),
    retry_base_delay_ms: z.number().int().min(100).max(10000).default(1000),
    checkpoint_interval_ms: z.number().int().min(5000).max(300000).default(30000),
    heartbeat_interval_ms: z.number().int().min(1000).max(60000).default(5000),
  }).optional(),
  dashboard: z.object({
    base_url: z.string().url().default('http://localhost:5173'),
    chat_panel_enabled: z.boolean().default(true),
    phoenix_events_enabled: z.boolean().default(true),
    model_selector_enabled: z.boolean().default(true),
  }).optional(),
});

export type PAIOSConfig = z.infer<typeof PAIOSConfigSchema>;
export type ProviderConfig = z.infer<typeof ProviderSchema>;
export type ModelProvider = 'github' | 'gemini' | 'local' | 'anthropic' | 'cloudflare' | 'copilot';

// ============================================================================
// CONFIG LOADER
// ============================================================================

let cachedConfig: PAIOSConfig | null = null;

/**
 * Load and validate PAIOS configuration from YAML file.
 * Falls back to sensible defaults if file doesn't exist.
 */
export function loadPaiosConfig(configPath = 'paios.config.yaml'): PAIOSConfig {
  // Return cached config if already loaded
  if (cachedConfig) {
    return cachedConfig;
  }

  const fullPath = path.resolve(process.cwd(), configPath);

  // If config file doesn't exist, use .env fallback
  if (!fs.existsSync(fullPath)) {
    console.warn(`[PAIOS Config] File not found: ${fullPath} - using .env fallback`);
    
    const fallbackConfig = {
      orchestrator: {
        default_model: (process.env.PAIOS_DEFAULT_MODEL as ModelProvider) ?? 'github',
        max_tasks_per_request: 5,
      },
      providers: {
        local: {
          enabled: true,
          model: process.env.OLLAMA_MODEL ?? 'qwen2.5-coder:7b',
          base_url_env: 'OLLAMA_BASE_URL',
        },
        gemini: {
          enabled: !!process.env.GEMINI_API_KEY,
          model: process.env.GEMINI_MODEL ?? 'gemini-2.0-flash-exp',
          api_key_env: 'GEMINI_API_KEY',
        },
      },
    };

    cachedConfig = PAIOSConfigSchema.parse(fallbackConfig);
    return cachedConfig;
  }

  try {
    // Read and parse YAML
    const fileContent = fs.readFileSync(fullPath, 'utf-8');
    const rawConfig = yaml.load(fileContent) as unknown;

    // Validate with Zod
    cachedConfig = PAIOSConfigSchema.parse(rawConfig);
    
    console.log(`[PAIOS Config] Loaded from ${fullPath}`);
    return cachedConfig;
  } catch (error) {
    if (error instanceof z.ZodError) {
      console.error('[PAIOS Config] Validation failed:', error.errors);
      throw new Error(`PAIOS config validation failed: ${error.errors.map(e => e.message).join(', ')}`);
    }
    throw error;
  }
}

/**
 * Get a specific provider configuration.
 * Returns undefined if provider is not configured or disabled.
 */
export function getProviderConfig(provider: ModelProvider): ProviderConfig | undefined {
  const config = loadPaiosConfig();
  const providerConfig = config.providers[provider];
  
  if (!providerConfig || !providerConfig.enabled) {
    return undefined;
  }

  return providerConfig;
}

/**
 * Get the API key for a provider from environment variables.
 */
export function getProviderApiKey(provider: ModelProvider): string | undefined {
  const providerConfig = getProviderConfig(provider);
  if (!providerConfig || !providerConfig.api_key_env) {
    return undefined;
  }

  return process.env[providerConfig.api_key_env];
}

/**
 * Get the base URL for a provider from environment variables.
 */
export function getProviderBaseUrl(provider: ModelProvider): string | undefined {
  const providerConfig = getProviderConfig(provider);
  if (!providerConfig || !providerConfig.base_url_env) {
    return undefined;
  }

  return process.env[providerConfig.base_url_env];
}

/**
 * Clear cached config (useful for tests or hot reload).
 */
export function clearConfigCache(): void {
  cachedConfig = null;
}

/**
 * Get list of enabled providers.
 */
export function getEnabledProviders(): ModelProvider[] {
  const config = loadPaiosConfig();
  const providers: ModelProvider[] = [];

  for (const [key, value] of Object.entries(config.providers)) {
    if (value && value.enabled) {
      providers.push(key as ModelProvider);
    }
  }

  return providers;
}

// ============================================================================
// EXPORTS
// ============================================================================

export default loadPaiosConfig;

/**
 * Code Quality P5: Config Validation with Zod
 *
 * Validates all environment variables at startup, ensuring:
 * - Type safety (strings, numbers, URLs, enums)
 * - Sensible defaults for optional values
 * - Early error detection (fails fast on invalid config)
 *
 * @see conductor/tracks/code_quality_improvements_20260210/spec.md (P5)
 */

import { z } from 'zod';

// ============================================================================
// SCHEMA DEFINITION
// ============================================================================

export const ConfigSchema = z.object({
  // Server
  port: z.coerce.number().int().positive().default(3000),
  nodeEnv: z.enum(['development', 'production', 'test']).default('development'),

  // LLM Providers
  ollamaBaseUrl: z.string().url().default('http://localhost:11434'),
  ollamaModel: z.string().optional(),

  geminiApiKey: z.string().optional(),
  geminiModel: z.string().default('gemini-2.5-flash'),

  githubToken: z.string().optional(),
  githubPat: z.string().optional(), // Alternative to githubToken
  githubModel: z.string().default('gpt-4.1'),
  githubWebhookSecret: z.string().optional(),

  // Python Backend
  pythonBaseUrl: z.string().url().default('http://localhost:8000'),

  // External Services
  anythingllmApiKey: z.string().optional(),
  langchainApiKey: z.string().optional(), // LangSmith tracing

  // Workspace
  workspaceRoot: z.string().default(process.cwd()),
});

export type Config = z.infer<typeof ConfigSchema>;

// ============================================================================
// PARSE & VALIDATE
// ============================================================================

/**
 * Parse and validate environment variables.
 * Throws ZodError if validation fails (with detailed error messages).
 */
function parseConfig(): Config {
  try {
    return ConfigSchema.parse({
      // Server
      port: process.env.PORT,
      nodeEnv: process.env.NODE_ENV,

      // LLM Providers
      ollamaBaseUrl: process.env.OLLAMA_BASE_URL,
      ollamaModel: process.env.OLLAMA_MODEL,

      geminiApiKey: process.env.GEMINI_API_KEY,
      geminiModel: process.env.GEMINI_MODEL,

      githubToken: process.env.GITHUB_TOKEN,
      githubPat: process.env.GITHUB_PAT,
      githubModel: process.env.GITHUB_MODEL,
      githubWebhookSecret: process.env.GITHUB_WEBHOOK_SECRET,

      // Python Backend (normalize PYTHON_SUBSET_URL to pythonBaseUrl)
      pythonBaseUrl: process.env.PYTHON_BASE_URL || process.env.PYTHON_SUBSET_URL,

      // External Services
      anythingllmApiKey: process.env.ANYTHINGLLM_API_KEY,
      langchainApiKey: process.env.LANGCHAIN_API_KEY,

      // Workspace
      workspaceRoot: process.env.BRUNELLA_WORKSPACE_ROOT,
    });
  } catch (error) {
    if (error instanceof z.ZodError) {
      const formattedErrors = error.errors.map(
        (e) => `  - ${e.path.join('.')}: ${e.message}`
      ).join('\n');

      throw new Error(
        `❌ Config Validation Failed:\n${formattedErrors}\n\n` +
        `Please check your .env file or environment variables.`
      );
    }
    throw error;
  }
}

// ============================================================================
// EXPORT VALIDATED CONFIG
// ============================================================================

/**
 * Validated configuration object.
 * Safe to use throughout the application.
 */
export const config = parseConfig();

// Log successful config load (development only)
if (config.nodeEnv === 'development') {
  console.log('✅ Config validated successfully');
  console.log(`   - Port: ${config.port}`);
  console.log(`   - Ollama: ${config.ollamaBaseUrl}`);
  console.log(`   - Python: ${config.pythonBaseUrl}`);
  console.log(`   - Node Env: ${config.nodeEnv}`);
}

import fs from 'fs-extra';
import path from 'path';
import { google } from 'googleapis';
import { logInfo, logError } from '../utils/logger.js';

export type GDriveConfig = {
  keyFile?: string; // service account JSON path
  folderId: string;
  destDir?: string;
};

export async function downloadFilesFromFolder(cfg: GDriveConfig): Promise<Array<{ filename: string; path: string }>> {
  const destDir = cfg.destDir || path.join(process.cwd(), 'data', 'invoices');
  await fs.mkdirp(destDir);

  try {
    const auth = new google.auth.GoogleAuth({ keyFile: cfg.keyFile, scopes: ['https://www.googleapis.com/auth/drive.readonly'] });
    const client = await auth.getClient();
    // Type workaround: Google Drive expects OAuth2Client, but GoogleAuth.getClient() returns AnyAuthClient
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const drive = google.drive({ version: 'v3', auth: client as any });

    const res = await drive.files.list({ q: `'${cfg.folderId}' in parents and trashed=false`, fields: 'files(id,name,mimeType)', pageSize: 500 });
    const files = res.data.files || [];
    logInfo('gdriveConnector', `Found ${files.length} files in folder ${cfg.folderId}`);

    const saved: Array<{ filename: string; path: string }> = [];
    for (const f of files) {
      if (!f.id || !f.name) continue;
      const destPath = path.join(destDir, f.name);
      const streamRes = await drive.files.get({ fileId: f.id, alt: 'media' }, { responseType: 'stream' as any });
      await new Promise((resolve, reject) => {
        const dest = fs.createWriteStream(destPath);
        (streamRes.data as any).on('end', () => { resolve(null); })
          .on('error', (err: unknown) => { reject(err); })
          .pipe(dest);
      });
      saved.push({ filename: f.name, path: destPath });
      logInfo('gdriveConnector', `Saved ${f.name} -> ${destPath}`);
    }

    return saved;
  } catch (e) {
    logError('gdriveConnector', `downloadFilesFromFolder error: ${String(e)}`);
    return [];
  }
}

import { ImapFlow } from 'imapflow';
import fs from 'fs-extra';
import path from 'path';
import { logInfo, logError } from '../utils/logger.js';
import { simpleParser } from 'mailparser';

export type ImapConfig = {
  host: string;
  port?: number;
  secure?: boolean;
  auth: { user: string; pass: string };
  mailbox?: string;
  destDir?: string;
  markSeen?: boolean;
  searchQuery?: any;
};

export async function fetchEmailsAsEml(cfg: ImapConfig): Promise<Array<{ filename: string; path: string; uid?: number; subject?: string }>> {
  const destDir = cfg.destDir || path.join(process.cwd(), 'data', 'invoices');
  await fs.mkdirp(destDir);
  const client = new ImapFlow({
    host: cfg.host,
    port: cfg.port ?? 993,
    secure: cfg.secure ?? true,
    auth: cfg.auth
  });

  try {
    logInfo('imapConnector', `Connecting to IMAP ${cfg.host}`);
    await client.connect();
    const mailbox = cfg.mailbox || 'INBOX';
    await client.mailboxOpen(mailbox);

    const searchQuery = cfg.searchQuery ?? ['UNSEEN'];
    const uids = await client.search(searchQuery);
    logInfo('imapConnector', `Found ${uids.length} messages matching query`);

    const saved: Array<{ filename: string; path: string; uid?: number; subject?: string }> = [];
    if (uids.length === 0) return saved;

    for await (const message of client.fetch(uids, { uid: true, envelope: true, source: true })) {
      try {
        const subject = message.envelope?.subject ?? 'no-subject';
        const safeSubj = subject.replace(/[\\/:*?"<>|]/g, '_').slice(0, 80);
        const filename = `${message.uid}_${safeSubj}.eml`;
        const destPath = path.join(destDir, filename);

        // message.source is a Buffer
        if (message.source) {
          await fs.writeFile(destPath, message.source);
          saved.push({ filename, path: destPath, uid: message.uid, subject });
          logInfo('imapConnector', `Saved message uid=${message.uid} -> ${destPath}`);
        }

        if (cfg.markSeen) {
          try { await client.messageFlagsAdd(message.uid, ['\\Seen']); } catch (err) { /* ignore */ }
        }
      } catch (inner) {
        logError('imapConnector', `Failed to save message: ${String(inner)}`);
      }
    }

    return saved;
  } catch (e) {
    logError('imapConnector', `Error in fetchEmailsAsEml: ${String(e)}`);
    return [];
  } finally {
    try { await client.logout(); } catch (e) { /* ignore */ }
  }
}

export async function fetchAndExtractAttachments(cfg: ImapConfig): Promise<Array<{ filename: string; path: string; uid?: number; subject?: string; contentType?: string; size?: number }>> {
  const destDir = cfg.destDir || path.join(process.cwd(), 'data', 'invoices');
  await fs.mkdirp(destDir);
  const client = new ImapFlow({
    host: cfg.host,
    port: cfg.port ?? 993,
    secure: cfg.secure ?? true,
    auth: cfg.auth
  });

  try {
    logInfo('imapConnector', `Connecting to IMAP ${cfg.host} (attachment extraction)`);
    await client.connect();
    const mailbox = cfg.mailbox || 'INBOX';
    await client.mailboxOpen(mailbox);

    const searchQuery = cfg.searchQuery ?? ['UNSEEN'];
    const uids = await client.search(searchQuery);
    logInfo('imapConnector', `Found ${uids.length} messages matching query`);

    const saved: Array<{ filename: string; path: string; uid?: number; subject?: string; contentType?: string; size?: number }> = [];
    if (uids.length === 0) return saved;

    for await (const message of client.fetch(uids, { uid: true, envelope: true, source: true })) {
      try {
        const subject = message.envelope?.subject ?? 'no-subject';
        const parsed = message.source ? await simpleParser(message.source as Buffer) : null;
        if (parsed && parsed.attachments && parsed.attachments.length) {
          let idx = 0;
          for (const att of parsed.attachments) {
            const fname = att.filename || `attachment_${message.uid}_${idx}`;
            const safe = fname.replace(/[\\/:*?"<>|]/g, '_').slice(0, 160);
            const filename = `${message.uid}_${safe}`;
            const destPath = path.join(destDir, filename);
            await fs.writeFile(destPath, att.content);
            saved.push({ filename, path: destPath, uid: message.uid, subject, contentType: att.contentType, size: att.size });
            logInfo('imapConnector', `Saved attachment for uid=${message.uid} -> ${destPath}`);
            idx++;
          }
        } else {
          // fallback: if no attachments, save the raw message
          if (message.source) {
            const safeSubj = subject.replace(/[\\/:*?"<>|]/g, '_').slice(0, 80);
            const emlName = `${message.uid}_${safeSubj}.eml`;
            const emlPath = path.join(destDir, emlName);
            await fs.writeFile(emlPath, message.source as Buffer);
            saved.push({ filename: emlName, path: emlPath, uid: message.uid, subject });
            logInfo('imapConnector', `Saved raw EML uid=${message.uid} -> ${emlPath}`);
          }
        }

        if (cfg.markSeen) {
          try { await client.messageFlagsAdd(message.uid, ['\\Seen']); } catch (err) { /* ignore */ }
        }
      } catch (inner) {
        logError('imapConnector', `Failed to extract/save attachments: ${String(inner)}`);
      }
    }

    return saved;
  } catch (e) {
    logError('imapConnector', `Error in fetchAndExtractAttachments: ${String(e)}`);
    return [];
  } finally {
    try { await client.logout(); } catch (e) { /* ignore */ }
  }
}

import { v4 as uuidv4 } from "uuid";

export interface RemoteTarget
{
  id: string;
  name: string;
  description: string;
  tags: string[];
}

export interface RemoteCommand
{
  id: string;
  command: string;
  timestamp: number;
  origin: string;
}

export interface RemoteSession
{
  id: string;
  targetId: string;
  initiator: string;
  streamId: string;
  createdAt: number;
  expiresAt: number;
  commands: RemoteCommand[];
  metadata: Record<string, unknown>;
}

const TTL_MS = 1000 * 60 * 10;
const CLEANUP_INTERVAL_MS = 1000 * 30;

class RemoteSessionManager
{
  private targets: Map<string, RemoteTarget> = new Map();
  private sessions: Map<string, RemoteSession> = new Map();

  constructor()
  {
    this.initializeDemoTargets();
    setInterval( () => this.purgeExpiredSessions(), CLEANUP_INTERVAL_MS ).unref();
  }

  private initializeDemoTargets()
  {
    for ( const name of [ "Client VM", "Edge Browser", "Cloud Runner" ] )
    {
      const target: RemoteTarget = {
        id: uuidv4(),
        name,
        description: `Automated remote target ${ name } for monitoring`,
        tags: [ "remote", "console", "stream" ],
      };
      this.targets.set( target.id, target );
    }
  }

  getTargets(): RemoteTarget[]
  {
    return Array.from( this.targets.values() );
  }

  createSession( targetId: string, initiator: string, metadata: Record<string, unknown> = {} ): RemoteSession
  {
    const target = this.targets.get( targetId );
    if ( !target )
    {
      throw new Error( "Target not found" );
    }

    const now = Date.now();
    const session: RemoteSession = {
      id: uuidv4(),
      targetId,
      initiator,
      streamId: uuidv4(),
      createdAt: now,
      expiresAt: now + TTL_MS,
      commands: [],
      metadata,
    };

    this.sessions.set( session.id, session );
    return session;
  }

  appendCommand( sessionId: string, command: string, origin = "service" ): RemoteCommand
  {
    const session = this.sessions.get( sessionId );
    if ( !session )
    {
      throw new Error( "Session not found" );
    }

    const cmd: RemoteCommand = {
      id: uuidv4(),
      command,
      timestamp: Date.now(),
      origin,
    };
    session.commands.push( cmd );
    session.expiresAt = Date.now() + TTL_MS;
    return cmd;
  }

  getSession( id: string ): RemoteSession | null
  {
    return this.sessions.get( id ) ?? null;
  }

  listSessions(): RemoteSession[]
  {
    return Array.from( this.sessions.values() );
  }

  private purgeExpiredSessions()
  {
    const now = Date.now();
    for ( const [ id, session ] of this.sessions.entries() )
    {
      if ( session.expiresAt < now )
      {
        this.sessions.delete( id );
      }
    }
  }
}

export const remoteSessionManager = new RemoteSessionManager();/**
 * Remote Session Manager
 * Manages in-memory remote sessions, commands, and event streams
 *
 * Phase 1: Foundation
 * - Session lifecycle (create, expire, cleanup)
 * - Command queuing and tracking
 * - Event stream for real-time updates
 */

import { v4 as uuidv4 } from 'uuid';
import { logInfo, logError } from '../utils/logger.js';
import type {
  RemoteSession,
  RemoteCommand,
  RemoteTarget,
  RemoteEvent,
} from './types/remote.js';

export class RemoteSessionManager {
  private sessions = new Map<string, RemoteSession>();
  private events = new Map<string, RemoteEvent[]>();
  private sessionTimeout = 3600000; // 1 hour default
  private maxEventsPerSession = 1000;

  /**
   * Create a new remote session
   */
  createSession(
    userId: string,
    targetId: string,
    metadata?: Record<string, any>
  ): RemoteSession {
    const now = Date.now();
    const session: RemoteSession = {
      id: uuidv4(),
      userId,
      targetId,
      createdAt: now,
      expiresAt: now + this.sessionTimeout,
      commands: [],
      active: true,
      metadata,
    };

    this.sessions.set(session.id, session);
    this.events.set(session.id, []);

    logInfo('RemoteSessionManager', `Session created: ${session.id} for target ${targetId}`);
    return session;
  }

  /**
   * Get an existing session
   */
  getSession(sessionId: string): RemoteSession | undefined {
    const session = this.sessions.get(sessionId);
    if (session && session.expiresAt < Date.now()) {
      // Session expired, clean it up
      this.sessions.delete(sessionId);
      this.events.delete(sessionId);
      logInfo('RemoteSessionManager', `Session expired: ${sessionId}`);
      return undefined;
    }
    return session;
  }

  /**
   * Add a command to a session
   */
  addCommand(
    sessionId: string,
    targetId: string,
    toolName: string,
    input: Record<string, any>
  ): RemoteCommand | null {
    const session = this.getSession(sessionId);
    if (!session) {
      logError('RemoteSessionManager', `Session not found: ${sessionId}`);
      return null;
    }

    const command: RemoteCommand = {
      id: uuidv4(),
      sessionId,
      targetId,
      toolName,
      input,
      status: 'pending',
      createdAt: Date.now(),
      updatedAt: Date.now(),
    };

    session.commands.push(command);
    logInfo('RemoteSessionManager', `Command added: ${command.id} to session ${sessionId}`);
    return command;
  }

  /**
   * Update command status
   */
  updateCommandStatus(
    sessionId: string,
    commandId: string,
    status: 'pending' | 'running' | 'completed' | 'failed',
    result?: Record<string, any>,
    error?: string
  ): RemoteCommand | null {
    const session = this.getSession(sessionId);
    if (!session) return null;

    const command = session.commands.find(c => c.id === commandId);
    if (!command) return null;

    command.status = status;
    command.updatedAt = Date.now();
    if (result) command.result = result;
    if (error) command.error = error;

    // Emit event for stream
    this.addEvent(sessionId, {
      id: uuidv4(),
      sessionId,
      type: 'command:status',
      payload: {
        commandId,
        status,
        result,
        error,
      },
      timestamp: Date.now(),
    });

    return command;
  }

  /**
   * Get pending commands for a session
   */
  getPendingCommands(sessionId: string): RemoteCommand[] {
    const session = this.getSession(sessionId);
    if (!session) return [];
    return session.commands.filter(c => c.status === 'pending');
  }

  /**
   * Add an event to the session stream
   */
  addEvent(sessionId: string, event: RemoteEvent): void {
    const events = this.events.get(sessionId) || [];
    events.push(event);

    // Keep only recent events
    if (events.length > this.maxEventsPerSession) {
      events.splice(0, events.length - this.maxEventsPerSession);
    }

    this.events.set(sessionId, events);
  }

  /**
   * Get events since a given timestamp
   */
  getEventsSince(sessionId: string, timestamp: number): RemoteEvent[] {
    const events = this.events.get(sessionId) || [];
    return events.filter(e => e.timestamp > timestamp);
  }

  /**
   * Close a session
   */
  closeSession(sessionId: string): void {
    const session = this.getSession(sessionId);
    if (session) {
      session.active = false;
      this.addEvent(sessionId, {
        id: uuidv4(),
        sessionId,
        type: 'stream:closed',
        payload: { reason: 'session_closed' },
        timestamp: Date.now(),
      });
      logInfo('RemoteSessionManager', `Session closed: ${sessionId}`);
    }
  }

  /**
   * Cleanup expired sessions
   */
  cleanupExpiredSessions(): void {
    const now = Date.now();
    let cleanedCount = 0;

    for (const [sessionId, session] of this.sessions.entries()) {
      if (session.expiresAt < now) {
        this.sessions.delete(sessionId);
        this.events.delete(sessionId);
        cleanedCount++;
      }
    }

    if (cleanedCount > 0) {
      logInfo('RemoteSessionManager', `Cleaned up ${cleanedCount} expired sessions`);
    }
  }

  /**
   * Get all active sessions (for debugging)
   */
  getActiveSessions(): RemoteSession[] {
    const now = Date.now();
    return Array.from(this.sessions.values()).filter(
      s => s.active && s.expiresAt > now
    );
  }
}

// Singleton instance
export const remoteSessionManager = new RemoteSessionManager();

// Cleanup expired sessions every 5 minutes
setInterval(() => {
  remoteSessionManager.cleanupExpiredSessions();
}, 5 * 60 * 1000);

import { existsSync } from 'fs';
import path from 'path';
import { getBifrostGateway, type ProviderHealth, type ProviderType } from './bifrost_gateway.js';
import { GraphRagEngine } from './graphRagEngine.js';
import { ReflectionEngine } from './reflectionEngine.js';
import { HybridMemory } from '../utils/rag.js';

export type AssistantReadinessStatus = 'ready' | 'partial' | 'planned';

export interface AssistantCapability {
  id: string;
  title: string;
  status: AssistantReadinessStatus;
  score: number;
  summary: string;
  details: string[];
  evidence?: Record<string, unknown>;
}

export interface AssistantArchitectureLayer {
  id: string;
  title: string;
  summary: string;
  modules: string[];
  purpose: string;
  nextUpgrade?: string;
}

export interface AssistantRoadmapPhase {
  id: string;
  title: string;
  goal: string;
  deliverables: string[];
}

export interface AssistantBlueprint {
  assistantName: string;
  targetPlatform: string;
  generatedAt: string;
  recommendedMode: {
    primaryCloudProvider: ProviderType | 'github';
    localFallbackProvider: ProviderType | 'ollama';
    desktopShell: string;
    recommendation: string;
