  const indexedDocuments = await hybridMemory.getTableCount().catch(() => 0);

  const hasTauriShell = existsSync(rootPath('src-tauri', 'tauri.conf.json'));
  const hasVoiceRoute = existsSync(rootPath('src', 'server', 'routes', 'voice.ts'));
