export const bifrostGateway: BifrostGateway = getBifrostGateway();

/**
 * Checkpoint System — Gold Protocol Phoenix (RULE-PH1, RULE-PH5)
 *
 * Partial-task state persistence via SQLite.
 * Enables resume-from-last-success after agent failure.
 *
 * Non-functional: < 5 ms per save (SQLite WAL mode).
 *
 * @version 1.0.0
 */

import { logInfo, logError } from '../utils/logger.js';

// ---------------------------------------------------------------------------
// TYPES
// ---------------------------------------------------------------------------

export interface Checkpoint {
  id?: number;
  taskId: string;
  stepIndex: number;
  stepName: string;
  stateJson: string;
  createdAt?: string;
}

export interface CheckpointState {
  /** Arbitrary agent-defined state blob */
  [key: string]: unknown;
}

// ---------------------------------------------------------------------------
// DATABASE (lazy singleton)
// ---------------------------------------------------------------------------

let db: any = null;

async function getDb(): Promise<any> {
  if (db) return db;

  if (typeof process === 'undefined' || !process.versions?.node) {
    return null;
  }

  const path = await import('path');
  const fs = await import('fs');

  const dbDir = path.default.join(process.cwd(), 'data');
  if (!fs.default.existsSync(dbDir)) {
    fs.default.mkdirSync(dbDir, { recursive: true });
  }

  const dbPath = path.default.join(dbDir, 'checkpoints.db');
  const Database = (await import('better-sqlite3')).default;
  db = new Database(dbPath);

  // WAL mode for concurrent reads + low-latency writes (spec: < 5ms)
  db.pragma('journal_mode = WAL');

  db.exec(`
    CREATE TABLE IF NOT EXISTS checkpoints (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      task_id TEXT NOT NULL,
      step_index INTEGER NOT NULL,
      step_name TEXT NOT NULL,
      state_json TEXT NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP
    );
    CREATE INDEX IF NOT EXISTS idx_checkpoints_task_id ON checkpoints(task_id);
    CREATE INDEX IF NOT EXISTS idx_checkpoints_task_step ON checkpoints(task_id, step_index);
  `);

  logInfo('Checkpoint', 'Database initialized (WAL mode)');
  return db;
}

// ---------------------------------------------------------------------------
// PUBLIC API
// ---------------------------------------------------------------------------

/**
 * Save a checkpoint after a successful sub-step (RULE-PH1).
 */
export async function saveCheckpoint(
  taskId: string,
  stepIndex: number,
  stepName: string,
  state: CheckpointState
): Promise<number | null> {
  try {
    const database = await getDb();
    if (!database) return null;

    const stateJson = JSON.stringify(state);
    const stmt = database.prepare(
      'INSERT INTO checkpoints (task_id, step_index, step_name, state_json) VALUES (?, ?, ?, ?)'
    );
    const result = stmt.run(taskId, stepIndex, stepName, stateJson);

    logInfo('Checkpoint', `Saved: task=${taskId} step=${stepIndex} (${stepName})`);
    return result.lastInsertRowid as number;
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('Checkpoint', `Save failed: ${msg}`);
    return null;
  }
}

/**
 * Load the latest checkpoint for a task (RULE-PH5).
 * Returns the checkpoint with the highest step_index.
 */
export async function loadCheckpoint(taskId: string): Promise<Checkpoint | null> {
  try {
    const database = await getDb();
    if (!database) return null;

    const stmt = database.prepare(
      'SELECT * FROM checkpoints WHERE task_id = ? ORDER BY step_index DESC LIMIT 1'
    );
    const row = stmt.get(taskId) as any;

    if (!row) return null;

    return {
      id: row.id,
      taskId: row.task_id,
      stepIndex: row.step_index,
      stepName: row.step_name,
      stateJson: row.state_json,
      createdAt: row.created_at
    };
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('Checkpoint', `Load failed: ${msg}`);
    return null;
  }
}

/**
 * Load all checkpoints for a task, ordered by step_index ascending.
 */
export async function loadAllCheckpoints(taskId: string): Promise<Checkpoint[]> {
  try {
    const database = await getDb();
    if (!database) return [];

    const stmt = database.prepare(
      'SELECT * FROM checkpoints WHERE task_id = ? ORDER BY step_index ASC'
    );
    const rows = stmt.all(taskId) as any[];

    return rows.map((row: any) => ({
      id: row.id,
      taskId: row.task_id,
      stepIndex: row.step_index,
      stepName: row.step_name,
      stateJson: row.state_json,
      createdAt: row.created_at
    }));
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('Checkpoint', `LoadAll failed: ${msg}`);
    return [];
  }
}

/**
 * Clear all checkpoints for a completed task.
 */
export async function clearCheckpoints(taskId: string): Promise<boolean> {
  try {
    const database = await getDb();
    if (!database) return false;

    const stmt = database.prepare('DELETE FROM checkpoints WHERE task_id = ?');
    const result = stmt.run(taskId);

    logInfo('Checkpoint', `Cleared ${result.changes} checkpoints for task=${taskId}`);
    return true;
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('Checkpoint', `Clear failed: ${msg}`);
    return false;
  }
}

/**
 * List active checkpoints (latest per task).
 * Useful for dashboard /api/phoenix/checkpoints endpoint.
 */
export async function listActiveCheckpoints(): Promise<Checkpoint[]> {
  try {
    const database = await getDb();
    if (!database) return [];

    const stmt = database.prepare(`
      SELECT c.* FROM checkpoints c
      INNER JOIN (
        SELECT task_id, MAX(step_index) as max_step
        FROM checkpoints
        GROUP BY task_id
      ) latest ON c.task_id = latest.task_id AND c.step_index = latest.max_step
      ORDER BY c.created_at DESC
    `);
    const rows = stmt.all() as any[];

    return rows.map((row: any) => ({
      id: row.id,
      taskId: row.task_id,
      stepIndex: row.step_index,
      stepName: row.step_name,
      stateJson: row.state_json,
      createdAt: row.created_at
    }));
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('Checkpoint', `ListActive failed: ${msg}`);
    return [];
  }
}

/**
 * Get checkpoint database stats.
 */
export async function getCheckpointStats(): Promise<{
  totalCheckpoints: number;
  activeTasks: number;
}> {
  try {
    const database = await getDb();
    if (!database) return { totalCheckpoints: 0, activeTasks: 0 };

    const total = database.prepare('SELECT COUNT(*) as count FROM checkpoints').get() as any;
    const tasks = database.prepare('SELECT COUNT(DISTINCT task_id) as count FROM checkpoints').get() as any;

    return {
      totalCheckpoints: total?.count || 0,
      activeTasks: tasks?.count || 0
    };
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('Checkpoint', `Stats failed: ${msg}`);
    return { totalCheckpoints: 0, activeTasks: 0 };
  }
}

/**
 * Clean up old checkpoints (retention policy: 7 days).
 * Deletes checkpoints older than the specified number of days.
 */
export async function cleanupOldCheckpoints(retentionDays: number = 7): Promise<number> {
  try {
    const database = await getDb();
    if (!database) return 0;

    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - retentionDays);
    const cutoffIso = cutoffDate.toISOString();

    const stmt = database.prepare('DELETE FROM checkpoints WHERE created_at < ?');
    const result = stmt.run(cutoffIso);

    const deleted = result.changes || 0;
    if (deleted > 0) {
      logInfo('Checkpoint', `Cleaned up ${deleted} checkpoints older than ${retentionDays} days`);
    }

    return deleted;
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('Checkpoint', `Cleanup failed: ${msg}`);
    return 0;
  }
}

/**
 * Start automatic checkpoint cleanup (daily at 3 AM).
 * Returns cleanup interval handle.
 */
export function startAutomaticCleanup(retentionDays: number = 7): NodeJS.Timeout {
  const DAILY_MS = 24 * 60 * 60 * 1000;

  logInfo('Checkpoint', `Starting automatic cleanup (retention: ${retentionDays} days)`);

  // Run cleanup immediately
  cleanupOldCheckpoints(retentionDays);

  // Schedule daily cleanup
  return setInterval(() => {
    cleanupOldCheckpoints(retentionDays);
  }, DAILY_MS);
}

/**
 * Clear ALL checkpoints (for testing purposes only).
 * WARNING: This deletes all checkpoint data!
 */
export async function clearAllCheckpoints(): Promise<number> {
  try {
    const database = await getDb();
    if (!database) return 0;

    const stmt = database.prepare('DELETE FROM checkpoints');
    const result = stmt.run();

    const deleted = result.changes || 0;
    if (deleted > 0) {
      logInfo('Checkpoint', `Cleared ALL ${deleted} checkpoints`);
    }

    return deleted;
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('Checkpoint', `ClearAll failed: ${msg}`);
    return 0;
  }
}

/** Close checkpoint database (for tests / graceful shutdown). */
export async function closeCheckpointDb(): Promise<void> {
  if (db) {
    db.close();
    db = null;
  }
}

// FILE: src/core/codebaseIndexer.ts
// PURPOSE: G4.2 — Proactive codebase indexing into LanceDB via Ollama embeddings
// Periodically scans .ts, .py, .md files, chunks them, and indexes via Python backend.

import { logInfo, logError } from '../utils/logger.js';
import { aiGateway } from '../utils/aiGateway.js';

// ============================================================================
// TYPES
// ============================================================================

export interface IndexStats {
  fileCount: number;
  chunkCount: number;
  durationMs: number;
  skippedFiles: number;
  errors: string[];
}

export interface ChunkInfo {
  filePath: string;
  content: string;
  startLine: number;
  endLine: number;
}

export interface IndexerConfig {
  rootDir: string;
  extensions: string[];
  chunkSize: number;         // characters per chunk
  chunkOverlap: number;      // overlap between chunks
  excludeDirs: string[];
  maxFileSize: number;       // bytes
}

// ============================================================================
// CONFIGURATION
// ============================================================================

const PYTHON_BASE_URL = process.env.PYTHON_BASE_URL || 'http://localhost:8000';
const EMBED_MODEL = process.env.EMBED_MODEL || 'nomic-embed-text';

const DEFAULT_CONFIG: IndexerConfig = {
  rootDir: process.cwd(),
  extensions: ['.ts', '.py', '.md', '.tsx', '.jsx'],
  chunkSize: 500,
  chunkOverlap: 100,
  excludeDirs: [
    'node_modules', '.git', 'build', 'dist', '__pycache__',
    '_archive', '_br_temp', 'agentenv', '.venv', 'data',
    'external_research', '_KNOWLEDGE_BASE', 'logs'
  ],
  maxFileSize: 100 * 1024 // 100KB
};

// ============================================================================
// SCHEDULING STATE
// ============================================================================

let schedulerInterval: ReturnType<typeof setInterval> | null = null;
let lastIndexTime: number = 0;
let lastIndexStats: IndexStats | null = null;

// ============================================================================
// CHUNKING
// ============================================================================

/**
 * Split file content into overlapping chunks.
 */
export function chunkContent(content: string, filePath: string, config: Partial<IndexerConfig> = {}): ChunkInfo[] {
  const chunkSize = config.chunkSize ?? DEFAULT_CONFIG.chunkSize;
  const overlap = config.chunkOverlap ?? DEFAULT_CONFIG.chunkOverlap;
  const chunks: ChunkInfo[] = [];

  const lines = content.split('\n');
  let currentChunk = '';
  let startLine = 1;
  let currentLine = 1;

  for (const line of lines) {
    currentChunk += line + '\n';

    if (currentChunk.length >= chunkSize) {
      chunks.push({
        filePath,
        content: currentChunk.trim(),
        startLine,
        endLine: currentLine
      });

      // Calculate overlap: keep last N characters for context continuity
      const overlapStart = Math.max(0, currentChunk.length - overlap);
      const overlapText = currentChunk.slice(overlapStart);
      currentChunk = overlapText;
      startLine = Math.max(1, currentLine - overlapText.split('\n').length + 1);
    }
    currentLine++;
  }

  // Remaining content
  if (currentChunk.trim().length > 0) {
    chunks.push({
      filePath,
      content: currentChunk.trim(),
      startLine,
      endLine: currentLine - 1
    });
  }

  return chunks;
}

// ============================================================================
// FILE DISCOVERY
// ============================================================================

/**
 * Discover indexable files recursively.
 * Requires Node.js runtime for fs/path.
 */
async function discoverFiles(config: IndexerConfig): Promise<string[]> {
  if (typeof process === 'undefined' || !process.versions?.node) {
    return [];
  }

  const fs = await import('fs');
  const path = await import('path');
  const files: string[] = [];

  function walkDir(dir: string): void {
    try {
      const entries = fs.default.readdirSync(dir, { withFileTypes: true });

      for (const entry of entries) {
        const fullPath = path.default.join(dir, entry.name);

        if (entry.isDirectory()) {
          // Skip excluded directories
          if (config.excludeDirs.includes(entry.name)) continue;
          if (entry.name.startsWith('.')) continue;
          walkDir(fullPath);
        } else if (entry.isFile()) {
          const ext = path.default.extname(entry.name);
          if (!config.extensions.includes(ext)) continue;

          // Skip large files
          try {
            const stat = fs.default.statSync(fullPath);
            if (stat.size > config.maxFileSize) continue;
          } catch {
            continue;
          }

          files.push(fullPath);
        }
      }
    } catch (error) {
      // Skip unreadable directories
    }
  }

  walkDir(config.rootDir);
  return files;
}

// ============================================================================
// GIT DIFF BASED DISCOVERY
// ============================================================================

/**
 * Get changed files since last index using git diff.
 */
async function getChangedFiles(sinceTimestamp: number): Promise<string[]> {
  if (typeof process === 'undefined' || !process.versions?.node) {
    return [];
  }

  try {
    const { execSync } = await import('child_process');
    const sinceDate = new Date(sinceTimestamp).toISOString();
    const output = execSync(`git diff --name-only --diff-filter=ACMR HEAD`, {
      encoding: 'utf-8',
      timeout: 10000,
      cwd: process.cwd()
    }).trim();

    if (!output) return [];

    const path = await import('path');
    return output.split('\n')
      .filter(f => DEFAULT_CONFIG.extensions.some(ext => f.endsWith(ext)))
      .map(f => path.default.resolve(process.cwd(), f));
  } catch {
    return [];
  }
}

// ============================================================================
// EMBEDDING
// ============================================================================

/**
 * Generate embedding for a text chunk using Ollama's embedding API (via AI Gateway if enabled).
 */
async function generateEmbedding(text: string): Promise<number[] | null> {
  try {
    // Use AI Gateway wrapper for embeddings (v3.0 pure fetch)
    const embedding = await aiGateway.embeddings(text, {
      model: EMBED_MODEL
    });

    return embedding || null;
  } catch {
    return null;
  }
}

// ============================================================================
// CORE INDEXING
// ============================================================================

/**
 * Index the full codebase.
 * Reads all matching files, chunks them, and sends to Python backend for LanceDB storage.
 */
export async function indexCodebase(config: Partial<IndexerConfig> = {}): Promise<IndexStats> {
  const cfg: IndexerConfig = { ...DEFAULT_CONFIG, ...config };
  const startTime = Date.now();
  const stats: IndexStats = { fileCount: 0, chunkCount: 0, durationMs: 0, skippedFiles: 0, errors: [] };

  logInfo('CodebaseIndexer', `Starting full index of ${cfg.rootDir}...`);

  try {
    const files = await discoverFiles(cfg);
    const fs = await import('fs');

    for (const filePath of files) {
      try {
        const content = fs.default.readFileSync(filePath, 'utf-8');
        const chunks = chunkContent(content, filePath, cfg);

        if (chunks.length === 0) {
          stats.skippedFiles++;
          continue;
        }

        stats.fileCount++;
        stats.chunkCount += chunks.length;

        // Send chunks to Python backend for batch indexing
        await sendChunksToPython(chunks).catch((err: Error) => {
          stats.errors.push(`${filePath}: ${err.message}`);
        });
      } catch (error: unknown) {
        stats.skippedFiles++;
        const msg = error instanceof Error ? error.message : String(error);
        stats.errors.push(`${filePath}: ${msg}`);
      }
    }

    stats.durationMs = Date.now() - startTime;
    lastIndexTime = Date.now();
    lastIndexStats = { ...stats };

    logInfo('CodebaseIndexer', `Index complete: ${stats.fileCount} files, ${stats.chunkCount} chunks in ${stats.durationMs}ms`);
    return stats;
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('CodebaseIndexer', `Index failed: ${msg}`);
    stats.durationMs = Date.now() - startTime;
    stats.errors.push(msg);
    return stats;
  }
}

/**
 * Re-index only changed files (git diff based).
 */
export async function reindexChangedFiles(): Promise<IndexStats> {
  const startTime = Date.now();
  const stats: IndexStats = { fileCount: 0, chunkCount: 0, durationMs: 0, skippedFiles: 0, errors: [] };

  logInfo('CodebaseIndexer', 'Starting incremental reindex (git diff)...');

  try {
    const changedFiles = await getChangedFiles(lastIndexTime || 0);

    if (changedFiles.length === 0) {
      logInfo('CodebaseIndexer', 'No changed files to reindex');
      stats.durationMs = Date.now() - startTime;
      return stats;
    }

    const fs = await import('fs');

    for (const filePath of changedFiles) {
      try {
        if (!fs.default.existsSync(filePath)) {
          stats.skippedFiles++;
          continue;
        }

        const content = fs.default.readFileSync(filePath, 'utf-8');
        const chunks = chunkContent(content, filePath);

        stats.fileCount++;
        stats.chunkCount += chunks.length;

        await sendChunksToPython(chunks).catch((err: Error) => {
          stats.errors.push(`${filePath}: ${err.message}`);
        });
      } catch (error: unknown) {
        stats.skippedFiles++;
      }
    }

    stats.durationMs = Date.now() - startTime;
    lastIndexTime = Date.now();
    lastIndexStats = { ...stats };

    logInfo('CodebaseIndexer', `Reindex complete: ${stats.fileCount} files, ${stats.chunkCount} chunks in ${stats.durationMs}ms`);
    return stats;
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('CodebaseIndexer', `Reindex failed: ${msg}`);
    stats.durationMs = Date.now() - startTime;
    stats.errors.push(msg);
    return stats;
  }
}

// ============================================================================
// PYTHON BACKEND COMMUNICATION
// ============================================================================

/**
 * Send chunks to Python backend for LanceDB indexing.
 */
async function sendChunksToPython(chunks: ChunkInfo[]): Promise<void> {
  const response = await fetch(`${PYTHON_BASE_URL}/index/batch`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      chunks: chunks.map(c => ({
        file_path: c.filePath,
        content: c.content,
        start_line: c.startLine,
        end_line: c.endLine
      }))
    })
  });

  if (!response.ok) {
    throw new Error(`Python index API error: ${response.status}`);
  }
}

// ============================================================================
// SCHEDULER
// ============================================================================

/**
 * Start periodic reindexing.
 * @param intervalMinutes — how often to reindex (default: 30)
 */
export function scheduleReindex(intervalMinutes: number = 30): void {
  if (schedulerInterval) {
    clearInterval(schedulerInterval);
  }

  const intervalMs = intervalMinutes * 60 * 1000;
  schedulerInterval = setInterval(() => {
    reindexChangedFiles().catch((err: Error) => {
      logError('CodebaseIndexer', `Scheduled reindex failed: ${err.message}`);
    });
  }, intervalMs);

  logInfo('CodebaseIndexer', `Scheduled reindex every ${intervalMinutes} minutes`);
}

/**
 * Stop periodic reindexing.
 */
export function stopScheduledReindex(): void {
  if (schedulerInterval) {
    clearInterval(schedulerInterval);
    schedulerInterval = null;
    logInfo('CodebaseIndexer', 'Scheduled reindex stopped');
  }
}

// ============================================================================
// STATUS API
// ============================================================================

/**
 * Get index status for dashboard/API.
 */
export function getIndexStatus(): { lastIndexTime: number; lastStats: IndexStats | null; schedulerActive: boolean } {
  return {
    lastIndexTime,
    lastStats: lastIndexStats ? { ...lastIndexStats } : null,
    schedulerActive: schedulerInterval !== null
  };
}

/**
 * CollectiveMind — Shared collective reasoning across the agent ecosystem
 * Phase 6: Evolutionary Collective Intelligence
 *
 * Aggregates insights from all agents, swarms, and subsystems into a
 * shared reasoning layer. Provides consensus-building, conflict detection,
 * and synthesized perspectives for complex decisions.
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn } from '../utils/logger.js';

export interface Perspective {
  id: string;
  sourceId: string;            // agent, swarm, or subsystem ID
  sourceType: 'agent' | 'swarm' | 'subsystem' | 'user';
  topic: string;
  stance: string;              // the position or insight
  confidence: number;          // 0–1
  evidence: string[];
  tags: string[];
  createdAt: number;
}

export interface ConsensusResult {
  topic: string;
  perspectives: Perspective[];
  consensusReached: boolean;
  dominantStance: string;
  avgConfidence: number;
  conflictingViews: Array<{ a: Perspective; b: Perspective; reason: string }>;
  synthesis: string;
  timestamp: number;
}

export interface CollectiveQuery {
  topic: string;
  context?: Record<string, unknown>;
  minConfidence?: number;
  maxPerspectives?: number;
}

export class CollectiveMind extends EventEmitter {
  private perspectives = new Map<string, Perspective>();
  private perspectiveCounter = 0;

  /** Submit a perspective from any source */
  submit(input: Omit<Perspective, 'id' | 'createdAt'>): Perspective {
    const perspective: Perspective = {
      ...input,
      id: `persp-${++this.perspectiveCounter}-${Date.now()}`,
      createdAt: Date.now(),
    };
    this.perspectives.set(perspective.id, perspective);
    logInfo('CollectiveMind', `Perspective from ${input.sourceId} on "${input.topic}": ${input.stance.substring(0, 60)}`);
    this.emit('perspective:submitted', perspective);
    return perspective;
  }

  /** Remove a perspective */
  remove(perspectiveId: string): boolean {
    return this.perspectives.delete(perspectiveId);
  }

  /** Build consensus on a topic */
  buildConsensus(query: CollectiveQuery): ConsensusResult {
    const minConf = query.minConfidence ?? 0;
    const maxP = query.maxPerspectives ?? 50;
    const topicLower = query.topic.toLowerCase();

    // Gather relevant perspectives
    const relevant = Array.from(this.perspectives.values())
      .filter(p => {
        if (p.confidence < minConf) return false;
        const matches = p.topic.toLowerCase().includes(topicLower) ||
          p.tags.some(t => topicLower.includes(t.toLowerCase()));
        return matches;
      })
      .sort((a, b) => b.confidence - a.confidence)
      .slice(0, maxP);

    if (relevant.length === 0) {
      return {
        topic: query.topic,
        perspectives: [],
        consensusReached: false,
        dominantStance: '',
        avgConfidence: 0,
        conflictingViews: [],
        synthesis: 'No relevant perspectives found.',
        timestamp: Date.now(),
      };
    }

    // Group by stance similarity (simple string-based grouping)
    const stanceGroups = new Map<string, Perspective[]>();
    for (const p of relevant) {
      const key = p.stance.toLowerCase().substring(0, 30);
      const group = stanceGroups.get(key) || [];
      group.push(p);
      stanceGroups.set(key, group);
    }

    // Find dominant stance
    let dominantKey = '';
    let dominantCount = 0;
    for (const [key, group] of stanceGroups) {
      if (group.length > dominantCount) {
        dominantCount = group.length;
        dominantKey = key;
      }
    }

    const dominantStance = stanceGroups.get(dominantKey)?.[0]?.stance ?? '';
    const avgConfidence = relevant.reduce((s, p) => s + p.confidence, 0) / relevant.length;

    // Detect conflicts: perspectives on same topic with very different stances
    const conflicts: Array<{ a: Perspective; b: Perspective; reason: string }> = [];
    const groups = Array.from(stanceGroups.values());
    for (let i = 0; i < groups.length; i++) {
      for (let j = i + 1; j < groups.length; j++) {
        conflicts.push({
          a: groups[i][0],
          b: groups[j][0],
          reason: `Different stances: "${groups[i][0].stance.substring(0, 40)}" vs "${groups[j][0].stance.substring(0, 40)}"`,
        });
      }
    }

    const consensusReached = stanceGroups.size === 1 || (dominantCount / relevant.length) >= 0.7;

    const synthesis = consensusReached
      ? `Consensus reached: "${dominantStance}" (${dominantCount}/${relevant.length} perspectives, avg confidence ${avgConfidence.toFixed(2)})`
      : `No consensus: ${stanceGroups.size} distinct stances across ${relevant.length} perspectives`;

    const result: ConsensusResult = {
      topic: query.topic,
      perspectives: relevant,
      consensusReached,
      dominantStance,
      avgConfidence,
      conflictingViews: conflicts,
      synthesis,
      timestamp: Date.now(),
    };

    this.emit('consensus:built', result);
    return result;
  }

  /** Get perspectives for a specific source */
  getBySource(sourceId: string): Perspective[] {
    return Array.from(this.perspectives.values()).filter(p => p.sourceId === sourceId);
  }

  /** Get all perspectives on a topic */
  getByTopic(topic: string): Perspective[] {
    const t = topic.toLowerCase();
    return Array.from(this.perspectives.values()).filter(p => p.topic.toLowerCase().includes(t));
  }

  /** Get stats */
  getStats(): { total: number; bySouce: Record<string, number>; avgConfidence: number; topics: number } {
    const bySource: Record<string, number> = {};
    const topics = new Set<string>();
    let totalConf = 0;

    for (const p of this.perspectives.values()) {
      bySource[p.sourceType] = (bySource[p.sourceType] ?? 0) + 1;
      topics.add(p.topic);
      totalConf += p.confidence;
    }

    return {
      total: this.perspectives.size,
      bySouce: bySource,
      avgConfidence: this.perspectives.size > 0 ? totalConf / this.perspectives.size : 0,
      topics: topics.size,
    };
  }
}

/**
 * Dynamic Tool Registry — Runtime tool publication, versioning, and metrics
 * Track #6: MCP Tool Discovery & Composability — Phase 1
 *
 * Enables agents to dynamically register/deregister MCP tools at runtime.
 * Tracks per-tool metrics (call count, latency, error rate) and supports
 * semver versioning with deprecation.
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn } from '../utils/logger.js';
import { z, type ZodTypeAny } from 'zod';

// --- Interfaces ---

export interface ToolManifest {
  id: string;
  name: string;
  version: string;                  // semver: "1.0.0"
  description: string;
  inputSchema: ZodTypeAny;
  outputSchema?: ZodTypeAny;
  publishedBy: string;              // agent name
  tags: string[];
  deprecated?: boolean;
  deprecatedMessage?: string;
  timeout?: number;                 // ms
  retryConfig?: {
    maxRetries: number;
    backoff: 'linear' | 'exponential';
  };
  composable?: {
    chainable: boolean;
    outputType: string;             // 'code' | 'text' | 'json' | 'file'
  };
}

export interface ToolMetrics {
  toolId: string;
  totalCalls: number;
  successCalls: number;
  errorCalls: number;
  avgLatencyMs: number;
  p95LatencyMs: number;
  lastUsed: number;                 // timestamp
  lastError?: string;
  latencyHistory: number[];         // last 100 latencies for p95 calculation
}

export interface ToolRegistryEntry {
  manifest: ToolManifest;
  metrics: ToolMetrics;
  registeredAt: number;
  handler?: (args: Record<string, unknown>) => Promise<unknown>;
}

export interface ToolFilter {
  tags?: string[];
  publishedBy?: string;
  name?: string;
  deprecated?: boolean;
  version?: string;                 // semver range (simple prefix match for now)
}

// --- Semver Utilities ---

function parseSemver(version: string): [number, number, number] | null {
  const match = version.match(/^(\d+)\.(\d+)\.(\d+)/);
  if (!match) return null;
  return [parseInt(match[1]), parseInt(match[2]), parseInt(match[3])];
}

function semverSatisfies(version: string, range: string): boolean {
  const ver = parseSemver(version);
  if (!ver) return false;

  // Exact match
  if (!range.startsWith('^') && !range.startsWith('~')) {
    const rangeVer = parseSemver(range);
    return rangeVer !== null && ver[0] === rangeVer[0] && ver[1] === rangeVer[1] && ver[2] === rangeVer[2];
  }

  const rangeVer = parseSemver(range.substring(1));
  if (!rangeVer) return false;

  if (range.startsWith('^')) {
    // ^1.2.3 → >=1.2.3 <2.0.0 (same major)
    if (ver[0] !== rangeVer[0]) return false;
    if (ver[1] > rangeVer[1]) return true;
    if (ver[1] === rangeVer[1] && ver[2] >= rangeVer[2]) return true;
    return false;
  }

  if (range.startsWith('~')) {
    // ~1.2.3 → >=1.2.3 <1.3.0 (same major.minor)
    if (ver[0] !== rangeVer[0] || ver[1] !== rangeVer[1]) return false;
    return ver[2] >= rangeVer[2];
  }

  return false;
}

function semverCompare(a: string, b: string): number {
  const va = parseSemver(a);
  const vb = parseSemver(b);
  if (!va || !vb) return 0;
  for (let i = 0; i < 3; i++) {
    if (va[i] !== vb[i]) return va[i] - vb[i];
  }
  return 0;
}

// --- Dynamic Tool Registry ---

export class DynamicToolRegistry extends EventEmitter {
  private tools = new Map<string, ToolRegistryEntry>();
  private static _instance: DynamicToolRegistry | null = null;

  static getInstance(): DynamicToolRegistry {
    if (!DynamicToolRegistry._instance) {
      DynamicToolRegistry._instance = new DynamicToolRegistry();
    }
    return DynamicToolRegistry._instance;
  }

  /**
   * Register a tool with the dynamic registry
   */
  registerTool(manifest: ToolManifest, handler?: (args: Record<string, unknown>) => Promise<unknown>): boolean {
    // Validate manifest
    if (!manifest.id || !manifest.name || !manifest.version) {
      logWarn('DynamicToolRegistry', `Invalid manifest: missing required fields (id=${manifest.id})`);
      return false;
    }
    if (!parseSemver(manifest.version)) {
      logWarn('DynamicToolRegistry', `Invalid semver for tool ${manifest.id}: ${manifest.version}`);
      return false;
    }

    const existing = this.tools.get(manifest.id);
    if (existing) {
      // Version upgrade: only allow same or higher version
      if (semverCompare(manifest.version, existing.manifest.version) < 0) {
        logWarn('DynamicToolRegistry', `Cannot downgrade tool ${manifest.id} from ${existing.manifest.version} to ${manifest.version}`);
        return false;
      }
    }

    const entry: ToolRegistryEntry = {
      manifest,
      metrics: existing?.metrics ?? {
        toolId: manifest.id,
        totalCalls: 0,
        successCalls: 0,
        errorCalls: 0,
        avgLatencyMs: 0,
        p95LatencyMs: 0,
        lastUsed: 0,
        latencyHistory: [],
      },
      registeredAt: Date.now(),
      handler,
    };

    this.tools.set(manifest.id, entry);
    logInfo('DynamicToolRegistry', `Tool registered: ${manifest.name}@${manifest.version} by ${manifest.publishedBy} [${manifest.tags.join(',')}]`);
    this.emit('tool:registered', manifest);

    if (manifest.deprecated) {
      logWarn('DynamicToolRegistry', `Tool ${manifest.id} is deprecated: ${manifest.deprecatedMessage ?? 'no reason given'}`);
    }

    return true;
  }

  /**
   * Deregister a tool
   */
  deregisterTool(toolId: string): boolean {
    const entry = this.tools.get(toolId);
    if (!entry) return false;

    this.tools.delete(toolId);
    logInfo('DynamicToolRegistry', `Tool deregistered: ${entry.manifest.name}@${entry.manifest.version}`);
    this.emit('tool:deregistered', entry.manifest);
    return true;
  }

  /**
   * Discover tools matching a filter
   */
  discoverTools(filter?: ToolFilter): ToolManifest[] {
    let results = Array.from(this.tools.values()).map(e => e.manifest);

    if (!filter) return results;

    if (filter.tags && filter.tags.length > 0) {
      results = results.filter(m => filter.tags!.some(t => m.tags.includes(t)));
    }
    if (filter.publishedBy) {
      results = results.filter(m => m.publishedBy === filter.publishedBy);
    }
    if (filter.name) {
      const nameLower = filter.name.toLowerCase();
      results = results.filter(m => m.name.toLowerCase().includes(nameLower));
    }
    if (filter.deprecated !== undefined) {
      results = results.filter(m => (m.deprecated ?? false) === filter.deprecated);
    }
    if (filter.version) {
      results = results.filter(m => semverSatisfies(m.version, filter.version!));
    }

    return results;
  }

  /**
   * Resolve the best matching version of a tool by name
   */
  resolveVersion(toolName: string, versionRange: string): ToolManifest | null {
    const candidates = Array.from(this.tools.values())
      .filter(e => e.manifest.name === toolName && semverSatisfies(e.manifest.version, versionRange))
      .sort((a, b) => semverCompare(b.manifest.version, a.manifest.version));

    return candidates[0]?.manifest ?? null;
  }

  /**
   * Record a tool call for metrics
   */
  recordCall(toolId: string, success: boolean, latencyMs: number, error?: string): void {
    const entry = this.tools.get(toolId);
    if (!entry) return;

    const m = entry.metrics;
    m.totalCalls++;
    if (success) {
      m.successCalls++;
    } else {
      m.errorCalls++;
      m.lastError = error;
    }
    m.lastUsed = Date.now();

    // Rolling latency history (keep last 100)
    m.latencyHistory.push(latencyMs);
    if (m.latencyHistory.length > 100) {
      m.latencyHistory.shift();
    }

    // Recalculate avg and p95
    const sum = m.latencyHistory.reduce((a, b) => a + b, 0);
    m.avgLatencyMs = sum / m.latencyHistory.length;

    const sorted = [...m.latencyHistory].sort((a, b) => a - b);
    const p95Index = Math.floor(sorted.length * 0.95);
    m.p95LatencyMs = sorted[p95Index] ?? m.avgLatencyMs;

    if (entry.manifest.deprecated) {
      logWarn('DynamicToolRegistry', `Deprecated tool called: ${entry.manifest.name} — ${entry.manifest.deprecatedMessage ?? 'consider migrating'}`);
    }
  }

  /**
   * Get metrics for a specific tool
   */
  getMetrics(toolId: string): ToolMetrics | null {
    return this.tools.get(toolId)?.metrics ?? null;
  }

  /**
   * Get all tool metrics
   */
  getAllMetrics(): ToolMetrics[] {
    return Array.from(this.tools.values()).map(e => ({
      ...e.metrics,
      latencyHistory: [],  // omit large array in bulk response
    }));
  }

  /**
   * Get a tool entry by ID
   */
  getTool(toolId: string): ToolRegistryEntry | null {
    return this.tools.get(toolId) ?? null;
  }

  /**
   * Get all registered tools
   */
  getAll(): ToolRegistryEntry[] {
    return Array.from(this.tools.values());
  }

  /**
   * Get registry statistics
   */
  getStats(): {
    totalTools: number;
    deprecatedTools: number;
    totalCalls: number;
    avgLatencyMs: number;
    publishers: string[];
  } {
    let totalCalls = 0;
    let totalLatency = 0;
    let callsWithLatency = 0;
    const publishers = new Set<string>();
    let deprecated = 0;

    for (const entry of this.tools.values()) {
      totalCalls += entry.metrics.totalCalls;
      if (entry.metrics.totalCalls > 0) {
        totalLatency += entry.metrics.avgLatencyMs * entry.metrics.totalCalls;
        callsWithLatency += entry.metrics.totalCalls;
      }
      publishers.add(entry.manifest.publishedBy);
      if (entry.manifest.deprecated) deprecated++;
    }

    return {
      totalTools: this.tools.size,
      deprecatedTools: deprecated,
      totalCalls,
      avgLatencyMs: callsWithLatency > 0 ? totalLatency / callsWithLatency : 0,
      publishers: Array.from(publishers),
    };
  }

  /** Clear all tools (for testing) */
  clear(): void {
    this.tools.clear();
  }
}

// Convenience singleton accessor
export function getDynamicToolRegistry(): DynamicToolRegistry {
  return DynamicToolRegistry.getInstance();
}

// Helper: convert ToolManifest to MCP-compatible tool definition
export function manifestToMcpTool(manifest: ToolManifest): {
  name: string;
  description: string;
  inputSchema: Record<string, unknown>;
} {
  let inputSchema: Record<string, unknown>;
  try {
    // Try to extract JSON schema from Zod
    if (manifest.inputSchema && typeof (manifest.inputSchema as { _def?: unknown })._def === 'object') {
      // Simplified: create basic object schema from Zod type
      inputSchema = {
        type: 'object',
        properties: { task: { type: 'string', description: 'Input for the tool' } },
        required: ['task'],
      };
    } else {
      inputSchema = {
        type: 'object',
        properties: { task: { type: 'string', description: 'Input for the tool' } },
        required: ['task'],
      };
    }
  } catch {
    inputSchema = {
      type: 'object',
      properties: { task: { type: 'string', description: 'Input for the tool' } },
      required: ['task'],
    };
  }

  const desc = manifest.deprecated
    ? `[DEPRECATED: ${manifest.deprecatedMessage ?? 'use alternative'}] ${manifest.description}`
    : manifest.description;

  return {
    name: manifest.name,
    description: `${desc} (v${manifest.version} by ${manifest.publishedBy})`,
    inputSchema,
  };
}

/**
 * EdgeHealthMonitor - Continuous Edge Health Monitoring
 *
 * Phoenix Protocol Szint 5: Proactive edge health monitoring with
 * event broadcasting and multi-step failover chain.
 *
 * Failover chain: edge → local → cloud → escalate
 *
 * @version 1.0.0
 */

import { logInfo, logError } from '../utils/logger.js';
import { phoenixEventBus } from './phoenixEventBus.js';

// ============================================================================
// INTERFACES
// ============================================================================

export type EdgeHealthStatus = 'healthy' | 'degraded' | 'offline';

export interface EdgeHealthSnapshot {
  status: EdgeHealthStatus;
  latencyMs: number;
  consecutiveFailures: number;
  lastSuccessAt: string | null;
  lastCheckAt: string;
}

interface HealthHistoryEntry {
  status: EdgeHealthStatus;
  latencyMs: number;
  timestamp: string;
}

// ============================================================================
// CONSTANTS
// ============================================================================

const DEFAULT_PROBE_INTERVAL = 30_000; // 30s
const DEGRADED_LATENCY_THRESHOLD = 2000; // 2s
const OFFLINE_CONSECUTIVE_FAILURES = 3;
const MAX_HEALTH_HISTORY = 100;

// ============================================================================
// EDGE HEALTH MONITOR
// ============================================================================

class EdgeHealthMonitorClass {
  private probeInterval: ReturnType<typeof setInterval> | null = null;
  private currentStatus: EdgeHealthStatus = 'offline';
  private consecutiveFailures = 0;
  private lastSuccessAt: string | null = null;
  private lastCheckAt = '';
  private lastLatency = -1;
  private workerUrl: string;
  private healthHistory: HealthHistoryEntry[] = [];
  private probeIntervalMs: number;

  constructor() {
    this.workerUrl = process.env.CLOUDFLARE_WORKER_URL || 'https://bas-orchestrator.workers.dev';
    this.probeIntervalMs = parseInt(process.env.EDGE_HEALTH_PROBE_INTERVAL || String(DEFAULT_PROBE_INTERVAL));
  }

  /**
   * Start continuous background health probing.
   */
  start(): void {
    if (this.probeInterval) return; // Already running

    logInfo('EdgeHealthMonitor', `Starting continuous monitoring (interval: ${this.probeIntervalMs}ms)`);

    // Immediate first check
    void this.probe();

    this.probeInterval = setInterval(() => void this.probe(), this.probeIntervalMs);
  }

  /**
   * Stop health probing.
   */
  stop(): void {
    if (this.probeInterval) {
      clearInterval(this.probeInterval);
      this.probeInterval = null;
      logInfo('EdgeHealthMonitor', 'Monitoring stopped');
    }
  }

  /**
   * Single health probe — fetches edge /health endpoint.
   */
  async probe(): Promise<EdgeHealthSnapshot> {
    const startTime = Date.now();
    const previousStatus = this.currentStatus;

    try {
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 10_000);

      const response = await fetch(`${this.workerUrl}/health`, {
        method: 'GET',
        signal: controller.signal,
      });
      clearTimeout(timeout);

      const latency = Date.now() - startTime;
      this.lastLatency = latency;
      this.lastCheckAt = new Date().toISOString();

      if (response.ok) {
        this.consecutiveFailures = 0;
        this.lastSuccessAt = this.lastCheckAt;
        this.currentStatus = latency > DEGRADED_LATENCY_THRESHOLD ? 'degraded' : 'healthy';
      } else {
        this.consecutiveFailures++;
        this.currentStatus = this.consecutiveFailures >= OFFLINE_CONSECUTIVE_FAILURES ? 'offline' : 'degraded';
      }
    } catch {
      this.lastLatency = Date.now() - startTime;
      this.lastCheckAt = new Date().toISOString();
      this.consecutiveFailures++;
      this.currentStatus = this.consecutiveFailures >= OFFLINE_CONSECUTIVE_FAILURES ? 'offline' : 'degraded';
    }

    // Record history
    const entry: HealthHistoryEntry = {
      status: this.currentStatus,
      latencyMs: this.lastLatency,
      timestamp: this.lastCheckAt,
    };
    this.healthHistory.push(entry);
    if (this.healthHistory.length > MAX_HEALTH_HISTORY) {
      this.healthHistory.splice(0, this.healthHistory.length - MAX_HEALTH_HISTORY);
    }

    // Broadcast status change via PhoenixEventBus
    if (previousStatus !== this.currentStatus) {
      phoenixEventBus.publish('phoenix:edge_health', {
        status: this.currentStatus,
        previousStatus,
        latencyMs: this.lastLatency,
        timestamp: this.lastCheckAt,
      });

      logInfo('EdgeHealthMonitor', `Status changed: ${previousStatus} → ${this.currentStatus} (latency: ${this.lastLatency}ms)`);
    }

    return this.getSnapshot();
  }

  /**
   * Get current health snapshot.
   */
  getSnapshot(): EdgeHealthSnapshot {
    return {
      status: this.currentStatus,
      latencyMs: this.lastLatency,
      consecutiveFailures: this.consecutiveFailures,
      lastSuccessAt: this.lastSuccessAt,
      lastCheckAt: this.lastCheckAt,
    };
  }

  /**
   * Get health history entries.
   */
  getHistory(limit = 50): HealthHistoryEntry[] {
    return this.healthHistory.slice(-limit);
  }

  /**
   * Whether edge is currently usable (healthy or degraded-but-reachable).
   */
  isEdgeAvailable(): boolean {
    return this.currentStatus !== 'offline';
  }

  /**
   * Whether edge is in optimal state.
   */
  isEdgeHealthy(): boolean {
    return this.currentStatus === 'healthy';
  }

  /**
   * Update the worker URL dynamically.
   */
  setWorkerUrl(url: string): void {
    this.workerUrl = url;
    this.consecutiveFailures = 0;
    this.currentStatus = 'offline'; // Will be updated on next probe
  }
}

export const edgeHealthMonitor = new EdgeHealthMonitorClass();
export default edgeHealthMonitor;

/**
 * EdgeRouter — Cloudflare-aware routing with fallback
 * Phase 4: Distributed Mesh & Edge Routing
 *
 * Routes requests to the best available node, preferring:
 *   1. Local node (if capability is available)
 *   2. Same-region edge peer
 *   3. Any available peer
 *   4. Cloudflare worker fallback
 */

import { logInfo, logWarn, logError } from '../utils/logger.js';
import type { MeshNodeInfo } from '../mesh/meshNode.js';
import type { MeshManager } from '../mesh/meshManager.js';

export interface RouteDecision {
  target: 'local' | 'peer' | 'edge';
  nodeId: string;
  host: string;
  region?: string;
  latencyHint?: number;
  fallback: boolean;
}

export interface EdgeRouterConfig {
  localNodeId: string;
  localRegion?: string;
  cloudflareWorkerUrl?: string;  // e.g. "https://cean-orchestrator.iam-dd1.workers.dev"
  preferLocal: boolean;
  maxRetries: number;
}

const DEFAULT_CONFIG: EdgeRouterConfig = {
  localNodeId: 'local',
  preferLocal: true,
  maxRetries: 2,
  cloudflareWorkerUrl: process.env.CF_EDGE_WORKER_URL,
};

export class EdgeRouter {
  private config: EdgeRouterConfig;
  private meshManager: MeshManager;
  private routeCache = new Map<string, { decision: RouteDecision; cachedAt: number }>();
  private static CACHE_TTL_MS = 10_000;

  constructor(meshManager: MeshManager, config?: Partial<EdgeRouterConfig>) {
    this.meshManager = meshManager;
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Resolve the best node for a given capability.
   * Priority: local → same-region peer → any peer → CF edge fallback
   */
  resolve(capability: string): RouteDecision {
    // Check cache
    const cached = this.routeCache.get(capability);
    if (cached && Date.now() - cached.cachedAt < EdgeRouter.CACHE_TTL_MS) {
      return cached.decision;
    }

    const topology = this.meshManager.getTopology();

    // 1. Local node
    if (this.config.preferLocal && topology.local.capabilities.includes(capability) && topology.local.status === 'online') {
      const decision: RouteDecision = {
        target: 'local',
        nodeId: topology.local.nodeId,
        host: topology.local.host,
        region: topology.local.region,
        fallback: false,
      };
      this.cacheDecision(capability, decision);
      return decision;
    }

    // 2. Same-region peer
    const sameRegion = topology.peers.filter(p =>
      p.status === 'online' &&
      p.capabilities.includes(capability) &&
      p.region === this.config.localRegion
    );
    if (sameRegion.length > 0) {
      const best = sameRegion[0];
      const decision: RouteDecision = {
        target: 'peer',
        nodeId: best.nodeId,
        host: best.host,
        region: best.region,
        fallback: false,
      };
      this.cacheDecision(capability, decision);
      return decision;
    }

    // 3. Any online peer with capability
    const anyPeer = topology.peers.filter(p =>
      p.status === 'online' && p.capabilities.includes(capability)
    );
    if (anyPeer.length > 0) {
      const best = anyPeer[0];
      const decision: RouteDecision = {
        target: 'peer',
        nodeId: best.nodeId,
        host: best.host,
        region: best.region,
        fallback: false,
      };
      this.cacheDecision(capability, decision);
      return decision;
    }

    // 4. Cloudflare edge fallback
    if (this.config.cloudflareWorkerUrl) {
      const decision: RouteDecision = {
        target: 'edge',
        nodeId: 'cf-edge',
        host: this.config.cloudflareWorkerUrl,
        region: 'cf-global',
        fallback: true,
      };
      logWarn('EdgeRouter', `No mesh peer for "${capability}", falling back to CF edge`);
      this.cacheDecision(capability, decision);
      return decision;
    }

    // No route found
    throw new Error(`EdgeRouter: No route found for capability "${capability}"`);
  }

  /**
   * Execute a routed request with retry + fallback logic
   */
  async executeRouted(capability: string, toolName: string, input: Record<string, unknown>): Promise<unknown> {
    let lastError: Error | null = null;

    for (let attempt = 0; attempt <= this.config.maxRetries; attempt++) {
      try {
        const decision = attempt === 0
          ? this.resolve(capability)
          : this.resolveFallback(capability, attempt);

        logInfo('EdgeRouter', `Routing ${capability}/${toolName} → ${decision.target}:${decision.nodeId} (attempt ${attempt + 1})`);

        if (decision.target === 'local') {
          // Local execution — caller handles this
          return { routed: 'local', nodeId: decision.nodeId };
        }

        // Remote execution via peer or edge
        const url = `${decision.host}/api/v1/mesh/execute`;
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 15_000);

        const res = await fetch(url, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ capability, toolName, input, fromNode: this.config.localNodeId }),
          signal: controller.signal,
        });
        clearTimeout(timeout);

        if (!res.ok) {
          throw new Error(`Remote execution failed: ${res.status} ${res.statusText}`);
        }

        return await res.json();
      } catch (err: unknown) {
        lastError = err instanceof Error ? err : new Error(String(err));
        logWarn('EdgeRouter', `Attempt ${attempt + 1} failed for ${capability}: ${lastError.message}`);
        // Invalidate cache so next attempt picks a different route
        this.routeCache.delete(capability);
      }
    }

    logError('EdgeRouter', `All attempts failed for ${capability}/${toolName}`);
    throw lastError ?? new Error(`EdgeRouter: all attempts failed for ${capability}`);
  }

  /** Get a fallback route for retry attempts */
  private resolveFallback(capability: string, attempt: number): RouteDecision {
    const topology = this.meshManager.getTopology();
    const available = topology.peers.filter(p =>
      p.status === 'online' && p.capabilities.includes(capability)
    );

    if (attempt <= available.length && available[attempt - 1]) {
      const peer = available[attempt - 1];
      return {
        target: 'peer',
        nodeId: peer.nodeId,
        host: peer.host,
        region: peer.region,
        fallback: true,
      };
    }

    // Ultimate fallback: CF edge
    if (this.config.cloudflareWorkerUrl) {
      return {
        target: 'edge',
        nodeId: 'cf-edge',
        host: this.config.cloudflareWorkerUrl,
        region: 'cf-global',
        fallback: true,
      };
    }

    throw new Error(`EdgeRouter: No fallback route for "${capability}"`);
  }

  private cacheDecision(capability: string, decision: RouteDecision): void {
    this.routeCache.set(capability, { decision, cachedAt: Date.now() });
  }

  /** Clear route cache */
  invalidateCache(): void {
    this.routeCache.clear();
  }
}

/**
 * FailoverRegistry - Cross-Agent Failover Mapping
 *
 * Phoenix Protocol Szint 4: When an agent fails after all retries exhausted,
 * this registry determines which backup agent(s) can handle the same task type.
 *
 * Fallback chain: primary → secondary → tertiary → escalate
 *
 * @version 1.0.0
 */

import { logInfo, logError } from '../utils/logger.js';

// ============================================================================
// INTERFACES
// ============================================================================

export interface FailoverMapping {
  /** Primary agent name */
  primary: string;
  /** Ordered list of backup agents to try */
  fallbacks: string[];
  /** Task categories this mapping covers */
  categories: string[];
}

export interface FailoverAttempt {
  primaryAgent: string;
  fallbackAgent: string;
  taskInstruction: string;
  success: boolean;
  error?: string;
  attemptIndex: number;
  timestamp: string;
}

// ============================================================================
// DEFAULT FAILOVER MAPPINGS
// ============================================================================

/**
 * Default failover chain per agent, based on capability overlap in registry.json.
 *
 * developer → evaluator → orchestrator (code tasks)
 * evaluator → developer → orchestrator (audit/test tasks)
 * researcher → orchestrator              (knowledge tasks)
 * robotkez → orchestrator                (browser tasks — no true backup)
 * lint_fixer → developer                 (lint tasks)
 * SpecWriter → developer                 (spec generation tasks)
 * ProjectConductor → orchestrator        (project management)
 * voice → orchestrator                   (voice tasks — no true backup)
 * EdgeProxy → orchestrator               (edge tasks → local fallback)
 */
const DEFAULT_FAILOVER_MAPPINGS: FailoverMapping[] = [
  {
    primary: 'Developer',
    fallbacks: ['evaluator', 'orchestrator'],
    categories: ['code_generation', 'self_healing', 'pipeline'],
  },
  {
    primary: 'evaluator',
    fallbacks: ['developer', 'orchestrator'],
    categories: ['audit_system', 'run_tests', 'check_health'],
  },
  {
    primary: 'researcher',
    fallbacks: ['orchestrator'],
    categories: ['rag_search', 'summarization'],
  },
  {
    primary: 'robotkez',
    fallbacks: ['orchestrator'],
    categories: ['browser_automation', 'web_scraping'],
  },
  {
    primary: 'lint_fixer',
    fallbacks: ['developer', 'orchestrator'],
    categories: ['lint_check', 'auto_fix', 'type_check'],
  },
  {
    primary: 'SpecWriter',
    fallbacks: ['developer', 'orchestrator'],
    categories: ['track_generation', 'requirement_extraction'],
  },
  {
    primary: 'ProjectConductor',
    fallbacks: ['orchestrator'],
    categories: ['project_management', 'documentation_sync'],
  },
  {
    primary: 'voice',
    fallbacks: ['orchestrator'],
    categories: ['voice_command_refinement', 'multimodal_context_analysis'],
  },
  {
    primary: 'EdgeProxy',
    fallbacks: ['orchestrator'],
    categories: ['edge', 'remote_access'],
  },
  {
    primary: 'project_organizer',
    fallbacks: ['developer', 'orchestrator'],
    categories: ['organization', 'documentation', 'cleanup'],
  },
];

// ============================================================================
// FAILOVER REGISTRY CLASS
// ============================================================================

class FailoverRegistryClass {
  private mappings: Map<string, FailoverMapping> = new Map();
  private attemptLog: FailoverAttempt[] = [];
  private readonly MAX_LOG_SIZE = 100;

  constructor() {
    this.loadDefaults();
  }

  private loadDefaults(): void {
    for (const mapping of DEFAULT_FAILOVER_MAPPINGS) {
      this.mappings.set(mapping.primary.toLowerCase(), mapping);
    }
  }

  /**
   * Get the ordered fallback chain for a failed agent.
   * Returns empty array if no fallbacks are defined.
   */
  getFallbacks(agentName: string): string[] {
    const mapping = this.mappings.get(agentName.toLowerCase());
    return mapping ? [...mapping.fallbacks] : [];
  }

  /**
   * Get all failover mappings.
   */
  getAllMappings(): FailoverMapping[] {
    return Array.from(this.mappings.values());
  }

  /**
   * Register or update a failover mapping.
   */
  registerMapping(mapping: FailoverMapping): void {
    this.mappings.set(mapping.primary.toLowerCase(), mapping);
    logInfo('FailoverRegistry', `Mapping updated: ${mapping.primary} → [${mapping.fallbacks.join(', ')}]`);
  }

  /**
   * Record a failover attempt for auditing.
   */
  recordAttempt(attempt: FailoverAttempt): void {
    this.attemptLog.push(attempt);
    if (this.attemptLog.length > this.MAX_LOG_SIZE) {
      this.attemptLog.splice(0, this.attemptLog.length - this.MAX_LOG_SIZE);
    }
  }

  /**
   * Get recent failover attempts, optionally filtered.
   */
  getAttempts(agentFilter?: string, limit = 50): FailoverAttempt[] {
    const filtered = agentFilter
      ? this.attemptLog.filter(
          (a) =>
            a.primaryAgent.toLowerCase() === agentFilter.toLowerCase() ||
            a.fallbackAgent.toLowerCase() === agentFilter.toLowerCase(),
        )
      : this.attemptLog;
    return filtered.slice(-limit);
  }

  /**
   * Get failover success rate statistics.
   */
  getStats(): {
    totalAttempts: number;
    successCount: number;
    failureCount: number;
    successRate: number;
    byAgent: Record<string, { total: number; success: number }>;
  } {
    const total = this.attemptLog.length;
    const success = this.attemptLog.filter((a) => a.success).length;
    const byAgent: Record<string, { total: number; success: number }> = {};

    for (const attempt of this.attemptLog) {
      const key = attempt.primaryAgent.toLowerCase();
      if (!byAgent[key]) byAgent[key] = { total: 0, success: 0 };
      byAgent[key].total++;
      if (attempt.success) byAgent[key].success++;
    }

    return {
      totalAttempts: total,
      successCount: success,
      failureCount: total - success,
      successRate: total > 0 ? success / total : 0,
      byAgent,
    };
  }

  /**
   * Clear attempt log.
   */
  clearAttempts(): void {
    this.attemptLog = [];
  }
}

export const failoverRegistry = new FailoverRegistryClass();
export default failoverRegistry;

/**
 * GeneticFlow — Genetic-algorithm-based workflow optimization
 * Phase 6: Evolutionary Collective Intelligence
 *
 * Evaluates multiple workflow variants (mutation / crossover of step order,
 * handler selection, parameter ranges), runs them against metrics, and
 * selects the fittest variant as the new default.
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn } from '../utils/logger.js';

export interface FlowVariant {
  id: string;
  flowId: string;
  generation: number;
  stepOrder: string[];             // ordered step IDs
  parameterOverrides: Record<string, number>;
  fitness: number;                 // 0–1 measured quality
  parentIds: string[];
  mutations: string[];
  createdAt: number;
}

export interface GeneticFlowConfig {
  populationSize: number;
  mutationRate: number;
  crossoverRate: number;
  maxGenerations: number;
  fitnessGoal: number;
}

export interface VariantEvaluation {
  variantId: string;
  durationMs: number;
  successRate: number;
  outputQuality: number;          // 0–1
  fitness: number;                // computed composite
}

const DEFAULT_CONFIG: GeneticFlowConfig = {
  populationSize: 8,
  mutationRate: 0.25,
  crossoverRate: 0.4,
  maxGenerations: 30,
  fitnessGoal: 0.9,
};

export class GeneticFlow extends EventEmitter {
  private config: GeneticFlowConfig;
  private variants = new Map<string, FlowVariant>();
  private evaluations: VariantEvaluation[] = [];
  private variantCounter = 0;

  constructor(config?: Partial<GeneticFlowConfig>) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /** Seed an initial population from a base flow definition */
  seedPopulation(flowId: string, baseStepOrder: string[], baseParams: Record<string, number> = {}): FlowVariant[] {
    const population: FlowVariant[] = [];

    const base = this.createVariant(flowId, baseStepOrder, baseParams, 0, [], ['seed']);
    population.push(base);

    for (let i = 1; i < this.config.populationSize; i++) {
      const parent = population[Math.floor(Math.random() * population.length)];
      const mutated = this.mutateVariant(parent);
      population.push(mutated);
    }

    logInfo('GeneticFlow', `Population seeded for ${flowId}: ${population.length} variants`);
    return population;
  }

  /** Record evaluation results for a variant */
  evaluate(variantId: string, result: Omit<VariantEvaluation, 'variantId' | 'fitness'>): VariantEvaluation {
    const fitness = result.successRate * 0.5 + result.outputQuality * 0.3 + Math.max(0, 1 - result.durationMs / 10000) * 0.2;
    const evaluation: VariantEvaluation = { variantId, ...result, fitness };
    this.evaluations.push(evaluation);

    const variant = this.variants.get(variantId);
    if (variant) variant.fitness = fitness;

    this.emit('variant:evaluated', evaluation);
    return evaluation;
  }

  /** Evolve the next generation: select top, crossover, mutate */
  evolve(flowId: string): FlowVariant[] {
    const all = this.getVariantsForFlow(flowId);
    if (all.length === 0) return [];

    const sorted = [...all].sort((a, b) => b.fitness - a.fitness);
    const eliteCount = Math.max(1, Math.ceil(sorted.length * 0.3));
    const elites = sorted.slice(0, eliteCount);
    const nextGen: FlowVariant[] = [...elites];

    // Crossover
    while (nextGen.length < this.config.populationSize * 0.6 && elites.length >= 2) {
      const a = elites[Math.floor(Math.random() * elites.length)];
      const b = elites[Math.floor(Math.random() * elites.length)];
      if (a.id !== b.id) {
        const child = this.crossoverVariants(a, b);
        nextGen.push(child);
      }
    }

    // Mutate to fill population
    while (nextGen.length < this.config.populationSize) {
      const parent = elites[Math.floor(Math.random() * elites.length)];
      if (Math.random() < this.config.mutationRate) {
        nextGen.push(this.mutateVariant(parent));
      } else {
        nextGen.push(this.createVariant(
          parent.flowId,
          [...parent.stepOrder],
          { ...parent.parameterOverrides },
          parent.generation + 1,
          [parent.id],
          ['clone']
        ));
      }
    }

    logInfo('GeneticFlow', `Evolved generation for ${flowId}: ${nextGen.length} variants, best fitness=${sorted[0].fitness.toFixed(3)}`);
    this.emit('generation:evolved', { flowId, size: nextGen.length, bestFitness: sorted[0].fitness });
    return nextGen;
  }

  /** Get the best variant for a flow */
  getBest(flowId: string): FlowVariant | undefined {
    return this.getVariantsForFlow(flowId).sort((a, b) => b.fitness - a.fitness)[0];
  }

  /** Get all variants for a flow */
  getVariantsForFlow(flowId: string): FlowVariant[] {
    return Array.from(this.variants.values()).filter(v => v.flowId === flowId);
  }

  /** Check if goal reached */
  goalReached(flowId: string): boolean {
    const best = this.getBest(flowId);
    return !!best && best.fitness >= this.config.fitnessGoal;
  }

  /** Get evaluation history */
  getEvaluations(): VariantEvaluation[] {
    return [...this.evaluations];
  }

  /** Create a variant */
  private createVariant(
    flowId: string, stepOrder: string[], params: Record<string, number>,
    generation: number, parentIds: string[], mutations: string[]
  ): FlowVariant {
    const variant: FlowVariant = {
      id: `fv-${++this.variantCounter}-${Date.now()}`,
      flowId,
      generation,
      stepOrder: [...stepOrder],
      parameterOverrides: { ...params },
      fitness: 0,
      parentIds,
      mutations,
      createdAt: Date.now(),
    };
    this.variants.set(variant.id, variant);
    return variant;
  }

  /** Mutate a variant: shuffle steps or tweak params */
  private mutateVariant(parent: FlowVariant): FlowVariant {
    const newSteps = [...parent.stepOrder];
    const newParams = { ...parent.parameterOverrides };
    const mutationTypes: string[] = [];

    // Random swap of two steps
    if (newSteps.length >= 2 && Math.random() < 0.5) {
      const i = Math.floor(Math.random() * newSteps.length);
      const j = Math.floor(Math.random() * newSteps.length);
      [newSteps[i], newSteps[j]] = [newSteps[j], newSteps[i]];
      mutationTypes.push('step_swap');
    }

    // Param tweak
    const paramKeys = Object.keys(newParams);
    if (paramKeys.length > 0 && Math.random() < 0.5) {
      const key = paramKeys[Math.floor(Math.random() * paramKeys.length)];
      newParams[key] = Math.max(0, Math.min(1, (newParams[key] ?? 0.5) + (Math.random() - 0.5) * 0.3));
      mutationTypes.push('param_tweak');
    }

    if (mutationTypes.length === 0) mutationTypes.push('clone');

    return this.createVariant(
      parent.flowId, newSteps, newParams,
      parent.generation + 1, [parent.id], mutationTypes
    );
  }

  /** Crossover two variants */
  private crossoverVariants(a: FlowVariant, b: FlowVariant): FlowVariant {
    const mid = Math.ceil(a.stepOrder.length / 2);
    const childSteps = [...new Set([...a.stepOrder.slice(0, mid), ...b.stepOrder.slice(mid)])];

    const childParams: Record<string, number> = {};
    const allKeys = new Set([...Object.keys(a.parameterOverrides), ...Object.keys(b.parameterOverrides)]);
    for (const key of allKeys) {
      childParams[key] = ((a.parameterOverrides[key] ?? 0.5) + (b.parameterOverrides[key] ?? 0.5)) / 2;
    }

    return this.createVariant(
      a.flowId, childSteps, childParams,
      Math.max(a.generation, b.generation) + 1,
      [a.id, b.id], ['crossover']
    );
  }
}

// FILE: src/core/goldenDatasetBridge.ts
// PURPOSE: G4.1 — Node.js → D1 golden dataset bridge (Phase 3: D1 Integration)
// RULES: RULE-GD1 (success+LLM→save), RULE-GD2 (quality threshold), RULE-GD3 (dedup SHA256)

import { logInfo, logError } from '../utils/logger.js';
import { vectorizeClient } from '../utils/vectorize.js';
import { getD1Adapter, getGlobalDb } from '../utils/globalDb.js';
import { fnvHash } from './hashUtils.js';

// ============================================================================
// TYPES
// ============================================================================

export interface GoldenSample {
  prompt: string;
  completion: string;
  source: string;
  quality: number;      // 0.0 - 1.0
}

export interface GoldenSaveResult {
  success: boolean;
  message?: string;
  stats?: Record<string, unknown>;
}

export interface GoldenDatasetStats {
  totalSamples: number;
  newSinceLastTraining: number;
  lastTrainingAt?: string;
}

// ============================================================================
// CONFIGURATION
// ============================================================================

const PYTHON_BASE_URL = process.env.PYTHON_BASE_URL || 'http://localhost:8000';
const MIN_PROMPT_LENGTH = 10;       // RULE-GD2: minimum task length
const MIN_QUALITY_SCORE = 0.5;      // From goldConfig spec
const SAVE_TIMEOUT_MS = 5000;

// ============================================================================
// DEDUPLICATION (RULE-GD3)
// ============================================================================

const recentHashes = new Set<string>();
const MAX_HASH_CACHE = 500;

/**
 * Simple hash for deduplication — SHA256 not available in all envs,
 * so we use a FNV-1a-like fast hash.
 */
function quickHash(str: string): string {
  return fnvHash(str);
}

function ensureGoldenLocalTable(): void {
  const db = getGlobalDb();
  db.exec(`
    CREATE TABLE IF NOT EXISTS golden_samples (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      sample_hash TEXT NOT NULL UNIQUE,
      prompt TEXT NOT NULL,
      completion TEXT NOT NULL,
      source TEXT NOT NULL,
      quality REAL NOT NULL,
      remote_status TEXT NOT NULL DEFAULT 'pending',
      remote_synced_at TEXT,
      created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
      updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
    );

    CREATE INDEX IF NOT EXISTS idx_golden_samples_remote_status ON golden_samples(remote_status);
    CREATE INDEX IF NOT EXISTS idx_golden_samples_created_at ON golden_samples(created_at);
  `);
}

export function saveGoldenSampleLocal(sample: GoldenSample): GoldenSaveResult {
  if (sample.quality < MIN_QUALITY_SCORE) {
    return {
      success: false,
      message: `Quality ${sample.quality} below threshold ${MIN_QUALITY_SCORE} (RULE-GD2)`,
    };
  }

  ensureGoldenLocalTable();
  const db = getGlobalDb();
  const sampleHash = quickHash(`${sample.prompt}|||${sample.completion}`);
  const nowIso = new Date().toISOString();

  db.prepare(`
    INSERT INTO golden_samples (
      sample_hash, prompt, completion, source, quality, remote_status, created_at, updated_at
    ) VALUES (
      @sample_hash, @prompt, @completion, @source, @quality, 'pending', @created_at, @updated_at
    )
    ON CONFLICT(sample_hash) DO UPDATE SET
      quality = excluded.quality,
      source = excluded.source,
      updated_at = excluded.updated_at
  `).run({
    sample_hash: sampleHash,
    prompt: sample.prompt,
    completion: sample.completion,
    source: sample.source,
    quality: sample.quality,
    created_at: nowIso,
    updated_at: nowIso,
  });

  return {
    success: true,
    message: 'Saved to local golden mirror',
    stats: { storage: 'sqlite', sampleHash },
  };
}

export async function syncLocalToD1(): Promise<{ synced: number; failed: number; skipped: number }> {
  ensureGoldenLocalTable();
  const d1Adapter = getD1Adapter();
  if (!d1Adapter) {
    return { synced: 0, failed: 0, skipped: 0 };
  }

  const db = getGlobalDb();
  const rows = db.prepare(`
    SELECT *
    FROM golden_samples
    WHERE remote_status != 'synced'
    ORDER BY created_at ASC
  `).all() as Array<Record<string, unknown>>;

  let synced = 0;
  let failed = 0;

  for (const row of rows) {
    try {
      const result = await d1Adapter.insertGoldenSample({
        id: `golden_${String(row.sample_hash)}`,
        instruction: String(row.prompt),
        output: String(row.completion),
        source: String(row.source),
      });

      if (result.status === 'error') {
        throw new Error(result.error || 'Unknown D1 sync error');
      }

      db.prepare(`
        UPDATE golden_samples
        SET remote_status = 'synced', remote_synced_at = ?, updated_at = ?
        WHERE sample_hash = ?
      `).run(new Date().toISOString(), new Date().toISOString(), String(row.sample_hash));
      synced += 1;
    } catch (error) {
      failed += 1;
      db.prepare(`
        UPDATE golden_samples
        SET remote_status = 'failed', updated_at = ?
        WHERE sample_hash = ?
      `).run(new Date().toISOString(), String(row.sample_hash));
      logError('GoldenBridge', `Local->D1 sync failed for ${String(row.sample_hash)}: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  return { synced, failed, skipped: 0 };
}

export function exportGoldenDataset(format: 'jsonl' | 'json' = 'jsonl'): string {
  ensureGoldenLocalTable();
  const db = getGlobalDb();
  const rows = db.prepare(`
    SELECT prompt, completion, source, quality, created_at, remote_status
    FROM golden_samples
    ORDER BY created_at DESC
  `).all() as Array<Record<string, unknown>>;

  if (format === 'json') {
    return JSON.stringify(rows, null, 2);
  }

  return rows.map((row) => JSON.stringify(row)).join('\n');
}

function isDuplicate(prompt: string, completion: string): boolean {
  const hash = quickHash(prompt + '|||' + completion);
  if (recentHashes.has(hash)) return true;
  
  recentHashes.add(hash);
  if (recentHashes.size > MAX_HASH_CACHE) {
    // Remove oldest entries (Set iteration order = insertion order)
    const iter = recentHashes.values();
    for (let i = 0; i < 100; i++) iter.next();
    const toKeep = new Set<string>();
    for (const v of recentHashes) {
      if (toKeep.size >= MAX_HASH_CACHE - 100) break;
      toKeep.add(v);
    }
    recentHashes.clear();
    for (const v of toKeep) recentHashes.add(v);
  }
  
  return false;
}

// ============================================================================
// QUALITY SCORING (RULE-GD2)
// ============================================================================

/**
 * Heuristic quality score based on prompt/completion characteristics.
 */
export function calculateQuality(prompt: string, completion: string): number {
  let score = 0.5; // Base

  // Longer prompts tend to be more specific
  if (prompt.length > 50) score += 0.1;
  if (prompt.length > 200) score += 0.1;

  // Longer completions tend to be more complete
  if (completion.length > 100) score += 0.1;
  if (completion.length > 500) score += 0.1;

  // Code-like completions are more valuable
  if (/function|class|export|import|const|let|def |async/.test(completion)) {
    score += 0.1;
  }

  return Math.min(1.0, score);
}

// ============================================================================
// CORE BRIDGE
// ============================================================================

/**
 * Save a golden sample to D1 database (Phase 3: Cloud-first storage).
 * Applies RULE-GD1 (success check), RULE-GD2 (quality threshold), RULE-GD3 (dedup).
 */
export async function saveGoldenSample(sample: GoldenSample): Promise<GoldenSaveResult> {
  try {
    // RULE-GD2: quality threshold
    if (sample.prompt.length < MIN_PROMPT_LENGTH) {
      return { success: false, message: 'Prompt too short (RULE-GD2)' };
    }
    if (!sample.completion || sample.completion.trim().length === 0) {
      return { success: false, message: 'Empty completion (RULE-GD2)' };
    }
    if (sample.quality < MIN_QUALITY_SCORE) {
      return { success: false, message: `Quality ${sample.quality} below threshold ${MIN_QUALITY_SCORE} (RULE-GD2)` };
    }

    // RULE-GD3: deduplication
    if (isDuplicate(sample.prompt, sample.completion)) {
      return { success: false, message: 'Duplicate sample (RULE-GD3)' };
    }

    const localResult = saveGoldenSampleLocal(sample);
    if (!localResult.success) {
      return localResult;
    }

    // Save to D1 (cloud-first strategy)
    const d1Adapter = getD1Adapter();
    if (d1Adapter) {
      try {
        const d1Result = await d1Adapter.insertGoldenSample({
          id: `golden_${Date.now()}_${Math.random().toString(36).slice(2)}`,
          instruction: sample.prompt,
          output: sample.completion,
          source: sample.source,
        });
        
        if (d1Result.status === 'error') {
          throw new Error(d1Result.error || 'Unknown D1 error');
        }
        
        logInfo('GoldenBridge', `Sample saved to D1 from ${sample.source} (quality: ${sample.quality.toFixed(2)})`);
        ensureGoldenLocalTable();
        getGlobalDb().prepare(`
          UPDATE golden_samples
          SET remote_status = 'synced', remote_synced_at = ?, updated_at = ?
          WHERE sample_hash = ?
        `).run(new Date().toISOString(), new Date().toISOString(), quickHash(`${sample.prompt}|||${sample.completion}`));
        return { 
          success: true, 
          message: 'Saved to D1 cloud storage',
          stats: { storage: 'd1', mirror: 'sqlite', quality: sample.quality }
        };
      } catch (d1Error: unknown) {
        const msg = d1Error instanceof Error ? d1Error.message : String(d1Error);
        logError('GoldenBridge', `D1 save failed, falling back to Python: ${msg}`);
        // Fall through to Python backup
        
        // If it's a network error like ECONNREFUSED, we should probably fail fast
        // since the Python backend is likely also unreachable if it's a local network issue
        if (msg.includes('ECONNREFUSED')) {
          return { success: false, message: `Save failed: ${msg}` };
        }
      }
    }

    // Fallback: Python backend (legacy support)
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), SAVE_TIMEOUT_MS);

    try {
      const response = await fetch(`${PYTHON_BASE_URL}/incubator/gold-sample`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          prompt: sample.prompt,
          completion: sample.completion,
          source: sample.source,
          quality: sample.quality
        }),
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`Python API error: ${response.status} ${response.statusText}`);
      }

      const data = await response.json();
      ensureGoldenLocalTable();
      getGlobalDb().prepare(`
        UPDATE golden_samples
        SET remote_status = 'synced', remote_synced_at = ?, updated_at = ?
        WHERE sample_hash = ?
      `).run(new Date().toISOString(), new Date().toISOString(), quickHash(`${sample.prompt}|||${sample.completion}`));
      logInfo('GoldenBridge', `Sample saved to Python backup from ${sample.source} (quality: ${sample.quality.toFixed(2)})`);
      return { success: true, message: data.message, stats: { ...data.stats, mirror: 'sqlite' } };
    } catch (fetchError: unknown) {
      clearTimeout(timeoutId);
      const msg = fetchError instanceof Error ? fetchError.message : String(fetchError);
      return { success: false, message: `Save failed: ${msg}` };
    }
  } catch (error: unknown) {
    const msg = error instanceof Error ? error.message : String(error);
    logError('GoldenBridge', `Save failed: ${msg}`);
    return { success: false, message: msg };
  }
}

/**
 * Get golden dataset statistics from D1 (cloud-first) or Python backup.
 */
export async function getGoldenStats(): Promise<GoldenDatasetStats | null> {
  try {
    ensureGoldenLocalTable();
    const localRow = getGlobalDb().prepare(`
      SELECT COUNT(*) AS total_samples
      FROM golden_samples
    `).get() as Record<string, unknown>;

    // Try D1 first
    const d1Adapter = getD1Adapter();
    if (d1Adapter) {
      try {
        const samplesResult = await d1Adapter.getAllGoldenSamples(1000);
        if (samplesResult.status === 'success' && samplesResult.results) {
          const samples = samplesResult.results;
          return {
            totalSamples: Math.max(samples.length, Number(localRow.total_samples ?? 0)),
            newSinceLastTraining: samples.filter(s => {
              const created = new Date(s.created_at);
              const weekAgo = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000);
              return created > weekAgo;
            }).length,
            lastTrainingAt: undefined // TODO: track training runs in D1
          };
        }
      } catch (d1Error: unknown) {
        const msg = d1Error instanceof Error ? d1Error.message : String(d1Error);
        logError('GoldenBridge', `D1 stats failed, trying Python backup: ${msg}`);
      }
    }

    // Fallback: Python backend
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), SAVE_TIMEOUT_MS);

    try {
      const response = await fetch(`${PYTHON_BASE_URL}/incubator/stats`, {
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) return null;

      const data = await response.json();
      return {
        ...(data.stats as GoldenDatasetStats),
        totalSamples: Math.max(Number(localRow.total_samples ?? 0), Number((data.stats as GoldenDatasetStats).totalSamples ?? 0)),
      };
    } catch (fetchError) {
      clearTimeout(timeoutId);
      return {
        totalSamples: Number(localRow.total_samples ?? 0),
        newSinceLastTraining: 0,
      };
    }
  } catch {
    logError('GoldenBridge', 'Failed to get golden dataset stats from both D1 and Python');
    return null;
  }
}

/**
 * Auto-save hook for AgentManager — called after successful agent execution.
 * Implements RULE-GD1: success + LLM call → save.
 */
export async function autoSaveGoldenSample(
  agentName: string,
  task: string,
  result: string | Record<string, unknown> | object
): Promise<void> {
  const completion = typeof result === 'string' ? result : JSON.stringify(result);
  const quality = calculateQuality(task, completion);

  if (quality < MIN_QUALITY_SCORE) {
    return; // Skip low-quality samples silently
  }

  // Fire-and-forget (non-blocking, RULE: audit write async)
  saveGoldenSample({
    prompt: task,
    completion,
    source: agentName,
    quality
  }).catch(() => { /* non-critical */ });

  // Vectorize upsert
  if (process.env.CF_VECTORIZE_ENABLED === 'true' || vectorizeClient.getStatus().enabled) {
    vectorizeClient.upsertText(
      `golden-${Date.now()}`,
      `${task}\n${completion}`,
      { source: agentName, type: 'golden_sample', quality }
    ).catch(e => logError('GoldenBridge', `Vectorize upsert failed: ${e.message}`));
  }
}

import Database from 'better-sqlite3';
import { v4 as uuidv4 } from 'uuid';
import { logInfo, logError } from '../utils/logger.js';
import { JulesConfigParser, type ScheduledTaskSpec } from './julesConfigParser.js';

export interface CreateTaskOptions {
  skipIfExists?: boolean;
  enableImmediately?: boolean;
}

export class JulesAutomationService {
  private db: Database.Database;
  private parser: JulesConfigParser;

  constructor(db: Database.Database, configPath?: string) {
    this.db = db;
    this.parser = new JulesConfigParser(configPath);
  }

  /**
   * Import Jules automation rules as scheduled tasks
   */
  async importJulesAutomations(options: CreateTaskOptions = {}): Promise<{
    imported: number;
    skipped: number;
    errors: string[];
  }> {
    const result: { imported: number; skipped: number; errors: string[] } = { imported: 0, skipped: 0, errors: [] };

    try {
      const rules = this.parser.getAutomationRules();
      logInfo('JulesAutomation', `Found ${rules.length} automation rules to import`);

      for (const rule of rules) {
        try {
          const taskSpec = this.parser.ruleToScheduledTask(rule);
          const created = this.createScheduledTask(taskSpec, options);

          if (created) {
            result.imported++;
            logInfo('JulesAutomation', `Imported rule: ${rule.name}`);
          } else {
            result.skipped++;
            logInfo('JulesAutomation', `Skipped existing rule: ${rule.name}`);
          }
        } catch (err) {
          result.errors.push(`${rule.name}: ${err}`);
          logError('JulesAutomation', `Failed to import rule ${rule.name}: ${err}`);
        }
      }
    } catch (err) {
      result.errors.push(`Import failed: ${err}`);
      logError('JulesAutomation', `Import failed: ${err}`);
    }

    return result;
  }

  /**
   * Create a scheduled task from Jules task spec
   */
  createScheduledTask(spec: ScheduledTaskSpec, options: CreateTaskOptions = {}): boolean {
    try {
      // Check if exists
      const existing = this.db
        .prepare('SELECT id FROM scheduled_tasks WHERE title = ?')
        .get(spec.title);

      if (existing && options.skipIfExists) {
        logInfo('JulesAutomation', `Task already exists: ${spec.title}`);
        return false;
      }

      const taskId = uuidv4();
      const now = new Date().toISOString();

      this.db
        .prepare(
          `
        INSERT INTO scheduled_tasks (
          id, title, prompt, cron_expression, handler,
          enabled, metadata, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
      `,
        )
        .run(
          taskId,
          spec.title,
          spec.prompt,
          spec.cron_expression,
          spec.handler,
          options.enableImmediately ? 1 : 0,
          JSON.stringify(spec.metadata || {}),
          now,
          now,
        );

      logInfo('JulesAutomation', `Created scheduled task: ${spec.title}`);
      return true;
    } catch (err) {
      logError('JulesAutomation', `Failed to create task: ${err}`);
      throw err;
    }
  }

  /**
   * Handle Render webhook and import Jules config
   */
  async handleRenderWebhook(payload: Record<string, unknown>): Promise<{
    success: boolean;
    message: string;
    result?: { imported: number; skipped: number; errors: string[] };
  }> {
    try {
      logInfo('JulesAutomation', 'Processing Render webhook');

      // Trigger Jules config import
      const importResult = await this.importJulesAutomations({
        skipIfExists: true,
        enableImmediately: false,
      });

      return {
        success: true,
        message: `Imported ${importResult.imported} Jules automation rules`,
        result: importResult,
      };
    } catch (err) {
      const message = `Render webhook processing failed: ${err}`;
      logError('JulesAutomation', message);
      return { success: false, message };
    }
  }

  /**
   * Get all imported Jules tasks
   */
  getImportedTasks(): Array<{
    id: string;
    title: string;
    source: string;
  }> {
    try {
      const tasks = this.db
        .prepare("SELECT id, title FROM scheduled_tasks WHERE metadata LIKE ?")
        .all('%"source":"jules_config"%') as Array<{ id: string; title: string }>;

      return tasks.map((t) => ({
        ...t,
        source: 'jules_config',
      }));
    } catch (err) {
      logError('JulesAutomation', `Failed to get imported tasks: ${err}`);
      return [];
    }
  }
}

import { readFileSync } from 'fs';
import path from 'path';
import YAML from 'yaml';
import { logInfo, logError, logWarn } from '../utils/logger.js';

export interface JulesConfig {
  version: string;
  workflows: JulesWorkflow[];
  automationRules?: JulesAutomationRule[];
}

export interface JulesWorkflow {
  name: string;
  description?: string;
  trigger: string;
  steps: JulesStep[];
  schedule?: string;
}

export interface JulesStep {
  name: string;
  action: string;
  config?: Record<string, unknown>;
}

export interface JulesAutomationRule {
  id: string;
  name: string;
  description?: string;
  trigger: string;
  criteria?: Record<string, unknown>;
  actions: JulesAction[];
  schedule?: string;
  enabled: boolean;
}

export interface JulesAction {
  type: string;
  target: string;
  params?: Record<string, unknown>;
}

export class JulesConfigParser {
  private configPath: string;
  private config: JulesConfig | null = null;

  constructor(configPath: string = '.jules.yml') {
    this.configPath = path.resolve(process.cwd(), configPath);
  }

  /**
   * Load and parse Jules config file
   */
  load(): JulesConfig {
    try {
      logInfo('JulesParser', `Loading config from ${this.configPath}`);
      const content = readFileSync(this.configPath, 'utf-8');
      this.config = YAML.parse(content) as JulesConfig;

      logInfo('JulesParser', `Loaded ${this.config?.workflows?.length || 0} workflows`);
      return this.config!;
    } catch (error) {
      logError('JulesParser', `Failed to load config: ${error}`);
      throw error;
    }
  }

  /**
   * Get all automation rules that can be converted to scheduled tasks
   */
  getAutomationRules(): JulesAutomationRule[] {
    if (!this.config) {
      this.load();
    }

    const rules = this.config?.automationRules || [];
    return rules.filter((r) => r.enabled !== false);
  }

  /**
   * Get workflows that match a trigger
   */
  getWorkflowsByTrigger(trigger: string): JulesWorkflow[] {
    if (!this.config) {
      this.load();
    }

    return this.config?.workflows?.filter((w) => w.trigger === trigger) || [];
  }

  /**
   * Convert Jules automation rule to scheduled task spec
   */
  ruleToScheduledTask(rule: JulesAutomationRule): ScheduledTaskSpec {
    const cronExpression = rule.schedule || '0 0 * * *'; // Default: daily at midnight

    return {
      title: rule.name,
      prompt: rule.description || `Run automation: ${rule.name}`,
      cron_expression: cronExpression,
      handler: 'jules_automation',
      metadata: {
        source: 'jules_config',
        ruleId: rule.id,
        trigger: rule.trigger,
        actions: rule.actions,
      },
    };
  }

  /**
   * Convert all automation rules to scheduled tasks
   */
  toScheduledTasks(): ScheduledTaskSpec[] {
    return this.getAutomationRules().map((rule) => this.ruleToScheduledTask(rule));
  }
}

export interface ScheduledTaskSpec {
  title: string;
  prompt: string;
  cron_expression: string;
  handler: string;
  metadata?: Record<string, unknown>;
}

/**
 * Jules AI Integration for Automated Workflow Fixes
 *
 * Orchestrates the complete flow:
 * GitHub workflow fails → Error analysis → Jules AI generates fix → PR creation → Auto-merge
 */

import { Octokit } from '@octokit/rest';
import { logInfo, logError, logWarn } from '../utils/logger.js';
import { DeploymentAnalyzer, type DeploymentAnalysis } from '../tools/deploymentAnalyzer.js';
import { GitHubAPIClient } from './githubAPIClient.js';
import { notifySlack } from './slackNotifications.js';

export interface JulesFixWorkflow {
  runId: number;
  owner: string;
  repo: string;
  branch: string;
  prNumber?: number;
  status: 'analyzing' | 'generating' | 'committing' | 'complete' | 'failed';
  analysis?: DeploymentAnalysis;
  error?: string;
  timestamp: string;
}

/**
 * Process a failed GitHub workflow and attempt automatic fix via Jules
 */
export async function processWorkflowFailure(
  owner: string,
  repo: string,
  runId: number,
  defaultBranch: string = 'main'
): Promise<JulesFixWorkflow> {
  const workflow: JulesFixWorkflow = {
    runId,
    owner,
    repo,
    branch: `fix/workflow-${runId}-${Date.now()}`,
    status: 'analyzing',
    timestamp: new Date().toISOString()
  };

  try {
    // 1. Fetch and analyze workflow logs
    logInfo('JulesIntegration', `🔍 Analyzing workflow failure for ${owner}/${repo}#${runId}`);
    workflow.status = 'analyzing';

    const apiClient = new GitHubAPIClient(process.env.GITHUB_TOKEN);
    const logs = await apiClient.getWorkflowRunLogs(owner, repo, runId);

    if (!logs) {
      throw new Error('Failed to fetch workflow logs');
    }

    const analysis = DeploymentAnalyzer.analyzeLogs(logs);
    workflow.analysis = analysis;

    logInfo(
      'JulesIntegration',
      `✅ Error analysis complete: ${analysis.category} (confidence: ${(analysis.confidence * 100).toFixed(0)}%)`
    );

    // Notify Slack - analyzing
    await notifySlack('analyzing', runId);

    // 2. Generate Jules fix prompt
    logInfo('JulesIntegration', '🤖 Generating fix prompt for Jules...');
    const fixPrompt = DeploymentAnalyzer.generateFixPrompt(analysis);

    workflow.status = 'generating';

    // TODO: Send to Jules API in Phase 3.3.2
    // For now, log the prompt for manual inspection
    logInfo('JulesIntegration', `Fix prompt generated:\n${fixPrompt}`);

    // 3. PR creation (to be implemented in Phase 3.3.2)
    logInfo('JulesIntegration', '📝 Creating PR with analysis...');
    workflow.status = 'committing';

    const octokit = new Octokit({
      auth: process.env.GITHUB_TOKEN
    });

    // 3a. Get main branch SHA
    const { data: mainBranch } = await octokit.git.getRef({
      owner,
      repo,
      ref: `heads/${defaultBranch}`
    });

    logInfo('JulesIntegration', `Creating branch: ${workflow.branch}`);

    // 3b. Create feature branch
    await octokit.git.createRef({
      owner,
      repo,
      ref: `refs/heads/${workflow.branch}`,
      sha: mainBranch.object.sha
    });

    // 3c. Create PR with analysis
    const { data: pr } = await octokit.pulls.create({
      owner,
      repo,
      title: `[Jules Auto-Fix] ${analysis.title} - Workflow #${runId}`,
      body: `## Jules AI Auto-Fix Report

### Error Analysis
**Type:** \`${analysis.category}\`  
**Title:** ${analysis.title}  
**Confidence:** ${(analysis.confidence * 100).toFixed(0)}%  

### Error Summary
${analysis.message}

${analysis.errorLocation ? `### Location
**File:** \`${analysis.errorLocation.file}\`  
${analysis.errorLocation.line ? `**Line:** ${analysis.errorLocation.line}` : ''}
` : ''}

${analysis.affectedFiles.length > 0 ? `### Affected Files
${analysis.affectedFiles.map((f) => `- \`${f}\``).join('\n')}
` : ''}

### Next Steps
1. Review the error analysis above
2. Jules will generate a fix proposal
3. Automated tests will verify the fix
4. PR will auto-merge if confidence ≥75%

---
*This PR was automatically created by Jules Continuous AI Integration (JCAI)*  
Workflow run: #${runId}
      `,
      head: workflow.branch,
      base: defaultBranch,
      draft: analysis.confidence < 0.75 // Draft if low confidence
    });

    workflow.prNumber = pr.number;

    logInfo(
      'JulesIntegration',
      `✅ PR created: #${pr.number} (${analysis.confidence < 0.75 ? 'DRAFT' : 'READY'})`
    );

    // 4. Notify Slack - PR created
    await notifySlack('fixed', runId);

    // 5. Auto-merge if high confidence
    if (analysis.confidence >= 0.75) {
      logInfo('JulesIntegration', '✨ Confidence ≥75%, attempting auto-merge...');

      try {
        const mergeResult = await octokit.pulls.merge({
          owner,
          repo,
          pull_number: pr.number,
          commit_title: `fix: ${analysis.title} (Workflow #${runId})`,
          merge_method: 'squash'
        });

        logInfo('JulesIntegration', `✅ PR auto-merged (#${pr.number})`);
        await notifySlack('merged', runId);
      } catch (mergeErr) {
        logWarn('JulesIntegration', `Auto-merge failed: ${mergeErr}`);
        // Continue - PR is still created, just not merged
      }
    } else {
      logWarn(
        'JulesIntegration',
        `Low confidence (${(analysis.confidence * 100).toFixed(0)}%) - marking as draft for manual review`
      );
    }

    workflow.status = 'complete';
    return workflow;
  } catch (err: unknown) {
    workflow.status = 'failed';
    const errMsg = err instanceof Error ? err.message : String(err);
    workflow.error = errMsg;

    logError('JulesIntegration', `❌ Fix workflow failed: ${errMsg}`);
    await notifySlack('failed', workflow.runId, errMsg);

    // Fallback: Create issue for manual review
    try {
      await createManualReviewIssue(owner, repo, workflow, errMsg);
    } catch (issueErr) {
      logError('JulesIntegration', `Failed to create manual review issue: ${issueErr}`);
    }

    throw err;
  }
}

/**
 * Create an issue for manual code review when automated fix fails
 */
async function createManualReviewIssue(
  owner: string,
  repo: string,
  workflow: JulesFixWorkflow,
  error: string
): Promise<void> {
  const octokit = new Octokit({
    auth: process.env.GITHUB_TOKEN
  });

  const { data: issue } = await octokit.issues.create({
    owner,
    repo,
    title: `[Jules] Manual Review Required: ${workflow.analysis?.title || 'Workflow Error'}`,
    body: `## Automated Fix Failed

Jules AI encountered an error while attempting to fix the workflow failure.

### Details
**Workflow ID:** ${workflow.runId}  
**Error Type:** ${workflow.analysis?.category || 'unknown'}  
**Confidence:** ${workflow.analysis ? (workflow.analysis.confidence * 100).toFixed(0) : 'N/A'}%  

### Error Message
\`\`\`
${error}
\`\`\`

### Action Required
Please review the workflow failure manually and apply fixes as needed.

---
*Created by Jules Continuous AI Integration*
    `,
    labels: ['bug', 'needs-review', 'jules-auto-fix']
  });

  logInfo('JulesIntegration', `📌 Created manual review issue: #${issue.number}`);
}

/**
 * Retry workflow fix with exponential backoff
 */
export async function retryWorkflowFix(
  owner: string,
  repo: string,
  runId: number,
  maxRetries: number = 3
): Promise<JulesFixWorkflow> {
  for (let attempt = 1; attempt <= maxRetries; attempt++) {
    try {
      return await processWorkflowFailure(owner, repo, runId);
    } catch (err) {
      if (attempt === maxRetries) {
        throw err;
      }

      const backoff = Math.pow(2, attempt) * 1000; // 2s, 4s, 8s
      logWarn(
        'JulesIntegration',
        `Retry ${attempt}/${maxRetries} after ${backoff}ms...`
      );

      await new Promise((resolve) => setTimeout(resolve, backoff));
    }
  }

  throw new Error('Max retries exceeded');
}

/**
 * Get fix workflow status
 */
export function getWorkflowStatus(workflow: JulesFixWorkflow): string {
  const status = workflow.status.toUpperCase();
  const emoji: Record<string, string> = {
    ANALYZING: '🔍',
    GENERATING: '🤖',
    COMMITTING: '📝',
    COMPLETE: '✅',
    FAILED: '❌'
  };

  return `${emoji[status] || '❓'} ${status}${workflow.prNumber ? ` - PR #${workflow.prNumber}` : ''}`;
}

