  },
  // Muscle models (Ollama local) — code gen, tests, repetitive tasks
  {
    name: process.env.OLLAMA_MODEL || 'qwen2.5-coder:7b',
    provider: 'ollama',
    role: 'muscle',
    contextWindow: 32768,
    costPerToken: 0,
    speed: 'fast',
    strengths: ['code_gen', 'test_gen', 'docs', 'translation', 'simple_tasks']
  },
  {
    name: 'qwen2.5-coder:7b',
    provider: 'ollama',
    role: 'muscle',
    contextWindow: 32768,
    costPerToken: 0,
    speed: 'fast',
    strengths: ['code_gen', 'refactor', 'debug', 'test_gen']
  },
  // Cloudflare Workers AI — free, no local GPU needed
  {
    name: '@cf/meta/llama-3.3-70b-instruct',
    provider: 'cloudflare',
    role: 'brain',
    contextWindow: 128000,
    costPerToken: 0,
    speed: 'medium',
    strengths: ['planning', 'analysis', 'reasoning', 'architecture', 'complex_reasoning']
  },
  {
    name: '@cf/meta/llama-3.1-8b-instruct',
    provider: 'cloudflare',
    role: 'muscle',
    contextWindow: 32768,
    costPerToken: 0,
    speed: 'fast',
    strengths: ['code_gen', 'fast_response', 'simple_tasks', 'translation']
  }
];

// ============================================================================
// DEFAULT CONFIG
// ============================================================================

const DEFAULT_CONFIG: RouterConfig = {
  budget: parseInt(process.env.ROUTER_BUDGET || '50', 10),
  preferLocal: process.env.ROUTER_PREFER_LOCAL !== 'false',
  fallbackEnabled: process.env.ROUTER_FALLBACK !== 'false',
  overrideModel: process.env.ROUTER_OVERRIDE_MODEL,
  overrideProvider: process.env.ROUTER_OVERRIDE_PROVIDER as ProviderName | undefined
};

// ============================================================================
// COMPLEXITY DETECTION
// ============================================================================

const HIGH_COMPLEXITY_PATTERNS = [
  /architect/i, /design.*(system|api|schema)/i, /plan/i, /strateg/i,
  /refactor.*large/i, /review.*code/i, /analyz/i, /evaluat/i,
  /debug.*complex/i, /migration/i, /security.*audit/i
];

const LOW_COMPLEXITY_PATTERNS = [
  /write.*test/i, /generate.*test/i, /fix.*lint/i, /format/i,
  /translate/i, /docstring/i, /comment/i, /rename/i,
  /simple.*fix/i, /typo/i, /update.*import/i, /add.*log/i
];

/**
 * Auto-detect task complexity from description.
 */
export function detectComplexity(description: string): TaskComplexity {
  for (const pattern of HIGH_COMPLEXITY_PATTERNS) {
    if (pattern.test(description)) return 'high';
  }
  for (const pattern of LOW_COMPLEXITY_PATTERNS) {
    if (pattern.test(description)) return 'low';
  }
  // Medium by default
  return 'medium';
}

/**
 * Detect task category from description.
 */
export function detectCategory(description: string): string {
  const lower = description.toLowerCase();
  if (/plan|architect|design|strateg/.test(lower)) return 'planning';
  if (/test|spec|vitest|jest/.test(lower)) return 'test';
  if (/doc|readme|comment|jsdoc/.test(lower)) return 'docs';
  if (/debug|fix|error|bug/.test(lower)) return 'debug';
  if (/analy|review|audit|evaluat/.test(lower)) return 'analysis';
  return 'code_gen';
}

// ============================================================================
// ROUTING DECISIONS LOG
// ============================================================================

const routingHistory: RoutingDecision[] = [];
const MAX_HISTORY = 200;

function recordDecision(decision: RoutingDecision): void {
  routingHistory.push(decision);
  if (routingHistory.length > MAX_HISTORY) {
    routingHistory.splice(0, routingHistory.length - MAX_HISTORY);
  }
}

// ============================================================================
// CORE ROUTER
// ============================================================================

/**
 * Select the best model for a given task profile.
 * Implements RULE-MR1 through RULE-MR4.
 */
export function selectModel(task: TaskProfile, config: Partial<RouterConfig> = {}): RoutingDecision {
  const cfg: RouterConfig = { ...DEFAULT_CONFIG, ...config };

  // Manual override (highest priority)
  if (cfg.overrideModel) {
    const overrideProfile = MODEL_REGISTRY.find(m => m.name === cfg.overrideModel)
      || MODEL_REGISTRY.find(m => m.provider === cfg.overrideProvider)
      || MODEL_REGISTRY[0];
    
    const decision: RoutingDecision = {
      model: overrideProfile,
      reason: `Manual override: ${cfg.overrideModel}`,
      timestamp: Date.now()
    };
    recordDecision(decision);
    return decision;
  }

  // RULE-MR3: budget === 0 → exclusively Ollama
  if (cfg.budget === 0) {
    const ollamaModel = findBestOllama(task);
    const decision: RoutingDecision = {
      model: ollamaModel,
      reason: 'RULE-MR3: Budget=0, Ollama only',
      timestamp: Date.now()
    };
    logInfo('ModelRouter', `[MR3] Budget=0 → ${ollamaModel.name}`);
    recordDecision(decision);
    return decision;
  }

  // RULE-MR1: high complexity → Cloud model
  if (task.complexity === 'high') {
    const cloudModel = findBestCloud(task, cfg);
    const fallback = cfg.fallbackEnabled ? findBestOllama(task) : undefined;
    
    const decision: RoutingDecision = {
      model: cloudModel,
      reason: `RULE-MR1: High complexity (${task.category || 'unknown'}) → ${cloudModel.provider}`,
      fallback,
      timestamp: Date.now()
    };
    logInfo('ModelRouter', `[MR1] High complexity → ${cloudModel.name} (${cloudModel.provider})`);
    recordDecision(decision);
    return decision;
  }

  // RULE-MR2: low complexity → Ollama local
  if (task.complexity === 'low') {
    const ollamaModel = findBestOllama(task);
    const decision: RoutingDecision = {
      model: ollamaModel,
      reason: `RULE-MR2: Low complexity (${task.category || 'unknown'}) → Ollama local`,
      timestamp: Date.now()
    };
    logInfo('ModelRouter', `[MR2] Low complexity → ${ollamaModel.name}`);
    recordDecision(decision);
    return decision;
  }

  // Medium complexity: prefer local if configured, otherwise choose by strengths
  if (cfg.preferLocal) {
    const ollamaModel = findBestOllama(task);
    const decision: RoutingDecision = {
      model: ollamaModel,
      reason: `Medium complexity + preferLocal → Ollama`,
      fallback: cfg.fallbackEnabled ? findBestCloud(task, cfg) : undefined,
      timestamp: Date.now()
    };
    logInfo('ModelRouter', `[Medium+Local] → ${ollamaModel.name}`);
    recordDecision(decision);
    return decision;
  }

  // Medium complexity, no preferLocal: pick best match by strengths
  const bestMatch = findBestByStrengths(task);
  const decision: RoutingDecision = {
    model: bestMatch,
    reason: `Medium complexity, best strength match → ${bestMatch.name}`,
    fallback: cfg.fallbackEnabled ? findBestOllama(task) : undefined,
    timestamp: Date.now()
  };
  logInfo('ModelRouter', `[Medium+Strength] → ${bestMatch.name}`);
  recordDecision(decision);
  return decision;
}

/**
 * Convenience: auto-detect complexity and select model.
 */
export function routeTask(description: string, config: Partial<RouterConfig> = {}): RoutingDecision {
  const complexity = detectComplexity(description);
  const category = detectCategory(description);

  const taskProfile: TaskProfile = {
    description,
    complexity,
    category
  };

  return selectModel(taskProfile, config);
}

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

function findBestOllama(task: TaskProfile): ModelProfile {
  const ollamaModels = MODEL_REGISTRY.filter(m => m.provider === 'ollama');
  if (ollamaModels.length === 0) {
    // Fallback to first model in registry
    return MODEL_REGISTRY[0];
  }

  // Score by matching strengths
  const scored = ollamaModels.map(m => ({
    model: m,
    score: scoreByStrengths(m, task)
  }));

  scored.sort((a, b) => b.score - a.score);
  return scored[0].model;
}

function findBestCloud(task: TaskProfile, cfg: RouterConfig): ModelProfile {
  const cloudModels = MODEL_REGISTRY.filter(m => m.provider !== 'ollama');
  if (cloudModels.length === 0) {
    // RULE-MR4: no cloud available → fallback to Ollama
    logInfo('ModelRouter', '[MR4] No cloud models available, falling back to Ollama');
    return findBestOllama(task);
  }

  // Check API key availability
  const available = cloudModels.filter(m => {
    if (m.provider === 'gemini') return !!process.env.GEMINI_API_KEY;
    if (m.provider === 'github') return !!(process.env.GITHUB_TOKEN || process.env.GITHUB_PAT);
    if (m.provider === 'cloudflare') return !!((process.env.CF_AI_API_TOKEN || process.env.CF_API_TOKEN) && process.env.AI_GATEWAY_ENABLED === 'true');
    return true;
  });

  if (available.length === 0) {
    // RULE-MR4: cloud not reachable → fallback to Ollama + warning
    logInfo('ModelRouter', '[MR4] No cloud API keys configured, falling back to Ollama');
    return findBestOllama(task);
  }

  // Score available cloud models by strengths
  const scored = available.map(m => ({
    model: m,
    score: scoreByStrengths(m, task)
  }));

  scored.sort((a, b) => b.score - a.score);
  return scored[0].model;
}

function findBestByStrengths(task: TaskProfile): ModelProfile {
  const scored = MODEL_REGISTRY.map(m => ({
    model: m,
    score: scoreByStrengths(m, task)
  }));

  scored.sort((a, b) => b.score - a.score);
  return scored[0].model;
}

function scoreByStrengths(model: ModelProfile, task: TaskProfile): number {
  let score = 0;

  // Category match
  if (task.category && model.strengths.includes(task.category)) {
    score += 10;
  }

  // Required strengths match
  if (task.requiredStrengths) {
    for (const req of task.requiredStrengths) {
      if (model.strengths.includes(req)) score += 5;
    }
  }

  // Speed bonus
  if (model.speed === 'fast') score += 3;
  else if (model.speed === 'medium') score += 1;

  // Cost efficiency bonus (prefer free)
  if (model.costPerToken === 0) score += 2;

  return score;
}

// ============================================================================
// PUBLIC API
// ============================================================================

/**
 * Get all registered model profiles.
 */
export function getModelProfiles(): ModelProfile[] {
  return [...MODEL_REGISTRY];
}

/**
 * Get routing decision history.
 */
export function getRoutingHistory(): RoutingDecision[] {
  return [...routingHistory];
}

/**
 * Get recent routing decisions (for CLI/API).
 * Returns last N decisions with flattened data for display.
 */
export function getRecentDecisions(limit= 50): Array<{
  timestamp: string;
  task: string;
  category: string;
  selectedModel: string;
  reason: string;
}> {
  const recent = routingHistory.slice(-limit);
  return recent.map(d => ({
    timestamp: new Date(d.timestamp).toISOString(),
    task: d.reason,
    category: d.model.role, // brain or muscle
    selectedModel: d.model.name,
    reason: d.reason,
  }));
}

/**
 * Clear routing history.
 */
export function clearRoutingHistory(): void {
  routingHistory.length = 0;
}

/**
 * Get current default router config.
 */
export function getRouterConfig(): RouterConfig {
  return { ...DEFAULT_CONFIG };
}

import { Client } from '@modelcontextprotocol/sdk/client/index.js';
import { StdioClientTransport } from '@modelcontextprotocol/sdk/client/stdio.js';
import { spawn, ChildProcess } from 'child_process';
import { Ollama } from 'ollama';
import type { ChatRequest, ChatResponse, Message, Tool as OllamaTool } from 'ollama';
import { logInfo, logError, logWarn } from '../utils/logger.js';
import path from 'path';

export interface OllamaMCPConfig {
  ollamaBaseUrl?: string;
  mcpServerPath?: string;
  defaultModel?: string;
  defaultTemperature?: number;
  maxTokens?: number;
  enableStreaming?: boolean;
}

export interface MCPToolCall {
  name: string;
  arguments: Record<string, any>;
}

export interface OllamaChatOptions {
  model?: string;
  temperature?: number;
  maxTokens?: number;
  tools?: string[]; // Tool names to make available
  stream?: boolean;
}

/**
 * Ollama MCP Client
 *
 * Integrates Ollama LLM with MCP filesystem tools.
 * Enables Ollama to perform secure file operations via MCP protocol.
 */
export class OllamaMCPClient {
  private mcpClient: Client | null = null;
  private ollama: Ollama;
  private config: Required<OllamaMCPConfig>;
  private mcpServerProcess: ChildProcess | null = null;
  private isConnected: boolean = false;

  constructor(config?: OllamaMCPConfig) {
    this.config = {
      ollamaBaseUrl: config?.ollamaBaseUrl || process.env.OLLAMA_BASE_URL || 'http://localhost:11434',
      mcpServerPath: config?.mcpServerPath || path.resolve('dist/server/mcp_server.js'),
      defaultModel: config?.defaultModel || 'qwen2.5-coder:7b',
      defaultTemperature: config?.defaultTemperature ?? 0.7,
      maxTokens: config?.maxTokens || 4096,
      enableStreaming: config?.enableStreaming ?? false
    };

    this.ollama = new Ollama({ host: this.config.ollamaBaseUrl });
    logInfo('OllamaMCPClient', 'Client initialized');
  }

  /**
   * Connect to MCP server
   */
  async connect(): Promise<void> {
    if (this.isConnected) {
      logWarn('OllamaMCPClient', 'Already connected to MCP server');
      return;
    }

    try {
      // Spawn MCP server process
      logInfo('OllamaMCPClient', `Starting MCP server: ${this.config.mcpServerPath}`);

      this.mcpServerProcess = spawn('node', [this.config.mcpServerPath], {
        stdio: ['pipe', 'pipe', 'pipe']
      });

      // Handle server process errors
      this.mcpServerProcess.on('error', (error) => {
        logError('OllamaMCPClient', `MCP server process error: ${error.message}`);
      });

      this.mcpServerProcess.stderr?.on('data', (data) => {
        logWarn('OllamaMCPClient', `MCP server stderr: ${data.toString()}`);
      });

      // Create MCP client with stdio transport
      const transport = new StdioClientTransport({
        command: 'node',
        args: [this.config.mcpServerPath]
      });

      this.mcpClient = new Client(
        {
          name: 'brunella-ollama-client',
          version: '1.0.0'
        },
        {
          capabilities: {}
        }
      );

      await this.mcpClient.connect(transport);
      this.isConnected = true;

      logInfo('OllamaMCPClient', 'Connected to MCP server');
    } catch (error: any) {
      logError('OllamaMCPClient', `Failed to connect to MCP server: ${error.message}`);
      const cause = error instanceof Error ? error : undefined;
      throw new Error(`MCP connection failed: ${error.message}`, { cause });
    }
  }

  /**
   * Disconnect from MCP server
   */
  async disconnect(): Promise<void> {
    if (!this.isConnected) {
      return;
    }

    try {
      if (this.mcpClient) {
        await this.mcpClient.close();
        this.mcpClient = null;
      }

      if (this.mcpServerProcess) {
        this.mcpServerProcess.kill();
        this.mcpServerProcess = null;
      }

      this.isConnected = false;
      logInfo('OllamaMCPClient', 'Disconnected from MCP server');
    } catch (error: any) {
      logError('OllamaMCPClient', `Error during disconnect: ${error.message}`);
    }
  }

  /**
   * Get available MCP tools
   */
  async listTools(): Promise<OllamaTool[]> {
    if (!this.isConnected || !this.mcpClient) {
      throw new Error('Not connected to MCP server. Call connect() first.');
    }

    try {
      const { tools } = await this.mcpClient.listTools();

      // Convert MCP tools to Ollama tool format
      const ollamaTools: OllamaTool[] = tools.map(tool => ({
        type: 'function',
        function: {
          name: tool.name,
          description: tool.description || '',
          parameters: tool.inputSchema
        }
      }));

      logInfo('OllamaMCPClient', `Listed ${ollamaTools.length} MCP tools`);
      return ollamaTools;
    } catch (error: any) {
      logError('OllamaMCPClient', `Failed to list tools: ${error.message}`);
      throw error;
    }
  }

  /**
   * Chat with Ollama using MCP tools
   */
  async chat(prompt: string, options?: OllamaChatOptions): Promise<ChatResponse> {
    if (!this.isConnected || !this.mcpClient) {
      throw new Error('Not connected to MCP server. Call connect() first.');
    }

    const model = options?.model || this.config.defaultModel;
    const temperature = options?.temperature ?? this.config.defaultTemperature;
    const maxTokens = options?.maxTokens || this.config.maxTokens;
    const stream = options?.stream ?? this.config.enableStreaming;

    try {
      // Get available MCP tools
      const allTools = await this.listTools();

      // Filter tools if specific tools requested
      const tools = options?.tools && options.tools.length > 0
        ? allTools.filter(t => t.function.name && options.tools!.includes(t.function.name))
        : allTools;

      logInfo('OllamaMCPClient', `Chat with model ${model}, ${tools.length} tools available`);

      // Initial chat request
      const messages: Message[] = [{ role: 'user', content: prompt }];

      // Initial chat request (non-streaming for tool calls)
      let response = await this.ollama.chat({
        model,
        messages,
        tools,
        stream: false,
        options: {
          temperature,
          num_predict: maxTokens
        }
      });

      // Handle tool calls (iterative refinement)
      let iterations = 0;
      const maxIterations = 5;

      while (response.message.tool_calls && iterations < maxIterations) {
        iterations++;
        logInfo('OllamaMCPClient', `Tool calls detected (iteration ${iterations})`);

        // Execute each tool call
        const toolResults = await Promise.all(
          response.message.tool_calls.map(async (toolCall: any) => {
            return await this.executeTool(toolCall.function.name, toolCall.function.arguments);
          })
        );

        // Add assistant message with tool calls
        messages.push(response.message);

        // Add tool results as messages
        toolResults.forEach((result: any) => {
          messages.push({
            role: 'tool',
            content: JSON.stringify(result)
          });
        });

        // Continue conversation with tool results
        response = await this.ollama.chat({
          model,
          messages,
          tools,
          stream: false,
          options: {
            temperature,
            num_predict: maxTokens
          }
        });
      }

      if (iterations >= maxIterations) {
        logWarn('OllamaMCPClient', 'Max tool call iterations reached');
      }

      logInfo('OllamaMCPClient', `Chat completed in ${iterations} iterations`);
      return response;
    } catch (error: any) {
      logError('OllamaMCPClient', `Chat failed: ${error.message}`);
      throw error;
    }
  }

  /**
   * Execute MCP tool
   */
  private async executeTool(toolName: string, args: Record<string, any>): Promise<any> {
    if (!this.mcpClient) {
      throw new Error('MCP client not initialized');
    }

    try {
      logInfo('OllamaMCPClient', `Executing tool: ${toolName}`);

      const result = await this.mcpClient.callTool({
        name: toolName,
        arguments: args
      });

      // Extract text content from result
      if (result.content && Array.isArray(result.content)) {
        const textContent = result.content.find(c => c.type === 'text');
        if (textContent && 'text' in textContent) {
          try {
            // Try to parse JSON response
            return JSON.parse(textContent.text);
          } catch {
            // Return raw text if not JSON
            return { success: true, data: textContent.text };
          }
        }
      }

      return result;
    } catch (error: any) {
      logError('OllamaMCPClient', `Tool execution failed: ${error.message}`);
      return {
        success: false,
        error: error.message
      };
    }
  }

  /**
   * Simple file read via MCP (convenience method)
   */
  async readFile(filePath: string): Promise<string> {
    const result = await this.executeTool('read_file', { path: filePath });

    if (!result.success) {
      throw new Error(`Failed to read file: ${result.error}`);
    }

    return result.content;
  }

  /**
   * Simple file write via MCP (convenience method)
   */
  async writeFile(filePath: string, content: string): Promise<boolean> {
    const result = await this.executeTool('write_file', {
      path: filePath,
      content
    });

    if (!result.success) {
      throw new Error(`Failed to write file: ${result.error}`);
    }

    return true;
  }

  /**
   * List directory contents via MCP (convenience method)
   */
  async listDirectory(dirPath: string, includeHidden: boolean = false): Promise<any[]> {
    const result = await this.executeTool('list_directory', {
      path: dirPath,
      include_hidden: includeHidden
    });

    if (!result.success) {
      throw new Error(`Failed to list directory: ${result.error}`);
    }

    return result.items;
  }

  /**
   * Search files via MCP (convenience method)
   */
  async searchFiles(pattern: string, directory?: string): Promise<string[]> {
    const result = await this.executeTool('search_files', {
      pattern,
      directory
    });

    if (!result.success) {
      throw new Error(`Failed to search files: ${result.error}`);
    }

    return result.matches;
  }

  /**
   * Check if connected to MCP server
   */
  isConnectedToMCP(): boolean {
    return this.isConnected;
  }

  /**
   * Get current configuration
   */
  getConfig(): Required<OllamaMCPConfig> {
    return { ...this.config };
  }
}

/**
 * Singleton instance for easy access
 */
let clientInstance: OllamaMCPClient | null = null;

/**
 * Get or create OllamaMCPClient singleton
 */
export function getOllamaMCPClient(config?: OllamaMCPConfig): OllamaMCPClient {
  if (!clientInstance) {
    clientInstance = new OllamaMCPClient(config);
  }
  return clientInstance;
}

/**
 * Reset singleton (mainly for testing)
 */
export function resetOllamaMCPClient(): void {
  if (clientInstance) {
    clientInstance.disconnect().catch(() => {});
    clientInstance = null;
  }
}

/**
 * PhoenixEventBus - Unified Pub/Sub Event System
 *
 * Connects isolated event systems (logger EventEmitter, Socket.IO, agent events)
 * into a single, typed event bus for Phoenix Protocol Szint 4-5.
 *
 * Events:
 *   phoenix:agent_failed      - Agent failed after all retries exhausted
 *   phoenix:failover_triggered - Cross-agent failover initiated
 *   phoenix:failover_result   - Failover completed (success or final failure)
 *   phoenix:edge_health       - Edge health status changed
 *   phoenix:circuit_breaker   - Circuit breaker state change
 *   phoenix:recovery          - Recovery event (crash, restart, git_checkpoint)
 *
 * @version 1.0.0
 */

import { EventEmitter } from 'events';
import { logInfo, logError } from '../utils/logger.js';

// ============================================================================
// EVENT TYPES
// ============================================================================

export interface PhoenixAgentFailedEvent {
  agentName: string;
  taskInstruction: string;
  taskContext?: Record<string, unknown>;
  error: string;
  retriesExhausted: number;
  timestamp: string;
}

export interface PhoenixFailoverTriggeredEvent {
  originalAgent: string;
  fallbackAgent: string;
  taskInstruction: string;
  attempt: number;
  timestamp: string;
}

export interface PhoenixFailoverResultEvent {
  originalAgent: string;
  fallbackAgent: string;
  taskInstruction: string;
  success: boolean;
  error?: string;
  executionTimeMs: number;
  timestamp: string;
}

export interface PhoenixEdgeHealthEvent {
  status: 'healthy' | 'degraded' | 'offline';
  previousStatus: 'healthy' | 'degraded' | 'offline';
  latencyMs: number;
  timestamp: string;
}

export interface PhoenixCircuitBreakerEvent {
  agentName: string;
  state: 'open' | 'closed' | 'half-open';
  previousState: 'open' | 'closed' | 'half-open';
  failures: number;
  timestamp: string;
}

export interface PhoenixRecoveryEvent {
  type: 'crash' | 'restart' | 'git_checkpoint' | 'failover';
  agent: string;
  details: string;
  timestamp: string;
}

export interface PhoenixRestartEvent {
  serviceName: string;
  success: boolean;
  error?: string;
  timestamp: string;
}

export interface PhoenixStateRestoredEvent {
  agentName: string;
  taskId: string;
  stepIndex: number;
  stepName: string;
  timestamp: string;
}

export interface PhoenixDegradedEvent {
  level: 'full' | 'partial' | 'minimal' | 'offline';
  services: string[];
  message: string;
  timestamp: string;
}

export type PhoenixEventMap = {
  'phoenix:agent_failed': PhoenixAgentFailedEvent;
  'phoenix:failover_triggered': PhoenixFailoverTriggeredEvent;
  'phoenix:failover_result': PhoenixFailoverResultEvent;
  'phoenix:edge_health': PhoenixEdgeHealthEvent;
  'phoenix:circuit_breaker': PhoenixCircuitBreakerEvent;
