  instance = null;
}

/**
 * ReflectionEngine — Self-reflection loop for agent learning
 * 
 * After task completion, evaluates performance, extracts lessons,
 * and persists them to GraphRAG + SelfModel for continuous improvement.
 * 
 * Architecture:
 *   Task completed → evaluate(outcome) → extract lessons → persist to GraphRAG
 *   → update SelfModel signals → inform future decisions
 * 
 * Wraps: SelfModel (capability tracking) + MetaReasoner (decision analysis)
 */

import { SelfModel, type SelfModelSignal } from './selfModel.js';
import { MetaReasoner, type DecisionRecord, type MetaInsight } from './metaReasoner.js';
import { GraphRagEngine } from './graphRagEngine.js';
import { logInfo, logWarn } from '../utils/logger.js';

// ─── Types ───────────────────────────────────────────────────────────────────

export interface TaskOutcome {
  taskId: string | number;
  agent: string;
  task: string;
  result: 'success' | 'failure' | 'partial';
  output: string;
  durationMs: number;
  errorMessage?: string;
  metadata?: Record<string, unknown>;
}

export interface ReflectionResult {
  taskId: string | number;
  qualityScore: number;      // 0-1
  lessons: string[];
  improvements: string[];
  selfModelUpdated: boolean;
  metaInsights: MetaInsight[];
}

export interface ReflectionStats {
  totalReflections: number;
  avgQualityScore: number;
  totalLessons: number;
  selfModelHealth: string;
  metaReasonerStats: { decisions: number; insights: number; sessions: number };
}

// ─── Reflection Engine ───────────────────────────────────────────────────────

export class ReflectionEngine {
  private static instance: ReflectionEngine | null = null;
  private selfModel: SelfModel;
  private metaReasoner: MetaReasoner;
  private reflectionCount = 0;
  private totalQuality = 0;
  private totalLessons = 0;

  private constructor() {
    this.selfModel = new SelfModel('Brunella Orchestrator');
    this.metaReasoner = new MetaReasoner();

    // Set core constraints
    this.selfModel.setConstraint('Mindig magyarul válaszolj');
    this.selfModel.setConstraint('Ne hajtsd végre valódi műveletet jóváhagyás nélkül magas kockázat esetén');
    this.selfModel.setConstraint('Logolj mindent, de ne tedd ki titkokat');
  }

  static getInstance(): ReflectionEngine {
    if (!ReflectionEngine.instance) {
      ReflectionEngine.instance = new ReflectionEngine();
    }
    return ReflectionEngine.instance;
  }

  /**
   * Reflect on a completed task — evaluate quality, extract lessons, update models.
   * Called after each agent task completion.
   */
  async reflect(outcome: TaskOutcome): Promise<ReflectionResult> {
    this.reflectionCount++;
    const qualityScore = this.evaluateQuality(outcome);
    const lessons = this.extractLessons(outcome, qualityScore);
    const improvements = this.suggestImprovements(outcome, qualityScore);

    // 1. Record decision in MetaReasoner
    this.metaReasoner.recordDecision({
      decisionMaker: outcome.agent,
      action: outcome.task,
      context: {
        taskId: outcome.taskId,
        durationMs: outcome.durationMs,
        outputLength: outcome.output.length,
        ...outcome.metadata,
      },
      outcome: outcome.result,
      outcomeDetails: outcome.errorMessage || outcome.output.slice(0, 200),
      metrics: {
        quality: qualityScore,
        durationMs: outcome.durationMs,
        outputLength: outcome.output.length,
      },
    });

    // 2. Update SelfModel with performance signal
    this.selfModel.ingestSignal({
      source: outcome.agent,
      category: outcome.result === 'failure' ? 'risk' : 'performance',
      confidence: qualityScore,
      payload: {
        capability: outcome.agent,
        area: outcome.task.slice(0, 50),
        quality: qualityScore,
        result: outcome.result,
        severity: qualityScore < 0.3 ? 'high' : qualityScore < 0.6 ? 'medium' : 'low',
        description: outcome.result === 'failure'
          ? `Hiba: ${outcome.errorMessage || 'ismeretlen'}`
          : `Sikeres végrehajtás (minőség: ${(qualityScore * 100).toFixed(0)}%)`,
      },
    });

    // 3. Persist lessons to GraphRAG
    const graphRag = GraphRagEngine.getInstance();
    for (const lesson of lessons) {
      graphRag.storeLesson(
        `reflection-${outcome.taskId}`,
        outcome.agent,
        outcome.task,
        lesson,
        qualityScore,
      );
    }

    // 4. Run MetaReasoner periodically (every 10 reflections)
    let metaInsights: MetaInsight[] = [];
    if (this.reflectionCount % 10 === 0) {
      metaInsights = this.metaReasoner.reason();
      if (metaInsights.length > 0) {
        logInfo('ReflectionEngine', `MetaReasoner: ${metaInsights.length} insight(s) — ${metaInsights.map(i => i.description.slice(0, 40)).join('; ')}`);
      }
    }

    // 5. Self-reflect periodically (every 20 reflections)
    let selfModelUpdated = false;
    if (this.reflectionCount % 20 === 0) {
      this.selfModel.reflect();
      selfModelUpdated = true;
      const state = this.selfModel.getState();
      logInfo('ReflectionEngine', `SelfModel reflection: health=${state.health}, coherence=${state.coherence.toFixed(2)}, blindSpots=${state.blindSpots.length}`);
    }

    this.totalQuality += qualityScore;
    this.totalLessons += lessons.length;

    logInfo('ReflectionEngine', `Reflected on [${outcome.agent}] ${outcome.task.slice(0, 40)}: quality=${(qualityScore * 100).toFixed(0)}%, lessons=${lessons.length}`);

    return {
      taskId: outcome.taskId,
      qualityScore,
      lessons,
      improvements,
      selfModelUpdated,
      metaInsights,
    };
  }

  /**
   * Evaluate quality of a task outcome (0-1 score).
   */
  private evaluateQuality(outcome: TaskOutcome): number {
    let score = 0.5; // baseline

    // Result factor
    if (outcome.result === 'success') score += 0.3;
    else if (outcome.result === 'partial') score += 0.1;
    else score -= 0.3;

    // Duration factor (faster is better, up to a point)
    if (outcome.durationMs < 5000) score += 0.1;
    else if (outcome.durationMs > 60000) score -= 0.1;

    // Output factor (non-empty output is good)
    if (outcome.output.length > 50) score += 0.05;
    if (outcome.output.length > 500) score += 0.05;

    // Error penalty
    if (outcome.errorMessage) score -= 0.15;

    return Math.max(0, Math.min(1, score));
  }

  /**
   * Extract actionable lessons from outcome.
   */
  private extractLessons(outcome: TaskOutcome, qualityScore: number): string[] {
    const lessons: string[] = [];

    if (outcome.result === 'failure') {
      lessons.push(
        `${outcome.agent} nem tudta elvégezni: "${outcome.task.slice(0, 80)}" — ok: ${outcome.errorMessage || 'ismeretlen'}`,
      );
      if (outcome.durationMs > 30000) {
        lessons.push(`${outcome.agent} túl sokáig futott (${(outcome.durationMs / 1000).toFixed(1)}s) mielőtt hibázott — időkorlát csökkentés javasolt`);
      }
    }

    if (outcome.result === 'success' && qualityScore > 0.8) {
      lessons.push(
        `${outcome.agent} kiválóan teljesített ("${outcome.task.slice(0, 60)}") — ez a feladattípus jól passzol hozzá`,
      );
    }

    if (outcome.result === 'partial') {
      lessons.push(
        `${outcome.agent} csak részben végezte el: "${outcome.task.slice(0, 60)}" — érdemes lehet más ágenssel kiegészíteni`,
      );
    }

    return lessons;
  }

  /**
   * Suggest improvements based on outcome patterns.
   */
  private suggestImprovements(outcome: TaskOutcome, qualityScore: number): string[] {
    const improvements: string[] = [];

    if (qualityScore < 0.4) {
      improvements.push(`Fontold meg más ágens használatát a "${outcome.task.slice(0, 40)}" típusú feladatokra`);
    }

    if (outcome.durationMs > 30000 && outcome.result === 'success') {
      improvements.push('A feladat sikeres de lassú — párhuzamos feldolgozás javíthatná a sebességet');
    }

    if (outcome.result === 'failure' && outcome.errorMessage?.includes('timeout')) {
      improvements.push('Timeout hiba — növeld a limitet vagy bontsd kisebb részekre a feladatot');
    }

    return improvements;
  }

  /**
   * Get context summary for system prompt enrichment.
   * Provides recent insights and blind spots to help the orchestrator make better decisions.
   */
  getReflectionContext(): string {
    const selfState = this.selfModel.getState();
    const recentInsights = this.metaReasoner.getInsights().slice(-5);
    const parts: string[] = [];

    if (selfState.blindSpots.length > 0) {
      const blindSpotsSummary = selfState.blindSpots
        .slice(0, 3)
        .map(b => `${b.area} (${b.severity})`)
        .join(', ');
      parts.push(`⚠️ Ismert gyengeségek: ${blindSpotsSummary}`);
    }

    if (selfState.capabilities.length > 0) {
      const topCapabilities = selfState.capabilities
        .filter(c => c.state === 'confident')
        .slice(0, 3)
        .map(c => c.capability)
        .join(', ');
      if (topCapabilities) {
        parts.push(`✅ Erősségek: ${topCapabilities}`);
      }
    }

    if (recentInsights.length > 0) {
      const insightsSummary = recentInsights
        .map(i => `[${i.category}] ${i.description.slice(0, 60)}`)
        .join('; ');
      parts.push(`🧠 Meta-insight-ok: ${insightsSummary}`);
    }

    parts.push(`📈 Rendszer koherencia: ${(selfState.coherence * 100).toFixed(0)}% (${selfState.health})`);

    return parts.length > 0
      ? `\n🔄 Reflexiós kontextus:\n${parts.join('\n')}`
      : '';
  }

  /** Get stats */
  getStats(): ReflectionStats {
    return {
      totalReflections: this.reflectionCount,
      avgQualityScore: this.reflectionCount > 0 ? this.totalQuality / this.reflectionCount : 0,
      totalLessons: this.totalLessons,
      selfModelHealth: this.selfModel.getState().health,
      metaReasonerStats: this.metaReasoner.getStats(),
    };
  }

  /** Get SelfModel state for monitoring */
  getSelfModelState() { return this.selfModel.getState(); }

  /** Get MetaReasoner insights */
  getMetaInsights(category?: 'pattern' | 'anomaly' | 'recommendation' | 'warning') {
    return this.metaReasoner.getInsights(category);
  }
}

/**
 * WASM/VM Sandbox — Secure JS/TS Code Execution Engine
 *
 * Uses Node.js built-in `vm` module for zero-dependency code isolation.
 * Features:
 * - Sandboxed execution with no host access (no process, fs, require)
 * - CPU timeout enforcement (maxCpuMs)
 * - Memory limit tracking (maxMemoryMB via context size)
 * - Instance pool for reuse (pre-warm, execute, reset, return)
 * - Custom error types: SandboxTimeoutError, SandboxOOMError
 *
 * @track sandbox_security_hardening_20260323
 * @phase Phase 1: WASM Sandbox (Node.js Code Isolation)
 */

import vm from 'vm';
import { logInfo, logWarn, logError } from '../../utils/logger.js';

// ============================================================================
// TYPES & ERRORS
// ============================================================================

export class SandboxTimeoutError extends Error {
  constructor(timeoutMs: number) {
    super(`Sandbox execution timed out after ${timeoutMs}ms`);
    this.name = 'SandboxTimeoutError';
  }
}

export class SandboxOOMError extends Error {
  constructor(limitMB: number) {
    super(`Sandbox exceeded memory limit of ${limitMB}MB`);
    this.name = 'SandboxOOMError';
  }
}

export class SandboxSecurityError extends Error {
  constructor(message: string) {
    super(`Sandbox security violation: ${message}`);
    this.name = 'SandboxSecurityError';
  }
}

export interface SandboxConfig {
  maxMemoryMB: number;      // Default: 128
  maxCpuMs: number;         // Default: 5000
  maxOutputSize: number;    // Default: 1MB (bytes)
  poolSize: number;         // Default: 3
  allowedGlobals?: string[];
}

export interface SandboxResult {
  success: boolean;
  output: string;
  error?: string;
  durationMs: number;
  memoryUsedBytes: number;
}

interface PooledInstance {
  id: number;
  context: vm.Context;
  inUse: boolean;
  executionCount: number;
  createdAt: number;
}

const DEFAULT_CONFIG: SandboxConfig = {
  maxMemoryMB: 128,
  maxCpuMs: 5000,
  maxOutputSize: 1_048_576, // 1MB
  poolSize: 3,
};

// Dangerous globals that must be blocked
const BLOCKED_GLOBALS = [
  'process', 'require', 'module', 'exports', '__filename', '__dirname',
  'globalThis', 'global', 'Buffer', 'fetch', 'XMLHttpRequest',
  'WebSocket', 'Worker', 'SharedArrayBuffer', 'Atomics',
  'eval',  // block nested eval
];

// Safe globals allowed in sandbox
const SAFE_GLOBALS = [
  'console', 'Math', 'Date', 'JSON', 'parseInt', 'parseFloat',
  'isNaN', 'isFinite', 'Number', 'String', 'Boolean', 'Array',
  'Object', 'Map', 'Set', 'WeakMap', 'WeakSet', 'Symbol',
  'Promise', 'RegExp', 'Error', 'TypeError', 'RangeError',
  'SyntaxError', 'URIError', 'encodeURI', 'decodeURI',
  'encodeURIComponent', 'decodeURIComponent',
  'setTimeout', 'clearTimeout', 'setInterval', 'clearInterval',
];

// ============================================================================
// SANDBOX POOL
// ============================================================================

export class SandboxPool {
  private instances: PooledInstance[] = [];
  private config: SandboxConfig;
  private nextId = 0;
  private stats = {
    totalExecutions: 0,
    successfulExecutions: 0,
    timeouts: 0,
    oomErrors: 0,
    securityViolations: 0,
    totalDurationMs: 0,
  };

  constructor(config: Partial<SandboxConfig> = {}) {
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /**
   * Pre-warm the pool with ready-to-use sandbox instances
   */
  warmUp(): void {
    const count = this.config.poolSize - this.instances.length;
    for (let i = 0; i < count; i++) {
      this.instances.push(this.createInstance());
    }
    logInfo('[SandboxPool]', `Pool warmed: ${this.instances.length} instances ready`);
  }

  /**
   * Execute code in a sandboxed context
   */
  async execute(code: string, options?: Partial<SandboxConfig>): Promise<SandboxResult> {
    const startTime = Date.now();
    const maxCpuMs = options?.maxCpuMs ?? this.config.maxCpuMs;
    const maxOutputSize = options?.maxOutputSize ?? this.config.maxOutputSize;

    // Security: reject code with dangerous patterns
    try {
      this.validateCode(code);
    } catch (err: unknown) {
      this.stats.totalExecutions++;
      this.stats.securityViolations++;
      return {
        success: false,
        output: '',
        error: (err as Error).message,
        durationMs: Date.now() - startTime,
        memoryUsedBytes: 0,
      };
    }

    const instance = this.acquireInstance();
    this.stats.totalExecutions++;

    try {
      // Capture console output
      const outputLines: string[] = [];
      let totalOutputBytes = 0;

      const sandboxConsole = {
        log: (...args: unknown[]) => {
          const line = args.map(a => typeof a === 'object' ? JSON.stringify(a) : String(a)).join(' ');
          totalOutputBytes += Buffer.byteLength(line, 'utf8');
          if (totalOutputBytes > maxOutputSize) {
            throw new SandboxOOMError(Math.round(maxOutputSize / 1024 / 1024));
          }
          outputLines.push(line);
        },
        error: (...args: unknown[]) => {
          const line = '[ERROR] ' + args.map(a => String(a)).join(' ');
          outputLines.push(line);
        },
        warn: (...args: unknown[]) => {
          const line = '[WARN] ' + args.map(a => String(a)).join(' ');
          outputLines.push(line);
        },
        info: (...args: unknown[]) => {
          const line = args.map(a => String(a)).join(' ');
          outputLines.push(line);
        },
      };

      // Set up sandboxed context
      instance.context.console = sandboxConsole;
      instance.context.__result = undefined;

      // Wrap code to capture return value
      const wrappedCode = `
        (function() {
          'use strict';
          try {
            ${code}
          } catch(e) {
            console.error(e.message || String(e));
            throw e;
          }
        })();
      `;

      const script = new vm.Script(wrappedCode, {
        filename: `sandbox-${instance.id}.js`,
      });

      // Execute with timeout
      script.runInContext(instance.context, {
        timeout: maxCpuMs,
        breakOnSigint: true,
      });

      const durationMs = Date.now() - startTime;
      this.stats.successfulExecutions++;
      this.stats.totalDurationMs += durationMs;

      instance.executionCount++;

      return {
        success: true,
        output: outputLines.join('\n'),
        durationMs,
        memoryUsedBytes: totalOutputBytes,
      };
    } catch (err: unknown) {
      const durationMs = Date.now() - startTime;
      this.stats.totalDurationMs += durationMs;

      if (err instanceof SandboxOOMError) {
        this.stats.oomErrors++;
        return { success: false, output: '', error: (err as Error).message, durationMs, memoryUsedBytes: maxOutputSize };
      }

      if (err instanceof SandboxSecurityError) {
        this.stats.securityViolations++;
        return { success: false, output: '', error: (err as Error).message, durationMs, memoryUsedBytes: 0 };
      }

      // vm timeout throws generic Error with specific message
      const errMsg = (err as Error)?.message ?? String(err);
      if (errMsg.includes('Script execution timed out')) {
        this.stats.timeouts++;
        return {
          success: false,
          output: '',
          error: new SandboxTimeoutError(maxCpuMs).message,
          durationMs,
          memoryUsedBytes: 0,
        };
      }

      return {
        success: false,
        output: '',
        error: errMsg,
        durationMs,
        memoryUsedBytes: 0,
      };
    } finally {
      this.releaseInstance(instance);
    }
  }

  /**
   * Get pool statistics
   */
  getStats() {
    return {
      ...this.stats,
      avgDurationMs: this.stats.totalExecutions > 0
        ? Math.round(this.stats.totalDurationMs / this.stats.totalExecutions)
        : 0,
      poolSize: this.instances.length,
      activeInstances: this.instances.filter(i => i.inUse).length,
      idleInstances: this.instances.filter(i => !i.inUse).length,
    };
  }

  /**
   * Destroy pool and free all resources
   */
  destroy(): void {
    this.instances = [];
    logInfo('[SandboxPool]', 'Pool destroyed');
  }

  // --------------------------------------------------------------------------
  // Private helpers
  // --------------------------------------------------------------------------

  private createInstance(): PooledInstance {
    const id = this.nextId++;
    const sandbox: Record<string, unknown> = {};

    // Copy safe globals
    for (const name of SAFE_GLOBALS) {
      if (name in globalThis) {
        sandbox[name] = (globalThis as Record<string, unknown>)[name];
      }
    }

    // Block dangerous globals explicitly
    for (const name of BLOCKED_GLOBALS) {
      sandbox[name] = undefined;
    }

    const context = vm.createContext(sandbox, {
      name: `sandbox-${id}`,
      codeGeneration: { strings: false, wasm: false },
    });

    return {
      id,
      context,
      inUse: false,
      executionCount: 0,
      createdAt: Date.now(),
    };
  }

  private acquireInstance(): PooledInstance {
    let instance = this.instances.find(i => !i.inUse);
    if (!instance) {
      instance = this.createInstance();
      this.instances.push(instance);
    }
    instance.inUse = true;
    return instance;
  }

  private releaseInstance(instance: PooledInstance): void {
    instance.inUse = false;
    // Reset context state after use (remove any user-defined vars)
    try {
      const resetScript = new vm.Script(`
        for (const key of Object.getOwnPropertyNames(this)) {
          if (!['console','Math','Date','JSON','parseInt','parseFloat','isNaN','isFinite',
                 'Number','String','Boolean','Array','Object','Map','Set','WeakMap','WeakSet',
                 'Symbol','Promise','RegExp','Error','TypeError','RangeError','SyntaxError',
                 'URIError','encodeURI','decodeURI','encodeURIComponent','decodeURIComponent',
                 'setTimeout','clearTimeout','setInterval','clearInterval','__result',
                 'undefined'].includes(key)) {
            try { delete this[key]; } catch {}
          }
        }
      `);
      resetScript.runInContext(instance.context, { timeout: 100 });
    } catch {
      // If reset fails, replace instance
      const idx = this.instances.indexOf(instance);
      if (idx >= 0) {
        this.instances[idx] = this.createInstance();
      }
    }
  }

  private validateCode(code: string): void {
    // Block dangerous patterns
    const dangerousPatterns = [
      /\bprocess\s*\./,
      /\brequire\s*\(/,
      /\bimport\s*\(/,
      /\b__proto__\b/,
      /\bconstructor\s*\[\s*['"]prototype['"]\s*\]/,
      /\bFunction\s*\(/,
      /\bchild_process\b/,
      /\bexecSync\b/,
      /\bspawnSync\b/,
    ];

    for (const pattern of dangerousPatterns) {
      if (pattern.test(code)) {
        throw new SandboxSecurityError(
          `Blocked dangerous pattern: ${pattern.source}`
        );
      }
    }
  }
}

// ============================================================================
// SINGLETON
// ============================================================================

let defaultPool: SandboxPool | null = null;

export function getSandboxPool(config?: Partial<SandboxConfig>): SandboxPool {
  if (!defaultPool) {
    defaultPool = new SandboxPool(config);
    defaultPool.warmUp();
  }
  return defaultPool;
}

export function resetSandboxPool(): void {
  if (defaultPool) {
    defaultPool.destroy();
    defaultPool = null;
  }
}

import * as cron from 'node-cron';
import Database from 'better-sqlite3';
import { logInfo, logError } from '../utils/logger.js';

interface ScheduledTaskRecord {
  id: string;
  task_name: string;
  cron_pattern: string;
  api_endpoint: string;
  method: 'GET' | 'POST';
  payload?: string;
  enabled: boolean;
  last_run?: string;
  next_run?: string;
  created_at: string;
}

interface ScheduleResult {
  success: boolean;
  taskId?: string;
  message: string;
  nextRun?: string;
}

export class ScheduledTasksEngine {
  private db: Database.Database;
  private tasks: Map<string, cron.ScheduledTask> = new Map();

  constructor(db: Database.Database) {
    this.db = db;
    logInfo('ScheduledTasksEngine', 'Initialized');
  }

  /**
   * Schedule a new task with cron pattern
   */
  scheduleTask(record: ScheduledTaskRecord): ScheduleResult {
    try {
      // Validate cron pattern
      if (!cron.validate(record.cron_pattern)) {
        return { success: false, message: 'Invalid cron pattern' };
      }

      // Create scheduled task
      const task = cron.schedule(record.cron_pattern, async () => {
        await this.executeTask(record);
      });

      // Store in memory
      this.tasks.set(record.id, task);

      // Calculate next run time
      const nextRun = `Scheduled for: ${record.cron_pattern}`;

      logInfo('ScheduledTasksEngine', `Task scheduled: ${record.task_name} → ${record.cron_pattern}`);

      return {
        success: true,
        taskId: record.id,
        message: `Task "${record.task_name}" scheduled`,
        nextRun,
      };
    } catch (e) {
      const error = e instanceof Error ? e.message : String(e);
      logError('ScheduledTasksEngine', error);
      return { success: false, message: error };
    }
  }

  /**
   * Execute a task (HTTP call to API endpoint)
   */
  private async executeTask(record: ScheduledTaskRecord): Promise<void> {
    try {
      const url = `http://localhost:3000${record.api_endpoint}`;
      const options: RequestInit = {
        method: record.method,
        headers: { 'Content-Type': 'application/json' },
      };

      if (record.method === 'POST' && record.payload) {
        options.body = record.payload;
      }

      const response = await fetch(url, options);
      const status = response.ok ? 'success' : 'failed';

      // Update last_run in DB
      this.db.prepare(`
        UPDATE scheduled_tasks 
        SET last_run = datetime('now'),
            next_run = datetime(datetime('now'), '+' || ? || 's')
        WHERE id = ?
      `).run('3600', record.id); // TODO: Calculate actual next run from cron

      logInfo('ScheduledTasksEngine', `Task executed: ${record.task_name} → ${status} (${response.status})`);
    } catch (error) {
      logError('ScheduledTasksEngine', `Failed to execute ${record.task_name}: ${error}`);
    }
  }

  /**
   * Stop a scheduled task
   */
  stopTask(taskId: string): ScheduleResult {
    try {
      const task = this.tasks.get(taskId);
      if (!task) {
        return { success: false, message: 'Task not found' };
      }

      task.stop();
      this.tasks.delete(taskId);

      // Mark as disabled in DB
      this.db.prepare('UPDATE scheduled_tasks SET enabled = 0 WHERE id = ?').run(taskId);

      logInfo('ScheduledTasksEngine', `Task stopped: ${taskId}`);
      return { success: true, message: 'Task stopped' };
    } catch (e) {
      const error = e instanceof Error ? e.message : String(e);
      return { success: false, message: error };
    }
  }

  /**
   * Load all enabled tasks from DB and schedule them
   */
  loadScheduledTasks(): ScheduleResult {
    try {
      const tasks = this.db
        .prepare('SELECT * FROM scheduled_tasks WHERE enabled = 1')
        .all() as ScheduledTaskRecord[];

      let scheduled = 0;
      for (const task of tasks) {
        const result = this.scheduleTask(task);
        if (result.success) scheduled++;
      }

      logInfo('ScheduledTasksEngine', `Loaded and scheduled ${scheduled}/${tasks.length} tasks`);
      return { success: true, message: `Scheduled ${scheduled} tasks` };
    } catch (e) {
      const error = e instanceof Error ? e.message : String(e);
      logError('ScheduledTasksEngine', error);
      return { success: false, message: error };
    }
  }

  /**
   * Stop all scheduled tasks
   */
  stopAllTasks(): void {
    for (const [id, task] of this.tasks) {
      task.stop();
    }
    this.tasks.clear();
    logInfo('ScheduledTasksEngine', 'All tasks stopped');
  }

  /**
   * Get status of a task
   */
  getTaskStatus(taskId: string): any {
    const record = this.db
      .prepare('SELECT * FROM scheduled_tasks WHERE id = ?')
      .get(taskId) as ScheduledTaskRecord | undefined;

    if (!record) return null;

    return {
      ...record,
      isRunning: this.tasks.has(taskId),
    };
  }

  /**
   * Get all scheduled tasks with status
   */
  getAllTasks(): any[] {
    const records = this.db
      .prepare('SELECT * FROM scheduled_tasks ORDER BY created_at DESC')
      .all() as ScheduledTaskRecord[];

    return records.map((r) => ({
      ...r,
      isRunning: this.tasks.has(r.id),
    }));
  }
}

export default ScheduledTasksEngine;

/**
 * Security Events Monitor - BAS Security Sandbox Phase 3
 * 
 * Purpose: Real-time security event tracking and alerting
 * Collects data from:
 * - Audit log (permission denials)
 * - Worker Thread Pool (suspicious crashes)
 * - E2B Sandbox (escape attempts)
 * - Agent executions (anomalies)
 * 
 * @track bas_security_sandbox_20260221
 * @phase Phase 3: Audit Trail & Monitoring
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn, logError } from '../utils/logger.js';
import { getAuditDb } from './auditLog.js';

// ============================================================================
// TYPES
// ============================================================================

export type SecurityEventType =
  | 'permission_denied'
  | 'sandbox_escape_attempt'
  | 'worker_crash'
  | 'anomalous_execution'
  | 'policy_violation'
  | 'resource_quota_exceeded'
  | 'suspicious_pattern';

export type SecurityEventSeverity = 'low' | 'medium' | 'high' | 'critical';

export interface SecurityEvent {
  id: string;
  timestamp: string;
  type: SecurityEventType;
  severity: SecurityEventSeverity;
  agent?: string;
  resource?: string;
  details: {
    message: string;
    metadata?: Record<string, unknown>;
    stackTrace?: string;
  };
  actionTaken?: string;
}

export interface SecurityAlertRule {
  id: string;
  name: string;
  eventType: SecurityEventType;
  severityThreshold: SecurityEventSeverity;
  threshold: number;  // Number of events within timeWindow
  timeWindow: number; // milliseconds
  action: 'log' | 'alert' | 'block';
  enabled: boolean;
}

export interface SecurityStats {
  totalEvents: number;
  eventsByType: Record<SecurityEventType, number>;
  eventsBySeverity: Record<SecurityEventSeverity, number>;
  last24Hours: number;
  activeAlerts: number;
}

// ============================================================================
// SECURITY EVENTS MONITOR
// ============================================================================

export class SecurityEventsMonitor extends EventEmitter {
  private events: SecurityEvent[] = [];
  private alerts: Map<string, SecurityAlertRule> = new Map();
  private eventCounts: Map<string, { count: number; firstSeen: number }> = new Map();
  private maxEventsInMemory = 1000;

  constructor() {
    super();
    this.initializeDefaultRules();
  }

  private initializeDefaultRules(): void {
    const defaultRules: SecurityAlertRule[] = [
      {
        id: 'permission-denial-spam',
        name: 'Permission Denial Spam Detection',
        eventType: 'permission_denied',
        severityThreshold: 'medium',
        threshold: 10,
        timeWindow: 60000, // 1 minute
        action: 'alert',
        enabled: true
      },
      {
        id: 'sandbox-escape-critical',
        name: 'Sandbox Escape Attempt',
        eventType: 'sandbox_escape_attempt',
        severityThreshold: 'critical',
        threshold: 1,
        timeWindow: 3600000, // 1 hour
        action: 'block',
        enabled: true
      },
      {
        id: 'worker-crash-pattern',
        name: 'Worker Crash Pattern Detection',
        eventType: 'worker_crash',
        severityThreshold: 'high',
        threshold: 5,
        timeWindow: 300000, // 5 minutes
        action: 'alert',
        enabled: true
      },
      {
        id: 'resource-quota-breach',
        name: 'Resource Quota Exceeded',
        eventType: 'resource_quota_exceeded',
        severityThreshold: 'high',
        threshold: 3,
        timeWindow: 60000, // 1 minute
        action: 'log',
        enabled: true
      }
    ];

    for (const rule of defaultRules) {
      this.alerts.set(rule.id, rule);
    }
  }

  /**
   * Record a security event
   */
  recordEvent(event: Omit<SecurityEvent, 'id' | 'timestamp'>): void {
    const fullEvent: SecurityEvent = {
      id: `sec-${Date.now()}-${Math.random().toString(36).slice(2)}`,
      timestamp: new Date().toISOString(),
      ...event
    };

    // Add to in-memory storage
    this.events.push(fullEvent);

    // Trim old events
    if (this.events.length > this.maxEventsInMemory) {
      this.events = this.events.slice(-this.maxEventsInMemory);
    }

    // Check alert rules
    this.checkAlertRules(fullEvent);

    // Emit event for listeners
    this.emit('security-event', fullEvent);

    // Log based on severity
    const logMessage = `[${fullEvent.severity.toUpperCase()}] ${fullEvent.type}: ${fullEvent.details.message}`;
    
    if (fullEvent.severity === 'critical' || fullEvent.severity === 'high') {
      logError('SecurityMonitor', logMessage);
    } else if (fullEvent.severity === 'medium') {
      logWarn('SecurityMonitor', logMessage);
    } else {
      logInfo('SecurityMonitor', logMessage);
    }
  }

  private checkAlertRules(event: SecurityEvent): void {
    for (const rule of this.alerts.values()) {
      if (!rule.enabled) continue;
      if (rule.eventType !== event.type) continue;

      // Check severity threshold
      const severities: SecurityEventSeverity[] = ['low', 'medium', 'high', 'critical'];
      const eventSevIndex = severities.indexOf(event.severity);
      const thresholdIndex = severities.indexOf(rule.severityThreshold);

      if (eventSevIndex < thresholdIndex) continue;

      // Track event count within time window
      const key = `${rule.id}:${event.type}`;
      const now = Date.now();

      if (!this.eventCounts.has(key)) {
        this.eventCounts.set(key, { count: 1, firstSeen: now });
      } else {
        const tracker = this.eventCounts.get(key)!;

        // Check if we're still within the time window
        if (now - tracker.firstSeen <= rule.timeWindow) {
          tracker.count++;

          // Threshold exceeded?
          if (tracker.count >= rule.threshold) {
            this.triggerAlert(rule, event, tracker.count);
            
            // Reset tracker after alert
            this.eventCounts.delete(key);
          }
        } else {
          // Time window expired, reset
          this.eventCounts.set(key, { count: 1, firstSeen: now });
        }
      }
    }
  }

  private triggerAlert(rule: SecurityAlertRule, event: SecurityEvent, count: number): void {
    const alert = {
      ruleId: rule.id,
      ruleName: rule.name,
      triggeredBy: event,
      count,
      action: rule.action,
      timestamp: new Date().toISOString()
    };

    logError('SecurityMonitor', `🚨 ALERT: ${rule.name} triggered (${count} events)`);
    
    // Emit alert event
    this.emit('security-alert', alert);

    // Take action based on rule
    switch (rule.action) {
      case 'log':
        // Already logged above
        break;
      
      case 'alert':
        // TODO: Send notification (email, Slack, etc.)
        logWarn('SecurityMonitor', `Alert notification should be sent for: ${rule.name}`);
        break;
      
      case 'block':
        // TODO: Implement blocking mechanism
        logError('SecurityMonitor', `Blocking action required for: ${rule.name}`);
        if (event.agent) {
          this.emit('block-agent', event.agent);
        }
        break;
    }
  }

  /**
   * Get security statistics
   */
  getStats(): SecurityStats {
    const now = Date.now();
    const last24Hours = now - 24 * 60 * 60 * 1000;

    const eventsByType: Record<string, number> = {};
    const eventsBySeverity: Record<string, number> = {};
    let last24HoursCount = 0;

    for (const event of this.events) {
      const eventTime = new Date(event.timestamp).getTime();

      // Count by type
      eventsByType[event.type] = (eventsByType[event.type] || 0) + 1;

      // Count by severity
      eventsBySeverity[event.severity] = (eventsBySeverity[event.severity] || 0) + 1;

      // Count last 24 hours
      if (eventTime >= last24Hours) {
        last24HoursCount++;
      }
    }

    return {
      totalEvents: this.events.length,
      eventsByType: eventsByType as Record<SecurityEventType, number>,
      eventsBySeverity: eventsBySeverity as Record<SecurityEventSeverity, number>,
      last24Hours: last24HoursCount,
      activeAlerts: Array.from(this.alerts.values()).filter(r => r.enabled).length
    };
  }

  /**
   * Get recent events
   */
  getRecentEvents(limit: number = 100): SecurityEvent[] {
    return this.events.slice(-limit);
  }

  /**
   * Clear all events (for testing)
   */
  clearEvents(): void {
    this.events = [];
    this.eventCounts.clear();
  }
}

// ============================================================================
// SINGLETON INSTANCE
// ============================================================================

let globalMonitor: SecurityEventsMonitor | null = null;

export function getSecurityMonitor(): SecurityEventsMonitor {
  if (!globalMonitor) {
    globalMonitor = new SecurityEventsMonitor();
    logInfo('SecurityMonitor', 'Security Events Monitor initialized');
  }

  return globalMonitor;
}

/**
 * SharedCognition — PAIOS + Brunella shared reasoning and memory layer
 * Phase 5: Adaptive Swarms & Workflow Intelligence
 *
 * Provides a unified cognition layer where Brunella and PAIOS share
 * context, memory, and reasoning results across the mesh.
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn } from '../utils/logger.js';

export interface CognitionEntry {
  id: string;
  source: 'brunella' | 'paios' | 'mesh' | 'user';
  category: 'fact' | 'observation' | 'decision' | 'prediction' | 'memory';
  content: string;
  confidence: number;     // 0–1
  context: Record<string, unknown>;
  tags: string[];
  createdAt: number;
  expiresAt?: number;
}

export interface ReasoningQuery {
  question: string;
  context?: Record<string, unknown>;
  maxResults?: number;
  minConfidence?: number;
}

export interface ReasoningResult {
  query: string;
  entries: CognitionEntry[];
  synthesis: string;
  confidence: number;
  timestamp: number;
}

export class SharedCognition extends EventEmitter {
  private entries = new Map<string, CognitionEntry>();
  private entryCounter = 0;

  /** Store a cognition entry */
  store(entry: Omit<CognitionEntry, 'id' | 'createdAt'>): CognitionEntry {
    const full: CognitionEntry = {
      ...entry,
      id: `cog-${++this.entryCounter}-${Date.now()}`,
      createdAt: Date.now(),
    };
    this.entries.set(full.id, full);
    logInfo('SharedCognition', `Stored ${full.category} from ${full.source}: ${full.content.substring(0, 80)}...`);
    this.emit('entry:stored', full);
    return full;
  }

  /** Remove an entry */
  remove(entryId: string): boolean {
    return this.entries.delete(entryId);
  }

  /** Query cognition by category, tags, and confidence */
  query(query: ReasoningQuery): ReasoningResult {
    const minConf = query.minConfidence ?? 0;
    const maxResults = query.maxResults ?? 20;
    const q = query.question.toLowerCase();

    // Filter and rank entries
    const candidates = Array.from(this.entries.values())
      .filter(e => {
        if (e.confidence < minConf) return false;
        if (e.expiresAt && e.expiresAt < Date.now()) return false;
        return true;
      });

    // Score by relevance: content match + tag match + confidence
    const scored = candidates.map(e => {
      const contentMatch = e.content.toLowerCase().includes(q) ? 0.5 : 0;
      const tagMatch = e.tags.some(t => q.includes(t.toLowerCase())) ? 0.3 : 0;
      const score = contentMatch + tagMatch + e.confidence * 0.2;
      return { entry: e, score };
    });

    scored.sort((a, b) => b.score - a.score);
    const topEntries = scored.slice(0, maxResults).map(s => s.entry);

    // Simple synthesis from top results
    const synthesis = topEntries.length > 0
      ? `Found ${topEntries.length} relevant entries. Top source: ${topEntries[0].source}, category: ${topEntries[0].category}.`
      : 'No relevant cognition entries found.';

    const avgConf = topEntries.length > 0
      ? topEntries.reduce((sum, e) => sum + e.confidence, 0) / topEntries.length
      : 0;

    return {
      query: query.question,
      entries: topEntries,
      synthesis,
      confidence: avgConf,
      timestamp: Date.now(),
    };
  }

  /** Get all entries for a source */
  getBySource(source: CognitionEntry['source']): CognitionEntry[] {
    return Array.from(this.entries.values()).filter(e => e.source === source);
  }

  /** Get all entries for a category */
  getByCategory(category: CognitionEntry['category']): CognitionEntry[] {
    return Array.from(this.entries.values()).filter(e => e.category === category);
  }

  /** Purge expired entries */
  purgeExpired(): number {
    const now = Date.now();
    let purged = 0;
    for (const [id, entry] of this.entries) {
      if (entry.expiresAt && entry.expiresAt < now) {
        this.entries.delete(id);
        purged++;
      }
    }
    if (purged > 0) logInfo('SharedCognition', `Purged ${purged} expired entries`);
    return purged;
  }

  /** Get stats */
  getStats(): { total: number; bySource: Record<string, number>; byCategory: Record<string, number>; avgConfidence: number } {
    const bySource: Record<string, number> = {};
    const byCategory: Record<string, number> = {};
    let totalConf = 0;

    for (const entry of this.entries.values()) {
      bySource[entry.source] = (bySource[entry.source] ?? 0) + 1;
      byCategory[entry.category] = (byCategory[entry.category] ?? 0) + 1;
      totalConf += entry.confidence;
    }

    return {
      total: this.entries.size,
      bySource,
      byCategory,
      avgConfidence: this.entries.size > 0 ? totalConf / this.entries.size : 0,
    };
  }
}

/**
 * Tool Composition — Chain tools together with schema compatibility
 * Track #6: MCP Tool Discovery & Composability — Phase 2+3
 *
 * Enables defining tool chains where the output of one tool feeds into the next.
 * Supports macro tools (chain → single MCP tool registration).
 */

import { logInfo, logWarn, logError } from '../utils/logger.js';
import { getDynamicToolRegistry, type ToolManifest } from './dynamicToolRegistry.js';

export interface ChainStep {
  toolId: string;
  version?: string;              // semver range for resolution
  transform?: (output: unknown) => unknown;  // optional output → input transform
  label?: string;
}

export interface ToolChain {
  id: string;
  name: string;
  description: string;
  steps: ChainStep[];
  tags: string[];
  createdBy: string;
}

export interface ChainExecutionResult {
  chainId: string;
  success: boolean;
  stepResults: Array<{
    toolId: string;
    success: boolean;
    output: unknown;
    latencyMs: number;
    error?: string;
  }>;
  finalOutput: unknown;
  totalLatencyMs: number;
}

/**
 * Validate that all tools in a chain exist in the registry
 */
export function validateChain(chain: ToolChain): { valid: boolean; errors: string[] } {
  const registry = getDynamicToolRegistry();
  const errors: string[] = [];

  for (let i = 0; i < chain.steps.length; i++) {
    const step = chain.steps[i];
    const tool = registry.getTool(step.toolId);

    if (!tool) {
      // Try version resolution if a version range is specified
      if (step.version) {
        const resolved = registry.resolveVersion(step.toolId, step.version);
        if (!resolved) {
          errors.push(`Step ${i}: tool "${step.toolId}" version "${step.version}" not found`);
        }
      } else {
        errors.push(`Step ${i}: tool "${step.toolId}" not registered`);
      }
    }
  }

  return { valid: errors.length === 0, errors };
}

/**
 * Execute a tool chain sequentially, passing output → input between steps
 */
export async function executeChain(
  chain: ToolChain,
  initialInput: unknown,
): Promise<ChainExecutionResult> {
  const registry = getDynamicToolRegistry();
  const start = Date.now();
  const stepResults: ChainExecutionResult['stepResults'] = [];
  let currentInput = initialInput;

  for (const step of chain.steps) {
    const stepStart = Date.now();
    const entry = registry.getTool(step.toolId);

    if (!entry?.handler) {
      const error = `Tool "${step.toolId}" has no handler`;
      logWarn('ToolComposition', error);
      stepResults.push({
        toolId: step.toolId,
        success: false,
        output: null,
        latencyMs: Date.now() - stepStart,
        error,
      });

      return {
        chainId: chain.id,
        success: false,
        stepResults,
        finalOutput: null,
        totalLatencyMs: Date.now() - start,
      };
    }

    try {
      const input = typeof currentInput === 'object' && currentInput !== null
        ? currentInput as Record<string, unknown>
        : { task: String(currentInput) };

      const output = await entry.handler(input);
      const latencyMs = Date.now() - stepStart;

      registry.recordCall(step.toolId, true, latencyMs);

      // Apply transform if provided
      currentInput = step.transform ? step.transform(output) : output;

      stepResults.push({
        toolId: step.toolId,
        success: true,
        output: currentInput,
        latencyMs,
      });

      logInfo('ToolComposition', `Chain "${chain.id}" step "${step.toolId}" completed (${latencyMs}ms)`);
    } catch (err: unknown) {
      const latencyMs = Date.now() - stepStart;
      const errorMsg = err instanceof Error ? err.message : String(err);

      registry.recordCall(step.toolId, false, latencyMs, errorMsg);

      stepResults.push({
        toolId: step.toolId,
        success: false,
        output: null,
        latencyMs,
        error: errorMsg,
      });

      logError('ToolComposition', `Chain "${chain.id}" failed at step "${step.toolId}": ${errorMsg}`);

      return {
        chainId: chain.id,
        success: false,
        stepResults,
        finalOutput: null,
        totalLatencyMs: Date.now() - start,
      };
    }
  }

  logInfo('ToolComposition', `Chain "${chain.id}" completed: ${chain.steps.length} steps, ${Date.now() - start}ms total`);

  return {
    chainId: chain.id,
    success: true,
    stepResults,
    finalOutput: currentInput,
    totalLatencyMs: Date.now() - start,
  };
}

/**
 * Create a tool chain definition
 */
export function createChain(config: {
  id: string;
  name: string;
  description: string;
  steps: ChainStep[];
  tags?: string[];
  createdBy: string;
}): ToolChain {
  return {
    id: config.id,
    name: config.name,
    description: config.description,
    steps: config.steps,
    tags: config.tags ?? [],
    createdBy: config.createdBy,
  };
}

/**
 * UnifiedRuntime — PAIOS + Brunella shared runtime context
 * Phase 6: Evolutionary Collective Intelligence
 *
 * Provides a single shared context layer where PAIOS and Brunella
 * can exchange state, share workflows, access common memory,
 * and coordinate cross-system actions.
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn } from '../utils/logger.js';

export interface RuntimeContext {
  id: string;
  source: 'brunella' | 'paios';
  key: string;
  value: unknown;
  version: number;
  updatedBy: string;
  updatedAt: number;
}

export interface SharedWorkflow {
  workflowId: string;
  name: string;
  owner: 'brunella' | 'paios' | 'shared';
  steps: Array<{ stepId: string; executor: 'brunella' | 'paios'; action: string }>;
  status: 'draft' | 'active' | 'paused' | 'completed';
  createdAt: number;
  lastRunAt?: number;
}

export interface RuntimeEvent {
  id: string;
  type: 'context_update' | 'workflow_start' | 'workflow_complete' | 'sync_request' | 'sync_response';
  source: 'brunella' | 'paios';
  payload: Record<string, unknown>;
  timestamp: number;
}

export class UnifiedRuntime extends EventEmitter {
  private contexts = new Map<string, RuntimeContext>();
  private workflows = new Map<string, SharedWorkflow>();
  private events: RuntimeEvent[] = [];
  private eventCounter = 0;
  private contextVersions = new Map<string, number>(); // key → version

  /** Set a context value (shared state) */
  setContext(source: 'brunella' | 'paios', key: string, value: unknown, updatedBy: string): RuntimeContext {
    const version = (this.contextVersions.get(key) ?? 0) + 1;
    this.contextVersions.set(key, version);

    const ctx: RuntimeContext = {
      id: `ctx-${key}-v${version}`,
      source,
      key,
      value,
      version,
      updatedBy,
      updatedAt: Date.now(),
    };

    this.contexts.set(key, ctx);
    this.recordEvent('context_update', source, { key, value, version });
    this.emit('context:updated', ctx);
    return ctx;
  }

  /** Get a context value */
  getContext(key: string): RuntimeContext | undefined {
    return this.contexts.get(key);
  }

  /** Get all context entries */
  getAllContexts(): RuntimeContext[] {
    return Array.from(this.contexts.values());
  }

  /** Register a shared workflow */
  registerWorkflow(workflow: Omit<SharedWorkflow, 'createdAt' | 'status'>): SharedWorkflow {
    const full: SharedWorkflow = {
      ...workflow,
      status: 'draft',
      createdAt: Date.now(),
    };
    this.workflows.set(workflow.workflowId, full);
    logInfo('UnifiedRuntime', `Workflow registered: ${workflow.name} (${workflow.workflowId})`);
    this.emit('workflow:registered', full);
    return full;
  }

  /** Start a shared workflow */
  startWorkflow(workflowId: string): boolean {
    const wf = this.workflows.get(workflowId);
    if (!wf || wf.status === 'completed') return false;

    wf.status = 'active';
    wf.lastRunAt = Date.now();
    this.recordEvent('workflow_start', wf.owner === 'shared' ? 'brunella' : wf.owner, { workflowId });
    this.emit('workflow:started', wf);
    logInfo('UnifiedRuntime', `Workflow started: ${wf.name}`);
    return true;
  }

  /** Complete a shared workflow */
  completeWorkflow(workflowId: string): boolean {
    const wf = this.workflows.get(workflowId);
    if (!wf || wf.status !== 'active') return false;

    wf.status = 'completed';
    this.recordEvent('workflow_complete', wf.owner === 'shared' ? 'brunella' : wf.owner, { workflowId });
    this.emit('workflow:completed', wf);
    return true;
  }

  /** Get a workflow */
  getWorkflow(workflowId: string): SharedWorkflow | undefined {
    return this.workflows.get(workflowId);
  }

  /** List all workflows */
  listWorkflows(status?: SharedWorkflow['status']): SharedWorkflow[] {
    const all = Array.from(this.workflows.values());
    if (!status) return all;
    return all.filter(w => w.status === status);
  }

  /** Request a sync between Brunella and PAIOS */
  requestSync(source: 'brunella' | 'paios', payload: Record<string, unknown> = {}): RuntimeEvent {
    const event = this.recordEvent('sync_request', source, payload);
    this.emit('sync:requested', event);
    logInfo('UnifiedRuntime', `Sync requested by ${source}`);
    return event;
  }

  /** Respond to a sync request */
  respondSync(source: 'brunella' | 'paios', payload: Record<string, unknown> = {}): RuntimeEvent {
    const event = this.recordEvent('sync_response', source, payload);
    this.emit('sync:responded', event);
    return event;
  }

  /** Get recent events */
  getEvents(limit = 50): RuntimeEvent[] {
    return this.events.slice(-limit);
  }

  /** Get stats */
  getStats(): { contexts: number; workflows: number; events: number; activeWorkflows: number } {
    return {
      contexts: this.contexts.size,
      workflows: this.workflows.size,
      events: this.events.length,
      activeWorkflows: Array.from(this.workflows.values()).filter(w => w.status === 'active').length,
    };
  }

  private recordEvent(type: RuntimeEvent['type'], source: RuntimeEvent['source'], payload: Record<string, unknown>): RuntimeEvent {
    const event: RuntimeEvent = {
      id: `re-${++this.eventCounter}-${Date.now()}`,
      type,
      source,
      payload,
      timestamp: Date.now(),
    };
    this.events.push(event);

    // Keep last 200 events
    if (this.events.length > 200) {
      this.events.splice(0, this.events.length - 200);
    }

    return event;
  }
}

import { getBifrostGateway, type ProviderType } from './bifrost_gateway.js';
import { getToolRegistry } from './toolRegistry.js';
import { agentManager } from '../agents/AgentManager.js';
import { logInfo, logError, logWarn } from '../utils/logger.js';
import { GraphRagEngine } from './graphRagEngine.js';
import { ReflectionEngine } from './reflectionEngine.js';
import { PredictiveIntelligence } from './predictiveIntelligence.js';

export interface ActionTriggered {
  agent: string;
  task: string;
  taskId: number;
  status: 'started' | 'completed' | 'error';
}

export interface UniversalChatMessage {
  role: 'user' | 'assistant';
  content: string;
}

export interface UniversalRequest {
  message: string;
  provider: string;
  model?: string;
  conversationHistory: UniversalChatMessage[];
  sessionId?: string;
  userId?: string;
}

export interface UniversalResponse {
  reply: string;
  actionsTriggered: ActionTriggered[];
  provider: string;
  model?: string;
  role: 'orchestrator';
  thinkingMs: number;
  sessionId: string;
  suggestions?: string[];
  missionTimeline?: MissionTimelineEntry[];
  approvalRequired?: boolean;
  approvalId?: string;
  riskLevel?: 'low' | 'high';
  runbookHint?: string;
  fallbackUsed?: boolean;
