import React, { useState, useEffect } from 'react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { Button } from '@radix-ui/react-button';
import { AlertCircle, Play, Pause, RotateCcw } from 'lucide-react';

interface LoadTestMetrics {
  totalExecuted: number;
  totalSucceeded: number;
  totalFailed: number;
  avgLatency: number;
  p95Latency: number;
  p99Latency: number;
  minLatency: number;
  maxLatency: number;
  throughput: number;
  errorRate: number;
  startTime: number;
  endTime: number;
  duration: number;
  costEstimate: number;
  memoryPeak: number;
  summary: string;
}

interface LoadTestConfig {
  pipelines: number;
  concurrency: number;
  minNodes: number;
  maxNodes: number;
  rampUp: boolean;
}

const LoadTestingDashboard: React.FC = () => {
  const [config, setConfig] = useState<LoadTestConfig>({
    pipelines: 100,
    concurrency: 10,
    minNodes: 3,
    maxNodes: 10,
    rampUp: false
  });

  const [isRunning, setIsRunning] = useState(false);
  const [metrics, setMetrics] = useState<LoadTestMetrics | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);
  const [history, setHistory] = useState<LoadTestMetrics[]>([]);

  const handleConfigChange = (key: keyof LoadTestConfig, value: any) => {
    setConfig(prev => ({ ...prev, [key]: value }));
  };

  const runLoadTest = async () => {
    try {
      setIsRunning(true);
      setError(null);
      setProgress(0);
      setMetrics(null);

      // Simulate progress updates
      const progressInterval = setInterval(() => {
        setProgress(prev => Math.min(prev + Math.random() * 30, 95));
      }, 1000);

      const queryParams = new URLSearchParams({
        pipelines: config.pipelines.toString(),
        concurrency: config.concurrency.toString(),
        minNodes: config.minNodes.toString(),
        maxNodes: config.maxNodes.toString(),
        rampUp: config.rampUp.toString()
      });

      const response = await fetch(
        `https://cean-orchestrator.your-domain.workers.dev/load-test/run?${queryParams}`,
        {
          method: 'GET',
          headers: { 'Content-Type': 'application/json' }
        }
      );

      clearInterval(progressInterval);
      setProgress(100);

      if (!response.ok) {
        throw new Error(`Load test failed: ${response.status}`);
      }

      const data = await response.json() as any;

      if (data.status === 'success') {
        setMetrics(data.metrics);
        setHistory(prev => [...prev, data.metrics]);
      } else {
        setError(data.error || 'Load test failed');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : String(err));
    } finally {
      setIsRunning(false);
      setProgress(0);
    }
  };

  const resetMetrics = () => {
    setMetrics(null);
    setHistory([]);
    setProgress(0);
    setError(null);
  };

  // Prepare data for charts
  const latencyData = metrics ? [
    { name: 'Min', value: metrics.minLatency },
    { name: 'Avg', value: metrics.avgLatency },
    { name: 'P95', value: metrics.p95Latency },
    { name: 'P99', value: metrics.p99Latency },
    { name: 'Max', value: metrics.maxLatency }
  ] : [];

  const throughputData = history.map((m, idx) => ({
    run: idx + 1,
    throughput: m.throughput.toFixed(2),
    successRate: ((m.totalSucceeded / m.totalExecuted) * 100).toFixed(2)
  }));

  return (
    <div className="space-y-6 p-6 bg-gradient-to-b from-slate-900 to-slate-800 rounded-lg">
      {/* Header */}
      <div>
        <h2 className="text-2xl font-bold text-white mb-2">🧪 Load Testing Suite</h2>
        <p className="text-slate-400">Test CEAN orchestrator with multiple concurrent pipelines</p>
      </div>

      {/* Configuration Section */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-4 bg-slate-800/50 p-4 rounded-lg border border-slate-700">
        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">Pipelines</label>
          <input
            type="number"
            value={config.pipelines}
            onChange={e => handleConfigChange('pipelines', parseInt(e.target.value))}
            disabled={isRunning}
            className="w-full px-3 py-2 bg-slate-700 text-white rounded border border-slate-600 disabled:opacity-50"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">Concurrency</label>
          <input
            type="number"
            value={config.concurrency}
            onChange={e => handleConfigChange('concurrency', parseInt(e.target.value))}
            disabled={isRunning}
            className="w-full px-3 py-2 bg-slate-700 text-white rounded border border-slate-600 disabled:opacity-50"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">Min Nodes</label>
          <input
            type="number"
            value={config.minNodes}
            onChange={e => handleConfigChange('minNodes', parseInt(e.target.value))}
            disabled={isRunning}
            className="w-full px-3 py-2 bg-slate-700 text-white rounded border border-slate-600 disabled:opacity-50"
          />
        </div>

        <div>
          <label className="block text-sm font-medium text-slate-300 mb-2">Max Nodes</label>
          <input
            type="number"
            value={config.maxNodes}
            onChange={e => handleConfigChange('maxNodes', parseInt(e.target.value))}
            disabled={isRunning}
            className="w-full px-3 py-2 bg-slate-700 text-white rounded border border-slate-600 disabled:opacity-50"
          />
        </div>

        <div className="flex items-end">
          <label className="flex items-center gap-2 text-slate-300 cursor-pointer">
            <input
              type="checkbox"
              checked={config.rampUp}
              onChange={e => handleConfigChange('rampUp', e.target.checked)}
              disabled={isRunning}
              className="w-4 h-4"
            />
            <span className="text-sm">Ramp Up</span>
          </label>
        </div>
      </div>

      {/* Control Buttons */}
      <div className="flex gap-3">
        <Button
          onClick={runLoadTest}
          disabled={isRunning}
          className="flex items-center gap-2 bg-blue-600 hover:bg-blue-700 disabled:bg-slate-600 text-white px-4 py-2 rounded"
        >
          <Play className="w-4 h-4" />
          {isRunning ? 'Running...' : 'Start Load Test'}
        </Button>

        <Button
          onClick={resetMetrics}
          disabled={isRunning}
          className="flex items-center gap-2 bg-slate-600 hover:bg-slate-700 disabled:bg-slate-600 text-white px-4 py-2 rounded"
        >
          <RotateCcw className="w-4 h-4" />
          Reset
        </Button>
      </div>

      {/* Progress Bar */}
      {isRunning && (
        <div className="space-y-2">
          <div className="w-full bg-slate-700 rounded-full h-2">
            <div
              className="bg-blue-500 h-2 rounded-full transition-all duration-300"
              style={{ width: `${progress}%` }}
            />
          </div>
          <p className="text-sm text-slate-400 text-center">{progress.toFixed(0)}% Complete</p>
        </div>
      )}

      {/* Error Alert */}
      {error && (
        <div className="flex items-start gap-3 bg-red-900/30 border border-red-700 rounded p-4">
          <AlertCircle className="w-5 h-5 text-red-500 flex-shrink-0 mt-0.5" />
          <div>
            <p className="font-semibold text-red-300">Error</p>
            <p className="text-sm text-red-400">{error}</p>
          </div>
        </div>
      )}

      {/* Metrics Results */}
      {metrics && (
        <div className="space-y-6 bg-slate-800/50 p-6 rounded-lg border border-slate-700">
          {/* Summary */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <div className="bg-slate-700 p-4 rounded">
              <p className="text-slate-400 text-sm">Total Executed</p>
              <p className="text-2xl font-bold text-green-400">{metrics.totalExecuted}</p>
            </div>
            <div className="bg-slate-700 p-4 rounded">
              <p className="text-slate-400 text-sm">Success Rate</p>
              <p className="text-2xl font-bold text-blue-400">
                {((metrics.totalSucceeded / metrics.totalExecuted) * 100).toFixed(2)}%
              </p>
            </div>
            <div className="bg-slate-700 p-4 rounded">
              <p className="text-slate-400 text-sm">Throughput</p>
              <p className="text-2xl font-bold text-amber-400">{metrics.throughput.toFixed(2)}/s</p>
            </div>
          </div>

          {/* Key Metrics Grid */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
            <div className="bg-slate-700 p-3 rounded">
              <p className="text-xs text-slate-400">Avg Latency</p>
              <p className="text-lg font-semibold text-white">{metrics.avgLatency.toFixed(0)}ms</p>
            </div>
            <div className="bg-slate-700 p-3 rounded">
              <p className="text-xs text-slate-400">P95 Latency</p>
              <p className="text-lg font-semibold text-white">{metrics.p95Latency.toFixed(0)}ms</p>
            </div>
            <div className="bg-slate-700 p-3 rounded">
              <p className="text-xs text-slate-400">P99 Latency</p>
              <p className="text-lg font-semibold text-white">{metrics.p99Latency.toFixed(0)}ms</p>
            </div>
            <div className="bg-slate-700 p-3 rounded">
              <p className="text-xs text-slate-400">Error Rate</p>
              <p className="text-lg font-semibold text-red-400">{metrics.errorRate.toFixed(2)}%</p>
            </div>
            <div className="bg-slate-700 p-3 rounded">
              <p className="text-xs text-slate-400">Duration</p>
              <p className="text-lg font-semibold text-white">{(metrics.duration / 1000).toFixed(1)}s</p>
            </div>
            <div className="bg-slate-700 p-3 rounded">
              <p className="text-xs text-slate-400">Cost (Est.)</p>
              <p className="text-lg font-semibold text-green-400">${metrics.costEstimate.toFixed(4)}</p>
            </div>
            <div className="bg-slate-700 p-3 rounded">
              <p className="text-xs text-slate-400">Memory (Peak)</p>
              <p className="text-lg font-semibold text-white">{metrics.memoryPeak}MB</p>
            </div>
            <div className="bg-slate-700 p-3 rounded">
              <p className="text-xs text-slate-400">Failed</p>
              <p className="text-lg font-semibold text-red-400">{metrics.totalFailed}</p>
            </div>
          </div>

          {/* Latency Distribution Chart */}
          {latencyData.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-3">Latency Distribution</h3>
              <ResponsiveContainer width="100%" height={300}>
                <BarChart data={latencyData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#475569" />
                  <XAxis dataKey="name" stroke="#94a3b8" />
                  <YAxis stroke="#94a3b8" />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #475569' }}
                    labelStyle={{ color: '#e2e8f0' }}
                    formatter={(value: any) => `${value.toFixed(0)}ms`}
                  />
                  <Bar dataKey="value" fill="#3b82f6" radius={[8, 8, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          )}

          {/* Throughput Trend */}
          {throughputData.length > 0 && (
            <div>
              <h3 className="text-lg font-semibold text-white mb-3">Throughput Trend</h3>
              <ResponsiveContainer width="100%" height={300}>
                <LineChart data={throughputData}>
                  <CartesianGrid strokeDasharray="3 3" stroke="#475569" />
                  <XAxis dataKey="run" stroke="#94a3b8" />
                  <YAxis yAxisId="left" stroke="#3b82f6" />
                  <YAxis yAxisId="right" orientation="right" stroke="#10b981" />
                  <Tooltip
                    contentStyle={{ backgroundColor: '#1e293b', border: '1px solid #475569' }}
                    labelStyle={{ color: '#e2e8f0' }}
                  />
                  <Legend />
                  <Line yAxisId="left" type="monotone" dataKey="throughput" stroke="#3b82f6" name="Throughput (pipelines/s)" />
                  <Line yAxisId="right" type="monotone" dataKey="successRate" stroke="#10b981" name="Success Rate (%)" />
                </LineChart>
              </ResponsiveContainer>
            </div>
          )}

          {/* Summary Text */}
          <div className="bg-slate-700 p-4 rounded border-l-4 border-blue-500">
            <p className="text-slate-300">{metrics.summary}</p>
          </div>
        </div>
      )}

      {/* No Results Yet */}
      {!metrics && !isRunning && (
        <div className="text-center py-12 text-slate-400">
          <p>👈 Configure and run load test to see metrics</p>
        </div>
      )}
    </div>
  );
};

export default LoadTestingDashboard;

import { useState } from 'react';
import {
  Plus,
  Trash2,
  Save,
  X,
  Link2,
  Settings,
  AlertCircle,
} from 'lucide-react';
import { Pipeline, DAGNode, DAGEdge, validatePipeline } from '../cean/types';
import { logInfo, logError } from '@/utils/logger';

/**
 * PipelineBuilder Component
 * Allows creating and editing DAG pipelines
 *
 * Features:
 * - Add/remove nodes
 * - Define dependencies/edges
 * - Validate DAG structure
 * - Test pipeline execution
 */
export const PipelineBuilder = ({
  initialPipeline,
  onSave,
}: {
  initialPipeline?: Pipeline;
  onSave?: (pipeline: Pipeline) => void;
}) => {
  const [pipeline, setPipeline] = useState<Pipeline>(
    initialPipeline || {
      id: `pipeline_${Date.now()}`,
      name: 'New Pipeline',
      version: '1.0.0',
      createdAt: new Date().toISOString(),
      nodes: [],
      edges: [],
      executionMode: 'mixed',
    },
  );

  const [newNodeName, setNewNodeName] = useState('');
  const [selectedNode, setSelectedNode] = useState<string | null>(null);
  const [validationErrors, setValidationErrors] = useState<string[]>([]);
  const [showNodeForm, setShowNodeForm] = useState(false);

  const validation = validatePipeline(pipeline);

  // Add new node
  const addNode = () => {
    if (!newNodeName.trim()) return;

    const newNode: DAGNode = {
      id: `node_${Date.now()}`,
      name: newNodeName,
      type: 'sequential',
      agentType: 'research',
      payload: {},
      dependencies: [],
    };

    setPipeline((prev) => ({
      ...prev,
      nodes: [...prev.nodes, newNode],
    }));

    setNewNodeName('');
    setShowNodeForm(false);
    logInfo('PipelineBuilder', `Node added: ${newNode.id}`);
  };

  // Delete node
  const deleteNode = (nodeId: string) => {
    setPipeline((prev) => ({
      ...prev,
      nodes: prev.nodes.filter((n) => n.id !== nodeId),
      edges: prev.edges.filter(
        (e) => e.from !== nodeId && e.to !== nodeId,
      ),
    }));

    if (selectedNode === nodeId) {
      setSelectedNode(null);
    }

    logInfo('PipelineBuilder', `Node deleted: ${nodeId}`);
  };

  // Add edge (dependency)
  const addEdge = (fromId: string, toId: string) => {
    if (fromId === toId) {
      setValidationErrors(['Cannot create self-loop']);
      return;
    }

    // Check if edge already exists
    if (pipeline.edges.some((e) => e.from === fromId && e.to === toId)) {
      return;
    }

    const newEdge: DAGEdge = {
      from: fromId,
      to: toId,
      condition: 'always',
    };

    const updatedPipeline = {
      ...pipeline,
      edges: [...pipeline.edges, newEdge],
    };

    // Update target node dependencies
    updatedPipeline.nodes = updatedPipeline.nodes.map((n) =>
      n.id === toId
        ? { ...n, dependencies: [...n.dependencies, fromId] }
        : n,
    );

    setPipeline(updatedPipeline);
    setValidationErrors([]);
    logInfo('PipelineBuilder', `Edge added: ${fromId} → ${toId}`);
  };

  // Remove edge
  const removeEdge = (fromId: string, toId: string) => {
    const updatedPipeline = {
      ...pipeline,
      edges: pipeline.edges.filter(
        (e) => !(e.from === fromId && e.to === toId),
      ),
    };

    // Update target node dependencies
    updatedPipeline.nodes = updatedPipeline.nodes.map((n) =>
      n.id === toId
        ? {
            ...n,
            dependencies: n.dependencies.filter((d) => d !== fromId),
          }
        : n,
    );

    setPipeline(updatedPipeline);
    setValidationErrors([]);
    logInfo('PipelineBuilder', `Edge removed: ${fromId} → ${toId}`);
  };

  // Update node property
  const updateNode = (nodeId: string, updates: Partial<DAGNode>) => {
    setPipeline((prev) => ({
      ...prev,
      nodes: prev.nodes.map((n) =>
        n.id === nodeId ? { ...n, ...updates } : n,
      ),
    }));
  };

  // Save pipeline
  const savePipeline = () => {
    if (!validation.valid) {
      setValidationErrors(validation.errors);
      return;
    }

    if (onSave) {
      onSave(pipeline);
    }

    logInfo('PipelineBuilder', `Pipeline saved: ${pipeline.id}`);
  };

  return (
    <div className="w-full space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
            Pipeline Builder
          </h2>
          <p className="text-sm text-gray-500 dark:text-gray-400 mt-1">
            Create and manage complex workflows with DAG
          </p>
        </div>

        <button
          onClick={savePipeline}
          className="flex items-center gap-2 px-4 py-2 rounded-lg bg-blue-600 text-white hover:bg-blue-700 transition"
        >
          <Save className="w-4 h-4" />
          Save Pipeline
        </button>
      </div>

      {/* Validation Errors */}
      {validationErrors.length > 0 && (
        <div className="p-4 rounded-lg bg-red-50 dark:bg-red-900/20 border border-red-200 dark:border-red-800 space-y-2">
          {validationErrors.map((err, idx) => (
            <div
              key={idx}
              className="flex items-start gap-2 text-red-700 dark:text-red-300"
            >
              <AlertCircle className="w-4 h-4 flex-shrink-0 mt-0.5" />
              <span className="text-sm">{err}</span>
            </div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
        {/* Nodes List */}
        <div className="lg:col-span-1">
          <div className="rounded-lg border border-gray-200 dark:border-gray-800 overflow-hidden">
            <div className="bg-gray-50 dark:bg-gray-800/50 px-4 py-3 border-b border-gray-200 dark:border-gray-800">
              <h3 className="font-semibold text-gray-900 dark:text-white">
                Nodes ({pipeline.nodes.length})
              </h3>
            </div>

            <div className="max-h-96 overflow-y-auto">
              {pipeline.nodes.map((node) => (
                <div
                  key={node.id}
                  onClick={() => setSelectedNode(node.id)}
                  className={`
                    p-3 border-b border-gray-100 dark:border-gray-800 cursor-pointer transition
                    ${
                      selectedNode === node.id
                        ? 'bg-blue-50 dark:bg-blue-900/20 border-l-4 border-l-blue-500'
                        : 'hover:bg-gray-50 dark:hover:bg-gray-800/30'
                    }
                  `}
                >
                  <p className="text-sm font-medium text-gray-900 dark:text-white truncate">
                    {node.name}
                  </p>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-1">
                    {node.agentType}
                  </p>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      deleteNode(node.id);
                    }}
                    className="mt-2 text-xs text-red-600 dark:text-red-400 hover:text-red-700 flex items-center gap-1"
                  >
                    <Trash2 className="w-3 h-3" />
                    Delete
                  </button>
                </div>
              ))}
            </div>

            {/* Add Node Button */}
            {!showNodeForm ? (
              <button
                onClick={() => setShowNodeForm(true)}
                className="w-full p-3 border-t border-gray-200 dark:border-gray-800 text-sm text-blue-600 dark:text-blue-400 hover:bg-gray-50 dark:hover:bg-gray-800/30 transition flex items-center justify-center gap-2"
              >
                <Plus className="w-4 h-4" />
                Add Node
              </button>
            ) : (
              <div className="p-3 border-t border-gray-200 dark:border-gray-800 space-y-2">
                <input
                  type="text"
                  placeholder="Node name..."
                  value={newNodeName}
                  onChange={(e) => setNewNodeName(e.target.value)}
                  onKeyPress={(e) => e.key === 'Enter' && addNode()}
                  className="w-full px-2 py-1 rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white text-sm"
                  autoFocus
                />
                <div className="flex gap-2">
                  <button
                    onClick={addNode}
                    className="flex-1 px-2 py-1 rounded text-xs bg-blue-600 text-white hover:bg-blue-700"
                  >
                    Add
                  </button>
                  <button
                    onClick={() => {
                      setShowNodeForm(false);
                      setNewNodeName('');
                    }}
                    className="flex-1 px-2 py-1 rounded text-xs bg-gray-200 dark:bg-gray-700 text-gray-900 dark:text-white hover:bg-gray-300 dark:hover:bg-gray-600"
                  >
                    Cancel
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Node Editor */}
        <div className="lg:col-span-3">
          {selectedNode ? (
            <div className="rounded-lg border border-gray-200 dark:border-gray-800 overflow-hidden">
              <div className="bg-gray-50 dark:bg-gray-800/50 px-4 py-3 border-b border-gray-200 dark:border-gray-800 flex items-start justify-between">
                <h3 className="font-semibold text-gray-900 dark:text-white">
                  Edit Node
                </h3>
                <button
                  onClick={() => setSelectedNode(null)}
                  className="text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>

              <div className="p-4 space-y-4">
                {(() => {
                  const node = pipeline.nodes.find(
                    (n) => n.id === selectedNode,
                  );
                  if (!node) return null;

                  return (
                    <>
                      {/* Node Name */}
                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                          Node Name
                        </label>
                        <input
                          type="text"
                          value={node.name}
                          onChange={(e) =>
                            updateNode(node.id, { name: e.target.value })
                          }
                          className="w-full px-3 py-2 rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        />
                      </div>

                      {/* Agent Type */}
                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                          Agent Type
                        </label>
                        <select
                          value={node.agentType}
                          onChange={(e) =>
                            updateNode(node.id, {
                              agentType: e.target.value as any,
                            })
                          }
                          className="w-full px-3 py-2 rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        >
                          <option value="research">Research</option>
                          <option value="grant">Grant</option>
                          <option value="harvester">Harvester</option>
                          <option value="analyzer">Analyzer</option>
                          <option value="aggregator">Aggregator</option>
                        </select>
                      </div>

                      {/* Node Type */}
                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                          Execution Type
                        </label>
                        <select
                          value={node.type}
                          onChange={(e) =>
                            updateNode(node.id, { type: e.target.value as any })
                          }
                          className="w-full px-3 py-2 rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        >
                          <option value="sequential">Sequential</option>
                          <option value="parallel">Parallel</option>
                          <option value="root">Root</option>
                          <option value="aggregator">Aggregator</option>
                        </select>
                      </div>

                      {/* Max Retries */}
                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
                          Max Retries
                        </label>
                        <input
                          type="number"
                          min="0"
                          max="5"
                          value={node.maxRetries || 0}
                          onChange={(e) =>
                            updateNode(node.id, {
                              maxRetries: parseInt(e.target.value),
                            })
                          }
                          className="w-full px-3 py-2 rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
                        />
                      </div>

                      {/* Dependencies */}
                      <div>
                        <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-2">
                          Add Dependency From
                        </label>
                        <div className="space-y-2">
                          {pipeline.nodes
                            .filter((n) => n.id !== node.id)
                            .map((otherNode) => {
                              const isDependent = node.dependencies.includes(
                                otherNode.id,
                              );
                              return (
                                <button
                                  key={otherNode.id}
                                  onClick={() => {
                                    if (isDependent) {
                                      removeEdge(otherNode.id, node.id);
                                    } else {
                                      addEdge(otherNode.id, node.id);
                                    }
                                  }}
                                  className={`
                                    w-full p-2 rounded text-left text-sm flex items-center gap-2 transition
                                    ${
                                      isDependent
                                        ? 'bg-blue-100 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300 border border-blue-300 dark:border-blue-700'
                                        : 'bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 border border-gray-300 dark:border-gray-700 hover:bg-gray-200 dark:hover:bg-gray-700'
                                    }
                                  `}
                                >
                                  {isDependent && (
                                    <Link2 className="w-4 h-4" />
                                  )}
                                  {otherNode.name}
                                </button>
                              );
                            })}
                        </div>
                      </div>
                    </>
                  );
                })()}
              </div>
            </div>
          ) : (
            <div className="rounded-lg border border-gray-200 dark:border-gray-800 p-8 text-center">
              <p className="text-gray-500 dark:text-gray-400">
                Select a node to edit
              </p>
            </div>
          )}
        </div>
      </div>

      {/* Pipeline Properties */}
      <div className="rounded-lg border border-gray-200 dark:border-gray-800 overflow-hidden">
        <div className="bg-gray-50 dark:bg-gray-800/50 px-4 py-3 border-b border-gray-200 dark:border-gray-800 flex items-center gap-2">
          <Settings className="w-5 h-5" />
          <h3 className="font-semibold text-gray-900 dark:text-white">
            Pipeline Properties
          </h3>
        </div>

        <div className="p-4 grid grid-cols-1 md:grid-cols-3 gap-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Pipeline Name
            </label>
            <input
              type="text"
              value={pipeline.name}
              onChange={(e) =>
                setPipeline((prev) => ({ ...prev, name: e.target.value }))
              }
              className="w-full px-3 py-2 rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Version
            </label>
            <input
              type="text"
              value={pipeline.version}
              onChange={(e) =>
                setPipeline((prev) => ({ ...prev, version: e.target.value }))
              }
              className="w-full px-3 py-2 rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            />
          </div>

          <div>
            <label className="block text-sm font-medium text-gray-700 dark:text-gray-300 mb-1">
              Execution Mode
            </label>
            <select
              value={pipeline.executionMode}
              onChange={(e) =>
                setPipeline((prev) => ({
                  ...prev,
                  executionMode: e.target.value as any,
                }))
              }
              className="w-full px-3 py-2 rounded border border-gray-300 dark:border-gray-600 bg-white dark:bg-gray-800 text-gray-900 dark:text-white"
            >
              <option value="sequential">Sequential</option>
              <option value="parallel">Parallel</option>
              <option value="mixed">Mixed</option>
            </select>
          </div>
        </div>
      </div>

      {/* Validation Status */}
      {validation.valid && (
        <div className="p-4 rounded-lg bg-green-50 dark:bg-green-900/20 border border-green-200 dark:border-green-800">
          <p className="text-green-700 dark:text-green-300 text-sm flex items-center gap-2">
            ✅ Pipeline is valid and ready to execute
          </p>
        </div>
      )}
    </div>
  );
};

import { useState, useEffect, useRef } from 'react';
import {
  ArrowRight,
  Circle,
  Check,
  AlertCircle,
  Play,
  Pause,
  RotateCcw,
} from 'lucide-react';
import { Pipeline, DAGNode, DAGEdge, PipelineExecution } from '../cean/types';
import { logInfo, logError } from '@/utils/logger';

/**
 * PipelineVisualizer Component
 * Renders and animates DAG execution with visual feedback
 *
 * Features:
 * - Visual DAG representation
 * - Real-time node status updates
 * - Animated execution flow
 * - Execution history timeline
 */
export const PipelineVisualizer = ({
  pipeline,
  execution,
  onStop,
}: {
  pipeline: Pipeline;
  execution: PipelineExecution | null;
  onStop?: () => void;
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [selectedNode, setSelectedNode] = useState<string | null>(null);
  const [animationFrame, setAnimationFrame] = useState(0);

  // Draw DAG on canvas
  useEffect(() => {
    if (!canvasRef.current || !pipeline.nodes.length) return;

    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Set canvas size
    canvas.width = Math.max(800, pipeline.nodes.length * 150);
    canvas.height = 400;

    // Clear canvas
    ctx.fillStyle = '#f8fafc';
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // Draw edges first (so they appear behind nodes)
    pipeline.edges.forEach((edge) => {
      drawEdge(ctx, canvas.width, canvas.height, pipeline.nodes, edge);
    });

    // Draw nodes
    pipeline.nodes.forEach((node) => {
      drawNode(
        ctx,
        canvas.width,
        canvas.height,
        node,
        execution?.nodeStates.get(node.id),
      );
    });
  }, [pipeline, execution, animationFrame]);

  const drawNode = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    node: DAGNode,
    state: any,
  ) => {
    const nodeWidth = 120;
    const nodeHeight = 60;

    // Calculate position (simple grid layout)
    const col = Math.floor((node.id.charCodeAt(0) + node.id.length) % 5);
    const row = Math.floor(
      (node.id.charCodeAt(0) + node.id.length * 2) % 4,
    );

    const x = 50 + col * 150;
    const y = 50 + row * 80;

    // Draw node box
    const isSelected = selectedNode === node.id;
    const statusColor = getStatusColor(state?.status);

    ctx.fillStyle = statusColor;
    ctx.fillRect(x, y, nodeWidth, nodeHeight);

    // Border
    ctx.strokeStyle = isSelected ? '#3b82f6' : '#999';
    ctx.lineWidth = isSelected ? 3 : 2;
    ctx.strokeRect(x, y, nodeWidth, nodeHeight);

    // Text
    ctx.fillStyle = '#000';
    ctx.font = 'bold 12px Arial';
    ctx.textAlign = 'center';
    ctx.fillText(node.name, x + nodeWidth / 2, y + 20);

    ctx.font = '10px Arial';
    ctx.fillStyle = '#666';
    ctx.fillText(`(${node.agentType})`, x + nodeWidth / 2, y + 35);

    // Status icon
    if (state?.status === 'completed') {
      ctx.fillStyle = '#22c55e';
      ctx.beginPath();
      ctx.arc(x + nodeWidth - 10, y + 10, 6, 0, Math.PI * 2);
      ctx.fill();
    } else if (state?.status === 'failed') {
      ctx.fillStyle = '#ef4444';
      ctx.fillRect(
        x + nodeWidth - 15,
        y + 5,
        10,
        10,
      );
    } else if (state?.status === 'running') {
      ctx.fillStyle = '#f59e0b';
      ctx.beginPath();
      ctx.arc(
        x + nodeWidth - 10,
        y + 10,
        6,
        0,
        Math.PI * 2,
      );
      ctx.fill();
    }
  };

  const drawEdge = (
    ctx: CanvasRenderingContext2D,
    width: number,
    height: number,
    nodes: DAGNode[],
    edge: DAGEdge,
  ) => {
    const fromNode = nodes.find((n) => n.id === edge.from);
    const toNode = nodes.find((n) => n.id === edge.to);

    if (!fromNode || !toNode) return;

    const nodeWidth = 120;
    const nodeHeight = 60;

    const col1 = Math.floor((edge.from.charCodeAt(0) + edge.from.length) % 5);
    const row1 = Math.floor(
      (edge.from.charCodeAt(0) + edge.from.length * 2) % 4,
    );
    const x1 = 50 + col1 * 150 + nodeWidth / 2;
    const y1 = 50 + row1 * 80 + nodeHeight;

    const col2 = Math.floor((edge.to.charCodeAt(0) + edge.to.length) % 5);
    const row2 = Math.floor(
      (edge.to.charCodeAt(0) + edge.to.length * 2) % 4,
    );
    const x2 = 50 + col2 * 150 + nodeWidth / 2;
    const y2 = 50 + row2 * 80;

    // Draw line with arrow
    ctx.strokeStyle = '#666';
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();

    // Arrow head
    const angle = Math.atan2(y2 - y1, x2 - x1);
    ctx.fillStyle = '#666';
    ctx.beginPath();
    ctx.moveTo(x2, y2);
    ctx.lineTo(x2 - 10 * Math.cos(angle - Math.PI / 6), y2 - 10 * Math.sin(angle - Math.PI / 6));
    ctx.lineTo(x2 - 10 * Math.cos(angle + Math.PI / 6), y2 - 10 * Math.sin(angle + Math.PI / 6));
    ctx.closePath();
    ctx.fill();
  };

  const getStatusColor = (status?: string) => {
    switch (status) {
      case 'completed':
        return '#d1fae5';
      case 'running':
        return '#fef3c7';
      case 'failed':
        return '#fee2e2';
      case 'skipped':
        return '#e5e7eb';
      default:
        return '#f3f4f6';
    }
  };

  const getStatusIcon = (status?: string) => {
    switch (status) {
      case 'completed':
        return <Check className="w-4 h-4 text-green-600" />;
      case 'failed':
        return <AlertCircle className="w-4 h-4 text-red-600" />;
      case 'running':
        return (
          <div className="w-4 h-4 border-2 border-amber-500 border-t-transparent rounded-full animate-spin" />
        );
      default:
        return <Circle className="w-4 h-4 text-gray-400" />;
    }
  };

  return (
    <div className="w-full space-y-4">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h3 className="text-lg font-semibold text-gray-900 dark:text-white">
            {pipeline.name}
          </h3>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            {pipeline.nodes.length} nodes, {pipeline.edges.length} edges
          </p>
        </div>

        <div className="flex items-center gap-2">
          {execution && (
            <>
              <span
                className={`px-2 py-1 rounded text-xs font-medium ${
                  execution.status === 'completed'
                    ? 'bg-green-100 text-green-700'
                    : execution.status === 'failed'
                      ? 'bg-red-100 text-red-700'
                      : 'bg-amber-100 text-amber-700'
                }`}
              >
                {execution.status}
              </span>

              {execution.status === 'running' && onStop && (
                <button
                  onClick={onStop}
                  className="p-2 rounded-lg hover:bg-gray-100 dark:hover:bg-gray-800"
                >
                  <Pause className="w-4 h-4" />
                </button>
              )}
            </>
          )}
        </div>
      </div>

      {/* Canvas */}
      <div className="rounded-lg border border-gray-200 dark:border-gray-800 overflow-x-auto bg-white dark:bg-gray-900">
        <canvas
          ref={canvasRef}
          onClick={(e) => {
            // TODO: Add click handling for node selection
          }}
          className="block w-full"
        />
      </div>

      {/* Node Details */}
      {selectedNode && (
        <div className="p-4 rounded-lg bg-blue-50 dark:bg-blue-900/20 border border-blue-200 dark:border-blue-800">
          <div className="flex items-start justify-between">
            <div>
              <h4 className="text-sm font-semibold text-gray-900 dark:text-white">
                Node: {selectedNode}
              </h4>
              {execution && (
                <div className="mt-2 space-y-1 text-sm text-gray-700 dark:text-gray-300">
                  <p>
                    Status:{' '}
                    <span
                      className={`font-medium ${
                        execution.nodeStates.get(selectedNode)?.status ===
                        'completed'
                          ? 'text-green-600'
                          : 'text-gray-600'
                      }`}
                    >
                      {execution.nodeStates.get(selectedNode)?.status ||
                        'N/A'}
                    </span>
                  </p>
                  {execution.nodeStates.get(selectedNode)?.taskId && (
                    <p>
                      Task ID:{' '}
                      <code className="text-xs">
                        {execution.nodeStates.get(selectedNode)?.taskId}
                      </code>
                    </p>
                  )}
                </div>
              )}
            </div>
            <button
              onClick={() => setSelectedNode(null)}
              className="text-gray-500 hover:text-gray-700"
            >
              ×
            </button>
          </div>
        </div>
      )}

      {/* Legend */}
      <div className="flex items-center gap-4 text-xs text-gray-600 dark:text-gray-400">
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded bg-gray-200"></div>
          <span>Pending</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded bg-amber-200"></div>
          <span>Running</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded bg-green-200"></div>
          <span>Completed</span>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded bg-red-200"></div>
          <span>Failed</span>
        </div>
      </div>
    </div>
  );
};

