    executionCount?: number;
}

export function AgentManagementPanel() {
    const [agents, setAgents] = useState<AgentStatus[]>([])
    const [selectedAgent, setSelectedAgent] = useState<string | null>(null)
    const [logs, setLogs] = useState<string[]>([])
    const [taskInput, setTaskInput] = useState('')
    const [executing, setExecuting] = useState(false)
    const [loading, setLoading] = useState(true)
    const eventSourceRef = useRef<EventSource | null>(null)
    const logEndRef = useRef<HTMLDivElement>(null)

    const fetchAgents = async () => {
        try {
            const data = await getAgentStatuses()
            setAgents(data as AgentStatus[])
        } catch (err: any) {
            toast.error(`Nem sikerült betölteni az ügynököket: ${err.message}`)
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        fetchAgents()
        const interval = setInterval(fetchAgents, 5000)
        return () => clearInterval(interval)
    }, [])

    useEffect(() => {
        if (logEndRef.current) {
            logEndRef.current.scrollIntoView({ behavior: 'smooth' })
        }
    }, [logs])

    const subscribeToLogs = (agentName: string) => {
        if (eventSourceRef.current) {
            eventSourceRef.current.close()
        }

        setLogs([`--- Feliratkozva a(z) ${agentName} naplójára ---`])
        const es = new EventSource(`${API_BASE}/api/agents/${encodeURIComponent(agentName)}/logs`)

        es.onmessage = (event) => {
            try {
                const data = JSON.parse(event.data)
                const timestamp = new Date().toLocaleTimeString()
                const message = data.message || formatAgentResponse(data, agentName)
                setLogs((prev: string[]) => [...prev, `[${timestamp}] ${message}`])
            } catch (e) {
                setLogs((prev: string[]) => [...prev, event.data])
            }
        }

        es.onerror = () => {
            setLogs((prev: string[]) => [...prev, 'CSATLAKOZÁSI HIBA A NAPLÓHOZ'])
            es.close()
        }

        eventSourceRef.current = es
    }

    const handleExecute = async () => {
        if (!selectedAgent || !taskInput.trim()) return
        setExecuting(true)
        setLogs((prev: string[]) => [...prev, `\n>>> Végrehajtás: ${taskInput}`])
        try {
            const result = await executeAgent(selectedAgent, taskInput)
            toast.success('Feladat sikeresen beküldve')
            const formattedResult = formatAgentResponse(result, selectedAgent)
            setLogs((prev: string[]) => [...prev, `<<< Eredmény:\n${formattedResult}`])
            setTaskInput('')
        } catch (err: any) {
            toast.error(`Végrehajtási hiba: ${err.message}`)
            setLogs((prev: string[]) => [...prev, `!!! HIBA: ${err.message}`])
        } finally {
            setExecuting(false)
        }
    }

    const clearLogs = () => setLogs([])

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-space font-bold text-foreground">Agent Management</h2>
                    <p className="text-zinc-500 mt-1">AI ügynökök felügyelete és közvetlen vezérlése.</p>
                </div>
                <Button onClick={fetchAgents} variant="outline" size="sm" className="gap-2">
                    <Clock className="w-4 h-4" /> Frissítés
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                {/* Registry & Status List */}
                <div className="lg:col-span-1 space-y-4">
                    <Card className="glass-card">
                        <CardHeader>
                            <CardTitle className="flex items-center gap-2 text-sm uppercase tracking-wider text-zinc-500">
                                <Brain className="w-4 h-4 text-primary" />
                                Regisztrált Ügynökök
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="p-0">
                            <ScrollArea className="h-[500px]">
                                <div className="divide-y divide-border/50">
                                    {loading ? (
                                        <div className="p-4 text-center text-zinc-500">Betöltés...</div>
                                    ) : agents.map((agent) => (
                                        <div
                                            key={agent.name}
                                            onClick={() => {
                                                setSelectedAgent(agent.name)
                                                subscribeToLogs(agent.name)
                                            }}
                                            className={`p-4 cursor-pointer transition-colors hover:bg-muted/50 ${selectedAgent === agent.name ? 'bg-muted border-l-4 border-primary' : ''}`}
                                        >
                                            <div className="flex items-center justify-between mb-1">
                                                <span className="font-bold text-sm">{agent.name}</span>
                                                <Badge variant={agent.status === 'working' ? 'default' : 'secondary'} className="text-[10px]">
                                                    {agent.status}
                                                </Badge>
                                            </div>
                                            <p className="text-xs text-zinc-500 line-clamp-1">{agent.description}</p>
                                        </div>
                                    ))}
                                </div>
                            </ScrollArea>
                        </CardContent>
                    </Card>
                </div>

                {/* Control & Logs Panel */}
                <div className="lg:col-span-2 space-y-6">
                    {selectedAgent ? (
                        <>
                            <Card className="glass-card overflow-hidden">
                                <CardHeader className="bg-muted/30 border-b border-border/50">
                                    <div className="flex items-center justify-between">
                                        <div>
                                            <CardTitle className="text-xl font-bold">{selectedAgent}</CardTitle>
                                            <CardDescription>Közvetlen feladat végrehajtás</CardDescription>
                                        </div>
                                        <Badge variant="outline" className="gap-1">
                                            <Activity className="w-3 h-3 text-cyan-400" /> Aktív
                                        </Badge>
                                    </div>
                                </CardHeader>
                                <CardContent className="p-6 space-y-4">
                                    <div className="flex gap-2">
                                        <input
                                            type="text"
                                            placeholder="Írd be a feladatot (pl. 'Írj egy hello world scriptet')"
                                            className="flex-1 bg-background border border-border/50 rounded-md px-4 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-primary"
                                            value={taskInput}
                                            onChange={(e) => setTaskInput(e.target.value)}
                                            onKeyDown={(e) => e.key === 'Enter' && handleExecute()}
                                            disabled={executing}
                                        />
                                        <Button onClick={handleExecute} disabled={executing || !taskInput.trim()} className="gap-2">
                                            <Play className="w-4 h-4 fill-current" />
                                            {executing ? 'Futtatás...' : 'Küldés'}
                                        </Button>
                                    </div>
                                    {executing && <Progress value={100} className="h-1 animate-pulse" />}
                                </CardContent>
                            </Card>

                            <Card className="glass-card flex-1 flex flex-col min-h-[400px]">
                                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-3 border-b border-border/50">
                                    <CardTitle className="text-sm font-medium flex items-center gap-2 text-zinc-500 uppercase tracking-wider">
                                        <Terminal className="w-4 h-4" />
                                        Agent Logs: {selectedAgent}
                                    </CardTitle>
                                    <Button variant="ghost" size="icon" onClick={clearLogs} className="h-8 w-8 text-zinc-500 hover:text-destructive" aria-label="Clear logs" title="Clear logs">
                                        <Trash2 className="w-4 h-4" />
                                    </Button>
                                </CardHeader>
                                <CardContent className="p-0 flex-1 relative">
                                    <ScrollArea className="h-[350px] w-full bg-white/[0.03] p-4 font-mono text-[12px]">
                                        <div className="space-y-1">
                                            {logs.map((log, i) => (
                                                <div key={i} className={`whitespace-pre-wrap ${log.includes('HIBA') || log.includes('error') ? 'text-red-400' :
                                                    log.includes('---') ? 'text-cyan-400' :
                                                        log.includes('<<<') ? 'text-green-400' :
                                                            'text-slate-300'
                                                    }`}>
                                                    {log}
                                                </div>
                                            ))}
                                            <div ref={logEndRef} />
                                        </div>
                                    </ScrollArea>
                                </CardContent>
                            </Card>
                        </>
                    ) : (
                        <Card className="glass-card h-full flex flex-col items-center justify-center p-12 text-center text-zinc-500">
                            <Brain className="w-16 h-16 mb-4 opacity-20" />
                            <h3 className="text-lg font-medium">Nincs kiválasztott ügynök</h3>
                            <p className="max-w-xs mt-2">Válassz egy ügynököt a bal oldali listából a vezérléshez és a naplók megtekintéséhez.</p>
                        </Card>
                    )}
                </div>
            </div>
        </div>
    )
}

import { useMemo, useState } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Switch } from '@/components/ui/switch';
import agentsRegistry from '../../../agents/registry.json';
import { FunnelSimple, MagnifyingGlass, CheckCircle, XCircle } from '@phosphor-icons/react';

type AgentItem = (typeof agentsRegistry)['agents'][number];

export function AgentRegistryCard() {
  const [query, setQuery] = useState('');
  const [category, setCategory] = useState<string>('all');
  const [showOnlyActive, setShowOnlyActive] = useState(false);
  const [disabled, setDisabled] = useState<Record<string, boolean>>({});

  const categories = useMemo(() => {
    const set = new Set<string>();
    agentsRegistry.agents.forEach(a => a.category && set.add(a.category));
    return Array.from(set);
  }, []);

  const filtered = useMemo(() => {
    return agentsRegistry.agents.filter(agent => {
      if (showOnlyActive && (disabled[agent.name] || agent.status === 'planned')) return false;
      if (category !== 'all' && agent.category !== category) return false;
      if (!query) return true;
      const hay = `${agent.name} ${agent.title ?? ''} ${agent.description ?? ''} ${agent.tags?.join(' ')}`.toLowerCase();
      return hay.includes(query.toLowerCase());
    });
  }, [category, query, showOnlyActive, disabled]);

  return (
    <Card className="w-full">
      <CardHeader>
        <div className="flex items-center gap-2">
          <FunnelSimple size={22} className="text-primary" />
          <div>
            <CardTitle>Agypiac – Ügynökök</CardTitle>
            <CardDescription>Ügynök-regiszter: keresés, szűrés, státusz jelzés</CardDescription>
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="flex flex-col md:flex-row gap-3">
          <div className="flex-1 relative">
            <MagnifyingGlass size={16} className="absolute left-2 top-1/2 -translate-y-1/2 text-zinc-500" />
            <Input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Keresés név, szerepkör vagy tag alapján..."
              className="pl-7"
            />
          </div>
          <div className="flex items-center gap-2">
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              className="border rounded-md px-2 py-1 text-sm bg-background"
            >
              <option value="all">Minden kategória</option>
              {categories.map(cat => (
                <option key={cat} value={cat}>{cat}</option>
              ))}
            </select>
            <div className="flex items-center gap-2 text-sm">
              <Switch
                checked={showOnlyActive}
                onCheckedChange={(v) => setShowOnlyActive(v)}
                id="only-active"
              />
              <label htmlFor="only-active" className="cursor-pointer">Csak aktív</label>
            </div>
          </div>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
          {filtered.map(agent => {
            const isDisabled = disabled[agent.name] ?? (agent.status === 'planned');
            return (
              <div
                key={agent.name}
                className={`p-4 border rounded-lg bg-card flex flex-col gap-2 ${isDisabled ? 'opacity-70' : ''}`}
              >
                <div className="flex justify-between items-start gap-2">
                  <div>
                    <p className="font-semibold">{agent.title ?? agent.name}</p>
                    <p className="text-xs text-zinc-500">{agent.description ?? ''}</p>
                  </div>
                  <Badge variant="outline" className={isDisabled ? 'text-zinc-500 border-muted-foreground/30' : 'text-green-500 border-green-500/30'}>
                    {isDisabled ? 'Inaktív' : 'Aktív'}
                  </Badge>
                </div>
                <div className="flex gap-2 flex-wrap text-xs">
                  {agent.category && <Badge variant="secondary">{agent.category}</Badge>}
                  {agent.tags?.map(tag => (
                    <Badge key={tag} variant="outline">{tag}</Badge>
                  ))}
                </div>
                <div className="flex gap-2 mt-2">
                  <Button
                    size="sm"
                    variant={isDisabled ? 'secondary' : 'outline'}
                    className="flex-1 gap-1"
                    onClick={() => setDisabled(prev => ({ ...prev, [agent.name]: !isDisabled }))}
                  >
                    {isDisabled ? <CheckCircle size={14} /> : <XCircle size={14} />}
                    {isDisabled ? 'Engedélyezés' : 'Tiltás (lokális)'}
                  </Button>
                </div>
              </div>
            );
          })}
          {filtered.length === 0 && (
            <div className="col-span-full text-zinc-500 text-sm border border-dashed rounded-md p-6">
              Nincs találat a megadott szűrőkkel.
            </div>
          )}
        </div>
      </CardContent>
    </Card>
  );
}

import { useSystemSignal } from "@/hooks/useSystemSignal";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { cn } from "@/lib/utils";
import { Brain, Activity, AlertCircle, CheckCircle2, Clock } from "lucide-react";
import { ScrollArea } from "@/components/ui/scroll-area";

export function AgentStatusMonitor() {
  const { agents } = useSystemSignal();

  // agents is a Map<string, AgentStatusEntry> — Array.from is required, Object.values(Map) returns []
  const agentsList = agents ? Array.from(agents.values()) : [];

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'working': return <Activity size={14} className="text-emerald-500 animate-pulse" />;
      case 'error': return <AlertCircle size={14} className="text-red-500" />;
      default: return <CheckCircle2 size={14} className="text-zinc-500" />;
    }
  };

  return (
    <Card className="glass-card border-white/10 h-full flex flex-col">
      <CardHeader className="pb-2 border-b border-white/[0.04] shrink-0">
        <CardTitle className="text-sm font-space font-bold tracking-tight uppercase text-zinc-500 flex items-center gap-2">
          <Brain size={16} className="text-primary" />
          Agent Status Monitor
        </CardTitle>
      </CardHeader>
      <CardContent className="p-0 flex-1 min-h-0">
        <ScrollArea className="h-full">
          <div className="divide-y divide-white/5">
            {agentsList.length === 0 ? (
              <div className="p-8 text-center text-xs text-zinc-500 font-mono italic">
                NO_AGENTS_DETECTED
              </div>
            ) : agentsList.map((agent) => (
              <div key={agent.name} className="p-3 hover:bg-white/[0.03] transition-colors group">
                <div className="flex items-center justify-between mb-1">
                  <div className="flex items-center gap-2">
                    <span className={cn(
                      "w-1.5 h-1.5 rounded-full",
                      agent.status === 'working' ? "bg-emerald-500 shadow-[0_0_5px_rgba(16,185,129,0.5)]" : 
                      agent.status === 'error' ? "bg-red-500" : "bg-zinc-600"
                    )} />
                    <span className="font-bold text-xs font-mono group-hover:text-primary transition-colors uppercase tracking-tight">
                      {agent.name}
                    </span>
                  </div>
                  <Badge variant={agent.status === 'working' ? 'default' : 'secondary'} className="text-[9px] h-4 px-1 font-mono">
                    {agent.status.toUpperCase()}
                  </Badge>
                </div>
                {agent.taskDescription && (
                  <div className="flex items-start gap-1.5 mt-1 px-3 py-1 bg-white/[0.04] rounded border border-white/[0.04]">
                    <Clock size={10} className="text-zinc-500 mt-0.5 shrink-0" />
                    <p className="text-[10px] text-zinc-400 font-mono line-clamp-1 italic leading-tight">
                      {agent.taskDescription}
                    </p>
                  </div>
                )}
              </div>
            ))}
          </div>
        </ScrollArea>
      </CardContent>
      <div className="p-2 bg-white/[0.02] border-t border-white/[0.04] shrink-0">
        <div className="flex justify-between items-center px-2">
          <span className="text-[9px] font-mono text-zinc-500 uppercase tracking-widest">Active: {agentsList.filter(a => a.status === 'working').length}</span>
          <span className="text-[9px] font-mono text-zinc-500 uppercase tracking-widest">Total: {agentsList.length}</span>
        </div>
      </div>
    </Card>
  );
}

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { Alert, AlertDescription } from '@/components/ui/alert';
import { Skeleton } from '@/components/ui/skeleton';
import { Database, PaperPlaneRight, Sparkle, Info } from '@phosphor-icons/react';
import * as api from '@/lib/apiService';
import { toast } from 'sonner';

interface AnythingLLMIntegrationProps {
    className?: string;
}

export function AnythingLLMIntegration({ className }: AnythingLLMIntegrationProps) {
    const [workspaces, setWorkspaces] = useState<api.Workspace[]>([]);
    const [selectedWorkspace, setSelectedWorkspace] = useState<string>('');
    const [loading, setLoading] = useState(true);
    const [message, setMessage] = useState('');
    const [response, setResponse] = useState('');
    const [isProcessing, setIsProcessing] = useState(false);

    useEffect(() => {
        loadWorkspaces();
    }, []);

    const loadWorkspaces = async () => {
        setLoading(true);
        try {
            const data = await api.getAnythingLLMWorkspaces();
            setWorkspaces(data);
            
            if (data.length > 0) {
                // Select default workspace from env or first one
                const defaultWorkspace = process.env.ANYTHINGLLM_WORKSPACE || data[0].slug;
                setSelectedWorkspace(defaultWorkspace);
            } else {
                toast.warning('Nincs elérhető workspace', {
                    description: 'Hozz létre egy workspace-t az AnythingLLM-ben'
                });
            }
        } catch (error: any) {
            toast.error('AnythingLLM betöltési hiba', {
                description: error.message
            });
        } finally {
            setLoading(false);
        }
    };

    const handleSendMessage = async () => {
        if (!message.trim() || !selectedWorkspace) {
            toast.error('Hiányzó adat', {
                description: 'Válassz workspace-t és írj üzenetet'
            });
            return;
        }

        setIsProcessing(true);
        setResponse('');

        try {
            const result = await api.chatWithAnythingLLM(selectedWorkspace, message);
            setResponse(result);
            toast.success('RAG válasz megérkezett');
        } catch (error: any) {
            toast.error('AnythingLLM chat hiba', {
                description: error.message
            });
            setResponse(`Hiba: ${error.message}`);
        } finally {
            setIsProcessing(false);
        }
    };

    const handleKeyDown = (e: React.KeyboardEvent) => {
        if (e.key === 'Enter' && e.ctrlKey) {
            handleSendMessage();
        }
    };

    if (loading) {
        return (
            <Card className={className}>
                <CardHeader>
                    <CardTitle className="flex items-center gap-2">
                        <Database size={24} />
                        AnythingLLM RAG
                    </CardTitle>
                    <CardDescription>Betöltés...</CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <Skeleton className="h-10 w-full" />
                    <Skeleton className="h-32 w-full" />
                </CardContent>
            </Card>
        );
    }

    return (
        <Card className={className}>
            <CardHeader>
                <CardTitle className="flex items-center gap-2">
                    <Database size={24} />
                    AnythingLLM RAG
                </CardTitle>
                <CardDescription>
                    Kérdezz a tudásbázisodból dokumentumok alapján
                </CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
                {workspaces.length === 0 ? (
                    <Alert>
                        <Info size={20} />
                        <AlertDescription>
                            Nincs elérhető workspace. Ellenőrizd az AnythingLLM kapcsolatot és az API kulcsot.
                        </AlertDescription>
                    </Alert>
                ) : (
                    <>
                        {/* Workspace Selector */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Workspace</label>
                            <Select
                                value={selectedWorkspace}
                                onValueChange={setSelectedWorkspace}
                            >
                                <SelectTrigger>
                                    <SelectValue placeholder="Válassz workspace-t" />
                                </SelectTrigger>
                                <SelectContent>
                                    {workspaces.map((ws) => (
                                        <SelectItem key={ws.id} value={ws.slug}>
                                            <div className="flex items-center gap-2">
                                                <Database size={16} />
                                                {ws.name}
                                            </div>
                                        </SelectItem>
                                    ))}
                                </SelectContent>
                            </Select>
                            <p className="text-xs text-zinc-500">
                                {workspaces.length} workspace elérhető
                            </p>
                        </div>

                        {/* Message Input */}
                        <div className="space-y-2">
                            <label className="text-sm font-medium">Kérdés</label>
                            <Textarea
                                value={message}
                                onChange={(e) => setMessage(e.target.value)}
                                onKeyDown={handleKeyDown}
                                placeholder="Pl.: Milyen dokumentumok vannak a projektről?"
                                className="min-h-[100px]"
                                disabled={isProcessing}
                            />
                            <p className="text-xs text-zinc-500">
                                Ctrl+Enter a küldéshez
                            </p>
                        </div>

                        {/* Send Button */}
                        <Button
                            onClick={handleSendMessage}
                            disabled={isProcessing || !message.trim()}
                            className="w-full"
                        >
                            <Sparkle size={18} className={isProcessing ? 'animate-pulse' : ''} />
                            <span className="ml-2">
                                {isProcessing ? 'Feldolgozás...' : 'RAG Lekérdezés'}
                            </span>
                            {!isProcessing && <PaperPlaneRight size={18} className="ml-2" />}
                        </Button>

                        {/* Response */}
                        {response && (
                            <div className="space-y-2">
                                <div className="flex items-center justify-between">
                                    <label className="text-sm font-medium">Válasz</label>
                                    <Badge variant="outline">RAG</Badge>
                                </div>
                                <div className="p-4 rounded-lg border bg-muted/50">
                                    <p className="text-sm whitespace-pre-wrap">{response}</p>
                                </div>
                            </div>
                        )}
                    </>
                )}
            </CardContent>
        </Card>
    );
}

/**
 * Gold Protocol G7.6: Audit Panel
 *
 * Permission audit log böngészése
 */

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { ShieldCheck, ShieldSlash, Eye } from '@phosphor-icons/react';

interface AuditEntry {
  id?: number;
  timestamp: string;
  agentName: string;
  action: string;
  resource: string;
  result: 'ALLOWED' | 'DENIED';
  reason?: string;
}

interface AuditStats {
  totalEntries: number;
  allowedCount: number;
  deniedCount: number;
  byAgent: Record<string, { allowed: number; denied: number }>;
}

export function AuditPanel() {
  const [entries, setEntries] = useState<AuditEntry[]>([]);
  const [stats, setStats] = useState<AuditStats | null>(null);
  const [showOnlyDenied, setShowOnlyDenied] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAudit();
    fetchStats();
    const interval = setInterval(() => {
      fetchAudit();
      fetchStats();
    }, 5000);
    return () => clearInterval(interval);
  }, [showOnlyDenied]);

  const fetchAudit = async () => {
    try {
      const endpoint = showOnlyDenied ? '/api/audit/denied' : '/api/audit/log?limit=50';
      const res = await fetch(endpoint);
      const data = await res.json();
      setEntries(data.entries || []);
      setLoading(false);
    } catch (e) {
      console.error('Failed to fetch audit:', e);
      setLoading(false);
    }
  };

  const fetchStats = async () => {
    try {
      const res = await fetch('/api/audit/stats');
      const data = await res.json();
      setStats(data);
    } catch (e) {
      console.error('Failed to fetch audit stats:', e);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Audit Log</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-gray-500">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-4 gap-4">
      {/* Stats Cards */}
      {stats && (
        <>
          <Card>
            <CardContent className="p-4">
              <div className="text-xs text-gray-500">Total Entries</div>
              <div className="text-2xl font-bold">{stats.totalEntries}</div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4">
              <div className="text-xs text-gray-500 flex items-center gap-1">
                <ShieldCheck className="w-3 h-3" /> Allowed
              </div>
              <div className="text-2xl font-bold text-green-600">{stats.allowedCount}</div>
            </CardContent>
          </Card>
          <Card>
            <CardContent className="p-4">
              <div className="text-xs text-gray-500 flex items-center gap-1">
                <ShieldSlash className="w-3 h-3" /> Denied
              </div>
              <div className="text-2xl font-bold text-red-600">{stats.deniedCount}</div>
            </CardContent>
          </Card>
        </>
      )}

      {/* Audit Log */}
      <Card className="lg:col-span-4">
        <CardHeader>
          <div className="flex items-center justify-between">
            <CardTitle className="flex items-center gap-2">
              <Eye className="w-5 h-5" />
              Audit Log ({entries.length} recent)
            </CardTitle>
            <Button
              size="sm"
              variant={showOnlyDenied ? 'default' : 'outline'}
              onClick={() => setShowOnlyDenied(!showOnlyDenied)}
            >
              {showOnlyDenied ? 'Show All' : 'Show Denied Only'}
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 max-h-[500px] overflow-y-auto">
            {entries.map((entry, idx) => (
              <div
                key={idx}
                className={`p-3 border rounded-lg ${
                  entry.result === 'DENIED' ? 'border-red-300 bg-red-50 dark:bg-red-900/10' : 'border-gray-200'
                }`}
              >
                <div className="flex items-center justify-between mb-1">
                  <div className="flex items-center gap-2">
                    <Badge className={entry.result === 'ALLOWED' ? 'bg-green-500' : 'bg-red-500'}>
                      {entry.result}
                    </Badge>
                    <span className="font-semibold text-sm">{entry.agentName}</span>
                    <span className="text-xs text-gray-500">→ {entry.action}</span>
                  </div>
                  <span className="text-xs text-gray-500">{new Date(entry.timestamp).toLocaleString()}</span>
                </div>
                <div className="text-xs text-gray-600">
                  <span className="font-mono">{entry.resource.slice(0, 80)}</span>
                  {entry.reason && (
                    <div className="mt-1 text-red-600">Reason: {entry.reason}</div>
                  )}
                </div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { 
    Code2, 
    MonitorPlay, 
    FileJson, 
    Layout, 
    Smartphone, 
    Globe, 
    Cpu, 
    Play, 
    Save, 
    History,
    ChevronRight,
    Loader2,
    CheckCircle2,
    Eye,
    Plus,
    Box
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Input } from '../ui/input';
import { Textarea } from '../ui/textarea';
import { ScrollArea } from '../ui/scroll-area';
import { Badge } from '../ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';

export function BrunellaStudio() {
    const [isCreating, setIsCreating] = useState(false);
    const [projectDesc, setProjectDescription] = useState('');
    const [projectName, setProjectName] = useState('');
    const [techStack, setTechStack] = useState('React + Tailwind');
    const [projects, setProjects] = useState<any[]>([]);
    const [selectedProjectId, setSelectedProjectId] = useState<string | null>(null);
    const [studioLogs, setStudioLogs] = useState<Record<string, string[]>>({});
    const [previewMode, setPreviewMode] = useState<'desktop' | 'mobile'>('desktop');
    const [iterationPrompt, setIterationPrompt] = useState('');
    const [isIterating, setIsIteration] = useState(false);
    const { socket } = useSocket();

    useEffect(() => {
        // Fetch existing projects
        fetch('/api/v1/studio/projects')
            .then(res => res.json())
            .then(data => {
                if (data.success) setProjects(data.projects);
            });
    }, []);

    useEffect(() => {
        if (!socket) return;

        const handleStudioLog = (data: { projectId: string, line: string, type: string }) => {
            setStudioLogs(prev => ({
                ...prev,
                [data.projectId]: [...(prev[data.projectId] || []), data.line].slice(-200)
            }));
        };

        const handleStudioReady = (data: { projectId: string, url: string }) => {
            setProjects(prev => prev.map(p => 
                p.id === data.projectId ? { ...p, status: 'coding', preview_url: data.url } : p
            ));
            toast.success(`Alkalmazás Előnézet Kész: ${data.projectId}`);
        };

        socket.on('studio:log', handleStudioLog);
        socket.on('studio:ready', handleStudioReady);

        return () => {
            socket.off('studio:log', handleStudioLog);
            socket.off('studio:ready', handleStudioReady);
        };
    }, [socket]);

    const handleCreateProject = async () => {
        if (!projectDesc.trim() || !projectName.trim()) {
            toast.error("Kérlek add meg a nevet és a leírást!");
            return;
        }

        setIsCreating(true);
        toast.info("Projekt inicializálása... Ágensek felkészítése.");

        try {
            const res = await fetch('/api/v1/studio/projects', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ 
                    name: projectName, 
                    description: projectDesc, 
                    tech_stack: techStack 
                })
            });
            const data = await res.json();
            if (data.success) {
                toast.success("Projekt létrehozva! A kódolás elindul a háttérben.");
                setProjects(prev => [data.project, ...prev]);
                setSelectedProjectId(data.project.id);
                setProjectDescription('');
                setProjectName('');
            }
        } catch (err) {
            toast.error("Hiba történt a projekt indításakor.");
        } finally {
            setIsCreating(false);
        }
    };

    const handleIterate = async () => {
        if (!iterationPrompt.trim() || !selectedProjectId) return;

        setIsIteration(true);
        toast.info("Változtatások alkalmazása...");

        try {
            const res = await fetch(`/api/v1/studio/projects/${selectedProjectId}/iterate`, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ instruction: iterationPrompt })
            });
            if (res.ok) {
                toast.success("Ágensek dolgoznak a módosításon.");
                setIterationPrompt('');
            }
        } catch (err) {
            toast.error("Hiba az iteráció során.");
        } finally {
            setIsIteration(false);
        }
    };

    const activeProject = projects.find(p => p.id === selectedProjectId) || projects[0];

    return (
        <div className="flex flex-col gap-6 h-[calc(100vh-120px)]">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-3xl font-black tracking-tight text-white flex items-center gap-3 font-mono">
                        <Code2 className="w-8 h-8 text-emerald-500" />
                        BRUNELLA STUDIO
                    </h1>
                    <p className="text-zinc-500">Full-stack alkalmazásfejlesztés & Marketing Preview</p>
                </div>
                <div className="flex gap-2">
                    <Badge variant="outline" className="bg-emerald-500/10 text-emerald-500 border-emerald-500/20 font-mono">AGENT_MODE: ACTIVE</Badge>
                    <Badge variant="outline" className="bg-blue-500/10 text-blue-500 border-blue-500/20 font-mono">PREVIEW_ENGINE: READY</Badge>
                </div>
            </div>

            <div className="grid grid-cols-12 gap-6 flex-1 overflow-hidden">
                {/* Bal szekció: Projektek & Chat */}
                <div className="col-span-12 lg:col-span-4 flex flex-col gap-6 overflow-hidden">
                    <Card className="bg-card/50 backdrop-blur-xl border-white/[0.04]">
                        <CardHeader className="pb-3">
                            <CardTitle className="text-sm flex items-center gap-2 font-mono uppercase tracking-widest">
                                <Plus className="w-4 h-4" /> Új Alkalmazás
                            </CardTitle>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <Input 
                                placeholder="App neve (pl. DreamFisher Webshop)" 
                                value={projectName}
                                onChange={(e) => setProjectName(e.target.value)}
                                className="bg-white/[0.02] border-white/10"
                            />
                            <Textarea 
                                placeholder="Írd le pontosan, mit szeretnél fejleszteni..." 
                                value={projectDesc}
                                onChange={(e) => setProjectDescription(e.target.value)}
                                className="bg-white/[0.02] border-white/10 min-h-[100px]"
                            />
                            <div className="grid grid-cols-2 gap-2">
                                <Button 
                                    variant="outline" 
                                    className="text-xs h-8"
                                    onClick={() => setTechStack('React + Tailwind')}
                                >
                                    Web (React)
                                </Button>
                                <Button 
                                    variant="outline" 
                                    className="text-xs h-8"
                                    onClick={() => setTechStack('Expo/React Native')}
                                >
                                    Mobil (App)
                                </Button>
                            </div>
                            <Button 
                                onClick={handleCreateProject} 
                                disabled={isCreating}
                                className="w-full bg-emerald-600 hover:bg-emerald-500 font-bold"
                            >
                                {isCreating ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Play className="w-4 h-4 mr-2" />}
                                Fejlesztés Indítása
                            </Button>
                        </CardContent>
                    </Card>

                    <Card className="bg-card/50 backdrop-blur-xl border-white/[0.04] flex-1 overflow-hidden">
                        <CardHeader className="pb-2">
                            <CardTitle className="text-xs font-mono uppercase text-zinc-500">Korábbi Projektek</CardTitle>
                        </CardHeader>
                        <CardContent className="p-0 overflow-hidden flex flex-col">
                            <ScrollArea className="flex-1">
                                <div className="p-4 space-y-2">
                                    {projects.map((p) => (
                                        <div 
                                            key={p.id}
                                            onClick={() => setSelectedProjectId(p.id)}
                                            className={`p-3 rounded-xl border cursor-pointer transition-all ${
                                                selectedProjectId === p.id 
                                                    ? 'bg-emerald-500/10 border-emerald-500/30 shadow-[0_0_15px_rgba(16,185,129,0.1)]' 
                                                    : 'bg-white/[0.04] border-transparent hover:border-white/10'
                                            }`}
                                        >
                                            <div className="flex justify-between items-center mb-1">
                                                <span className="font-bold text-xs text-white">{p.name}</span>
                                                <Badge className="text-[9px] h-4">{p.status.toUpperCase()}</Badge>
                                            </div>
                                            <div className="text-[10px] text-zinc-500 font-mono italic truncate">{p.tech_stack}</div>
                                        </div>
                                    ))}
                                </div>
                            </ScrollArea>
                        </CardContent>
                    </Card>
                </div>

                {/* Középső & Jobb szekció: Kód & Preview */}
                <div className="col-span-12 lg:col-span-8 flex flex-col gap-6 overflow-hidden">
                    <Tabs defaultValue="preview" className="h-full flex flex-col">
                        <div className="flex justify-between items-center mb-4">
                            <TabsList className="bg-white/[0.02] border border-white/[0.04] p-1 h-10">
                                <TabsTrigger value="preview" className="data-[state=active]:bg-emerald-600 flex items-center gap-2 text-xs font-bold uppercase tracking-wider">
                                    <MonitorPlay className="w-4 h-4" /> Live Preview
                                </TabsTrigger>
                                <TabsTrigger value="code" className="data-[state=active]:bg-blue-600 flex items-center gap-2 text-xs font-bold uppercase tracking-wider">
                                    <FileJson className="w-4 h-4" /> Code Stream
                                </TabsTrigger>
                                <TabsTrigger value="architecture" className="data-[state=active]:bg-purple-600 flex items-center gap-2 text-xs font-bold uppercase tracking-wider">
                                    <Box className="w-4 h-4" /> Specs
                                </TabsTrigger>
                            </TabsList>
                            {activeProject && (
                                <div className="flex items-center gap-4 text-xs font-mono">
                                    <div className="flex items-center gap-2">
                                        <div className="w-2 h-2 rounded-full bg-emerald-500 animate-ping" />
                                        <span className="text-emerald-500">AKTÍV KÓDOLÁS</span>
                                    </div>
                                    <div className="text-zinc-500">{activeProject.root_dir}</div>
                                </div>
                            )}
                        </div>

                        <TabsContent value="preview" className="flex-1 mt-0 bg-white/[0.03] rounded-3xl border border-white/10 overflow-hidden relative group">
                            {activeProject?.preview_url ? (
                                <iframe 
                                    src={activeProject.preview_url} 
                                    className="w-full h-full border-none"
                                    title="App Preview"
                                />
                            ) : (
                                <div className="w-full h-full flex flex-col items-center justify-center text-zinc-600 gap-4">
                                    <div className="p-6 rounded-full bg-white/[0.04] border border-white/[0.04]">
                                        <Globe className="w-12 h-12 opacity-20" />
                                    </div>
                                    <p className="text-sm font-mono uppercase tracking-widest opacity-40">Preview Engine Offline</p>
                                    <p className="text-xs text-center max-w-xs opacity-30 italic">"Indíts el egy fejlesztést, és Brunella itt fogja felépíteni neked a felületet valós időben."</p>
                                </div>
                            )}
                            <div className="absolute bottom-4 right-4 flex gap-2">
                                <Button size="sm" variant="secondary" className="rounded-full h-8 w-8 p-0"><Smartphone size={14} /></Button>
                                <Button size="sm" variant="secondary" className="rounded-full h-8 w-8 p-0"><Layout size={14} /></Button>
                            </div>
                        </TabsContent>

                        <TabsContent value="code" className="flex-1 mt-0 bg-zinc-950 rounded-3xl border border-white/10 overflow-hidden p-6 font-mono text-xs">
                            <div className="flex justify-between items-center mb-4 border-b border-white/[0.04] pb-2">
                                <span className="text-zinc-500 uppercase tracking-widest">Build & Execution Stream</span>
                                <span className="text-emerald-500/50">Live</span>
                            </div>
                            <ScrollArea className="h-[500px]">
                                <div className="space-y-1">
                                    {(studioLogs[activeProject?.id] || []).map((line, i) => (
                                        <div key={i} className="text-zinc-400 break-all whitespace-pre-wrap">{line}</div>
                                    ))}
                                    {(!studioLogs[activeProject?.id] || studioLogs[activeProject?.id].length === 0) && (
                                        <div className="text-zinc-700 italic">Várakozás a logokra...</div>
                                    )}
                                </div>
                            </ScrollArea>
                        </TabsContent>

                        <TabsContent value="architecture" className="flex-1 mt-0">
                            <Card className="h-full bg-white/[0.02] border-white/[0.04]">
                                <CardContent className="pt-6">
                                    <div className="space-y-6">
                                        <div className="flex items-center gap-4">
                                            <div className="p-3 bg-purple-500/10 rounded-xl"><CheckCircle2 className="w-5 h-5 text-purple-500" /></div>
                                            <div>
                                                <div className="text-sm font-bold">Adatmodell Tervezve</div>
                                                <div className="text-[10px] text-zinc-500">SQLite + Prisma séma kész</div>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-4">
                                            <div className="p-3 bg-blue-500/10 rounded-xl"><CheckCircle2 className="w-5 h-5 text-blue-500" /></div>
                                            <div>
                                                <div className="text-sm font-bold">UI Kit Kiválasztva</div>
                                                <div className="text-[10px] text-zinc-500">Shadcn UI + Radix primitives</div>
                                            </div>
                                        </div>
                                        <div className="flex items-center gap-4 opacity-40">
                                            <div className="p-3 bg-zinc-500/10 rounded-xl"><Loader2 className="w-5 h-5 animate-spin" /></div>
                                            <div>
                                                <div className="text-sm font-bold">Marketing Pipeline</div>
                                                <div className="text-[10px] text-zinc-500">SEO kulcsszavak generálása...</div>
                                            </div>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        </TabsContent>
                    </Tabs>
                </div>
            </div>
        </div>
    );
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
    Megaphone, 
    Zap, 
    ArrowRight, 
    History,
    CheckCircle2,
    Loader2,
    MonitorPlay,
    Video,
    MessageCircle,
    Target
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Textarea } from '../ui/textarea';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useBusinessStore } from '../../lib/businessStore';
import { format } from 'date-fns';

export function CampaignGeneratorWidget() {
    const [productInfo, setProductInfo] = useState('');
    const { jobs, isLoading, fetchJobs, createJob } = useBusinessStore();
    const { socket } = useSocket();
    const [selectedJobId, setSelectedJobId] = useState<string | null>(null);

    const campaignJobs = useMemo(() => jobs.filter(j => j.type === 'marketing_director'), [jobs]);

    useEffect(() => {
        fetchJobs('marketing_director');
    }, [fetchJobs]);

    useEffect(() => {
        if (!socket) return;

        const handleJobUpdate = (data: { jobId: string, status: string }) => {
            fetchJobs('marketing_director');
            if (data.status === 'completed') {
                toast.success("Marketing Kampány és Weboldal sikeresen elindítva!", {
                    icon: <Megaphone className="w-4 h-4 text-primary" />
                });
            }
        };

        socket.on('business_job:updated', handleJobUpdate);
        return () => {
            socket.off('business_job:updated', handleJobUpdate);
        };
    }, [socket, fetchJobs]);

    const handleStartCampaign = async () => {
        if (!productInfo.trim()) {
            toast.error("Kérlek add meg a termék vagy szolgáltatás leírását!");
            return;
        }
        
        const jobId = await createJob('marketing_director', productInfo);
        if (jobId) {
            toast.info("Kampány tervezés elindítva... Ágensek felébresztve.");
            setProductInfo('');
        }
    };

    const activeJob = jobs.find(j => j.id === selectedJobId) || campaignJobs[0];
    const data = activeJob?.results_json ? JSON.parse(activeJob.results_json) : null;

    return (
        <Card className="w-full shadow-xl border-primary/20 bg-card/50 backdrop-blur-md min-h-[600px]">
            <CardHeader className="pb-3 border-b border-white/[0.04] bg-secondary/10">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-primary/10 rounded-full">
                            <Megaphone className="w-5 h-5 text-primary" />
                        </div>
                        <div>
                            <CardTitle>Campaign Generator</CardTitle>
                            <CardDescription>Automatizált Marketing, Posztok & Weboldal Készítés</CardDescription>
                        </div>
                    </div>
                </div>
            </CardHeader>
            <CardContent className="pt-6">
                <div className="flex gap-2 mb-8 flex-col lg:flex-row">
                    <Textarea 
                        placeholder="Termék/szolgáltatás leírása, előnyök, célközönség (pl. Prémium kávégép irodáknak, fókusz a gyorsaságon és minőségen)" 
                        value={productInfo}
                        onChange={(e) => setProductInfo(e.target.value)}
                        className="bg-secondary/20 border-primary/10 min-h-[80px] flex-1"
                    />
                    <Button 
                        onClick={handleStartCampaign} 
                        disabled={isLoading}
                        className="bg-primary hover:bg-primary/90 min-w-[200px] h-auto text-white font-bold"
                    >
                        {isLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Zap className="w-4 h-4 mr-2" />}
                        Kampány Generálása
                    </Button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                    {/* Előzmények */}
                    <div className="lg:col-span-1 border-r border-white/[0.04] pr-4 flex flex-col gap-4">
                        <h3 className="text-xs font-semibold uppercase text-zinc-500 flex items-center gap-2">
                            <History size={12} />
                            Korábbi Kampányok
                        </h3>
                        <ScrollArea className="h-[450px]">
                            <div className="space-y-2">
                                {campaignJobs.length === 0 ? (
                                    <p className="text-xs text-zinc-500 italic">Nincsenek korábbi kampányok.</p>
                                ) : (
                                    campaignJobs.map((job) => (
                                        <div 
                                            key={job.id}
                                            onClick={() => setSelectedJobId(job.id)}
                                            className={`p-3 rounded-lg border cursor-pointer transition-all ${
                                                selectedJobId === job.id || (!selectedJobId && campaignJobs[0].id === job.id)
                                                    ? 'bg-primary/10 border-primary/30' 
                                                    : 'bg-secondary/5 border-transparent hover:border-primary/20'
                                            }`}
                                        >
                                            <div className="font-bold text-xs truncate mb-1">{job.query}</div>
                                            <div className="flex justify-between items-center text-[9px] text-zinc-500 font-mono">
                                                {format(new Date(job.created_at), 'MM.dd HH:mm')}
                                                {job.status === 'completed' && <CheckCircle2 size={10} className="text-primary" />}
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </ScrollArea>
                    </div>

                    {/* Részletek */}
                    <div className="lg:col-span-3">
                        {activeJob ? (
                            <div className="space-y-6 h-full">
                                {activeJob.status === 'running' ? (
                                    <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500">
                                        <Loader2 className="w-10 h-10 mb-4 animate-spin text-primary" />
                                        <p className="animate-pulse text-xs text-center font-mono text-zinc-400 max-w-[250px]">
                                            {activeJob.metadata || "Marketing anyagok és stúdió projekt generálása..."}
                                        </p>
                                    </div>
                                ) : data ? (
                                    <div className="grid grid-cols-1 md:grid-cols-2 gap-4 h-full animate-in fade-in duration-500">
                                        
                                        {/* Akcióterv */}
                                        <div className="p-4 rounded-xl border border-white/[0.04] bg-white/[0.02] flex flex-col">
                                            <h4 className="text-[10px] font-bold text-primary uppercase tracking-widest mb-3 flex items-center gap-2">
                                                <Target size={12} /> Akcióterv (GTM)
                                            </h4>
                                            <ScrollArea className="flex-1 h-[180px]">
                                                <div className="text-xs text-zinc-300 whitespace-pre-wrap leading-relaxed pr-3">
                                                    {data.actionPlan}
                                                </div>
                                            </ScrollArea>
                                        </div>

                                        {/* Közösségi Média */}
                                        <div className="p-4 rounded-xl border border-white/[0.04] bg-white/[0.02] flex flex-col">
                                            <h4 className="text-[10px] font-bold text-blue-500 uppercase tracking-widest mb-3 flex items-center gap-2">
                                                <MessageCircle size={12} /> Közösségi Média
                                            </h4>
                                            <ScrollArea className="flex-1 h-[180px]">
                                                <div className="text-xs text-zinc-300 whitespace-pre-wrap leading-relaxed pr-3">
                                                    {data.socialPosts}
                                                </div>
