import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Rocket, Loader2, Wand2 } from 'lucide-react';
import { toast } from 'sonner';
import { executeAgent } from '@/lib/apiService';
import { ScrollArea } from '@/components/ui/scroll-area';

export function CampaignStudio() {
  const [prompt, setPrompt] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [campaignResult, setCampaignResult] = useState<string | null>(null);

  const handleGenerateCampaign = async () => {
    if (!prompt.trim()) {
      toast.error('A kampány leírása nem lehet üres!');
      return;
    }
    setIsLoading(true);
    setCampaignResult(null);
    try {
      const result = await executeAgent('CampaignGenerator', prompt);
      if (result.success) {
        toast.success('Kampány sikeresen legenerálva!');
        setCampaignResult(result.data?.report || 'Nincs megjeleníthető riport.');
      } else {
        throw new Error(result.message || 'Ismeretlen hiba történt.');
      }
    } catch (e: any) {
      toast.error(`Kampány generálás sikertelen: ${e.message}`);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="space-y-6">
      <Card className="glass-card">
        <CardHeader>
          <CardTitle className="flex items-center gap-2 text-xl">
            <Wand2 className="text-primary" />
            Automatikus Kampány Stúdió
          </CardTitle>
          <CardDescription>
            Írj le egy terméket vagy szolgáltatást, és a BAS legenerálja a teljes marketing kampányt.
          </CardDescription>
        </CardHeader>
        <CardContent className="space-y-4">
          <Textarea
            placeholder="Például: 'Egy új, környezetbarát csomagolású kávé, ami specialty minősítéssel rendelkezik és a célcsoportja a 25-40 év közötti városi réteg...'"
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            className="min-h-[120px] bg-background/50 border-border/80"
            disabled={isLoading}
          />
          <Button onClick={handleGenerateCampaign} disabled={isLoading} className="w-full gap-2 bg-primary hover:bg-primary/90">
            {isLoading ? (
              <Loader2 className="animate-spin" />
            ) : (
              <Rocket />
            )}
            {isLoading ? 'Kampány generálása folyamatban...' : 'Kampány Generálása'}
          </Button>
        </CardContent>
      </Card>

      {campaignResult && (
        <Card className="glass-card">
          <CardHeader>
            <CardTitle>Legenerált Kampány Eredmény</CardTitle>
          </CardHeader>
          <CardContent>
            <ScrollArea className="h-[500px] bg-background/50 border border-border/80 rounded-md p-4">
              <pre className="whitespace-pre-wrap text-sm font-mono">{campaignResult}</pre>
            </ScrollArea>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

interface Message {
  id: string;
  text: string;
  sender: 'user' | 'agent';
  timestamp: Date;
  screenshot?: string;
}

const ChatInterface: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [input, setInput] = useState('');
  const [screenshot, setScreenshot] = useState<string>('');
  const [isTyping, setIsTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const chatEndpoint = process.env.REACT_APP_BROWSER_CHAT_ENDPOINT || 'http://localhost:8000/browser/chat';
  const screenshotEndpoint = process.env.REACT_APP_BROWSER_SCREENSHOT_ENDPOINT || 'http://localhost:8000/browser/screenshot';

  useEffect(() => {
    scrollToBottom();
  }, [messages, screenshot]);

  useEffect(() => {
    const interval = setInterval(async () => {
      if (messages.length > 0) {
        try {
          const response = await axios.get(screenshotEndpoint, {
            responseType: 'arraybuffer'
          });
          const base64 = Buffer.from(response.data, 'binary').toString('base64');
          setScreenshot(base64);
        } catch (error) {
          console.error('Screenshot error:', error);
        }
      }
    }, 2000);

    return () => clearInterval(interval);
  }, [messages.length]);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage: Message = {
      id: Date.now().toString(),
      text: input,
      sender: 'user',
      timestamp: new Date()
    };

    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsTyping(true);

    try {
      const response = await axios.post(chatEndpoint, {
        message: input,
        session_id: messages.length > 0 ? messages[messages.length - 1].id : undefined
      });

      const agentMessage: Message = {
        id: response.data.session_id,
        text: response.data.response,
        sender: 'agent',
        timestamp: new Date(),
        screenshot: response.data.screenshot
      };

      setMessages(prev => [...prev, agentMessage]);
      if (response.data.screenshot) {
        setScreenshot(response.data.screenshot);
      }
    } catch (error) {
      console.error('Chat error:', error);
    } finally {
      setIsTyping(false);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-gray-900 text-white">
      <div className="p-4 bg-gray-800 border-b border-gray-700">
        <h1 className="text-xl font-bold">Brunella Browser Automation</h1>
        <p className="text-sm text-gray-400">Magyar nyelvű chat és élő böngésző példány</p>
      </div>

      {screenshot && (
        <div className="p-4 bg-gray-800 border-b border-gray-700">
          <h2 className="text-sm font-semibold mb-2">Élő Böngésző Képernyő:</h2>
          <img
            src={`data:image/png;base64,${screenshot}`}
            alt="Live Browser"
            className="w-full h-auto rounded-lg border border-gray-600"
          />
        </div>
      )}

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.map((message) => (
          <div
            key={message.id}
            className={`flex ${message.sender === 'user' ? 'justify-end' : 'justify-start'}`}
          >
            <div
              className={`max-w-xs lg:max-w-md p-3 rounded-lg ${message.sender === 'user' ? 'bg-blue-600' : 'bg-gray-700'}`}
            >
              {message.screenshot && (
                <img
                  src={`data:image/png;base64,${message.screenshot}`}
                  alt="Agent Screenshot"
                  className="w-full h-auto rounded mb-2"
                />
              )}
              <p className="text-sm">{message.text}</p>
              <span className="text-xs text-gray-400">
                {message.timestamp.toLocaleTimeString('hu-HU')}
              </span>
            </div>
          </div>
        ))}

        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-gray-700 p-3 rounded-lg">
              <span className="text-sm">Gondolkodok...</span>
            </div>
          </div>
        )}

        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 bg-gray-800 border-t border-gray-700">
        <div className="flex gap-2">
          <input
            type="text"
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSend()}
            placeholder="Írd meg az utasítást magyarul..."
            className="flex-1 px-4 py-2 rounded-lg bg-gray-700 text-white border border-gray-600 focus:outline-none focus:border-blue-500"
          />
          <button
            onClick={handleSend}
            disabled={isTyping}
            className="px-6 py-2 bg-blue-600 rounded-lg hover:bg-blue-700 disabled:bg-gray-600"
          >
            Küldés
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatInterface;

import { useState, useEffect } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Cloud, Globe, RefreshCcw } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { toast } from 'sonner'
import { Skeleton } from '@/components/ui/skeleton'
import { getCloudflareConfig, submitCloudflareWorkerTask, type CloudflareRuntimeConfig } from '@/lib/apiService'

interface EdgeAgent
{
    id: string
    name: string
    kind: 'public' | 'internal'
    url?: string
    status: 'online' | 'offline' | 'unknown'
    latencyMs?: number
    statusCode?: number
    error?: string
}

interface CloudflareStatus
{
    status: 'connected' | 'degraded' | 'error'
    summary: {
        total: number
        online: number
        offline: number
        unknown: number
    }
    workers: EdgeAgent[]
}

export function CloudflareAgentsCard ()
{
    const [data, setData] = useState<CloudflareStatus | null>( null )
    const [config, setConfig] = useState<CloudflareRuntimeConfig | null>( null )
    const [loading, setLoading] = useState( true )
    const [instruction, setInstruction] = useState( 'health check' )
    const [runningWorkerId, setRunningWorkerId] = useState<string | null>( null )

    const fetchData = async () =>
    {
        try
        {
            const [agentsRes, configRes] = await Promise.all( [
                fetch( '/api/cloudflare/agents' ),
                getCloudflareConfig(),
            ] )

            if ( !agentsRes.ok )
            {
                throw new Error( `HTTP ${ agentsRes.status }` )
            }

            const json = await agentsRes.json()
            setData( json )
            setConfig( configRes )
        } catch ( e: unknown )
        {
            toast.error( 'Failed to fetch Cloudflare status' )
        } finally
        {
            setLoading( false )
        }
    }

    useEffect( () =>
    {
        fetchData()
        const interval = setInterval( fetchData, 10000 ) // Poll every 10s
        return () => clearInterval( interval )
    }, [] )

    const handleWorkerTask = async ( workerId: string, workerName: string ) =>
    {
        if ( !instruction.trim() )
        {
            toast.error( 'Adj meg egy feladatot a workerhez' )
            return
        }

        setRunningWorkerId( workerId )
        try
        {
            const result = await submitCloudflareWorkerTask( workerId, instruction.trim(), {} )
            toast.success( `Feladat elküldve: ${ workerName }`, {
                description: result.endpoint ? `endpoint: ${ result.endpoint }` : 'worker task accepted',
            } )
        } catch ( e: unknown )
        {
            const msg = e instanceof Error ? e.message : String( e )
            toast.error( `Worker dispatch hiba: ${ workerName }`, {
                description: msg,
            } )
        } finally
        {
            setRunningWorkerId( null )
        }
    }

    if ( loading && !data )
    {
        return (
            <Card className="glass-card border-white/[0.04] overflow-hidden mt-4">
                <CardHeader className="pb-3 border-b border-white/[0.04] bg-white/[0.04] flex flex-row items-center justify-between">
                    <CardTitle className="flex items-center gap-2 text-sm font-bold tracking-wider uppercase text-zinc-500">
                        <Skeleton className="h-4 w-4 rounded-full" />
                        <Skeleton className="h-4 w-32" />
                    </CardTitle>
                </CardHeader>
                <CardContent className="p-0">
                    <div className="p-4 space-y-3">
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <Skeleton className="h-4 w-4 rounded-full" />
                                <div className="space-y-1">
                                    <Skeleton className="h-3 w-24" />
                                    <Skeleton className="h-2 w-16" />
                                </div>
                            </div>
                            <Skeleton className="h-2 w-12" />
                        </div>
                        <div className="flex items-center justify-between">
                            <div className="flex items-center gap-3">
                                <Skeleton className="h-4 w-4 rounded-full" />
                                <div className="space-y-1">
                                    <Skeleton className="h-3 w-24" />
                                    <Skeleton className="h-2 w-16" />
                                </div>
                            </div>
                            <Skeleton className="h-2 w-12" />
                        </div>
                    </div>
                </CardContent>
            </Card>
        )
    }

    if ( !data ) return null

    return (
        <Card className="glass-card border-white/[0.04] overflow-hidden mt-4">
            <CardHeader className="pb-3 border-b border-white/[0.04] bg-white/[0.04] flex flex-row items-center justify-between">
                <CardTitle className="flex items-center gap-2 text-sm font-bold tracking-wider uppercase text-zinc-500">
                    <Cloud size={ 16 } className="text-orange-400" />
                    Cloudflare Edge Agents
                </CardTitle>
                <div className="flex items-center gap-2">
                    <Badge variant={ data.status === 'connected' ? 'default' : data.status === 'degraded' ? 'secondary' : 'destructive' } className="text-[10px]">
                        { data.status }
                    </Badge>
                    <Button variant="ghost" size="icon" className="h-6 w-6" onClick={ fetchData } disabled={ loading }>
                        <RefreshCcw size={ 12 } className={ loading ? "animate-spin" : "" } />
                    </Button>
                </div>
            </CardHeader>
            <CardContent className="p-0">
                <div className="px-4 py-3 border-b border-white/[0.04] bg-white/[0.02] flex flex-col gap-2">
                    <span className="text-xs text-zinc-400">Direkt worker task</span>
                    <div className="flex gap-2">
                        <Input
                            value={ instruction }
                            onChange={ ( e ) => setInstruction( e.target.value ) }
                            placeholder="Pl.: health check vagy status report"
                            className="h-8 text-xs"
                        />
                    </div>
                </div>
                <div className="px-4 py-2 text-xs text-zinc-400 border-b border-white/[0.04] bg-white/[0.02]">
                    total: { data.summary.total } • online: { data.summary.online } • offline: { data.summary.offline } • unknown: { data.summary.unknown }
                </div>
                { config && (
                    <div className="px-4 py-2 text-[11px] text-zinc-400 border-b border-white/[0.04] bg-white/[0.02] space-y-1">
                        <div>
                            edge: <span className="font-mono text-zinc-300">{ config.edge.workerUrl }</span>
                        </div>
                        <div>
                            chat: <span className="font-mono text-zinc-300">{ config.chat.url }</span>
                        </div>
                        <div className="flex flex-wrap gap-3">
                            <span>
                                tunnel: { config.tunnel.enabled ? 'enabled' : 'disabled' }
                            </span>
                            <span>
                                api-token: { config.auth.hasCloudflareApiToken ? 'ok' : 'missing' }
                            </span>
                            <span>
                                cean-key: { config.auth.hasCeanApiKey ? 'ok' : 'missing' }
                            </span>
                        </div>
                        { config.tunnel.dashboardUrl && (
                            <div>
                                <a
                                    href={ config.tunnel.dashboardUrl }
                                    target="_blank"
                                    rel="noreferrer"
                                    className="text-cyan-400 hover:text-cyan-300 underline"
                                >
                                    Mobil Dashboard megnyitása (Tunnel)
                                </a>
                            </div>
                        ) }
                    </div>
                ) }
                <div className="divide-y divide-white/5">
                    { data.workers.map( agent => (
                        <div key={ agent.id } className="flex items-center justify-between px-4 py-3 hover:bg-white/[0.03] transition-colors">
                            <div className="flex items-center gap-3">
                                <Globe size={ 16 } className="text-zinc-500" />
                                <div className="flex flex-col">
                                    <span className="text-sm font-mono text-zinc-200">{ agent.name }</span>
                                    <span className="text-[10px] text-zinc-500">
                                        { agent.kind } • { agent.url || 'not configured' }
                                    </span>
                                </div>
                            </div>
                            <div className="flex items-center gap-2">
                                <span className={ `h-2 w-2 rounded-full ${ agent.status === 'online' ? 'bg-green-500 animate-pulse' : agent.status === 'offline' ? 'bg-red-500' : 'bg-yellow-500' }` } />
                                <span className="text-xs text-zinc-400 capitalize">
                                    { agent.status }
                                    { typeof agent.latencyMs === 'number' ? ` (${ agent.latencyMs }ms)` : '' }
                                </span>
                                <Button
                                    size="sm"
                                    variant="outline"
                                    className="h-7 px-2 text-[10px]"
                                    disabled={ !agent.url || runningWorkerId === agent.id }
                                    onClick={ () => handleWorkerTask( agent.id, agent.name ) }
                                >
                                    { runningWorkerId === agent.id ? 'Küldés...' : 'Task küldés' }
                                </Button>
                            </div>
                        </div>
                    ) ) }
                    { data.workers.length === 0 && (
                        <div className="p-4 text-center text-xs text-zinc-500">
                            No active agents on the edge.
                        </div>
                    ) }
                </div>
            </CardContent>
        </Card>
    )
}

/**
 * Gold Protocol G7.4 UI: Cognitive Memory Panel
 *
 * Golden dataset + codebase indexing UI
 */

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Database, ArrowClockwise, FloppyDisk } from '@phosphor-icons/react';

interface MemoryStats {
  goldenSamples: number;
  avgQuality: number;
  indexedFiles: number;
  indexedChunks: number;
  lastIndexed: string;
}

export function CognitiveMemoryPanel() {
  const [stats, setStats] = useState<MemoryStats | null>(null);
  const [manualTask, setManualTask] = useState('');
  const [manualResponse, setManualResponse] = useState('');
  const [manualQuality, setManualQuality] = useState(5);
  const [loading, setLoading] = useState(true);
  const [reindexing, setReindexing] = useState(false);

  useEffect(() => {
    fetchStats();
    const interval = setInterval(fetchStats, 15000); // Auto-refresh 15s
    return () => clearInterval(interval);
  }, []);

  const fetchStats = async () => {
    try {
      const res = await fetch('/api/memory/stats');
      const data = await res.json();
      setStats({
        goldenSamples: data.golden.count,
        avgQuality: data.golden.avgQuality,
        indexedFiles: data.index.filesIndexed,
        indexedChunks: data.index.chunksIndexed,
        lastIndexed: data.index.lastUpdated,
      });
      setLoading(false);
    } catch (e) {
      console.error('Failed to fetch memory stats:', e);
      setLoading(false);
    }
  };

  const saveGoldenSample = async () => {
    if (!manualTask.trim() || !manualResponse.trim()) return;
    try {
      await fetch('/api/memory/golden', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          task: manualTask,
          response: manualResponse,
          quality: manualQuality,
        }),
      });
      setManualTask('');
      setManualResponse('');
      setManualQuality(5);
      fetchStats();
    } catch (e) {
      console.error('Failed to save golden sample:', e);
    }
  };

  const triggerReindex = async () => {
    setReindexing(true);
    try {
      await fetch('/api/memory/reindex', { method: 'POST' });
      setTimeout(fetchStats, 3000);
    } catch (e) {
      console.error('Failed to trigger reindex:', e);
    } finally {
      setReindexing(false);
    }
  };

  if (loading || !stats) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Cognitive Memory</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-gray-500">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* Stats */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
        <Card>
          <CardContent className="p-4">
            <div className="text-xs text-gray-500 mb-1">Golden Samples</div>
            <div className="text-2xl font-bold">{stats.goldenSamples}</div>
            <div className="text-xs text-gray-600">Avg Quality: {stats.avgQuality.toFixed(2)}/10</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="text-xs text-gray-500 mb-1">Indexed Files</div>
            <div className="text-2xl font-bold">{stats.indexedFiles}</div>
          </CardContent>
        </Card>
        <Card>
          <CardContent className="p-4">
            <div className="text-xs text-gray-500 mb-1">Indexed Chunks</div>
            <div className="text-2xl font-bold">{stats.indexedChunks}</div>
            <div className="text-xs text-gray-600">Last: {new Date(stats.lastIndexed).toLocaleString()}</div>
          </CardContent>
        </Card>
      </div>

      {/* Manual Golden Sample Form */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FloppyDisk className="w-5 h-5" />
            Save Golden Sample
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-3">
            <div>
              <label className="text-xs text-gray-600 mb-1 block">Task</label>
              <input
                type="text"
                className="w-full p-2 border rounded text-sm"
                placeholder="Task description..."
                value={manualTask}
                onChange={(e) => setManualTask(e.target.value)}
              />
            </div>
            <div>
              <label className="text-xs text-gray-600 mb-1 block">Response</label>
              <textarea
                className="w-full p-2 border rounded text-sm"
                placeholder="Response content..."
                rows={4}
                value={manualResponse}
                onChange={(e) => setManualResponse(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-4">
              <label className="text-xs text-gray-600">Quality:</label>
              <input
                type="range"
                min="1"
                max="10"
                value={manualQuality}
                onChange={(e) => setManualQuality(Number(e.target.value))}
                className="flex-1"
              />
              <Badge>{manualQuality}/10</Badge>
            </div>
            <Button onClick={saveGoldenSample} disabled={!manualTask.trim() || !manualResponse.trim()}>
              Save Sample
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Reindex */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ArrowClockwise className="w-5 h-5" />
            Codebase Reindexing
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-sm text-gray-600 mb-3">
            Trigger incremental reindexing of the codebase (only changed files).
          </p>
          <Button onClick={triggerReindex} disabled={reindexing}>
            {reindexing ? 'Reindexing...' : 'Start Reindex'}
          </Button>
        </CardContent>
      </Card>
    </div>
  );
}

