  History,
  GitBranch,
  GitCommit,
  GitPullRequest,
  Upload,
  Download,
  Plus,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { DeveloperPipeline, type PipelinePhaseView } from "./DeveloperPipeline";
import { toast } from "sonner";

// ==================== Types ====================

interface PipelineData {
  taskId: string;
  task: string;
  status: string;
  phases: PipelinePhaseView[];
  createdAt: number;
  completedAt?: number;
  error?: string;
}

interface DevStatus {
  activeTasks: number;
  completedTasks: number;
  failedTasks: number;
  totalTasks: number;
}

interface HistoryEntry {
  taskId: string;
  task: string;
  status: string;
  createdAt: number;
  completedAt?: number;
}

// ==================== P8: Git Types ====================

interface GitFileData {
  path: string;
  status: string;
}

interface GitStatusData {
  branch: string;
  ahead: number;
  behind: number;
  staged: GitFileData[];
  unstaged: GitFileData[];
  untracked: GitFileData[];
}

interface GitBranchData {
  name: string;
  current: boolean;
  remote?: boolean;
}

interface GitLogEntry {
  hash: string;
  author: string;
  date: string;
  message: string;
}

// ==================== API helpers ====================

const API_PREFIX = "/api/v1/developer";

async function devApiFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const response = await fetch(`${API_PREFIX}${path}`, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || `HTTP ${response.status}`);
  return data as T;
}

async function executeDeveloperTask(
  task: string,
  context?: Record<string, unknown>,
): Promise<{ taskId: string }> {
  return devApiFetch("/execute", {
    method: "POST",
    body: JSON.stringify({ task, context }),
  });
}

// ==================== P8: Git API Helpers ====================

async function getGitStatus(): Promise<GitStatusData> {
  const result = await devApiFetch<{ status: GitStatusData }>("/git/status");
  return result.status;
}

async function getGitBranches(remote = false): Promise<GitBranchData[]> {
  const result = await devApiFetch<{ branches: GitBranchData[] }>(
    `/git/branches?remote=${remote}`,
  );
  return result.branches;
}

async function stageGitFiles(files: string[]): Promise<void> {
  await devApiFetch("/git/stage", {
    method: "POST",
    body: JSON.stringify({ files }),
  });
}

async function unstageGitFiles(files: string[]): Promise<void> {
  await devApiFetch("/git/unstage", {
    method: "POST",
    body: JSON.stringify({ files }),
  });
}

async function commitGit(message: string): Promise<void> {
  await devApiFetch("/git/commit", {
    method: "POST",
    body: JSON.stringify({ message }),
  });
}

async function pushGit(remote?: string, branch?: string): Promise<void> {
  await devApiFetch("/git/push", {
    method: "POST",
    body: JSON.stringify({ remote, branch }),
  });
}

async function checkoutBranch(name: string): Promise<void> {
  await devApiFetch(`/git/branch/${name}`, {
    method: "PUT",
    body: JSON.stringify({ action: "checkout" }),
  });
}

// ==================== P4: Review Types & API ====================

interface ReviewFinding {
  severity: "critical" | "warning" | "info" | "suggestion";
  line?: number;
  message: string;
  rule?: string;
  suggestion?: string;
}

interface ReviewResult {
  filePath: string;
  fileName: string;
  language: string;
  score: number;
  summary: string;
  findings: ReviewFinding[];
  stats: {
    critical: number;
    warning: number;
    info: number;
    suggestion: number;
    total: number;
  };
  reviewedAt: number;
}

async function reviewFile(filePath: string): Promise<ReviewResult> {
  const data = await devApiFetch<{ review: ReviewResult }>("/review", {
    method: "POST",
    body: JSON.stringify({ filePath }),
  });
  return data.review;
}

// ==================== P5: Context Types & API ====================

interface ContextFile {
  relativePath: string;
  reason: string;
  size: number;
}

interface ContextResult {
  targetFile: string;
  totalSize: number;
  truncated: boolean;
  files: ContextFile[];
}

async function gatherContext(filePath: string): Promise<ContextResult> {
  const data = await devApiFetch<{ context: ContextResult }>("/context", {
    method: "POST",
    body: JSON.stringify({ filePath }),
  });
  return data.context;
}

const SEVERITY_CONFIG: Record<
  string,
  { icon: typeof ShieldAlert; color: string; bg: string }
> = {
  critical: { icon: ShieldAlert, color: "text-red-500", bg: "bg-red-500/10" },
  warning: {
    icon: AlertTriangle,
    color: "text-yellow-500",
    bg: "bg-yellow-500/10",
  },
  info: { icon: Info, color: "text-blue-500", bg: "bg-blue-500/10" },
  suggestion: {
    icon: Lightbulb,
    color: "text-purple-400",
    bg: "bg-purple-500/10",
  },
};

// ==================== P6: Coverage Types & API ====================

interface CoverageMetricData {
  total: number;
  covered: number;
  pct: number;
}

interface CoverageSummaryData {
  totalFiles: number;
  filesWithTests: number;
  filesWithoutTests: number;
  aggregate: {
    statements: CoverageMetricData;
    branches: CoverageMetricData;
    functions: CoverageMetricData;
    lines: CoverageMetricData;
  };
  worstFiles: Array<{
    relativePath: string;
    lines: CoverageMetricData;
    functions: CoverageMetricData;
    uncoveredLines: number[];
  }>;
  untestedFiles: string[];
  collectedAt: number;
}

async function fetchCoverage(
  mode: "run" | "parse" = "parse",
): Promise<CoverageSummaryData> {
  const data = await devApiFetch<{ coverage: CoverageSummaryData }>(
    "/coverage",
    {
      method: "POST",
      body: JSON.stringify({ mode }),
    },
  );
  return data.coverage;
}

function CoverageBar({ pct }: { pct: number }) {
  const color =
    pct >= 80 ? "bg-green-500" : pct >= 60 ? "bg-yellow-500" : "bg-red-500";
  return (
    <div className="w-20 h-2 bg-muted rounded-full overflow-hidden">
      <div
        className={cn("h-full rounded-full transition-all", color)}
        style={{ width: `${pct}%` }}
      />
    </div>
  );
}

// ==================== P7: Queue Types & API ====================

type QueueTaskStatus =
  | "queued"
  | "running"
  | "completed"
  | "failed"
  | "cancelled";
type QueueTaskPriority = "high" | "medium" | "low";

interface QueuedTaskData {
  id: string;
  type: string;
  description: string;
  priority: QueueTaskPriority;
  status: QueueTaskStatus;
  createdAt: number;
  startedAt?: number;
  completedAt?: number;
  error?: string;
}

interface QueueStatsData {
  total: number;
  queued: number;
  running: number;
  completed: number;
  failed: number;
  cancelled: number;
  avgWaitTime: number;
  avgExecutionTime: number;
}

async function fetchQueueTasks(filters?: {
  status?: string;
}): Promise<{ tasks: QueuedTaskData[]; stats: QueueStatsData }> {
  const params = filters?.status ? `?status=${filters.status}` : "";
  const data = await devApiFetch<{
    tasks: QueuedTaskData[];
    stats: QueueStatsData;
  }>(`/queue${params}`);
  return data;
}

async function cancelQueueTask(taskId: string): Promise<void> {
  await devApiFetch<{ task: QueuedTaskData; message: string }>(
    `/queue/${taskId}`,
    {
      method: "PUT",
      body: JSON.stringify({ action: "cancel" }),
    },
  );
}

async function retryQueueTask(taskId: string): Promise<QueuedTaskData> {
  const data = await devApiFetch<{ task: QueuedTaskData; message: string }>(
    `/queue/${taskId}/retry`,
    {
      method: "POST",
    },
  );
  return data.task;
}

// ==================== P10: Metrics Types & API ====================

type MetricsHistoryType = "task" | "build" | "test";
type MetricsStatus = "success" | "fail" | "error";

interface MetricsHistoryEntry {
  type: MetricsHistoryType;
  status: MetricsStatus;
  details: string;
  durationMs: number;
  timestamp: number;
}

interface MetricsData {
  builds: {
    total: number;
    success: number;
    fail: number;
    lastStatus: "success" | "fail" | "unknown";
    lastDurationMs: number;
    lastTimestamp?: number;
  };
  tests: {
    totalRuns: number;
    lastPassRate: number;
    lastDurationMs: number;
    lastTimestamp?: number;
  };
  tasks: {
    total: number;
    success: number;
    error: number;
    avgDurationMs: number;
  };
  ai: {
    totalTokenUsage: number;
    estimatedCost: number;
  };
  history: MetricsHistoryEntry[];
}

async function fetchMetrics(): Promise<MetricsData> {
  const data = await devApiFetch<{ metrics: MetricsData }>("/metrics");
  return data.metrics;
}

// ==================== P11: Approval Types & API ====================

type ApprovalStatus = "pending" | "approved" | "rejected" | "expired";

interface ApprovalRequest {
  id: string;
  type: "file_edit" | "command_exec" | "critical_action";
  description: string;
  metadata?: Record<string, unknown>;
  status: ApprovalStatus;
  createdAt: number;
  expiresAt: number;
  response?: unknown;
  respondedAt?: number;
}

async function fetchApprovals(
  status?: ApprovalStatus,
): Promise<ApprovalRequest[]> {
  const qs = status ? `?status=${status}` : "";
  const data = await devApiFetch<{ requests: ApprovalRequest[] }>(
    `/approval${qs}`,
  );
  return data.requests;
}

async function respondApproval(
  id: string,
  action: "approve" | "reject",
  response?: unknown,
): Promise<void> {
  await devApiFetch(`/approval/${id}/respond`, {
    method: "POST",
    body: JSON.stringify({ action, response }),
  });
}

// ==================== P12: Activity Feed Types & API ====================

type ActivityType = "info" | "success" | "warning" | "error" | "approval";
type ActivitySource =
  | "system"
  | "agent"
  | "user"
  | "pipeline"
  | "git"
  | "queue";

interface ActivityItem {
  id: string;
  type: ActivityType;
  source: ActivitySource;
  message: string;
  metadata?: Record<string, unknown>;
  timestamp: string;
}

async function fetchActivity(limit: number = 50): Promise<ActivityItem[]> {
  const data = await devApiFetch<{ activities: ActivityItem[] }>(
    `/feed?limit=${limit}`,
  );
  return data.activities;
}

// ==================== Component ====================

export function DeveloperPanel() {
  const [prompt, setPrompt] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [activePipeline, setActivePipeline] = useState<PipelineData | null>(
    null,
  );
  const [history, setHistory] = useState<HistoryEntry[]>([]);
  const [status, setStatus] = useState<DevStatus | null>(null);
  // P4: Code Review state
  const [reviewPath, setReviewPath] = useState("");
  const [isReviewing, setIsReviewing] = useState(false);
  const [reviewResult, setReviewResult] = useState<ReviewResult | null>(null);
  const [activeTab, setActiveTab] = useState<
    | "build"
    | "review"
    | "coverage"
    | "queue"
    | "git"
    | "metrics"
    | "approvals"
    | "activity"
  >("build");
  // P5: Context state
  const [contextPath, setContextPath] = useState("");
  const [isGatheringContext, setIsGatheringContext] = useState(false);
  const [contextResult, setContextResult] = useState<ContextResult | null>(
    null,
  );
  const [contextExpanded, setContextExpanded] = useState(false);
  // P6: Coverage state
  const [coverageData, setCoverageData] = useState<CoverageSummaryData | null>(
    null,
  );
  const [isLoadingCoverage, setIsLoadingCoverage] = useState(false);
  // P7: Queue state
  const [queueTasks, setQueueTasks] = useState<QueuedTaskData[]>([]);
  const [queueStats, setQueueStats] = useState<QueueStatsData | null>(null);
  const [isLoadingQueue, setIsLoadingQueue] = useState(false);
  // P10: Metrics state
  const [metricsData, setMetricsData] = useState<MetricsData | null>(null);
  const [isLoadingMetrics, setIsLoadingMetrics] = useState(false);
  // P11: Approvals state
  const [approvalFilter, setApprovalFilter] = useState<
    ApprovalStatus | undefined
  >("pending");
  const [approvals, setApprovals] = useState<ApprovalRequest[]>([]);
  const [isLoadingApprovals, setIsLoadingApprovals] = useState(false);
  const [respondingId, setRespondingId] = useState<string | null>(null);
  // P12: Activity Feed state
  const [activities, setActivities] = useState<ActivityItem[]>([]);
  const [isLoadingActivity, setIsLoadingActivity] = useState(false);
  const [activityLimit, setActivityLimit] = useState(30);

  // P8: Git state
  const [gitStatus, setGitStatus] = useState<GitStatusData | null>(null);
  const [gitBranches, setGitBranches] = useState<GitBranchData[]>([]);
  const [isLoadingGit, setIsLoadingGit] = useState(false);
  const [selectedFiles, setSelectedFiles] = useState<Set<string>>(new Set());
  const [commitMessage, setCommitMessage] = useState("");
  const [isCommitting, setIsCommitting] = useState(false);
  const [isPushing, setIsPushing] = useState(false);

  // Fetch status and history on mount
  const refreshData = useCallback(async () => {
    try {
      const [statusResult, historyResult] = await Promise.all([
        devApiFetch<DevStatus>("/status").catch(() => null),
        devApiFetch<{ history: HistoryEntry[] }>("/history?limit=15").catch(
          () => ({ history: [] }),
        ),
      ]);
      if (statusResult) setStatus(statusResult);
      setHistory(historyResult.history);
    } catch {
      // ignore
    }
  }, []);

  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 5000);
    return () => clearInterval(interval);
  }, [refreshData]);

  // Poll active pipeline
  useEffect(() => {
    const taskId = activePipeline?.taskId;
    const status = activePipeline?.status;

    if (!taskId || status === "done" || status === "error") return;

    const interval = setInterval(async () => {
      try {
        const result = await devApiFetch<{ pipeline: PipelineData }>(
          `/pipeline/${taskId}`,
        );
        
        // Csak akkor frissítsünk, ha változott az állapot vagy a fázisok száma
        if (JSON.stringify(result.pipeline) !== JSON.stringify(activePipeline)) {
          setActivePipeline(result.pipeline);

          if (result.pipeline.status === "done") {
            toast.success("Task completed!");
            refreshData();
          } else if (result.pipeline.status === "error") {
            toast.error(`Task failed: ${result.pipeline.error || "Unknown error"}`);
            refreshData();
          }
        }
      } catch {
        // ignore polling errors
      }
    }, 2000); // 2mp-re emelve a stabilitásért

    return () => clearInterval(interval);
  }, [activePipeline?.taskId, activePipeline?.status, refreshData]);

  const handleSubmit = async (taskOverride?: string) => {
    const task = taskOverride || prompt.trim();
    if (!task) return;

    setIsLoading(true);
    try {
      const { taskId } = await executeDeveloperTask(task);
      toast.info(`Pipeline started: ${taskId.slice(0, 15)}...`);

      // Fetch initial pipeline state
      const result = await devApiFetch<{ pipeline: PipelineData }>(
        `/pipeline/${taskId}`,
      );
      setActivePipeline(result.pipeline);
      setPrompt("");
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : "Failed to start task");
    } finally {
      setIsLoading(false);
    }
  };

  const handleQuickAction = (action: string) => {
    handleSubmit(action);
  };

  const calculateProgress = (pipeline: PipelineData): number => {
    const total = pipeline.phases.length;
    const done = pipeline.phases.filter(
      (p) => p.status === "done" || p.status === "skipped",
    ).length;
    const running = pipeline.phases.filter(
      (p) => p.status === "running",
    ).length;
    return Math.round(((done + running * 0.5) / total) * 100);
  };

  const loadMetrics = useCallback(async () => {
    setIsLoadingMetrics(true);
    try {
      const data = await fetchMetrics();
      setMetricsData(data);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to load metrics";
      toast.error(msg);
    } finally {
      setIsLoadingMetrics(false);
    }
  }, []);

  const loadApprovals = useCallback(
    async (status: ApprovalStatus | undefined = approvalFilter) => {
      setIsLoadingApprovals(true);
      try {
        const items = await fetchApprovals(status);
        setApprovals(items);
        if (status !== approvalFilter) {
          setApprovalFilter(status);
        }
      } catch (err: unknown) {
        const msg =
          err instanceof Error ? err.message : "Failed to load approvals";
        toast.error(msg);
      } finally {
        setIsLoadingApprovals(false);
      }
    },
    [approvalFilter],
  );

  const handleApprovalAction = async (
    id: string,
    action: "approve" | "reject",
  ) => {
    setRespondingId(id);
    try {
      await respondApproval(id, action);
      toast.success(action === "approve" ? "Approved" : "Rejected");
      await loadApprovals(approvalFilter);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Action failed";
      toast.error(msg);
    } finally {
      setRespondingId(null);
    }
  };

  const loadActivity = useCallback(
    async (limit: number = activityLimit) => {
      setIsLoadingActivity(true);
      try {
        const data = await fetchActivity(limit);
        setActivities(data);
        setActivityLimit(limit);
      } catch (err: unknown) {
        const msg =
          err instanceof Error ? err.message : "Failed to load activity feed";
        toast.error(msg);
      } finally {
        setIsLoadingActivity(false);
      }
    },
    [activityLimit],
  );

  // P8: Git data loading
  const loadGitStatus = useCallback(async () => {
    setIsLoadingGit(true);
    try {
      const [status, branches] = await Promise.all([
        getGitStatus(),
        getGitBranches(false),
      ]);
      setGitStatus(status);
      setGitBranches(branches);
      setSelectedFiles(new Set());
    } catch (err: unknown) {
      const msg =
        err instanceof Error ? err.message : "Failed to load git status";
      toast.error(msg);
    } finally {
      setIsLoadingGit(false);
    }
  }, []);

  const handleStageFiles = async (files: string[]) => {
    try {
      await stageGitFiles(files);
      toast.success(`Staged ${files.length} file(s)`);
      loadGitStatus();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to stage files";
      toast.error(msg);
    }
  };

  const handleUnstageFiles = async (files: string[]) => {
    try {
      await unstageGitFiles(files);
      toast.success(`Unstaged ${files.length} file(s)`);
      loadGitStatus();
    } catch (err: unknown) {
      const msg =
        err instanceof Error ? err.message : "Failed to unstage files";
      toast.error(msg);
    }
  };

  const handleCommit = async () => {
    if (!commitMessage.trim()) {
      toast.error("Commit message required");
      return;
    }
    setIsCommitting(true);
    try {
      await commitGit(commitMessage);
      toast.success("Committed successfully");
      setCommitMessage("");
      loadGitStatus();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to commit";
      toast.error(msg);
    } finally {
      setIsCommitting(false);
    }
  };

  const handlePush = async () => {
    setIsPushing(true);
    try {
      await pushGit();
      toast.success("Pushed successfully");
      loadGitStatus();
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Failed to push";
      toast.error(msg);
    } finally {
      setIsPushing(false);
    }
  };

  const handleBranchSwitch = async (branchName: string) => {
    try {
      await checkoutBranch(branchName);
      toast.success(`Switched to ${branchName}`);
      loadGitStatus();
    } catch (err: unknown) {
      const msg =
        err instanceof Error ? err.message : "Failed to switch branch";
      toast.error(msg);
    }
  };

  // Tab-change data loading effects
  useEffect(() => {
    switch (activeTab) {
      case "metrics":
        if (!metricsData) loadMetrics();
        break;
      case "approvals":
        loadApprovals(approvalFilter);
        break;
      case "activity":
        loadActivity(activityLimit);
        break;
      case "git":
        loadGitStatus();
        break;
    }
  }, [activeTab, approvalFilter, activityLimit]); // Csak a lényeges váltókra figyelünk

  useEffect(() => {
    if (activeTab !== "activity") return;
    const interval = setInterval(() => {
      loadActivity(activityLimit);
    }, 5000);
    return () => clearInterval(interval);
  }, [activeTab, activityLimit, loadActivity]);

  // P4: Submit code review
  const handleReview = async () => {
    const path = reviewPath.trim();
    if (!path) return;

    setIsReviewing(true);
    setReviewResult(null);
    try {
      const result = await reviewFile(path);
      setReviewResult(result);
      toast.success(`Review complete: ${result.score}/100`);
    } catch (e: unknown) {
      toast.error(e instanceof Error ? e.message : "Review failed");
    } finally {
      setIsReviewing(false);
    }
  };

  // Score color helper
  const getScoreColor = (score: number): string => {
    if (score >= 80) return "text-green-500";
    if (score >= 60) return "text-yellow-500";
    return "text-red-500";
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h2 className="flex items-center gap-2 text-lg font-bold">
          <Code2 size={20} className="text-primary" />
          Developer Agent
        </h2>
        <div className="flex items-center gap-2">
          {status && (
            <div className="flex items-center gap-3 text-xs text-zinc-500">
              <span className="flex items-center gap-1">
                <Activity size={12} className="text-blue-500" />
                {status.activeTasks} active
              </span>
              <span className="flex items-center gap-1">
                <CheckCircle2 size={12} className="text-green-500" />
                {status.completedTasks} done
              </span>
              <span className="flex items-center gap-1">
                <XCircle size={12} className="text-red-500" />
                {status.failedTasks} failed
              </span>
            </div>
          )}
          <Button variant="ghost" size="sm" onClick={refreshData}>
            <RefreshCw size={14} />
          </Button>
        </div>
      </div>

      {/* Tab Switcher */}
      <div className="flex gap-1 p-1 bg-muted/50 rounded-lg w-fit">
        <button
          onClick={() => setActiveTab("build")}
          className={cn(
            "px-4 py-1.5 rounded-md text-sm font-medium transition-colors",
            activeTab === "build"
              ? "bg-background shadow text-foreground"
              : "text-zinc-500 hover:text-foreground",
          )}
        >
          <span className="flex items-center gap-1.5">
            <Code2 size={14} /> Build
          </span>
        </button>
        <button
          onClick={() => setActiveTab("review")}
          className={cn(
            "px-4 py-1.5 rounded-md text-sm font-medium transition-colors",
            activeTab === "review"
              ? "bg-background shadow text-foreground"
              : "text-zinc-500 hover:text-foreground",
          )}
        >
          <span className="flex items-center gap-1.5">
            <FileSearch size={14} /> Review
          </span>
        </button>
        <button
          onClick={() => setActiveTab("coverage")}
          className={cn(
            "px-4 py-1.5 rounded-md text-sm font-medium transition-colors",
            activeTab === "coverage"
              ? "bg-background shadow text-foreground"
              : "text-zinc-500 hover:text-foreground",
          )}
        >
          <span className="flex items-center gap-1.5">
            <BarChart3 size={14} /> Coverage
          </span>
        </button>
        <button
          onClick={() => setActiveTab("queue")}
          className={cn(
            "px-4 py-1.5 rounded-md text-sm font-medium transition-colors",
            activeTab === "queue"
              ? "bg-background shadow text-foreground"
              : "text-zinc-500 hover:text-foreground",
          )}
        >
          <span className="flex items-center gap-1.5">
            <ListTodo size={14} /> Queue
          </span>
        </button>
        <button
          onClick={() => setActiveTab("metrics")}
          className={cn(
            "px-4 py-1.5 rounded-md text-sm font-medium transition-colors",
            activeTab === "metrics"
              ? "bg-background shadow text-foreground"
              : "text-zinc-500 hover:text-foreground",
          )}
        >
          <span className="flex items-center gap-1.5">
            <Gauge size={14} /> Metrics
          </span>
        </button>
        <button
          onClick={() => setActiveTab("approvals")}
          className={cn(
            "px-4 py-1.5 rounded-md text-sm font-medium transition-colors",
            activeTab === "approvals"
              ? "bg-background shadow text-foreground"
              : "text-zinc-500 hover:text-foreground",
          )}
        >
          <span className="flex items-center gap-1.5">
            <Bell size={14} /> Approvals
          </span>
        </button>
        <button
          onClick={() => setActiveTab("activity")}
          className={cn(
            "px-4 py-1.5 rounded-md text-sm font-medium transition-colors",
            activeTab === "activity"
              ? "bg-background shadow text-foreground"
              : "text-zinc-500 hover:text-foreground",
          )}
        >
          <span className="flex items-center gap-1.5">
            <History size={14} /> Activity
          </span>
        </button>
      </div>

      {/* ==================== BUILD TAB ==================== */}
      {activeTab === "build" && (
        <>
          {/* P5: Context Gatherer */}
          <Card className="glass-card">
            <CardContent className="p-3">
              <button
                onClick={() => setContextExpanded(!contextExpanded)}
                className="flex items-center gap-2 text-sm font-medium text-zinc-500 hover:text-foreground transition-colors w-full"
              >
                {contextExpanded ? (
                  <ChevronDown size={14} />
                ) : (
                  <ChevronRight size={14} />
                )}
                <FolderOpen size={14} className="text-primary" />
                Context Files
                {contextResult && (
                  <span className="text-xs bg-primary/10 text-primary px-1.5 py-0.5 rounded-full ml-auto">
                    {contextResult.files.length} files
                  </span>
                )}
              </button>
              {contextExpanded && (
                <div className="mt-3 space-y-2">
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={contextPath}
                      onChange={(e) => setContextPath(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          setIsGatheringContext(true);
                          gatherContext(contextPath)
                            .then((r) => {
                              setContextResult(r);
                              toast.success(
                                `Found ${r.files.length} context files`,
                              );
                            })
                            .catch((err: unknown) => {
                              toast.error(
                                err instanceof Error
                                  ? err.message
                                  : "Context failed",
                              );
                            })
                            .finally(() => setIsGatheringContext(false));
                        }
                      }}
                      placeholder="Enter file path to discover related files..."
                      className="flex-1 bg-transparent border border-border rounded-md px-3 py-1.5 text-xs
                             focus:outline-none focus:ring-1 focus:ring-primary/50 placeholder:text-zinc-500/50"
                      disabled={isGatheringContext}
                    />
                    <Button
                      variant="outline"
                      size="sm"
                      disabled={!contextPath.trim() || isGatheringContext}
                      onClick={() => {
                        setIsGatheringContext(true);
                        gatherContext(contextPath)
                          .then((r) => {
                            setContextResult(r);
                            toast.success(
                              `Found ${r.files.length} context files`,
                            );
                          })
                          .catch((err: unknown) => {
                            toast.error(
                              err instanceof Error
                                ? err.message
                                : "Context failed",
                            );
                          })
                          .finally(() => setIsGatheringContext(false));
                      }}
                    >
                      {isGatheringContext ? (
                        <Activity size={12} className="animate-spin" />
                      ) : (
                        <Search size={12} />
                      )}
                    </Button>
                  </div>
                  {contextResult && contextResult.files.length > 0 && (
                    <ScrollArea className="h-[140px]">
                      <div className="space-y-1">
                        {contextResult.files.map((f, i) => (
                          <div
                            key={i}
                            className="flex items-center justify-between text-xs px-2 py-1.5 rounded hover:bg-muted/50 transition-colors"
                          >
                            <div className="flex items-center gap-2 min-w-0">
                              <Code2
                                size={10}
                                className="text-primary shrink-0"
                              />
                              <span className="truncate font-mono">
                                {f.relativePath}
                              </span>
                            </div>
                            <div className="flex items-center gap-2 shrink-0 ml-2">
                              <span className="text-[10px] text-zinc-500">
                                {f.reason}
                              </span>
                              <span className="text-[10px] text-zinc-500/60">
                                {(f.size / 1024).toFixed(1)}K
                              </span>
                            </div>
                          </div>
                        ))}
                      </div>
                    </ScrollArea>
                  )}
                  {contextResult && (
                    <div className="flex items-center justify-between text-[10px] text-zinc-500 px-1">
                      <span>
                        Total: {(contextResult.totalSize / 1024).toFixed(1)} KB
                      </span>
                      {contextResult.truncated && (
                        <span className="text-yellow-500">⚠ Truncated</span>
                      )}
                    </div>
                  )}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Prompt Input */}
          <Card className="glass-card">
            <CardContent className="p-4">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) =>
                    e.key === "Enter" && !e.shiftKey && handleSubmit()
                  }
                  placeholder="Describe what you want to build... (e.g., 'generate a REST API for user management')"
                  className="flex-1 bg-transparent border border-border rounded-lg px-4 py-2.5 text-sm
                         focus:outline-none focus:ring-2 focus:ring-primary/50 placeholder:text-zinc-500/50"
                  disabled={isLoading}
                />
                <Button
                  onClick={() => handleSubmit()}
                  disabled={!prompt.trim() || isLoading}
                  className="gap-2"
                >
                  <Send size={14} />
                  Generate
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Quick Actions */}
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
            <Button
              variant="outline"
              className="gap-2 h-auto py-3"
              onClick={() =>
                handleQuickAction("generate code: create a utility module")
              }
              disabled={isLoading}
            >
              <Play size={16} className="text-green-500" />
              <div className="text-left">
                <div className="text-xs font-medium">Generate</div>
                <div className="text-[10px] text-zinc-500">
                  Create code
                </div>
              </div>
            </Button>
            <Button
              variant="outline"
              className="gap-2 h-auto py-3"
              onClick={() =>
                handleQuickAction(
                  "generate vitest tests for the latest changes",
                )
              }
              disabled={isLoading}
            >
              <TestTube2 size={16} className="text-blue-500" />
              <div className="text-left">
                <div className="text-xs font-medium">Test</div>
                <div className="text-[10px] text-zinc-500">
                  Write tests
                </div>
              </div>
            </Button>
            <Button
              variant="outline"
              className="gap-2 h-auto py-3"
              onClick={() =>
                handleQuickAction("fix all build errors automatically")
              }
              disabled={isLoading}
            >
              <Wrench size={16} className="text-orange-500" />
              <div className="text-left">
                <div className="text-xs font-medium">Fix</div>
                <div className="text-[10px] text-zinc-500">
                  Auto-repair
                </div>
              </div>
            </Button>
            <Button
              variant="outline"
              className="gap-2 h-auto py-3"
              onClick={() =>
                handleQuickAction(
                  "self-heal: fix all build errors and ensure npm run build succeeds",
                )
              }
              disabled={isLoading}
            >
              <HeartPulse size={16} className="text-red-500" />
              <div className="text-left">
                <div className="text-xs font-medium">Heal</div>
                <div className="text-[10px] text-zinc-500">
                  Self-repair
                </div>
              </div>
            </Button>
          </div>

          {/* Active Pipeline */}
          {activePipeline &&
            activePipeline.status !== "done" &&
            activePipeline.status !== "error" && (
              <Card className="glass-card border-blue-500/30">
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm flex items-center gap-2">
                    <Activity
                      size={14}
                      className="text-blue-500 animate-pulse"
                    />
                    Active Pipeline
                    <span className="text-xs text-zinc-500 font-normal ml-auto">
                      {activePipeline.taskId.slice(0, 20)}
                    </span>
                  </CardTitle>
                </CardHeader>
                <CardContent className="pt-0">
                  <p className="text-xs text-zinc-500 mb-3 truncate">
                    {activePipeline.task}
                  </p>
                  <DeveloperPipeline
                    phases={activePipeline.phases}
                    progress={calculateProgress(activePipeline)}
                  />
                </CardContent>
              </Card>
            )}

          {/* Last completed pipeline */}
          {activePipeline &&
            (activePipeline.status === "done" ||
              activePipeline.status === "error") && (
              <Card
                className={cn(
                  "glass-card",
                  activePipeline.status === "done"
                    ? "border-green-500/30"
                    : "border-red-500/30",
                )}
              >
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm flex items-center gap-2">
                    {activePipeline.status === "done" ? (
                      <CheckCircle2 size={14} className="text-green-500" />
                    ) : (
                      <XCircle size={14} className="text-red-500" />
                    )}
                    Last Result:{" "}
                    {activePipeline.status === "done" ? "Success" : "Failed"}
                  </CardTitle>
                </CardHeader>
                <CardContent className="pt-0">
                  <p className="text-xs text-zinc-500 mb-3 truncate">
                    {activePipeline.task}
                  </p>
                  <DeveloperPipeline
                    phases={activePipeline.phases}
                    progress={calculateProgress(activePipeline)}
                  />
                  {activePipeline.error && (
                    <p className="text-xs text-red-400 mt-2">
                      {activePipeline.error}
                    </p>
                  )}
                </CardContent>
              </Card>
            )}

          {/* Task History */}
          <Card className="glass-card">
            <CardHeader className="pb-3 border-b border-border/50">
              <CardTitle className="flex items-center gap-2 text-sm">
                <Clock size={14} className="text-zinc-500" />
                Task History
              </CardTitle>
            </CardHeader>
            <CardContent className="p-0">
              <ScrollArea className="h-[280px]">
                {history.length === 0 ? (
                  <div className="p-6 text-center text-sm text-zinc-500">
                    No developer tasks yet. Use the prompt above to start.
                  </div>
                ) : (
                  <div className="divide-y divide-border/50">
                    {history.map((entry, i) => (
                      <div
                        key={`${entry.taskId}-${i}`}
                        className="flex items-center gap-3 px-4 py-3 hover:bg-muted/50 transition-colors"
                      >
                        <div className="shrink-0">
                          {entry.status === "done" ? (
                            <CheckCircle2
                              size={14}
                              className="text-green-500"
                            />
                          ) : entry.status === "error" ? (
                            <XCircle size={14} className="text-red-500" />
                          ) : (
                            <Clock size={14} className="text-yellow-500" />
                          )}
                        </div>
                        <div className="flex-1 min-w-0">
                          <p className="text-sm truncate">{entry.task}</p>
                          <p className="text-xs text-zinc-500">
                            {new Date(entry.createdAt).toLocaleTimeString()}
                            {entry.completedAt && (
                              <span className="ml-2">
                                (
                                {(
                                  (entry.completedAt - entry.createdAt) /
                                  1000
                                ).toFixed(1)}
                                s)
                              </span>
                            )}
                          </p>
                        </div>
                        <span
                          className={cn(
                            "text-xs font-medium px-2 py-0.5 rounded-full",
                            entry.status === "done" &&
                              "bg-green-500/10 text-green-500",
                            entry.status === "error" &&
                              "bg-red-500/10 text-red-500",
                            !["done", "error"].includes(entry.status) &&
                              "bg-yellow-500/10 text-yellow-500",
                          )}
                        >
                          {entry.status}
                        </span>
                      </div>
                    ))}
                  </div>
                )}
              </ScrollArea>
            </CardContent>
          </Card>
        </>
      )}

      {/* ==================== REVIEW TAB ==================== */}
      {activeTab === "review" && (
        <>
          {/* Review Input */}
          <Card className="glass-card">
            <CardContent className="p-4">
              <div className="flex gap-2">
                <input
                  type="text"
                  value={reviewPath}
                  onChange={(e) => setReviewPath(e.target.value)}
                  onKeyDown={(e) => e.key === "Enter" && handleReview()}
                  placeholder="Enter file path to review (e.g., src/agents/DeveloperAgent.ts)"
                  className="flex-1 bg-transparent border border-border rounded-lg px-4 py-2.5 text-sm
                         focus:outline-none focus:ring-2 focus:ring-primary/50 placeholder:text-zinc-500/50"
                  disabled={isReviewing}
                />
                <Button
                  onClick={handleReview}
                  disabled={!reviewPath.trim() || isReviewing}
                  className="gap-2"
                >
                  <Search size={14} />
                  Review
                </Button>
              </div>
            </CardContent>
          </Card>

          {/* Review Loading */}
          {isReviewing && (
            <Card className="glass-card border-blue-500/30">
              <CardContent className="p-6 text-center">
                <Activity
                  size={24}
                  className="text-blue-500 animate-spin mx-auto mb-2"
                />
                <p className="text-sm text-zinc-500">
                  Analyzing code quality...
                </p>
              </CardContent>
            </Card>
          )}

          {/* Review Results */}
          {reviewResult && !isReviewing && (
            <>
              {/* Score & Summary */}
              <Card className="glass-card">
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm flex items-center justify-between">
                    <span className="flex items-center gap-2">
                      <FileSearch size={14} className="text-primary" />
                      {reviewResult.fileName}
                      <span className="text-xs font-normal text-zinc-500">
                        ({reviewResult.language})
                      </span>
                    </span>
                    <span
                      className={cn(
                        "text-2xl font-bold",
                        getScoreColor(reviewResult.score),
                      )}
                    >
                      {reviewResult.score}/100
                    </span>
                  </CardTitle>
                </CardHeader>
                <CardContent className="pt-0">
                  <p className="text-sm text-zinc-500 mb-3">
                    {reviewResult.summary}
                  </p>
                  {/* Stats row */}
                  <div className="flex gap-3 text-xs">
                    <span className="flex items-center gap-1">
                      <ShieldAlert size={12} className="text-red-500" />
                      {reviewResult.stats.critical} critical
                    </span>
                    <span className="flex items-center gap-1">
                      <AlertTriangle size={12} className="text-yellow-500" />
                      {reviewResult.stats.warning} warnings
                    </span>
                    <span className="flex items-center gap-1">
                      <Info size={12} className="text-blue-500" />
                      {reviewResult.stats.info} info
                    </span>
                    <span className="flex items-center gap-1">
                      <Lightbulb size={12} className="text-purple-400" />
                      {reviewResult.stats.suggestion} suggestions
                    </span>
                  </div>
                </CardContent>
              </Card>

              {/* Findings List */}
              {reviewResult.findings.length > 0 && (
                <Card className="glass-card">
                  <CardHeader className="pb-3 border-b border-border/50">
                    <CardTitle className="flex items-center gap-2 text-sm">
                      <Search size={14} className="text-zinc-500" />
                      Findings ({reviewResult.findings.length})
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="p-0">
                    <ScrollArea className="h-[340px]">
                      <div className="divide-y divide-border/50">
                        {reviewResult.findings.map((finding, i) => {
                          const config =
                            SEVERITY_CONFIG[finding.severity] ||
                            SEVERITY_CONFIG.info;
                          const Icon = config.icon;
                          return (
                            <div
                              key={i}
                              className="px-4 py-3 hover:bg-muted/50 transition-colors"
                            >
                              <div className="flex items-start gap-2">
                                <span
                                  className={cn(
                                    "shrink-0 mt-0.5",
                                    config.color,
                                  )}
                                >
                                  <Icon size={14} />
                                </span>
                                <div className="flex-1 min-w-0">
                                  <div className="flex items-center gap-2">
                                    <span
                                      className={cn(
                                        "text-[10px] font-medium px-1.5 py-0.5 rounded-full uppercase",
                                        config.bg,
                                        config.color,
                                      )}
                                    >
                                      {finding.severity}
                                    </span>
                                    {finding.line && (
                                      <span className="text-xs text-zinc-500">
                                        Line {finding.line}
                                      </span>
                                    )}
                                    {finding.rule && (
                                      <span className="text-[10px] text-zinc-500 font-mono">
                                        [{finding.rule}]
                                      </span>
                                    )}
                                  </div>
                                  <p className="text-sm mt-1">
                                    {finding.message}
                                  </p>
                                  {finding.suggestion && (
                                    <p className="text-xs text-zinc-500 mt-1 italic">
                                      → {finding.suggestion}
                                    </p>
                                  )}
                                </div>
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    </ScrollArea>
                  </CardContent>
                </Card>
              )}
            </>
          )}

          {/* Empty state for review */}
          {!reviewResult && !isReviewing && (
            <Card className="glass-card">
              <CardContent className="p-8 text-center">
                <FileSearch
                  size={32}
                  className="text-zinc-500/50 mx-auto mb-3"
                />
                <p className="text-sm text-zinc-500">
                  Enter a file path above to start an AI-powered code review.
                </p>
                <p className="text-xs text-zinc-500/70 mt-1">
                  The review analyzes code quality, security, patterns, and
                  suggests improvements.
                </p>
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* ==================== COVERAGE TAB ==================== */}
      {activeTab === "coverage" && (
        <>
          {/* Coverage Controls */}
          <Card className="glass-card">
            <CardContent className="p-4">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <BarChart3 size={16} className="text-primary" />
                  <span className="text-sm font-medium">
                    Test Coverage Analysis
                  </span>
                </div>
                <div className="flex gap-2">
                  <Button
                    variant="outline"
                    size="sm"
                    disabled={isLoadingCoverage}
                    onClick={async () => {
                      setIsLoadingCoverage(true);
                      try {
                        const result = await fetchCoverage("parse");
                        setCoverageData(result);
                        toast.success("Coverage data loaded");
                      } catch (err: unknown) {
                        toast.error(
                          err instanceof Error
                            ? err.message
                            : "Failed to load coverage",
                        );
                      } finally {
                        setIsLoadingCoverage(false);
                      }
                    }}
                  >
                    {isLoadingCoverage ? (
                      <Activity size={12} className="animate-spin" />
                    ) : (
                      <RefreshCw size={12} />
                    )}
                    <span className="ml-1.5">Load Existing</span>
                  </Button>
                  <Button
                    size="sm"
                    disabled={isLoadingCoverage}
                    onClick={async () => {
                      setIsLoadingCoverage(true);
                      try {
                        const result = await fetchCoverage("run");
                        setCoverageData(result);
                        toast.success("Coverage run complete");
                      } catch (err: unknown) {
                        toast.error(
                          err instanceof Error
                            ? err.message
                            : "Coverage run failed",
                        );
                      } finally {
                        setIsLoadingCoverage(false);
                      }
                    }}
                  >
                    <Play size={12} />
                    <span className="ml-1.5">Run Coverage</span>
                  </Button>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* Coverage Loading */}
          {isLoadingCoverage && (
            <Card className="glass-card border-blue-500/30">
              <CardContent className="p-6 text-center">
                <Activity
                  size={24}
                  className="text-blue-500 animate-spin mx-auto mb-2"
                />
                <p className="text-sm text-zinc-500">
                  Analyzing coverage...
                </p>
              </CardContent>
            </Card>
          )}

          {/* Coverage Results */}
          {coverageData && !isLoadingCoverage && (
            <>
              {/* Aggregate Metrics */}
              <Card className="glass-card">
                <CardHeader className="pb-3">
                  <CardTitle className="text-sm flex items-center gap-2">
                    <BarChart3 size={14} className="text-primary" />
                    Aggregate Coverage
                    <span className="ml-auto text-xs text-zinc-500">
                      {coverageData.filesWithTests} / {coverageData.totalFiles}{" "}
                      files
                    </span>
                  </CardTitle>
                </CardHeader>
                <CardContent className="pt-0 space-y-2">
                  {(
                    ["statements", "branches", "functions", "lines"] as const
                  ).map((metric) => {
                    const d = coverageData.aggregate[metric];
                    return (
                      <div
                        key={metric}
                        className="flex items-center gap-3 text-xs"
                      >
                        <span className="w-20 text-zinc-500 capitalize">
                          {metric}
                        </span>
                        <CoverageBar pct={d.pct} />
                        <span
                          className={cn(
                            "w-10 text-right font-medium",
                            d.pct >= 80
                              ? "text-green-500"
                              : d.pct >= 60
                                ? "text-yellow-500"
                                : "text-red-500",
                          )}
                        >
                          {d.pct}%
                        </span>
                        <span className="text-zinc-500/60">
                          {d.covered}/{d.total}
                        </span>
                      </div>
                    );
                  })}
                </CardContent>
              </Card>

              {/* Worst Files */}
              {coverageData.worstFiles.length > 0 && (
                <Card className="glass-card">
                  <CardHeader className="pb-3 border-b border-border/50">
                    <CardTitle className="flex items-center gap-2 text-sm">
                      <AlertTriangle size={14} className="text-yellow-500" />
                      Lowest Coverage ({coverageData.worstFiles.length})
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="p-0">
                    <ScrollArea className="h-[200px]">
                      <div className="divide-y divide-border/50">
                        {coverageData.worstFiles.map((f, i) => (
                          <div
                            key={i}
                            className="px-4 py-2 hover:bg-muted/50 transition-colors"
                          >
                            <div className="flex items-center justify-between">
                              <span className="text-xs font-mono truncate flex-1">
                                {f.relativePath}
                              </span>
                              <div className="flex items-center gap-2 ml-2">
                                <CoverageBar pct={f.lines.pct} />
                                <span
                                  className={cn(
                                    "text-xs font-medium w-10 text-right",
                                    f.lines.pct >= 80
                                      ? "text-green-500"
                                      : f.lines.pct >= 60
                                        ? "text-yellow-500"
                                        : "text-red-500",
                                  )}
                                >
                                  {f.lines.pct}%
                                </span>
                              </div>
                            </div>
                            {f.uncoveredLines.length > 0 &&
                              f.uncoveredLines.length <= 10 && (
                                <p className="text-[10px] text-zinc-500 mt-0.5">
                                  Uncovered: L{f.uncoveredLines.join(", L")}
                                </p>
                              )}
                          </div>
                        ))}
                      </div>
                    </ScrollArea>
                  </CardContent>
                </Card>
              )}

              {/* Untested Files */}
              {coverageData.untestedFiles.length > 0 && (
                <Card className="glass-card border-red-500/20">
                  <CardHeader className="pb-3">
                    <CardTitle className="flex items-center gap-2 text-sm">
                      <XCircle size={14} className="text-red-500" />
                      Untested Files ({coverageData.untestedFiles.length})
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="pt-0">
                    <ScrollArea className="h-[120px]">
                      <div className="space-y-1">
                        {coverageData.untestedFiles.map((f, i) => (
                          <div
                            key={i}
                            className="text-xs text-red-400 font-mono"
                          >
                            {f}
                          </div>
                        ))}
                      </div>
                    </ScrollArea>
                  </CardContent>
                </Card>
              )}
            </>
          )}

          {/* Empty state for coverage */}
          {!coverageData && !isLoadingCoverage && (
            <Card className="glass-card">
              <CardContent className="p-8 text-center">
                <BarChart3
                  size={32}
                  className="text-zinc-500/50 mx-auto mb-3"
                />
                <p className="text-sm text-zinc-500">
                  Click &quot;Load Existing&quot; to parse coverage data, or
                  &quot;Run Coverage&quot; to generate fresh results.
                </p>
                <p className="text-xs text-zinc-500/70 mt-1">
                  Coverage analysis shows statement, branch, function, and line
                  coverage metrics.
                </p>
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* ==================== P7: Queue Tab ==================== */}
      {activeTab === "queue" && (
        <>
          <div className="flex items-center justify-between mb-6">
            <div>
              <h2 className="text-xl font-semibold mb-1">Task Queue</h2>
              <p className="text-sm text-zinc-500">
                Manage concurrent developer tasks (max 3 workers)
              </p>
            </div>
            <Button
              onClick={async () => {
                setIsLoadingQueue(true);
                try {
                  const data = await fetchQueueTasks();
                  setQueueTasks(data.tasks);
                  setQueueStats(data.stats);
                  toast.success("Queue refreshed");
                } catch (err: unknown) {
                  const errMsg =
                    err instanceof Error ? err.message : String(err);
                  toast.error("Failed to load queue", { description: errMsg });
                } finally {
                  setIsLoadingQueue(false);
                }
              }}
              disabled={isLoadingQueue}
              size="sm"
              variant="outline"
            >
              {isLoadingQueue ? "Loading..." : "Refresh Queue"}
            </Button>
          </div>

          {/* Queue Stats Cards */}
          {queueStats && (
            <div className="grid grid-cols-2 lg:grid-cols-4 gap-4 mb-6">
              <Card className="glass-card">
                <CardContent className="p-4">
                  <div className="text-sm text-zinc-500 mb-1">
                    Queued
                  </div>
                  <div className="text-2xl font-bold text-yellow-500">
                    {queueStats.queued}
                  </div>
                </CardContent>
              </Card>
              <Card className="glass-card">
                <CardContent className="p-4">
                  <div className="text-sm text-zinc-500 mb-1">
                    Running
                  </div>
                  <div className="text-2xl font-bold text-blue-500">
                    {queueStats.running}
                  </div>
                </CardContent>
              </Card>
              <Card className="glass-card">
                <CardContent className="p-4">
                  <div className="text-sm text-zinc-500 mb-1">
                    Completed
                  </div>
                  <div className="text-2xl font-bold text-green-500">
                    {queueStats.completed}
                  </div>
                </CardContent>
              </Card>
              <Card className="glass-card">
                <CardContent className="p-4">
                  <div className="text-sm text-zinc-500 mb-1">
                    Failed
                  </div>
                  <div className="text-2xl font-bold text-red-500">
                    {queueStats.failed}
                  </div>
                </CardContent>
              </Card>
            </div>
          )}

          {/* Task List */}
          {queueTasks.length > 0 && (
            <Card className="glass-card">
              <CardContent className="p-0">
                <ScrollArea className="h-[500px]">
                  <div className="divide-y divide-border">
                    {queueTasks.map((task, i) => (
                      <div
                        key={`${task.id}-${i}`}
                        className="p-4 hover:bg-accent/50 transition-colors"
                      >
                        <div className="flex items-start justify-between gap-4">
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 mb-2">
                              <Badge
                                variant={
                                  task.status === "completed"
                                    ? "default"
                                    : task.status === "failed"
                                      ? "destructive"
                                      : task.status === "running"
                                        ? "default"
                                        : task.status === "cancelled"
                                          ? "secondary"
                                          : "outline"
                                }
                                className={cn(
                                  "text-xs",
                                  task.status === "queued" &&
                                    "bg-yellow-500/10 text-yellow-500 border-yellow-500/20",
                                  task.status === "running" &&
                                    "bg-blue-500/10 text-blue-500 border-blue-500/20",
                                  task.status === "completed" &&
                                    "bg-green-500/10 text-green-500 border-green-500/20",
                                )}
                              >
                                {task.status.toUpperCase()}
                              </Badge>
                              <Badge
                                variant="outline"
                                className={cn(
                                  "text-xs",
                                  task.priority === "high" &&
                                    "bg-red-500/10 text-red-500 border-red-500/30",
                                  task.priority === "medium" &&
                                    "bg-yellow-500/10 text-yellow-500 border-yellow-500/30",
                                  task.priority === "low" &&
                                    "bg-gray-500/10 text-gray-500 border-gray-500/30",
                                )}
                              >
                                {task.priority === "high"
                                  ? "HIGH"
                                  : task.priority === "medium"
                                    ? "MED"
                                    : "LOW"}
                              </Badge>
                              <span className="text-xs text-zinc-500">
                                {task.type}
                              </span>
                            </div>
                            <p className="text-sm font-medium mb-1 truncate">
                              {task.description}
                            </p>
                            <div className="flex items-center gap-3 text-xs text-zinc-500">
                              <span>ID: {task.id.slice(0, 8)}</span>
                              <span>
                                Created:{" "}
                                {new Date(task.createdAt).toLocaleTimeString()}
                              </span>
                              {task.completedAt && (
                                <span>
                                  Duration:{" "}
                                  {Math.round(
                                    (task.completedAt -
                                      (task.startedAt || task.createdAt)) /
                                      1000,
                                  )}
                                  s
                                </span>
                              )}
                            </div>
                            {task.error && (
                              <div className="mt-2 p-2 bg-destructive/10 border border-destructive/20 rounded text-xs text-destructive">
                                {task.error}
                              </div>
                            )}
                          </div>
                          <div className="flex items-center gap-2">
                            {(task.status === "queued" ||
                              task.status === "running") && (
                              <Button
                                size="sm"
                                variant="ghost"
                                onClick={async () => {
                                  try {
                                    await cancelQueueTask(task.id);
                                    toast.success("Task cancelled");
                                    const data = await fetchQueueTasks();
                                    setQueueTasks(data.tasks);
                                    setQueueStats(data.stats);
                                  } catch (err: unknown) {
                                    const errMsg =
                                      err instanceof Error
                                        ? err.message
                                        : String(err);
                                    toast.error("Failed to cancel task", {
                                      description: errMsg,
                                    });
                                  }
                                }}
                              >
                                <X size={16} />
                              </Button>
                            )}
                            {task.status === "failed" && (
                              <Button
                                size="sm"
                                variant="ghost"
                                onClick={async () => {
                                  try {
                                    await retryQueueTask(task.id);
                                    toast.success("Task retried");
                                    const data = await fetchQueueTasks();
                                    setQueueTasks(data.tasks);
                                    setQueueStats(data.stats);
                                  } catch (err: unknown) {
                                    const errMsg =
                                      err instanceof Error
                                        ? err.message
                                        : String(err);
                                    toast.error("Failed to retry task", {
                                      description: errMsg,
                                    });
                                  }
                                }}
                              >
                                <RotateCw size={16} />
                              </Button>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              </CardContent>
            </Card>
          )}

          {/* Empty State */}
          {queueTasks.length === 0 && !isLoadingQueue && (
            <Card className="glass-card">
              <CardContent className="p-8 text-center">
                <ListTodo
                  size={32}
                  className="text-zinc-500/50 mx-auto mb-3"
                />
                <p className="text-sm text-zinc-500">
                  No tasks in queue. Use CLI to add tasks:{" "}
                  <code className="text-xs bg-muted px-1 py-0.5 rounded">
                    brunella dev queue add
                  </code>
                </p>
                <p className="text-xs text-zinc-500/70 mt-1">
                  Queue supports concurrent task execution with priority
                  scheduling.
                </p>
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* ==================== P10: Metrics Tab ==================== */}
      {activeTab === "metrics" && (
        <>
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold">Developer Metrics</h2>
              <p className="text-sm text-zinc-500">
                Build, test, and task performance snapshots
              </p>
            </div>
            <Button
              size="sm"
              variant="outline"
              disabled={isLoadingMetrics}
              onClick={loadMetrics}
            >
              {isLoadingMetrics ? (
                <Activity size={14} className="animate-spin" />
              ) : (
                <RefreshCw size={14} />
              )}
              <span className="ml-1.5">Refresh</span>
            </Button>
          </div>

          {isLoadingMetrics && (
            <Card className="glass-card border-blue-500/20">
              <CardContent className="p-6 text-center">
                <Activity
                  size={20}
                  className="animate-spin text-blue-500 mx-auto mb-2"
                />
                <p className="text-sm text-zinc-500">
                  Loading metrics...
                </p>
              </CardContent>
            </Card>
          )}

          {metricsData && !isLoadingMetrics && (
            <>
              <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <Card className="glass-card">
                  <CardContent className="p-4 space-y-2">
                    <div className="flex items-center justify-between text-sm text-zinc-500">
                      <span className="flex items-center gap-2">
                        <Gauge size={14} className="text-primary" /> Builds
                      </span>
                      <Badge variant="outline" className="text-[10px]">
                        {metricsData.builds.lastStatus === "unknown"
                          ? "n/a"
                          : metricsData.builds.lastStatus}
                      </Badge>
                    </div>
                    <div className="text-3xl font-bold">
                      {metricsData.builds.total}
                    </div>
                    <div className="flex items-center gap-3 text-xs text-zinc-500">
                      <span className="text-green-500">
                        {metricsData.builds.success} success
                      </span>
                      <span className="text-red-500">
                        {metricsData.builds.fail} fail
                      </span>
                    </div>
                    {metricsData.builds.lastDurationMs > 0 && (
                      <p className="text-xs text-zinc-500">
                        Last duration:{" "}
                        {(metricsData.builds.lastDurationMs / 1000).toFixed(1)}s
                      </p>
                    )}
                  </CardContent>
                </Card>
                <Card className="glass-card">
                  <CardContent className="p-4 space-y-2">
                    <div className="flex items-center justify-between text-sm text-zinc-500">
                      <span className="flex items-center gap-2">
                        <TestTube2 size={14} className="text-primary" /> Tests
                      </span>
                      <Badge variant="outline" className="text-[10px]">
                        {metricsData.tests.totalRuns} runs
                      </Badge>
                    </div>
                    <div className="text-3xl font-bold">
                      {metricsData.tests.lastPassRate}%
                    </div>
                    <p className="text-xs text-zinc-500">
                      Last duration:{" "}
                      {(metricsData.tests.lastDurationMs / 1000).toFixed(1)}s
                    </p>
                  </CardContent>
                </Card>
                <Card className="glass-card">
                  <CardContent className="p-4 space-y-2">
                    <div className="flex items-center justify-between text-sm text-zinc-500">
                      <span className="flex items-center gap-2">
                        <Activity size={14} className="text-primary" /> Tasks
                      </span>
                      <Badge variant="outline" className="text-[10px]">
                        Avg {Math.round(metricsData.tasks.avgDurationMs / 1000)}
                        s
                      </Badge>
                    </div>
                    <div className="text-3xl font-bold">
                      {metricsData.tasks.total}
                    </div>
                    <div className="flex items-center gap-3 text-xs text-zinc-500">
                      <span className="text-green-500">
                        {metricsData.tasks.success} success
                      </span>
                      <span className="text-red-500">
                        {metricsData.tasks.error} error
                      </span>
                    </div>
                  </CardContent>
                </Card>
              </div>

              {metricsData.history.length > 0 ? (
                <Card className="glass-card">
                  <CardHeader className="pb-3 border-b border-border/50">
                    <CardTitle className="flex items-center gap-2 text-sm">
                      <History size={14} className="text-zinc-500" />{" "}
                      Recent Runs
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="p-0">
                    <ScrollArea className="h-[260px]">
                      <div className="divide-y divide-border/60">
                        {metricsData.history.map((entry, idx) => (
                          <div
                            key={idx}
                            className="px-4 py-3 flex items-center gap-3"
                          >
                            <Badge
                              variant="outline"
                              className={cn(
                                "text-[10px]",
                                entry.status === "success" &&
                                  "bg-green-500/10 text-green-500 border-green-500/30",
                                entry.status !== "success" &&
                                  "bg-red-500/10 text-red-500 border-red-500/30",
                              )}
                            >
                              {entry.type.toUpperCase()}
                            </Badge>
                            <div className="flex-1 min-w-0">
                              <p className="text-sm truncate">
                                {entry.details}
                              </p>
                              <p className="text-xs text-zinc-500">
                                {(entry.durationMs / 1000).toFixed(1)}s •{" "}
                                {new Date(entry.timestamp).toLocaleTimeString()}
                              </p>
                            </div>
                          </div>
                        ))}
                      </div>
                    </ScrollArea>
                  </CardContent>
                </Card>
              ) : (
                <Card className="glass-card">
                  <CardContent className="p-6 text-center text-sm text-zinc-500">
                    No metrics recorded yet. Run builds or tasks to populate
                    history.
                  </CardContent>
                </Card>
              )}
            </>
          )}

          {!metricsData && !isLoadingMetrics && (
            <Card className="glass-card">
              <CardContent className="p-6 text-center text-sm text-zinc-500">
                No metrics data available. Trigger a build/test/task to start
                tracking.
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* ==================== P11: Approvals Tab ==================== */}
      {activeTab === "approvals" && (
        <>
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold">Approval Requests</h2>
              <p className="text-sm text-zinc-500">
                Human-in-the-loop confirmations for critical actions
              </p>
            </div>
            <div className="flex items-center gap-2">
              {(
                [
                  "pending",
                  "approved",
                  "rejected",
                  "expired",
                ] as ApprovalStatus[]
              ).map((status) => (
                <Button
                  key={status}
                  variant={approvalFilter === status ? "default" : "outline"}
                  size="sm"
                  onClick={() => loadApprovals(status)}
                >
                  {status}
                </Button>
              ))}
              <Button
                size="sm"
                variant="ghost"
                onClick={() => loadApprovals(approvalFilter)}
                disabled={isLoadingApprovals}
              >
                {isLoadingApprovals ? (
                  <Activity size={14} className="animate-spin" />
                ) : (
                  <RefreshCw size={14} />
                )}
              </Button>
            </div>
          </div>

          {isLoadingApprovals && (
            <Card className="glass-card border-blue-500/20">
              <CardContent className="p-6 text-center text-sm text-zinc-500">
                <Activity
                  size={18}
                  className="animate-spin text-blue-500 mx-auto mb-2"
                />
                Loading approvals...
              </CardContent>
            </Card>
          )}

          {approvals.length > 0 && !isLoadingApprovals && (
            <Card className="glass-card">
              <CardContent className="p-0">
                <ScrollArea className="h-[420px]">
                  <div className="divide-y divide-border/60">
                    {approvals.map((req) => (
                      <div key={req.id} className="p-4 flex items-start gap-3">
                        <Badge
                          variant="outline"
                          className={cn(
                            "text-[10px] mt-0.5",
                            req.status === "pending" &&
                              "bg-yellow-500/10 text-yellow-500 border-yellow-500/40",
                            req.status === "approved" &&
                              "bg-green-500/10 text-green-500 border-green-500/40",
                            req.status === "rejected" &&
                              "bg-red-500/10 text-red-500 border-red-500/40",
                            req.status === "expired" &&
                              "bg-muted/60 text-zinc-500 border-border",
                          )}
                        >
                          {req.status.toUpperCase()}
                        </Badge>
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 text-xs text-zinc-500">
                            <span className="font-mono">
                              {req.id.slice(0, 8)}
                            </span>
                            <span>Type: {req.type}</span>
                            <span>
                              Created:{" "}
                              {new Date(req.createdAt).toLocaleTimeString()}
                            </span>
                          </div>
                          <p className="text-sm mt-1">{req.description}</p>
                          {req.metadata && (
                            <p className="text-xs text-zinc-500 mt-1 truncate">
                              Meta: {JSON.stringify(req.metadata)}
                            </p>
                          )}
                          {req.response && (
                            <p className="text-xs text-zinc-500 mt-1">
                              Response: {JSON.stringify(req.response)}
                            </p>
                          )}
                          <div className="flex items-center gap-2 mt-2">
                            {req.status === "pending" && (
                              <>
                                <Button
                                  size="sm"
                                  variant="default"
                                  disabled={respondingId === req.id}
                                  onClick={() =>
                                    handleApprovalAction(req.id, "approve")
                                  }
                                  className="h-7"
                                >
                                  {respondingId === req.id ? "..." : "Approve"}
                                </Button>
                                <Button
                                  size="sm"
                                  variant="outline"
                                  disabled={respondingId === req.id}
                                  onClick={() =>
                                    handleApprovalAction(req.id, "reject")
                                  }
                                  className="h-7"
                                >
                                  Reject
                                </Button>
                              </>
                            )}
                            {req.status !== "pending" && req.respondedAt && (
                              <span className="text-xs text-zinc-500">
                                Resolved{" "}
                                {new Date(req.respondedAt).toLocaleTimeString()}
                              </span>
                            )}
                          </div>
                        </div>
                      </div>
                    ))}
                  </div>
                </ScrollArea>
              </CardContent>
            </Card>
          )}

          {approvals.length === 0 && !isLoadingApprovals && (
            <Card className="glass-card">
              <CardContent className="p-6 text-center text-sm text-zinc-500">
                No approval requests in this state.
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* ==================== P12: Activity Feed Tab ==================== */}
      {activeTab === "activity" && (
        <>
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold">Activity Feed</h2>
              <p className="text-sm text-zinc-500">
                Recent system, agent, queue, and approval events
              </p>
            </div>
            <div className="flex items-center gap-2">
              <select
                className="border border-border rounded-md bg-transparent text-sm px-2 py-1"
                value={activityLimit}
                onChange={(e) => loadActivity(parseInt(e.target.value, 10))}
              >
                {[20, 30, 50, 100].map((n) => (
                  <option key={n} value={n}>
                    {n} items
                  </option>
                ))}
              </select>
              <Button
                size="sm"
                variant="outline"
                onClick={() => loadActivity(activityLimit)}
                disabled={isLoadingActivity}
              >
                {isLoadingActivity ? (
                  <Activity size={14} className="animate-spin" />
                ) : (
                  <RefreshCw size={14} />
                )}
              </Button>
            </div>
          </div>

          {isLoadingActivity && (
            <Card className="glass-card border-blue-500/20">
              <CardContent className="p-6 text-center text-sm text-zinc-500">
                <Activity
                  size={18}
                  className="animate-spin text-blue-500 mx-auto mb-2"
                />
                Loading activity...
              </CardContent>
            </Card>
          )}

          {activities.length > 0 && !isLoadingActivity && (
            <Card className="glass-card">
              <CardContent className="p-0">
                <ScrollArea className="h-[480px]">
                  <div className="divide-y divide-border/60">
                    {activities.map((item, i) => {
                      const color =
                        item.type === "success"
                          ? "text-green-500"
                          : item.type === "warning"
                            ? "text-yellow-500"
                            : item.type === "error"
                              ? "text-red-500"
                              : item.type === "approval"
                                ? "text-blue-500"
                                : "text-zinc-500";
                      return (
                        <div
                          key={`${item.id}-${i}`}
                          className="p-4 flex items-start gap-3"
                        >
                          <div
                            className={cn(
                              "mt-0.5 h-2 w-2 rounded-full",
                              item.type === "success"
                                ? "bg-green-500"
                                : item.type === "warning"
                                  ? "bg-yellow-500"
                                  : item.type === "error"
                                    ? "bg-red-500"
                                    : item.type === "approval"
                                      ? "bg-blue-500"
                                      : "bg-muted-foreground",
                            )}
                          />
                          <div className="flex-1 min-w-0">
                            <div className="flex items-center gap-2 text-xs text-zinc-500">
                              <span className={color}>{item.type}</span>
                              <span className="uppercase text-[10px]">
                                {item.source}
                              </span>
                              <span>
                                {new Date(item.timestamp).toLocaleTimeString()}
                              </span>
                            </div>
                            <p className="text-sm mt-1">{item.message}</p>
                            {item.metadata && (
                              <p className="text-xs text-zinc-500 mt-1 truncate">
                                Meta: {JSON.stringify(item.metadata)}
                              </p>
                            )}
                          </div>
                        </div>
                      );
                    })}
                  </div>
                </ScrollArea>
              </CardContent>
            </Card>
          )}

          {activities.length === 0 && !isLoadingActivity && (
            <Card className="glass-card">
              <CardContent className="p-6 text-center text-sm text-zinc-500">
                No activity recorded yet.
              </CardContent>
            </Card>
          )}
        </>
      )}

      {/* ==================== P8: Git Tab ==================== */}
      {activeTab === "git" && (
        <>
          <div className="flex items-center justify-between">
            <div>
              <h2 className="text-xl font-semibold">Git Workflow</h2>
              <p className="text-sm text-zinc-500">
                Branch:{" "}
                <Badge variant="outline">{gitStatus?.branch || "..."}</Badge>
                {gitStatus && (gitStatus.ahead > 0 || gitStatus.behind > 0) && (
                  <>
                    {gitStatus.ahead > 0 && (
                      <span className="ml-2 text-xs text-green-500">
                        ↑{gitStatus.ahead}
                      </span>
                    )}
                    {gitStatus.behind > 0 && (
                      <span className="ml-2 text-xs text-yellow-500">
                        ↓{gitStatus.behind}
                      </span>
                    )}
                  </>
                )}
              </p>
            </div>
            <div className="flex items-center gap-2">
              <Button
                size="sm"
                variant="outline"
                onClick={loadGitStatus}
                disabled={isLoadingGit}
              >
                {isLoadingGit ? (
                  <Activity size={14} className="animate-spin" />
                ) : (
                  <RefreshCw size={14} />
                )}
              </Button>
              <Button
                size="sm"
                onClick={handlePush}
                disabled={isPushing || !gitStatus?.staged?.length}
              >
                <Upload size={14} className="mr-1" />
                {isPushing ? "Pushing..." : "Push"}
              </Button>
            </div>
          </div>

          {isLoadingGit && (
            <Card className="glass-card border-blue-500/20">
              <CardContent className="p-6 text-center text-sm text-zinc-500">
                <Activity
                  size={18}
                  className="animate-spin text-blue-500 mx-auto mb-2"
                />
                Loading git status...
              </CardContent>
            </Card>
          )}

          {gitStatus && !isLoadingGit && (
            <>
              {/* Branch Switcher */}
              {gitBranches.length > 0 && (
                <Card className="glass-card">
                  <CardHeader>
                    <CardTitle className="text-sm flex items-center gap-2">
                      <GitBranch size={16} /> Switch Branch
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="px-4 pb-4">
                    <select
                      className="w-full border border-border rounded-md bg-background text-sm px-3 py-2"
                      value={gitStatus.branch}
                      onChange={(e) => handleBranchSwitch(e.target.value)}
                    >
                      {gitBranches.map((b) => (
                        <option key={b.name} value={b.name}>
                          {b.name} {b.current ? "(current)" : ""}
                        </option>
                      ))}
                    </select>
                  </CardContent>
                </Card>
              )}

              {/* Staging Area */}
              {(gitStatus.unstaged.length > 0 ||
                gitStatus.untracked.length > 0) && (
                <Card className="glass-card">
                  <CardHeader>
                    <CardTitle className="text-sm flex items-center gap-2">
                      <FileSearch size={16} /> Unstaged Changes (
                      {gitStatus.unstaged.length + gitStatus.untracked.length})
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="px-0 pb-4">
                    <ScrollArea className="h-[200px]">
                      <div className="px-4 space-y-2">
                        {[...gitStatus.unstaged, ...gitStatus.untracked].map(
                          (file) => (
                            <div
                              key={file.path}
                              className="flex items-center gap-2 p-2 border border-border/40 rounded hover:bg-muted/30"
                            >
                              <input
                                type="checkbox"
                                className="cursor-pointer"
                                checked={selectedFiles.has(file.path)}
                                onChange={(e) => {
                                  const updated = new Set(selectedFiles);
                                  if (e.target.checked) {
                                    updated.add(file.path);
                                  } else {
                                    updated.delete(file.path);
                                  }
                                  setSelectedFiles(updated);
                                }}
                              />
                              <Badge
                                variant={
                                  file.status === "M" ? "default" : "secondary"
                                }
                                className="text-[10px]"
                              >
                                {file.status}
                              </Badge>
                              <span className="text-xs font-mono flex-1 truncate">
                                {file.path}
                              </span>
                            </div>
                          ),
                        )}
                      </div>
                    </ScrollArea>
                    <div className="px-4 mt-3">
                      <Button
                        size="sm"
                        onClick={() =>
                          handleStageFiles(Array.from(selectedFiles))
                        }
                        disabled={selectedFiles.size === 0}
                        className="w-full"
                      >
                        <Plus size={14} className="mr-1" />
                        Stage Selected ({selectedFiles.size})
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              )}

              {/* Staged Files */}
              {gitStatus.staged.length > 0 && (
                <Card className="glass-card border-green-500/20">
                  <CardHeader>
                    <CardTitle className="text-sm flex items-center gap-2">
                      <CheckCircle2 size={16} className="text-green-500" />{" "}
                      Staged Changes ({gitStatus.staged.length})
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="px-0 pb-4">
                    <ScrollArea className="h-[200px]">
                      <div className="px-4 space-y-2">
                        {gitStatus.staged.map((file) => (
                          <div
                            key={file.path}
                            className="flex items-center gap-2 p-2 bg-green-500/5 border border-green-500/20 rounded"
                          >
                            <Badge
                              variant="default"
                              className="text-[10px] bg-green-500"
                            >
                              {file.status}
                            </Badge>
                            <span className="text-xs font-mono flex-1 truncate">
                              {file.path}
                            </span>
                            <Button
                              size="sm"
                              variant="ghost"
                              onClick={() => handleUnstageFiles([file.path])}
                              className="h-6 w-6 p-0"
                            >
                              <X size={12} />
                            </Button>
                          </div>
                        ))}
                      </div>
                    </ScrollArea>
                  </CardContent>
                </Card>
              )}

              {/* Commit Form */}
              {gitStatus.staged.length > 0 && (
                <Card className="glass-card border-blue-500/20">
                  <CardHeader>
                    <CardTitle className="text-sm flex items-center gap-2">
                      <GitCommit size={16} /> Commit Changes
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="space-y-3">
                    <textarea
                      className="w-full border border-border rounded-md bg-background text-sm px-3 py-2 min-h-[80px]"
                      placeholder="Commit message..."
                      value={commitMessage}
                      onChange={(e) => setCommitMessage(e.target.value)}
                    />
                    <Button
                      onClick={handleCommit}
                      disabled={isCommitting || !commitMessage.trim()}
                      className="w-full"
                    >
                      <GitCommit size={14} className="mr-1" />
                      {isCommitting
                        ? "Committing..."
                        : `Commit ${gitStatus.staged.length} file(s)`}
                    </Button>
                  </CardContent>
                </Card>
              )}

              {/* Empty State */}
              {gitStatus.staged.length === 0 &&
                gitStatus.unstaged.length === 0 &&
                gitStatus.untracked.length === 0 && (
                  <Card className="glass-card">
                    <CardContent className="p-6 text-center text-sm text-zinc-500">
                      <CheckCircle2
                        size={32}
                        className="text-green-500 mx-auto mb-2"
                      />
                      <p>Working tree clean</p>
                      <p className="text-xs mt-1">No changes to commit</p>
                    </CardContent>
                  </Card>
                )}
            </>
          )}
        </>
      )}
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import {
    Users,
    FileText,
    Upload,
    CheckCircle2,
    XCircle,
    Loader2,
    Search,
    Mail,
    UserCheck,
    BarChart3,
    History,
    ExternalLink
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Input } from '../ui/input';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useBusinessStore } from '../../lib/businessStore';
import { format } from 'date-fns';

export function DigitalHRWidget() {
    const [jobDescription, setJobDescription] = useState('');
    const { jobs, isLoading, fetchJobs, createJob } = useBusinessStore();
    const { socket } = useSocket();
    const [selectedJobId, setSelectedJobId] = useState<string | null>(null);

    const hrJobs = useMemo(() => jobs.filter(j => j.type === 'digital_hr'), [jobs]);

    useEffect(() => {
        fetchJobs('digital_hr');
    }, [fetchJobs]);

    useEffect(() => {
        if (!socket) return;

        const handleJobUpdate = (data: { jobId: string, status: string }) => {
            fetchJobs('digital_hr');
            if (data.status === 'completed') {
                toast.success("Önéletrajz elemzése sikeresen befejeződött!");
            }
        };

        socket.on('business_job:updated', handleJobUpdate);
        return () => {
            socket.off('business_job:updated', handleJobUpdate);
        };
    }, [socket, fetchJobs]);

    const handleStartScreening = async () => {
        if (!jobDescription.trim()) {
            toast.error("Kérlek add meg a munkaköri leírást!");
            return;
        }

        const jobId = await createJob('digital_hr', jobDescription);
        if (jobId) {
            toast.info("HR szűrés elindítva... PDF parsolása Vision MI-vel.");
            setJobDescription('');
        }
    };

    const activeJob = jobs.find(j => j.id === selectedJobId) || hrJobs[0];
    const candidate = activeJob?.results_json ? JSON.parse(activeJob.results_json) : null;

    return (
        <Card className="w-full shadow-xl border-blue-500/20 bg-card/50 backdrop-blur-md">
            <CardHeader className="pb-3 border-b border-white/[0.04]">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-500/10 rounded-full">
                            <Users className="w-5 h-5 text-blue-500" />
                        </div>
                        <div>
                            <CardTitle>Digital HR & CV Screening</CardTitle>
                            <CardDescription>Vision OCR alapú jelölt szűrés és MI pontozás</CardDescription>
                        </div>
                    </div>
                </div>
            </CardHeader>
            <CardContent className="pt-6">
                <div className="flex flex-col gap-4 mb-8">
                    <div className="flex gap-2">
                        <Input
                            placeholder="Milyen pozícióra keresünk? (pl. Senior React Fejlesztő)"
                            value={jobDescription}
                            onChange={(e) => setJobDescription(e.target.value)}
                            className="bg-secondary/20 border-blue-500/10 h-12"
                        />
                        <Button
                            onClick={handleStartScreening}
                            disabled={isLoading}
                            className="bg-blue-600 hover:bg-blue-700 min-w-[160px] h-12 text-white font-bold"
                        >
                            {isLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Search className="w-4 h-4 mr-2" />}
                            Szűrés Indítása
                        </Button>
                    </div>
                    <div className="flex items-center gap-2 text-[10px] text-zinc-500 italic">
                        <Upload size={12} />
                        Tipp: Másold be a munkaköri leírást, Brunella pedig átnézi a beérkezett PDF-eket.
                    </div>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Előzmények */}
                    <div className="lg:col-span-1 border-r border-white/[0.04] pr-4">
                        <h3 className="text-xs font-semibold uppercase text-zinc-500 mb-3 flex items-center gap-2">
                            <History className="w-3 h-3" />
                            Korábbi Jelöltek
                        </h3>
                        <ScrollArea className="h-[400px]">
                            <div className="space-y-2">
                                {hrJobs.length === 0 ? (
                                    <p className="text-xs text-zinc-500 italic">Nincsenek korábbi szűrések.</p>
                                ) : (
                                    hrJobs.map((job) => {
                                        const res = job.results_json ? JSON.parse(job.results_json) : {};
                                        return (
                                            <div
                                                key={job.id}
                                                onClick={() => setSelectedJobId(job.id)}
                                                className={`p-3 rounded-lg border cursor-pointer transition-all ${selectedJobId === job.id || (!selectedJobId && hrJobs[0].id === job.id)
                                                        ? 'bg-blue-500/10 border-blue-500/30'
                                                        : 'bg-secondary/5 border-transparent hover:border-blue-500/20'
                                                    }`}
                                            >
                                                <div className="flex justify-between items-start mb-1">
                                                    <span className="font-bold text-xs truncate">{res.name || job.query}</span>
                                                    {res.matchScore && (
                                                        <Badge className={res.matchScore >= 80 ? "bg-green-500/20 text-green-500" : "bg-yellow-500/20 text-yellow-500"}>
                                                            {res.matchScore}%
                                                        </Badge>
                                                    )}
                                                </div>
                                                <div className="text-[9px] text-zinc-500">
                                                    {format(new Date(job.created_at), 'yyyy.MM.dd HH:mm')}
                                                </div>
                                            </div>
                                        );
                                    })
                                )}
                            </div>
                        </ScrollArea>
                    </div>

                    {/* Részletek */}
                    <div className="lg:col-span-2">
                        {activeJob ? (
                            <div className="space-y-6">
                                {activeJob.status === 'running' ? (
                                    <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500">
                                        <Loader2 className="w-10 h-10 mb-4 animate-spin text-blue-500" />
                                        <p className="animate-pulse">CV elemzése Vision MI-vel...</p>
                                    </div>
                                ) : candidate ? (
                                    <div className="space-y-6 animate-in fade-in slide-in-from-right-4 duration-500">
                                        <div className="flex justify-between items-start">
                                            <div>
                                                <h3 className="text-2xl font-black text-white">{candidate.name}</h3>
                                                <p className="text-sm text-blue-400 font-mono">{candidate.contact}</p>
                                            </div>
                                            <div className="text-right">
                                                <div className="text-[10px] text-zinc-500 uppercase font-bold tracking-tighter mb-1">Match Score</div>
                                                <div className={`text-4xl font-black ${candidate.matchScore >= 80 ? 'text-green-500' : 'text-yellow-500'}`}>
                                                    {candidate.matchScore}%
                                                </div>
                                            </div>
                                        </div>

                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="p-4 rounded-xl bg-white/[0.04] border border-white/[0.04]">
                                                <div className="text-[10px] font-bold text-zinc-500 uppercase mb-2 flex items-center gap-2">
                                                    <BarChart3 size={12} /> Tapasztalat
                                                </div>
                                                <div className="text-lg font-bold text-white">{candidate.experience} év</div>
                                            </div>
                                            <div className="p-4 rounded-xl bg-white/[0.04] border border-white/[0.04]">
                                                <div className="text-[10px] font-bold text-zinc-500 uppercase mb-2 flex items-center gap-2">
                                                    <UserCheck size={12} /> Státusz
                                                </div>
                                                <Badge className={candidate.status === 'priority' ? "bg-red-500 text-white" : "bg-blue-500 text-white"}>
                                                    {candidate.status === 'priority' ? 'KIEMELT JELÖLT' : 'INTERJÚRA AJÁNLOTT'}
                                                </Badge>
                                            </div>
                                        </div>

                                        <div className="space-y-2">
                                            <div className="text-[10px] font-bold text-zinc-500 uppercase">Képességek</div>
                                            <div className="flex flex-wrap gap-2">
                                                {candidate.skills?.split(',').map((s: string, i: number) => (
                                                    <Badge key={i} variant="outline" className="border-blue-500/20 bg-blue-500/5 text-blue-200">
                                                        {s.trim()}
                                                    </Badge>
                                                ))}
                                            </div>
                                        </div>

                                        <div className="flex gap-2 pt-4 border-t border-white/[0.04]">
                                            <Button size="sm" className="flex-1 gap-2"
                                                onClick={() => toast.info("Email küldés hamarosan elérhető")}>
                                                <Mail size={14} /> Email küldése
                                            </Button>
                                            <Button size="sm" variant="outline" className="flex-1 gap-2"
                                                onClick={() => toast.info("Interjú ütemezés hamarosan elérhető")}>
                                                <History size={14} /> Interjú ütemezése
                                            </Button>
                                        </div>
                                    </div>
                                ) : null}
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500 opacity-40">
                                <UserCheck className="w-16 h-16 mb-4" />
                                <p>Válassz ki egy jelöltet az elemzéshez.</p>
                            </div>
                        )}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@radix-ui/themes';

/**
 * EnterpriseModulePanel
 * Dashboard component for managing and monitoring all 14 enterprise modules
 * 
 * Features:
 * - List all modules by category
 * - Execute tasks via the orchestrator
 * - Monitor module health
 * - View execution history
 */

interface Module {
  name: string;
  category: string;
  keywords: string[];
  priority: number;
}

interface ExecutionResult {
  taskId: string;
  targetModules: string[];
  status: string;
  executedAt: string;
  totalExecutionTime: number;
}

export const EnterpriseModulePanel: React.FC = () => {
  const [modules, setModules] = useState<Module[]>([]);
  const [selectedCategory, setSelectedCategory] = useState<string>('all');
  const [loading, setLoading] = useState(false);
  const [taskInput, setTaskInput] = useState('');
  const [executionHistory, setExecutionHistory] = useState<ExecutionResult[]>([]);
  const [stats, setStats] = useState({ totalModules: 0, byCategory: {} });

  // Load modules on mount
  useEffect(() => {
    loadModules();
    loadStats();
  }, []);

  /**
   * Load all enterprise modules
   */
  const loadModules = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/enterprise/modules');
      const data = await response.json();
      
      if (data.status === 'success') {
        setModules(data.modules);
      }
    } catch (error) {
      console.error('Failed to load modules:', error);
    } finally {
      setLoading(false);
    }
  };

  /**
   * Load module statistics
   */
  const loadStats = async () => {
    try {
      const response = await fetch('/api/enterprise/stats');
      const data = await response.json();
      
      if (data.status === 'success') {
        setStats(data.stats);
      }
    } catch (error) {
      console.error('Failed to load stats:', error);
    }
  };

  /**
   * Get modules filtered by category
   */
  const getFilteredModules = () => {
    if (selectedCategory === 'all') {
      return modules;
    }
    return modules.filter((m) => m.category === selectedCategory);
  };

  /**
   * Execute a task against the enterprise suite
   */
  const executeTask = async () => {
    if (!taskInput.trim()) {
      alert('Please enter a task description');
      return;
    }

    try {
      setLoading(true);
      const response = await fetch('/api/enterprise/execute', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          task: taskInput,
          priority: 'medium'
        })
      });

      const data = await response.json();
      
      if (data.status === 'success') {
        setExecutionHistory([data.result, ...executionHistory]);
        setTaskInput('');
        alert('Task executed successfully!');
      } else {
        alert('Task execution failed: ' + data.error);
      }
    } catch (error) {
      console.error('Failed to execute task:', error);
      alert('Failed to execute task');
    } finally {
      setLoading(false);
    }
  };

  const categories = ['all', 'sales', 'finance', 'hr', 'logistics'];
  const filteredModules = getFilteredModules();

  return (
    <div className="w-full space-y-6 p-4">
      {/* Header */}
      <div className="space-y-2">
        <h1 className="text-3xl font-bold">Enterprise Suite Master</h1>
        <p className="text-gray-600">
          Manage and monitor all {stats.totalModules} enterprise modules
        </p>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <Card>
          <CardHeader>
            <CardTitle>Total Modules</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-4xl font-bold">{stats.totalModules}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Sales</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-4xl font-bold">{stats.byCategory?.sales || 0}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Finance</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-4xl font-bold">{stats.byCategory?.finance || 0}</div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>HR & Logistics</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="text-4xl font-bold">
              {(stats.byCategory?.hr || 0) + (stats.byCategory?.logistics || 0)}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Task Executor */}
      <Card>
        <CardHeader>
          <CardTitle>Execute Enterprise Task</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <textarea
            value={taskInput}
            onChange={(e) => setTaskInput(e.target.value)}
            placeholder="Describe your task (e.g., 'Generate sales leads in tech industry')"
            className="w-full p-3 border border-gray-300 rounded text-sm"
            rows={4}
          />
          <button
            onClick={executeTask}
            disabled={loading}
            className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 disabled:opacity-50"
          >
            {loading ? 'Processing...' : 'Execute'}
          </button>
        </CardContent>
      </Card>

      {/* Module Browser */}
      <Card>
        <CardHeader>
          <CardTitle>Module Browser</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {/* Category Filter */}
          <div className="flex gap-2 flex-wrap">
            {categories.map((cat) => (
              <button
                key={cat}
                onClick={() => setSelectedCategory(cat)}
                className={`px-3 py-1 rounded text-sm ${
                  selectedCategory === cat
                    ? 'bg-blue-600 text-white'
                    : 'bg-gray-200 text-gray-700 hover:bg-gray-300'
                }`}
              >
                {cat.charAt(0).toUpperCase() + cat.slice(1)}
              </button>
            ))}
          </div>

          {/* Modules List */}
          {loading ? (
            <div className="text-center py-8">Loading modules...</div>
          ) : filteredModules.length === 0 ? (
            <div className="text-center py-8 text-gray-600">
              No modules found in this category
            </div>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {filteredModules.map((module) => (
                <div
                  key={module.name}
                  className="p-4 border border-gray-200 rounded bg-gray-50"
                >
                  <h3 className="font-bold text-sm">{module.name}</h3>
                  <p className="text-xs text-gray-600 mt-1">
                    Category: <span className="font-mono">{module.category}</span>
                  </p>
                  <p className="text-xs text-gray-600 mt-1">
                    Priority: <span className="font-bold">{module.priority}</span>
                  </p>
                  <div className="mt-3 flex flex-wrap gap-1">
                    {module.keywords.slice(0, 3).map((kw) => (
                      <span key={kw} className="text-xs bg-blue-100 text-blue-700 px-2 py-1 rounded">
                        {kw}
                      </span>
                    ))}
                    {module.keywords.length > 3 && (
                      <span className="text-xs text-gray-500">+{module.keywords.length - 3}</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      {/* Execution History */}
      {executionHistory.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Recent Executions</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-3">
              {executionHistory.slice(0, 5).map((exec) => (
                <div key={exec.taskId} className="p-3 border-l-4 border-green-500 bg-green-50">
                  <p className="text-sm font-mono">{exec.taskId}</p>
                  <p className="text-xs text-gray-600 mt-1">
                    Modules: {exec.targetModules.join(', ')}
                  </p>
                  <p className="text-xs text-gray-600">
                    Time: {exec.totalExecutionTime}ms | {exec.executedAt}
                  </p>
                </div>
              ))}
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
};

export default EnterpriseModulePanel;

import { useState, useEffect } from 'react'
import { Folder, File, ArrowLeft, RefreshCw, Eye, Download, Info } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import { listFiles, getFileContent, type FileInfo } from '@/lib/apiService'
import { toast } from 'sonner'
import { Skeleton } from '@/components/ui/skeleton'

export function FileExplorer() {
    const [currentPath, setCurrentPath] = useState('.')
    const [files, setFiles] = useState<FileInfo[]>([])
    const [loading, setLoading] = useState(true)
    const [previewContent, setPreviewContent] = useState<string | null>(null)
    const [previewFile, setPreviewFile] = useState<FileInfo | null>(null)

    const fetchFiles = async (path: string) => {
        setLoading(true)
        try {
            const data = await listFiles(path)
            // Folders first, then files
            setFiles(data.sort((a, b) => {
                if (a.isDirectory && !b.isDirectory) return -1
                if (!a.isDirectory && b.isDirectory) return 1
                return a.name.localeCompare(b.name)
            }))
            setCurrentPath(path)
        } catch (e) {
            toast.error('Hiba a fájlok listázásakor')
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        fetchFiles('.')
    }, [])

    const handleFolderClick = (path: string) => {
        fetchFiles(path)
    }

    const handleBack = () => {
        const parts = currentPath.split('/')
        if (parts.length > 1) {
            parts.pop()
            fetchFiles(parts.join('/') || '.')
        } else if (currentPath !== '.') {
            fetchFiles('.')
        }
    }

    const handlePreview = async (file: FileInfo) => {
        try {
            setLoading(true)
            const content = await getFileContent(file.path)
            setPreviewContent(content)
            setPreviewFile(file)
        } catch (e) {
            toast.error('Hiba a fájl beolvasásakor')
        } finally {
            setLoading(false)
        }
    }

    const formatSize = (bytes: number) => {
        if (bytes === 0) return '-'
        const k = 1024
        const sizes = ['B', 'KB', 'MB', 'GB']
        const i = Math.floor(Math.log(bytes) / Math.log(k))
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i]
    }

    return (
        <div className="space-y-4 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <Button variant="ghost" size="icon" onClick={handleBack} disabled={currentPath === '.'}>
                        <ArrowLeft size={18} />
                    </Button>
                    <div className="flex flex-col">
                        <h2 className="text-xl font-bold tracking-tight">Fájlrendszer</h2>
                        <p className="text-xs font-mono text-zinc-500">{currentPath}</p>
                    </div>
                </div>
                <Button variant="outline" size="sm" onClick={() => fetchFiles(currentPath)} disabled={loading}>
                    <RefreshCw size={14} className={loading ? "animate-spin mr-2" : "mr-2"} />
                    Frissítés
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-[1fr_350px] gap-6">
                <Card className="glass-card overflow-hidden">
                    <CardHeader className="pb-3 border-b border-border/50">
                        <CardTitle className="text-sm font-medium flex items-center gap-2">
                            <Folder size={16} className="text-primary" />
                            Tartalom
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="p-0">
                        <ScrollArea className="h-[600px]">
                            <div className="divide-y divide-border/50">
                                {loading && files.length === 0 ? (
                                    Array.from({ length: 8 }).map((_, i) => (
                                        <div key={i} className="flex items-center gap-4 px-4 py-3">
                                            <Skeleton className="h-4 w-4" />
                                            <Skeleton className="h-4 flex-1" />
                                            <Skeleton className="h-4 w-16" />
                                        </div>
                                    ))
                                ) : (
                                    files.map((file) => (
                                        <div
                                            key={file.path}
                                            className="group flex items-center justify-between px-4 py-3 hover:bg-muted/50 transition-colors cursor-pointer"
                                            onClick={() => file.isDirectory ? handleFolderClick(file.path) : handlePreview(file)}
                                        >
                                            <div className="flex items-center gap-3 overflow-hidden">
                                                {file.isDirectory ? (
                                                    <Folder size={18} className="text-blue-400 shrink-0" />
                                                ) : (
                                                    <File size={18} className="text-zinc-500 shrink-0" />
                                                )}
                                                <span className="text-sm font-mono truncate group-hover:text-primary transition-colors">
                                                    {file.name}
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-4 text-xs font-mono text-zinc-500">
                                                <span>{formatSize(file.size)}</span>
                                                {!file.isDirectory && (
                                                    <Button variant="ghost" size="icon" className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity">
                                                        <Eye size={12} />
                                                    </Button>
                                                )}
                                            </div>
                                        </div>
                                    ))
                                )}
                                {!loading && files.length === 0 && (
                                    <div className="p-8 text-center text-zinc-500 italic">
                                        Ez a mappa üres
                                    </div>
                                )}
                            </div>
                        </ScrollArea>
                    </CardContent>
                </Card>

                <Card className="glass-card h-fit sticky top-20">
                    <CardHeader className="pb-3 border-b border-border/50">
                        <CardTitle className="text-sm font-medium flex items-center gap-2">
                            <Info size={16} className="text-primary" />
                            Részletek / Előnézet
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="p-4">
                        {previewFile ? (
                            <div className="space-y-4">
                                <div className="space-y-1">
                                    <h3 className="font-bold text-sm truncate">{previewFile.name}</h3>
                                    <p className="text-[10px] font-mono text-zinc-500 break-all">{previewFile.path}</p>
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                    <div className="bg-muted/50 rounded p-2 border border-border/50">
                                        <span className="text-[9px] uppercase text-zinc-500 block">Mérete</span>
                                        <span className="text-xs font-mono">{formatSize(previewFile.size)}</span>
                                    </div>
                                    <div className="bg-muted/50 rounded p-2 border border-border/50">
                                        <span className="text-[9px] uppercase text-zinc-500 block">Módosítva</span>
                                        <span className="text-xs font-mono">{new Date(previewFile.modified).toLocaleDateString()}</span>
                                    </div>
                                </div>

                                <div className="pt-2">
                                    <span className="text-[10px] uppercase font-bold text-zinc-500 mb-1 block">Tartalom:</span>
                                    <div className="bg-muted/30 rounded-lg p-3 border border-border/50 max-h-[300px] overflow-auto">
                                        <pre className="text-[10px] font-mono whitespace-pre-wrap text-foreground/80">
                                            {previewContent || "Nincs megjeleníthető tartalom"}
                                        </pre>
                                    </div>
                                </div>

                                <Button className="w-full" size="sm" variant="outline" onClick={() => {
                                    if (previewFile) {
                                        const blob = new Blob([previewContent || ''], { type: 'text/plain' });
                                        const url = URL.createObjectURL(blob);
                                        const a = document.createElement('a');
                                        a.href = url;
                                        a.download = previewFile.name || 'download.txt';
                                        a.click();
                                        URL.revokeObjectURL(url);
                                    }
                                }}>
                                    <Download size={14} className="mr-2" />
                                    Letöltés
                                </Button>
                            </div>
                        ) : (
                            <div className="p-8 text-center text-zinc-500 text-xs italic">
                                Válassz ki egy fájlt a részletek megtekintéséhez
                            </div>
                        )}
                    </CardContent>
                </Card>
            </div>
        </div>
    )
}

/**
 * Gold Protocol G7.10: Gold Status Widget
 *
 * Main dashboard összefoglaló widget — 6 pillér státusza
 */

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Badge } from '../ui/badge';
import {
  FileText,
  ArrowClockwise,
  Broadcast,
  Database,
  ChartLine,
  ShieldCheck,
} from '@phosphor-icons/react';

interface PillarStatus {
  id: string;
  name: string;
  icon: React.ReactNode;
  status: 'active' | 'idle' | 'warning';
  metric: string;
  link: string;
}

export function GoldStatusWidget() {
  const [pillars, setPillars] = useState<PillarStatus[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 20000); // Auto-refresh 20s
    return () => clearInterval(interval);
  }, []);

  const fetchStatus = async () => {
    try {
      // Párhuzamosan fetch minden pillar adatot
      const [specs, checkpoints, models, memory, telemetry, audit] = await Promise.all([
        fetch('/api/specs').then((r) => r.ok ? r.json() : {}),
        fetch('/api/phoenix/checkpoints').then((r) => r.ok ? r.json() : {}),
        fetch('/api/router/decisions').then((r) => r.ok ? r.json() : {}),
        fetch('/api/memory/stats').then((r) => r.ok ? r.json() : {}),
        fetch('/api/telemetry/stats').then((r) => r.ok ? r.json() : {}),
        fetch('/api/audit/stats').then((r) => r.ok ? r.json() : {}),
      ]);

      setPillars([
        {
          id: 'spec',
          name: 'Spec Management',
          icon: <FileText className="w-6 h-6" />,
          status: specs.specs?.some((t: { spec_status?: string }) => t.spec_status === 'pending_approval') ? 'warning' : 'active',
          metric: `${specs.specs?.filter((t: { spec_status?: string }) => t.spec_status === 'approved').length || 0} approved`,
          link: '/gold/specs',
        },
        {
          id: 'phoenix',
          name: 'Phoenix Protocol',
          icon: <ArrowClockwise className="w-6 h-6" />,
          status: checkpoints.checkpoints?.length > 0 ? 'active' : 'idle',
          metric: `${checkpoints.checkpoints?.length || 0} checkpoints`,
          link: '/gold/phoenix',
        },
        {
          id: 'router',
          name: 'Model Router',
          icon: <Broadcast className="w-6 h-6" />,
          status: 'active',
          metric: `${models.decisions?.length || 0} recent`,
          link: '/gold/router',
        },
        {
          id: 'memory',
          name: 'Cognitive Memory',
          icon: <Database className="w-6 h-6" />,
          status: 'active',
          metric: `${memory.golden?.count || 0} samples`,
          link: '/gold/memory',
        },
        {
          id: 'observability',
          name: 'Observability',
          icon: <ChartLine className="w-6 h-6" />,
          status: telemetry.totalSpans > 0 ? 'active' : 'idle',
          metric: `${telemetry.totalSpans || 0} traces`,
          link: '/gold/observability',
        },
        {
          id: 'audit',
          name: 'Audit',
          icon: <ShieldCheck className="w-6 h-6" />,
          status: audit.deniedCount > 0 ? 'warning' : 'active',
          metric: `${audit.deniedCount || 0} denied`,
          link: '/gold/audit',
        },
      ]);
      setLoading(false);
    } catch (e) {
      console.error('Failed to fetch Gold Protocol status:', e);
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Gold Protocol Status</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-gray-500">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center justify-between">
          <span>Gold Protocol Status</span>
          <Badge className="bg-yellow-500 text-black">🏆 ACTIVE</Badge>
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
          {pillars.map((pillar) => (
            <a
              key={pillar.id}
              href={pillar.link}
              className={`p-4 border rounded-lg cursor-pointer transition-all hover:shadow-lg ${
                pillar.status === 'active'
                  ? 'border-green-300 bg-green-50 dark:bg-green-900/10'
                  : pillar.status === 'warning'
                  ? 'border-orange-300 bg-orange-50 dark:bg-orange-900/10'
                  : 'border-gray-300 bg-gray-50 dark:bg-gray-900/10'
              }`}
            >
              <div className="flex items-center gap-2 mb-2">
                {pillar.icon}
                <Badge
                  className={
                    pillar.status === 'active'
                      ? 'bg-green-500'
                      : pillar.status === 'warning'
                      ? 'bg-orange-500'
                      : 'bg-gray-500'
                  }
                >
                  {pillar.status.toUpperCase()}
                </Badge>
              </div>
              <div className="text-sm font-semibold mb-1">{pillar.name}</div>
              <div className="text-xs text-gray-600">{pillar.metric}</div>
            </a>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import {
    FileText,
    Coins,
    Calendar,
    CheckCircle2,
    XCircle,
    Loader2,
    Search,
    ExternalLink,
    History,
    AlertCircle,
    ArrowUpRight
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Input } from '../ui/input';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useBusinessStore } from '../../lib/businessStore';
import { format } from 'date-fns';

export function GrantHunterWidget() {
    const [query, setQuery] = useState('');
    const { jobs, isLoading, fetchJobs, createJob } = useBusinessStore();
    const { socket } = useSocket();
    const [selectedJobId, setSelectedJobId] = useState<string | null>(null);

    const grantJobs = useMemo(() => jobs.filter(j => j.type === 'grant_hunter'), [jobs]);

    useEffect(() => {
        fetchJobs('grant_hunter');
    }, [fetchJobs]);

    useEffect(() => {
        if (!socket) return;

        const handleJobUpdate = (data: { jobId: string, status: string }) => {
            fetchJobs('grant_hunter');
            if (data.status === 'completed') {
                toast.success("Pályázatfigyelés sikeresen lefutott!");
            }
        };

        socket.on('business_job:updated', handleJobUpdate);
        return () => {
            socket.off('business_job:updated', handleJobUpdate);
        };
    }, [socket, fetchJobs]);

    const handleStartScan = async () => {
        const jobId = await createJob('grant_hunter', query || 'Aktuális KKV pályázatok');
        if (jobId) {
            toast.info("Pályázatok keresése folyamatban...");
            setQuery('');
        }
    };

    const activeJob = jobs.find(j => j.id === selectedJobId) || grantJobs[0];
    const grants = activeJob?.results_json ? JSON.parse(activeJob.results_json) : [];

    return (
        <Card className="w-full shadow-xl border-orange-500/20 bg-card/50 backdrop-blur-md">
            <CardHeader className="pb-3 border-b border-white/[0.04]">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-orange-500/10 rounded-full">
                            <FileText className="w-5 h-5 text-orange-500" />
                        </div>
                        <div>
                            <CardTitle>Grant Hunter</CardTitle>
                            <CardDescription>Automata pályázatfigyelő és előminősítő</CardDescription>
                        </div>
                    </div>
                </div>
            </CardHeader>
            <CardContent className="pt-6">
                <div className="flex gap-2 mb-8">
                    <Input
                        placeholder="Szűrés (pl. digitalizáció, napelem, TEÁOR kód)"
                        value={query}
                        onChange={(e) => setQuery(e.target.value)}
                        className="bg-secondary/20 border-orange-500/10 h-12"
                    />
                    <Button
                        onClick={handleStartScan}
                        disabled={isLoading}
                        className="bg-orange-600 hover:bg-orange-700 min-w-[160px] h-12 text-white font-bold"
                    >
                        {isLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Search className="w-4 h-4 mr-2" />}
                        Keresés
                    </Button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Előzmények */}
                    <div className="lg:col-span-1 border-r border-white/[0.04] pr-4 flex flex-col gap-4">
                        <h3 className="text-xs font-semibold uppercase text-zinc-500 flex items-center gap-2">
                            <History size={12} />
                            Előzmények
                        </h3>
                        <ScrollArea className="h-[400px]">
                            <div className="space-y-2">
                                {grantJobs.length === 0 ? (
                                    <p className="text-xs text-zinc-500 italic">Nincs korábbi adat.</p>
                                ) : (
                                    grantJobs.map((job) => (
                                        <div
                                            key={job.id}
                                            onClick={() => setSelectedJobId(job.id)}
                                            className={`p-3 rounded-lg border cursor-pointer transition-all ${selectedJobId === job.id || (!selectedJobId && grantJobs[0].id === job.id)
                                                    ? 'bg-orange-500/10 border-orange-500/30'
                                                    : 'bg-secondary/5 border-transparent hover:border-orange-500/20'
                                                }`}
                                        >
                                            <div className="font-bold text-xs truncate mb-1">{job.query}</div>
                                            <div className="flex justify-between items-center text-[9px] text-zinc-500 font-mono">
                                                {format(new Date(job.created_at), 'MM.dd HH:mm')}
                                                {job.status === 'completed' && <CheckCircle2 size={10} className="text-orange-500" />}
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </ScrollArea>
                    </div>

                    {/* Találatok */}
                    <div className="lg:col-span-2">
                        {activeJob ? (
                            <div className="space-y-4">
                                <h3 className="text-sm font-bold">Talált Pályázatok ({grants.length})</h3>
                                <ScrollArea className="h-[400px] pr-4">
                                    {activeJob.status === 'running' ? (
                                        <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500">
                                            <Loader2 className="w-10 h-10 mb-4 animate-spin text-orange-500" />
                                            <p className="animate-pulse text-xs">Pályázati portálok átvizsgálása...</p>
                                        </div>
                                    ) : (
                                        <div className="space-y-4">
                                            {grants.map((grant: any, i: number) => (
                                                <div
                                                    key={i}
                                                    className="p-4 rounded-xl border border-white/[0.04] bg-white/[0.04] hover:border-orange-500/30 transition-all group"
                                                >
                                                    <div className="flex justify-between items-start mb-3">
                                                        <h4 className="font-bold text-sm text-orange-100 leading-tight group-hover:text-orange-400 transition-colors">{grant.title}</h4>
                                                        <Badge variant={grant.eligible ? "default" : "outline"} className={grant.eligible ? "bg-green-600 text-white" : "text-zinc-500"}>
                                                            {grant.eligible ? 'RELEVÁNS' : 'NEM IGAZOLT'}
                                                        </Badge>
                                                    </div>

                                                    <div className="grid grid-cols-2 gap-4 mb-4">
                                                        <div className="flex items-center gap-2 text-xs text-zinc-400">
                                                            <Coins size={14} className="text-yellow-500" />
                                                            {grant.fundingAmount?.toLocaleString()} {grant.currency || 'HUF'}
                                                        </div>
                                                        <div className="flex items-center gap-2 text-xs text-zinc-400">
                                                            <Calendar size={14} className="text-blue-400" />
                                                            Határidő: {grant.deadline || 'N/A'}
                                                        </div>
                                                    </div>

                                                    <div className="flex justify-between items-center mt-2">
                                                        <div className="flex items-center gap-1 text-[10px] font-bold text-green-500">
                                                            <ArrowUpRight size={12} />
                                                            Match: {grant.score}%
                                                        </div>
                                                        <Button size="xs" variant="ghost" className="h-7 text-[10px] gap-1 opacity-0 group-hover:opacity-100 transition-opacity"
                                                            onClick={() => (grant as any).url ? window.open((grant as any).url, '_blank') : toast.info("Részletek nem elérhetők")}>
                                                            Részletek <ExternalLink size={10} />
                                                        </Button>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </ScrollArea>
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500 opacity-40">
                                <AlertCircle className="w-16 h-16 mb-4" />
                                <p>Nincsenek megjeleníthető adatok.</p>
                            </div>
                        )}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

import { useState, useEffect } from 'react';
import {
    Flask,
    Database,
    Cpu,
    ArrowRight,
    CheckCircle,
    Warning,
    Play,
    FileCode,
    Plus,
    ClockCounterClockwise
} from '@phosphor-icons/react';
import { Activity } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { Progress } from '@/components/ui/progress';
import { toast } from 'sonner';
import { addGoldSample, getIncubatorStats, trainModel, type DatasetStats } from '@/lib/apiService';

export function IncubatorPanel() {
    const [stats, setStats] = useState<DatasetStats | null>(null);
    const [loading, setLoading] = useState(true);
    const [activeTab, setActiveTab] = useState('overview');
    const [isTraining, setIsTraining] = useState(false);

    // Form state
    const [prompt, setPrompt] = useState('');
    const [completion, setCompletion] = useState('');
    const [isSaving, setIsSaving] = useState(false);

    const fetchStats = async () => {
        try {
            const data = await getIncubatorStats();
            setStats(data);
        } catch (error) {
            console.error('Failed to fetch stats:', error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchStats();
        const interval = setInterval(fetchStats, 10000);
        return () => clearInterval(interval);
    }, []);

    const handleSaveSample = async () => {
        if (!prompt || !completion) {
            toast.error('Minden mezőt ki kell tölteni!');
            return;
        }

        setIsSaving(true);
        try {
            await addGoldSample(prompt, completion, 'manual', 1.0);
            toast.success('„Arany Minta" sikeresen elmentve!');
            setPrompt('');
            setCompletion('');
            fetchStats();
        } catch (e: any) {
            toast.error('Hiba a mentés során: ' + e.message);
        } finally {
            setIsSaving(false);
        }
    };

    const handleStartTraining = async () => {
        if (!stats || stats.total_samples < 10) {
            toast.error('Legalább 10 minta szükséges a training indításához!');
            return;
        }

        setIsTraining(true);
        try {
            const result = await trainModel();
            if (result.success) {
                toast.success(result.message || 'Training elindítva! Ez eltarthat néhány percig...');
                if (result.task_id) {
                    toast.info(`Task ID: ${result.task_id}`);
                }
            } else {
                toast.error('Training indítás sikertelen');
            }
        } catch (e: any) {
            toast.error('Training hiba: ' + e.message);
        } finally {
            setIsTraining(false);
        }
    };

    return (
        <div className="space-y-6 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-3xl font-space font-bold text-foreground flex items-center gap-3">
                        <Flask className="text-primary" />
                        Green Lightning Incubator
                    </h2>
                    <p className="text-zinc-500 mt-1">
                        AI modellek finomhangolása és az „Arany Adatkészlet” (Golden Dataset) karbantartása.
                    </p>
                </div>
                <div className="flex gap-2">
                    <Button variant="outline" onClick={fetchStats} className="gap-2">
                        <ClockCounterClockwise /> Frissítés
                    </Button>
                    <Button
                        className="gap-2 bg-primary hover:bg-primary/80"
                        onClick={handleStartTraining}
                        disabled={isTraining || !stats || stats.total_samples < 10}
                    >
                        <Play weight="fill" /> {isTraining ? 'Training fut...' : 'Training indítása'}
                    </Button>
                </div>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                {/* Stats Cards */}
                <Card className="glass-card border-white/10">
                    <CardHeader className="pb-2">
                        <CardTitle className="text-xs font-mono uppercase text-zinc-500 flex items-center gap-2">
                            <Database size={16} className="text-cyan-400" />
                            Arany Adatkészlet
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="text-4xl font-space font-bold">
                            {loading ? '...' : stats?.total_samples || 0}
                        </div>
                        <p className="text-xs text-zinc-500 mt-1">Validált tanító minta összesen</p>
                    </CardContent>
                </Card>

                <Card className="glass-card border-white/10">
                    <CardHeader className="pb-2">
                        <CardTitle className="text-xs font-mono uppercase text-zinc-500 flex items-center gap-2">
                            <CheckCircle size={16} className="text-green-400" />
                            Átlagos Minőség
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="text-4xl font-space font-bold">
                            {loading ? '...' : `${((stats?.avg_quality || 0) * 100).toFixed(1)}%`}
                        </div>
                        <Progress value={(stats?.avg_quality || 0) * 100} className="h-1 mt-3" />
                    </CardContent>
                </Card>

                <Card className="glass-card border-white/10">
                    <CardHeader className="pb-2">
                        <CardTitle className="text-xs font-mono uppercase text-zinc-500 flex items-center gap-2">
                            <Cpu size={16} className="text-yellow-400" />
                            Hardware Status
                        </CardTitle>
                    </CardHeader>
                    <CardContent>
                        <div className="text-xl font-space font-bold text-green-500 flex items-center gap-2">
                            RTX 3060 Ready
                        </div>
                        <p className="text-[10px] text-zinc-500 mt-2 font-mono uppercase">
                            VRAM: 12GB Available | Unsloth: Aktív
                        </p>
                    </CardContent>
                </Card>
            </div>

            <Tabs value={activeTab} onValueChange={setActiveTab} className="w-full">
                <TabsList className="bg-muted/30 border border-white/10 p-1">
                    <TabsTrigger value="overview" className="gap-2">
                        <Activity size={16} /> Áttekintés
                    </TabsTrigger>
                    <TabsTrigger value="harvest" className="gap-2">
                        <Plus size={16} /> Minta Felvétel
                    </TabsTrigger>
                    <TabsTrigger value="config" className="gap-2">
                        <FileCode size={16} /> Modelfile
                    </TabsTrigger>
                </TabsList>

                <TabsContent value="overview" className="mt-6 space-y-6">
                    <Card className="glass-card">
                        <CardHeader>
                            <CardTitle>Tanítási Napló</CardTitle>
                            <CardDescription>A legutóbbi finomhangolási ciklusok eredményei.</CardDescription>
                        </CardHeader>
                        <CardContent>
                            <div className="flex flex-col items-center justify-center p-12 bg-white/[0.02] rounded-xl border border-dashed border-white/10">
                                <ClockCounterClockwise size={48} className="text-zinc-500 opacity-20 mb-4" />
                                <p className="text-zinc-500 italic">Még nem történt finomhangolás ezzel az „Arany Adatkészlettel”.</p>
                            </div>
                        </CardContent>
                    </Card>
                </TabsContent>

                <TabsContent value="harvest" className="mt-6">
                    <Card className="glass-card">
                        <CardHeader>
                            <CardTitle>Manuális Adatbevitel</CardTitle>
                            <CardDescription>
                                Adj hozzá egy sikeres interakciót az Arany Adatkészlethez. Ezeket later az Unsloth fogja feldolgozni.
                            </CardDescription>
                        </CardHeader>
                        <CardContent className="space-y-4">
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Prompt (Felhasználói kérés)</label>
                                <textarea
                                    className="w-full min-h-[100px] bg-white/[0.03] border border-white/10 rounded-lg p-3 text-sm font-mono focus:ring-1 focus:ring-primary outline-none"
                                    placeholder="Írd be a mintát..."
                                    value={prompt}
                                    onChange={(e) => setPrompt(e.target.value)}
                                />
                            </div>
                            <div className="space-y-2">
                                <label className="text-sm font-medium">Kívánt Válasz (AI válasz)</label>
                                <textarea
                                    className="w-full min-h-[150px] bg-white/[0.03] border border-white/10 rounded-lg p-3 text-sm font-mono focus:ring-1 focus:ring-primary outline-none"
                                    placeholder="Írd be a helyes AI választ..."
                                    value={completion}
                                    onChange={(e) => setCompletion(e.target.value)}
                                />
                            </div>
                            <Button
                                onClick={handleSaveSample}
                                disabled={isSaving || !prompt || !completion}
                                className="w-full gap-2"
                            >
                                <CheckCircle size={18} />
                                {isSaving ? 'Mentés...' : 'Mentés az Arany Adatkészletbe'}
                            </Button>
                        </CardContent>
                    </Card>
                </TabsContent>

                <TabsContent value="config" className="mt-6">
                    <Card className="glass-card">
                        <CardHeader>
                            <CardTitle>Ollama Modelfile Template</CardTitle>
                            <CardDescription>A tanítás után generált modell alapértelmezett konfigurációja.</CardDescription>
                        </CardHeader>
                        <CardContent>
                            <pre className="p-4 bg-black/60 rounded-lg overflow-x-auto text-xs font-mono text-cyan-400 border border-white/[0.04]">
                                {`FROM lora_output.gguf
TEMPLATE """{{ if .System }}<|im_start|>system
{{ .System }}<|im_end|>
{{ end }}{{ if .Prompt }}<|im_start|>user
{{ .Prompt }}<|im_end|>
{{ end }}<|im_start|>assistant
{{ .Response }}<|im_end|>"""
PARAMETER stop "<|im_start|>"
PARAMETER stop "<|im_end|>"`}
                            </pre>
                        </CardContent>
                    </Card>
                </TabsContent>
            </Tabs>
        </div>
    );
}

import React, { useState, useEffect } from 'react';
import { 
    Bridge, 
    Lightbulb, 
    Zap, 
    Search,
    History,
    CheckCircle2,
    XCircle,
    Loader2,
    BookOpen,
    ArrowRightLeft,
    Globe
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Input } from '../ui/input';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useBusinessStore } from '../../lib/businessStore';
import { format } from 'date-fns';

export function InnovationBridgeWidget() {
    const [problem, setProblem] = useState('');
    const { jobs, isLoading, fetchJobs, createJob } = useBusinessStore();
    const { socket } = useSocket();
    const [selectedJobId, setSelectedJobId] = useState<string | null>(null);

    useEffect(() => {
        fetchJobs('innovation_bridge');
    }, [fetchJobs]);

    useEffect(() => {
        if (!socket) return;

        const handleJobUpdate = (data: { jobId: string, status: string }) => {
            fetchJobs('innovation_bridge');
            if (data.status === 'completed') {
                toast.success("Innovációs kutatás sikeresen befejeződött!");
            } else if (data.status === 'failed') {
                toast.error("Innovációs kutatás sikertelen.");
            }
        };

        socket.on('business_job:updated', handleJobUpdate);
        return () => {
            socket.off('business_job:updated', handleJobUpdate);
        };
    }, [socket, fetchJobs]);

    const handleStartInnovation = async () => {
        if (!problem.trim()) {
            toast.error("Kérlek írd le a technikai problémát!");
            return;
        }
        
        const jobId = await createJob('innovation_bridge', problem);
        if (jobId) {
            toast.info("TRIZ elemzés és kutatás elindítva...");
            setProblem('');
        }
    };

    const activeJob = jobs.find(j => j.id === selectedJobId) || jobs[0];
    const results = activeJob?.results_json ? JSON.parse(activeJob.results_json) : null;

    return (
        <Card className="w-full shadow-xl border-primary/20 bg-card/50 backdrop-blur-md">
            <CardHeader className="pb-3">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-primary/10 rounded-full">
                            <ArrowRightLeft className="w-5 h-5 text-primary" />
                        </div>
                        <div>
                            <CardTitle>Innovation Bridge</CardTitle>
                            <CardDescription>TRIZ-alapú kereszt-iparági megoldáskereső</CardDescription>
                        </div>
                    </div>
                </div>
            </CardHeader>
            <CardContent>
                <div className="flex gap-2 mb-6">
                    <Input 
                        placeholder="Pl: Hogyan hűtsünk szoftveresen egy túlmelegedő szervert?" 
                        value={problem}
                        onChange={(e) => setProblem(e.target.value)}
                        className="bg-secondary/20 border-primary/10"
                        onKeyPress={(e) => e.key === 'Enter' && handleStartInnovation()}
                    />
                    <Button 
                        onClick={handleStartInnovation} 
                        disabled={isLoading}
                        className="bg-primary hover:bg-primary/90 min-w-[140px]"
                    >
                        {isLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Lightbulb className="w-4 h-4 mr-2" />}
                        Innováció
                    </Button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Előzmények */}
                    <div className="lg:col-span-1 border-r border-primary/10 pr-4">
                        <h3 className="text-xs font-semibold uppercase text-zinc-500 mb-3 flex items-center gap-2">
                            <History className="w-3 h-3" />
                            Korábbi lekérdezések
                        </h3>
                        <ScrollArea className="h-[400px]">
                            <div className="space-y-2">
                                {jobs.filter(j => j.type === 'innovation_bridge').length === 0 ? (
                                    <p className="text-xs text-zinc-500 italic">Nincsenek korábbi futások.</p>
                                ) : (
                                    jobs.filter(j => j.type === 'innovation_bridge').map((job) => (
                                        <div 
                                            key={job.id}
                                            onClick={() => setSelectedJobId(job.id)}
                                            className={`p-3 rounded-lg border cursor-pointer transition-all ${
                                                selectedJobId === job.id || (!selectedJobId && jobs[0].id === job.id)
                                                    ? 'bg-primary/10 border-primary/30' 
                                                    : 'bg-secondary/5 border-transparent hover:border-primary/20'
                                            }`}
                                        >
                                            <div className="flex justify-between items-start mb-1">
                                                <span className="font-bold text-xs truncate max-w-[120px]">{job.query}</span>
                                                {job.status === 'completed' ? (
                                                    <CheckCircle2 className="w-3 h-3 text-green-500" />
                                                ) : job.status === 'failed' ? (
                                                    <XCircle className="w-3 h-3 text-red-500" />
                                                ) : (
                                                    <Loader2 className="w-3 h-3 text-blue-500 animate-spin" />
                                                )}
                                            </div>
                                            <div className="text-[10px] text-zinc-500">
                                                {format(new Date(job.created_at), 'MMM d. HH:mm')}
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </ScrollArea>
                    </div>

                    {/* Analógia riport */}
                    <div className="lg:col-span-2">
                        {activeJob && activeJob.type === 'innovation_bridge' ? (
                            <div className="space-y-4">
                                <div className="flex justify-between items-center">
                                    <h3 className="text-sm font-bold flex items-center gap-2">
                                        Elemzés: {activeJob.query}
                                    </h3>
                                    <Badge variant="outline" className="text-[10px] uppercase">{activeJob.status}</Badge>
                                </div>

                                <ScrollArea className="h-[360px] pr-4">
                                    {activeJob.status === 'running' ? (
                                        <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500">
                                            <Loader2 className="w-10 h-10 mb-4 animate-spin text-primary" />
                                            <p className="animate-pulse text-center px-4">A TRIZ motor elemzi az ellentmondásokat és kutatja a távoli iparágak analógiáit...</p>
                                        </div>
                                    ) : !results ? (
                                        <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500">
                                            <ArrowRightLeft className="w-10 h-10 mb-4 opacity-20" />
                                            <p>Nincsenek megjeleníthető adatok.</p>
                                        </div>
                                    ) : (
                                        <div className="space-y-6">
                                            {/* TRIZ Ellentmondás */}
                                            {results.trizAnalysis && (
                                                <div className="p-4 rounded-lg bg-primary/5 border border-primary/20">
                                                    <h4 className="text-xs font-bold uppercase text-primary mb-2 flex items-center gap-2">
                                                        <Zap className="w-3 h-3" /> Technikai Ellentmondás
                                                    </h4>
                                                    <div className="flex items-center gap-4 text-sm font-medium">
                                                        <span className="text-green-500">↑ {results.trizAnalysis.improvedParam}</span>
                                                        <span className="text-zinc-500">vs</span>
                                                        <span className="text-red-500">↓ {results.trizAnalysis.worsenedParam}</span>
                                                    </div>
                                                    <p className="mt-2 text-xs text-zinc-500 italic">"{results.trizAnalysis.reasoning}"</p>
                                                </div>
                                            )}

                                            {/* Alapelvek */}
                                            <div className="space-y-3">
                                                <h4 className="text-xs font-bold uppercase text-zinc-500 flex items-center gap-2">
                                                    <BookOpen className="w-3 h-3" /> Javasolt Alapelvek
                                                </h4>
                                                {results.suggestedPrinciples?.map((p: any, i: number) => (
                                                    <div key={i} className="p-3 rounded border border-primary/10 bg-secondary/5">
                                                        <div className="font-bold text-xs mb-1">{p.id}. {p.name}</div>
                                                        <p className="text-xs text-zinc-500">{p.description}</p>
                                                    </div>
                                                ))}
                                            </div>

                                            {/* Kutatási Találatok */}
                                            <div className="space-y-3">
                                                <h4 className="text-xs font-bold uppercase text-zinc-500 flex items-center gap-2">
                                                    <Globe className="w-3 h-3" /> Kereszt-iparági Analógiák
                                                </h4>
                                                {results.swarmResults?.map((r: any, i: number) => (
                                                    <div key={i} className="p-4 rounded-lg border border-primary/10 bg-card/30">
                                                        <div className="text-xs leading-relaxed whitespace-pre-wrap">
                                                            {typeof r === 'string' ? r : r.message}
                                                        </div>
                                                    </div>
                                                ))}
                                            </div>
                                        </div>
                                    )}
                                </ScrollArea>
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500 opacity-40">
                                <Search className="w-16 h-16 mb-4" />
                                <p>Válassz ki egy korábbi elemzést vagy írj be egy technikai problémát!</p>
                            </div>
                        )}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

/**
 * Agent & Tool Catalog - Mission Control 2.0
 * Bento Grid: Agents + Tools, Test Run modal
 * Adatforrás: GET /api/agents, GET /api/tools
 */

import { useEffect, useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Robot, Wrench, Play, MagnifyingGlass } from '@phosphor-icons/react';
import * as api from '@/lib/apiService';
import { toast } from 'sonner';

interface AgentDef {
  name: string;
  description?: string;
  role?: string;
  status?: string;
}

interface ToolDef {
  id?: string;
  name: string;
  description?: string;
  parameters?: { name: string; type: string; required?: boolean }[];
  category?: string;
}

export function InventoryCatalog() {
  const [agents, setAgents] = useState<AgentDef[]>([]);
  const [tools, setTools] = useState<ToolDef[]>([]);
  const [query, setQuery] = useState('');
  const [activeTool, setActiveTool] = useState<ToolDef | null>(null);
  const [toolArgs, setToolArgs] = useState<Record<string, string>>({});
  const [runningTool, setRunningTool] = useState(false);

  useEffect(() => {
    api.getAgents().then(setAgents).catch(() => setAgents([]));
    api.getTools().then((data) => setTools(Array.isArray(data) ? data : data?.tools || [])).catch(() => setTools([]));
  }, []);

  const filteredAgents = agents.filter(
    (a) =>
      !query ||
      `${a.name} ${a.description || ''} ${a.role || ''}`.toLowerCase().includes(query.toLowerCase())
  );
  const filteredTools = tools.filter(
    (t) =>
      !query ||
      `${t.name} ${t.description || ''}`.toLowerCase().includes(query.toLowerCase())
  );

  const runTool = async () => {
    if (!activeTool) return;
    setRunningTool(true);
    try {
      const args: Record<string, unknown> = {};
      activeTool.parameters?.forEach((p) => {
        const v = toolArgs[p.name] ?? '';
        if (p.type === 'number') args[p.name] = Number(v) || 0;
        else if (p.type === 'boolean') args[p.name] = v === 'true';
        else args[p.name] = v;
      });
      const result = await api.executeTool(activeTool.name, args);
      toast.success('Tool lefuttatva', {
        description: typeof result === 'string' ? result.slice(0, 80) + '...' : JSON.stringify(result).slice(0, 80),
      });
      setActiveTool(null);
    } catch (e: any) {
      toast.error(e.message || 'Tool futtatás sikertelen');
    } finally {
      setRunningTool(false);
    }
  };

  const openToolModal = (tool: ToolDef) => {
    const init: Record<string, string> = {};
    tool.parameters?.forEach((p) => (init[p.name] = ''));
    setToolArgs(init);
    setActiveTool(tool);
  };

  return (
    <div className="space-y-4">
      <div className="flex items-center gap-2">
        <div className="relative flex-1">
          <MagnifyingGlass size={16} className="absolute left-2 top-1/2 -translate-y-1/2 text-zinc-500" />
          <Input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Keresés ügynök vagy eszköz..."
            className="pl-8 bg-zinc-900/60 border-white/[0.04]"
          />
        </div>
      </div>

      <Tabs defaultValue="agents" className="w-full">
        <TabsList className="bg-zinc-900/60 border border-white/[0.04]">
          <TabsTrigger value="agents" className="gap-2">
            <Robot size={16} />
            Ügynökök ({agents.length})
          </TabsTrigger>
          <TabsTrigger value="tools" className="gap-2">
            <Wrench size={16} />
            Eszközök ({tools.length})
          </TabsTrigger>
        </TabsList>

        <TabsContent value="agents" className="mt-4">
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
            {filteredAgents.map((agent) => (
              <Card key={agent.name} className="bg-transparent border-none shadow-none">
                <CardHeader className="pb-2">
                  <div className="flex items-center gap-2">
                    <div className="h-8 w-8 rounded-full bg-emerald-500/20 flex items-center justify-center">
                      <Robot size={16} className="text-emerald-400" />
                    </div>
                    <CardTitle className="text-sm font-medium">{agent.name}</CardTitle>
                  </div>
                  <p className="text-xs text-zinc-500 line-clamp-2">{agent.description || agent.role}</p>
                  <Badge variant="outline" className="w-fit text-xs">
                    {agent.status || 'loaded'}
                  </Badge>
                </CardHeader>
              </Card>
            ))}
            {filteredAgents.length === 0 && (
              <p className="col-span-full text-sm text-zinc-500">Nincs ügynök</p>
            )}
          </div>
        </TabsContent>

        <TabsContent value="tools" className="mt-4">
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
            {filteredTools.map((tool) => (
              <Card key={tool.id || tool.name} className="bg-transparent border-none shadow-none">
                <CardHeader className="pb-2">
                  <div className="flex items-start justify-between gap-2">
                    <div>
                      <CardTitle className="text-sm font-medium">{tool.name}</CardTitle>
                      <p className="text-xs text-zinc-500 line-clamp-2 mt-1">{tool.description}</p>
                    </div>
                    <Badge variant="secondary" className="text-[10px] shrink-0">
                      {tool.category || 'tool'}
                    </Badge>
                  </div>
                  {tool.parameters && tool.parameters.length > 0 && (
                    <div className="flex flex-wrap gap-1 mt-2">
                      {tool.parameters.map((p) => (
                        <Badge key={p.name} variant="outline" className="text-[10px]">
                          {p.name}: {p.type}
                        </Badge>
                      ))}
                    </div>
                  )}
                  <Button
                    size="sm"
                    variant="outline"
                    className="mt-2 gap-1"
                    onClick={() => openToolModal(tool)}
                  >
                    <Play size={12} />
                    Test Run
                  </Button>
                </CardHeader>
              </Card>
            ))}
            {filteredTools.length === 0 && (
              <p className="col-span-full text-sm text-zinc-500">Nincs eszköz</p>
            )}
          </div>
        </TabsContent>
      </Tabs>

      <Dialog open={!!activeTool} onOpenChange={(o) => !o && setActiveTool(null)}>
        <DialogContent className="border-white/[0.04] bg-zinc-950">
          <DialogHeader>
            <DialogTitle>{activeTool?.name}</DialogTitle>
            <DialogDescription>{activeTool?.description}</DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            {activeTool?.parameters?.map((p) => (
              <div key={p.name} className="space-y-1">
                <Label className="text-zinc-400">
                  {p.name} {p.required && '*'}
                </Label>
                <Input
                  value={toolArgs[p.name] ?? ''}
                  onChange={(e) => setToolArgs((prev) => ({ ...prev, [p.name]: e.target.value }))}
                  placeholder={`${p.type}`}
                  className="bg-white/[0.03] border-white/[0.04] rounded-lg"
                />
              </div>
            ))}
            {activeTool && (!activeTool.parameters || activeTool.parameters.length === 0) && (
              <p className="text-sm text-zinc-500">Nincs paraméter</p>
            )}
          </div>
          <DialogFooter>
            <Button variant="outline" onClick={() => setActiveTool(null)}>
              Mégse
            </Button>
            <Button onClick={runTool} disabled={runningTool}>
              {runningTool ? 'Futtatás...' : 'Futtatás'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

import { useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { executeAgent } from "@/lib/apiService";
import { toast } from "sonner";
import { 
  RefreshCcw, 
  FileSpreadsheet, 
  Mail, 
  Search, 
  FileCheck, 
  CheckCircle2, 
  HardDrive,
  AlertTriangle 
} from "lucide-react";

type ProcessStatus = "idle" | "running" | "success" | "error";

export function InvoiceAutomationWidget() {
  const [status, setStatus] = useState<ProcessStatus>("idle");
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState<any>(null);

  const handleProcess = async () => {
    setStatus("running");
    setProgress(20);
    toast.info("Számlák keresése és feldolgozása elindult...");
    
    try {
      // Execute the new InvoiceAutomation agent
      const res = await executeAgent("InvoiceAutomation", "process all invoices from gmail");
      
      setProgress(100);
      if (res.success) {
        setResult(res.data);
        setStatus("success");
        toast.success(res.message || "Feldolgozás sikeresen befejeződött.");
      } else {
        throw new Error(res.message || "Ismeretlen hiba az ügynök futtatása során.");
      }
    } catch (e: any) {
      console.error("[InvoiceAutomation]", e.message);
      setStatus("error");
      toast.error(`Hiba: ${e.message}`);
    }
  };

  return (
    <Card className="glass-card border-white/[0.04] bg-white/[0.03] backdrop-blur-xl h-full flex flex-col">
      <CardHeader className="p-4 border-b border-white/[0.04]">
        <CardTitle className="flex items-center justify-between text-xs font-bold tracking-widest uppercase text-white">
          <span className="flex items-center gap-2">
            <FileSpreadsheet size={16} className="text-blue-400" />
            Számla Automatizálás (Vision)
          </span>
          <Badge variant={status === "success" ? "default" : status === "error" ? "destructive" : "secondary"}>
            {status.toUpperCase()}
          </Badge>
        </CardTitle>
      </CardHeader>
      
      <CardContent className="p-4 flex-1 flex flex-col justify-between space-y-6">
        <div className="space-y-4">
          <div className="flex items-center justify-between">
            <div>
              <p className="text-[10px] text-zinc-500 uppercase font-mono tracking-wider">Mód</p>
              <p className="text-sm font-medium text-zinc-200">Gmail → Gemini → Drive & Sheets</p>
            </div>
            {status === "running" && (
              <div className="flex items-center gap-2 text-blue-400">
                <RefreshCcw size={14} className="animate-spin" />
                <span className="text-[10px] font-bold uppercase">Folyamatban</span>
              </div>
            )}
          </div>

          <div className="space-y-2">
            <div className="flex justify-between text-[10px] font-mono text-zinc-500 uppercase">
              <span>Feldolgozás</span>
              <span>{Math.round(progress)}%</span>
            </div>
            <Progress value={progress} className="h-1 bg-white/[0.04]" />
          </div>

          <div className="grid grid-cols-4 gap-2">
            <StepIcon icon={<Mail size={14} />} label="Gmail" active={status === "running" && progress < 40} done={progress >= 40} />
            <StepIcon icon={<Search size={14} />} label="Vision" active={status === "running" && progress >= 40 && progress < 70} done={progress >= 70} />
            <StepIcon icon={<HardDrive size={14} />} label="Drive" active={status === "running" && progress >= 70 && progress < 90} done={progress >= 90} />
            <StepIcon icon={<FileCheck size={14} />} label="Sheets" active={status === "running" && progress >= 90} done={progress === 100} />
          </div>
        </div>

        <div className="space-y-3">
          {result && (
            <div className="p-3 rounded-xl bg-zinc-900/50 border border-white/[0.04] space-y-2">
              <div className="flex items-center gap-2 text-emerald-400">
                <CheckCircle2 size={14} />
                <span className="text-[10px] font-bold uppercase">Eredmény</span>
              </div>
              <div className="grid grid-cols-2 gap-2 text-[11px]">
                <div className="text-zinc-500 font-mono">Sikeres:</div>
                <div className="text-emerald-400 font-bold text-right">{result.processedCount || 0}</div>
                <div className="text-zinc-500 font-mono">Sikertelen:</div>
                <div className="text-rose-400 font-bold text-right">{result.failedCount || 0}</div>
              </div>
            </div>
          )}

          {status === "error" && (
            <div className="p-3 rounded-xl bg-rose-500/5 border border-rose-500/10 flex items-center gap-3">
              <AlertTriangle size={18} className="text-rose-500" />
              <p className="text-xs text-rose-200">Feldolgozási hiba történt. Ellenőrizd a logokat!</p>
            </div>
          )}

          <Button 
            onClick={handleProcess} 
            disabled={status === "running"}
            className="w-full gap-2 bg-blue-500/10 hover:bg-blue-500/20 text-blue-400 border border-blue-500/20 transition-all hover:scale-[1.01]"
          >
            {status === "running" ? <RefreshCcw size={14} className="animate-spin" /> : <RefreshCcw size={14} />}
            Feldolgozás Indítása
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}

function StepIcon({ icon, label, active, done }: { icon: React.ReactNode, label: string, active: boolean, done: boolean }) {
  return (
    <div className={`p-2 rounded-lg border flex flex-col items-center gap-1 transition-all ${
      done ? "bg-emerald-500/10 border-emerald-500/20 text-emerald-400" : 
      active ? "bg-blue-500/10 border-blue-500/20 text-blue-400 animate-pulse" : 
      "bg-white/[0.02] border-white/[0.04] text-zinc-600"
    }`}>
      {icon}
      <span className="text-[8px] uppercase font-bold">{label}</span>
    </div>
  );
}

import { useMemo, useState, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Progress } from "@/components/ui/progress";
import { executeTool, executeAgent } from "@/lib/apiService";
import { toast } from "sonner";
import { RefreshCcw, FileSpreadsheet, Mail, Search, FileCheck, CheckCircle2 } from "lucide-react";

type SyncStatus = "idle" | "searching" | "downloading" | "processing" | "exporting" | "success" | "error";

export function InvoiceSyncWidget() {
  const [status, setStatus] = useState<SyncStatus>("idle");
  const [progress, setProgress] = useState(0);
  const [lastSyncResult, setLastSyncResult] = useState<any>(null);
  const [downloadedCount, setDownloadedCount] = useState(0);

  const statusLabel = useMemo(() => {
    switch (status) {
      case "searching": return "Gmail keresés...";
      case "downloading": return "PDF letöltés...";
      case "processing": return "OCR & Adatkinyerés...";
      case "exporting": return "Sheets export...";
      case "success": return "Kész";
      case "error": return "Hiba";
      default: return "Készenlét";
    }
  }, [status]);

  const handleFullAutomation = async () => {
    setStatus("searching");
    setProgress(10);
    
    try {
      // 1. Gmail Search & Download
      toast.info("Számlák keresése a Gmailben...");
      const downloadRes = await executeAgent("FinanceGuardian", "Download PDF invoice from gmail");
      
      if (!downloadRes.success) {
        throw new Error(downloadRes.message);
      }

      const files = downloadRes.data?.downloadedFiles || [];
      setDownloadedCount(files.length);
      
      if (files.length === 0) {
        setStatus("success");
        setProgress(100);
        toast.success("Nincs feldolgozandó új számla.");
        return;
      }

      setStatus("processing");
      setProgress(40);

      // 2. Process each file (Simulated loop calling FinanceGuardian for each)
      // In a real scenario, the agent would handle the batch or we call it per file
      for (let i = 0; i < files.length; i++) {
        setProgress(40 + (i / files.length) * 40);
        toast.info(`Feldolgozás: ${files[i].split('\\').pop()}`);
        
        // This task triggers OCR and LanceDB storage
        await executeAgent("FinanceGuardian", "Process invoice data", { 
          context: { filePath: files[i] } 
        });
      }

      setStatus("exporting");
      setProgress(90);
      toast.info("Exportálás Google Sheets-be...");

      // 3. Final Export
      // (Assuming the agent knows which ones to export or exports as it goes)
      // For this widget, we'll just signal completion
      
      setStatus("success");
      setProgress(100);
      setLastSyncResult({
        timestamp: new Date().toISOString(),
        processed: files.length
      });
      toast.success(`${files.length} db számla sikeresen feldolgozva!`);

    } catch (e: any) {
      logError("InvoiceSync", e.message);
      setStatus("error");
      toast.error(`Hiba: ${e.message}`);
    }
  };

  return (
    <Card className="glass-card border-white/[0.04] bg-white/[0.03] backdrop-blur-xl">
      <CardHeader className="p-4 border-b border-white/[0.04]">
        <CardTitle className="flex items-center justify-between text-xs font-bold tracking-widest uppercase text-white">
          <span className="flex items-center gap-2">
            <FileSpreadsheet size={16} className="text-emerald-400" />
            Invoice Automation (MT2)
          </span>
          <Badge variant={status === "success" ? "default" : status === "error" ? "destructive" : "secondary"}>
            {status.toUpperCase()}
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="p-4 space-y-6">
        <div className="flex items-center justify-between gap-4">
          <div className="flex-1 space-y-1">
            <p className="text-[10px] text-zinc-500 uppercase font-mono tracking-wider">Aktuális folyamat</p>
            <p className="text-sm font-medium text-zinc-200">{statusLabel}</p>
          </div>
          <div className="text-right">
            <p className="text-[10px] text-zinc-500 uppercase font-mono">Letöltve</p>
            <p className="text-lg font-bold text-white">{downloadedCount} <span className="text-xs font-normal text-zinc-500">db</span></p>
          </div>
        </div>

        <div className="space-y-2">
          <div className="flex justify-between text-[10px] font-mono text-zinc-500 uppercase">
            <span>Progress</span>
            <span>{Math.round(progress)}%</span>
          </div>
          <Progress value={progress} className="h-1 bg-white/[0.04]" />
        </div>

        <div className="grid grid-cols-3 gap-2">
          <div className="p-2 rounded-lg bg-white/[0.04] border border-white/[0.04] flex flex-col items-center gap-1">
            <Mail size={14} className={status === "searching" ? "text-blue-400 animate-pulse" : "text-zinc-500"} />
            <span className="text-[9px] uppercase text-zinc-500">Gmail</span>
          </div>
          <div className="p-2 rounded-lg bg-white/[0.04] border border-white/[0.04] flex flex-col items-center gap-1">
            <Search size={14} className={status === "processing" ? "text-purple-400 animate-pulse" : "text-zinc-500"} />
            <span className="text-[9px] uppercase text-zinc-500">OCR</span>
          </div>
          <div className="p-2 rounded-lg bg-white/[0.04] border border-white/[0.04] flex flex-col items-center gap-1">
            <FileCheck size={14} className={status === "exporting" ? "text-emerald-400 animate-pulse" : "text-zinc-500"} />
            <span className="text-[9px] uppercase text-zinc-500">Sheets</span>
          </div>
        </div>

        {lastSyncResult && (
          <div className="p-3 rounded-xl bg-emerald-500/5 border border-emerald-500/10 flex items-center gap-3">
            <CheckCircle2 size={18} className="text-emerald-500" />
            <div className="flex-1">
              <p className="text-xs font-medium text-emerald-200">Utolsó sikeres szinkron</p>
              <p className="text-[10px] text-emerald-500/70 font-mono">
                {new Date(lastSyncResult.timestamp).toLocaleString('hu-HU')} • {lastSyncResult.processed} db számla
              </p>
            </div>
          </div>
        )}

        <Button 
          onClick={handleFullAutomation} 
          disabled={status !== "idle" && status !== "success" && status !== "error"}
          className="w-full gap-2 bg-primary/10 hover:bg-primary/20 text-primary border border-primary/20 transition-all hover:scale-[1.02]"
        >
          <RefreshCcw size={14} className={status !== "idle" && status !== "success" && status !== "error" ? "animate-spin" : ""} />
          Automatizált Feldolgozás Indítása
        </Button>
      </CardContent>
    </Card>
  );
}

// Internal logging helper mock (as we don't have it in props)
function logError(tag: string, msg: string) {
  console.error(`[${tag}] ${msg}`);
}

import { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import {
  Robot,
  ArrowsClockwise,
  Play,
  GitPullRequest,
  ChartLine,
} from "@phosphor-icons/react";
import {
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  ResponsiveContainer,
} from "recharts";
import {
  getJulesSessions,
  createJulesTask,
  syncJulesSession,
  type JulesSession,
  getJulesWorkflowRuns,
  dispatchJulesWorkflow,
  type JulesWorkflowRun,
} from "@/lib/apiService";
import { toast } from "sonner";

export function JulesPanel() {
  const [prompt, setPrompt] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [sessions, setSessions] = useState<JulesSession[]>([]);
  const [isLoading, setIsLoading] = useState(false);
  const [runs, setRuns] = useState<JulesWorkflowRun[]>([]);
  const [isLoadingRuns, setIsLoadingRuns] = useState(false);
  const [showAllSessions, setShowAllSessions] = useState(false);
  const [showAsyncTests, setShowAsyncTests] = useState(false);

  const WORKFLOW = "jules-async-tests.yml";
  const MAX_VISIBLE_SESSIONS = 5;

  const refreshSessions = async () => {
    setIsLoading(true);
    try {
      const data = await getJulesSessions();
      setSessions(data);
    } catch (error) {
      console.error("Failed to load Jules sessions:", error);
      toast.error("Jules sessions load failed");
    } finally {
      setIsLoading(false);
    }
  };

  const refreshRuns = async () => {
    setIsLoadingRuns(true);
    try {
      const list = await getJulesWorkflowRuns({
        workflow: WORKFLOW,
        limit: 10,
      });
      setRuns(list);
    } catch (error: any) {
      // Token missing is expected in some dev envs → keep it non-fatal
      setRuns([]);
    } finally {
      setIsLoadingRuns(false);
    }
  };

  const handleCreateTask = async () => {
    if (!prompt.trim()) return;
    setIsSubmitting(true);
    try {
      const result = await createJulesTask(prompt);
      toast.success(`Jules task started: ${result.sessionId || "queued"}`);
      setPrompt("");
      refreshSessions();
    } catch (error) {
      toast.error("Failed to create Jules task");
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleSync = async (sessionId: string) => {
    try {
      await syncJulesSession(sessionId);
      toast.success("Sync started for session");
      refreshSessions();
    } catch (error) {
      toast.error("Sync failed");
    }
  };

  useEffect(() => {
    refreshSessions();
    refreshRuns();
    // Auto-refresh every 30s
    const interval = setInterval(() => {
      refreshSessions();
      refreshRuns();
    }, 30000);
    return () => clearInterval(interval);
  }, []);

  const triggerAsyncTests = async () => {
    try {
      await dispatchJulesWorkflow({
        workflow: WORKFLOW,
        ref: "main",
        inputs: {},
      });
      toast.success("Async tesztek elindítva (workflow_dispatch)");
      refreshRuns();
    } catch (e: any) {
      toast.error(e?.message || "Nem sikerült indítani a workflow-t");
    }
  };

  return (
    <Card className="bg-transparent border-none shadow-none h-full flex flex-col">
      <CardHeader className="flex flex-row items-center justify-between pb-3 px-4 pt-4 shrink-0">
        <CardTitle className="text-xs font-medium tracking-wide text-zinc-400 flex items-center gap-2">
          <Robot size={24} weight="duotone" />
          Jules Integration
        </CardTitle>
        <Button
          variant="ghost"
          size="sm"
          onClick={refreshSessions}
          disabled={isLoading}
        >
          <ArrowsClockwise
            size={16}
            className={isLoading ? "animate-spin" : ""}
          />
        </Button>
      </CardHeader>
      <CardContent className="space-y-6 flex-1 overflow-auto">
        {/* Input Area */}
        <div className="space-y-2">
          <Textarea
            placeholder="Describe the task for Jules (e.g. 'Refactor the authentication logic in python')..."
            value={prompt}
            onChange={(e) => setPrompt(e.target.value)}
            className="bg-white/[0.02] border-white/[0.04] min-h-[100px]"
          />
          <div className="flex justify-end">
            <Button
              onClick={handleCreateTask}
              disabled={isSubmitting || !prompt.trim()}
              className="bg-purple-600 hover:bg-purple-700"
            >
              {isSubmitting ? (
                <ArrowsClockwise className="mr-2 h-4 w-4 animate-spin" />
              ) : (
                <Play className="mr-2 h-4 w-4" />
              )}
              Send to Jules
            </Button>
          </div>
        </div>

        {/* Sessions List - Compact */}
        <div className="rounded-md border border-white/[0.04] overflow-hidden">
          <Table>
            <TableHeader className="bg-white/[0.04]">
              <TableRow className="text-xs">
                <TableHead className="w-[80px] py-2">Session</TableHead>
                <TableHead className="py-2">Status</TableHead>
                <TableHead className="py-2">Task</TableHead>
                <TableHead className="text-right py-2">Action</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {sessions.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={4}
                    className="text-center text-zinc-500 h-16 text-xs"
                  >
                    No active sessions found.
                  </TableCell>
                </TableRow>
              ) : (
                sessions
                  .slice(0, showAllSessions ? undefined : MAX_VISIBLE_SESSIONS)
                  .map((session, i) => (
                    <TableRow key={`session-${session.id || i}`} className="text-xs">
                      <TableCell className="font-mono text-[10px] py-2">
                        {session.id.slice(0, 12)}...
                      </TableCell>
                      <TableCell className="py-2">
                        <Badge
                          variant={
                            session.status?.toLowerCase().includes("completed")
                              ? "default"
                              : session.status?.toLowerCase().includes("running")
                                ? "secondary"
                                : "outline"
                          }
                          className="text-[10px] px-1.5 py-0"
                        >
                          {session.status}
                        </Badge>
                      </TableCell>
                      <TableCell
                        className="max-w-[200px] truncate py-2"
                        title={session.task}
                      >
                        {session.task}
                      </TableCell>
                      <TableCell className="text-right py-2">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleSync(session.id)}
                          title="Sync / Pull"
                          className="h-6 w-6 p-0"
                        >
                          <GitPullRequest size={14} />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
              )}
            </TableBody>
          </Table>
          {sessions.length > MAX_VISIBLE_SESSIONS && (
            <div className="border-t border-white/[0.04] bg-white/[0.04] p-2 text-center">
              <Button
                variant="ghost"
                size="sm"
                onClick={() => setShowAllSessions(!showAllSessions)}
                className="text-xs text-purple-400 hover:text-purple-300"
              >
                {showAllSessions
                  ? "Show Less"
                  : `Show ${sessions.length - MAX_VISIBLE_SESSIONS} More`}
              </Button>
            </div>
          )}
        </div>

        {/* Async Tests (GitHub Actions) - Collapsible */}
        <div
          className="flex items-center justify-between px-3 py-2 bg-white/[0.04] w-full hover:bg-white/10 transition-colors cursor-pointer"
          onClick={() => setShowAsyncTests(!showAsyncTests)}
          role="button"
          tabIndex={0}
          onKeyDown={(e) => {
            if (e.key === 'Enter' || e.key === ' ') {
              setShowAsyncTests(!showAsyncTests);
            }
          }}
        >
          <div className="text-xs font-medium text-zinc-500 flex items-center gap-2">
            Async Tests (GitHub Actions)
            {runs.length > 0 && (
              <Badge variant="secondary" className="text-[10px] px-1.5 py-0">
                {runs.filter((r) => r.conclusion === "success").length}/{runs.length} Pass
              </Badge>
            )}
          </div>
          <div className="flex gap-2 items-center">
            <Button
              variant="ghost"
              size="sm"
              onClick={(e) => {
                e.stopPropagation();
                refreshRuns();
              }}
              disabled={isLoadingRuns}
              title="Frissítés"
              className="h-6 w-6 p-0"
            >
              <ArrowsClockwise
                size={14}
                className={isLoadingRuns ? "animate-spin" : ""}
              />
            </Button>
            <span className="text-xs text-zinc-500">
              {showAsyncTests ? "▼" : "▶"}
            </span>
          </div>
        </div>
        {showAsyncTests && (
          <div className="rounded-md border border-white/[0.04] overflow-hidden">
            <Table>
            <TableHeader className="bg-white/[0.04]">
              <TableRow>
                <TableHead className="w-[80px]">#</TableHead>
                <TableHead>Status</TableHead>
                <TableHead>Conclusion</TableHead>
                <TableHead>Updated</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {runs.length === 0 ? (
                <TableRow>
                  <TableCell
                    colSpan={4}
                    className="text-center text-zinc-500 h-16"
                  >
                    {isLoadingRuns
                      ? "Betöltés..."
                      : "Nincs adat (lehet hiányzik a GITHUB_TOKEN a szerveren)."}
                  </TableCell>
                </TableRow>
              ) : (
                runs.map((r, i) => (
                  <TableRow key={`run-${r.id || i}`}>
                    <TableCell className="font-mono text-xs">
                      {r.run_number ?? r.id}
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">{r.status || "unknown"}</Badge>
                    </TableCell>
                    <TableCell>
                      <Badge
                        variant={
                          (r.conclusion || "") === "success"
                            ? "default"
                            : (r.conclusion || "") === "failure"
                              ? "destructive"
                              : "secondary"
                        }
                      >
                        {r.conclusion ?? "-"}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-xs text-zinc-500">
                      {(r.updated_at || r.created_at || "")
                        .slice(0, 19)
                        .replace("T", " ")}
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
          </div>
          )}

        {/* Test Trend Chart - Only show if tests are visible and there are successes */}
        {showAsyncTests && runs.length > 0 && runs.some(r => r.conclusion === "success") && (
          <div className="rounded-md border border-white/[0.04] overflow-hidden">
            <div className="flex items-center justify-between px-3 py-2 bg-white/[0.04]">
              <div className="text-sm font-medium text-zinc-500 flex items-center gap-2">
                <ChartLine size={16} />
                Test Success Trend (Last 10 Runs)
              </div>
            </div>
            <div className="p-4 bg-white/[0.02]">
              <ResponsiveContainer width="100%" height={200}>
                <LineChart
                  data={runs
                    .slice()
                    .reverse()
                    .map((r, idx) => ({
                      run: `#${r.run_number ?? idx + 1}`,
                      success: r.conclusion === "success" ? 100 : 0,
                    }))}
                >
                  <CartesianGrid strokeDasharray="3 3" stroke="#333" />
                  <XAxis dataKey="run" stroke="#888" fontSize={11} />
                  <YAxis stroke="#888" fontSize={11} domain={[0, 100]} />
                  <Tooltip
                    contentStyle={{
                      backgroundColor: "#1a1a1a",
                      border: "1px solid #333",
                      borderRadius: "4px",
                    }}
                  />
                  <Line
                    type="monotone"
                    dataKey="success"
                    stroke="#10b981"
                    strokeWidth={2}
                    dot={{ fill: "#10b981", r: 4 }}
                  />
                </LineChart>
              </ResponsiveContainer>
              <div className="mt-2 text-xs text-zinc-500 text-center">
                {runs.filter((r) => r.conclusion === "success").length} / {runs.length} successful runs (
                {Math.round((runs.filter((r) => r.conclusion === "success").length / runs.length) * 100)}% pass rate)
              </div>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from 'react'
import { Database, Search, Upload, FileText, CheckCircle2, AlertCircle, Loader2 } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Badge } from '@/components/ui/badge'
import { toast } from 'sonner'
import { API_BASE } from '@/lib/apiService'

interface RagStats {
    table: string;
    provider: string;
    status: string;
}

interface SearchResult {
    text: string;
    path?: string;
    score?: number;
}

export function KnowledgeBasePanel() {
    const [stats, setStats] = useState<RagStats | null>(null)
    const [isLoading, setIsLoading] = useState(false)
    const [isIngesting, setIsIngesting] = useState(false)
    const [rowCount, setRowCount] = useState(0)
    const [query, setQuery] = useState('')
    const [isSearching, setIsSearching] = useState(false)
    const [results, setResults] = useState<SearchResult[]>([])

    useEffect(() => {
        fetchStats()
    }, [])

    const fetchStats = async () => {
        setIsLoading(true)
        try {
            const response = await fetch(`${API_BASE}/api/rag/stats`)
            const data = await response.json()
            setStats(data)
            setRowCount(data.rowCount || 0)
        } catch (error) {
            toast.error('Hiba a RAG statisztikák betöltésekor')
        } finally {
            setIsLoading(false)
        }
    }

    const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
        const file = e.target.files?.[0]
        if (!file) return

        setIsIngesting(true)
        const reader = new FileReader()

        reader.onload = async (event) => {
            const text = event.target?.result as string
            if (!text) {
                toast.error('Gond adódott a fájl beolvasása közben')
                setIsIngesting(false)
                return
            }

            try {
                toast.info(`${file.name} indexelése folyamatban...`)
                const response = await fetch(`${API_BASE}/api/rag/ingest`, {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json' },
                    body: JSON.stringify({
                        text,
                        metadata: {
                            path: file.name,
                            size: file.size,
                            type: file.type || 'text/plain'
                        }
                    })
                })

                if (response.ok) {
                    toast.success(`${file.name} sikeresen beindexelve!`)
                    fetchStats()
                } else {
                    toast.error('Sikertelen indexelés')
                }
            } catch (error) {
                toast.error('Hálózati hiba az indexelés során')
            } finally {
                setIsIngesting(false)
            }
        }

        reader.onerror = () => {
            toast.error('Hiba a fájl olvasásakor')
            setIsIngesting(false)
        }

        reader.readAsText(file)
    }

    const handleSearch = async () => {
        if (!query.trim()) return
        setIsSearching(true)
        try {
            const response = await fetch(`${API_BASE}/api/rag/query?query=${encodeURIComponent(query)}`)
            const data = await response.json()
            setResults(data.results || [])
            if (data.results?.length === 0) {
                toast.info('Nincs találat a tudásbázisban')
            }
        } catch (error) {
            toast.error('Hiba a keresés során')
        } finally {
            setIsSearching(false)
        }
    }

    return (
        <div className="p-6 space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h1 className="text-3xl font-bold tracking-tight">Knowledge Base</h1>
                    <p className="text-zinc-500">
                        Brunella szemantikus memóriájának (RAG) kezelése és vizualizációja.
                    </p>
                </div>
                <div className="flex gap-2">
                    <Button variant="outline" onClick={fetchStats} disabled={isLoading}>
                        <CheckCircle2 className={`w-4 h-4 mr-2 ${stats?.status === 'online' ? 'text-green-500' : ''}`} />
                        {stats?.provider || 'LanceDB'} {stats?.status || 'Offline'}
                    </Button>
                </div>
            </div>

            <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Bejegyzések Száma</CardTitle>
                        <Database className="h-4 w-4 text-zinc-500" />
                    </CardHeader>
                    <CardContent>
                        <div className="text-2xl font-bold">{rowCount}</div>
                        <p className="text-xs text-zinc-500">Szemantikus vektor tároló ({stats?.table || 'memory'})</p>
                    </CardContent>
                </Card>
                <Card>
                    <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                        <CardTitle className="text-sm font-medium">Ingestion</CardTitle>
                        <Upload className="h-4 w-4 text-zinc-500" />
                    </CardHeader>
                    <CardContent>
                        <div className="flex items-center gap-2">
                            <Input
                                id="rag-file-upload"
                                type="file"
                                className="hidden"
                                accept=".txt,.md,.log,.json,.ts,.js,.py"
                                onChange={handleFileUpload}
                                disabled={isIngesting}
                            />
                            <Button
                                variant="outline"
                                className="w-full"
                                onClick={() => document.getElementById('rag-file-upload')?.click()}
                                disabled={isIngesting}
                            >
                                {isIngesting ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Upload className="h-4 h-4 mr-2" />}
                                Fájl feltöltése
                            </Button>
                        </div>
                    </CardContent>
                </Card>
            </div>

            <Card className="col-span-3">
                <CardHeader>
                    <CardTitle>Szemantikus Keresés</CardTitle>
                    <CardDescription>
                        Keress a beindexelt dokumentumok között természetes nyelven.
                    </CardDescription>
                </CardHeader>
                <CardContent className="space-y-4">
                    <div className="flex gap-2">
                        <Input
                            placeholder="Mire emlékszik Brunella?..."
                            value={query}
                            onChange={(e) => setQuery(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && handleSearch()}
                        />
                        <Button onClick={handleSearch} disabled={isSearching}>
                            {isSearching ? <Loader2 className="w-4 h-4 animate-spin" /> : <Search className="w-4 h-4 mr-2" />}
                            Keresés
                        </Button>
                    </div>

                    <ScrollArea className="h-[400px] rounded-md border p-4">
                        {results.length > 0 ? (
                            <div className="space-y-4">
                                {results.map((res, idx) => (
                                    <div key={idx} className="p-3 rounded-lg bg-muted/50 border border-border space-y-2">
                                        <div className="flex items-center justify-between">
                                            <div className="flex items-center gap-2">
                                                <FileText className="w-4 h-4 text-primary" />
                                                <span className="text-sm font-semibold">{res.path || 'Unknown Source'}</span>
                                            </div>
                                            {res.score !== undefined && (
                                                <Badge variant="secondary">Dist: {res.score.toFixed(4)}</Badge>
                                            )}
                                        </div>
                                        <p className="text-sm text-foreground leading-relaxed italic border-l-2 border-primary/30 pl-3">
                                            "{res.text}"
                                        </p>
                                    </div>
                                ))}
                            </div>
                        ) : (
                            <div className="flex flex-col items-center justify-center h-full text-zinc-500 py-10">
                                <Search className="w-10 h-10 mb-4 opacity-20" />
                                <p>Nincsenek aktív keresési találatok</p>
                            </div>
                        )}
                    </ScrollArea>
                </CardContent>
            </Card>
        </div>
    )
}

import { useState, useEffect } from 'react'
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card'
import { Badge } from '@/components/ui/badge'
import { Button } from '@/components/ui/button'
import {
    Zap,
    RefreshCcw,
    CheckCircle2,
    XCircle,
    Activity,
    Cpu,
    Globe,
    Github
} from 'lucide-react'
import { getProvidersStatus, type ProviderStatus } from '@/lib/apiService'
import { toast } from 'sonner'
import { Progress } from '@/components/ui/progress'

export function LLMProvidersPanel() {
    const [providers, setProviders] = useState<ProviderStatus[]>([])
    const [loading, setLoading] = useState(true)

    const fetchStatus = async () => {
        setLoading(true)
        try {
            const results = await getProvidersStatus()
            setProviders(results)
        } catch (err: any) {
            toast.error(`Hiba a lekérdezés során: ${err.message}`)
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        fetchStatus()
        const interval = setInterval(fetchStatus, 30000) // Refresh every 30s
        return () => clearInterval(interval)
    }, [])

    const getProviderIcon = (id: string) => {
        switch (id) {
            case 'ollama': return <Cpu className="text-orange-500" size={20} />
            case 'gemini': return <Globe className="text-blue-500" size={20} />
            case 'github': return <Github className="text-white" size={20} />
            default: return <Zap className="text-primary" size={20} />
        }
    }

    return (
        <div className="space-y-6">
            <div className="flex items-center justify-between">
                <div>
                    <h2 className="text-2xl font-space font-bold text-foreground">LLM Providers</h2>
                    <p className="text-zinc-500 text-sm">Monitor connectivity and latency for neural engines.</p>
                </div>
                <Button
                    variant="outline"
                    size="sm"
                    onClick={fetchStatus}
                    disabled={loading}
                    className="gap-2"
                >
                    <RefreshCcw size={14} className={loading ? "animate-spin" : ""} />
                    Refresh
                </Button>
            </div>

            <div className="grid gap-4 md:grid-cols-3">
                {providers.map((p) => (
                    <Card key={p.id} className="glass-card border-white/10 overflow-hidden group hover:border-primary/50 transition-all">
                        <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                            <div className="flex items-center gap-3">
                                <div className="p-2 bg-muted/50 rounded-lg">
                                    {getProviderIcon(p.id)}
                                </div>
                                <div>
                                    <CardTitle className="text-sm font-bold">{p.name}</CardTitle>
                                    <CardDescription className="text-[10px] uppercase tracking-wider">{p.id === 'ollama' ? 'Local Compute' : 'Cloud Compute'}</CardDescription>
                                </div>
                            </div>
                            <Badge variant={p.status === 'online' ? 'default' : 'destructive'} className="h-5 px-1.5 py-0">
                                {p.status === 'online' ? <CheckCircle2 size={10} className="mr-1" /> : <XCircle size={10} className="mr-1" />}
                                {p.status}
                            </Badge>
                        </CardHeader>
                        <CardContent>
                            <div className="mt-4 space-y-3">
                                <div className="flex justify-between items-end">
                                    <span className="text-xs text-zinc-500 flex items-center gap-1">
                                        <Activity size={10} /> Latency
                                    </span>
                                    <span className={p.status === 'online' ? "text-sm font-mono text-green-400" : "text-sm font-mono text-zinc-500"}>
                                        {p.status === 'online' ? `${p.latency}ms` : 'N/A'}
                                    </span>
                                </div>
                                <Progress value={p.status === 'online' ? Math.max(10, 100 - (p.latency || 0) / 10) : 0} className="h-1 bg-white/[0.04]" />

                                {p.error && (
                                    <div className="bg-destructive/10 border border-destructive/20 rounded p-2 mt-2">
                                        <p className="text-[10px] text-destructive leading-tight truncate">{p.error}</p>
                                    </div>
                                )}
                            </div>
                        </CardContent>
                    </Card>
                ))}
                {providers.length === 0 && loading && (
                    Array.from({ length: 3 }).map((_, i) => (
                        <Card key={i} className="glass-card animate-pulse h-[160px] border-white/10" />
                    ))
                )}
            </div>
        </div>
    )
}

import React, { useState, useEffect, useMemo } from 'react';
import { 
    ShieldAlert, 
    Scale, 
    Calendar, 
    CheckCircle2, 
    XCircle, 
    Loader2, 
    Search,
    ExternalLink,
    History,
    AlertTriangle,
    FileWarning,
    Briefcase
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Input } from '../ui/input';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useBusinessStore } from '../../lib/businessStore';
import { format } from 'date-fns';

export function LawDetectiveWidget() {
    const [keywords, setKeywords] = useState('');
    const { jobs, isLoading, fetchJobs, createJob } = useBusinessStore();
    const { socket } = useSocket();
    const [selectedJobId, setSelectedJobId] = useState<string | null>(null);

    const lawJobs = useMemo(() => jobs.filter(j => j.type === 'law_detective'), [jobs]);

    useEffect(() => {
        fetchJobs('law_detective');
    }, [fetchJobs]);

    useEffect(() => {
        if (!socket) return;

        const handleJobUpdate = (data: { jobId: string, status: string }) => {
            fetchJobs('law_detective');
            if (data.status === 'completed') {
                toast.success("Jogszabály elemzés sikeresen befejeződött!", {
                    icon: <ShieldAlert className="w-4 h-4 text-blue-500" />
                });
            }
        };

        socket.on('business_job:updated', handleJobUpdate);
        return () => {
            socket.off('business_job:updated', handleJobUpdate);
        };
    }, [socket, fetchJobs]);

    const handleStartScan = async () => {
        const jobId = await createJob('law_detective', keywords || 'KKV adózás és munkaügy');
        if (jobId) {
            toast.info("Magyar Közlöny átvilágítása megkezdődött...");
            setKeywords('');
        }
    };

    const activeJob = jobs.find(j => j.id === selectedJobId) || lawJobs[0];
    const changes = activeJob?.results_json ? JSON.parse(activeJob.results_json) : [];

    return (
        <Card className="w-full shadow-xl border-blue-500/20 bg-card/50 backdrop-blur-md">
            <CardHeader className="pb-3 border-b border-white/[0.04]">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-blue-500/10 rounded-full">
                            <Scale className="w-5 h-5 text-blue-500" />
                        </div>
                        <div>
                            <CardTitle>Law Detective</CardTitle>
                            <CardDescription>Jogszabály-monitoring és automatikus hatásvizsgálat</CardDescription>
                        </div>
                    </div>
                </div>
            </CardHeader>
            <CardContent className="pt-6">
                <div className="flex gap-2 mb-8">
                    <Input 
                        placeholder="Figyelt kulcsszavak (pl. KATA, ÁFA, minimálbér)" 
                        value={keywords}
                        onChange={(e) => setKeywords(e.target.value)}
                        className="bg-secondary/20 border-blue-500/10 h-12"
                    />
                    <Button 
                        onClick={handleStartScan} 
                        disabled={isLoading}
                        className="bg-blue-600 hover:bg-blue-700 min-w-[160px] h-12 text-white font-bold"
                    >
                        {isLoading ? <Loader2 className="w-4 h-4 animate-spin mr-2" /> : <Search className="w-4 h-4 mr-2" />}
                        Figyelés
                    </Button>
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
                    {/* Előzmények */}
                    <div className="lg:col-span-1 border-r border-white/[0.04] pr-4 flex flex-col gap-4">
                        <h3 className="text-xs font-semibold uppercase text-zinc-500 flex items-center gap-2">
                            <History size={12} />
                            Utolsó Vizsgálatok
                        </h3>
                        <ScrollArea className="h-[400px]">
                            <div className="space-y-2">
                                {lawJobs.length === 0 ? (
                                    <p className="text-xs text-zinc-500 italic">Nincs korábbi adat.</p>
                                ) : (
                                    lawJobs.map((job) => (
                                        <div 
                                            key={job.id}
                                            onClick={() => setSelectedJobId(job.id)}
                                            className={`p-3 rounded-lg border cursor-pointer transition-all ${
                                                selectedJobId === job.id || (!selectedJobId && lawJobs[0].id === job.id)
                                                    ? 'bg-blue-500/10 border-blue-500/30' 
                                                    : 'bg-secondary/5 border-transparent hover:border-blue-500/20'
                                            }`}
                                        >
                                            <div className="font-bold text-[10px] truncate mb-1 uppercase tracking-wider">{job.query}</div>
                                            <div className="flex justify-between items-center text-[9px] text-zinc-500 font-mono">
                                                {format(new Date(job.created_at), 'MM.dd HH:mm')}
                                                {job.status === 'completed' && <CheckCircle2 size={10} className="text-blue-500" />}
                                            </div>
                                        </div>
                                    ))
                                )}
                            </div>
                        </ScrollArea>
                    </div>

                    {/* Változások Idővonala */}
                    <div className="lg:col-span-2">
                        {activeJob ? (
                            <div className="space-y-4">
                                <h3 className="text-sm font-bold flex items-center gap-2">
                                    Releváns Változások
                                    <Badge variant="outline" className="text-[10px]">{changes.length}</Badge>
                                </h3>

                                <ScrollArea className="h-[400px] pr-4 text-zinc-100">
                                    {activeJob.status === 'running' ? (
                                        <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500">
                                            <Loader2 className="w-10 h-10 mb-4 animate-spin text-blue-500" />
                                            <p className="animate-pulse text-xs">Magyar Közlöny PDF-ek elemzése...</p>
                                        </div>
                                    ) : (
                                        <div className="space-y-6">
                                            {changes.map((law: any, i: number) => (
                                                <div 
                                                    key={i}
                                                    className="relative pl-6 border-l-2 border-blue-500/20 py-2"
                                                >
                                                    <div className="absolute -left-[9px] top-4 w-4 h-4 rounded-full bg-zinc-900 border-2 border-blue-500" />
                                                    
                                                    <div className="flex justify-between items-start mb-2">
                                                        <h4 className="font-bold text-sm text-blue-100 leading-tight">{law.title}</h4>
                                                        <Badge className={law.relevanceScore >= 80 ? "bg-red-500/20 text-red-500" : "bg-blue-500/20 text-blue-500"}>
                                                            {law.relevanceScore}%
                                                        </Badge>
                                                    </div>
                                                    
                                                    <div className="flex items-center gap-3 text-[10px] text-zinc-500 mb-3 font-mono uppercase">
                                                        <span>{law.category}</span>
                                                        <span>•</span>
                                                        <span>{law.date}</span>
                                                    </div>

                                                    <p className="text-xs text-zinc-400 mb-4 italic leading-relaxed">
                                                        "{law.summary}"
                                                    </p>

                                                    <div className="p-3 rounded-lg bg-red-500/5 border border-red-500/10 flex gap-3">
                                                        <Briefcase className="w-4 h-4 text-red-400 shrink-0 mt-0.5" />
                                                        <div>
                                                            <div className="text-[10px] font-bold text-red-400 uppercase tracking-widest mb-1">Cégvezetői Teendő</div>
                                                            <div className="text-xs text-zinc-200 font-medium">{law.businessImpact}</div>
                                                        </div>
                                                    </div>
                                                </div>
                                            ))}
                                        </div>
                                    )}
                                </ScrollArea>
                            </div>
                        ) : (
                            <div className="h-full flex flex-col items-center justify-center py-20 text-zinc-500 opacity-40">
                                <FileWarning className="w-16 h-16 mb-4" />
                                <p>Indíts egy vizsgálatot a kulcsszavak alapján.</p>
                            </div>
                        )}
                    </div>
                </div>
            </CardContent>
        </Card>
    );
}

import React, { useState, useEffect } from 'react';
import {
    Users,
    Zap,
    ArrowRight,
    Download,
    RefreshCw,
    Search,
    MessageSquare,
    ExternalLink
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';

interface Lead {
    id: string;
    name: string;
    website: string;
    industry: string;
