      <CardContent className="p-0 flex-1 overflow-hidden">
        <ScrollArea className="h-full max-h-[400px]">
          <div className="p-4 space-y-4">
            {chatter.length === 0 ? (
              <div className="flex flex-col items-center justify-center h-32 text-zinc-500 space-y-2">
                <MessageSquare className="w-8 h-8 opacity-20" />
                <p className="text-xs italic">Még nincs ügynök aktivitás...</p>
              </div>
            ) : (
              chatter.map((entry) => (
                <div
                  key={entry.id}
                  className="group flex flex-col space-y-1 animate-in fade-in slide-in-from-left-2 duration-300"
                >
                  <div className="flex items-center gap-2">
                    <div className="flex items-center gap-1 bg-white/[0.04] px-2 py-0.5 rounded-full border border-white/10">
                      {getAgentIcon(entry.sender)}
                      <span className="text-[10px] font-bold text-zinc-300">{entry.sender}</span>
                    </div>

                    {entry.receiver && (
                      <>
                        <ArrowRight className="w-3 h-3 text-zinc-600" />
                        <div className="flex items-center gap-1 bg-white/[0.04] px-2 py-0.5 rounded-full border border-white/10">
                          {getAgentIcon(entry.receiver)}
                          <span className="text-[10px] font-bold text-zinc-300">{entry.receiver}</span>
                        </div>
                      </>
                    )}

                    <span className="text-[10px] text-zinc-600 font-mono ml-auto">
                      {new Date(entry.timestamp).toLocaleTimeString('hu-HU')}
                    </span>
                  </div>

                  <div className="pl-2 border-l-2 border-primary/20 group-hover:border-primary/50 transition-colors">
                    <p className="text-xs text-zinc-400 leading-relaxed">
                      {entry.message}
                    </p>
                  </div>
                </div>
              ))
            )}
          </div>
        </ScrollArea>
      </CardContent>
    </Card>
  );
}

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Progress } from '@/components/ui/progress';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
  CheckCircle,
  Circle,
  XCircle,
  StopCircle,
  Clock,
  Eye,
  ArrowRight
} from 'lucide-react';
import { useSystemSignal } from '@/hooks/useSystemSignal';
import { RobotkezStep } from '@/context/SocketContext';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';

export function LiveExecutionMonitor() {
  const { robotkezPlan, robotkezSteps, socket } = useSystemSignal();
  const [selectedScreenshot, setSelectedScreenshot] = useState<string | null>(null);

  if (!robotkezPlan) return null;

  const totalSteps = robotkezSteps.length;
  const completedSteps = robotkezSteps.filter(s => s.status === 'completed').length;
  const progress = totalSteps > 0 ? (completedSteps / totalSteps) * 100 : 0;
  const isRunning = robotkezSteps.some(s => s.status === 'working');
  const isFinished = completedSteps === totalSteps || robotkezSteps.some(s => s.status === 'error');

  const handleAbort = () => {
    if (socket) {
      socket.emit('robotkez:abort');
      toast.warning('Megszakítás elküldve...');
    }
  };

  const getStatusIcon = (status: RobotkezStep['status']) => {
    switch (status) {
      case 'completed': return <CheckCircle className="w-4 h-4 text-emerald-500" />;
      case 'working': return <div className="w-4 h-4 border-2 border-primary border-t-transparent rounded-full animate-spin" />;
      case 'error': return <XCircle className="w-4 h-4 text-red-500" />;
      default: return <Circle className="w-4 h-4 text-zinc-600" />;
    }
  };

  return (
    <div className="space-y-4 animate-in fade-in slide-in-from-top-4 duration-500">
      <Card className="glass-panel border-primary/20 bg-primary/5">
        <CardHeader className="p-4 border-b border-white/[0.04] flex flex-row items-center justify-between">
          <div className="space-y-1">
            <CardTitle className="text-sm font-bold tracking-widest uppercase flex items-center gap-2">
              <div className="w-2 h-2 rounded-full bg-primary animate-pulse" />
              Live Execution Monitor
            </CardTitle>
            <p className="text-[10px] font-mono text-zinc-500">MISSION_ID: {robotkezPlan.taskId}</p>
          </div>

          {!isFinished && (
            <Button
              variant="destructive"
              size="sm"
              className="h-8 gap-2 bg-red-500/20 hover:bg-red-500 text-red-500 hover:text-white border border-red-500/30"
              onClick={handleAbort}
            >
              <StopCircle size={14} />
              STOP
            </Button>
          )}
        </CardHeader>

        <CardContent className="p-4 space-y-4">
          {/* Progress Section */}
          <div className="space-y-2">
            <div className="flex justify-between text-[10px] font-mono text-zinc-400 uppercase">
              <span>Progress</span>
              <span>{Math.round(progress)}% ({completedSteps}/{totalSteps})</span>
            </div>
            <Progress value={progress} className="h-1.5 bg-white/[0.04]" />
          </div>

          {/* Steps List */}
          <ScrollArea className="h-[300px] pr-4">
            <div className="space-y-3">
              {robotkezSteps.map((step, idx) => (
                <div
                  key={idx}
                  className={cn(
                    "flex items-start gap-3 p-3 rounded-xl border transition-all duration-300",
                    step.status === 'working' ? "bg-primary/10 border-primary/30" :
                      step.status === 'completed' ? "bg-white/[0.04] border-emerald-500/20" :
                        "bg-white/[0.02] border-white/[0.04] opacity-60"
                  )}
                >
                  <div className="mt-0.5 shrink-0">
                    {getStatusIcon(step.status)}
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className={cn(
                      "text-xs font-medium leading-none",
                      step.status === 'completed' ? "text-emerald-400" : "text-zinc-200"
                    )}>
                      {step.description}
                    </p>
                    {step.error && (
                      <p className="text-[10px] text-red-400 mt-1 font-mono">ERR: {step.error}</p>
                    )}
                  </div>
                  {step.screenshot && (
                    <Button
                      variant="ghost"
                      size="icon"
                      className="h-6 w-6 rounded-full hover:bg-white/10"
                      onClick={() => setSelectedScreenshot(step.screenshot || null)}
                    >
                      <Eye size={12} className="text-zinc-400" />
                    </Button>
                  )}
                </div>
              ))}
            </div>
          </ScrollArea>

          {/* Estimated Time */}
          <div className="pt-2 border-t border-white/[0.04] flex items-center justify-between text-[10px] font-mono text-zinc-500 uppercase">
            <div className="flex items-center gap-1.5">
              <Clock size={12} />
              <span>Est. Remaining: {Math.round((robotkezPlan.plan.estimatedDuration * (1 - progress / 100)) / 1000)}s</span>
            </div>
            {isFinished && (
              <Button
                variant="link"
                size="sm"
                className="h-auto p-0 text-[10px] text-zinc-400 hover:text-primary"
                onClick={() => { /* Potential clear/archive logic */ }}
              >
                DISMISS MONITOR
              </Button>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Screenshot Modal/Overlay */}
      {selectedScreenshot && (
        <div
          className="fixed inset-0 z-[100] bg-black/90 flex items-center justify-center p-8 animate-in fade-in duration-300"
          onClick={() => setSelectedScreenshot(null)}
        >
          <div className="relative max-w-5xl w-full max-h-full flex flex-col items-center gap-4">
            <img
              src={selectedScreenshot.startsWith('data:') ? selectedScreenshot : `data:image/png;base64,${selectedScreenshot}`}
              alt="Step Screenshot"
              className="max-w-full max-h-[85vh] rounded-lg border border-white/10 shadow-2xl"
            />
            <Button variant="outline" className="bg-white/[0.04] border-white/10 text-white hover:bg-white/10">
              CLOSE PREVIEW
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import React, { useState, useEffect } from 'react';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../ui/tabs';
import { ScrollArea } from '../ui/scroll-area';
import {
  Activity,
  Zap,
  Shield,
  FileText,
  Play,
  CheckCircle2,
  XCircle,
  Clock,
  Database,
  CloudCog
} from 'lucide-react';

/**
 * MCPCommandCenter - Dashboard for MCP + Bifrost Gateway
 *
 * Features:
 * - Provider health status (Ollama, Gemini, GitHub, Anthropic)
 * - MCP tool list + execution
 * - Safe Zone audit log viewer
 * - E2B sandbox stats
 * - Bifrost usage statistics
 */

interface Provider {
  provider: string;
  available: boolean;
  last_check: string;
  response_time_ms?: number;
  error?: string;
}

interface MCPTool {
  name: string;
  description: string;
  inputSchema: any;
}

interface AuditEntry {
  timestamp: string;
  verdict: 'ALLOWED' | 'DENIED';
  path: string;
  operation: string;
  reason?: string;
  zone?: string;
}

interface Stats {
  bifrost: {
    total_requests: number;
    by_provider: Record<string, number>;
    enabled_providers: string[];
  };
  e2b: {
    total_executions: number;
    active_sandboxes: number;
    avg_duration_ms: number;
  };
}

export function MCPCommandCenter() {
  const [providers, setProviders] = useState<Provider[]>([]);
  const [tools, setTools] = useState<MCPTool[]>([]);
  const [auditLog, setAuditLog] = useState<AuditEntry[]>([]);
  const [stats, setStats] = useState<Stats | null>(null);
  const [loading, setLoading] = useState(true);
  const [selectedTool, setSelectedTool] = useState<MCPTool | null>(null);
  const [toolArgs, setToolArgs] = useState('{}');
  const [toolResult, setToolResult] = useState<any>(null);
  const [executing, setExecuting] = useState(false);

  // Fetch data on mount
  useEffect(() => {
    fetchData();
    const interval = setInterval(fetchData, 10000); // Refresh every 10s
    return () => clearInterval(interval);
  }, []);

  async function fetchData() {
    try {
      // Fetch providers
      const providersRes = await fetch('/api/v1/mcp/providers');
      const providersData = await providersRes.json();
      if (providersData.success) {
        setProviders(providersData.providers);
      }

      // Fetch tools
      const toolsRes = await fetch('/api/v1/mcp/tools');
      const toolsData = await toolsRes.json();
      if (toolsData.success) {
        setTools(toolsData.tools);
      }

      // Fetch audit log
      const auditRes = await fetch('/api/v1/mcp/audit?limit=20');
      const auditData = await auditRes.json();
      if (auditData.success) {
        setAuditLog(auditData.audit_log);
      }

      // Fetch stats
      const statsRes = await fetch('/api/v1/mcp/stats');
      const statsData = await statsRes.json();
      if (statsData.success) {
        setStats(statsData);
      }

      setLoading(false);
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      console.error('Failed to fetch MCP data:', error);
      setLoading(false);
    }
  }

  async function executeTool() {
    if (!selectedTool) return;

    setExecuting(true);
    setToolResult(null);

    try {
      const args = JSON.parse(toolArgs);

      const response = await fetch(`/api/v1/mcp/tools/${selectedTool.name}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ args })
      });

      const result = await response.json();
      setToolResult(result);
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      setToolResult({ success: false, error });
    } finally {
      setExecuting(false);
    }
  }

  if (loading) {
    return (
      <Card className="glass-card border-white/[0.04]">
        <CardContent className="py-8 flex items-center justify-center">
          <div className="flex items-center gap-2 text-zinc-400">
            <Activity className="w-4 h-4 animate-spin" />
            <span>Loading MCP Command Center...</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card className="glass-card border-white/[0.04]">
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle className="text-lg font-mono flex items-center gap-2">
              <CloudCog className="w-5 h-5 text-blue-400" />
              MCP Command Center
            </CardTitle>
            <CardDescription>
              Multi-Provider LLM Gateway + Safe Zone Management
            </CardDescription>
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={fetchData}
            className="text-xs"
          >
            <Activity className="w-3 h-3 mr-1" />
            Refresh
          </Button>
        </div>
      </CardHeader>

      <CardContent>
        <Tabs defaultValue="providers" className="w-full">
          <TabsList className="grid w-full grid-cols-4 bg-zinc-900/50">
            <TabsTrigger value="providers">Providers</TabsTrigger>
            <TabsTrigger value="tools">MCP Tools</TabsTrigger>
            <TabsTrigger value="audit">Audit Log</TabsTrigger>
            <TabsTrigger value="stats">Statistics</TabsTrigger>
          </TabsList>

          {/* Providers Tab */}
          <TabsContent value="providers" className="space-y-3">
            <div className="grid gap-3">
              {providers.map((provider) => (
                <Card key={provider.provider} className="bg-white/[0.02] border-white/[0.04] rounded-lg">
                  <CardContent className="py-3 px-4">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-3">
                        {provider.available ? (
                          <CheckCircle2 className="w-5 h-5 text-green-400" />
                        ) : (
                          <XCircle className="w-5 h-5 text-red-400" />
                        )}
                        <div>
                          <div className="font-mono text-sm capitalize">
                            {provider.provider}
                          </div>
                          {provider.error && (
                            <div className="text-xs text-red-400 mt-1">
                              {provider.error.slice(0, 60)}...
                            </div>
                          )}
                        </div>
                      </div>

                      <div className="flex items-center gap-2">
                        {provider.response_time_ms && (
                          <Badge variant="outline" className="text-xs">
                            <Clock className="w-3 h-3 mr-1" />
                            {provider.response_time_ms}ms
                          </Badge>
                        )}
                        <Badge
                          variant={provider.available ? 'default' : 'destructive'}
                          className="text-xs"
                        >
                          {provider.available ? 'Available' : 'Offline'}
                        </Badge>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </TabsContent>

          {/* MCP Tools Tab */}
          <TabsContent value="tools" className="space-y-3">
            <div className="grid md:grid-cols-2 gap-3">
              {/* Tool List */}
              <div className="space-y-2">
                <div className="text-xs font-mono text-zinc-400 mb-2">
                  Available Tools ({tools.length})
                </div>
                {tools.map((tool) => (
                  <Card
                    key={tool.name}
                    className={`bg-zinc-900/30 border-white/[0.04]/50 cursor-pointer hover:border-blue-500/50 transition-colors ${
                      selectedTool?.name === tool.name ? 'border-blue-500/50 bg-blue-900/10' : ''
                    }`}
                    onClick={() => {
                      setSelectedTool(tool);
                      setToolResult(null);
                      // Set default args based on schema
                      const defaultArgs: any = {};
                      if (tool.inputSchema?.properties) {
                        Object.keys(tool.inputSchema.properties).forEach(key => {
                          if (tool.inputSchema.required?.includes(key)) {
                            defaultArgs[key] = '';
                          }
                        });
                      }
                      setToolArgs(JSON.stringify(defaultArgs, null, 2));
                    }}
                  >
                    <CardContent className="py-2 px-3">
                      <div className="font-mono text-sm text-blue-400">
                        {tool.name}
                      </div>
                      <div className="text-xs text-zinc-400 mt-1">
                        {tool.description}
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>

              {/* Tool Execution */}
              <div className="space-y-2">
                {selectedTool ? (
                  <>
                    <div className="text-xs font-mono text-zinc-400 mb-2">
                      Execute: {selectedTool.name}
                    </div>
                    <textarea
                      className="w-full h-32 bg-zinc-900/50 border border-white/[0.04] rounded-md p-2 text-xs font-mono text-zinc-300 focus:outline-none focus:border-blue-500/50"
                      placeholder="Tool arguments (JSON)"
                      value={toolArgs}
                      onChange={(e) => setToolArgs(e.target.value)}
                    />
                    <Button
                      onClick={executeTool}
                      disabled={executing}
                      className="w-full"
                      size="sm"
                    >
                      {executing ? (
                        <>
                          <Activity className="w-3 h-3 mr-1 animate-spin" />
                          Executing...
                        </>
                      ) : (
                        <>
                          <Play className="w-3 h-3 mr-1" />
                          Execute Tool
                        </>
                      )}
                    </Button>

                    {toolResult && (
                      <Card className="bg-zinc-900/50 border-white/[0.04]/50 mt-2">
                        <CardContent className="py-2 px-3">
                          <div className="text-xs font-mono text-zinc-400 mb-1">Result:</div>
                          <pre className="text-xs text-zinc-300 overflow-auto max-h-48">
                            {JSON.stringify(toolResult, null, 2)}
                          </pre>
                        </CardContent>
                      </Card>
                    )}
                  </>
                ) : (
                  <div className="text-xs text-zinc-500 text-center py-8">
                    Select a tool to execute
                  </div>
                )}
              </div>
            </div>
          </TabsContent>

          {/* Audit Log Tab */}
          <TabsContent value="audit">
            <ScrollArea className="h-72">
              <div className="space-y-2">
                {auditLog.map((entry, idx) => (
                  <Card
                    key={idx}
                    className={`bg-zinc-900/30 ${
                      entry.verdict === 'ALLOWED'
                        ? 'border-green-500/30'
                        : 'border-red-500/30'
                    }`}
                  >
                    <CardContent className="py-2 px-3">
                      <div className="flex items-start justify-between gap-2">
                        <div className="flex-1 min-w-0">
                          <div className="flex items-center gap-2 mb-1">
                            <Badge
                              variant={entry.verdict === 'ALLOWED' ? 'default' : 'destructive'}
                              className="text-xs"
                            >
                              {entry.verdict}
                            </Badge>
                            <span className="text-xs text-zinc-400 font-mono">
                              {entry.operation}
                            </span>
                            {entry.zone && (
                              <Badge variant="outline" className="text-xs">
                                {entry.zone}
                              </Badge>
                            )}
                          </div>
                          <div className="text-xs text-zinc-300 font-mono truncate">
                            {entry.path}
                          </div>
                          {entry.reason && (
                            <div className="text-xs text-zinc-500 mt-1">
                              {entry.reason}
                            </div>
                          )}
                        </div>
                        <div className="text-xs text-zinc-500 whitespace-nowrap">
                          {new Date(entry.timestamp).toLocaleTimeString()}
                        </div>
                      </div>
                    </CardContent>
                  </Card>
                ))}
              </div>
            </ScrollArea>
          </TabsContent>

          {/* Statistics Tab */}
          <TabsContent value="stats" className="space-y-4">
            {stats && (
              <>
                {/* Bifrost Stats */}
                <Card className="bg-white/[0.02] border-white/[0.04] rounded-lg">
                  <CardHeader className="py-3 px-4">
                    <CardTitle className="text-sm font-mono flex items-center gap-2">
                      <Zap className="w-4 h-4 text-yellow-400" />
                      Bifrost Gateway
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="py-2 px-4 space-y-2">
                    <div className="flex justify-between text-sm">
                      <span className="text-zinc-400">Total Requests:</span>
                      <span className="font-mono text-zinc-200">
                        {stats.bifrost.total_requests}
                      </span>
                    </div>
                    <div className="space-y-1">
                      <div className="text-xs text-zinc-500">By Provider:</div>
                      {Object.entries(stats.bifrost.by_provider).map(([provider, count]) => (
                        <div key={provider} className="flex justify-between text-xs">
                          <span className="text-zinc-400 capitalize">{provider}:</span>
                          <span className="font-mono text-zinc-300">{count}</span>
                        </div>
                      ))}
                    </div>
                  </CardContent>
                </Card>

                {/* E2B Stats */}
                <Card className="bg-white/[0.02] border-white/[0.04] rounded-lg">
                  <CardHeader className="py-3 px-4">
                    <CardTitle className="text-sm font-mono flex items-center gap-2">
                      <Database className="w-4 h-4 text-purple-400" />
                      E2B Sandboxes
                    </CardTitle>
                  </CardHeader>
                  <CardContent className="py-2 px-4 space-y-2">
                    <div className="flex justify-between text-sm">
                      <span className="text-zinc-400">Total Executions:</span>
                      <span className="font-mono text-zinc-200">
                        {stats.e2b.total_executions}
                      </span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-zinc-400">Active Sandboxes:</span>
                      <span className="font-mono text-zinc-200">
                        {stats.e2b.active_sandboxes}
                      </span>
                    </div>
                    <div className="flex justify-between text-sm">
                      <span className="text-zinc-400">Avg Duration:</span>
                      <span className="font-mono text-zinc-200">
                        {stats.e2b.avg_duration_ms}ms
                      </span>
                    </div>
                  </CardContent>
                </Card>
              </>
            )}
          </TabsContent>
        </Tabs>
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from 'react';
import { 
    Zap, 
    TrendingUp, 
    AlertCircle, 
    ExternalLink, 
    RefreshCw, 
    Search,
    ShieldCheck,
    History
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useSystemSignalStore } from '../../store/systemSignalStore';
import { useShallow } from 'zustand/react/shallow';

interface BuyAlert {
    id: string;
    title: string;
    priceEur: number;
    estimatedValueEur: number;
    discountPct: number;
    score: number;
    source: string;
    url: string;
    timestamp: string;
    category: string;
    severity: 'critical' | 'warning';
}

export function MachineHunterWidget() {
    const [isHunting, setIsHunting] = useState(false);
    const { socket } = useSocket();
    
    const { alerts, clearAlerts } = useSystemSignalStore(useShallow((state) => ({
        alerts: state.machineAlerts,
        clearAlerts: state.clearMachineAlerts
    })));

    // Toast notification for new alerts (since we removed local handling)
    useEffect(() => {
        if (!socket) return;

        const handleNewAlert = (alert: BuyAlert) => {
            if (alert.severity === 'critical') {
                toast.error(`🔥 PROFIT LEHETŐSÉG: ${alert.title}`, {
                    description: `${alert.priceEur} EUR (${alert.discountPct}% diszkont!)`,
                    duration: 10000
                });
            } else {
                toast.success(`Új gép találat: ${alert.title}`);
            }
        };

        socket.on('machine:alert', handleNewAlert);
        return () => {
            socket.off('machine:alert', handleNewAlert);
        };
    }, [socket]);

    const handleStartHunt = async () => {
        setIsHunting(true);
