/**
 * Gold Protocol G7.3 UI: Model Router Panel
 *
 * Model routing decisions és profile viewer
 */

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { Broadcast, ChartBar } from '@phosphor-icons/react';

interface ModelProfile {
  model: string;
  specialties: string[];
  costPerToken: number;
  fallback?: string;
}

interface RoutingDecision {
  timestamp: string;
  task: string;
  category: string;
  selectedModel: string;
  reason: string;
}

interface RouterStats {
  byModel: Record<string, number>;
  byCategory: Record<string, Record<string, number>>;
}

export function ModelRouterPanel() {
  const [models, setModels] = useState<ModelProfile[]>([]);
  const [decisions, setDecisions] = useState<RoutingDecision[]>([]);
  const [stats, setStats] = useState<RouterStats | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAll();
    const interval = setInterval(fetchAll, 8000); // Auto-refresh 8s
    return () => clearInterval(interval);
  }, []);

  const fetchAll = async () => {
    try {
      const [modelsRes, decisionsRes, statsRes] = await Promise.all([
        fetch('/api/router/models'),
        fetch('/api/router/decisions'),
        fetch('/api/router/stats'),
      ]);
      const modelsData = await modelsRes.json();
      const decisionsData = await decisionsRes.json();
      const statsData = await statsRes.json();
      setModels(modelsData.models || []);
      setDecisions(decisionsData.decisions || []);
      setStats(statsData);
      setLoading(false);
    } catch (e) {
      console.error('Failed to fetch router data:', e);
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Model Router</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-gray-500">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-4">
      {/* Model Profiles */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Broadcast className="w-5 h-5" />
            Model Profiles ({models.length})
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
            {models.map((model) => (
              <div key={model.model} className="p-4 border rounded-lg">
                <div className="font-semibold text-lg mb-2">{model.model}</div>
                <div className="text-xs text-gray-600 mb-2">
                  Cost: <span className="font-mono">${model.costPerToken}</span>/token
                </div>
                <div className="flex flex-wrap gap-1 mb-2">
                  {model.specialties.map((spec) => (
                    <Badge key={spec} className="bg-blue-500 text-xs">
                      {spec}
                    </Badge>
                  ))}
                </div>
                {model.fallback && (
                  <div className="text-xs text-gray-500">Fallback: {model.fallback}</div>
                )}
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Recent Decisions */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <ChartBar className="w-5 h-5" />
            Recent Routing Decisions ({decisions.length})
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 max-h-[400px] overflow-y-auto">
            {decisions.map((dec, idx) => (
              <div key={idx} className="p-3 border rounded-lg">
                <div className="flex items-center justify-between mb-1">
                  <div className="flex items-center gap-2">
                    <Badge className="bg-green-500">{dec.selectedModel}</Badge>
                    <Badge variant="outline">{dec.category}</Badge>
                  </div>
                  <span className="text-xs text-gray-500">{new Date(dec.timestamp).toLocaleString()}</span>
                </div>
                <div className="text-xs text-gray-600 font-mono mb-1">{dec.task.slice(0, 100)}...</div>
                <div className="text-xs text-blue-600">{dec.reason}</div>
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Statistics */}
      {stats && (
        <Card>
          <CardHeader>
            <CardTitle>Router Statistics</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* By Model */}
              <div>
                <h4 className="text-sm font-semibold mb-2">Usage by Model</h4>
                <div className="space-y-1">
                  {Object.entries(stats.byModel).map(([model, count]) => (
                    <div key={model} className="flex items-center justify-between p-2 border rounded">
                      <span className="text-sm">{model}</span>
                      <Badge>{count}</Badge>
                    </div>
                  ))}
                </div>
              </div>

              {/* By Category */}
              <div>
                <h4 className="text-sm font-semibold mb-2">Usage by Category</h4>
                <div className="space-y-1">
                  {Object.entries(stats.byCategory).map(([category, modelCounts]) => (
                    <div key={category} className="p-2 border rounded">
                      <div className="text-sm font-semibold mb-1">{category}</div>
                      <div className="flex gap-2 flex-wrap">
                        {Object.entries(modelCounts).map(([model, count]) => (
                          <Badge key={model} variant="outline" className="text-xs">
                            {model}: {count}
                          </Badge>
                        ))}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

/**
 * NeuralCommandWidget - Natural Language Task Execution
 *
 * Magyar nyelvű parancs doboz az Enterprise Orchestrator számára.
 * Természetes nyelven írt feladatokat küld az /api/enterprise/execute endpoint-ra.
 *
 * @track cloudflare_workers_ai_20260221
 * @phase Natural Language Task Routing - Dashboard
 */

import { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Textarea } from '@/components/ui/textarea';
import { Badge } from '@/components/ui/badge';
import { toast } from 'sonner';
import { Zap, Loader2, CheckCircle, AlertCircle } from 'lucide-react';

interface ExecutionResult {
    status: string;
    result: any;
    executedAt: string;
}

export function NeuralCommandWidget() {
    const [command, setCommand] = useState('');
    const [executing, setExecuting] = useState(false);
    const [lastResult, setLastResult] = useState<ExecutionResult | null>(null);

    const predefinedTasks = [
        { icon: '🔍', label: 'Projekt Státusz', value: 'Ellenőrizd a projekt státuszát és add meg a track-ek összefoglalóját' },
        { icon: '📊', label: 'Tesztek Futtatása', value: 'Futtasd le az összes tesztet és készíts összefoglalót' },
        { icon: '🌐', label: 'Webes Kutatás', value: 'Keress rá az AI fejlesztések legfrissebb híreire' },
        { icon: '💻', label: 'Kód Generálás', value: 'Készíts Python scriptet CSV fájl beolvasására és elemzésére' },
    ];

    const handleExecute = async () => {
        if (!command.trim()) {
            toast.error('Írd le a feladatot!');
            return;
        }

        setExecuting(true);
        setLastResult(null);

        try {
            const response = await fetch('/api/enterprise/execute', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    task: command.trim(),
                    context: {},
                }),
            });

            const text = await response.text();
            const data = text ? JSON.parse(text) : {};

            if (!response.ok) {
                throw new Error(data.error || `HTTP ${response.status}`);
            }

            setLastResult(data);

            if (data.status === 'success') {
                toast.success('Feladat végrehajtva!', {
                    description: formatResultPreview(data.result),
                });
            } else {
                toast.error('Hiba történt', {
                    description: data.error || 'Ismeretlen hiba',
                });
            }
        } catch (error: any) {
            toast.error('API hiba', {
                description: error.message,
            });
            console.error('Execution error:', error);
        } finally {
            setExecuting(false);
        }
    };

    const handlePredefined = (value: string) => {
        setCommand(value);
    };

    const formatResultPreview = (result: any): string => {
        if (typeof result === 'string') {
            return result.substring(0, 100);
        }

        if (result?.message) {
            return result.message.substring(0, 100);
        }

        return 'Sikeresen végrehajtva';
    };

    const formatResultDisplay = (result: any): string => {
        if (typeof result === 'string') {
            return result;
        }

        if (result?.status && result?.message) {
            return `${result.status}: ${result.message}`;
        }

        return JSON.stringify(result, null, 2);
    };

    const formatTimestamp = (timestamp: string): string => {
        const date = new Date(timestamp);
        return date.toLocaleString('hu-HU');
    };

    return (
        <Card className="col-span-full">
            <CardHeader>
                <div className="flex items-center justify-between">
                    <div className="flex items-center gap-2">
                        <Zap className="h-5 w-5 text-blue-500" />
                        <CardTitle>Magyar Parancs Végrehajtás</CardTitle>
                    </div>
                    <Badge variant="outline" className="bg-blue-50 text-blue-700 dark:bg-blue-900/20">
                        Neural Router
                    </Badge>
                </div>
            </CardHeader>
            <CardContent className="space-y-4">
                {/* Command Input */}
                <div className="space-y-2">
                    <Textarea
                        placeholder="Írd le magyarul a feladatot... (pl. 'Keress rá az AI hírekre')"
                        value={command}
                        onChange={(e) => setCommand(e.target.value)}
                        onKeyDown={(e) => {
                            if (e.key === 'Enter' && e.ctrlKey) {
                                e.preventDefault();
                                handleExecute();
                            }
                        }}
                        className="min-h-[80px] resize-none"
                        disabled={executing}
                    />
                    <div className="flex items-center justify-between text-sm text-zinc-500">
                        <span>Ctrl + Enter küldés</span>
                        <span>{command.length} karakter</span>
                    </div>
                </div>

                {/* Predefined Tasks */}
                <div className="space-y-2">
                    <p className="text-sm text-zinc-500">Gyors parancsok:</p>
                    <div className="flex flex-wrap gap-2">
                        {predefinedTasks.map((task, index) => (
                            <Button
                                key={index}
                                variant="outline"
                                size="sm"
                                onClick={() => handlePredefined(task.value)}
                                disabled={executing}
                                className="text-sm"
                            >
                                <span className="mr-1">{task.icon}</span>
                                {task.label}
                            </Button>
                        ))}
                    </div>
                </div>

                {/* Execute Button */}
                <Button
                    onClick={handleExecute}
                    disabled={executing || !command.trim()}
                    className="w-full"
                >
                    {executing ? (
                        <>
                            <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                            Végrehajtás folyamatban...
                        </>
                    ) : (
                        <>
                            <Zap className="mr-2 h-4 w-4" />
                            Feladat Végrehajtása
                        </>
                    )}
                </Button>

                {/* Last Result */}
                {lastResult && (
                    <div className="space-y-2 rounded-lg border p-4">
                        <div className="flex items-center gap-2">
                            {lastResult.status === 'success' ? (
                                <>
                                    <CheckCircle className="h-4 w-4 text-green-500" />
                                    <span className="font-medium text-green-700 dark:text-green-400">
                                        Sikeres végrehajtás
                                    </span>
                                </>
                            ) : (
                                <>
                                    <AlertCircle className="h-4 w-4 text-red-500" />
                                    <span className="font-medium text-red-700 dark:text-red-400">
                                        Hiba történt
                                    </span>
                                </>
                            )}
                            <span className="ml-auto text-xs text-zinc-500">
                                {formatTimestamp(lastResult.executedAt)}
                            </span>
                        </div>

                        <div className="rounded bg-muted/50 p-3">
                            <pre className="whitespace-pre-wrap text-sm">
                                {formatResultDisplay(lastResult.result)}
                            </pre>
                        </div>
                    </div>
                )}

                {/* Info Banner */}
                <div className="rounded-lg border border-blue-200 bg-blue-50 p-3 dark:border-blue-900 dark:bg-blue-900/20">
                    <p className="text-sm text-blue-700 dark:text-blue-400">
                        <strong>ℹ️ Használat:</strong> Írj bármilyen feladatot magyarul, az OrchestratorAgent
                        automatikusan irányít a megfelelő ügynökhöz (Robotkéz, Developer, Researcher, stb.)
                    </p>
                </div>
            </CardContent>
        </Card>
    );
}

/**
 * Neural Link Chat - Mission Control 2.0
 * Orchestratorral vagy Ollamával kommunikáció
 * - Orchestrator: executeAgent("Orchestrator", task) – delegálás, tervezés
 * - Ollama: közvetlen LLM generálás
 */

import { useState, useRef, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { PaperPlaneRight, Robot, User, Circle, Eye, EyeSlash, ArrowsClockwise, Microphone, SpeakerHigh } from "@phosphor-icons/react";
import { Brain, FileText } from "lucide-react";
import * as api from "@/lib/apiService";
import { toast } from "sonner";
import { buildConversationPrompt } from "@/lib/chat/contextBuilder";
import { getProvider } from "@/lib/chat/providerRegistry";
import { loadChatSession, saveChatSession } from "@/lib/chat/sessionStore";
import { LiveExecutionMonitor } from "@/components/dashboard/LiveExecutionMonitor";
import type { ChatMessage as Message, ChatMode } from "@/lib/chat/types";

export function NeuralLinkChat() {
  const [messages, setMessages] = useState<Message[]>(() => {
    const restored = loadChatSession();
    return restored?.messages ?? [];
  });
  const [input, setInput] = useState("");
  const [showBrowser, setShowBrowser] = useState(false);
  const [browserTimestamp, setBrowserTimestamp] = useState(Date.now());
  useEffect(() => {
    if (showBrowser) {
      const interval = setInterval(() => setBrowserTimestamp(Date.now()), 1500);
      return () => clearInterval(interval);
    }
  }, [showBrowser]);
  const [mode, setMode] = useState<ChatMode>(() => {
    const restored = loadChatSession();
    return restored?.mode ?? "orchestrator";
  });
  const [models, setModels] = useState<{ name: string }[]>([]);
  const [selectedModel, setSelectedModel] = useState<string>(() => {
    const restored = loadChatSession();
    return restored?.selectedModel ?? "";
  });
  const [ghModels, setGhModels] = useState<
    { name: string; provider: string }[]
  >([]);
  const [selectedGhModel, setSelectedGhModel] = useState<string>(() => {
    const restored = loadChatSession();
    return restored?.selectedGhModel ?? "";
  });
  const [geminiModels, setGeminiModels] = useState<{ name: string }[]>([]);
  const [selectedGeminiModel, setSelectedGeminiModel] = useState<string>(() => {
    const restored = loadChatSession();
    return restored?.selectedGeminiModel ?? "";
  });
  const [isLoading, setIsLoading] = useState(false);
  const [activeAgents, setActiveAgents] = useState<{name: string, task: string}[]>([]);
  const [expandedThoughts, setExpandedThoughts] = useState<
    Record<number, boolean>
  >({});

  // Fetch active tasks periodically
  useEffect(() => {
    const interval = setInterval(() => {
      api.getActiveTasks().then(tasks => {
        const agents = tasks.map((t: any) => ({ name: t.agent, task: t.description }));
        setActiveAgents(agents);
      }).catch(() => {});
    }, 2000);
    return () => clearInterval(interval);
  }, []);
  const [edgeStatus, setEdgeStatus] = useState<{
    enabled: boolean;
    healthy: boolean;
  } | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    api
      .getOllamaModels()
      .then((list) => {
        setModels(list);
        if (list.length > 0) {
          setSelectedModel((prev) => prev || list[0].name);
        }
      })
      .catch(() => setModels([]));
    api
      .getGithubModels()
      .then((list) => {
        setGhModels(list);
        if (list.length > 0) {
          setSelectedGhModel((prev) => prev || list[0].name);
        }
      })
      .catch(() => setGhModels([]));
    api
      .getGeminiModels()
      .then((list) => {
        setGeminiModels(list);
        if (list.length > 0) {
          setSelectedGeminiModel((prev) => prev || list[0].name);
        }
      })
      .catch(() => setGeminiModels([]));

    // Fetch Edge status for connection indicator
    api
      .getCloudflareStatus()
      .then((status) => {
        setEdgeStatus(status.status);
      })
      .catch(() => setEdgeStatus({ enabled: false, healthy: false }));
  }, []);

  useEffect(() => {
    const timer = setTimeout(() => {
      saveChatSession({
        messages,
        mode,
        selectedModel,
        selectedGhModel,
        selectedGeminiModel,
      });
    }, 300);

    return () => clearTimeout(timer);
  }, [messages, mode, selectedModel, selectedGhModel, selectedGeminiModel]);

  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages]);

  const toggleThoughts = (index: number) => {
    setExpandedThoughts((prev) => ({ ...prev, [index]: !prev[index] }));
  };

  const send = async () => {
    const text = input.trim();
    if (!text || isLoading) return;

    setInput("");
    const userMsgTimestamp = Date.now();
    setMessages((prev) => [
      ...prev,
      { role: "user", content: text, timestamp: userMsgTimestamp },
    ]);
    setIsLoading(true);

    try {
      const conversationPrompt = buildConversationPrompt(messages, text);
      const provider = getProvider(mode);
      const response = await provider.send({
        text,
        history: messages,
        conversationPrompt,
        selectedModel,
        selectedGhModel,
        selectedGeminiModel,
      });

      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: response.message,
          timestamp: Date.now(),
          thoughts: response.thoughts,
          contextUsed: response.contextUsed,
          executedBy: response.executedBy,
          screenshot: response.screenshot,
        },
      ]);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : "Generálás sikertelen";
      toast.error(msg);
      setMessages((prev) => [
        ...prev,
        {
          role: "assistant",
          content: `⚠️ Hiba: ${msg}`,
          timestamp: Date.now(),
