    taskId?: number;
}

interface ChatMessage {
    role: 'user' | 'assistant';
    content: string;
    timestamp: number;
    plan?: PlanStep[];
    taskIds?: number[];
    actionsTriggered?: ActionTriggered[];
    provider?: string;
    model?: string;
    roleLabel?: string;
    thinkingMs?: number;
    suggestions?: string[];
    missionTimeline?: MissionTimelineEntry[];
    approvalRequired?: boolean;
    approvalId?: string;
    riskLevel?: 'low' | 'high';
    runbookHint?: string;
    fallbackUsed?: boolean;
    fallbackReason?: string;
    phoenixTriggered?: boolean;
    error?: boolean;
}

interface PaiosChatResponse {
    success?: boolean;
    summary?: string;
    reply?: string;
    plan?: PlanStep[];
    taskIds?: number[];
    actionsTriggered?: ActionTriggered[];
    provider?: string;
    model?: string;
    role?: string;
    thinkingMs?: number;
    sessionId?: string;
    suggestions?: string[];
    missionTimeline?: MissionTimelineEntry[];
    approvalRequired?: boolean;
    approvalId?: string;
    riskLevel?: 'low' | 'high';
    runbookHint?: string;
    fallbackUsed?: boolean;
    fallbackReason?: string;
    phoenixTriggered?: boolean;
    error?: string;
}

type ModelProvider = 'gemini' | 'github' | 'ollama' | 'anthropic' | 'cloudflare' | 'copilot';

interface BrowserSpeechRecognitionResultEvent {
    results: ArrayLike<ArrayLike<{ transcript: string }>>;
}

interface BrowserSpeechRecognition {
    lang: string;
    interimResults: boolean;
    maxAlternatives: number;
    onstart: (() => void) | null;
    onresult: ((event: BrowserSpeechRecognitionResultEvent) => void) | null;
    onerror: (() => void) | null;
    onend: (() => void) | null;
    start: () => void;
}

interface SpeechRecognitionCapableWindow extends Window {
    SpeechRecognition?: new () => BrowserSpeechRecognition;
    webkitSpeechRecognition?: new () => BrowserSpeechRecognition;
}

interface ProviderVisual {
    label: string;
    icon: typeof Brain;
    color: string;
    defaultModel: string;
    fallbackModels: string[];
}

const PROVIDER_VISUALS: Record<ModelProvider, ProviderVisual> = {
    github: {
        label: 'GitHub Models',
        icon: Cloud,
        color: 'text-purple-500',
        defaultModel: 'gpt-4.1',
        fallbackModels: ['gpt-4.1', 'gpt-4.1-mini', 'gpt-4o', 'o3-mini', 'o1-mini'],
    },
    gemini: {
        label: 'Google Gemini',
        icon: Brain,
        color: 'text-blue-500',
        defaultModel: 'gemini-2.5-flash',
        fallbackModels: ['gemini-2.5-flash', 'gemini-2.5-pro', 'gemini-2.0-flash'],
    },
    anthropic: {
        label: 'Anthropic Claude',
        icon: Zap,
        color: 'text-orange-500',
        defaultModel: 'claude-3-5-sonnet-20241022',
        fallbackModels: ['claude-3-5-sonnet-20241022', 'claude-3-5-haiku-20241022'],
    },
    cloudflare: {
        label: 'Cloudflare AI',
        icon: Cloud,
        color: 'text-cyan-500',
        defaultModel: '@cf/meta/llama-3.3-70b-instruct',
        fallbackModels: ['@cf/meta/llama-3.3-70b-instruct', '@cf/meta/llama-3.1-8b-instruct'],
    },
    ollama: {
        label: 'Ollama Local',
        icon: Cpu,
        color: 'text-green-500',
        defaultModel: 'qwen2.5-coder:7b',
        fallbackModels: ['qwen2.5-coder:7b', 'llama3.1:8b', 'deepseek-r1:8b'],
    },
    copilot: {
        label: 'Copilot CLI',
        icon: Zap,
        color: 'text-yellow-500',
        defaultModel: 'copilot-cli',
        fallbackModels: ['copilot-cli'],
    },
};

const FALLBACK_PROVIDER_CATALOG: LLMCatalogProvider[] = (Object.entries(PROVIDER_VISUALS) as Array<[ModelProvider, ProviderVisual]>).map(([id, visual]) => ({
    id,
    label: visual.label,
    enabled: true,
    defaultModel: visual.defaultModel,
    models: visual.fallbackModels.map((name) => ({
        id: name,
        name,
        provider: id,
        source: 'default' as const,
    })),
}));

function isModelProvider(value: string): value is ModelProvider {
    return value in PROVIDER_VISUALS;
}

const SESSION_STORAGE_KEY = 'paios_orchestrator_session_id';

function createSessionId(): string {
    const randomPart = Math.random().toString(36).slice(2, 10);
    return `dashboard-${Date.now()}-${randomPart}`;
}

export function PAIOSOrchestratorChat() {
    const [messages, setMessages] = useState<ChatMessage[]>([]);
    const [input, setInput] = useState('');
    const [isLoading, setIsLoading] = useState(false);
    const [providerCatalog, setProviderCatalog] = useState<LLMCatalogProvider[]>(FALLBACK_PROVIDER_CATALOG);
    const [selectedProvider, setSelectedProvider] = useState<ModelProvider>('github');
    const [selectedModel, setSelectedModel] = useState<string>(PROVIDER_VISUALS.github.defaultModel);
    const [sessionId, setSessionId] = useState<string>(() => {
        if (typeof window === 'undefined') {
            return createSessionId();
        }

        const existing = window.sessionStorage.getItem(SESSION_STORAGE_KEY);
        if (existing) {
            return existing;
        }

        const generated = createSessionId();
        window.sessionStorage.setItem(SESSION_STORAGE_KEY, generated);
        return generated;
    });
    const scrollRef = useRef<HTMLDivElement>(null);
    const chatContainerRef = useRef<HTMLDivElement>(null);
    const { socket } = useSocket();

    const [isListening, setIsListening] = useState(false);
    const [isSpeaking, setIsSpeaking] = useState(false);
    const [expandedMeta, setExpandedMeta] = useState<Record<number, boolean>>({});
    const audioRef = useRef<HTMLAudioElement | null>(null);

    useEffect(() => {
        let isMounted = true;

        void (async () => {
            try {
                const catalog = await getLLMModelCatalog();
                const supportedProviders = catalog.providers.filter((provider): provider is LLMCatalogProvider & { id: ModelProvider } =>
                    isModelProvider(provider.id) && (provider.enabled || provider.id === 'ollama'),
                );

                if (isMounted && supportedProviders.length > 0) {
                    setProviderCatalog(supportedProviders);
                }
            } catch {
                // Csendes fallback a lokális alaplistára
            }
        })();

        return () => {
            isMounted = false;
        };
    }, []);

    useEffect(() => {
        const providerEntry = providerCatalog.find((provider) => provider.id === selectedProvider);
        if (!providerEntry) {
            setSelectedModel(PROVIDER_VISUALS[selectedProvider].defaultModel);
            return;
        }

        const availableModels = providerEntry.models.map((model) => model.name);
        if (!availableModels.includes(selectedModel)) {
            setSelectedModel(providerEntry.defaultModel || availableModels[0] || PROVIDER_VISUALS[selectedProvider].defaultModel);
        }
    }, [selectedProvider, selectedModel, providerCatalog]);

    const activeProviderCatalog = providerCatalog.find((provider) => provider.id === selectedProvider)
        ?? FALLBACK_PROVIDER_CATALOG.find((provider) => provider.id === selectedProvider)
        ?? FALLBACK_PROVIDER_CATALOG[0];

    const startListening = () => {
        const speechWindow = window as SpeechRecognitionCapableWindow;
        const SpeechRecognition = speechWindow.SpeechRecognition || speechWindow.webkitSpeechRecognition;
        if (!SpeechRecognition) {
            toast.error('A böngésződ nem támogatja a hangfelismerést.');
            return;
        }

        const recognition = new SpeechRecognition();
        recognition.lang = 'hu-HU';
        recognition.interimResults = false;
        recognition.maxAlternatives = 1;

        recognition.onstart = () => {
            setIsListening(true);
            toast.info('Figyelek...');
        };

        recognition.onresult = (event: BrowserSpeechRecognitionResultEvent) => {
            const transcript = event.results[0][0].transcript;
            setInput(transcript);
            toast.success('Sikeres hangfelismerés.');
        };

        recognition.onerror = () => {
            setIsListening(false);
            toast.error('Hiba a hangfelismerés során.');
        };

        recognition.onend = () => {
            setIsListening(false);
        };

        recognition.start();
    };

    const playTTS = async (text: string) => {
        const plainText = text.replace(/[#*_`~\[\]()>|-]/g, '').replace(/\n{2,}/g, '. ').trim();
        if (!plainText) return;

        try {
            setIsSpeaking(true);
            // OpenAI Nova TTS via backend /api/tts (returns audio/mpeg blob)
            const response = await fetch('/api/tts', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    text: plainText.slice(0, 4000),
                    voice: 'nova',
                    model: 'tts-1',
                    speed: 1.0,
                }),
            });

            if (response.ok && response.headers.get('content-type')?.includes('audio')) {
                if (audioRef.current) audioRef.current.pause();
                const audioBlob = await response.blob();
                const audioUrl = URL.createObjectURL(audioBlob);
                const audio = new Audio(audioUrl);
                audioRef.current = audio;
                audio.onended = () => { setIsSpeaking(false); URL.revokeObjectURL(audioUrl); };
                audio.onerror = () => { setIsSpeaking(false); URL.revokeObjectURL(audioUrl); };
                await audio.play();
                toast.success('🎙️ Brunella beszél... (Nova)');
                return;
            }
        } catch {
            // Backend TTS nem elérhető, fallback a böngésző speechSynthesis-re
        }

        // Fallback: böngésző beépített speechSynthesis
        if ('speechSynthesis' in window) {
            window.speechSynthesis.cancel();
            const utterance = new SpeechSynthesisUtterance(plainText.slice(0, 500));
            utterance.lang = 'hu-HU';
            utterance.rate = 1.05;
            utterance.onend = () => setIsSpeaking(false);
            utterance.onerror = () => setIsSpeaking(false);
            window.speechSynthesis.speak(utterance);
        } else {
            setIsSpeaking(false);
        }
    };

    useEffect(() => {
        const container = chatContainerRef.current;
        if (!container) return;
        // Auto-scroll csak ha a user a chat alján van (±80px)
        const isNearBottom = container.scrollHeight - container.scrollTop - container.clientHeight < 80;
        if (isNearBottom) {
            scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
        }
    }, [messages]);

    useEffect(() => {
        if (!socket) return;

        const handleTasksCreated = (data: {
            summary: string;
            taskIds: number[];
            plan: PlanStep[];
            actionsTriggered?: ActionTriggered[];
            timestamp: string;
        }) => {
            toast.success(`✨ ${data.taskIds.length} task delegálva`);
            setMessages((prev) => {
                const updated = [...prev];
                const lastMsg = updated[updated.length - 1];
                if (lastMsg && lastMsg.role === 'assistant') {
                    lastMsg.taskIds = data.taskIds;
                    lastMsg.actionsTriggered = data.actionsTriggered ?? lastMsg.actionsTriggered;
                }
                return updated;
            });
        };

        socket.on('paios:tasks_created', handleTasksCreated);
        return () => {
            socket.off('paios:tasks_created', handleTasksCreated);
        };
    }, [socket]);

    const startNewSession = () => {
        const newSessionId = createSessionId();
        setSessionId(newSessionId);
        setMessages([]);
        if (typeof window !== 'undefined') {
            window.sessionStorage.setItem(SESSION_STORAGE_KEY, newSessionId);
        }
        toast.success('Új operátori session indítva.');
    };

    const sendMessage = async (overrideText?: string) => {
        const text = (overrideText ?? input).trim();
        if (!text || isLoading) return;

        setInput('');
        const userMsg: ChatMessage = {
            role: 'user',
            content: text,
            timestamp: Date.now(),
        };
        setMessages((prev) => [...prev, userMsg]);
        setIsLoading(true);

        try {
            const conversationHistory = messages
                .filter((msg) => !msg.error)
                .map((msg) => ({ role: msg.role, content: msg.content }));

            const response = await fetch('/api/paios/chat', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({
                    message: text,
                    provider: selectedProvider,
                    model: selectedModel,
                    conversationHistory,
                    sessionId,
                }),
            });

            if (!response.ok) {
                throw new Error(`HTTP ${response.status}`);
            }

            const result = (await response.json()) as PaiosChatResponse;

            if (result.success) {
                const assistantReply = result.summary || result.reply || 'A kérés feldolgozva.';
                if (result.sessionId && result.sessionId !== sessionId) {
                    setSessionId(result.sessionId);
                    if (typeof window !== 'undefined') {
                        window.sessionStorage.setItem(SESSION_STORAGE_KEY, result.sessionId);
                    }
                }

                setMessages((prev) => [
                    ...prev,
                    {
                        role: 'assistant',
                        content: assistantReply,
                        timestamp: Date.now(),
                        plan: result.plan,
                        taskIds: result.taskIds,
                        actionsTriggered: result.actionsTriggered,
                        provider: result.provider ?? selectedProvider,
                        model: result.model ?? selectedModel,
                        roleLabel: result.role ?? 'orchestrator',
                        thinkingMs: result.thinkingMs,
                        suggestions: result.suggestions,
                        missionTimeline: result.missionTimeline,
                        approvalRequired: result.approvalRequired,
                        approvalId: result.approvalId,
                        riskLevel: result.riskLevel,
                        runbookHint: result.runbookHint,
                        fallbackUsed: result.fallbackUsed,
                        fallbackReason: result.fallbackReason,
                        phoenixTriggered: result.phoenixTriggered,
                    },
                ]);
                if (result.approvalRequired) {
                    toast.warning('Jóváhagyás szükséges a high-risk végrehajtáshoz.');
                }
                toast.success('✅ Orchestrator válaszolt');
                void playTTS(assistantReply);
            } else {
                throw new Error(result.error || 'Unknown error');
            }
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : 'Hiba történt';
            toast.error(`❌ ${msg}`);
            setMessages((prev) => [
                ...prev,
                {
                    role: 'assistant',
                    content: `❌ Hiba: ${msg}`,
                    timestamp: Date.now(),
                    error: true,
                },
            ]);
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Card className="h-full flex flex-col">
            <CardHeader className="border-b py-3 px-4">
                <div className="flex items-center justify-between gap-2">
                    <CardTitle className="flex items-center gap-2 text-base">
                        <Brain className="w-4 h-4 text-blue-500" />
                        PAIOS Chat
                    </CardTitle>
                    <div className="flex flex-wrap items-center gap-1 justify-end">
                        <Button
                            variant="outline"
                            size="sm"
                            className="gap-1 h-7"
                            title="Új session"
                            onClick={ startNewSession }
                        >
                            <RefreshCw className="w-3 h-3" />
                            <span className="hidden sm:inline text-xs">Új session</span>
                        </Button>
                        { providerCatalog.map((provider) => {
                            const visual = PROVIDER_VISUALS[provider.id as ModelProvider];
                            const Icon = visual.icon;
                            const isActive = selectedProvider === provider.id;
                            return (
                                <Button
                                    key={ provider.id }
                                    variant={ isActive ? 'default' : 'outline' }
                                    size="sm"
                                    onClick={ () => setSelectedProvider(provider.id as ModelProvider) }
                                    className="gap-1 h-7"
                                    title={ provider.label }
                                >
                                    <Icon className={ `w-3 h-3 ${isActive ? 'text-white' : visual.color}` } />
                                    <span className="hidden sm:inline text-xs">{ provider.label.split(' ')[0] }</span>
                                </Button>
                            );
                        }) }
                        <select
                            value={ selectedModel }
                            onChange={ (e) => setSelectedModel(e.target.value) }
                            className="h-7 rounded-md border bg-background px-2 text-xs"
                            title="Model választás"
                        >
                            { activeProviderCatalog.models.map((model) => (
                                <option key={ model.id } value={ model.name }>
                                    { model.name }
                                </option>
                            )) }
                        </select>
                    </div>
                </div>
                <div className="flex items-center gap-3 mt-1">
                    <p className="text-[10px] text-zinc-500">
                        magyar kérés → tool calling → agent delegálás
                    </p>
                    <p className="text-[10px] text-zinc-600">
                        Session: <span className="font-mono">{ sessionId.slice(-12) }</span>
                    </p>
                </div>
            </CardHeader>

            <CardContent className="flex-1 flex flex-col p-0 overflow-hidden min-h-0">
                <div ref={ chatContainerRef } className="flex-1 overflow-y-auto p-3 scroll-smooth">
                    <div className="space-y-3">
                        { messages.length === 0 && (
                            <div className="text-center text-zinc-500 py-16">
                                <Brain className="w-10 h-10 mx-auto mb-3 opacity-30" />
                                <p className="text-sm font-medium">Adj egy feladatot magyarul...</p>
                                <p className="text-xs mt-1 opacity-60">Példa: "Készíts egy új API endpointot TDD-vel"</p>
                            </div>
                        ) }

                        { messages.map((msg, idx) => (
                            <div key={ idx } className={ `flex gap-3 ${msg.role === 'user' ? 'justify-end' : 'justify-start'}` }>
                                { msg.role === 'assistant' && (
                                    <div className="w-8 h-8 rounded-full bg-blue-500 flex items-center justify-center flex-shrink-0">
                                        <Bot className="w-4 h-4 text-white" />
                                    </div>
                                ) }

                                <div
                                    className={ `max-w-[80%] rounded-lg p-3 ${msg.role === 'user'
                                        ? 'bg-primary text-primary-foreground'
                                        : msg.error
                                            ? 'bg-red-100 dark:bg-red-950 border border-red-300 dark:border-red-800'
                                            : 'bg-muted'
                                        }` }
                                >
                                    { msg.role === 'user' ? (
                                        <p className="text-sm whitespace-pre-wrap">{ msg.content }</p>
                                    ) : (
                                        <div
                                            className="text-sm prose prose-sm dark:prose-invert prose-p:my-1 prose-headings:my-2 prose-ul:my-1 prose-ol:my-1 prose-li:my-0.5 max-w-none [&_hr]:my-2"
                                            dangerouslySetInnerHTML={ { __html: renderMarkdown(msg.content) } }
                                        />
                                    ) }

                                    { msg.role === 'assistant' && (
                                        <div className="mt-2 flex flex-wrap items-center gap-1 text-xs opacity-75">
                                            { msg.provider && <Badge variant="outline" className="text-[10px]">{ msg.provider }</Badge> }
                                            { msg.model && <Badge variant="outline" className="text-[10px]">{ msg.model }</Badge> }
                                            { typeof msg.thinkingMs === 'number' && <span>⏱️ { msg.thinkingMs } ms</span> }
                                        </div>
                                    ) }

                                    { msg.role === 'assistant' && msg.approvalRequired && msg.approvalId && (
                                        <div className="mt-2 flex flex-wrap gap-1 border-t pt-2">
                                            <Button
                                                variant="default"
                                                size="sm"
                                                className="h-6 px-2 text-[10px]"
                                                onClick={ () => void sendMessage(`jóváhagyom ${msg.approvalId}`) }
                                            >
                                                ✅ Jóváhagyom { msg.approvalId }
                                            </Button>
                                            <Button
                                                variant="outline"
                                                size="sm"
                                                className="h-6 px-2 text-[10px]"
                                                onClick={ () => void sendMessage('elutasítom') }
                                            >
                                                ❌ Elutasítom
                                            </Button>
                                        </div>
                                    ) }

                                    { msg.role === 'assistant' && msg.suggestions && msg.suggestions.length > 0 && (
                                        <div className="mt-2 flex flex-wrap gap-1">
                                            { msg.suggestions.slice(0, 4).map((suggestion, suggestionIndex) => (
                                                <Button
                                                    key={ `${idx}-suggestion-${suggestionIndex}` }
                                                    variant="outline"
                                                    size="sm"
                                                    className="h-6 px-2 text-[10px]"
                                                    onClick={ () => void sendMessage(suggestion) }
                                                >
                                                    { suggestion }
                                                </Button>
                                            )) }
                                        </div>
                                    ) }

                                    { /* Összecsukható részletek (timeline, plan, tasks) */ }
                                    { msg.role === 'assistant' && (msg.missionTimeline?.length || msg.plan?.length || msg.taskIds?.length || msg.runbookHint || msg.actionsTriggered?.length) && (
                                        <div className="mt-2 border-t pt-1">
                                            <button
                                                onClick={ () => setExpandedMeta((prev) => ({ ...prev, [idx]: !prev[idx] })) }
                                                className="flex items-center gap-1 text-[10px] text-zinc-400 hover:text-zinc-200 transition-colors"
                                            >
                                                { expandedMeta[idx] ? <ChevronUp className="w-3 h-3" /> : <ChevronDown className="w-3 h-3" /> }
                                                Részletek
                                                { msg.runbookHint && <span className="opacity-60 ml-1">| 📚 { msg.runbookHint }</span> }
                                            </button>

                                            { expandedMeta[idx] && (
                                                <div className="mt-1 space-y-1 text-xs animate-in slide-in-from-top-1 duration-200">
                                                    { msg.fallbackUsed && (
                                                        <p className="opacity-80">
                                                            ♻️ Fallback{ msg.fallbackReason ? ` (${msg.fallbackReason})` : '' }
                                                        </p>
                                                    ) }

                                                    { msg.missionTimeline && msg.missionTimeline.length > 0 && (
                                                        <div className="space-y-0.5">
                                                            <p className="font-semibold opacity-75">🧭 Mission Timeline</p>
                                                            { msg.missionTimeline.slice(-8).map((entry, timelineIndex) => (
                                                                <div key={ `${idx}-timeline-${timelineIndex}` } className="flex items-start gap-2">
                                                                    <Badge variant="outline" className="text-[10px] shrink-0">{ entry.phase }</Badge>
                                                                    <span className="opacity-80">[{ entry.status }] { entry.detail }</span>
                                                                </div>
                                                            )) }
                                                        </div>
                                                    ) }

                                                    { msg.plan && msg.plan.length > 0 && (
                                                        <div className="space-y-1">
                                                            <p className="font-semibold opacity-70">📋 Execution Plan</p>
                                                            { msg.plan.map((step, i) => (
                                                                <div key={ i } className="flex items-start gap-2">
                                                                    <Badge variant="outline" className="shrink-0">{ step.phase }</Badge>
                                                                    <div className="flex-1">
                                                                        <span className="font-medium">{ step.agent }</span>
                                                                        <span className="opacity-70"> → { step.task }</span>
                                                                    </div>
                                                                </div>
                                                            )) }
                                                        </div>
                                                    ) }

                                                    { msg.taskIds && msg.taskIds.length > 0 && (
                                                        <div className="flex flex-wrap gap-1">
                                                            <span className="opacity-70">🎯 Tasks:</span>
                                                            { msg.taskIds.map((id) => (
                                                                <Badge key={ id } variant="secondary" className="text-xs">#{ id }</Badge>
                                                            )) }
                                                        </div>
                                                    ) }

                                                    { msg.actionsTriggered && msg.actionsTriggered.length > 0 && (
                                                        <div className="space-y-0.5">
                                                            <p className="opacity-70">🤖 Delegált műveletek:</p>
                                                            { msg.actionsTriggered.map((action) => (
                                                                <div key={ `${action.agent}-${action.taskId}` } className="flex items-center justify-between gap-2">
                                                                    <span className="truncate">
                                                                        <strong>{ action.agent }</strong>: { action.task }
                                                                    </span>
                                                                    <Badge variant="secondary" className="text-[10px]">#{ action.taskId }</Badge>
                                                                </div>
                                                            )) }
                                                        </div>
                                                    ) }
                                                </div>
                                            ) }
                                        </div>
                                    ) }

                                    <p className="text-xs opacity-50 mt-2">
                                        { new Date(msg.timestamp).toLocaleTimeString('hu-HU') }
                                    </p>
                                </div>

                                { msg.role === 'user' && (
                                    <div className="w-8 h-8 rounded-full bg-gray-700 dark:bg-gray-600 flex items-center justify-center flex-shrink-0">
                                        <User className="w-4 h-4 text-white" />
                                    </div>
                                ) }
                            </div>
                        )) }
                        <div ref={ scrollRef } />
                    </div>
                </div>

                <div className="border-t p-3 bg-background shrink-0">
                    <div className="flex gap-2 items-end">
                        <Textarea
                            value={ input }
                            onChange={ (e) => setInput(e.target.value) }
                            onKeyDown={ (e) => {
                                if (e.key === 'Enter' && !e.shiftKey) {
                                    e.preventDefault();
                                    void sendMessage();
                                }
                            } }
                            placeholder="Írd be a feladatot magyarul... (Enter = küldés)"
                            className="resize-none min-h-[44px] max-h-[120px] text-sm"
                            disabled={ isLoading }
                        />
                        <Button
                            onClick={ startListening }
                            variant="outline"
                            size="icon"
                            className={ `shrink-0 h-9 w-9 transition-all duration-300 ${isListening ? 'bg-red-500/20 text-red-500 border-red-500/50 animate-pulse' : ''}` }
                            title="Hangutasítás (Magyar)"
                        >
                            { isSpeaking ? (
                                <Volume2 className="w-4 h-4 animate-bounce text-primary" />
                            ) : (
                                <Mic className={ `w-4 h-4 ${isListening ? 'text-red-500' : ''}` } />
                            ) }
                        </Button>
                        <Button onClick={ () => void sendMessage() } disabled={ !input.trim() || isLoading } className="shrink-0 h-9 w-9" size="icon">
                            { isLoading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Send className="w-4 h-4" /> }
                        </Button>
                    </div>
                    { isLoading && (
                        <p className="text-xs text-zinc-500 mt-1 animate-pulse">⏳ Orchestrator gondolkodik...</p>
                    ) }
                </div>
            </CardContent>
        </Card>
    );
}

/**
 * PAIOS Phoenix Events Panel - Real-time Phoenix Protocol Monitoring
 *
 * Features:
 * - Real-time Phoenix event stream (Socket.IO)
 * - Event filtering by type
 * - Color-coded event badges
 * - Auto-scroll to latest events
 * - Event history (max 100 events)
 *
 * @track paios_phoenix_events_panel_20260223
 */

import { useState, useEffect, useRef } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import {
    Select,
    SelectContent,
    SelectItem,
    SelectTrigger,
    SelectValue,
} from '@/components/ui/select';
import {
    Flame,
    CheckCircle2,
    RotateCcw,
    Database,
    AlertTriangle,
    XCircle,
    Activity,
} from 'lucide-react';
import { useSocket } from '@/context/SocketContext';
import { nanoid } from 'nanoid';

export interface PhoenixEvent {
    id: string;
    type: PhoenixEventType;
    timestamp: string;
    agent?: string;
    taskId?: string;
    details?: string;
    serviceName?: string;
    success?: boolean;
    error?: string;
    stepIndex?: number;
    stepName?: string;
    level?: string;
}

export type PhoenixEventType =
    | 'phoenix:recovery'
    | 'phoenix:restart'
    | 'phoenix:state_restored'
    | 'phoenix:checkpoint_saved'
    | 'phoenix:agent_failed'
    | 'phoenix:failover_triggered'
    | 'phoenix:failover_result'
    | 'phoenix:degraded'
    | 'phoenix:edge_health'
    | 'phoenix:circuit_breaker';

const EVENT_CONFIGS: Record<
    PhoenixEventType,
    { label: string; icon: typeof Flame; color: string; bgColor: string }
> = {
    'phoenix:recovery': {
        label: 'Recovery',
        icon: CheckCircle2,
        color: 'text-green-500',
        bgColor: 'bg-green-500/10 border-green-500/30',
    },
    'phoenix:restart': {
        label: 'Restart',
        icon: RotateCcw,
        color: 'text-yellow-500',
        bgColor: 'bg-yellow-500/10 border-yellow-500/30',
    },
    'phoenix:state_restored': {
        label: 'State Restored',
        icon: Database,
        color: 'text-blue-500',
        bgColor: 'bg-blue-500/10 border-blue-500/30',
    },
    'phoenix:checkpoint_saved': {
        label: 'Checkpoint',
        icon: Database,
        color: 'text-cyan-500',
        bgColor: 'bg-cyan-500/10 border-cyan-500/30',
    },
    'phoenix:agent_failed': {
        label: 'Agent Failed',
        icon: XCircle,
        color: 'text-red-500',
        bgColor: 'bg-red-500/10 border-red-500/30',
    },
    'phoenix:failover_triggered': {
        label: 'Failover',
        icon: AlertTriangle,
        color: 'text-orange-500',
        bgColor: 'bg-orange-500/10 border-orange-500/30',
    },
    'phoenix:failover_result': {
        label: 'Failover Result',
        icon: Activity,
        color: 'text-purple-500',
        bgColor: 'bg-purple-500/10 border-purple-500/30',
    },
    'phoenix:degraded': {
        label: 'Degraded',
        icon: AlertTriangle,
        color: 'text-orange-500',
        bgColor: 'bg-orange-500/10 border-orange-500/30',
    },
    'phoenix:edge_health': {
        label: 'Edge Health',
        icon: Activity,
        color: 'text-teal-500',
        bgColor: 'bg-teal-500/10 border-teal-500/30',
    },
    'phoenix:circuit_breaker': {
        label: 'Circuit Breaker',
        icon: AlertTriangle,
        color: 'text-amber-500',
        bgColor: 'bg-amber-500/10 border-amber-500/30',
    },
};

export function PhoenixEventsPanel() {
    const [events, setEvents] = useState<PhoenixEvent[]>([]);
    const [filter, setFilter] = useState<string>('all');
    const { socket } = useSocket();
    const scrollRef = useRef<HTMLDivElement>(null);

    // Socket.IO listeners for all Phoenix events
    useEffect(() => {
        if (!socket) return;

        const eventTypes: PhoenixEventType[] = [
            'phoenix:recovery',
            'phoenix:restart',
            'phoenix:state_restored',
            'phoenix:checkpoint_saved',
            'phoenix:agent_failed',
            'phoenix:failover_triggered',
            'phoenix:failover_result',
            'phoenix:degraded',
            'phoenix:edge_health',
            'phoenix:circuit_breaker',
        ];

        const handleEvent = (type: PhoenixEventType) => (data: any) => {
            const event: PhoenixEvent = {
                id: nanoid(),
                type,
                timestamp: data.timestamp || new Date().toISOString(),
                agent: data.agent || data.agentName,
                taskId: data.taskId,
                details: data.details || data.message,
                serviceName: data.serviceName,
                success: data.success,
                error: data.error,
                stepIndex: data.stepIndex,
                stepName: data.stepName,
                level: data.level,
            };

            setEvents((prev) => [event, ...prev].slice(0, 100)); // Keep max 100 events
        };

        // Register all listeners
        eventTypes.forEach((type) => {
            socket.on(type, handleEvent(type));
        });

        // Cleanup
        return () => {
            eventTypes.forEach((type) => {
                socket.off(type);
            });
        };
    }, [socket]);

    // Auto-scroll to top when new events arrive
    useEffect(() => {
        scrollRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
    }, [events.length]);

    // Filter events
    const filteredEvents = filter === 'all' ? events : events.filter((e) => e.type === filter);

    // Clear all events
    const handleClear = () => {
        setEvents([]);
    };

    return (
        <Card className="h-full flex flex-col">
            <CardHeader className="border-b">
                <div className="flex items-center justify-between">
                    <CardTitle className="flex items-center gap-2">
                        <Flame className="w-5 h-5 text-orange-500" />
                        Phoenix Events
                    </CardTitle>
                    <div className="flex gap-2">
                        <Select value={filter} onValueChange={setFilter}>
                            <SelectTrigger className="w-[180px]">
                                <SelectValue placeholder="Filter events" />
                            </SelectTrigger>
                            <SelectContent>
                                <SelectItem value="all">All Events</SelectItem>
                                {Object.entries(EVENT_CONFIGS).map(([type, config]) => (
                                    <SelectItem key={type} value={type}>
                                        {config.label}
                                    </SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                        <Button variant="outline" size="sm" onClick={handleClear}>
                            Clear
                        </Button>
                    </div>
                </div>
                <p className="text-xs text-zinc-500 mt-1">
                    Real-time Phoenix Protocol recovery events • {filteredEvents.length}/100 events
                </p>
            </CardHeader>

            <CardContent className="flex-1 p-4 overflow-hidden">
                <ScrollArea className="h-full">
                    <div className="space-y-2">
                        <div ref={scrollRef} />
                        {filteredEvents.length === 0 ? (
                            <div className="text-center text-zinc-500 py-12">
                                <Flame className="w-12 h-12 mx-auto mb-2 opacity-30" />
                                <p className="text-sm">No Phoenix events yet</p>
                                <p className="text-xs mt-1 opacity-70">Events will appear here in real-time</p>
                            </div>
                        ) : (
                            filteredEvents.map((event) => (
                                <EventCard key={event.id} event={event} />
                            ))
                        )}
                    </div>
                </ScrollArea>
            </CardContent>
        </Card>
    );
}

function EventCard({ event }: { event: PhoenixEvent }) {
    const config = EVENT_CONFIGS[event.type];
    const Icon = config.icon;

    const formatTime = (timestamp: string) => {
        try {
            return new Date(timestamp).toLocaleTimeString('hu-HU', {
                hour: '2-digit',
                minute: '2-digit',
                second: '2-digit',
            });
        } catch {
            return timestamp;
        }
    };

    return (
        <div className={`border rounded-lg p-3 ${config.bgColor}`}>
            <div className="flex items-start gap-3">
                <Icon className={`w-5 h-5 ${config.color} flex-shrink-0 mt-0.5`} />
                <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                        <Badge variant="outline" className="text-xs">
                            {config.label}
                        </Badge>
                        <span className="text-xs text-zinc-500">{formatTime(event.timestamp)}</span>
                        {event.success !== undefined && (
                            <Badge variant={event.success ? 'default' : 'destructive'} className="text-xs">
                                {event.success ? '✓' : '✗'}
                            </Badge>
                        )}
                    </div>

                    {event.agent && (
                        <p className="text-sm font-medium">
                            Agent: <span className={config.color}>{event.agent}</span>
                        </p>
                    )}

                    {event.taskId && (
                        <p className="text-xs text-zinc-500">Task: {event.taskId}</p>
                    )}

                    {event.serviceName && (
                        <p className="text-xs text-zinc-500">Service: {event.serviceName}</p>
                    )}

                    {event.stepName && (
                        <p className="text-xs">
                            Step {event.stepIndex}: {event.stepName}
                        </p>
                    )}

                    {event.details && (
                        <p className="text-xs text-zinc-500 mt-1 line-clamp-2">{event.details}</p>
                    )}

                    {event.error && (
                        <p className="text-xs text-red-500 mt-1 font-mono line-clamp-2">Error: {event.error}</p>
                    )}

                    {event.level && (
                        <Badge variant="secondary" className="text-xs mt-1">
                            Level: {event.level}
                        </Badge>
                    )}
                </div>
            </div>
        </div>
    );
}

/**
 * Gold Protocol G7.2 UI: Phoenix Panel
 *
 * Checkpoint + recovery log viewer
 */

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { CheckCircle, ArrowClockwise, Cpu, HardDrive } from '@phosphor-icons/react';

interface Checkpoint {
  id?: number;
  taskId: string;
  step: string;
  timestamp: string;
  state: any;
}

interface RecoveryEvent {
  timestamp: string;
  taskId: string;
  step: string;
  reason: string;
}

interface SystemHealth {
  cpu: { usage: number };
  memory: { used: number; total: number };
  uptime: number;
}

export function PhoenixPanel() {
  const [checkpoints, setCheckpoints] = useState<Checkpoint[]>([]);
  const [recoveryLog, setRecoveryLog] = useState<RecoveryEvent[]>([]);
  const [health, setHealth] = useState<SystemHealth | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAll();
    const interval = setInterval(fetchAll, 5000); // Auto-refresh 5s
    return () => clearInterval(interval);
  }, []);

  const fetchAll = async () => {
    try {
      const [cpRes, logRes, healthRes] = await Promise.all([
        fetch('/api/phoenix/checkpoints'),
        fetch('/api/phoenix/recovery-log'),
        fetch('/api/phoenix/health'),
      ]);
      const cpData = await cpRes.json();
      const logData = await logRes.json();
      const healthData = await healthRes.json();
      setCheckpoints(cpData.checkpoints || []);
      setRecoveryLog(logData.events || []);
      setHealth(healthData);
      setLoading(false);
    } catch (e) {
      console.error('Failed to fetch Phoenix data:', e);
      setLoading(false);
    }
  };

  const clearCheckpointsForTask = async (taskId: string) => {
    try {
      await fetch(`/api/phoenix/checkpoints/${taskId}`, { method: 'DELETE' });
      fetchAll();
    } catch (e) {
      console.error('Failed to clear checkpoints:', e);
    }
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Phoenix Protocol</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="text-gray-500">Loading...</div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
      {/* Active Checkpoints */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <CheckCircle className="w-5 h-5" />
            Active Checkpoints ({checkpoints.length})
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 max-h-[400px] overflow-y-auto">
            {checkpoints.map((cp, idx) => (
              <div key={idx} className="p-3 border rounded-lg">
                <div className="flex items-center justify-between mb-1">
                  <Badge className="bg-blue-500">{cp.taskId}</Badge>
                  <Button size="sm" variant="outline" onClick={() => clearCheckpointsForTask(cp.taskId)}>
                    Clear
                  </Button>
                </div>
                <div className="text-xs text-gray-600">
                  Step: <span className="font-mono">{cp.step}</span>
                </div>
                <div className="text-xs text-gray-500">{new Date(cp.timestamp).toLocaleString()}</div>
              </div>
            ))}
            {checkpoints.length === 0 && (
              <div className="text-gray-500 text-sm">No active checkpoints</div>
            )}
          </div>
        </CardContent>
      </Card>

      {/* Recovery Log + Health */}
      <div className="space-y-4">
        {/* System Health */}
        {health && (
          <Card>
            <CardHeader>
              <CardTitle className="flex items-center gap-2">
                <Cpu className="w-5 h-5" />
                System Health
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-2 gap-4">
                <div>
                  <div className="text-xs text-gray-500 mb-1">CPU Usage</div>
                  <div className="text-2xl font-bold">{health.cpu.usage.toFixed(1)}%</div>
                </div>
                <div>
                  <div className="text-xs text-gray-500 mb-1">Memory</div>
                  <div className="text-2xl font-bold">
                    {((health.memory.used / health.memory.total) * 100).toFixed(1)}%
                  </div>
                  <div className="text-xs text-gray-600">
                    {(health.memory.used / 1024 / 1024).toFixed(0)} MB / {(health.memory.total / 1024 / 1024).toFixed(0)} MB
                  </div>
                </div>
              </div>
              <div className="mt-3 text-xs text-gray-500">
                Uptime: {(health.uptime / 3600).toFixed(1)} hours
              </div>
            </CardContent>
          </Card>
        )}

        {/* Recovery Log */}
        <Card>
          <CardHeader>
            <CardTitle className="flex items-center gap-2">
              <ArrowClockwise className="w-5 h-5" />
              Recovery Log ({recoveryLog.length})
            </CardTitle>
          </CardHeader>
          <CardContent>
            <div className="space-y-2 max-h-[300px] overflow-y-auto">
              {recoveryLog.map((event, idx) => (
                <div key={idx} className="p-3 border rounded-lg border-orange-300 bg-orange-50 dark:bg-orange-900/10">
                  <div className="flex items-center justify-between mb-1">
                    <Badge className="bg-orange-500">{event.taskId}</Badge>
                    <span className="text-xs text-gray-500">{new Date(event.timestamp).toLocaleString()}</span>
                  </div>
                  <div className="text-xs text-gray-600">
                    Step: <span className="font-mono">{event.step}</span>
                  </div>
                  <div className="text-xs text-red-600 mt-1">Reason: {event.reason}</div>
                </div>
              ))}
              {recoveryLog.length === 0 && (
                <div className="text-gray-500 text-sm">No recovery events</div>
              )}
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

