export function ProcessControlWidget() {
  const { tasks, setTasks } = useSystemSignalStore(useShallow((state) => ({
    tasks: state.tasks,
    setTasks: state.setTasks,
  })));
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [isTraceModalOpen, setIsTraceModalOpen] = useState(false);
  const [selectedTask, setSelectedTask] = useState<QueuedTask | null>(null);
  const [selectedTraceTaskId, setSelectedTraceTaskId] = useState<number | null>(null);
  const [sortedTasks, setSortedTasks] = useState<QueuedTask[]>([]);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const refreshActiveTasks = async () => {
    setIsRefreshing(true);
    try {
      const response = await getTasks(50, 0);
      setTasks(response.tasks || []);
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      toast.error(`Feladatlista frissítés hiba: ${message}`);
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    // Initialize sortedTasks with tasks from the store, filter for active/pending
    const active = tasks.filter(task => task.status === "running" || task.status === "pending" || task.status === "paused");
    setSortedTasks(active);
  }, [tasks]);

  const sensors = useSensors(
    useSensor(PointerSensor),
    useSensor(KeyboardSensor, {
      coordinateGetter: sortableKeyboardCoordinates,
    }),
  );

  const handleControlAction = async (taskId: number, action: 'pause' | 'resume' | 'kill' | 'retry' | 'debugRetry') => {
    try {
      switch (action) {
        case 'pause':
          await pauseTask(taskId);
          toast.success(`Feladat ${taskId} szüneteltetve.`);
          break;
        case 'resume':
          await resumeTask(taskId);
          toast.success(`Feladat ${taskId} folytatva.`);
          break;
        case 'kill':
          await cancelTask(taskId);
          toast.success(`Feladat ${taskId} leállítva.`);
          break;
        case 'retry':
          await retryTask(taskId, false);
          toast.success(`Feladat ${taskId} újrapróbálva.`);
          break;
        case 'debugRetry':
          await retryTask(taskId, true);
          toast.success(`Feladat ${taskId} újrapróbálva debug móddal.`);
          break;
        default:
          toast.error(`Ismeretlen akció: ${action}`);
          return;
      }
      await refreshActiveTasks();
    } catch (error: any) {
      toast.error(`Sikertelen akció ${action} a feladaton ${taskId}: ${error.message}`);
    }
  };

  const handleDragEnd = async (event: DragEndEvent) => {
    const { active, over } = event;
    if (!over) return;

    if (active.id !== over.id) {
      const oldIndex = sortedTasks.findIndex((task) => task.id === active.id);
      const newIndex = sortedTasks.findIndex((task) => task.id === over.id);

      if (oldIndex !== -1 && newIndex !== -1) {
        const newSortedTasks = [...sortedTasks];
        const [removed] = newSortedTasks.splice(oldIndex, 1);
        newSortedTasks.splice(newIndex, 0, removed);
        setSortedTasks(newSortedTasks);

        // Update backend order
        try {
          const newOrderIds = newSortedTasks.map(task => task.id);
          await updateTaskOrder(newOrderIds); // This API call needs to be implemented
          toast.success("Feladatok sorrendje frissítve.");
        } catch (error: any) {
          toast.error(`Sikertelen sorrendfrissítés: ${error.message}`);
          // Revert UI on error
          setSortedTasks(tasks.filter(task => task.status === "running" || task.status === "pending" || task.status === "paused"));
        }
      }
    }
  };

  return (
    <Card className="h-full">
      <CardHeader>
        <CardTitle className="text-xl font-bold flex items-center gap-2">
          <Zap size={20} className="text-primary" /> Folyamatvezérlés
        </CardTitle>
      </CardHeader>
      <CardContent className="h-[calc(100%-70px)] overflow-y-auto custom-scrollbar">
        {sortedTasks.length === 0 ? (
          <p className="text-sm text-zinc-500">Nincsenek aktív vagy függőben lévő feladatok.</p>
        ) : (
          <DndContext
            sensors={sensors}
            collisionDetection={closestCenter}
            onDragEnd={handleDragEnd}
          >
            <SortableContext items={sortedTasks.map(task => task.id)} strategy={verticalListSortingStrategy}>
              <div className="space-y-4">
                {sortedTasks.map((task) => (
                  <SortableItem
                    key={task.id}
                    task={task}
                    onControlAction={handleControlAction}
                    onViewDetails={(task) => {
                      setSelectedTask(task);
                      setIsModalOpen(true);
                    }}
                    onViewTrace={(taskId) => {
                      setSelectedTraceTaskId(taskId);
                      setIsTraceModalOpen(true);
                    }}
                  />
                ))}
              </div>
            </SortableContext>
          </DndContext>
        )}
        <div className="mt-4 flex justify-end">
          <Button variant="outline" size="sm" onClick={refreshActiveTasks} disabled={isRefreshing}>
            <RefreshCcw size={14} className={isRefreshing ? "mr-2 animate-spin" : "mr-2"} />
            Frissítés
          </Button>
        </div>
      </CardContent>
      <TaskDetailsModal task={selectedTask} isOpen={isModalOpen} onClose={() => setIsModalOpen(false)} />
      <TraceViewerModal taskId={selectedTraceTaskId} isOpen={isTraceModalOpen} onClose={() => setIsTraceModalOpen(false)} />
    </Card>
  );
}

export default ProcessControlWidget;

import { useState, useEffect } from 'react'
import { Folder, File, ArrowLeft, RefreshCw, Eye, Download, Info } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { ScrollArea } from '@/components/ui/scroll-area'
import { listFiles, getFileContent, type FileInfo } from '@/lib/apiService'
import { toast } from 'sonner'
import { Skeleton } from '@/components/ui/skeleton'

const BASE_PATH = 'G:/Brunella/.000_PROJEKTEK';

export function ProjectExplorer() {
    const [currentPath, setCurrentPath] = useState(BASE_PATH)
    const [files, setFiles] = useState<FileInfo[]>([])
    const [loading, setLoading] = useState(true)
    const [previewContent, setPreviewContent] = useState<string | null>(null)
    const [previewFile, setPreviewFile] = useState<FileInfo | null>(null)

    const fetchFiles = async (path: string) => {
        setLoading(true)
        try {
            const data = await listFiles(path)
            // Folders first, then files
            setFiles(data.sort((a, b) => {
                if (a.isDirectory && !b.isDirectory) return -1
                if (!a.isDirectory && b.isDirectory) return 1
                return a.name.localeCompare(b.name)
            }))
            setCurrentPath(path)
        } catch (e) {
            toast.error('Hiba a fájlok listázásakor')
        } finally {
            setLoading(false)
        }
    }

    useEffect(() => {
        fetchFiles(BASE_PATH)
    }, [])

    const handleFolderClick = (path: string) => {
        fetchFiles(path)
    }

    const handleBack = () => {
        // Prevent going above BASE_PATH
        if (currentPath === BASE_PATH || currentPath === 'G:\\Brunella\\.000_PROJEKTEK') {
            return;
        }
        
        const parts = currentPath.split(/["//\\]/);
        if (parts.length > 1) {
            parts.pop()
            const newPath = parts.join('/') || BASE_PATH;
            
            // Extra safety check
            if (!newPath.startsWith(BASE_PATH.replace(/\\/g, '/')) && !newPath.startsWith('G:\\Brunella\\.000_PROJEKTEK')) {
                fetchFiles(BASE_PATH);
            } else {
                fetchFiles(newPath);
            }
        } else {
            fetchFiles(BASE_PATH)
        }
    }

    const handlePreview = async (file: FileInfo) => {
        try {
            setLoading(true)
            const content = await getFileContent(file.path)
            setPreviewContent(content)
            setPreviewFile(file)
        } catch (e) {
            toast.error('Hiba a fájl beolvasásakor')
        } finally {
            setLoading(false)
        }
    }

    const formatSize = (bytes: number) => {
        if (bytes === 0) return '-'
        const k = 1024
        const sizes = ['B', 'KB', 'MB', 'GB']
        const i = Math.floor(Math.log(bytes) / Math.log(k))
        return parseFloat((bytes / Math.pow(k, i)).toFixed(1)) + ' ' + sizes[i]
    }

    const isAtRoot = currentPath.replace(/\\/g, '/') === BASE_PATH.replace(/\\/g, '/');

    return (
        <div className="space-y-4 animate-in fade-in duration-500">
            <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                    <Button variant="ghost" size="icon" onClick={handleBack} disabled={isAtRoot}>
                        <ArrowLeft size={18} />
                    </Button>
                    <div className="flex flex-col">
                        <h2 className="text-xl font-bold tracking-tight">Projektek</h2>
                        <p className="text-xs font-mono text-zinc-500">{currentPath}</p>
                    </div>
                </div>
                <Button variant="outline" size="sm" onClick={() => fetchFiles(currentPath)} disabled={loading}>
                    <RefreshCw size={14} className={loading ? "animate-spin mr-2" : "mr-2"} />
                    Frissítés
                </Button>
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-[1fr_350px] gap-6">
                <Card className="glass-card overflow-hidden">
                    <CardHeader className="pb-3 border-b border-border/50">
                        <CardTitle className="text-sm font-medium flex items-center gap-2">
                            <Folder size={16} className="text-primary" />
                            Tartalom
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="p-0">
                        <ScrollArea className="h-[600px]">
                            <div className="divide-y divide-border/50">
                                {loading && files.length === 0 ? (
                                    Array.from({ length: 8 }).map((_, i) => (
                                        <div key={i} className="flex items-center gap-4 px-4 py-3">
                                            <Skeleton className="h-4 w-4" />
                                            <Skeleton className="h-4 flex-1" />
                                            <Skeleton className="h-4 w-16" />
                                        </div>
                                    ))
                                ) : (
                                    files.map((file) => (
                                        <div
                                            key={file.path}
                                            className="group flex items-center justify-between px-4 py-3 hover:bg-muted/50 transition-colors cursor-pointer"
                                            onClick={() => file.isDirectory ? handleFolderClick(file.path) : handlePreview(file)}
                                        >
                                            <div className="flex items-center gap-3 overflow-hidden">
                                                {file.isDirectory ? (
                                                    <Folder size={18} className="text-blue-400 shrink-0" />
                                                ) : (
                                                    <File size={18} className="text-zinc-500 shrink-0" />
                                                )}
                                                <span className="text-sm font-mono truncate group-hover:text-primary transition-colors">
                                                    {file.name}
                                                </span>
                                            </div>
                                            <div className="flex items-center gap-4 text-xs font-mono text-zinc-500">
                                                <span>{formatSize(file.size)}</span>
                                                {!file.isDirectory && (
                                                    <Button variant="ghost" size="icon" className="h-6 w-6 opacity-0 group-hover:opacity-100 transition-opacity">
                                                        <Eye size={12} />
                                                    </Button>
                                                )}
                                            </div>
                                        </div>
                                    ))
                                )}
                                {!loading && files.length === 0 && (
                                    <div className="p-8 text-center text-zinc-500 italic">
                                        Ez a mappa üres
                                    </div>
                                )}
                            </div>
                        </ScrollArea>
                    </CardContent>
                </Card>

                <Card className="glass-card h-fit sticky top-20">
                    <CardHeader className="pb-3 border-b border-border/50">
                        <CardTitle className="text-sm font-medium flex items-center gap-2">
                            <Info size={16} className="text-primary" />
                            Részletek / Előnézet
                        </CardTitle>
                    </CardHeader>
                    <CardContent className="p-4">
                        {previewFile ? (
                            <div className="space-y-4">
                                <div className="space-y-1">
                                    <h3 className="font-bold text-sm truncate">{previewFile.name}</h3>
                                    <p className="text-[10px] font-mono text-zinc-500 break-all">{previewFile.path}</p>
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                    <div className="bg-muted/50 rounded p-2 border border-border/50">
                                        <span className="text-[9px] uppercase text-zinc-500 block">Mérete</span>
                                        <span className="text-xs font-mono">{formatSize(previewFile.size)}</span>
                                    </div>
                                    <div className="bg-muted/50 rounded p-2 border border-border/50">
                                        <span className="text-[9px] uppercase text-zinc-500 block">Módosítva</span>
                                        <span className="text-xs font-mono">{new Date(previewFile.modified).toLocaleDateString()}</span>
                                    </div>
                                </div>

                                <div className="pt-2">
                                    <span className="text-[10px] uppercase font-bold text-zinc-500 mb-1 block">Tartalom:</span>
                                    <div className="bg-muted/30 rounded-lg p-3 border border-border/50 max-h-[300px] overflow-auto">
                                        <pre className="text-[10px] font-mono whitespace-pre-wrap text-foreground/80">
                                            {previewContent || "Nincs megjeleníthető tartalom"}
                                        </pre>
                                    </div>
                                </div>

                                <Button className="w-full" size="sm" variant="outline" onClick={() => {
                                    if (previewFile) {
                                        const blob = new Blob([previewContent || ''], { type: 'text/plain' });
                                        const url = URL.createObjectURL(blob);
                                        const a = document.createElement('a');
                                        a.href = url;
                                        a.download = previewFile.name || 'download.txt';
                                        a.click();
                                        URL.revokeObjectURL(url);
                                    }
                                }}>
                                    <Download size={14} className="mr-2" />
                                    Letöltés
                                </Button>
                            </div>
                        ) : (
                            <div className="p-8 text-center text-zinc-500 text-xs italic">
                                Válassz ki egy fájlt a részletek megtekintéséhez
                            </div>
                        )}
                    </CardContent>
                </Card>
            </div>
        </div>
    )
}

