import { useState } from 'react';
import { Card, CardHeader, CardTitle, CardContent } from '../ui/card';
import { Input } from '../ui/input';
import { Button } from '../ui/button';
import { Search, Database, CloudCog } from 'lucide-react';

interface RAGResult {
  text: string;
  path?: string;
  score?: number;
}

export function RAGMemoryWidget() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState<RAGResult[]>([]);
  const [loading, setLoading] = useState(false);
  const [stats, setStats] = useState<{ rowCount: number; provider: string } | null>(null);

  const loadStats = async () => {
    try {
      const response = await fetch('/api/rag/stats');
      const data = await response.json();
      setStats(data);
    } catch (e) {
      console.error('RAG stats betöltési hiba:', e);
    }
  };

  const handleSearch = async () => {
    if (!query.trim()) return;

    setLoading(true);
    try {
      const response = await fetch(`/api/rag/query?query=${encodeURIComponent(query)}&limit=5`);
      const data = await response.json();
      setResults(data.results || []);
    } catch (e) {
      console.error('RAG keresési hiba:', e);
      setResults([]);
    } finally {
      setLoading(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleSearch();
    }
  };

  return (
    <Card className="h-full flex flex-col">
      <CardHeader className="flex-shrink-0">
        <CardTitle className="flex items-center gap-2">
          <Database className="w-5 h-5" />
          RAG Memória
          <Button
            variant="ghost"
            size="sm"
            onClick={loadStats}
            className="ml-auto"
          >
            <CloudCog className="w-4 h-4" />
          </Button>
        </CardTitle>
        {stats && (
          <p className="text-sm text-zinc-500">
            {stats.rowCount.toLocaleString()} dokumentum ({stats.provider})
          </p>
        )}
      </CardHeader>

      <CardContent className="flex-1 flex flex-col gap-4 overflow-hidden">
        <div className="flex gap-2">
          <Input
            placeholder="Keresés a memóriában..."
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            onKeyPress={handleKeyPress}
            disabled={loading}
          />
          <Button onClick={handleSearch} disabled={loading || !query.trim()}>
            <Search className="w-4 h-4" />
          </Button>
        </div>

        <div className="flex-1 overflow-y-auto space-y-3">
          {loading && (
            <div className="text-center text-zinc-500 py-8">
              Keresés folyamatban...
            </div>
          )}

          {!loading && results.length === 0 && query && (
            <div className="text-center text-zinc-500 py-8">
              Nincs találat a keresésre: "{query}"
            </div>
          )}

          {!loading && results.length === 0 && !query && (
            <div className="text-center text-zinc-500 py-8">
              Írj be egy keresési kifejezést
            </div>
          )}

          {results.map((result, idx) => (
            <div
              key={idx}
              className="p-3 border rounded-lg bg-card hover:bg-accent/50 transition-colors"
            >
              <p className="text-sm line-clamp-3">{result.text}</p>
              <div className="flex items-center gap-2 mt-2 text-xs text-zinc-500">
                {result.path && <span>📄 {result.path}</span>}
                {result.score !== undefined && (
                  <span className="ml-auto">
                    Score: {result.score.toFixed(3)}
                  </span>
                )}
              </div>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

import { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "../ui/card";
import { Input } from "../ui/input";
import { Button } from "../ui/button";
import { toast } from "sonner";
import { RemoteTargetPayload, RemoteSessionPayload } from "../../../utils/BrunellaRemoteClient";

type RemoteTargetMap = Record<string, RemoteTargetPayload>;

export function RemoteConsolePanel()
{
  const [targets, setTargets] = useState<RemoteTargetPayload[]>( [] );
  const [sessions, setSessions ] = useState<RemoteSessionPayload[]>( [] );
  const [selectedTarget, setSelectedTarget ] = useState<string | null>( null );
  const [initiator, setInitiator ] = useState( "Copilot Remote" );
  const [command, setCommand ] = useState( "echo Hello Remote" );
  const [creating, setCreating ] = useState( false );

  const targetMap = useMemo<RemoteTargetMap>( () =>
  {
    const map: RemoteTargetMap = {};
    targets.forEach( ( target ) => { map[ target.id ] = target; } );
    return map;
  }, [ targets ] );

  useEffect( () =>
  {
    void fetchTargets();
    void fetchSessions();
  }, [] );

  async function fetchTargets()
  {
    try
    {
      const res = await fetch( "/api/v1/remote/targets" );
      const data = await res.json();
      setTargets( data.targets ?? [] );
      if ( !selectedTarget && Array.isArray( data.targets ) && data.targets.length > 0 )
      {
        setSelectedTarget( data.targets[ 0 ].id );
      }
    }
    catch ( error )
    {
      console.error( error );
    }
  }

  async function fetchSessions()
  {
    try
    {
      const res = await fetch( "/api/v1/remote/sessions" );
      const data = await res.json();
      setSessions( data.sessions ?? [] );
    }
    catch ( error )
    {
      console.error( error );
    }
  }

  async function handleCreateSession()
  {
    if ( !selectedTarget )
    {
      toast.error( "Válassz célt a létrehozáshoz" );
      return;
    }
    setCreating( true );
    try
    {
      const res = await fetch( "/api/v1/remote/sessions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify( { targetId: selectedTarget, initiator } ),
      } );

      if ( !res.ok )
      {
        const json = await res.json();
        throw new Error( json?.error ?? "Nem sikerült új session-t létrehozni" );
      }

      const data = await res.json();
      setSessions( [ ...( sessions ?? [] ), data.session ] );
      toast.success( `Session létrehozva: ${ data.session.id }` );
    }
    catch ( error )
    {
      toast.error( error instanceof Error ? error.message : "Hiba" );
    }
    finally
    {
      setCreating( false );
    }
  }

  async function handleSendCommand( sessionId: string )
  {
    try
    {
      const res = await fetch( `/api/v1/remote/sessions/${ sessionId }/commands`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify( { command, origin: "dashboard" } ),
      } );
      if ( !res.ok ) throw new Error( "Hiba a parancs küldésekor" );

      const updated = await res.json();
      setSessions( sessions.map( ( session ) =>
        session.id === sessionId ? { ...session, commands: [ ...session.commands, updated.command ] } : session
      ) );
      toast.success( `Parancs elküldve ${ sessionId }` );
    }
    catch ( error )
    {
      toast.error( error instanceof Error ? error.message : "Hiba" );
    }
  }

  return (
    <Card className="h-full" id="remote-session-panel">
      <CardHeader>
        <CardTitle>Remote Layer Console</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid gap-3 md:grid-cols-3">
          <label className="flex flex-col gap-2 text-sm">
            <span>Célválasztás</span>
            <select className="rounded border border-border px-3 py-2 text-sm" value={ selectedTarget ?? "" } onChange={ ( e ) => setSelectedTarget( e.target.value ) }>
              { targets.map( ( target ) => (
                <option key={ target.id } value={ target.id }>{ target.name }</option>
              ) ) }
            </select>
          </label>
          <label className="flex flex-col gap-2 text-sm">
            <span>Initiátor</span>
            <Input value={ initiator } onChange={ ( event ) => setInitiator( event.target.value ) } />
          </label>
          <label className="flex flex-col gap-2 text-sm">
            <span>Parancs</span>
            <Input value={ command } onChange={ ( event ) => setCommand( event.target.value ) } />
          </label>
        </div>
        <div className="flex flex-wrap gap-3">
          <Button variant="outline" onClick={ handleCreateSession } size="sm" disabled={ creating }>
            { creating ? "Létrehozás..." : "Új session" }
          </Button>
          <Button variant="secondary" size="sm" onClick={ () => void fetchSessions() }>
            Frissítés
          </Button>
        </div>
        <div className="space-y-2">
          { sessions.length === 0 && <p className="text-sm text-muted-foreground">Nincsenek aktív session-ök.</p> }
          { sessions.map( ( session ) => (
            <article key={ session.id } className="rounded-lg border border-border/50 bg-background/60 p-3 shadow-sm">
              <div className="flex flex-col gap-1">
                <p className="text-xs text-muted-foreground">ID: { session.id }</p>
                <p className="text-base font-medium">{ targetMap[ session.targetId ]?.name ?? session.targetId }</p>
                <p className="text-sm text-muted-foreground">Initiátor: { session.initiator }</p>
                <p className="text-sm text-muted-foreground">Expires: { new Date( session.expiresAt ).toLocaleTimeString() }</p>
              </div>
              <div className="mt-2 flex items-center gap-2">
                <Button size="xs" onClick={ () => void handleSendCommand( session.id ) }>
                  Küld parancs
                </Button>
                <span className="text-xs text-muted-foreground">{ session.commands.length } parancs</span>
              </div>
            </article>
          ) ) }
        </div>
      </CardContent>
    </Card>
  );
}import { useEffect, useMemo, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "../ui/card";
import { Input } from "../ui/input";
import { Button } from "../ui/button";
import { toast } from "sonner";
import { RemoteTargetPayload, RemoteSessionPayload } from "../../utils/BrunellaRemoteClient";

type RemoteSessionMap = Record<string, RemoteSessionPayload>;

export function RemoteConsolePanel()
{
  const [targets, setTargets] = useState<RemoteTargetPayload[]>( [] );
  const [sessions, setSessions ] = useState<RemoteSessionPayload[]>( [] );
  const [selectedTarget, setSelectedTarget ] = useState<string | null>( null );
  const [initiator, setInitiator ] = useState( "Copilot Remote" );
  const [command, setCommand ] = useState( "echo Hello Remote" );
  const [creating, setCreating ] = useState( false );

  const targetMap = useMemo<RemoteSessionMap>( () =>
  {
    const map: RemoteSessionMap = {};
    sessions.forEach( ( s ) => { map[ s.id ] = s; } );
    return map;
  }, [ sessions ] );

  useEffect( () =>
  {
    void fetchTargets();
    void fetchSessions();
  }, [] );

  async function fetchTargets()
  {
    try
    {
      const res = await fetch( "/api/v1/remote/targets" );
      const data = await res.json();
      setTargets( data.targets ?? [] );
      if ( !selectedTarget && Array.isArray( data.targets ) && data.targets.length > 0 )
      {
        setSelectedTarget( data.targets[ 0 ].id );
      }
    }
    catch ( error )
    {
      console.error( error );
    }
  }

  async function fetchSessions()
  {
    try
    {
      const res = await fetch( "/api/v1/remote/sessions" );
      const data = await res.json();
      setSessions( data.sessions ?? [] );
    }
    catch ( error )
    {
      console.error( error );
    }
  }

  async function handleCreateSession()
  {
    if ( !selectedTarget )
    {
      toast.error( "Válassz célt a létrehozáshoz" );
      return;
    }
    setCreating( true );
    try
    {
      const res = await fetch( "/api/v1/remote/sessions", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify( { targetId: selectedTarget, initiator } ),
      } );

      if ( !res.ok )
      {
        const json = await res.json();
        throw new Error( json?.error ?? "Nem sikerült új session-t létrehozni" );
      }

      const data = await res.json();
      setSessions( [ ...( sessions ?? [] ), data.session ] );
      toast.success( `Session létrehozva: ${ data.session.id }` );
    }
    catch ( error )
    {
      toast.error( error instanceof Error ? error.message : "Hiba" );
    }
    finally
    {
      setCreating( false );
    }
  }

  async function handleSendCommand( sessionId: string )
  {
    try
    {
      const res = await fetch( `/api/v1/remote/sessions/${ sessionId }/commands`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify( { command, origin: "dashboard" } ),
      } );
      if ( !res.ok ) throw new Error( "Hiba a parancs küldésekor" );

      const updated = await res.json();
      setSessions( sessions.map( ( session ) =>
        session.id === sessionId ? { ...session, commands: [ ...session.commands, updated.command ] } : session
      ) );
      toast.success( `Parancs elküldve ${ sessionId }` );
    }
    catch ( error )
    {
      toast.error( error instanceof Error ? error.message : "Hiba" );
    }
  }

  return (
    <Card className="h-full" id="remote-session-panel">
      <CardHeader>
        <CardTitle>Remote Layer Console</CardTitle>
      </CardHeader>
      <CardContent className="space-y-4">
        <div className="grid gap-3 md:grid-cols-3">
          <label className="flex flex-col gap-2 text-sm">
            <span>Célválasztás</span>
            <select className="rounded border border-border px-3 py-2 text-sm" value={ selectedTarget ?? "" } onChange={ ( e ) => setSelectedTarget( e.target.value ) }>
              { targets.map( ( target ) => (
                <option key={ target.id } value={ target.id }>{ target.name }</option>
              ) ) }
            </select>
          </label>
          <label className="flex flex-col gap-2 text-sm">
            <span>Initiátor</span>
            <Input value={ initiator } onChange={ ( event ) => setInitiator( event.target.value ) } />
          </label>
          <label className="flex flex-col gap-2 text-sm">
            <span>Parancs</span>
            <Input value={ command } onChange={ ( event ) => setCommand( event.target.value ) } />
          </label>
        </div>
        <div className="flex flex-wrap gap-3">
          <Button variant="outline" onClick={ handleCreateSession } size="sm" disabled={ creating }>
            { creating ? "Létrehozás..." : "Új session" }
          </Button>
          <Button variant="secondary" size="sm" onClick={ () => void fetchSessions() }>
            Frissítés
          </Button>
        </div>
        <div className="space-y-2">
          { sessions.length === 0 && <p className="text-sm text-muted-foreground">Nincsenek aktív session-ök.</p> }
          { sessions.map( ( session ) => (
            <article key={ session.id } className="rounded-lg border border-border/50 bg-background/60 p-3 shadow-sm">
              <div className="flex flex-col gap-1">
                <p className="text-xs text-muted-foreground">ID: { session.id }</p>
                <p className="text-base font-medium">{ targetMap[ session.id ]?.name ?? session.targetId }</p>
                <p className="text-sm text-muted-foreground">Initiátor: { session.initiator }</p>
                <p className="text-sm text-muted-foreground">Expires: { new Date( session.expiresAt ).toLocaleTimeString() }</p>
              </div>
              <div className="mt-2 flex items-center gap-2">
                <Button size="xs" onClick={ () => void handleSendCommand( session.id ) }>
                  Küld parancs
                </Button>
                <span className="text-xs text-muted-foreground">{ session.commands.length } parancs</span>
              </div>
            </article>
          ) ) }
        </div>
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from 'react';
import { Play, Square, Camera, RefreshCw, Terminal, Activity, Globe, Loader2 } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { Progress } from '../ui/progress';
import { toast } from 'sonner';
import {
    startBrowser,
    stopBrowser,
    getBrowserStatus,
    runRobotkezTest,
    getRobotkezScreenshot,
    getN8nWorkflows,
    BrowserStatus
} from '../../lib/apiService';

interface N8nWorkflow {
    name: string;
    active: boolean;
}

import { useSocket } from '../../context/SocketContext';

export function RobotkezPanel() {
    const [status, setStatus] = useState<BrowserStatus>({ active: false });
    const [loading, setLoading] = useState(false);
    const [runningTest, setRunningTest] = useState<number | null>(null);
    const [logs, setLogs] = useState<string[]>([]);
    const [screenshotUrl, setScreenshotUrl] = useState<string>('');
    const [thought, setThought] = useState<string>('');
    const [lastAction, setLastAction] = useState<any>(null);
    const [n8nWorkflows, setN8nWorkflows] = useState<N8nWorkflow[]>([]);
    const [n8nLoading, setN8nLoading] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);
    const { socket } = useSocket();

    // Refresh status and screenshot
    const refreshData = async () => {
        setIsRefreshing(true);
        try {
            // Get Browser Status
            const browserData = await getBrowserStatus();
            setStatus(browserData);

            // Get Screenshot (if active and not updated by socket recently)
            if (browserData.active && !screenshotUrl.startsWith('data:image')) {
                setScreenshotUrl(await getRobotkezScreenshot());
            } else if (!browserData.active) {
                setScreenshotUrl('');
            }
        } catch (err: any) {
            console.error(err);
        } finally {
            setIsRefreshing(false);
        }
    };

    // WebSocket listeners
    useEffect(() => {
        if (!socket) return;

        socket.on('robotkez:step', (data) => {
            if (data.description) setThought(data.description);
            if (data.screenshot) setScreenshotUrl(`data:image/png;base64,${data.screenshot}`);
            if (data.coords) setLastAction(data.coords);
            setLogs(prev => [`[${new Date().toLocaleTimeString()}] ${data.description || 'Action step'}`, ...prev.slice(0, 100)]);
        });

        socket.on('robotkez:vision_thought', (data) => {
            setThought(data.message);
        });

        return () => {
            socket.off('robotkez:step');
            socket.off('robotkez:vision_thought');
        };
    }, [socket]);

    const fetchN8nWorkflows = async () => {
        setN8nLoading(true);
        try {
            const data = await getN8nWorkflows();
            setN8nWorkflows(data.data || []);
        } catch (err: any) {
            console.error('n8n error:', err);
            // Don't toast on auto-refresh to avoid spam
            if (!n8nLoading) toast.error(`n8n hiba: ${err.message}`);
            setN8nWorkflows([]);
        } finally {
            setN8nLoading(false);
        }
    };

    // Auto-refresh hook
    useEffect(() => {
        refreshData();
        fetchN8nWorkflows();
        const interval = setInterval(() => {
            refreshData();
        }, 5000);
        return () => clearInterval(interval);
    }, []);

    const handleStart = async () => {
        setLoading(true);
        try {
            await startBrowser({
                startUrl: "https://google.com", 
                sessionName: "Dashboard Session"
            });
            toast.success("Böngésző elindítva");
            setTimeout(refreshData, 1000);
        } catch (err: any) {
            toast.error(`Hiba: ${err.message}`);
        } finally {
            setLoading(false);
        }
    };

    const handleStop = async () => {
        setLoading(true);
        try {
            await stopBrowser(status.sessionId || undefined);
            toast.info("Böngésző leállítva");
            setTimeout(refreshData, 1000);
        } catch (err: any) {
            toast.error(`Hiba: ${err.message}`);
        } finally {
            setLoading(false);
        }
    };

    const handleRunTest = async (level: 1 | 2 | 3) => {
        setRunningTest(level);
        setLogs(prev => [...prev, `\n--- Futtatás: Level ${level} teszt ---`]);
        
        try {
            // Start the test and get session ID
            const result = await runRobotkezTest(level);
            const sessionId = result.sessionId;
            
            // Connect to SSE stream
            // Note: This connects directly to Python FastAPI (port 8000)
            const evtSource = new EventSource(`http://localhost:8000/test/logs/${sessionId}`);
            
            evtSource.addEventListener('log', (e: MessageEvent) => {
                try {
                    const data = JSON.parse(e.data);
                    // Add timestamp? data.ts is available
                    setLogs(prev => [...prev, `[${data.level?.toUpperCase() || 'INFO'}] ${data.message}`]);
                } catch (err) {
                    console.error('Log parse error:', err);
                }
            });

            evtSource.addEventListener('done', (e: MessageEvent) => {
                try {
                    const data = JSON.parse(e.data);
                    setLogs(prev => [...prev, `\n--- KÉSZ (Exit: ${data.exitCode}, Idő: ${data.durationMs}ms) ---`]);
                    
                    if (data.status === 'success') {
                        toast.success(`Level ${level} teszt sikeres`);
                    } else {
                        toast.error('Teszt hibával zárult');
                    }
                } catch (err) {
                    console.error('Done parse error:', err);
                } finally {
                    evtSource.close();
                    setRunningTest(null);
                }
            });

            evtSource.onerror = (err) => {
                console.error('SSE Error:', err);
                evtSource.close();
                setRunningTest(null);
            };

        } catch (err: any) {
            toast.error(`Indítási hiba: ${err.message}`);
            setRunningTest(null);
        }
    };

    return (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-4 md:gap-6 p-3 md:p-6 pb-20 md:pb-6">
            {/* Session Control Card */}
            <Card className="lg:col-span-1 shadow-lg border-primary/20 bg-card/50 backdrop-blur-sm">
                <CardHeader className="p-4 md:p-6">
                    <div className="flex justify-between items-center">
                        <CardTitle className="flex items-center gap-2 text-base md:text-lg">
                            <Globe className="w-4 h-4 md:w-5 md:h-5 text-primary" />
                            Robotkéz Session
                        </CardTitle>
                        <Badge variant={status.active ? 'default' : 'secondary'} className={status.active ? 'bg-green-500/20 text-green-500 border-green-500/50 text-[10px]' : 'text-[10px]'}>
                            {status.active ? 'AKTÍV' : 'LEÁLLÍTVA'}
                        </Badge>
                    </div>
                </CardHeader>
                <CardContent className="p-4 md:p-6 pt-0 space-y-4">
                    <div className="flex gap-2">
                        <Button
                            className="flex-1 gap-2 h-9 md:h-10 text-sm"
                            onClick={handleStart}
                            disabled={loading || status.active}
                        >
                            {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Play className="w-4 h-4" />}
                            Start
                        </Button>
                        <Button
                            variant="destructive"
                            className="flex-1 gap-2 h-9 md:h-10 text-sm"
                            onClick={handleStop}
                            disabled={loading || !status.active}
                        >
                            <Square className="w-4 h-4" />
                            Stop
                        </Button>
                    </div>

                    <div className="pt-4 border-t border-primary/10">
                        <CardDescription className="mb-2 text-xs md:text-sm uppercase tracking-wider">Teszt Futtatás</CardDescription>
                        <div className="grid grid-cols-1 gap-2">
                            {[1, 2, 3].map(level => (
                                <Button
                                    key={level}
                                    variant="outline"
                                    className="justify-start gap-2 h-9 md:h-10 text-xs md:text-sm px-3"
                                    onClick={() => handleRunTest(level as any)}
                                    disabled={runningTest !== null}
                                >
                                    {runningTest === level ? <Loader2 className="w-3.5 h-3.5 animate-spin text-primary" /> : <Activity className="w-3.5 h-3.5 text-primary" />}
                                    Level {level} {level === 2 ? '(n8n)' : level === 3 ? '(Monitor)' : '(Nav)'}
                                </Button>
                            ))}
                        </div>
                    </div>
                </CardContent>
            </Card>

            {/* Live View Card */}
            <Card className="lg:col-span-2 shadow-lg border-primary/20 bg-card/50 backdrop-blur-sm overflow-hidden min-h-[350px] md:min-h-0">
                <CardHeader className="flex flex-row items-center justify-between p-4 md:p-6">
                    <CardTitle className="flex items-center gap-2 text-sm font-medium">
                        <Camera className="w-4 h-4 text-primary" />
                        Élő Nézet (5mp frissítés)
                    </CardTitle>
                    <Button variant="ghost" size="icon" onClick={refreshData} className="h-8 w-8" disabled={isRefreshing}>
                        <RefreshCw className={`w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}`} />
                    </Button>
                </CardHeader>
                <CardContent className="p-0 border-t border-primary/10 bg-black min-h-[250px] md:min-h-[300px] flex items-center justify-center relative group">
                    {screenshotUrl ? (
                        <>
                            <img
                                src={screenshotUrl}
                                alt="Robotkéz Screenshot"
                                className="w-full h-auto object-contain cursor-zoom-in transition-transform group-hover:scale-[1.01]"
                                onClick={() => window.open(screenshotUrl, '_blank')}
                            />
                            
                            {/* Click Point Visualization */}
                            {lastAction && (
                                <div 
                                    className="absolute w-6 h-6 md:w-8 md:h-8 border-2 md:border-4 border-red-500 rounded-full animate-ping pointer-events-none"
                                    style={{ 
                                        left: `${(lastAction.x / 1920) * 100}%`, 
                                        top: `${(lastAction.y / 1080) * 100}%`,
                                        transform: 'translate(-50%, -50%)'
                                    }}
                                />
                            )}

                            {/* Thought Bubble */}
                            {thought && (
                                <div className="absolute bottom-2 left-2 right-2 md:bottom-4 md:left-4 md:right-4 bg-primary/90 text-primary-foreground p-2 md:p-3 rounded-lg shadow-xl backdrop-blur-md animate-in slide-in-from-bottom-2 border border-white/20">
                                    <div className="flex items-center gap-2 text-[9px] md:text-xs font-bold uppercase tracking-widest opacity-70 mb-0.5 md:mb-1">
                                        <Zap className="w-2.5 h-2.5 md:w-3 md:h-3 fill-current" />
                                        Robotkéz Gondolata
                                    </div>
                                    <p className="text-xs md:text-sm font-medium italic">"{thought}"</p>
                                </div>
                            )}
                        </>
                    ) : (
                        <div className="text-zinc-500 flex flex-col items-center gap-2">
                            <Activity className="w-8 h-8 opacity-20" />
                            <span className="text-xs uppercase tracking-widest opacity-50 font-mono">IDLE_NO_STREAM</span>
                        </div>
                    )}
                </CardContent>
            </Card>

            {/* Logs Viewer */}
            <Card className="lg:col-span-2 shadow-lg border-primary/20 bg-card/50 backdrop-blur-sm">
                <CardHeader className="p-4 md:p-6">
                    <CardTitle className="flex items-center gap-2 text-sm font-medium uppercase tracking-wider">
                        <Terminal className="w-4 h-4 text-primary" />
                        Napló & Kimenet
                    </CardTitle>
                </CardHeader>
                <CardContent className="p-0 border-t border-primary/10">
                    <ScrollArea className="h-[150px] md:h-[200px] w-full bg-slate-950/80 p-3 md:p-4 font-mono text-[10px] md:text-xs text-green-400">
                        {logs.length === 0 ? (
                            <span className="opacity-30 italic">Üres - Várjuk a kimenetet...</span>
                        ) : (
                            logs.map((log, i) => (
                                <div key={i} className="mb-1 whitespace-pre-wrap flex gap-2">
                                    <span className="opacity-40 shrink-0">{i+1}.</span>
                                    <span>{log}</span>
                                </div>
                            ))
                        )}
                    </ScrollArea>
                </CardContent>
            </Card>

            {/* n8n Status Card */}
            <Card className="lg:col-span-1 shadow-lg border-primary/20 bg-card/50 backdrop-blur-sm">
                <CardHeader className="flex flex-row items-center justify-between p-4 md:p-6">
                    <CardTitle className="flex items-center gap-2 text-sm font-medium">
                        <div className="w-2 h-2 rounded-full bg-orange-500 animate-pulse" />
                        n8n Integráció
                    </CardTitle>
                    <Button variant="ghost" size="sm" onClick={fetchN8nWorkflows} disabled={n8nLoading} className="h-7 text-[10px] md:text-xs">
                        {n8nLoading ? <Loader2 className="w-3 h-3 animate-spin" /> : 'REFRESH'}
                    </Button>
                </CardHeader>
                <CardContent className="p-4 md:p-6 pt-0 space-y-4">
                    <div className="flex justify-between items-end">
                        <div>
                            <div className="text-xl md:text-2xl font-bold">{n8nWorkflows.length}</div>
                            <div className="text-[10px] text-zinc-500 uppercase">Aktív Workflow</div>
                        </div>
                        <Progress value={Math.min(n8nWorkflows.length * 10, 100)} className="h-1 w-16 md:w-20" />
                    </div>

                    <div className="space-y-1.5 md:space-y-2">
                        {n8nWorkflows.slice(0, 4).map((wf, idx) => (
                            <div key={idx} className="flex justify-between items-center text-[10px] md:text-xs p-2 bg-secondary/20 rounded border border-primary/5">
                                <span className="font-medium truncate max-w-[140px]">{wf.name}</span>
                                <Badge variant="outline" className="text-[9px] px-1.5 py-0 h-4 border-primary/20 font-mono">
                                    {wf.active ? 'LIVE' : 'IDLE'}
                                </Badge>
                            </div>
                        ))}
                        {n8nWorkflows.length === 0 && (
                            <div className="text-[10px] text-zinc-500 p-2 italic">Nincsenek elérhető workflow-k</div>
                        )}
                    </div>
                </CardContent>
            </Card>
        </div>
    );
}

/**
