interface ChatMessage {
  role: 'user' | 'assistant';
  content: string;
  timestamp: number;
  plan?: api.ExecutionPlan;
  taskId?: string;
  backgroundTask?: boolean;
  screenshot?: string; // NEW: for inline visual feedback
}

export function RobotkezV2Chat() {
  const { socket } = useSocket();
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [status, setStatus] = useState<api.RobotkezStatusResponse | null>(null);
  const [activePlan, setActivePlan] = useState<api.ExecutionPlan | null>(null);
  const [currentStep, setCurrentStep] = useState<number>(-1);
  const [showBrowserView, setShowBrowserView] = useState(true);
  const [screenshotUrl, setScreenshotUrl] = useState<string>('');
  const [backgroundTasks, setBackgroundTasks] = useState<api.BackgroundTask[]>([]);
  const [expandedTaskId, setExpandedTaskId] = useState<string | null>(null);
  const scrollRef = useRef<HTMLDivElement>(null);

  // --- Gépi Vezérlés állapotok ---
  const [viewMode, setViewMode] = useState<'chat' | 'computer' | 'devtools'>('chat');
  const [computerScreenB64, setComputerScreenB64] = useState<string>('');
  const [computerLoading, setComputerLoading] = useState(false);
  const [typeText, setTypeText] = useState('');
  const [visionDesc, setVisionDesc] = useState('');
  const [computerLog, setComputerLog] = useState<string[]>([]);
  const [autoTaskInput, setAutoTaskInput] = useState('');
  const [autoTaskRunning, setAutoTaskRunning] = useState(false);
  const [trainingRunning, setTrainingRunning] = useState(false);
  const [trainingMode, setTrainingMode] = useState<'basic' | 'workflows'>('basic');

  // --- DevTools állapotok ---
  const [devtoolsUrl, setDevtoolsUrl] = useState('http://localhost:5173');
  const [devtoolsLoading, setDevtoolsLoading] = useState(false);
  const [devtoolsReport, setDevtoolsReport] = useState<api.DevToolsDebugReport | null>(null);
  const [devtoolsMarkdown, setDevtoolsMarkdown] = useState('');
  const [isRefreshing, setIsRefreshing] = useState(false);

  const addComputerLog = (msg: string) => setComputerLog(prev => [msg, ...prev].slice(0, 20));

  const refreshComputerScreen = async () => {
    try {
      const data = await api.computerScreenshot();
      if (data.screenshot_b64) setComputerScreenB64(data.screenshot_b64);
    } catch (err) {
      addComputerLog(`❌ Képernyőfotó hiba: ${err instanceof Error ? err.message : String(err)}`);
    }
  };

  const handleComputerImageClick = async (e: React.MouseEvent<HTMLImageElement>) => {
    const img = e.currentTarget;
    const rect = img.getBoundingClientRect();
    const x_pct = (e.clientX - rect.left) / rect.width;
    const y_pct = (e.clientY - rect.top) / rect.height;
    setComputerLoading(true);
    try {
      const result = await api.computerClickPct(x_pct, y_pct);
      addComputerLog(`🖱️ Kattintás: (${(x_pct * 100).toFixed(1)}%, ${(y_pct * 100).toFixed(1)}%) → ${result.x}×${result.y}px`);
      await refreshComputerScreen();
    } catch (err) {
      addComputerLog(`❌ Kattintás hiba: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setComputerLoading(false);
    }
  };

  const handleComputerType = async () => {
    if (!typeText.trim()) return;
    setComputerLoading(true);
    try {
      await api.computerType(typeText);
      addComputerLog(`⌨️ Begépelve: "${typeText}"`);
      setTypeText('');
      await refreshComputerScreen();
    } catch (err) {
      addComputerLog(`❌ Gépelési hiba: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setComputerLoading(false);
    }
  };

  const handleVisionClick = async () => {
    if (!visionDesc.trim()) return;
    setComputerLoading(true);
    try {
      const result = await api.computerVisionClick(visionDesc);
      addComputerLog(`🎯 Vision kattintás: "${visionDesc}" → ${result.status}`);
      setVisionDesc('');
      await refreshComputerScreen();
    } catch (err) {
      addComputerLog(`❌ Vision kattintás hiba: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setComputerLoading(false);
    }
  };

  const handleAutoTask = async () => {
    if (!autoTaskInput.trim()) return;
    setAutoTaskRunning(true);
    addComputerLog(`🚀 Autonóm feladat indítása: "${autoTaskInput}"`);
    try {
      const result = await api.computerAutoTask(autoTaskInput);
      const cr = result.comet_result;
      if (cr.success) {
        addComputerLog(`✅ Feladat kész! ${cr.steps_completed} lépés, ${cr.attempts} próbálkozás`);
      } else {
        addComputerLog(`❌ Feladat sikertelen: ${cr.error ?? 'ismeretlen hiba'} (${cr.attempts} próba)`);
      }
      // Step log megjelenítése
      for (const entry of result.step_log) {
        if (entry['type'] === 'step_done') {
          const icon = entry['success'] ? '✓' : '✗';
          addComputerLog(`  ${icon} ${entry['action'] ?? '?'}`);
        }
      }
      setAutoTaskInput('');
      await refreshComputerScreen();
    } catch (err) {
      addComputerLog(`❌ Auto feladat hiba: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setAutoTaskRunning(false);
    }
  };

  const handleTrainingToggle = async () => {
    if (trainingRunning) {
      try {
        await api.robotkezTrainingStop();
        addComputerLog('⏹ Tréning leállítva');
        setTrainingRunning(false);
      } catch (err) {
        addComputerLog(`❌ Tréning leállítás hiba: ${err instanceof Error ? err.message : String(err)}`);
      }
    } else {
      try {
        const result = await api.robotkezTrainingStart(trainingMode);
        addComputerLog(`▶ Tréning elindult (${trainingMode}, PID: ${result.pid})`);
        setTrainingRunning(true);
      } catch (err) {
        addComputerLog(`❌ Tréning indítás hiba: ${err instanceof Error ? err.message : String(err)}`);
      }
    }
  };

  // DevTools debug futtatás
  const handleDevToolsRun = async () => {
    if (!devtoolsUrl.trim()) return;
    setDevtoolsLoading(true);
    setDevtoolsReport(null);
    setDevtoolsMarkdown('');
    try {
      const result = await api.robotkezDevToolsReport(devtoolsUrl);
      if (result.success) {
        setDevtoolsReport(result.report);
        setDevtoolsMarkdown(result.markdown);
        toast.success('DevTools riport kész');
      } else {
        toast.error('DevTools riport sikertelen');
      }
    } catch (err) {
      toast.error(`DevTools hiba: ${err instanceof Error ? err.message : String(err)}`);
    } finally {
      setDevtoolsLoading(false);
    }
  };

  // Tréning állapot ellenőrzés (10s)
  useEffect(() => {
    if (viewMode !== 'computer') return;
    const checkTraining = async () => {
      try {
        const st = await api.robotkezTrainingStatus();
        setTrainingRunning(st.running);
      } catch { /* ignore */ }
    };
    checkTraining();
    const interval = setInterval(checkTraining, 10000);
    return () => clearInterval(interval);
  }, [viewMode]);

  // Gépi Vezérlés auto-frissítés (3s)
  useEffect(() => {
    if (viewMode !== 'computer') return;
    refreshComputerScreen();
    const interval = setInterval(refreshComputerScreen, 3000);
    return () => clearInterval(interval);
  }, [viewMode]);

  // Socket.IO: valós idejű Comet step események
  useEffect(() => {
    if (!socket) return;
    const handler = (data: Record<string, unknown>) => {
      const t = data['type'] as string;
      if (t === 'step_done') {
        const icon = data['success'] ? '✅' : '❌';
        addComputerLog(`${icon} [${(data['step_index'] as number) + 1}] ${data['action'] ?? '?'} — ${data['description'] ?? ''}`);
      } else if (t === 'attempt_start') {
        addComputerLog(`🔄 Próbálkozás ${data['attempt']}/${data['max_retries']}: ${data['task'] ?? ''}`);
      } else if (t === 'step_start') {
        addComputerLog(`⏳ [${(data['step_index'] as number) + 1}/${data['total_steps']}] ${data['description'] ?? data['action']}`);
      }
    };
    socket.on('robotkez:step', handler);
    return () => { socket.off('robotkez:step', handler); };
  }, [socket]);

  // Auto-scroll to bottom when new messages arrive
  useEffect(() => {
    scrollRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Refresh status, screenshot, and background tasks
  const refreshData = async () => {
    setIsRefreshing(true);
    try {
      const statusData = await api.robotkezStatus();
      setStatus(statusData);

      // Refresh screenshot (if browser active)
      if (statusData.browser.active) {
        setScreenshotUrl(`/api/v1/robotkez/screenshot?t=${Date.now()}`);
      } else {
        setScreenshotUrl('');
      }

      // Refresh background tasks
      const tasksData = await api.robotkezGetTasks();
      setBackgroundTasks(tasksData.tasks);

      // Update active task details if expanded
      if (expandedTaskId) {
        const taskDetail = await api.robotkezGetTaskById(expandedTaskId);
        setBackgroundTasks(prev =>
          prev.map(t => t.id === expandedTaskId ? taskDetail.task : t)
        );
      }
    } catch (err) {
      console.error('[RobotkezV2Chat] Refresh error:', err instanceof Error ? err.message : String(err));
    } finally {
      setIsRefreshing(false);
    }
  };

  // Auto-refresh hook (2s interval)
  useEffect(() => {
    refreshData();
    const interval = setInterval(refreshData, 2000);
    return () => clearInterval(interval);
  }, [expandedTaskId]);

  // Send chat message
  const send = async () => {
    const text = input.trim();
    if (!text || isLoading) return;

    setInput('');
    const userMsg: ChatMessage = {
      role: 'user',
      content: text,
      timestamp: Date.now()
    };
    setMessages(prev => [...prev, userMsg]);
    setIsLoading(true);
    setActivePlan(null);
    setCurrentStep(-1);

    try {
      const result = await api.robotkezChat(text);

      // Check if task was delegated to background
      if (result.data?.taskId) {
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: result.message,
          timestamp: Date.now(),
          taskId: result.data.taskId,
          plan: result.data.plan,
          backgroundTask: true
        }]);
        toast.info('Háttérben fut - lásd Background Tasks');
      } else {
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: result.message || (result.success ? 'Kész!' : 'Hiba történt'),
          timestamp: Date.now(),
          screenshot: result.data?.screenshot
        }]);
        toast.success('Feladat befejezve');
      }
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : 'Hiba történt';
      toast.error(msg);
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: `❌ Hiba: ${msg}`,
        timestamp: Date.now()
      }]);
    } finally {
      setIsLoading(false);
      refreshData();
    }
  };

  // Preview execution plan
  const previewPlan = async () => {
    const text = input.trim();
    if (!text) return;

    try {
      const planData = await api.robotkezPlan(text);
      setActivePlan(planData.plan);
      setCurrentStep(-1);
      toast.info(`Terv előnézet: ${planData.plan.plan.length} lépés`);
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : 'Plan előnézet hiba';
      toast.error(msg);
    }
  };

  // Cancel background task
  const cancelTask = async (id: string) => {
    try {
      await api.robotkezCancelTask(id);
      toast.success('Feladat megszakítva');
      refreshData();
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : 'Megszakítás sikertelen';
      toast.error(msg);
    }
  };

  // Toggle task details
  const toggleTaskDetails = (id: string) => {
    setExpandedTaskId(prev => prev === id ? null : id);
  };

  // Step status icon helper
  const getStepIcon = (status: api.TaskStep['status']) => {
    switch (status) {
      case 'completed':
        return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'running':
        return <Loader className="w-4 h-4 text-blue-500 animate-spin" />;
      case 'error':
        return <XCircle className="w-4 h-4 text-red-500" />;
      default:
        return <Circle className="w-4 h-4 text-zinc-500" />;
    }
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 p-6 h-full">
      {/* Left Column: Chat + Timeline */ }
      <div className="lg:col-span-2 space-y-6">
        {/* Chat Card */ }
        <Card className="glass-card border-border/50 bg-background/50 backdrop-blur-xl flex flex-col h-[500px] overflow-hidden">
          <CardHeader className="flex flex-row items-center justify-between pb-2 border-b border-border/50">
            <CardTitle className="flex items-center gap-2 text-base font-medium">
              <Bot className="w-5 h-5 text-primary" />
              Robotkéz V2 - Magyar Agentic Browser
            </CardTitle>
            <div className="flex items-center gap-2">
              <Badge variant={ status?.browser.active ? 'default' : 'secondary' } className={ status?.browser.active ? 'bg-green-500/20 text-green-500 border-green-500/50' : '' }>
                { status?.browser.active ? 'AKTÍV' : 'LEÁLLÍTVA' }
              </Badge>
              { status?.browser.engine && (
                <Badge
                  variant="outline"
                  className={
                    status.browser.engine.toLowerCase().includes('cloudflare')
                      ? 'bg-blue-500/10 text-blue-400 border-blue-400/40'
                      : 'bg-zinc-500/10 text-zinc-300 border-zinc-400/30'
                  }
                >
                  { status.browser.engine.toLowerCase().includes('cloudflare') ? '☁ CF Browser' : '🖥 Local' }
                </Badge>
              ) }
              <Button variant="ghost" size="icon" onClick={ refreshData } title="Frissítés" aria-label="Adatok frissítése" disabled={ isRefreshing }>
                <RefreshCw className={ `w-4 h-4 ${isRefreshing ? 'animate-spin' : ''}` } />
              </Button>
            </div>
          </CardHeader>

          {/* Mode Switcher Tab Bar */ }
          <div className="flex border-b border-border/50 bg-background/30">
            <button
              onClick={ () => setViewMode('chat') }
              className={ `flex items-center gap-1.5 px-4 py-2 text-xs font-medium transition-colors ${viewMode === 'chat'
                  ? 'border-b-2 border-primary text-primary bg-primary/5'
                  : 'text-zinc-500 hover:text-foreground'
                }` }
            >
              <Bot className="w-3.5 h-3.5" />
              Böngésző Chat
            </button>
            <button
              onClick={ () => setViewMode('computer') }
              className={ `flex items-center gap-1.5 px-4 py-2 text-xs font-medium transition-colors ${viewMode === 'computer'
                  ? 'border-b-2 border-primary text-primary bg-primary/5'
                  : 'text-zinc-500 hover:text-foreground'
                }` }
            >
              <Monitor className="w-3.5 h-3.5" />
              Gépi Vezérlés
            </button>
            <button
              onClick={ () => setViewMode('devtools') }
              className={ `flex items-center gap-1.5 px-4 py-2 text-xs font-medium transition-colors ${viewMode === 'devtools'
                  ? 'border-b-2 border-primary text-primary bg-primary/5'
                  : 'text-zinc-500 hover:text-foreground'
                }` }
            >
              <Bug className="w-3.5 h-3.5" />
              DevTools
            </button>
          </div>

          <CardContent className="flex-1 flex flex-col min-h-0 p-0">
            {/* === CHAT MÓD === */ }
            { viewMode === 'chat' && (<>
              {/* Message History */ }
              <ScrollArea className="flex-1 px-4">
                <div className="space-y-4 py-4">
                  { messages.length === 0 && (
                    <div className="flex flex-col items-center justify-center py-12 text-center space-y-4">
                      <div className="p-4 rounded-full bg-primary/10 border border-primary/20">
                        <Activity className="w-8 h-8 text-primary animate-pulse" />
                      </div>
                      <div className="space-y-1">
                        <p className="text-sm font-medium text-foreground/80">
                          RobotkezV2 készen áll
                        </p>
                        <p className="text-xs text-zinc-500 max-w-xs">
                          Adj magyar nyelvű utasításokat a böngésző automatizálásához!
                        </p>
                      </div>
                    </div>
                  ) }
                  { messages.map((msg, i) => (
                    <div
                      key={ i }
                      className={ `flex gap-3 ${msg.role === 'user' ? 'justify-end' : 'justify-start'} animate-in fade-in slide-in-from-bottom-2 duration-300` }
                    >
                      { msg.role === 'assistant' && (
                        <div className="h-8 w-8 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center shrink-0">
                          <Bot className="w-4 h-4 text-primary" />
                        </div>
                      ) }
                      <div className="flex flex-col gap-1.5 max-w-[85%]">
                        <div
                          className={ `rounded-2xl px-4 py-2.5 text-sm shadow-sm ${msg.role === 'user'
                            ? 'bg-primary text-primary-foreground font-medium'
                            : 'bg-muted/50 border border-border/50 text-foreground'
                            }` }
                        >
                          <p className="whitespace-pre-wrap leading-relaxed">
                            { msg.content }
                          </p>
                          { msg.screenshot && (
                            <div className="mt-2 rounded-lg overflow-hidden border border-border/50 bg-white/[0.02]">
                              <img
                                src={ msg.screenshot.startsWith('data:') ? msg.screenshot : `data:image/png;base64,${msg.screenshot}` }
                                alt="Screenshot"
                                className="w-full h-auto cursor-zoom-in hover:scale-[1.02] transition-transform"
                                onClick={ () => window.open(msg.screenshot?.startsWith('data:') ? msg.screenshot : `data:image/png;base64,${msg.screenshot}`, '_blank') }
                              />
                            </div>
                          ) }
                        </div>

                        {/* Background Task Badge */ }
                        { msg.backgroundTask && msg.taskId && (
                          <button
                            onClick={ () => toggleTaskDetails(msg.taskId!) }
                            className="flex items-center gap-1.5 text-[10px] uppercase font-bold tracking-widest text-zinc-500 hover:text-primary transition-colors w-fit px-2 py-1 rounded bg-blue-500/10 border border-blue-500/20"
                          >
                            <Clock className="w-3 h-3" />
                            Háttérben fut - Task ID: { msg.taskId.slice(0, 8) }
                          </button>
                        ) }
                      </div>
                      { msg.role === 'user' && (
                        <div className="h-8 w-8 rounded-full bg-primary/10 border border-primary/20 flex items-center justify-center shrink-0">
                          <User className="w-4 h-4 text-primary" />
                        </div>
                      ) }
                    </div>
                  )) }
                  { isLoading && (
                    <div className="flex gap-3">
                      <div className="h-8 w-8 rounded-full bg-primary/20 flex items-center justify-center shrink-0">
                        <Loader className="w-4 h-4 text-primary animate-spin" />
                      </div>
                      <div className="bg-muted/50 rounded-lg px-3 py-2 border border-border/50">
                        <p className="text-sm text-zinc-500">Feldolgozás...</p>
                      </div>
                    </div>
                  ) }
                  <div ref={ scrollRef } />
                </div>
              </ScrollArea>

              {/* Input Area */ }
              <div className="p-4 border-t border-border/50">
                <div className="flex gap-2 mb-2">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={ previewPlan }
                    disabled={ !input.trim() || isLoading }
                    className="text-xs"
                  >
                    Terv előnézet
                  </Button>
                </div>
                <div className="flex gap-2">
                  <Textarea
                    value={ input }
                    onChange={ (e) => setInput(e.target.value) }
                    onKeyDown={ (e) =>
                      e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), send())
                    }
                    placeholder="pl. 'Navigálj a google.com-ra és keress rá az AI hírekre'"
                    className="min-h-[60px] bg-background/50 border-border resize-none"
                    disabled={ isLoading }
                  />
                  <Button
                    onClick={ send }
                    disabled={ !input.trim() || isLoading }
                    className="shrink-0"
                  >
                    <Send className="w-4 h-4" />
                  </Button>
                </div>
              </div>
            </>) }

            {/* === GÉPI VEZÉRLÉS MÓD === */ }
            { viewMode === 'computer' && (
              <div className="flex-1 flex flex-col min-h-0 overflow-hidden">
                {/* OS Képernyő (kattintható) */ }
                <div className="flex-1 bg-black min-h-0 relative overflow-hidden">
                  { computerLoading && (
                    <div className="absolute inset-0 bg-black/60 flex items-center justify-center z-10">
                      <Loader className="w-6 h-6 text-primary animate-spin" />
                    </div>
                  ) }
                  { computerScreenB64 ? (
                    <img
                      src={ `data:image/png;base64,${computerScreenB64}` }
                      alt="Képernyő"
                      className="w-full h-full object-contain cursor-crosshair"
                      onClick={ handleComputerImageClick }
                      title="Kattints ide a képernyőn való kattintáshoz"
                    />
                  ) : (
                    <div className="flex items-center justify-center h-full text-zinc-500 flex-col gap-2">
                      <Monitor className="w-8 h-8 opacity-20" />
                      <span className="text-xs uppercase tracking-widest opacity-50">
                        Képernyő betöltése...
                      </span>
                    </div>
                  ) }
                </div>

                {/* Vezérlők */ }
                <div className="p-3 border-t border-border/50 space-y-2 bg-background/80">
                  {/* Gépelés sor */ }
                  <div className="flex gap-2">
                    <div className="flex items-center gap-1 text-zinc-500 shrink-0">
                      <Keyboard className="w-4 h-4" />
                    </div>
                    <input
                      type="text"
                      value={ typeText }
                      onChange={ e => setTypeText(e.target.value) }
                      onKeyDown={ e => e.key === 'Enter' && handleComputerType() }
                      placeholder="Begépelendő szöveg (Enter = küld)"
                      className="flex-1 bg-background/50 border border-border/50 rounded px-3 py-1.5 text-sm focus:outline-none focus:ring-1 focus:ring-primary/50"
                      disabled={ computerLoading }
                    />
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={ handleComputerType }
                      disabled={ !typeText.trim() || computerLoading }
                    >
                      <Send className="w-3 h-3" />
                    </Button>
                  </div>

                  {/* Vision kattintás sor */ }
                  <div className="flex gap-2">
                    <div className="flex items-center gap-1 text-zinc-500 shrink-0">
                      <Crosshair className="w-4 h-4" />
                    </div>
                    <input
                      type="text"
                      value={ visionDesc }
                      onChange={ e => setVisionDesc(e.target.value) }
                      onKeyDown={ e => e.key === 'Enter' && handleVisionClick() }
                      placeholder="Vision kattintás: pl. 'Start gomb', 'Böngésző ikon'"
                      className="flex-1 bg-background/50 border border-border/50 rounded px-3 py-1.5 text-sm focus:outline-none focus:ring-1 focus:ring-primary/50"
                      disabled={ computerLoading }
                    />
                    <Button
                      size="sm"
                      variant="outline"
                      onClick={ handleVisionClick }
                      disabled={ !visionDesc.trim() || computerLoading }
                    >
                      <MousePointer className="w-3 h-3" />
                    </Button>
                  </div>

                  {/* Autonóm feladat sor (Comet Orchestrator) */ }
                  <div className="flex gap-2">
                    <div className="flex items-center gap-1 text-zinc-500 shrink-0">
                      <Bot className="w-4 h-4" />
                    </div>
                    <input
                      type="text"
                      value={ autoTaskInput }
                      onChange={ e => setAutoTaskInput(e.target.value) }
                      onKeyDown={ e => e.key === 'Enter' && handleAutoTask() }
                      placeholder="Autonóm feladat: pl. 'Keress rá a Google-on az AI hírekre'"
                      className="flex-1 bg-background/50 border border-border/50 rounded px-3 py-1.5 text-sm focus:outline-none focus:ring-1 focus:ring-primary/50"
                      disabled={ autoTaskRunning }
                    />
                    <Button
                      size="sm"
                      variant={ autoTaskRunning ? 'secondary' : 'default' }
                      onClick={ handleAutoTask }
                      disabled={ !autoTaskInput.trim() || autoTaskRunning }
                    >
                      { autoTaskRunning ? <Loader className="w-3 h-3 animate-spin" /> : <Send className="w-3 h-3" /> }
                    </Button>
                  </div>

                  {/* Training vezérlés */ }
                  <div className="flex gap-2 items-center pt-1 border-t border-border/30">
                    <span className="text-[10px] text-zinc-500 shrink-0 uppercase tracking-wider">Tréning:</span>
                    <select
                      value={ trainingMode }
                      onChange={ e => setTrainingMode(e.target.value as 'basic' | 'workflows') }
                      className="bg-background/50 border border-border/50 rounded px-2 py-1 text-xs focus:outline-none"
                      disabled={ trainingRunning }
                    >
                      <option value="basic">Alapfeladatok</option>
                      <option value="workflows">n8n Workflow Builder</option>
                    </select>
                    <Button
                      size="sm"
                      variant={ trainingRunning ? 'destructive' : 'default' }
                      onClick={ handleTrainingToggle }
                      className="text-xs"
                    >
                      { trainingRunning ? '⏹ Leállítás' : '▶ Indítás' }
                    </Button>
                    { trainingRunning && (
                      <Badge variant="secondary" className="bg-green-500/20 text-green-500 text-[10px] animate-pulse">
                        Fut
                      </Badge>
                    ) }
                  </div>

                  {/* Eseménynapló */ }
                  { computerLog.length > 0 && (
                    <div className="max-h-[72px] overflow-y-auto space-y-0.5">
                      { computerLog.map((entry, i) => (
                        <p key={ i } className="text-[10px] text-zinc-500 font-mono truncate">{ entry }</p>
                      )) }
                    </div>
                  ) }
                </div>
              </div>
            ) }

            {/* === DEVTOOLS MÓD === */ }
            { viewMode === 'devtools' && (
              <div className="flex-1 flex flex-col min-h-0 overflow-auto">
                {/* URL input + Futtatás */ }
                <div className="p-4 border-b border-border/50 space-y-3">
                  <div className="flex gap-2">
                    <input
                      type="text"
                      value={ devtoolsUrl }
                      onChange={ e => setDevtoolsUrl(e.target.value) }
                      onKeyDown={ e => e.key === 'Enter' && handleDevToolsRun() }
                      placeholder="URL (pl. http://localhost:5173)"
                      className="flex-1 bg-background/50 border border-border/50 rounded px-3 py-2 text-sm focus:outline-none focus:ring-1 focus:ring-primary/50"
                      disabled={ devtoolsLoading }
                    />
                    <Button
                      onClick={ handleDevToolsRun }
                      disabled={ !devtoolsUrl.trim() || devtoolsLoading }
                    >
                      { devtoolsLoading ? <Loader className="w-4 h-4 animate-spin" /> : <Bug className="w-4 h-4" /> }
                      <span className="ml-1.5">Elemzés</span>
                    </Button>
                  </div>
                  <p className="text-[10px] text-zinc-500">
                    Hálózati kérések, JS hibák és teljesítmény metrikák elemzése Playwright CDP-vel
                  </p>
                </div>

                {/* Eredmények */ }
                <div className="flex-1 overflow-auto p-4 space-y-4">
                  { devtoolsLoading && (
                    <div className="flex flex-col items-center justify-center py-12 gap-3">
                      <Loader className="w-8 h-8 text-primary animate-spin" />
                      <p className="text-sm text-zinc-500">Elemzés folyamatban... (böngésző indítás + adatgyűjtés)</p>
                    </div>
                  ) }

                  { devtoolsReport && !devtoolsLoading && (
                    <>
                      {/* Összefoglaló kártyák */ }
                      <div className="grid grid-cols-2 sm:grid-cols-4 gap-2">
                        <div className="bg-muted/30 border border-border/30 rounded-lg p-3 text-center">
                          <p className="text-lg font-bold">{ devtoolsReport.performance.pageLoadTime.toFixed(0) }</p>
                          <p className="text-[10px] text-zinc-500 uppercase">Page Load (ms)</p>
                        </div>
                        <div className="bg-muted/30 border border-border/30 rounded-lg p-3 text-center">
                          <p className="text-lg font-bold">{ devtoolsReport.performance.firstContentfulPaint.toFixed(0) }</p>
                          <p className="text-[10px] text-zinc-500 uppercase">FCP (ms)</p>
                        </div>
                        <div className={ `border rounded-lg p-3 text-center ${devtoolsReport.console.errors.length > 0 ? 'bg-red-500/10 border-red-500/30' : 'bg-muted/30 border-border/30'}` }>
                          <p className="text-lg font-bold">{ devtoolsReport.console.errors.length }</p>
                          <p className="text-[10px] text-zinc-500 uppercase">JS Hibák</p>
                        </div>
                        <div className={ `border rounded-lg p-3 text-center ${devtoolsReport.network.failedRequests > 0 ? 'bg-orange-500/10 border-orange-500/30' : 'bg-muted/30 border-border/30'}` }>
                          <p className="text-lg font-bold">{ devtoolsReport.network.failedRequests }</p>
                          <p className="text-[10px] text-zinc-500 uppercase">Hálózati Hiba</p>
                        </div>
                      </div>

                      {/* Összefoglaló szöveg */ }
                      <div className="bg-muted/20 border border-border/30 rounded-lg p-3">
                        <p className="text-xs whitespace-pre-wrap">{ devtoolsReport.summary }</p>
                      </div>

                      {/* JS Hibák */ }
                      { devtoolsReport.console.errors.length > 0 && (
                        <div>
                          <h4 className="text-xs font-semibold mb-2 text-red-500">JS Hibák ({ devtoolsReport.console.errors.length })</h4>
                          <div className="space-y-1">
                            { devtoolsReport.console.errors.map((err, i) => (
                              <div key={ i } className="bg-red-500/5 border border-red-500/20 rounded p-2 text-xs font-mono">
                                <span className="text-red-400">{ err.message }</span>
                                { err.source && <span className="text-zinc-500 ml-2">@ { err.source }{ err.line ? `:${err.line}` : '' }</span> }
                              </div>
                            )) }
                          </div>
                        </div>
                      ) }

                      {/* Figyelmeztetések */ }
                      { devtoolsReport.console.warnings.length > 0 && (
                        <div>
                          <h4 className="text-xs font-semibold mb-2 text-yellow-500">Figyelmeztetések ({ devtoolsReport.console.warnings.length })</h4>
                          <div className="space-y-1">
                            { devtoolsReport.console.warnings.slice(0, 5).map((w, i) => (
                              <p key={ i } className="text-xs font-mono text-yellow-400 truncate">{ w.message }</p>
                            )) }
                            { devtoolsReport.console.warnings.length > 5 && (
                              <p className="text-[10px] text-zinc-500">...és még { devtoolsReport.console.warnings.length - 5 } további</p>
                            ) }
                          </div>
                        </div>
                      ) }

                      {/* Hálózati hibák */ }
                      { devtoolsReport.network.failedRequestsList.length > 0 && (
                        <div>
                          <h4 className="text-xs font-semibold mb-2 text-orange-500">Sikertelen Kérések ({ devtoolsReport.network.failedRequestsList.length })</h4>
                          <div className="space-y-1">
                            { devtoolsReport.network.failedRequestsList.map((req, i) => (
                              <div key={ i } className="text-xs font-mono truncate">
                                <span className="text-orange-400">{ req.url }</span>
                                <span className="text-zinc-500"> — { req.error }</span>
                              </div>
                            )) }
                          </div>
                        </div>
                      ) }

                      {/* Hálózati összesítés */ }
                      <div>
                        <h4 className="text-xs font-semibold mb-2">Hálózat ({ devtoolsReport.network.totalRequests } kérés)</h4>
                        <div className="text-xs text-zinc-500">
                          { devtoolsReport.network.requests
                            .sort((a, b) => b.duration - a.duration)
                            .slice(0, 5)
                            .map((r, i) => (
                              <div key={ i } className="flex justify-between py-0.5 border-b border-border/20">
                                <span className="truncate flex-1 mr-2">{ r.url.length > 60 ? r.url.slice(0, 57) + '...' : r.url }</span>
                                <span className="shrink-0 font-mono">{ r.status } { r.duration.toFixed(0) }ms</span>
                              </div>
                            )) }
                        </div>
                      </div>
                    </>
                  ) }

                  { !devtoolsReport && !devtoolsLoading && (
                    <div className="flex flex-col items-center justify-center py-12 text-center space-y-3">
                      <Bug className="w-8 h-8 text-zinc-500 opacity-20" />
                      <p className="text-xs text-zinc-500">Adj meg egy URL-t és kattints az Elemzés gombra</p>
                    </div>
                  ) }
                </div>
              </div>
            ) }
          </CardContent>
        </Card>

        {/* Execution Timeline */ }
        { activePlan && (
          <Card className="glass-card border-border/50 bg-background/50 backdrop-blur-xl">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-sm font-medium">
                <Activity className="w-4 h-4 text-primary" />
                Végrehajtási Terv ({ activePlan.plan.length } lépés)
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="space-y-2">
                { activePlan.plan.map((step, i) => (
                  <div
                    key={ i }
                    className="flex items-start gap-3 p-2 rounded bg-muted/30 border border-border/30"
                  >
                    { getStepIcon(currentStep === i ? 'running' : currentStep > i ? 'completed' : 'pending') }
                    <div className="flex-1">
                      <p className="text-sm font-medium">{ step.action }</p>
                      <p className="text-xs text-zinc-500">{ step.description }</p>
                    </div>
                  </div>
                )) }
              </div>
              <div className="mt-4">
                <div className="flex justify-between text-xs text-zinc-500 mb-1">
                  <span>Becsült idő</span>
                  <span>{ (activePlan.estimatedDuration / 1000).toFixed(1) }s</span>
                </div>
                <Progress value={ currentStep >= 0 ? ((currentStep + 1) / activePlan.plan.length) * 100 : 0 } className="h-1" />
              </div>
            </CardContent>
          </Card>
        ) }
      </div>

      {/* Right Column: Live View + Background Tasks */ }
      <div className="space-y-6">
        {/* Live Browser View */ }
        <Card className="glass-card border-border/50 bg-background/50 backdrop-blur-xl overflow-hidden">
          <CardHeader className="flex flex-row items-center justify-between pb-2 border-b border-border/50">
            <CardTitle className="flex items-center gap-2 text-sm font-medium">
              <Eye className="w-4 h-4 text-primary" />
              Élő Nézet (2s frissítés)
            </CardTitle>
            <Button
              variant="ghost"
              size="icon"
              onClick={ () => setShowBrowserView(!showBrowserView) }
              title={ showBrowserView ? 'Elrejtés' : 'Megjelenítés' }
              aria-label={ showBrowserView ? 'Élő nézet elrejtése' : 'Élő nézet megjelenítése' }
            >
              { showBrowserView ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" /> }
            </Button>
          </CardHeader>
          { showBrowserView && (
            <CardContent className="p-0 border-t border-border/50 bg-black min-h-[300px] flex items-center justify-center">
              { screenshotUrl ? (
                <img
                  src={ screenshotUrl }
                  alt="Böngésző nézet"
                  className="w-full h-auto object-contain cursor-zoom-in transition-transform hover:scale-105"
                  onClick={ () => window.open(screenshotUrl, '_blank') }
                />
              ) : (
                <div className="text-zinc-500 flex flex-col items-center gap-2">
                  <Activity className="w-8 h-8 opacity-20" />
                  <span className="text-xs uppercase tracking-widest opacity-50">Nincs aktív kép</span>
                </div>
              ) }
            </CardContent>
          ) }
        </Card>

        {/* Background Tasks Panel */ }
        <Card className="glass-card border-border/50 bg-background/50 backdrop-blur-xl">
          <CardHeader className="flex flex-row items-center justify-between pb-2 border-b border-border/50">
            <CardTitle className="flex items-center gap-2 text-sm font-medium">
              <Clock className="w-4 h-4 text-primary" />
              Háttér Feladatok ({ backgroundTasks.length })
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <ScrollArea className="h-[300px]">
              <div className="p-4 space-y-2">
                { backgroundTasks.length === 0 ? (
                  <div className="text-xs text-zinc-500 text-center py-8">
                    Nincsenek háttér feladatok
                  </div>
                ) : (
                  backgroundTasks.map((task) => (
                    <div key={ task.id } className="border border-border/50 rounded-lg bg-muted/20">
                      <div
                        className="flex items-center justify-between p-3 cursor-pointer hover:bg-muted/30 transition-colors"
                        onClick={ () => toggleTaskDetails(task.id) }
                      >
                        <div className="flex-1">
                          <p className="text-xs font-medium truncate">{ task.instruction }</p>
                          <div className="flex items-center gap-2 mt-1">
                            <Badge
                              variant={ task.status === 'completed' ? 'default' : task.status === 'error' ? 'destructive' : 'secondary' }
                              className="text-[10px] h-4"
                            >
                              { task.status }
                            </Badge>
                            <span className="text-[10px] text-zinc-500">{ task.progress }%</span>
                          </div>
                        </div>
                        { task.status === 'running' && (
                          <Button
                            variant="ghost"
                            size="icon"
                            className="h-6 w-6"
                            title="Folyamat leállítása"
                            aria-label="Folyamat leállítása"
                            onClick={ (e) => {
                              e.stopPropagation();
                              cancelTask(task.id);
                            } }
                          >
                            <X className="w-3 h-3" />
                          </Button>
                        ) }
                      </div>

                      {/* Task Details (expanded) */ }
                      { expandedTaskId === task.id && (
                        <div className="border-t border-border/50 p-3 space-y-2 bg-background/50">
                          <Progress value={ task.progress } className="h-1" />
                          <div className="space-y-1">
                            { task.steps.map((step, i) => (
                              <div key={ i } className="flex items-start gap-2 text-xs">
                                { getStepIcon(step.status) }
                                <span className={ step.status === 'completed' ? 'text-zinc-500 line-through' : '' }>
                                  { step.description }
                                </span>
                              </div>
                            )) }
                          </div>
                          { task.error && (
                            <div className="text-xs text-red-500 bg-red-500/10 border border-red-500/20 rounded p-2">
                              { task.error }
                            </div>
                          ) }
                        </div>
                      ) }
                    </div>
                  ))
                ) }
              </div>
            </ScrollArea>
          </CardContent>
        </Card>

        {/* Agent Status Card */ }
        { status && (
          <Card className="glass-card border-border/50 bg-background/50 backdrop-blur-xl">
            <CardHeader className="pb-2 border-b border-border/50">
              <CardTitle className="text-sm font-medium">Agent Státusz</CardTitle>
            </CardHeader>
            <CardContent className="pt-4 space-y-2 text-xs">
              <div className="flex justify-between">
                <span className="text-zinc-500">Név:</span>
                <span className="font-medium">{ status.agent.name }</span>
              </div>
              <div className="flex justify-between">
                <span className="text-zinc-500">Szerepkör:</span>
                <span className="font-medium">{ status.agent.role }</span>
              </div>
              <div className="flex justify-between">
                <span className="text-zinc-500">Futó feladatok:</span>
                <span className="font-medium text-blue-500">{ status.tasks.running }</span>
              </div>
              <div className="flex justify-between">
                <span className="text-zinc-500">Befejezett:</span>
                <span className="font-medium text-green-500">{ status.tasks.completed }</span>
              </div>
              <div className="flex justify-between">
                <span className="text-zinc-500">Hibák:</span>
                <span className="font-medium text-red-500">{ status.tasks.error }</span>
              </div>
            </CardContent>
          </Card>
        ) }
      </div>
    </div>
  );
}

import React, { useState, useEffect, useMemo } from 'react';
import {
    Trello,
    Zap,
    ArrowRight,
    CheckCircle2,
    XCircle,
    Loader2,
    Mail,
    MessageSquare,
    Calendar,
    Handshake,
    Filter,
    BarChart3,
    UserPlus,
    Building2,
    ChevronDown,
    FileText
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '../ui/card';
import { Button } from '../ui/button';
import { Badge } from '../ui/badge';
import { ScrollArea } from '../ui/scroll-area';
import { toast } from 'sonner';
import { useSocket } from '../../context/SocketContext';
import { useBusinessStore } from '../../lib/businessStore';
import { format } from 'date-fns';

const STAGES = [
    { id: 'new', label: 'Új Leadek', icon: <UserPlus className="w-3 h-3" />, color: 'bg-blue-500' },
    { id: 'outreach', label: 'Megkeresés', icon: <Mail className="w-3 h-3" />, color: 'bg-purple-500' },
    { id: 'responded', label: 'Válaszolt', icon: <MessageSquare className="w-3 h-3" />, color: 'bg-orange-500' },
    { id: 'meeting', label: 'Tárgyalás', icon: <Calendar className="w-3 h-3" />, color: 'bg-yellow-500' },
    { id: 'loi', label: 'Szándéknyilatkozat', icon: <FileText className="w-3 h-3" />, color: 'bg-emerald-500' },
    { id: 'closed', label: 'Lezárva', icon: <Handshake className="w-3 h-3" />, color: 'bg-green-600' }
];

export function SalesPipelineWidget() {
    const [leads, setLeads] = useState<any[]>([]);
    const [stats, setStats] = useState<any>({});
    const [isLoadingLeads, setIsLoadingLeads] = useState(false);
    const { socket } = useSocket();

    const fetchPipelineData = async () => {
        setIsLoadingLeads(true);
        try {
            // Overall stats
            const statsRes = await fetch('/api/v1/business-jobs/pipeline/stats');
            const statsData = await statsRes.json();
            if (statsData.success) {
                const s: any = {};
                statsData.stats.forEach((item: any) => s[item.status] = item.count);
                setStats(s);
            }

            // All leads (simplified for now, ideally paginated)
            const leadsRes = await fetch('/api/v1/business-jobs/leads/all'); // Assuming a global getter or we fetch by last job
            // For now, let's just show leads from the most recent jobs
            const jobsRes = await fetch('/api/v1/business-jobs?limit=5');
            const jobsData = await jobsRes.json();

            if (jobsData.success && jobsData.jobs.length > 0) {
                const allLeads: any[] = [];
                for (const job of jobsData.jobs) {
                    const lr = await fetch(`/api/v1/business-jobs/leads/${job.id}`);
                    const ld = await lr.json();
                    if (ld.success) allLeads.push(...ld.leads);
                }
                setLeads(allLeads);
            }
        } catch (err) {
            console.error("Error fetching pipeline:", err);
        } finally {
            setIsLoadingLeads(false);
        }
    };

    useEffect(() => {
        fetchPipelineData();
    }, []);

    const handleUpdateStatus = async (leadId: string, newStatus: string) => {
        try {
            const res = await fetch(`/api/v1/business-jobs/leads/${leadId}/status`, {
                method: 'PATCH',
                headers: { 'Content-Type': 'application/json' },
                body: JSON.stringify({ status: newStatus })
            });
            if (res.ok) {
                toast.success(`Státusz frissítve: ${newStatus}`);
                fetchPipelineData();
            }
        } catch (err) {
            toast.error("Hiba a frissítés során.");
        }
    };

    const groupedLeads = useMemo(() => {
        const groups: any = {};
        STAGES.forEach(s => groups[s.id] = leads.filter(l => l.status === s.id));
        return groups;
    }, [leads]);

    return (
        <Card className="w-full shadow-2xl border-primary/20 bg-card/50 backdrop-blur-md overflow-hidden">
            <CardHeader className="pb-3 border-b border-white/[0.04] bg-secondary/10">
                <div className="flex justify-between items-center">
                    <div className="flex items-center gap-3">
                        <div className="p-2 bg-primary/10 rounded-full">
                            <Trello className="w-5 h-5 text-primary" />
                        </div>
                        <div>
                            <CardTitle>Sales Pipeline</CardTitle>
                            <CardDescription>Aktív üzleti folyamatok és tölcsér követés</CardDescription>
                        </div>
                    </div>
                    <Button variant="outline" size="sm" onClick={fetchPipelineData} disabled={isLoadingLeads}>
                        {isLoadingLeads ? <Loader2 className="w-4 h-4 animate-spin" /> : <BarChart3 className="w-4 h-4" />}
                    </Button>
                </div>
            </CardHeader>
            <CardContent className="p-0">
                <div className="flex overflow-x-auto no-scrollbar p-4 gap-4 min-h-[600px] bg-white/[0.02]">
                    {STAGES.map((stage) => (
                        <div key={stage.id} className="min-w-[280px] flex flex-col gap-4">
                            <div className="flex items-center justify-between px-2">
                                <div className="flex items-center gap-2">
                                    <div className={`w-2 h-2 rounded-full ${stage.color}`} />
                                    <span className="text-[10px] font-black uppercase tracking-widest text-zinc-400">{stage.label}</span>
                                </div>
                                <Badge variant="secondary" className="text-[10px] bg-white/[0.04]">{groupedLeads[stage.id]?.length || 0}</Badge>
                            </div>

                            <ScrollArea className="flex-1">
                                <div className="space-y-3 pb-4">
                                    {groupedLeads[stage.id]?.map((lead: any) => (
                                        <div key={lead.id} className="p-4 rounded-xl border border-white/[0.04] bg-secondary/5 hover:border-primary/30 transition-all group relative">
                                            <div className="flex justify-between items-start mb-2">
                                                <div className="flex-1 min-w-0">
                                                    <h4 className="font-bold text-xs text-white truncate">{lead.company_name}</h4>
                                                    <p className="text-[9px] text-zinc-500 mt-0.5">{lead.contact_person}</p>
                                                </div>
                                                <div className="opacity-0 group-hover:opacity-100 transition-opacity">
                                                    <SelectStatus currentStatus={lead.status} onUpdate={(s) => handleUpdateStatus(lead.id, s)} />
                                                </div>
                                            </div>

                                            {lead.last_interaction_at && (
                                                <div className="flex items-center gap-1.5 text-[9px] text-zinc-600 font-mono uppercase mt-2">
                                                    <Zap size={10} className="text-yellow-500" />
                                                    {format(new Date(lead.last_interaction_at), 'MMM d. HH:mm')}
                                                </div>
                                            )}

                                            <div className="mt-4 flex gap-2">
                                                <Button size="xs" variant="ghost" className="h-6 text-[9px] flex-1 bg-white/[0.04]">Adatlap</Button>
                                                {stage.id === 'outreach' && (
                                                    <Button size="xs" className="h-6 text-[9px] flex-1 bg-primary/20 text-primary">Email küldve?</Button>
                                                )}
                                            </div>
                                        </div>
                                    ))}
                                    {groupedLeads[stage.id]?.length === 0 && (
                                        <div className="py-10 border-2 border-dashed border-white/[0.04] rounded-xl flex flex-col items-center justify-center opacity-20">
                                            <Filter size={24} />
                                        </div>
                                    )}
                                </div>
                            </ScrollArea>
                        </div>
                    ))}
                </div>
            </CardContent>
        </Card>
    );
}

function SelectStatus({ currentStatus, onUpdate }: { currentStatus: string, onUpdate: (s: string) => void }) {
    return (
        <div className="relative inline-block text-left">
            <select
                className="text-[10px] bg-white/[0.03] border border-white/10 rounded px-1 py-0.5 outline-none appearance-none cursor-pointer pr-4"
                value={currentStatus}
                onChange={(e) => onUpdate(e.target.value)}
            >
                {STAGES.map(s => (
                    <option key={s.id} value={s.id}>{s.id.toUpperCase()}</option>
                ))}
            </select>
            <ChevronDown className="absolute right-1 top-1.5 w-2 h-2 text-zinc-500 pointer-events-none" />
        </div>
    );
}

import { useState, useEffect } from "react";
import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { toast } from "sonner";
import {
  CalendarClock,
  Plus,
  Trash,
  Play,
  RefreshCw,
  Clock,
} from "lucide-react";

interface ScheduledTask {
  id: string;
  title: string;
  prompt: string;
  cron_expression: string;
  handler: string;
  enabled: boolean;
  last_run_at?: string;
  last_status?: string;
  next_run_at?: string;
}

export function ScheduledTasksPanel() {
  const [tasks, setTasks] = useState<ScheduledTask[]>([]);
  const [loading, setLoading] = useState(false);
  const [isDialogOpen, setIsDialogOpen] = useState(false);

  // New task form state
  const [newTask, setNewTask] = useState({
    title: "",
    cron_expression: "0 9 * * *",
    prompt: "",
    handler: "agent",
  });

  const fetchTasks = async () => {
    try {
      setLoading(true);
      const res = await fetch("/api/v1/scheduled-tasks");
      if (!res.ok) throw new Error("Hiba a feladatok betöltésekor");
      const data = await res.json();
      setTasks(data.data || []);
    } catch (err: any) {
      toast.error(err.message || "Hiba a feladatok betöltésekor");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchTasks();
    const interval = setInterval(fetchTasks, 30000);
    return () => clearInterval(interval);
  }, []);

  const handleCreate = async () => {
    try {
      const res = await fetch("/api/v1/scheduled-tasks", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(newTask),
      });
      if (!res.ok) {
        const error = await res.json();
        throw new Error(error.error || "Sikertelen mentés");
      }
      toast.success("Feladat sikeresen ütemezve");
      setIsDialogOpen(false);
      setNewTask({ title: "", cron_expression: "0 9 * * *", prompt: "", handler: "agent" });
      fetchTasks();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  const handleDelete = async (id: string) => {
    if (!confirm("Biztosan törlöd?")) return;
    try {
      await fetch(`/api/v1/scheduled-tasks/${id}`, { method: "DELETE" });
      toast.success("Feladat törölve");
      fetchTasks();
    } catch (err) {
      toast.error("Sikertelen törlés");
    }
  };

  const handleTrigger = async (id: string) => {
    try {
      toast.info("Feladat indítása...");
      const res = await fetch(`/api/v1/scheduled-tasks/${id}/trigger`, { method: "POST" });
      if (!res.ok) throw new Error("Sikertelen indítás");
      toast.success("Feladat végrehajtva");
      fetchTasks();
    } catch (err: any) {
      toast.error(err.message);
    }
  };

  return (
    <Card className="h-full flex flex-col bg-transparent border-none shadow-none">
      <CardHeader className="flex flex-row items-center justify-between pb-3 px-4 pt-4">
        <CardTitle className="text-xs font-medium tracking-wide text-zinc-400 flex items-center gap-2">
          <CalendarClock className="h-4 w-4 text-purple-500" />
          Ütemezett MI Feladatok
        </CardTitle>
        <div className="flex gap-2">
          <Button variant="ghost" size="icon" onClick={fetchTasks} disabled={loading}>
            <RefreshCw className={`h-4 w-4 ${loading ? "animate-spin" : ""}`} />
          </Button>
          <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
            <DialogTrigger asChild>
              <Button size="sm" variant="outline" className="h-8 gap-1">
                <Plus className="h-3.5 w-3.5" />
                Új feladat
              </Button>
            </DialogTrigger>
            <DialogContent>
              <DialogHeader>
                <DialogTitle>Új feladat ütemezése</DialogTitle>
              </DialogHeader>
              <div className="grid gap-4 py-4">
                <div className="grid gap-2">
                  <Label>Megnevezés</Label>
                  <Input
                    value={newTask.title}
                    onChange={(e) => setNewTask({ ...newTask, title: e.target.value })}
                    placeholder="pl. Napi lead generálás"
                  />
                </div>
                <div className="grid gap-2">
                  <Label>Cron Kifejezés</Label>
                  <Input
                    value={newTask.cron_expression}
                    onChange={(e) => setNewTask({ ...newTask, cron_expression: e.target.value })}
                    placeholder="0 9 * * *"
                  />
                  <p className="text-xs text-zinc-500">Standard cron szintaxis (perc óra nap hó nap_hete)</p>
                </div>
                <div className="grid gap-2">
                  <Label>Prompt / Utasítás</Label>
                  <Input
                    value={newTask.prompt}
                    onChange={(e) => setNewTask({ ...newTask, prompt: e.target.value })}
                    placeholder="Mit tegyen az ügynök?"
                  />
                </div>
                <div className="grid gap-2">
                  <Label>Handler ID</Label>
                  <Input
                    value={newTask.handler}
                    onChange={(e) => setNewTask({ ...newTask, handler: e.target.value })}
                    placeholder="agent vagy scan-todos"
                  />
                </div>
                <Button onClick={handleCreate}>Ütemezés mentése</Button>
              </div>
            </DialogContent>
          </Dialog>
        </div>
      </CardHeader>
      <CardContent className="flex-1 overflow-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <TableHead>Megnevezés</TableHead>
              <TableHead>Ütemezés</TableHead>
              <TableHead>Utolsó futás</TableHead>
              <TableHead className="text-right">Műveletek</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {tasks.length === 0 ? (
              <TableRow>
                <TableCell colSpan={4} className="text-center text-zinc-500 h-24">
                  Nincs ütemezett feladat.
                </TableCell>
              </TableRow>
            ) : (
              tasks.map((task) => (
                <TableRow key={task.id}>
                  <TableCell>
                    <div className="font-medium">{task.title}</div>
                    <div className="text-xs text-zinc-500 truncate max-w-[200px]">
                      {task.prompt}
                    </div>
                  </TableCell>
                  <TableCell>
                    <Badge variant="outline" className="font-mono text-xs">
                      {task.cron_expression}
                    </Badge>
                  </TableCell>
                  <TableCell>
                    <div className="flex flex-col text-xs">
                      <span className={task.last_status === 'success' ? 'text-green-500' : task.last_status === 'failed' ? 'text-red-500' : ''}>
                        {task.last_run_at ? new Date(task.last_run_at).toLocaleString('hu-HU') : 'Soha'}
                      </span>
                      {task.next_run_at && (
                        <span className="text-zinc-500 flex items-center gap-1">
                          <Clock className="h-3 w-3" />
                          {new Date(task.next_run_at).toLocaleTimeString('hu-HU')}
                        </span>
                      )}
                    </div>
                  </TableCell>
                  <TableCell className="text-right">
                    <div className="flex justify-end gap-1">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 hover:text-blue-500"
                        onClick={() => handleTrigger(task.id)}
                        title="Futtatás most"
                      >
                        <Play className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 hover:text-destructive"
                        onClick={() => handleDelete(task.id)}
                        title="Törlés"
                      >
                        <Trash className="h-4 w-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </CardContent>
    </Card>
  );
}

/**
 * Service Control Widget - Mission Control 2.0
 * Kapcsolók: Ollama, AnythingLLM, Python Subsystem
 * Státusz: 🟢 Online / 🔴 Offline / 🟡 Starting
 */

import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Switch } from "@/components/ui/switch";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { ArrowsClockwise } from "@phosphor-icons/react";
import * as api from "@/lib/apiService";
import type { ServiceState } from "@/lib/apiService";
import { toast } from "sonner";

const SERVICE_LABELS: Record<string, string> = {
  ollama: "Ollama",
  anythingllm: "AnythingLLM",
  python: "Python Subsystem",
};

const STATUS_EMOJI: Record<string, string> = {
  online: "🟢",
  offline: "🔴",
  starting: "🟡",
  stopping: "🟡",
  unknown: "⚪",
};

export function ServiceControlWidget() {
  const [services, setServices] = useState<ServiceState[]>([]);
  const [loading, setLoading] = useState<Record<string, boolean>>({});
  const [isRefreshing, setIsRefreshing] = useState(false);

  const fetchStatus = async () => {
    setIsRefreshing(true);
    try {
      const states = await api.getServiceStatus();
      setServices(states);
    } catch (e) {
      toast.error("Státusz lekérés sikertelen");
    } finally {
      setIsRefreshing(false);
    }
  };

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 15000);
    return () => clearInterval(interval);
  }, []);

  const handleToggle = async (serviceId: string, currentlyOnline: boolean) => {
    if (loading[serviceId]) return;
    setLoading((prev) => ({ ...prev, [serviceId]: true }));

    try {
      if (currentlyOnline) {
        if (serviceId === "anythingllm") {
          toast.info("AnythingLLM Desktop app – manuálisan zárd be");
          return;
        }
        const result = await api.stopService(serviceId as "ollama" | "python");
        if (result.success) {
          toast.success(result.message);
        } else {
          toast.error(result.message);
        }
      } else {
        const result = await api.startService(
          serviceId as "ollama" | "python" | "anythingllm",
        );
        if (result.success) {
          toast.success(result.message);
        } else {
          toast.error(result.message);
        }
      }
      await fetchStatus();
    } catch (e: any) {
      toast.error(e.message || "Művelet sikertelen");
    } finally {
      setLoading((prev) => ({ ...prev, [serviceId]: false }));
    }
  };

  return (
    <Card className="bg-transparent border-none shadow-none">
      <CardHeader className="flex flex-row items-center justify-between pb-2">
        <CardTitle className="flex items-center gap-2 text-base font-medium text-zinc-200">
          Rendszervezérlő
        </CardTitle>
        <Button
          variant="ghost"
          size="sm"
          onClick={fetchStatus}
          disabled={isRefreshing}
          className="text-zinc-400 hover:text-zinc-200"
        >
          <ArrowsClockwise
            size={14}
            className={isRefreshing ? "animate-spin" : ""}
          />
        </Button>
      </CardHeader>
      <CardContent className="space-y-3">
        {services.map((svc, i) => {
          const isOnline = svc.status === "online";
          const isStarting =
            svc.status === "starting" || svc.status === "stopping";
          const canStop = svc.id !== "anythingllm" && isOnline;

          return (
            <div
              key={`${svc.id}-${i}`}
              className="flex items-center justify-between rounded-lg border border-white/[0.04]/60 bg-zinc-900/40 px-3 py-2"
            >
              <div className="flex items-center gap-2">
                <span className="text-sm">
                  {STATUS_EMOJI[svc.status] || "⚪"}
                </span>
                <span className="font-mono text-sm text-zinc-300">
                  {SERVICE_LABELS[svc.id] || svc.id}
                </span>
                {isStarting && (
                  <Badge variant="secondary" className="text-xs">
                    {svc.status === "starting" ? "Indul..." : "Leáll..."}
                  </Badge>
                )}
              </div>
              <Switch
                checked={isOnline}
                disabled={loading[svc.id] || isStarting}
                onCheckedChange={() => handleToggle(svc.id, isOnline)}
              />
            </div>
          );
        })}
        {services.length === 0 && (
          <p className="text-sm text-zinc-500">Szolgáltatások betöltése...</p>
        )}
      </CardContent>
    </Card>
  );
}

/**
 * Gold Protocol G7.1: Spec Manager Panel
 *
 * Dashboard komponens az összes track spec státuszának kezelésére.
 * RULE-UI2: Valós idejű frissítések Socket.IO-n keresztül
 */

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '../ui/card';
import { Badge } from '../ui/badge';
import { Button } from '../ui/button';
import { CheckCircle, XCircle, Clock, FileText } from '@phosphor-icons/react';

interface SpecMeta {
  id: string;
  title: string;
  status: string;
  spec_status: 'pending_approval' | 'approved' | 'rejected' | 'not_found';
  priority: string;
  created: string;
  updated: string;
  owner: string;
  progress: number;
  tags: string[];
  rejection_reason?: string;
}

export function SpecManagerPanel() {
  const [specs, setSpecs] = useState<SpecMeta[]>([]);
  const [selectedTrack, setSelectedTrack] = useState<string | null>(null);
  const [specDetails, setSpecDetails] = useState<{ specContent: string; planContent: string } | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchSpecs();
    const interval = setInterval(fetchSpecs, 10000); // Auto-refresh every 10s
    return () => clearInterval(interval);
  }, []);

  const fetchSpecs = async () => {
    try {
      const res = await fetch('/api/specs');
      const data = await res.json();
      setSpecs(data.specs || []);
      setLoading(false);
    } catch (e) {
      console.error('Failed to fetch specs:', e);
      setLoading(false);
    }
  };

  const fetchSpecDetails = async (trackId: string) => {
    try {
      const res = await fetch(`/api/specs/${trackId}`);
      const data = await res.json();
      setSpecDetails({
        specContent: data.specContent || 'No spec.md found',
        planContent: data.planContent || 'No plan.md found',
      });
      setSelectedTrack(trackId);
    } catch (e) {
      console.error('Failed to fetch spec details:', e);
    }
  };

  const handleApprove = async (trackId: string) => {
    try {
      const res = await fetch(`/api/specs/${trackId}/approve`, { method: 'POST' });
      const data = await res.json();
      if (data.success) {
        fetchSpecs(); // Refresh list
        alert(`✅ Spec approved: ${trackId}`);
      } else {
        alert(`❌ Failed to approve: ${data.message}`);
      }
    } catch (e) {
      alert('Failed to approve spec');
    }
  };

  const handleReject = async (trackId: string) => {
    const reason = prompt('Rejection reason (optional):');
    try {
      const res = await fetch(`/api/specs/${trackId}/reject`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason }),
      });
      const data = await res.json();
      if (data.success) {
        fetchSpecs();
        alert(`❌ Spec rejected: ${trackId}`);
      } else {
        alert(`Failed to reject: ${data.message}`);
      }
    } catch (e) {
      alert('Failed to reject spec');
    }
  };

  const getStatusBadge = (status: string) => {
    switch (status) {
      case 'approved':
        return <Badge className="bg-green-500 text-white"><CheckCircle className="w-3 h-3 mr-1" />Approved</Badge>;
      case 'rejected':
        return <Badge className="bg-red-500 text-white"><XCircle className="w-3 h-3 mr-1" />Rejected</Badge>;
      case 'pending_approval':
        return <Badge className="bg-yellow-500 text-white"><Clock className="w-3 h-3 mr-1" />Pending</Badge>;
      default:
        return <Badge className="bg-gray-500 text-white">Unknown</Badge>;
    }
  };

  const getPriorityBadge = (priority: string) => {
    const colors: Record<string, string> = {
      critical: 'bg-red-600',
      high: 'bg-orange-500',
      medium: 'bg-blue-500',
      low: 'bg-gray-400',
    };
    return <Badge className={`${colors[priority.toLowerCase()] || 'bg-gray-500'} text-white`}>{priority.toUpperCase()}</Badge>;
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle>Spec Manager</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center p-8">
            <div className="text-gray-500">Loading specs...</div>
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      {/* Left Panel: Spec List */}
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <FileText className="w-5 h-5" />
            Track Specifications ({specs.length})
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="space-y-2 max-h-[600px] overflow-y-auto">
            {specs.map((spec) => (
              <div
                key={spec.id}
                className={`p-3 border rounded-lg cursor-pointer transition-colors hover:bg-gray-100 dark:hover:bg-gray-800 ${
                  selectedTrack === spec.id ? 'border-blue-500 bg-blue-50 dark:bg-blue-900/20' : 'border-gray-300'
                }`}
                onClick={() => fetchSpecDetails(spec.id)}
              >
                <div className="flex items-start justify-between mb-2">
                  <div className="flex-1">
                    <h3 className="font-semibold text-sm">{spec.title}</h3>
                    <p className="text-xs text-gray-500">ID: {spec.id}</p>
                  </div>
                  {getStatusBadge(spec.spec_status)}
                </div>
                <div className="flex items-center gap-2 text-xs">
                  {getPriorityBadge(spec.priority)}
                  <Badge className="bg-gray-200 text-gray-700">Progress: {spec.progress}%</Badge>
                  <span className="text-gray-500">Updated: {spec.updated}</span>
                </div>
                {spec.rejection_reason && (
                  <div className="mt-2 text-xs text-red-600 bg-red-50 p-2 rounded">
                    Reason: {spec.rejection_reason}
                  </div>
                )}
                {spec.spec_status === 'pending_approval' && (
                  <div className="flex gap-2 mt-2">
                    <Button size="sm" variant="default" onClick={(e) => { e.stopPropagation(); handleApprove(spec.id); }}>
                      Approve
                    </Button>
                    <Button size="sm" variant="destructive" onClick={(e) => { e.stopPropagation(); handleReject(spec.id); }}>
                      Reject
                    </Button>
                  </div>
                )}
              </div>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* Right Panel: Spec Details */}
      <Card>
        <CardHeader>
          <CardTitle>Spec Details</CardTitle>
        </CardHeader>
        <CardContent>
          {selectedTrack && specDetails ? (
            <div className="space-y-4">
              <div>
                <h3 className="font-semibold mb-2">Specification (spec.md)</h3>
                <div className="bg-gray-50 dark:bg-gray-900 p-3 rounded-lg text-xs max-h-[250px] overflow-y-auto font-mono whitespace-pre-wrap">
                  {specDetails.specContent}
                </div>
              </div>
              <div>
                <h3 className="font-semibold mb-2">Implementation Plan (plan.md)</h3>
                <div className="bg-gray-50 dark:bg-gray-900 p-3 rounded-lg text-xs max-h-[250px] overflow-y-auto font-mono whitespace-pre-wrap">
                  {specDetails.planContent}
                </div>
              </div>
            </div>
          ) : (
            <div className="text-gray-500 text-center p-8">
              Select a track to view spec details
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * SwarmPanel — Dashboard component for Swarm monitoring
 * Track #5: Swarm Intelligence v2 — Phase 4
 */
import React, { useState, useEffect } from 'react';
import { Users, Activity, Vote, AlertCircle, Play, Square, RefreshCw } from 'lucide-react';

interface ColonySummary {
  swarmId: string;
  name: string;
  status: string;
  agentCount: number;
  leaderId: string | null;
  tasksCompleted: number;
  tasksFailed: number;
  avgDurationMs: number;
}

interface CheckpointInfo {
  totalCheckpoints: number;
  colonies: number;
  latestAt: string | null;
}

export default function SwarmPanel() {
  const [colonies, setColonies] = useState<ColonySummary[]>([]);
  const [checkpoints, setCheckpoints] = useState<CheckpointInfo | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  async function fetchData() {
    setLoading(true);
    try {
      const [colRes, cpRes] = await Promise.all([
        fetch('/api/v1/swarm/status'),
        fetch('/api/v1/swarm/checkpoints/stats'),
      ]);
      if (colRes.ok) setColonies(await colRes.json());
      if (cpRes.ok) setCheckpoints(await cpRes.json());
      setError(null);
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Fetch failed');
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { void fetchData(); }, []);

  const statusColor = (status: string) => {
    switch (status) {
      case 'active': return 'text-green-400';
      case 'forming': return 'text-yellow-400';
      case 'paused': return 'text-orange-400';
      case 'degraded': return 'text-red-400';
      default: return 'text-gray-400';
    }
  };

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold flex items-center gap-2">
          <Users className="w-5 h-5" /> Swarm Intelligence v2
        </h2>
        <button onClick={() => void fetchData()} className="p-2 rounded hover:bg-gray-700" title="Frissítés">
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {error && (
        <div className="bg-red-900/30 border border-red-700 rounded p-3 flex items-center gap-2">
          <AlertCircle className="w-4 h-4 text-red-400" /> <span className="text-red-300">{error}</span>
        </div>
      )}

      {/* Colony Cards */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {colonies.map(colony => (
          <div key={colony.swarmId} className="bg-gray-800 rounded-lg p-4 border border-gray-700">
            <div className="flex items-center justify-between mb-2">
              <h3 className="font-semibold">{colony.name}</h3>
              <span className={`text-sm font-mono ${statusColor(colony.status)}`}>{colony.status}</span>
            </div>
            <div className="grid grid-cols-2 gap-2 text-sm text-gray-400">
              <div className="flex items-center gap-1">
                <Users className="w-3 h-3" /> {colony.agentCount} agent
              </div>
              <div className="flex items-center gap-1">
                <Activity className="w-3 h-3" /> {colony.tasksCompleted}✓ / {colony.tasksFailed}✗
              </div>
              <div>Leader: {colony.leaderId ?? '—'}</div>
              <div>Avg: {colony.avgDurationMs.toFixed(0)}ms</div>
            </div>
          </div>
        ))}
        {colonies.length === 0 && !loading && (
          <div className="col-span-2 text-center text-gray-500 py-8">Nincs aktív colony</div>
        )}
      </div>

      {/* Checkpoint Stats */}
      {checkpoints && (
        <div className="bg-gray-800 rounded-lg p-4 border border-gray-700">
          <h3 className="font-semibold mb-2 flex items-center gap-2">
            <Vote className="w-4 h-4" /> Checkpoint Statisztikák
          </h3>
          <div className="grid grid-cols-3 gap-4 text-sm">
            <div>
              <div className="text-gray-400">Összes checkpoint</div>
              <div className="text-lg font-mono">{checkpoints.totalCheckpoints}</div>
            </div>
            <div>
              <div className="text-gray-400">Colony-k</div>
              <div className="text-lg font-mono">{checkpoints.colonies}</div>
            </div>
            <div>
              <div className="text-gray-400">Legutóbbi</div>
              <div className="text-sm font-mono">{checkpoints.latestAt ?? '—'}</div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

