import { useEffect, useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { Switch } from "@/components/ui/switch";
import {
  Circle,
  CheckCircle,
  Warning,
  XCircle,
  ArrowsClockwise,
} from "@phosphor-icons/react";
import * as api from "@/lib/apiService";
import { toast } from "sonner";

interface ServiceStatus {
  id: string;
  name: string;
  status: "healthy" | "unhealthy" | "checking" | "starting" | "stopping";
  message?: string;
}

export function SystemHealthCard() {
  const [services, setServices] = useState<ServiceStatus[]>([
    { id: "ollama", name: "Ollama", status: "checking" },
    { id: "anythingllm", name: "AnythingLLM", status: "checking" },
    { id: "agents", name: "Agents", status: "checking" },
    { id: "mcp", name: "MCP Servers", status: "checking" },
    { id: "python", name: "Python Service", status: "checking" },
    { id: "cloudflare", name: "Cloudflare", status: "checking" },
  ]);
  const [lastCheck, setLastCheck] = useState<string>("");
  const [isChecking, setIsChecking] = useState(false);
  const [loading, setLoading] = useState<Record<string, boolean>>({});

  const checkHealth = async () => {
    setIsChecking(true);
    try {
      const health = await api.checkHealth();
      const so = (s: { status?: string } | string) =>
        (typeof s === "object" ? s.status : s) ?? "unhealthy";
      const ok = (s: { status?: string } | string) => so(s) === "healthy";

      const newServices: ServiceStatus[] = [
        {
          id: "ollama",
          name: "Ollama",
          status: ok(health.services.ollama) ? "healthy" : "unhealthy",
          message: ok(health.services.ollama)
            ? "Működik"
            : "Indítsd el: ollama serve",
        },
        {
          id: "anythingllm",
          name: "AnythingLLM",
          status: ok(health.services.anythingllm) ? "healthy" : "unhealthy",
          message: ok(health.services.anythingllm)
            ? "Működik"
            : "Service nem elérhető",
        },
        {
          id: "agents",
          name: "Agents",
          status: ok(health.services.agents) ? "healthy" : "unhealthy",
          message: ok(health.services.agents)
            ? "Aktív ágensek rendelkezésre állnak"
            : "Nincs regisztrált ágens",
        },
        {
          id: "mcp",
          name: "MCP Servers",
          status: ok(health.services.mcp) ? "healthy" : "unhealthy",
          message: ok(health.services.mcp)
            ? "MCP kapcsolat működik"
            : "Nincs elérhető MCP szerver",
        },
        {
          id: "python",
          name: "Python Service",
          status: ok(health.services.python) ? "healthy" : "unhealthy",
          message: ok(health.services.python)
            ? "Python alrendszer OK"
            : "Python server nem fut",
        },
        {
          id: "cloudflare",
          name: "Cloudflare",
          status: ok(health.services.cloudflare) ? "healthy" : "unhealthy",
          message: ok(health.services.cloudflare)
            ? "Gateway & R2 OK"
            : "CS csatlakozási hiba",
        },
      ];

      setServices(newServices);
      setLastCheck(new Date().toLocaleString("hu-HU"));
    } catch (error: any) {
      console.error("Health check error:", error);
      setServices((prev) =>
        prev.map((s) => ({
          ...s,
          status: "unhealthy",
          message: "Szerver nem elérhető",
        })),
      );
    } finally {
      setIsChecking(false);
    }
  };

  const handleToggle = async (serviceId: string, currentlyHealthy: boolean) => {
    if (serviceId === "agents" || serviceId === "mcp") {
      toast.info(`${serviceId} állapotát a rendszer automatikusan kezeli`);
      return;
    }

    setLoading((prev) => ({ ...prev, [serviceId]: true }));
    try {
      if (currentlyHealthy) {
        if (serviceId === "anythingllm") {
          toast.info("AnythingLLM Desktop app – manuálisan zárd be");
          return;
        }
        const result = await api.stopService(serviceId as any);
        if (result.success) toast.success(result.message);
        else toast.error(result.message);
      } else {
        const result = await api.startService(serviceId as any);
        if (result.success) toast.success(result.message);
        else toast.error(result.message);
      }
      await checkHealth();
    } catch (e: any) {
      toast.error(e.message || "Művelet sikertelen");
    } finally {
      setLoading((prev) => ({ ...prev, [serviceId]: false }));
    }
  };

  useEffect(() => {
    checkHealth();
    const interval = setInterval(checkHealth, 30000); // 30s as per masterplan V3
    return () => clearInterval(interval);
  }, []);

  const getStatusIcon = (status: string) => {
    switch (status) {
      case "healthy":
        return (
          <CheckCircle size={20} className="text-green-500" weight="fill" />
        );
      case "unhealthy":
        return <XCircle size={14} className="text-red-500" weight="fill" />;
      case "checking":
        return (
          <Circle
            size={14}
            className="text-yellow-500 animate-pulse"
            weight="fill"
          />
        );
      default:
        return <Warning size={14} className="text-gray-500" />;
    }
  };

  const healthyCount = services.filter((s) => s.status === "healthy").length;
  const totalCount = services.length;

  return (
    <Card className="bg-transparent border-none shadow-none">
      <CardHeader className="flex flex-row items-center justify-between pb-3 px-4 pt-4">
        <CardTitle className="text-xs font-medium tracking-wide text-zinc-400 flex items-center gap-2">
          <ArrowsClockwise
            size={14}
            className={isChecking ? "animate-spin text-primary" : "text-zinc-500"}
          />
          System Health
        </CardTitle>
        <Badge
          variant={healthyCount === totalCount ? "default" : "destructive"}
          className="text-[10px] font-mono px-1.5 py-0"
        >
          {healthyCount}/{totalCount}
        </Badge>
      </CardHeader>
      <CardContent className="p-0">
        <div className="divide-y divide-white/[0.04]">
          {services.map((service) => {
            const isHealthy = service.status === "healthy";
            const canToggle =
              service.id === "ollama" ||
              service.id === "anythingllm" ||
              service.id === "python";

            return (
              <div
                key={service.id}
                className="flex items-center justify-between px-4 py-2.5 hover:bg-white/[0.03] transition-colors"
              >
                <div className="flex items-center gap-2.5">
                  {getStatusIcon(service.status)}
                  <div className="min-w-0">
                    <p className="font-medium text-xs text-zinc-200">
                      {service.name}
                    </p>
                    <p className="text-[10px] text-zinc-500 truncate max-w-[140px]">
                      {service.message || "System online"}
                    </p>
                  </div>
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  {canToggle && (
                    <Switch
                      checked={isHealthy}
                      disabled={loading[service.id] || isChecking}
                      onCheckedChange={() =>
                        handleToggle(service.id, isHealthy)
                      }
                      className="scale-75"
                    />
                  )}
                  {!canToggle && (
                    <Badge
                      variant="outline"
                      className="text-[9px] h-5 opacity-40 border-zinc-700"
                    >
                      AUTO
                    </Badge>
                  )}
                </div>
              </div>
            );
          })}
        </div>

        <div className="px-4 py-2 border-t border-white/[0.04]">
          <p className="text-[9px] text-zinc-600 font-mono text-center">
            {lastCheck || "Initializing..."}
          </p>
        </div>
      </CardContent>
    </Card>
  );
}

import { useState, useEffect } from "react";
import {
  BarChart,
  Bar,
  LineChart,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
  ResponsiveContainer,
  ComposedChart,
} from "recharts";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Skeleton } from "@/components/ui/skeleton";
import { toast } from "sonner";
import { Play, RefreshCw, Clock, Zap, CheckCircle, XCircle } from "lucide-react";

interface TestStats {
  totalRuns: number;
  passRate: string;
  averageDuration: string;
  lastRunStatus: string;
  lastRunTime: string;
  sevenDayPassRate: string;
}

interface TestRun {
  id: string;
  status: "passed" | "failed" | "running";
  duration: string;
  passed: number;
  failed: number;
  startedAt: string;
}

interface ChartData {
  date: string;
  passRate: number;
  passed: number;
  failed: number;
}

export function TestResultsWidget() {
  const [stats, setStats] = useState<TestStats | null>(null);
  const [recentRuns, setRecentRuns] = useState<TestRun[]>([]);
  const [chartData, setChartData] = useState<ChartData[]>([]);
  const [loading, setLoading] = useState(true);
  const [triggering, setTriggering] = useState(false);
  const [autoRefresh, setAutoRefresh] = useState(true);

  // Fetch stats
  const fetchStats = async () => {
    try {
      setLoading(true);
      const response = await fetch("/api/tests/stats");
      if (!response.ok) throw new Error("Failed to fetch stats");
      
      const data = await response.json() as TestStats;
      setStats(data);

      // Parse pass rate percentage
      const passRateNum = parseFloat(data.passRate);
      setChartData([
        {
          date: "7d Trend",
          passRate: passRateNum,
          passed: 0,
          failed: 0,
        },
      ]);
    } catch (error) {
      toast.error("Failed to load test statistics");
    } finally {
      setLoading(false);
    }
  };

  // Fetch recent runs
  const fetchRecentRuns = async () => {
    try {
      const response = await fetch("/api/tests/results?limit=10");
      if (!response.ok) throw new Error("Failed to fetch runs");
      
      const data = await response.json();
      setRecentRuns(data.runs || []);
    } catch (error) {
      toast.error("Failed to load recent test runs");
    }
  };

  // Trigger manual run
  const handleTriggerRun = async () => {
    try {
      setTriggering(true);
      const response = await fetch("/api/tests/run", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ triggerReason: "Manual trigger from dashboard" }),
      });

      if (!response.ok) throw new Error("Failed to trigger test run");

      const data = await response.json();
      toast.success(`Test run triggered: ${data.runId}`);
      
      // Refresh data after a short delay
      setTimeout(() => {
        fetchStats();
        fetchRecentRuns();
      }, 1000);
    } catch (error) {
      toast.error("Failed to trigger test run");
    } finally {
      setTriggering(false);
    }
  };

  // Initial load
  useEffect(() => {
    fetchStats();
    fetchRecentRuns();
  }, []);

  // Auto-refresh
  useEffect(() => {
    if (!autoRefresh) return;

    const interval = setInterval(() => {
      fetchStats();
      fetchRecentRuns();
    }, 5 * 60 * 1000); // 5 minutes

    return () => clearInterval(interval);
  }, [autoRefresh]);

  if (loading) {
    return (
      <div className="space-y-4">
        <Skeleton className="h-64 w-full" />
        <Skeleton className="h-32 w-full" />
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Header with Actions */}
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold">Teszt Ütemezés (Test Scheduler)</h2>
        <div className="flex gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => {
              fetchStats();
              fetchRecentRuns();
            }}
            disabled={loading}
            aria-label="Tesztek frissítése"
            title="Tesztek frissítése"
          >
            <RefreshCw className={`h-4 w-4 mr-2 ${loading ? "animate-spin" : ""}`} />
            Frissítés
          </Button>
          <Button
            onClick={handleTriggerRun}
            disabled={triggering}
            className="bg-blue-600 hover:bg-blue-700"
            aria-label="Tesztek futtatása"
            title="Tesztek futtatása"
          >
            <Play className={`h-4 w-4 mr-2 ${triggering ? "animate-pulse" : ""}`} />
            {triggering ? "Futtatás..." : "Tesztek Futtatása"}
          </Button>
        </div>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-gray-600">
                Összes Futás
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-3xl font-bold">{stats.totalRuns}</div>
              <p className="text-xs text-gray-500 mt-1">lifetime</p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-gray-600">
                Pass Rate (7d)
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-3xl font-bold text-green-600">
                {stats.sevenDayPassRate}
              </div>
              <p className="text-xs text-gray-500 mt-1">most recent</p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-gray-600">
                Átlagos Futási Idő
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold flex items-center gap-2">
                <Clock className="h-5 w-5 text-orange-500" />
                {stats.averageDuration}
              </div>
              <p className="text-xs text-gray-500 mt-1">avg duration</p>
            </CardContent>
          </Card>

          <Card>
            <CardHeader className="pb-2">
              <CardTitle className="text-sm font-medium text-gray-600">
                Utolsó Futás
              </CardTitle>
            </CardHeader>
            <CardContent>
              <div className="text-2xl font-bold flex items-center gap-2">
                {stats.lastRunStatus === "passed" ? (
                  <CheckCircle className="h-5 w-5 text-green-500" />
                ) : (
                  <XCircle className="h-5 w-5 text-red-500" />
                )}
                <span className="capitalize">{stats.lastRunStatus}</span>
              </div>
              <p className="text-xs text-gray-500 mt-1">{stats.lastRunTime}</p>
            </CardContent>
          </Card>
        </div>
      )}

      {/* Chart */}
      <Card>
        <CardHeader>
          <CardTitle>Pass Rate Trend (7 nap)</CardTitle>
        </CardHeader>
        <CardContent>
          <ResponsiveContainer width="100%" height={300}>
            <ComposedChart data={chartData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis yAxisId="left" label={{ value: "Pass Rate (%)", angle: -90, position: "insideLeft" }} />
              <YAxis yAxisId="right" orientation="right" label={{ value: "Test Count", angle: 90, position: "insideRight" }} />
              <Tooltip />
              <Legend />
              <Line
                yAxisId="left"
                type="monotone"
                dataKey="passRate"
                stroke="#10b981"
                strokeWidth={2}
                name="Sikeres arány (%)"
              />
              <Bar yAxisId="right" dataKey="passed" fill="#3b82f6" name="Sikeres" />
              <Bar yAxisId="right" dataKey="failed" fill="#ef4444" name="Sikertelen" />
            </ComposedChart>
          </ResponsiveContainer>
        </CardContent>
      </Card>

      {/* Recent Runs Table */}
      <Card>
        <CardHeader>
          <CardTitle>Utolsó 10 Futás</CardTitle>
        </CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead className="border-b">
                <tr>
                  <th className="text-left py-2 px-4 font-medium">Státusz</th>
                  <th className="text-left py-2 px-4 font-medium">Sikeres</th>
                  <th className="text-left py-2 px-4 font-medium">Sikertelen</th>
                  <th className="text-left py-2 px-4 font-medium">Futási Idő</th>
                  <th className="text-left py-2 px-4 font-medium">Időpont</th>
                </tr>
              </thead>
              <tbody>
                {recentRuns.length === 0 ? (
                  <tr>
                    <td colSpan={5} className="text-center py-4 text-gray-500">
                      Nincs korábbi futás
                    </td>
                  </tr>
                ) : (
                  recentRuns.map((run) => (
                    <tr key={run.id} className="border-b hover:bg-gray-50">
                      <td className="py-2 px-4">
                        <span
                          className={`px-2 py-1 rounded text-xs font-medium ${
                            run.status === "passed"
                              ? "bg-green-100 text-green-800"
                              : run.status === "failed"
                                ? "bg-red-100 text-red-800"
                                : "bg-yellow-100 text-yellow-800"
                          }`}
                        >
                          {run.status}
                        </span>
                      </td>
                      <td className="py-2 px-4">
                        <span className="text-green-600 font-medium">
                          {run.passed}
                        </span>
                      </td>
                      <td className="py-2 px-4">
                        <span className="text-red-600 font-medium">
                          {run.failed}
                        </span>
                      </td>
                      <td className="py-2 px-4">{run.duration}</td>
                      <td className="py-2 px-4 text-gray-500 text-xs">
                        {new Date(run.startedAt).toLocaleString("hu-HU")}
                      </td>
                    </tr>
                  ))
                )}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      {/* Auto-refresh Toggle */}
      <div className="flex items-center gap-2 text-sm">
        <input
          type="checkbox"
          id="auto-refresh"
          checked={autoRefresh}
          onChange={(e) => setAutoRefresh(e.target.checked)}
          className="rounded"
        />
        <label htmlFor="auto-refresh">
          Auto-frissítés 5 percenként
        </label>
      </div>
    </div>
  );
}

/**
 * ToolDiscoveryPanel — Dashboard component for MCP tool registry
 * Track #6: MCP Tool Discovery — Phase 4
 */
import React, { useState, useEffect } from 'react';
import { Wrench, Search, TrendingUp, AlertTriangle, RefreshCw, ChevronDown, ChevronRight } from 'lucide-react';

interface ToolInfo {
  id: string;
  name: string;
  version: string;
  description: string;
  publishedBy: string;
  tags: string[];
  deprecated: boolean;
  totalCalls: number;
  errorRate: number;
  avgLatencyMs: number;
}

interface RegistryStats {
  totalTools: number;
  deprecatedTools: number;
  totalCalls: number;
  avgLatencyMs: number;
  publishers: string[];
}

export default function ToolDiscoveryPanel() {
  const [tools, setTools] = useState<ToolInfo[]>([]);
  const [stats, setStats] = useState<RegistryStats | null>(null);
  const [filter, setFilter] = useState('');
  const [loading, setLoading] = useState(true);
  const [expandedTool, setExpandedTool] = useState<string | null>(null);

  async function fetchData() {
    setLoading(true);
    try {
      const [toolsRes, statsRes] = await Promise.all([
        fetch('/api/v1/tools/registry'),
        fetch('/api/v1/tools/stats'),
      ]);
      if (toolsRes.ok) setTools(await toolsRes.json());
      if (statsRes.ok) setStats(await statsRes.json());
    } catch {
      // silent
    } finally {
      setLoading(false);
    }
  }

  useEffect(() => { void fetchData(); }, []);

  const filtered = tools.filter(t =>
    t.name.toLowerCase().includes(filter.toLowerCase()) ||
    t.tags.some(tag => tag.toLowerCase().includes(filter.toLowerCase())) ||
    t.publishedBy.toLowerCase().includes(filter.toLowerCase())
  );

  return (
    <div className="p-6 space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-xl font-bold flex items-center gap-2">
          <Wrench className="w-5 h-5" /> MCP Tool Discovery
        </h2>
        <button onClick={() => void fetchData()} className="p-2 rounded hover:bg-gray-700" title="Frissítés">
          <RefreshCw className={`w-4 h-4 ${loading ? 'animate-spin' : ''}`} />
        </button>
      </div>

      {/* Stats Cards */}
      {stats && (
        <div className="grid grid-cols-4 gap-4">
          <div className="bg-gray-800 rounded-lg p-3 border border-gray-700 text-center">
            <div className="text-2xl font-mono font-bold">{stats.totalTools}</div>
            <div className="text-xs text-gray-400">Tool-ok</div>
          </div>
          <div className="bg-gray-800 rounded-lg p-3 border border-gray-700 text-center">
            <div className="text-2xl font-mono font-bold">{stats.totalCalls}</div>
            <div className="text-xs text-gray-400">Összes hívás</div>
          </div>
          <div className="bg-gray-800 rounded-lg p-3 border border-gray-700 text-center">
            <div className="text-2xl font-mono font-bold">{stats.avgLatencyMs.toFixed(0)}ms</div>
            <div className="text-xs text-gray-400">Átlag latency</div>
          </div>
          <div className="bg-gray-800 rounded-lg p-3 border border-gray-700 text-center">
            <div className="text-2xl font-mono font-bold text-yellow-400">{stats.deprecatedTools}</div>
            <div className="text-xs text-gray-400">Deprecated</div>
          </div>
        </div>
      )}

      {/* Search */}
      <div className="relative">
        <Search className="absolute left-3 top-2.5 w-4 h-4 text-gray-500" />
        <input
          type="text"
          placeholder="Keresés név, tag vagy publisher alapján..."
          value={filter}
          onChange={e => setFilter(e.target.value)}
          className="w-full bg-gray-800 border border-gray-700 rounded pl-10 pr-4 py-2 text-sm"
        />
      </div>

      {/* Tool List */}
      <div className="space-y-2">
        {filtered.map(tool => (
          <div key={tool.id} className="bg-gray-800 rounded-lg border border-gray-700">
            <div
              className="flex items-center justify-between p-3 cursor-pointer hover:bg-gray-750"
              onClick={() => setExpandedTool(expandedTool === tool.id ? null : tool.id)}
            >
              <div className="flex items-center gap-3">
                {expandedTool === tool.id ? <ChevronDown className="w-4 h-4" /> : <ChevronRight className="w-4 h-4" />}
                <span className="font-mono text-sm">{tool.name}</span>
                <span className="text-xs text-gray-500">v{tool.version}</span>
                {tool.deprecated && (
                  <span className="text-xs bg-yellow-900/50 text-yellow-400 px-1.5 py-0.5 rounded">deprecated</span>
                )}
              </div>
              <div className="flex items-center gap-4 text-xs text-gray-400">
                <span>{tool.totalCalls} hívás</span>
                <span>{tool.avgLatencyMs.toFixed(0)}ms</span>
                {tool.errorRate > 0.1 && (
                  <span className="text-red-400 flex items-center gap-1">
                    <AlertTriangle className="w-3 h-3" /> {(tool.errorRate * 100).toFixed(0)}%
                  </span>
                )}
              </div>
            </div>
            {expandedTool === tool.id && (
              <div className="border-t border-gray-700 p-3 text-sm text-gray-300 space-y-2">
                <div>{tool.description}</div>
                <div className="flex gap-2">
                  {tool.tags.map(tag => (
                    <span key={tag} className="text-xs bg-blue-900/40 text-blue-300 px-2 py-0.5 rounded">{tag}</span>
                  ))}
                </div>
                <div className="text-xs text-gray-500">Publisher: {tool.publishedBy}</div>
              </div>
            )}
          </div>
        ))}
        {filtered.length === 0 && !loading && (
          <div className="text-center text-gray-500 py-8">Nincs tool az aktuális szűrőhöz</div>
        )}
      </div>
    </div>
  );
}

import { useMemo, useState } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Switch } from "@/components/ui/switch";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import {
  Select,
  SelectTrigger,
  SelectContent,
  SelectItem,
  SelectValue,
} from "@/components/ui/select";
import { useMcpStore } from "@/lib/mcpStore";
import { useMCP } from "@/hooks/useMCP";
import { AgentTool } from "@/lib/types";
import { FunnelSimple, MagnifyingGlass, Play } from "@phosphor-icons/react";
import { toast } from "sonner";

export function ToolsCard() {
  const { agentTools } = useMcpStore();
  const { runTool } = useMCP();

  const [query, setQuery] = useState("");
  const [category, setCategory] = useState<string>("all");
  const [onlyNoParams, setOnlyNoParams] = useState(false);
  const [activeTool, setActiveTool] = useState<AgentTool | null>(null);
  const [formValue, setFormValue] = useState<Record<string, string>>({});
  const [quickFilter, setQuickFilter] = useState<string | null>(null);

  const categories = useMemo(() => {
    const set = new Set<string>();
    agentTools.forEach((t) => t.category && set.add(t.category));
    return Array.from(set);
  }, [agentTools]);

  const filtered = useMemo(() => {
    const priority = (t: AgentTool) => {
      const label = t.category?.toLowerCase() ?? "";
      const name = t.name.toLowerCase();
      if (label.includes("github") || name.includes("github")) return 0;
      if (label.includes("a2a") || name.includes("a2a")) return 1;
      if (
        label.includes("adk") ||
        name.includes("adk") ||
        name.includes("copilot")
      )
        return 2;
      if (label.includes("mcp")) return 3;
      if (label.includes("native")) return 4;
      return 5;
    };

    return agentTools
      .filter((tool) => {
        if (category !== "all" && tool.category !== category) return false;
        if (onlyNoParams && tool.parameters && tool.parameters.length > 0)
          return false;
        if (quickFilter) {
          const lname = tool.name.toLowerCase();
          const lcat = tool.category?.toLowerCase() ?? "";
          if (
            quickFilter === "github" &&
            !(lname.includes("github") || lcat.includes("github"))
          )
            return false;
          if (
            quickFilter === "a2a" &&
            !(lname.includes("a2a") || lcat.includes("a2a"))
          )
            return false;
          if (
            quickFilter === "adk" &&
            !(
              lname.includes("adk") ||
              lname.includes("copilot") ||
              lcat.includes("adk")
            )
          )
            return false;
          if (quickFilter === "mcp" && !lcat.includes("mcp")) return false;
          if (quickFilter === "native" && !lcat.includes("native"))
            return false;
        }
        if (!query) return true;
        const hay = `${tool.name} ${tool.description ?? ""}`.toLowerCase();
        return hay.includes(query.toLowerCase());
      })
      .sort((a, b) => priority(a) - priority(b));
  }, [agentTools, category, query, onlyNoParams]);

  const tagLabel = (tool: AgentTool) => {
    const label = tool.category?.toLowerCase() ?? "";
    const name = tool.name.toLowerCase();
    if (label.includes("a2a") || name.includes("a2a")) return "a2a";
    if (
      label.includes("adk") ||
      name.includes("adk") ||
      name.includes("copilot")
    )
      return "ADK";
    if (label.includes("github") || name.includes("github")) return "GitHub";
    if (label.includes("mcp")) return "MCP";
    if (label.includes("native")) return "native";
    return tool.category ?? "tool";
  };

  const invoke = (tool: AgentTool) => {
    if (tool.parameters && tool.parameters.length > 0) {
      const initVal: Record<string, string> = {};
      tool.parameters.forEach((p) => {
        initVal[p.name] = "";
      });
      setFormValue(initVal);
      setActiveTool(tool);
    } else {
      const id = runTool(tool.name, {});
      toast.info(`Tool elküldve: ${tool.name}`, {
        description: id ? `id=${id}` : "",
      });
    }
  };

  const submitForm = () => {
    if (!activeTool) return;
    try {
      const args: any = {};
      activeTool.parameters?.forEach((p) => {
        const raw = formValue[p.name] ?? "";
        if (p.type === "number") {
          const num = Number(raw);
          if (Number.isNaN(num)) throw new Error(`A(z) ${p.name} számot vár.`);
          args[p.name] = num;
        } else if (p.type === "boolean") {
          args[p.name] = raw === "true";
        } else {
          args[p.name] = raw;
        }
      });
      const id = runTool(activeTool.name, args);
      toast.info(`Tool elküldve: ${activeTool.name}`, {
        description: id ? `id=${id}` : "",
      });
      setActiveTool(null);
    } catch (e: any) {
      toast.error(e.message || "Hibás paraméter.");
    }
  };

  return (
    <>
      <Card className="w-full">
        <CardHeader>
          <div className="flex items-center gap-2">
            <FunnelSimple size={22} className="text-primary" />
            <div>
              <CardTitle>Tools (ADK / MCP / native)</CardTitle>
              <CardDescription>
                Elérhető eszközök listázása, gyors futtatás
              </CardDescription>
            </div>
          </div>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="flex flex-col md:flex-row gap-3">
            <div className="flex-1 relative">
              <MagnifyingGlass
                size={16}
                className="absolute left-2 top-1/2 -translate-y-1/2 text-zinc-500"
              />
              <Input
                value={query}
                onChange={(e) => setQuery(e.target.value)}
                placeholder="Keresés név vagy leírás alapján..."
                className="pl-7"
              />
            </div>
            <div className="flex items-center gap-2">
              <select
                value={category}
                onChange={(e) => setCategory(e.target.value)}
                className="border rounded-md px-2 py-1 text-sm bg-background"
              >
                <option value="all">Minden kategória</option>
                {categories.map((cat, i) => (
                  <option key={`${cat}-${i}`} value={cat}>
                    {cat}
                  </option>
                ))}
              </select>
              <div className="flex items-center gap-2 text-sm">
                <Switch
                  checked={onlyNoParams}
                  onCheckedChange={(v) => setOnlyNoParams(v)}
                  id="only-no-params"
                />
                <label htmlFor="only-no-params" className="cursor-pointer">
                  Csak paraméter nélküli
                </label>
              </div>
              <div className="flex flex-wrap gap-1 text-xs">
                {["github", "a2a", "adk", "mcp", "native"].map((tag) => (
                  <Button
                    key={tag}
                    size="sm"
                    variant={quickFilter === tag ? "default" : "outline"}
                    onClick={() =>
                      setQuickFilter((prev) => (prev === tag ? null : tag))
                    }
                  >
                    {tag}
                  </Button>
                ))}
              </div>
            </div>
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-3">
            {filtered.map((tool, i) => (
              <div
                key={`${tool.id ?? tool.name}-${i}`}
                className="p-4 border rounded-lg bg-card flex flex-col gap-2"
              >
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <p className="font-semibold">{tool.name}</p>
                    <p className="text-xs text-zinc-500">
                      {tool.description ?? ""}
                    </p>
                  </div>
                  <Badge variant="secondary">{tagLabel(tool)}</Badge>
                </div>
                {tool.parameters && tool.parameters.length > 0 ? (
                  <p className="text-xs text-zinc-500">
                    Paraméterek: {tool.parameters.map((p) => p.name).join(", ")}
                  </p>
                ) : (
                  <p className="text-xs text-zinc-500">
                    Nincs paraméter
                  </p>
                )}
                <Button
                  size="sm"
                  variant="outline"
                  className="mt-1 gap-2"
                  onClick={() => invoke(tool)}
                >
                  <Play size={14} /> Futtatás
                </Button>
              </div>
            ))}
            {filtered.length === 0 && (
              <div className="col-span-full text-zinc-500 text-sm border border-dashed rounded-md p-6">
                Nincs találat a megadott szűrőkkel.
              </div>
            )}
          </div>
        </CardContent>
      </Card>
      <Dialog
        open={!!activeTool}
        onOpenChange={(open) => {
          if (!open) setActiveTool(null);
        }}
      >
        <DialogContent className="sm:max-w-xl">
          <DialogHeader>
            <DialogTitle>{activeTool?.name}</DialogTitle>
            <DialogDescription>{activeTool?.description}</DialogDescription>
          </DialogHeader>
          <div className="space-y-3">
            {activeTool?.parameters?.map((p) => (
              <div key={p.name} className="space-y-1">
                <Label htmlFor={`param-${p.name}`}>
                  {p.name} {p.required ? "*" : ""}{" "}
                  <span className="text-xs text-zinc-500">
                    ({p.type})
                  </span>
                </Label>
                {p.type === "boolean" ? (
                  <div className="flex items-center gap-2">
                    <Switch
                      id={`param-${p.name}`}
                      checked={(formValue[p.name] ?? "false") === "true"}
                      onCheckedChange={(v) =>
                        setFormValue((prev) => ({
                          ...prev,
                          [p.name]: v ? "true" : "false",
                        }))
                      }
                    />
                    <span className="text-sm text-zinc-500">
                      {(formValue[p.name] ?? "false") === "true"
                        ? "true"
                        : "false"}
                    </span>
                  </div>
                ) : (p as any).enum && Array.isArray((p as any).enum) ? (
                  <Select
                    value={formValue[p.name] ?? ""}
                    onValueChange={(v) =>
                      setFormValue((prev) => ({ ...prev, [p.name]: v }))
                    }
                  >
                    <SelectTrigger id={`param-${p.name}`} className="w-full">
                      <SelectValue placeholder="Válassz" />
                    </SelectTrigger>
                    <SelectContent>
                      {(p as any).enum.map((opt: string) => (
                        <SelectItem key={opt} value={opt}>
                          {opt}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                ) : (
                  <Input
                    id={`param-${p.name}`}
                    value={formValue[p.name] ?? ""}
                    onChange={(e) =>
                      setFormValue((prev) => ({
                        ...prev,
                        [p.name]: e.target.value,
                      }))
                    }
                    placeholder={p.description || ""}
                  />
                )}
              </div>
            ))}
            {activeTool &&
              (!activeTool.parameters ||
                activeTool.parameters.length === 0) && (
                <p className="text-sm text-zinc-500">
                  Nincs paraméter ehhez a toolhoz.
                </p>
              )}
          </div>
          <DialogFooter className="flex justify-end gap-2">
            <Button variant="outline" onClick={() => setActiveTool(null)}>
              Mégse
            </Button>
            <Button onClick={submitForm}>Futtatás</Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </>
  );
}

import React, { useEffect, useState } from 'react';
import {
    Dialog,
    DialogContent,
    DialogHeader,
    DialogTitle,
} from '../ui/dialog';
import { Button } from '../ui/button';
import { ScrollArea } from '../ui/scroll-area';
import { X, Copy, ExternalLink } from 'lucide-react';
import { toast } from 'sonner';

interface TraceData {
    taskId: number;
    agentName: string;
    description: string;
    status: string;
    startedAt?: string;
    completedAt?: string;
    result?: any;
    error?: string;
    logs?: Array<{
        timestamp: string;
        level: string;
        message: string;
        agent?: string;
    }>;
    context?: any;
    priority?: number;
    retryCount?: number;
}

interface PerformanceMetrics {
    duration: string;
    avgLogInterval: string;
    errorRate: number;
}

interface TraceViewerModalProps {
    isOpen: boolean;
    onClose: () => void;
    taskId: number | null;
}

export function TraceViewerModal({ isOpen, onClose, taskId }: TraceViewerModalProps) {
    const [trace, setTrace] = useState<TraceData | null>(null);
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);

    useEffect(() => {
        if (!isOpen || !taskId) {
            setTrace(null);
            setError(null);
            return;
        }

        const fetchTrace = async () => {
            setLoading(true);
            setError(null);
            try {
                const response = await fetch(`/api/tasks/${taskId}`);
                if (!response.ok) {
                    throw new Error(`Failed to fetch trace: ${response.statusText}`);
                }
                const data = await response.json();
                setTrace(data.task);
            } catch (err: unknown) {
                const msg = err instanceof Error ? err.message : String(err);
                setError(msg);
                toast.error(`Failed to load trace: ${msg}`);
            } finally {
                setLoading(false);
            }
        };

        fetchTrace();
    }, [isOpen, taskId]);

    const copyToClipboard = () => {
        if (!trace) return;
        navigator.clipboard.writeText(JSON.stringify(trace, null, 2));
        toast.success('Trace copied to clipboard');
    };

    const openInLangSmith = () => {
        // LangSmith integration - open trace in external viewer
        if (!trace?.taskId) return;
        const langsmithUrl = `https://smith.langchain.com/o/${process.env.LANGCHAIN_ORG || 'your-org'}/projects/p/${process.env.LANGCHAIN_PROJECT || 'default'}/traces/${trace.taskId}`;
        window.open(langsmithUrl, '_blank');
        toast.success('Opening in LangSmith...');
    };

    const calculateMetrics = (): PerformanceMetrics | null => {
        if (!trace || !trace.startedAt) return null;
        
        const start = new Date(trace.startedAt).getTime();
        const end = trace.completedAt ? new Date(trace.completedAt).getTime() : Date.now();
        const durationMs = end - start;
        
        const duration = durationMs < 1000 
            ? `${durationMs}ms` 
            : durationMs < 60000 
            ? `${(durationMs / 1000).toFixed(2)}s` 
            : `${(durationMs / 60000).toFixed(2)}min`;
        
        const errorCount = trace.logs?.filter(l => l.level === 'error').length || 0;
        const totalLogs = trace.logs?.length || 0;
        const errorRate = totalLogs > 0 ? (errorCount / totalLogs) * 100 : 0;
        
        let avgLogInterval = 'N/A';
        if (trace.logs && trace.logs.length > 1) {
            const intervals: number[] = [];
            for (let i = 1; i < trace.logs.length; i++) {
                const prev = new Date(trace.logs[i - 1].timestamp).getTime();
                const curr = new Date(trace.logs[i].timestamp).getTime();
                intervals.push(curr - prev);
            }
            const avg = intervals.reduce((a, b) => a + b, 0) / intervals.length;
            avgLogInterval = avg < 1000 ? `${avg.toFixed(0)}ms` : `${(avg / 1000).toFixed(2)}s`;
        }
        
        return { duration, avgLogInterval, errorRate };
    };

    const metrics = calculateMetrics();

    return (
        <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
            <DialogContent className="max-w-4xl max-h-[80vh]">
                <DialogHeader>
                    <DialogTitle className="flex items-center justify-between">
                        <span>Deep Dive Trace - Task #{taskId}</span>
                        <div className="flex gap-2">
                            <Button size="sm" variant="outline" onClick={copyToClipboard}>
                                <Copy className="w-4 h-4 mr-1" />
                                Copy
                            </Button>
                            <Button size="sm" variant="outline" onClick={openInLangSmith}>
                                <ExternalLink className="w-4 h-4 mr-1" />
                                LangSmith
                            </Button>
                            <Button size="sm" variant="ghost" onClick={onClose}>
                                <X className="w-4 h-4" />
                            </Button>
                        </div>
                    </DialogTitle>
                </DialogHeader>

                <ScrollArea className="h-[60vh] w-full">
                    {loading && (
                        <div className="flex items-center justify-center h-full">
                            <div className="text-zinc-500">Loading trace...</div>
                        </div>
                    )}

                    {error && (
                        <div className="p-4 bg-destructive/10 text-destructive rounded-md">
                            <strong>Error:</strong> {error}
                        </div>
                    )}

                    {trace && !loading && (
                        <div className="space-y-4 p-4">
                            {/* Task Overview */}
                            <div className="bg-card p-4 rounded-lg border">
                                <h3 className="font-semibold mb-2">Task Overview</h3>
                                <div className="grid grid-cols-2 gap-2 text-sm">
                                    <div>
                                        <span className="text-zinc-500">Agent:</span>{' '}
                                        <span className="font-mono">{trace.agentName}</span>
                                    </div>
                                    <div>
                                        <span className="text-zinc-500">Status:</span>{' '}
                                        <span className={`font-semibold ${trace.status === 'completed' ? 'text-green-500' :
                                            trace.status === 'failed' ? 'text-red-500' :
                                                trace.status === 'running' ? 'text-yellow-500' :
                                                    'text-zinc-500'
                                            }`}>
                                            {trace.status}
                                        </span>
                                    </div>
                                    {trace.startedAt && (
                                        <div>
                                            <span className="text-zinc-500">Started:</span>{' '}
                                            {new Date(trace.startedAt).toLocaleString()}
                                        </div>
                                    )}
                                    {trace.completedAt && (
                                        <div>
                                            <span className="text-zinc-500">Completed:</span>{' '}
                                            {new Date(trace.completedAt).toLocaleString()}
                                        </div>
                                    )}
                                    {trace.priority !== undefined && (
                                        <div>
                                            <span className="text-zinc-500">Priority:</span>{' '}
                                            <span className="font-semibold">{trace.priority}</span>
                                        </div>
                                    )}
                                    {trace.retryCount !== undefined && trace.retryCount > 0 && (
                                        <div>
                                            <span className="text-zinc-500">Retries:</span>{' '}
                                            <span className="font-semibold text-orange-500">{trace.retryCount}</span>
                                        </div>
                                    )}
                                </div>
                                <div className="mt-2">
                                    <span className="text-zinc-500">Description:</span>
                                    <p className="mt-1">{trace.description}</p>
                                </div>
                            </div>

                            {/* Performance Metrics */}
                            {metrics && (
                                <div className="bg-card p-4 rounded-lg border">
                                    <h3 className="font-semibold mb-2">Performance Metrics</h3>
                                    <div className="grid grid-cols-3 gap-4 text-sm">
                                        <div className="text-center">
                                            <div className="text-2xl font-bold text-blue-500">{metrics.duration}</div>
                                            <div className="text-xs text-zinc-500">Duration</div>
                                        </div>
                                        <div className="text-center">
                                            <div className="text-2xl font-bold text-green-500">{metrics.avgLogInterval}</div>
                                            <div className="text-xs text-zinc-500">Avg Log Interval</div>
                                        </div>
                                        <div className="text-center">
                                            <div className={`text-2xl font-bold ${metrics.errorRate > 30 ? 'text-red-500' : metrics.errorRate > 10 ? 'text-yellow-500' : 'text-green-500'}`}>
                                                {metrics.errorRate.toFixed(1)}%
                                            </div>
                                            <div className="text-xs text-zinc-500">Error Rate</div>
                                        </div>
                                    </div>
                                </div>
                            )}

                            {/* Context */}
                            {trace.context && Object.keys(trace.context).length > 0 && (
                                <div className="bg-card p-4 rounded-lg border">
                                    <h3 className="font-semibold mb-2">Context</h3>
                                    <pre className="text-xs bg-muted p-2 rounded overflow-x-auto">
                                        {JSON.stringify(trace.context, null, 2)}
                                    </pre>
                                </div>
                            )}

                            {/* Result */}
                            {trace.result && (
                                <div className="bg-card p-4 rounded-lg border">
                                    <h3 className="font-semibold mb-2">Result</h3>
                                    <pre className="text-xs bg-muted p-2 rounded overflow-x-auto">
                                        {JSON.stringify(trace.result, null, 2)}
                                    </pre>
                                </div>
                            )}

                            {/* Error */}
                            {trace.error && (
                                <div className="bg-destructive/10 p-4 rounded-lg border border-destructive">
                                    <h3 className="font-semibold mb-2 text-destructive">Error</h3>
                                    <pre className="text-xs whitespace-pre-wrap">{trace.error}</pre>
                                </div>
                            )}

                            {/* Logs */}
                            {trace.logs && trace.logs.length > 0 && (
                                <div className="bg-card p-4 rounded-lg border">
                                    <h3 className="font-semibold mb-2">Execution Logs</h3>
                                    <div className="space-y-1">
                                        {trace.logs.map((log, idx) => (
                                            <div
                                                key={idx}
                                                className={`text-xs p-2 rounded font-mono ${log.level === 'error' ? 'bg-red-500/10 text-red-500' :
                                                    log.level === 'warn' ? 'bg-yellow-500/10 text-yellow-500' :
                                                        'bg-muted'
                                                    }`}
                                            >
                                                <span className="text-zinc-500">
                                                    [{new Date(log.timestamp).toLocaleTimeString()}]
                                                </span>{' '}
                                                {log.agent && <span className="font-semibold">[{log.agent}]</span>}{' '}
                                                {log.message}
                                            </div>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    )}
                </ScrollArea>
            </DialogContent>
        </Dialog>
    );
}

/**
 * TrackGenerator.tsx — SpecWriterAgent Dashboard Integration
 *
 * EPP v2 Protocol: Dashboard + CLI integration KÖTELEZŐ (Rule #6)
 *
 * Features:
 * - Kreatív ötlet input (textarea, 2-5 mondat)
 * - Track generálása 3-stage LLM pipeline-nal
 * - Real-time progress indicator (Stage 1/3, 2/3, 3/3)
 * - Markdown preview (marked renderer)
 * - Toast notifications (success/error)
 */

import { useState } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Textarea } from "@/components/ui/textarea";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import {
  Sparkles,
  Send,
  Activity,
  CheckCircle2,
  FileText,
  Rocket,
  AlertTriangle,
} from "lucide-react";
import { cn } from "@/lib/utils";
import { toast } from "sonner";
import { marked } from "marked";

// ==================== Types ====================

interface GeneratedTrackResult {
  trackId: string;
  trackPath: string;
  preview: string;
}

interface TrackMetadata {
  id: string;
  title: string;
  priority: string;
  progress: number;
  created: string;
}

// ==================== API Helpers ====================

const API_PREFIX = "/api/v1/tracks";

async function apiFetch<T>(path: string, options?: RequestInit): Promise<T> {
  const response = await fetch(`${API_PREFIX}${path}`, {
    headers: { "Content-Type": "application/json" },
    ...options,
  });

  const text = await response.text();
  if (!text) throw new Error(`Empty response from ${path}`);

  const data = JSON.parse(text) as T;
  if (!response.ok) {
    throw new Error(
      (data as Record<string, string>).error || `HTTP ${response.status}`,
    );
  }

  return data;
}

async function generateTrack(idea: string): Promise<GeneratedTrackResult> {
  return apiFetch<GeneratedTrackResult>("/generate", {
    method: "POST",
    body: JSON.stringify({ idea }),
  });
}

async function listTracks(): Promise<{
  count: number;
  tracks: TrackMetadata[];
}> {
  return apiFetch<{ success: boolean; count: number; tracks: TrackMetadata[] }>(
    "/",
  );
}

// ==================== Component ====================

export function TrackGenerator() {
  const [idea, setIdea] = useState("");
  const [isGenerating, setIsGenerating] = useState(false);
  const [currentStage, setCurrentStage] = useState(0); // 0 = idle, 1-3 = stages
  const [generatedTrack, setGeneratedTrack] =
    useState<GeneratedTrackResult | null>(null);
  const [recentTracks, setRecentTracks] = useState<TrackMetadata[]>([]);
  const [showRecentTracks, setShowRecentTracks] = useState(false);

  const handleGenerate = async () => {
    const trimmedIdea = idea.trim();
    if (!trimmedIdea || trimmedIdea.length < 10) {
      toast.error("Túl rövid ötlet! Írj legalább 2-3 mondatot.");
      return;
    }

    setIsGenerating(true);
    setCurrentStage(1);
    setGeneratedTrack(null);

    try {
      // Stage 1: Requirements extraction
      toast.info("📊 Stage 1/3: Követelmények kinyerése...");
      setCurrentStage(1);
      await new Promise((resolve) => setTimeout(resolve, 1000)); // Artificial delay for UX

      // Stage 2: Track markdown generation
      toast.info("📝 Stage 2/3: Track írása...");
      setCurrentStage(2);
      await new Promise((resolve) => setTimeout(resolve, 1000));

      // Stage 3: Validation & file write
      toast.info("✔️ Stage 3/3: Validálás...");
      setCurrentStage(3);

      const result = await generateTrack(trimmedIdea);

      setGeneratedTrack(result);
      toast.success(`✨ Track generálva: ${result.trackId}`);
      setIdea(""); // Clear input after success
    } catch (e: unknown) {
      const errorMessage = e instanceof Error ? e.message : "Ismeretlen hiba";
      toast.error(`❌ Hiba történt: ${errorMessage}`);
      console.error("Track generation failed:", e);
    } finally {
      setIsGenerating(false);
      setCurrentStage(0);
    }
  };

  const loadRecentTracks = async () => {
    try {
      const result = await listTracks();
      setRecentTracks(result.tracks.slice(0, 5)); // Show only 5 most recent
      setShowRecentTracks(true);
      toast.success(`${result.count} track található`);
    } catch (e: unknown) {
      const errorMessage =
        e instanceof Error ? e.message : "Failed to load tracks";
      toast.error(`Hiba: ${errorMessage}`);
    }
  };

  const renderMarkdown = (markdown: string): string => {
    return marked(markdown, { breaks: true, gfm: true }) as string;
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <h2 className="flex items-center gap-2 text-lg font-bold">
          <Sparkles size={20} className="text-primary" />
          Track Generátor
          <Badge variant="outline" className="ml-2 text-xs">
            EPP v2
          </Badge>
        </h2>
        <Button variant="ghost" size="sm" onClick={loadRecentTracks}>
          <FileText size={14} className="mr-1.5" />
          Tracks listázása
        </Button>
      </div>

      {/* Recent Tracks List */}
      {showRecentTracks && recentTracks.length > 0 && (
        <Card className="glass-card">
          <CardHeader className="pb-3 border-b border-border/50">
            <CardTitle className="flex items-center gap-2 text-sm">
              <FileText size={14} className="text-zinc-500" />
              Legutóbbi Tracks ({recentTracks.length})
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <ScrollArea className="h-[200px]">
              <div className="divide-y divide-border/50">
                {recentTracks.map((track, i) => (
                  <div
                    key={`${track.id}-${i}`}
                    className="flex items-center gap-3 px-4 py-3 hover:bg-muted/50 transition-colors"
                  >
                    <div className="flex-1 min-w-0">
                      <p className="text-sm font-medium truncate">
                        {track.title}
                      </p>
                      <p className="text-xs text-zinc-500">
                        ID: {track.id} • {track.created}
                      </p>
                    </div>
                    <Badge variant="outline" className="text-xs">
                      {track.priority}
                    </Badge>
                    <span className="text-xs text-zinc-500">
                      {track.progress}%
                    </span>
                  </div>
                ))}
              </div>
            </ScrollArea>
          </CardContent>
        </Card>
      )}

      {/* Input Card */}
      <Card className="glass-card">
        <CardHeader className="pb-3">
          <CardTitle className="text-sm flex items-center gap-2">
            <Rocket size={14} className="text-primary" />
            Írd le az ötleted (2-5 mondat, magyarul is OK)
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <Textarea
            value={idea}
            onChange={(e) => setIdea(e.target.value)}
            placeholder="Példa: Dashboard TODO widget real-time sync-kal. WebSocket frissítés, checkbox toggle, track progress megjelenítés. Használjuk a Socket.IO-t és egy új React komponenst."
            rows={6}
            disabled={isGenerating}
            className="resize-none"
          />
          <div className="flex items-center justify-between">
            <span className="text-xs text-zinc-500">
              {idea.length} karakter •{" "}
              {idea.trim().length < 10
                ? "Írj még legalább " + (10 - idea.trim().length) + " karaktert"
                : "Rendben!"}
            </span>
            <Button
              onClick={handleGenerate}
              disabled={!idea.trim() || idea.trim().length < 10 || isGenerating}
              className="gap-2"
            >
              {isGenerating ? (
                <>
                  <Activity size={14} className="animate-spin" />
                  Generálás...
                </>
              ) : (
                <>
                  <Send size={14} />
                  Track Generálása
                </>
              )}
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* Progress Indicator */}
      {isGenerating && currentStage > 0 && (
        <Card className="glass-card border-blue-500/30">
          <CardContent className="p-4">
            <div className="space-y-3">
              <div className="flex items-center gap-2 text-sm font-medium">
                <Activity size={14} className="text-blue-500 animate-pulse" />
                Track generálása folyamatban...
              </div>
              <div className="space-y-2">
                {[
                  {
                    stage: 1,
                    label: "Követelmények kinyerése",
                    icon: CheckCircle2,
                  },
                  { stage: 2, label: "Track írása", icon: FileText },
                  { stage: 3, label: "Validálás", icon: CheckCircle2 },
                ].map((item) => (
                  <div
                    key={item.stage}
                    className={cn(
                      "flex items-center gap-2 text-xs transition-all",
                      currentStage === item.stage &&
                        "text-blue-500 font-medium",
                      currentStage > item.stage && "text-green-500",
                      currentStage < item.stage && "text-zinc-500",
                    )}
                  >
                    {currentStage > item.stage ? (
                      <CheckCircle2 size={12} className="text-green-500" />
                    ) : currentStage === item.stage ? (
                      <Activity
                        size={12}
                        className="animate-spin text-blue-500"
                      />
                    ) : (
                      <div className="h-3 w-3 rounded-full border border-border" />
                    )}
                    <span>
                      Stage {item.stage}/3: {item.label}
                    </span>
                  </div>
                ))}
              </div>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Generated Track Preview */}
      {generatedTrack && !isGenerating && (
        <Card className="glass-card border-green-500/30">
          <CardHeader className="pb-3 border-b border-border/50">
            <CardTitle className="flex items-center gap-2 text-sm">
              <CheckCircle2 size={14} className="text-green-500" />
              Track generálva: {generatedTrack.trackId}
              <Badge variant="outline" className="ml-auto text-[10px]">
                {generatedTrack.trackPath}
              </Badge>
            </CardTitle>
          </CardHeader>
          <CardContent className="p-0">
            <ScrollArea className="h-[400px]">
              <div
                className="prose prose-sm dark:prose-invert max-w-none px-4 py-3"
                dangerouslySetInnerHTML={{
                  __html: renderMarkdown(generatedTrack.preview),
                }}
              />
            </ScrollArea>
          </CardContent>
        </Card>
      )}

      {/* Empty State */}
      {!isGenerating && !generatedTrack && !showRecentTracks && (
        <Card className="glass-card">
          <CardContent className="p-8 text-center">
            <Sparkles
              size={32}
              className="text-zinc-500/50 mx-auto mb-3"
            />
            <p className="text-sm text-zinc-500">
              Írj be egy kreatív ötletet (2-5 mondat), majd kattints a
              &quot;Track Generálása&quot; gombra.
            </p>
            <p className="text-xs text-zinc-500/70 mt-1">
              A SpecWriterAgent automatikusan létrehoz egy professzionális EPP
              v2 compliant track.md fájlt.
            </p>
          </CardContent>
        </Card>
      )}

      {/* Info Card */}
      <Card className="glass-card border-yellow-500/20 bg-yellow-500/5">
        <CardContent className="p-4 flex items-start gap-3">
          <AlertTriangle
            size={16}
            className="text-yellow-500 mt-0.5 shrink-0"
          />
          <div className="space-y-1">
            <p className="text-sm font-medium">
              EPP v2 Rule #6: Dashboard + CLI Integration
            </p>
            <p className="text-xs text-zinc-500">
              Minden generált track tartalmaz Dashboard komponens és CLI parancs
              leírást. A CLI-ből használd:{" "}
              <code className="bg-muted px-1 py-0.5 rounded text-[10px]">
                brunella tracks generate
              </code>
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * Track TODO Widget
 *
 * Real-time track progress widget displaying TODO checkboxes
 */

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '../ui/card';
import { Button } from '../ui/button';
import { Checkbox } from '../ui/checkbox';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '../ui/select';
import { Progress } from '../ui/progress';
import { Badge } from '../ui/badge';
import { Loader2, CheckCircle2, Circle } from 'lucide-react';

interface TrackTodoItem {
  id: string;
  text: string;
  completed: boolean;
  lineNumber: number;
}

interface TrackTodoView {
  trackId: string;
  trackTitle: string;
  status: string;
  todos: TrackTodoItem[];
  progress: number;
}

interface TrackMeta {
  id: string;
  name: string;
  status: string;
  priority: string;
  progress: number;
}

export function TrackTodoWidget() {
  const [tracks, setTracks] = useState<TrackMeta[]>([]);
  const [selectedTrackId, setSelectedTrackId] = useState<string>('');
  const [todoView, setTodoView] = useState<TrackTodoView | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string>('');

  // Load available tracks
  useEffect(() => {
    fetchTracks();
  }, []);

  // Load TODOs when track is selected
  useEffect(() => {
    if (selectedTrackId) {
      fetchTodos(selectedTrackId);
    }
  }, [selectedTrackId]);

  const fetchTracks = async () => {
    try {
      const res = await fetch('/api/v1/tracks');
      const data = await res.json();
      setTracks(data.tracks || []);

      // Auto-select first active track
      const firstActive = data.tracks.find((t: TrackMeta) => t.status === 'active' || t.status === 'in_progress');
      if (firstActive) {
        setSelectedTrackId(firstActive.id);
      }
    } catch (err) {
      console.error('Failed to fetch tracks:', err);
      setError('Failed to load tracks');
    }
  };

  const fetchTodos = async (trackId: string) => {
    setLoading(true);
    setError('');

    try {
      const res = await fetch(`/api/v1/tracks/${trackId}/todos`);
      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
      }
      const data = await res.json();
      setTodoView(data);
    } catch (err) {
      console.error('Failed to fetch TODOs:', err);
      setError('Failed to load TODOs');
      setTodoView(null);
    } finally {
      setLoading(false);
    }
  };

  const toggleTodo = async (todoId: string) => {
    if (!selectedTrackId) return;

    try {
      const res = await fetch(`/api/v1/tracks/${selectedTrackId}/todos/${todoId}`, {
        method: 'PATCH',
      });

      if (!res.ok) {
        throw new Error(`HTTP ${res.status}`);
      }

      const updatedView = await res.json();
      setTodoView(updatedView);
    } catch (err) {
      console.error('Failed to toggle TODO:', err);
      setError('Failed to update TODO');
    }
  };

  const activeStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case 'completed':
      case 'archived':
        return 'bg-green-500/10 text-green-500';
      case 'active':
      case 'in_progress':
        return 'bg-blue-500/10 text-blue-500';
      default:
        return 'bg-gray-500/10 text-gray-500';
    }
  };

  return (
    <Card className="col-span-1">
      <CardHeader>
        <CardTitle>Track TODO Progress</CardTitle>
        <CardDescription>
          Real-time track progress tracking
        </CardDescription>
      </CardHeader>
      <CardContent className="space-y-4">
        {/* Track Selector */}
        <div className="space-y-2">
          <label className="text-sm font-medium">Select Track</label>
          <Select value={selectedTrackId} onValueChange={setSelectedTrackId}>
            <SelectTrigger>
              <SelectValue placeholder="Choose a track..." />
            </SelectTrigger>
            <SelectContent>
              {tracks.map((track) => (
                <SelectItem key={track.id} value={track.id}>
                  {track.name || track.id} ({track.status})
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>

        {/* Error Message */}
        {error && (
          <div className="p-3 rounded-md bg-red-500/10 text-red-500 text-sm">
            {error}
          </div>
        )}

        {/* Loading State */}
        {loading && (
          <div className="flex items-center justify-center p-8">
            <Loader2 className="h-6 w-6 animate-spin text-blue-500" />
          </div>
        )}

        {/* TODO List */}
        {!loading && todoView && (
          <div className="space-y-4">
            {/* Track Header */}
            <div className="flex items-center justify-between">
              <div>
                <h3 className="font-medium">{todoView.trackTitle}</h3>
                <Badge className={activeStatusColor(todoView.status)}>
                  {todoView.status}
                </Badge>
              </div>
              <div className="text-sm text-zinc-500">
                {todoView.todos.filter(t => t.completed).length} / {todoView.todos.length} done
              </div>
            </div>

            {/* Progress Bar */}
            <div className="space-y-1">
              <Progress value={todoView.progress} className="h-2" />
              <div className="text-xs text-zinc-500 text-right">
                {todoView.progress}% complete
              </div>
            </div>

            {/* TODO Checklist */}
            <div className="space-y-2 max-h-96 overflow-y-auto">
              {todoView.todos.length === 0 ? (
                <p className="text-sm text-zinc-500 text-center py-4">
                  No TODO items found
                </p>
              ) : (
                todoView.todos.map((todo) => (
                  <div
                    key={todo.id}
                    className="flex items-start space-x-2 p-2 rounded-md hover:bg-accent/50 transition-colors"
                  >
                    <Checkbox
                      id={todo.id}
                      checked={todo.completed}
                      onCheckedChange={() => toggleTodo(todo.id)}
                      className="mt-0.5"
                    />
                    <label
                      htmlFor={todo.id}
                      className={`text-sm flex-1 cursor-pointer ${
                        todo.completed ? 'line-through text-zinc-500' : ''
                      }`}
                    >
                      {todo.text}
                    </label>
                    {todo.completed ? (
                      <CheckCircle2 className="h-4 w-4 text-green-500 mt-0.5" />
                    ) : (
                      <Circle className="h-4 w-4 text-gray-400 mt-0.5" />
                    )}
                  </div>
                ))
              )}
            </div>
          </div>
        )}

        {/* Empty State */}
        {!loading && !todoView && !error && selectedTrackId && (
          <div className="text-center py-8 text-zinc-500">
            <p className="text-sm">No track.md file found</p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

