  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {fleets.map((fleet) => {
          const health = healthData[fleet.id];
          const isSelected = selectedFleet === fleet.id;
