/**
 * Hook for fetching a single fleet
 * Path: src/dashboard/components/fleet/hooks/useFleet.ts
 */

import { useState, useEffect, useCallback } from 'react';
import { Fleet } from '../types.js';
import { useCEANSocket } from '../../cean/hooks/useCEANSocket.js';

interface UseFleetResult {
  fleet: Fleet | null;
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

export function useFleet(fleetId: string): UseFleetResult {
  const [fleet, setFleet] = useState<Fleet | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { socket } = useCEANSocket();

  const fetchFleet = useCallback(async () => {
    if (!fleetId) return;

    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/fleet/${fleetId}`);
      if (!response.ok) {
        throw new Error(`Fleet fetch failed: ${response.statusText}`);
      }
      const data = await response.json();
      setFleet(data.data || null);
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      setFleet(null);
    } finally {
      setLoading(false);
    }
  }, [fleetId]);

  // Initial fetch
  useEffect(() => {
    fetchFleet();
  }, [fetchFleet]);

  // Listen for fleet updates via Socket.IO
  useEffect(() => {
    if (!socket) return;

    const handleFleetUpdated = (data: any) => {
      if (data.fleet_id === fleetId) {
        setFleet(data);
      }
    };

    socket.on('fleet_updated', handleFleetUpdated);

    return () => {
      socket.off('fleet_updated', handleFleetUpdated);
    };
  }, [socket, fleetId]);

  return { fleet, loading, error, refetch: fetchFleet };
}

/**
 * Hook for fetching all fleets with health status
 * Path: src/dashboard/components/fleet/hooks/useFleetList.ts
 */

import { useState, useEffect, useCallback } from 'react';
import { Fleet, FleetHealth } from '../types.js';
import { useCEANSocket } from '../../cean/hooks/useCEANSocket.js';

interface UseFleetListResult {
  fleets: Fleet[];
  healthData: Record<string, FleetHealth>;
  totalWorkers: number;
  totalErrors: number;
  avgLatency: number;
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

export function useFleetList(): UseFleetListResult {
  const [fleets, setFleets] = useState<Fleet[]>([]);
  const [healthData, setHealthData] = useState<Record<string, FleetHealth>>({});
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { socket } = useCEANSocket();

  const fetchFleets = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      // Fetch fleet list
      const fleetsResponse = await fetch('/api/fleet/list');
      if (!fleetsResponse.ok) {
        throw new Error(`Fleet list fetch failed: ${fleetsResponse.statusText}`);
      }
      const fleetsData = await fleetsResponse.json();
      const fleetsList = fleetsData.data || [];
      setFleets(fleetsList);

      // Fetch health summary for each fleet
      const healthMap: Record<string, FleetHealth> = {};

      for (const fleet of fleetsList) {
        try {
          const healthResponse = await fetch(`/api/metrics/fleet/${fleet.id}/summary`);
          if (healthResponse.ok) {
            const healthDataPayload = await healthResponse.json();
            healthMap[fleet.id] = healthDataPayload.data || {
              total_workers: 0,
              healthy_workers: 0,
              error_rate: 0,
              avg_latency: 0,
              p95_latency: 0,
              rps: 0,
            };
          }
        } catch (err) {
          console.warn(`Failed to fetch health for fleet ${fleet.id}:`, err);
          healthMap[fleet.id] = {
            total_workers: 0,
            healthy_workers: 0,
            error_rate: 0,
            avg_latency: 0,
            p95_latency: 0,
            rps: 0,
          };
        }
      }

      setHealthData(healthMap);
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      setFleets([]);
    } finally {
      setLoading(false);
    }
  }, []);

  // Initial fetch
  useEffect(() => {
    fetchFleets();

    // Auto-refetch every 10 seconds
    const interval = setInterval(fetchFleets, 10000);

    return () => clearInterval(interval);
  }, [fetchFleets]);

  // Listen for fleet updates via Socket.IO
  useEffect(() => {
    if (!socket) return;

    const handleFleetScaled = (data: any) => {
      setHealthData((prev) => ({
        ...prev,
        [data.fleet_id]: {
          ...prev[data.fleet_id],
          total_workers: data.new_worker_count,
        },
      }));
    };

    const handleMetricsUpdated = (data: any) => {
      setHealthData((prev) => ({
        ...prev,
        [data.fleet_id]: data,
      }));
    };

    socket.on('fleet_scaled', handleFleetScaled);
    socket.on('metrics_updated', handleMetricsUpdated);

    return () => {
      socket.off('fleet_scaled', handleFleetScaled);
      socket.off('metrics_updated', handleMetricsUpdated);
    };
  }, [socket]);

  // Calculate aggregates
  const totalWorkers = Object.values(healthData).reduce(
    (sum, h) => sum + (h.total_workers || 0),
    0
  );
  const totalErrors = Object.values(healthData).reduce(
    (sum, h) => sum + Math.round((h.error_rate || 0) * 100),
    0
  );
  const avgLatency =
    Object.values(healthData).length > 0
      ? Math.round(
          Object.values(healthData).reduce((sum, h) => sum + (h.avg_latency || 0), 0) /
            Object.values(healthData).length
        )
      : 0;

  return {
    fleets,
    healthData,
    totalWorkers,
    totalErrors,
    avgLatency,
    loading,
    error,
    refetch: fetchFleets,
  };
}

/**
 * Hook for fetching and managing scaling policies
 * Path: src/dashboard/components/fleet/hooks/useScaling.ts
 */

import { useState, useEffect, useCallback } from 'react';
import { ScalingPolicy } from '../types.js';
import { useCEANSocket } from '../../cean/hooks/useCEANSocket.js';

interface UseScalingResult {
  policy: ScalingPolicy | null;
  policies: ScalingPolicy[];
  loading: boolean;
  error: string | null;
  executeScale: (fleetId: string, direction: 'up' | 'down') => Promise<void>;
  savePolicy: (policy: ScalingPolicy) => Promise<void>;
  fetchPolicy: () => Promise<void>;
}

export function useScaling(fleetId?: string): UseScalingResult {
  const [policy, setPolicy] = useState<ScalingPolicy | null>(null);
  const [policies, setPolicies] = useState<ScalingPolicy[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { socket } = useCEANSocket();

  const fetchPolicies = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const response = await fetch('/api/scaling/policies');
      if (!response.ok) {
        throw new Error(`Policies fetch failed: ${response.statusText}`);
      }
      const data = await response.json();
      const policiesList = data.data || [];
      setPolicies(policiesList);

      // If fleetId is provided, find its policy
      if (fleetId) {
        const fleetPolicy = policiesList.find((p: ScalingPolicy) => p.fleet_id === fleetId);
        setPolicy(fleetPolicy || null);
      }
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      setPolicies([]);
    } finally {
      setLoading(false);
    }
  }, [fleetId]);

  // Initial fetch
  useEffect(() => {
    fetchPolicies();
  }, [fetchPolicies]);

  const executeScale = useCallback(
    async (targetFleetId: string, direction: 'up' | 'down') => {
      setError(null);

      try {
        const response = await fetch('/api/scaling/trigger', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            fleet_id: targetFleetId,
            direction,
          }),
        });

        if (!response.ok) {
          throw new Error(`Scale trigger failed: ${response.statusText}`);
        }

        const data = await response.json();
        if (data.success) {
          // Refetch policies to get updated worker counts
          await fetchPolicies();
        } else {
          throw new Error(data.error || 'Scaling failed');
        }
      } catch (err: unknown) {
        const errorMessage = err instanceof Error ? err.message : 'Unknown error';
        setError(errorMessage);
        throw err;
      }
    },
    [fetchPolicies]
  );

  const savePolicy = useCallback(async (newPolicy: ScalingPolicy) => {
    setError(null);

    try {
      const response = await fetch(`/api/scaling/policies/${newPolicy.fleet_id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newPolicy),
      });

      if (!response.ok) {
        throw new Error(`Policy save failed: ${response.statusText}`);
      }

      const data = await response.json();
      if (data.success) {
        setPolicy(data.data || null);
        // Update policies list
        setPolicies((prev) =>
          prev.map((p) => (p.fleet_id === newPolicy.fleet_id ? data.data : p))
        );
      } else {
        throw new Error(data.error || 'Policy save failed');
      }
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      throw err;
    }
  }, []);

  // Listen for scaling events
  useEffect(() => {
    if (!socket) return;

    const handleFleetScaled = (data: any) => {
      if (!fleetId || data.fleet_id === fleetId) {
        // Refetch on any scaling event
        fetchPolicies();
      }
    };

    socket.on('fleet_scaled', handleFleetScaled);

    return () => {
      socket.off('fleet_scaled', handleFleetScaled);
    };
  }, [socket, fleetId, fetchPolicies]);

  return {
    policy,
    policies,
    loading,
    error,
    executeScale,
    savePolicy,
    fetchPolicy: fetchPolicies,
  };
}

/**
 * Hook for fetching worker metrics with live updates
 * Path: src/dashboard/components/fleet/hooks/useWorkerMetrics.ts
 */

import { useState, useEffect, useCallback } from 'react';
import { WorkerMetrics } from '../types.js';
import { useCEANSocket } from '../../cean/hooks/useCEANSocket.js';

interface UseWorkerMetricsResult {
  metrics: WorkerMetrics | null;
  loading: boolean;
  error: string | null;
  refetch: () => Promise<void>;
}

export function useWorkerMetrics(workerId: string): UseWorkerMetricsResult {
  const [metrics, setMetrics] = useState<WorkerMetrics | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const { socket } = useCEANSocket();

  const fetchMetrics = useCallback(async () => {
    if (!workerId) return;

    setLoading(true);
    setError(null);

    try {
      const response = await fetch(`/api/metrics/${workerId}/latest`);
      if (!response.ok) {
        throw new Error(`Metrics fetch failed: ${response.statusText}`);
      }
      const data = await response.json();
      setMetrics(data.data || null);
    } catch (err: unknown) {
      const errorMessage = err instanceof Error ? err.message : 'Unknown error';
      setError(errorMessage);
      setMetrics(null);
    } finally {
      setLoading(false);
    }
  }, [workerId]);

  // Initial fetch
  useEffect(() => {
    fetchMetrics();

    // Auto-refetch every 5 seconds
    const interval = setInterval(fetchMetrics, 5000);

    return () => clearInterval(interval);
  }, [fetchMetrics]);

  // Listen for real-time metrics updates via Socket.IO
  useEffect(() => {
    if (!socket) return;

    const handleMetricsUpdated = (data: any) => {
      if (data.worker_id === workerId) {
        setMetrics(data);
      }
    };

    const handleWorkerStatusChanged = (data: any) => {
      if (data.worker_id === workerId) {
        setMetrics((prev) => ({
          ...prev,
          status: data.status,
          last_updated: new Date().toISOString(),
        } as WorkerMetrics));
      }
    };

    socket.on('metrics_updated', handleMetricsUpdated);
    socket.on('worker_status_changed', handleWorkerStatusChanged);

    return () => {
      socket.off('metrics_updated', handleMetricsUpdated);
      socket.off('worker_status_changed', handleWorkerStatusChanged);
    };
  }, [socket, workerId]);

  return { metrics, loading, error, refetch: fetchMetrics };
}

