import React, { createContext, useContext, useState, useEffect } from "react";

type ExperimentVariant = "A" | "B";

interface ExperimentContextType {
  layoutDensity: ExperimentVariant;
  aiResponseStyle: ExperimentVariant;
}

const ExperimentContext = createContext<ExperimentContextType | undefined>(undefined);

export const ExperimentProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [variants, setVariants] = useState<ExperimentContextType>({
    layoutDensity: "A",
    aiResponseStyle: "A"
  });

  useEffect(() => {
    // Randomly assign variants if not already set
    const saved = localStorage.getItem("bas-experiments");
    if (saved) {
      setVariants(JSON.parse(saved));
    } else {
      const newVariants: ExperimentContextType = {
        layoutDensity: Math.random() > 0.5 ? "A" : "B",
        aiResponseStyle: Math.random() > 0.5 ? "A" : "B"
      };
      setVariants(newVariants);
      localStorage.setItem("bas-experiments", JSON.stringify(newVariants));
      console.log("BAS VCC Experiments Initialized:", newVariants);
    }
  }, []);

  return (
    <ExperimentContext.Provider value={variants}>
      {children}
    </ExperimentContext.Provider>
  );
};

export const useExperiments = () => {
  const context = useContext(ExperimentContext);
  if (!context) {
    throw new Error("useExperiments must be used within an ExperimentProvider");
  }
  return context;
};

import {
  createContext,
  useContext,
  useEffect,
  useState,
  type ReactNode,
} from "react";
import { io, type Socket } from "socket.io-client";
import { useSystemSignalStore } from "../store/systemSignalStore";
import {
  getTasks,
  getTaskStats,
  checkHealth,
  getDeveloperMetrics,
} from "../lib/apiService";

export type LogType = "info" | "error" | "success";

export interface LogEntry {
  id: string;
  message: string;
  type: LogType;
  timestamp: number;
  source?: string;
}

export type AgentStatusPayload = "idle" | "working" | "error";

export interface RobotkezStep {
  index: number;
  status: 'pending' | 'working' | 'completed' | 'error';
  description: string;
  screenshot?: string;
  error?: string;
}

export interface RobotkezPlan {
  taskId: string;
  plan: {
    plan: RobotkezStep[];
    estimatedDuration: number;
  };
}

export interface AgentStatusEntry {
  name: string;
  status: AgentStatusPayload;
  taskDescription?: string;
  lastUpdated: number;
}

export interface ChatterEntry {
  id: string;
  sender: string;
  receiver?: string;
  message: string;
  context?: any;
  timestamp: number;
}

interface SocketContextValue {
  socket: Socket | null;
}

const SocketContext = createContext<SocketContextValue | null>(null);

const SOCKET_URL = import.meta.env.VITE_SOCKET_URL || "";

export function SocketProvider({ children }: { children: ReactNode }) {
  const [socketInstance, setSocketInstance] = useState<Socket | null>(null);

  // Get actions from the store
  const setConnected = useSystemSignalStore((state) => state.setConnected);
  const addLog = useSystemSignalStore((state) => state.addLog);
  const addChatter = useSystemSignalStore((state) => state.addChatter);
  const updateAgentStatus = useSystemSignalStore((state) => state.updateAgentStatus);
  const setAllAgentStatuses = useSystemSignalStore((state) => state.setAllAgentStatuses);
  const setRobotkezPlan = useSystemSignalStore((state) => state.setRobotkezPlan);
  const updateRobotkezStep = useSystemSignalStore((state) => state.updateRobotkezStep);
  const clearRobotkez = useSystemSignalStore((state) => state.clearRobotkez);
  const addMachineAlert = useSystemSignalStore((state) => state.addMachineAlert);
  const setError = useSystemSignalStore((state) => state.setError);
  const setLoading = useSystemSignalStore((state) => state.setLoading);
  const setTasks = useSystemSignalStore((state) => state.setTasks);
  const setTaskStats = useSystemSignalStore((state) => state.setTaskStats);
  const setHealthStatus = useSystemSignalStore((state) => state.setHealthStatus);
  const setDeveloperMetrics = useSystemSignalStore((state) => state.setDeveloperMetrics);

  // Initial REST fetch
  useEffect(() => {
    let isMounted = true;
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        const [tasksRes, taskStatsRes, healthRes, devMetricsRes] = await Promise.allSettled([
          getTasks(50, 0, "running"),
          getTaskStats(),
          checkHealth(),
          getDeveloperMetrics(),
        ]);

        if (!isMounted) return;

        if (tasksRes.status === "fulfilled") setTasks(tasksRes.value.tasks);
        else setError(tasksRes.reason.message);

        if (taskStatsRes.status === "fulfilled") setTaskStats(taskStatsRes.value);
        else setError(taskStatsRes.reason.message);

        if (healthRes.status === "fulfilled") setHealthStatus(healthRes.value);
        else setError(healthRes.reason.message);

        if (devMetricsRes.status === "fulfilled") setDeveloperMetrics(devMetricsRes.value);
        else setError(devMetricsRes.reason.message);

      } catch (err: any) {
        if (!isMounted) return;
        setError(err.message || "Adatlekérdezési hiba");
        addLog({ message: `REST adatlekérdezési hiba: ${err.message}`, type: "error", source: "SystemSignal" });
      } finally {
        if (isMounted) setLoading(false);
      }
    };

    fetchData();
    const interval = setInterval(fetchData, 5000);
    return () => {
      isMounted = false;
      clearInterval(interval);
    };
  }, [setLoading, setError, setTasks, setTaskStats, setHealthStatus, setDeveloperMetrics, addLog]);

  useEffect(() => {
    const socket = io(SOCKET_URL, {
      path: "/socket.io",
      transports: ["polling", "websocket"],
      reconnection: true,
      reconnectionAttempts: 5,
      reconnectionDelay: 1000,
    });

    setSocketInstance(socket);

    // Expose socket to window for E2E testing
    if (typeof window !== 'undefined') {
      (window as any).__BRUNELLA_SOCKET__ = socket;
    }

    const getErrorMessage = (error: unknown): string => {
      if (error instanceof Error) return error.message;
      if (typeof error === "string") return error;
      if (typeof error === "object" && error !== null) {
        const maybe = (error as { message?: unknown }).message;
        if (typeof maybe === "string") return maybe;
      }
      return "ismeretlen hiba";
    };

    const log = (message: string, type: LogType = "info") => {
      addLog({
        message,
        type,
        timestamp: Date.now(),
        source: "Socket",
      });
    };

    const onConnect = () => {
      setConnected(true);
      log("Socket csatlakozva ✅", "success");
    };

    const onDisconnect = (reason: unknown) => {
      setConnected(false);
      const r = typeof reason === "string" ? reason : "unknown";
      log(`Socket bontva: ${r}`, "error");
    };

    const onConnectError = (error: unknown) => {
      log(`Socket kapcsolódási hiba: ${getErrorMessage(error)}`, "error");
    };

    const onError = (error: unknown) => {
      const msg = getErrorMessage(error);
      log(`Socket hiba: ${msg}`, "error");
    };

    socket.on("connect", onConnect);
    socket.on("disconnect", onDisconnect);
    socket.on("connect_error", onConnectError);
    socket.on("error", onError);

    // Reconnect UX (manager events)
    const manager = socket.io;
    const onReconnectAttempt = (attempt: unknown) => {
      const n = typeof attempt === "number" ? attempt : undefined;
      log(`Socket újrapróbálkozás...${n ? ` (#${n})` : ""}`);
    };
    const onReconnect = (attempt: unknown) => {
      const n = typeof attempt === "number" ? attempt : undefined;
      log(`Socket újracsatlakozott ✅${n ? ` (#${n})` : ""}`, "success");
    };
    const onReconnectError = (_err: unknown) => {
      log("Socket újracsatlakozás sikertelen (próbálkozás fut)", "error");
    };
    const onReconnectFailed = () => {
      log("Socket újracsatlakozás feladva (max próbálkozás)", "error");
    };

    manager.on("reconnect_attempt", onReconnectAttempt);
    manager.on("reconnect", onReconnect);
    manager.on("reconnect_error", onReconnectError);
    manager.on("reconnect_failed", onReconnectFailed);

    socket.on(
      "system:log",
      (data: {
        message: string;
        type: LogType;
        timestamp?: number;
        source?: string;
      }) => {
        addLog({
          message: data.message,
          type: data.type ?? "info",
          timestamp: data.timestamp ?? Date.now(),
          source: data.source,
        });
      },
    );

    socket.on(
      "agent:chatter",
      (data: {
        sender: string;
        receiver?: string;
        message: string;
        context?: any;
        timestamp?: number;
      }) => {
        addChatter({
          sender: data.sender,
          receiver: data.receiver,
          message: data.message,
          context: data.context,
          timestamp: data.timestamp ?? Date.now(),
        });
      },
    );

    socket.on(
      "agent:update",
      (data: {
        agentName: string;
        status: AgentStatusPayload;
        taskDescription?: string;
      }) => {
        if (data.agentName && data.status) {
          updateAgentStatus(data.agentName, data.status, data.taskDescription);
        }
      },
    );

    socket.on("robotkez:plan", (data: RobotkezPlan) => {
      setRobotkezPlan(data);
    });

    socket.on("robotkez:step", (data: Partial<RobotkezStep> & { index: number }) => {
      updateRobotkezStep(data);
    });

    socket.on("robotkez:aborted", () => {
      clearRobotkez();
    });

    socket.on("agents:snapshot", (data: AgentStatusEntry[]) => {
      if (Array.isArray(data)) {
        setAllAgentStatuses(data);
      }
    });

    socket.on("machine:alert", (data: any) => {
      addMachineAlert(data);
    });

    // Developer pipeline progress → rendszernapló + chatter
    socket.on("developer:progress", (data: {
      taskId?: string;
      phaseId?: string;
      status?: string;
      progress?: number;
      message?: string;
    }) => {
      if (data.message) {
        addLog({
          message: `[Pipeline] ${data.message}`,
          type: data.status === 'error' ? 'error' : 'info',
          source: 'DeveloperPipeline',
        });
        addChatter({
          sender: 'DeveloperPipeline',
          message: data.message,
          timestamp: Date.now(),
        });
      }
    });

    // Task lista valós idejű frissítése (szerver 5mp-enként küldi)
    socket.on("tasks_update", (data: any[]) => {
      if (Array.isArray(data)) {
        setTasks(data);
      }
    });

    return () => {
      socket.off("connect", onConnect);
      socket.off("disconnect", onDisconnect);
      socket.off("connect_error", onConnectError);
      socket.off("error", onError);

      manager.off("reconnect_attempt", onReconnectAttempt);
      manager.off("reconnect", onReconnect);
      manager.off("reconnect_error", onReconnectError);
      manager.off("reconnect_failed", onReconnectFailed);

      socket.off("system:log");
      socket.off("agent:update");
      socket.off("agent:chatter");
      socket.off("robotkez:plan");
      socket.off("robotkez:step");
      socket.off("robotkez:aborted");
      socket.off("agents:snapshot");
      socket.off("machine:alert");
      socket.off("developer:progress");
      socket.off("tasks_update");
      socket.disconnect();
      setSocketInstance(null);
    };
  }, [setConnected, addLog, addChatter, updateAgentStatus, setAllAgentStatuses, setRobotkezPlan, updateRobotkezStep, clearRobotkez, addMachineAlert, setTasks]);

  const value: SocketContextValue = {
    socket: socketInstance,
  };

  return (
    <SocketContext.Provider value={value}>{children}</SocketContext.Provider>
  );
}

export function useSocket() {
  const ctx = useContext(SocketContext);
  if (!ctx) throw new Error("useSocket must be used within SocketProvider");
  return ctx;
}

/**
 * Custom hook to initialize Dashboard data from backend API
 */

import { useEffect, useState } from 'react';
import { useMcpStore } from '@/lib/mcpStore';
import * as api from '@/lib/apiService';
import { toast } from 'sonner';

export function useDashboardData() {
    const { setAgentTools, setServerState, setConnected } = useMcpStore();

    useEffect(() => {
        let mounted = true;

        async function initializeData() {
            try {
                // Check health
                const health = await api.checkHealth();
                
                if (mounted) {
                    setConnected(true);
                    setServerState({
                        status: health.status === 'ok' ? 'running' : 'error',
                        lastUpdated: health.timestamp
                    });

                    // Show warnings for unhealthy services
                    const so = (s: { status?: string } | string) => (typeof s === 'object' ? s?.status : s) ?? '';
                    if (so(health.services.ollama) === 'unhealthy') {
                        toast.warning('Ollama nem elérhető', {
                            description: 'Az Ollama service nem fut. Indítsd el: ollama serve',
                        });
                    }
                    if (so(health.services.anythingllm) === 'unhealthy') {
                        toast.warning('AnythingLLM nem elérhető', {
                            description: 'Az AnythingLLM service nem érhető el.',
                        });
                    }
                }

                // Load agents as tools
                const agents = await api.getAgents();
                if (mounted) {
                    const agentTools = agents.map(agent => ({
                        id: `agent-${agent.name.toLowerCase()}`,
                        name: agent.name,
                        description: agent.description,
                        enabled: true,
                        category: 'server' as const,
                        parameters: [
                            { name: 'task', type: 'string', required: true },
                            { name: 'context', type: 'object', required: false }
                        ]
                    }));
                    setAgentTools(agentTools);
                }

                // Load additional tools
                const tools = await api.getTools();
                if (mounted && tools.length > 0) {
                    const toolsFormatted = tools.map((tool: any) => ({
                        id: tool.id || `tool-${tool.name}`,
                        name: tool.name,
                        description: tool.description || '',
                        enabled: tool.enabled !== false,
                        category: tool.category || 'custom' as const,
                        parameters: tool.parameters || []
                    }));
                    setAgentTools(prev => [...prev, ...toolsFormatted]);
                }

            } catch (error: any) {
                console.error('Failed to initialize dashboard data:', error);
                if (mounted) {
                    setConnected(false);
                    toast.error('Kapcsolódási hiba', {
                        description: 'Nem sikerült kapcsolódni a szerverhez.'
                    });
                }
            }
        }

        initializeData();

        return () => {
            mounted = false;
        };
    }, [setAgentTools, setServerState, setConnected]);
}

export function useOllamaModels() {
    const [models, setModels] = useState<api.OllamaModel[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        let mounted = true;

        async function loadModels() {
            try {
                const data = await api.getOllamaModels();
                if (mounted) {
                    setModels(data);
                }
            } catch (error) {
                console.warn('Failed to load Ollama models:', error);
            } finally {
                if (mounted) {
                    setLoading(false);
                }
            }
        }

        loadModels();

        return () => {
            mounted = false;
        };
    }, []);

    return { models, loading };
}

export function useAnythingLLMWorkspaces() {
    const [workspaces, setWorkspaces] = useState<api.Workspace[]>([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        let mounted = true;

        async function loadWorkspaces() {
            try {
                const data = await api.getAnythingLLMWorkspaces();
                if (mounted) {
                    setWorkspaces(data);
                }
            } catch (error) {
                console.warn('Failed to load AnythingLLM workspaces:', error);
            } finally {
                if (mounted) {
                    setLoading(false);
                }
            }
        }

        loadWorkspaces();

        return () => {
            mounted = false;
        };
    }, []);

    return { workspaces, loading };
}

import { useEffect } from 'react'
import { io, Socket } from 'socket.io-client'
import { useMcpStore } from '@/lib/mcpStore'
import { LogEntry, ServerMetrics, AgentTool, AgentToolParameter, ExecutionPlan } from '@/lib/types'

const BACKEND_URL = window.location.hostname === 'localhost' ? 'http://localhost:3000' : window.location.origin;
let socket: Socket | null = null;

export function useMCP() {
  const {
    isConnected,
    setConnected,
    addLog,
    setServerState,
    setMetrics,
    setAgentTools,
    setCurrentPlan,
    updatePlanStep,
    setMcpServers
  } = useMcpStore()

  useEffect(() => {
    if (!socket) {
      socket = io(BACKEND_URL)

      socket.on('connect', () => {
        setConnected(true)
        setServerState({ status: 'running' })
        useMcpStore.getState().addLog({
          id: `log-${Date.now()}`,
          timestamp: new Date().toISOString(),
          level: 'info',
          message: 'Csatlakozva a Core szerverhez',
          source: 'dashboard'
        })
      })

      socket.on('disconnect', () => {
        setConnected(false)
        setServerState({ status: 'stopped' })
      })

      // Listen for real logs from backend
      socket.on('system_log', (log: LogEntry) => {
        useMcpStore.getState().addLog(log)
      })

      // Listen for MCP servers status
      socket.on('mcp_servers_status', (servers: any[]) => {
        useMcpStore.getState().setMcpServers(servers)
      })

      // Streaming support
      socket.on('bot_message_start', (data: { isUser: boolean }) => {
        useMcpStore.getState().addChatMessage({
          id: `msg-${Date.now()}`,
          role: data.isUser ? 'user' : 'assistant',
          content: '',
          timestamp: new Date().toISOString(),
          isStreaming: true
        });
      });

      socket.on('bot_message_chunk', (data: { text: string }) => {
        useMcpStore.getState().appendChunkToLastMessage(data.text);
      });

      socket.on('bot_message_end', () => {
        useMcpStore.getState().setLastMessageStreaming(false);
      });

      // Listen for metrics
      socket.on('metrics_update', (metrics: ServerMetrics) => {
        useMcpStore.getState().setMetrics(metrics)
      })

      // Listen for Plan events
      socket.on('plan_created', (plan: ExecutionPlan) => {
        useMcpStore.getState().setCurrentPlan(plan)
        useMcpStore.getState().addChatMessage({
          id: `plan-${Date.now()}`,
          role: 'system',
          content: `🧭 Terv készült: ${plan.task} (${plan.steps.length} lépés)`,
          timestamp: new Date().toISOString(),
          isStreaming: false
        })
      })

      socket.on('plan_step_update', (step: any) => {
        useMcpStore.getState().updatePlanStep(step)
        const statusLabel = step.status === 'running'
          ? '▶'
          : step.status === 'completed'
            ? '✔'
            : step.status === 'failed'
              ? '✖'
              : '•'
        const resultSnippet = step.result
          ? `\n${step.result.toString().substring(0, 160)}`
          : ''
        useMcpStore.getState().addChatMessage({
          id: `step-${step.id}-${Date.now()}`,
          role: 'system',
          content: `${statusLabel} [${step.agent}] ${step.description}${resultSnippet}`,
          timestamp: new Date().toISOString(),
          isStreaming: false
        })
      })

      socket.on('agent_update', (agents: any[]) => {
        console.log('Agents updated:', agents);
      });

      // Listen for tool updates and adapt Schema
      socket.on('tools_update', (tools: any[]) => {
        const frontendTools: AgentTool[] = tools.map((t) => {
          const schema = t.inputSchema || {};
          const params: AgentToolParameter[] = [];

          if (schema.properties) {
            Object.keys(schema.properties).forEach(key => {
              const prop = schema.properties[key];
              params.push({
                name: key,
                type: prop.type || 'string',
                description: prop.description || '',
                required: (schema.required || []).includes(key)
              });
            });
          }

          return {
            id: t.name,
            name: t.name,
            description: t.description,
            enabled: true,
            parameters: params,
            category: 'server',
            createdAt: new Date().toISOString()
          };
        });
        useMcpStore.getState().setAgentTools(frontendTools)
      })

      socket.on('tool_result', (data) => {
        const fullResult = JSON.stringify(data.result, null, 2)
        useMcpStore.getState().addChatMessage({
          id: `tool-${data.name}-${Date.now()}`,
          role: 'system',
          content: `🛠️ Tool eredmény: ${data.name}\n${fullResult}`,
          timestamp: new Date().toISOString(),
          isStreaming: false
        })
      });

      socket.on('tool_error', (data) => {
        useMcpStore.getState().addChatMessage({
          id: `tool-${data.name}-err-${Date.now()}`,
          role: 'system',
          content: `⚠️ Tool hiba: ${data.name}\n${data.error}`,
          timestamp: new Date().toISOString(),
          isStreaming: false
        })
      });
    }

    return () => {
      // In a singleton pattern, we might not want to disconnect on every unmount
      // or we handle it differently. For now, keep it alive.
    }
  }, [])

  const sendMessage = (text: string, tools?: string[], model?: string, provider?: string) => {
    if (socket) {
      socket.emit('user_message', { text, tools, model, provider })
    }
  }

  const runTool = (name: string, args: any) => {
    if (socket) {
      const id = `req-${Date.now()}`;
      socket.emit('run_tool', { name, args, id });
      return id;
    }
    return null;
  }

  const startMcpServer = (name: string) => {
    if (socket) {
      socket.emit('mcp_server:start', name);
    }
  }

  const stopMcpServer = (name: string) => {
    if (socket) {
      socket.emit('mcp_server:stop', name);
    }
  }

  return {
    sendMessage,
    runTool,
    startMcpServer,
    stopMcpServer,
    isConnected
  }
}

import { renderHook, act, waitFor } from '@testing-library/react';
import { useSystemSignal } from './useSystemSignal';
import { useSystemSignalStore } from '../store/systemSignalStore';
import { io as mockedIo, Socket as MockSocket } from 'socket.io-client';
import * as apiService from '../lib/apiService';

// Mock socket.io-client
vi.mock('socket.io-client', () => {
  const mockSocket = {
    on: vi.fn(),
    off: vi.fn(),
    emit: vi.fn(),
    disconnect: vi.fn(),
    connected: false,
    io: { on: vi.fn(), off: vi.fn() }, // Mock for manager events
  };
  return {
    io: vi.fn(() => mockSocket),
  };
});

// Mock apiService
vi.mock('../lib/apiService', () => ({
  getTasks: vi.fn(() => Promise.resolve({ tasks: [], total: 0, limit: 0, offset: 0 })),
  getTaskStats: vi.fn(() => Promise.resolve({ total: 0, successCount: 0, errorCount: 0, pendingCount: 0, runningCount: 0, cancelledCount: 0, successRate: 0, avgDurationMs: 0, failedByAgent: [] })),
  checkHealth: vi.fn(() => Promise.resolve({ status: 'HEALTHY', timestamp: '', services: {} })),
  getDeveloperMetrics: vi.fn(() => Promise.resolve({ builds: {}, tests: {}, tasks: {}, ai: {}, history: [] })),
}));

const mockSocket = mockedIo() as MockSocket;

describe('useSystemSignal', () => {
  const initialStoreState = useSystemSignalStore.getState();

  beforeEach(() => {
    // Reset Zustand store to initial state before each test
    useSystemSignalStore.setState(initialStoreState, true);
    vi.clearAllMocks();
    vi.useFakeTimers();
  });

  afterEach(() => {
    vi.runOnlyPendingTimers();
    vi.useRealTimers();
  });

  it('should initialize with default state', () => {
    const { result } = renderHook(() => useSystemSignal());

    expect(result.current.isConnected).toBe(false);
    expect(result.current.logs).toEqual([]);
    expect(result.current.tasks).toEqual([]);
    expect(result.current.healthStatus).toBeNull();
    expect(result.current.error).toBeNull();
    expect(result.current.isLoading).toBe(false);
  });

  it('should connect and disconnect WebSocket', async () => {
    renderHook(() => useSystemSignal());

    // Simulate socket connect
    act(() => {
      mockSocket.on.mock.calls.find((call) => call[0] === 'connect')[1]();
    });
    await waitFor(() => expect(useSystemSignalStore.getState().isConnected).toBe(true));
    expect(useSystemSignalStore.getState().logs[0].message).toContain('Socket csatlakozva');

    // Simulate socket disconnect
    act(() => {
      mockSocket.on.mock.calls.find((call) => call[0] === 'disconnect')[1]('client disconnect');
