/**
 * useTTS Hook
 *
 * React hook for Text-to-Speech with Brunella's Nova voice
 */

import { useState, useCallback } from 'react';
import { toast } from 'sonner';

export type VoiceOption = 'alloy' | 'echo' | 'fable' | 'onyx' | 'nova' | 'shimmer';

export interface TTSOptions {
  voice?: VoiceOption;
  autoPlay?: boolean;
}

export function useTTS() {
  const [isSpeaking, setIsSpeaking] = useState(false);
  const [currentAudio, setCurrentAudio] = useState<HTMLAudioElement | null>(null);

  /**
   * Stop current speech playback
   */
  const stop = useCallback(() => {
    if (currentAudio) {
      currentAudio.pause();
      currentAudio.currentTime = 0;
      setCurrentAudio(null);
      setIsSpeaking(false);
    }
  }, [currentAudio]);

  /**
   * Speak text using OpenAI TTS API (Nova voice)
   *
   * @param text - Text to speak
   * @param options - TTS options
   */
  const speak = useCallback(
    async (text: string, options: TTSOptions = {}) => {
      const { voice = 'nova', autoPlay = true } = options;

      // Stop any currently playing audio
      if (currentAudio) {
        stop();
      }

      if (!text || text.trim().length === 0) {
        toast.error('Nincs mit mondani');
        return;
      }

      setIsSpeaking(true);

      try {
        // Call backend TTS API
        const response = await fetch('http://localhost:3000/api/tts', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            text: text.trim(),
            voice,
            model: 'tts-1',
            speed: 1.0,
          }),
        });

        if (!response.ok) {
          const errorData = await response.json().catch(() => ({}));
          throw new Error(errorData.error || `TTS failed: ${response.status}`);
        }

        // Convert response to audio blob
        const audioBlob = await response.blob();
        const audioUrl = URL.createObjectURL(audioBlob);

        // Create and play audio
        const audio = new Audio(audioUrl);
        setCurrentAudio(audio);

        audio.onended = () => {
          URL.revokeObjectURL(audioUrl);
          setCurrentAudio(null);
          setIsSpeaking(false);
        };

        audio.onerror = () => {
          URL.revokeObjectURL(audioUrl);
          setCurrentAudio(null);
          setIsSpeaking(false);
          toast.error('Hanglejátszási hiba');
        };

        if (autoPlay) {
          await audio.play();
          toast.success(`🎙️ Brunella beszél...`, {
            description: `Hang: ${voice === 'nova' ? 'Nova (alapértelmezett)' : voice}`,
          });
        }

        return audio;
      } catch (error: any) {
        console.error('TTS error:', error);
        setIsSpeaking(false);
        toast.error('TTS hiba', {
          description: error.message || 'Nem sikerült a hangot generálni',
        });
        throw error;
      }
    },
    [currentAudio, stop]
  );

  return {
    speak,
    stop,
    isSpeaking,
  };
}

/**
 * Agent Response Formatter
 * Átalakítja az ügynökök JSON válaszait olvasható magyar nyelvre
 */

interface AgentResponse {
  status?: string;
  data?: any;
  error?: string;
  success?: boolean;
  [key: string]: any;
}

export function formatAgentResponse(response: any, agentName?: string): string {
  if (typeof response === 'string') return response;

  try {
    const data = response as AgentResponse;

    // Hiba formázás
    if (data.status === 'error' || data.error) {
      return `❌ Hiba: ${data.error || 'Ismeretlen hiba történt'}`;
    }

    // Health check formázás (Evaluator)
    if (data.data?.status && data.data?.components) {
      return formatHealthCheck(data.data);
    }

    // Általános success válasz
    if (data.status === 'success' && data.data) {
      return formatSuccessData(data.data, agentName);
    }

    // Delegated válasz (Orchestrator)
    if (data.status === 'delegated') {
      return `🔄 Feladat delegálva → ${data.delegatedTo}${data.reason ? `\n   Indok: ${data.reason}` : ''}`;
    }

    // Ha nincs speciális formázás, próbáljuk emberi nyelvre fordítani
    return formatGenericResponse(data);

  } catch (e) {
    return JSON.stringify(response, null, 2);
  }
}

function formatHealthCheck(healthData: any): string {
  const statusIcon = healthData.status === 'HEALTHY' ? '✅' : '⚠️';
  let result = `${statusIcon} Rendszer állapot: ${translateStatus(healthData.status)}\n\n`;

  if (healthData.components) {
    result += '📊 Komponensek:\n';
    for (const [name, info] of Object.entries(healthData.components as Record<string, any>)) {
      const componentStatus = info.status === 'healthy' ? '🟢' : '🔴';
      const latency = info.latencyMs ? ` (${info.latencyMs}ms)` : '';
      result += `   ${componentStatus} ${name}: ${translateStatus(info.status)}${latency}\n`;
    }
  }

  if (healthData.recommendation) {
    result += `\n💡 Javaslat: ${translateRecommendation(healthData.recommendation)}`;
  }

  return result;
}

function formatSuccessData(data: any, agentName?: string): string {
  if (typeof data === 'string') {
    return `✅ ${data}`;
  }

  if (Array.isArray(data)) {
    return `✅ Sikeresen lekérve (${data.length} elem)\n${data.map((item, i) => `   ${i + 1}. ${JSON.stringify(item)}`).join('\n')}`;
  }

  if (typeof data === 'object' && data !== null) {
    let result = '✅ Művelet sikeres:\n';
    for (const [key, value] of Object.entries(data)) {
      result += `   • ${translateKey(key)}: ${formatValue(value)}\n`;
    }
    return result;
  }

  return `✅ ${data}`;
}

function formatGenericResponse(data: AgentResponse): string {
  let result = '';

  if (data.success === true) {
    result += '✅ Művelet sikeres\n';
  } else if (data.success === false) {
    result += '❌ Művelet sikertelen\n';
  }

  const excludeKeys = ['status', 'success', 'data'];
  const entries = Object.entries(data).filter(([key]) => !excludeKeys.includes(key));

  if (entries.length > 0) {
    for (const [key, value] of entries) {
      result += `   • ${translateKey(key)}: ${formatValue(value)}\n`;
    }
  }

  return result || JSON.stringify(data, null, 2);
}

function translateStatus(status: string): string {
  const statusMap: Record<string, string> = {
    'HEALTHY': 'Egészséges',
    'healthy': 'működik',
    'DEGRADED': 'Korlátozott',
    'UNHEALTHY': 'Hibás',
    'idle': 'tétlen',
    'working': 'dolgozik',
    'error': 'hiba',
    'success': 'sikeres',
    'failure': 'sikertelen'
  };
  return statusMap[status] || status;
}

function translateRecommendation(text: string): string {
  const translations: Record<string, string> = {
    'System is nominal.': 'A rendszer normálisan működik.',
    'All systems operational.': 'Minden rendszer működőképes.',
    'Check logs for details.': 'Ellenőrizd a naplókat a részletekért.'
  };
  return translations[text] || text;
}

function translateKey(key: string): string {
  const keyMap: Record<string, string> = {
    'message': 'üzenet',
    'result': 'eredmény',
    'output': 'kimenet',
    'code': 'kód',
    'description': 'leírás',
    'timestamp': 'időbélyeg',
    'duration': 'időtartam',
    'delegatedTo': 'delegálva',
    'reason': 'indok',
    'taskId': 'feladat azonosító',
    'agentName': 'ügynök neve',
    'status': 'állapot',
    'components': 'komponensek',
    'latencyMs': 'késleltetés (ms)',
    'recommendation': 'javaslat'
  };
  return keyMap[key] || key;
}

function formatValue(value: any): string {
  if (value === null || value === undefined) return '—';
  if (typeof value === 'boolean') return value ? '✓ Igen' : '✗ Nem';
  if (typeof value === 'number') return value.toString();
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return `[${value.length} elem]`;
  if (typeof value === 'object') return JSON.stringify(value);
  return String(value);
}

/**
 * API Service for Dashboard - Backend Communication
 * Centralized API calls to the MCP Brunella Core backend
 */

import { AgentStatusType, TaskItem } from '../types/dashboard.js';

export const API_BASE = ""; // Same origin
const DEFAULT_TIMEOUT_MS = 30000; // 30 seconds default timeout
const LONG_TIMEOUT_MS = 120000; // 2 minutes for LLM calls

/** Fetch with timeout support */
export async function fetchWithTimeout(
  url: string,
  options: RequestInit = {},
  timeoutMs: number = DEFAULT_TIMEOUT_MS,
): Promise<Response> {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      ...options,
      signal: controller.signal,
    });
    return response;
  } catch (error: any) {
    if (error.name === "AbortError") {
      throw new Error(`Időtúllépés (${timeoutMs / 1000}s)`);
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
}

/** Biztonságos JSON parse – üres vagy hibás válasz kezelése */
export async function safeJson<T>(response: Response): Promise<T> {
  const text = await response.text();
  if (!text || text.trim().length === 0) {
    throw new Error(
      response.ok
        ? "Üres válasz"
        : `HTTP ${response.status}: ${response.statusText}`,
    );
  }
  try {
    return JSON.parse(text) as T;
  } catch {
    throw new Error(`Érvénytelen válasz: ${text.slice(0, 100)}...`);
  }
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null;
}

function getErrorMessage(value: unknown): string | undefined {
  if (!isRecord(value)) return undefined;
  return typeof value.error === "string" ? value.error : undefined;
}

function isCloudflareTaskResponse(
  value: unknown,
): value is CloudflareTaskResponse {
  if (!isRecord(value)) return false;
  return (
    typeof value.success === "boolean" &&
    typeof value.taskId === "string" &&
    typeof value.type === "string" &&
    typeof value.message === "string"
  );
}

function isCloudflareChatResponse(
  value: unknown,
): value is CloudflareChatResponse {
  if (!isRecord(value)) return false;
  return (
    typeof value.success === "boolean" &&
    typeof value.message === "string" &&
    (value.endpoint === undefined || typeof value.endpoint === "string")
  );
}

function isCloudflareStatus(value: unknown): value is CloudflareStatus {
  if (!isRecord(value)) return false;
  if (!isRecord(value.status)) return false;
  return (
    typeof value.status.enabled === "boolean" &&
    typeof value.status.healthy === "boolean"
  );
}

