import { create } from 'zustand';
import { BusinessJob } from '../types/dashboard.js';
import { apiService } from './apiService.js';

interface BusinessStore {
  jobs: BusinessJob[];
  isLoading: boolean;
  error: string | null;
  fetchJobs: (type?: string) => Promise<void>;
  createJob: (type: string, query: string, metadata?: any) => Promise<string | null>;
  updateJobStatus: (id: string, status: BusinessJob['status'], results?: any) => void;
}

export const useBusinessStore = create<BusinessStore>((set, get) => ({
  jobs: [],
  isLoading: false,
  error: null,

  fetchJobs: async (type?: string) => {
    set({ isLoading: true, error: null });
    try {
      // Assuming apiService.getBusinessJobs exists or using generic fetch
      const response = await fetch(`/api/v1/business-jobs${type ? `?type=${type}` : ''}`);
      const data = await response.json();
      if (data.success) {
        set({ jobs: data.jobs, isLoading: false });
      } else {
        set({ error: data.error, isLoading: false });
      }
    } catch (err: any) {
      set({ error: err.message, isLoading: false });
    }
  },

  createJob: async (type: string, query: string, extraParams?: any) => {
    set({ isLoading: true, error: null });
    try {
      const response = await fetch('/api/v1/business-jobs', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ type, query, ...extraParams })
      });
      const data = await response.json();
      if (data.success) {
        await get().fetchJobs(type);
        set({ isLoading: false });
        return data.jobId;
      } else {
        set({ error: data.error, isLoading: false });
        return null;
      }
    } catch (err: any) {
      set({ error: err.message, isLoading: false });
      return null;
    }
  },

  updateJobStatus: (id: string, status: BusinessJob['status'], results?: any) => {
    set((state) => ({
      jobs: state.jobs.map((job) => 
        job.id === id 
          ? { ...job, status, results_json: results ? JSON.stringify(results) : job.results_json } 
          : job
      )
    }));
  }
}));

/**
 * Copilot CLI Bridge Provider
 *
 * Sends chat messages to the BAS backend which routes them
 * through the Bifrost Gateway "copilot" provider (file-bridge).
 * The Copilot CLI picks up request files, processes them, and writes responses.
 */
import type { ChatProvider, ChatSendInput, ChatSendOutput } from "../types";
import { MasterOrchestratorProvider } from "./masterOrchestratorProvider";

// Egyszerű heurisztika: ha a promptban szerepel "agent", "orchestrate", "swarm", vagy több agent neve, multi-agent orchestration-t indítunk
function needsMultiAgentOrchestration(input: ChatSendInput): boolean {
  const text = input.text.toLowerCase();
  // Egyszerűbb trigger szavak
  if (text.includes("orchestrate") || text.includes("swarm") || text.includes("multi-agent") || text.includes("több ügynök")) return true;
  // Ha felsorolás van, vesszővel elválasztva legalább 2 agent név
  if ((text.match(/agent/gi) || []).length > 1) return true;
  return false;
}

export const copilotProvider: ChatProvider = {
  mode: "copilot",

  async send(input) {
    if (needsMultiAgentOrchestration(input)) {
      // Multi-agent orchestration delegálás a masterOrchestratorProvider-nek
      const master = new MasterOrchestratorProvider();
      return master.send(input);
    }
    // Single-agent (alapértelmezett)
    const response = await fetch("/api/paios/chat", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        message: input.text,
        provider: "copilot",
        model: "copilot-cli",
        systemPrompt: input.conversationPrompt,
        history: input.history.map((m) => ({
          role: m.role,
          content: m.content,
        })),
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`Copilot bridge error: ${response.status} - ${errorText}`);
    }

    const data = (await response.json()) as {
      message?: string;
      response?: string;
      error?: string;
    };

    if (data.error) {
      throw new Error(data.error);
    }

    return {
      message: data.message || data.response || "No response from Copilot CLI",
      executedBy: "copilot-cli",
    };
  },
};

import { ChatProvider, ChatMode, ChatSendInput, ChatSendOutput } from "../types";
import { analyzeIntent } from "@/../../src/core/intentAnalyzer"; // Adjust path if needed
import * as api from "@/lib/apiService";

/**
 * Master Orchestrator Provider
 * Routes requests between Local Orchestrator and Cloudflare Edge Orchestrator
 * based on intent analysis.
 */
export class MasterOrchestratorProvider implements ChatProvider {
  readonly mode: ChatMode = "master_orchestrator";

  async send(args: ChatSendInput): Promise<ChatSendOutput> {
    const { text } = args;
    
    // 1. Analyze Intent
    const analysis = analyzeIntent(text);
    
    // 2. Delegate to correct target
    if (analysis.target === "edge") {
      try {
        const result = await api.submitCloudflareTask(text, { source: "master_orchestrator" });
        return {
          message: `[Edge] Feladat beküldve a Cloudflare orkesztrátornak (ID: ${result.taskId}).\n\nIndoklás: ${analysis.reasoning}`,
          executedBy: "CEAN Orchestrator",
          thoughts: analysis.reasoning,
          contextUsed: ["Cloudflare Edge Network"]
        };
      } catch (e: any) {
        return {
          message: `⚠️ Hiba az Edge delegálás során: ${e.message}. Megpróbálom helyben végrehajtani...`,
          executedBy: "System Fallback"
        };
      }
    }

    // 3. Default to Local Orchestrator
    try {
      const response = await api.executeAgent("orchestrator", text);
      return {
        message: response.data?.message || "A helyi orkesztrátor megkezdte a feladat végrehajtását.",
        executedBy: "Local Orchestrator",
        thoughts: analysis.reasoning,
        contextUsed: ["Local Workspace"]
      };
    } catch (e: any) {
      throw new Error(`Helyi orkesztrációs hiba: ${e.message}`);
    }
  }
}

import { ExternalApiConfig } from './types'

export interface ApiExecutionResult {
  success: boolean
  data?: any
  error?: string
  statusCode?: number
  headers?: Record<string, string>
}

export class ExternalApiService {
  async executeApiCall(
    config: ExternalApiConfig,
    parameters: Record<string, any>
  ): Promise<ApiExecutionResult> {
    try {
      const url = this.interpolateString(config.url, parameters)
      const headers = this.buildHeaders(config)
      const body = config.bodyTemplate 
        ? this.interpolateString(config.bodyTemplate, parameters)
        : undefined

      const controller = new AbortController()
      const timeout = config.timeout || 30000
      const timeoutId = setTimeout(() => controller.abort(), timeout)

      try {
        const response = await fetch(url, {
          method: config.method,
          headers,
          body: body && config.method !== 'GET' ? body : undefined,
          signal: controller.signal,
        })

        clearTimeout(timeoutId)

        const contentType = response.headers.get('content-type')
        let data: any

        if (contentType?.includes('application/json')) {
          data = await response.json()
        } else {
          data = await response.text()
        }

        if (!response.ok) {
          return {
            success: false,
            error: `API hiba: ${response.status} ${response.statusText}`,
            statusCode: response.status,
            data,
          }
        }

        const mappedData = config.responseMapping
          ? this.mapResponse(data, config.responseMapping)
          : data

        return {
          success: true,
          data: mappedData,
          statusCode: response.status,
          headers: Object.fromEntries(response.headers.entries()),
        }
      } catch (fetchError) {
        clearTimeout(timeoutId)
        
        if (fetchError instanceof Error && fetchError.name === 'AbortError') {
          return {
            success: false,
            error: `API timeout (${timeout}ms túllépve)`,
          }
        }
        
        throw fetchError
      }
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Ismeretlen API hiba',
      }
    }
  }

  private buildHeaders(config: ExternalApiConfig): Record<string, string> {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      ...config.headers,
    }

    if (config.authType && config.authValue) {
      switch (config.authType) {
        case 'bearer':
          headers['Authorization'] = `Bearer ${config.authValue}`
          break
        case 'apikey':
          headers['X-API-Key'] = config.authValue
          break
        case 'basic':
          headers['Authorization'] = `Basic ${config.authValue}`
          break
      }
    }

    return headers
  }

  private interpolateString(template: string, parameters: Record<string, any>): string {
    return template.replace(/\{\{(\w+)\}\}/g, (match, key) => {
      return parameters[key] !== undefined ? String(parameters[key]) : match
    })
  }

  private mapResponse(data: any, mapping: string): any {
    try {
      const paths = mapping.split('.')
      let result = data

      for (const path of paths) {
        if (result === null || result === undefined) {
          return null
        }
        result = result[path]
      }

      return result
    } catch (error) {
      return data
    }
  }

  async validateApiConfig(config: ExternalApiConfig): Promise<{ valid: boolean; error?: string }> {
    try {
      new URL(config.url)
    } catch {
      return { valid: false, error: 'Érvénytelen URL formátum' }
    }

    if (!['GET', 'POST', 'PUT', 'DELETE', 'PATCH'].includes(config.method)) {
      return { valid: false, error: 'Érvénytelen HTTP metódus' }
    }

    if (config.bodyTemplate && config.method === 'GET') {
      return { valid: false, error: 'GET kérés nem tartalmazhat body-t' }
    }

    return { valid: true }
  }
}

