/**
 * Frontend Logger Wrapper
 * Provides console-based logging for dashboard components
 * (Backend logger.ts is Node.js-only and unavailable in browser)
 */

const LOG_COLORS = {
  INFO: '#0ea5e9',    // cyan
  ERROR: '#ef4444',   // red
  WARN: '#f59e0b',    // amber
  DEBUG: '#8b5cf6',   // purple
};

function formatTime(): string {
  return new Date().toLocaleTimeString('hu-HU', {
    hour: '2-digit',
    minute: '2-digit',
    second: '2-digit',
    fractionalSecondDigits: 3,
  });
}

export function logInfo(component: string, message: string): void {
  console.log(
    `%c[${formatTime()}] ${component}: ${message}`,
    `color: ${LOG_COLORS.INFO}; font-weight: bold;`
  );
}

export function logError(component: string, message: string): void {
  console.error(
    `%c[${formatTime()}] ❌ ${component}: ${message}`,
    `color: ${LOG_COLORS.ERROR}; font-weight: bold;`
  );
}

export function logWarn(component: string, message: string): void {
  console.warn(
    `%c[${formatTime()}] ⚠️ ${component}: ${message}`,
    `color: ${LOG_COLORS.WARN}; font-weight: bold;`
  );
}

export function logDebug(component: string, message: string): void {
  if (process.env.NODE_ENV === 'development') {
    console.debug(
      `%c[${formatTime()}] 🐛 ${component}: ${message}`,
      `color: ${LOG_COLORS.DEBUG}; font-weight: bold;`
    );
  }
}

import { BookkeepingTransaction, BankTransactionData, NavInvoiceData } from '../types/bookkeeping.d.js';
import { logError } from '../utils/logger.js';
import { Database } from 'better-sqlite3';
let db: Database | null = null; // better-sqlite3 Database instance

export function initDB(dbPath: string = 'data/bookkeeping.db') {
    try {
        const Database = require('better-sqlite3');
        db = new Database(dbPath);
        (db as any).exec(`
            CREATE TABLE IF NOT EXISTS transactions (
                id TEXT PRIMARY KEY,
                source TEXT NOT NULL,
                data TEXT NOT NULL,
                status TEXT NOT NULL,
                matchedInvoice TEXT
            )
        `);
    } catch (error) {
        logError("bookkeeping_db", "Failed to initialize database:", error);
        throw error;
    }
}

export function saveTransaction(tx: BookkeepingTransaction) {
    try {
        if (!db) throw new Error('Database not initialized');
        const stmt = db.prepare('INSERT OR REPLACE INTO transactions (id, source, data, status, matchedInvoice) VALUES (?, ?, ?, ?, ?)');
        stmt.run(tx.id, tx.source, JSON.stringify(tx.data), tx.status, tx.matchedInvoice || null);
    } catch (error) {
        logError("bookkeeping_db", `Failed to save transaction: ${tx.id}`, error);
        throw error;
    }
}

export function getTransaction(id: string): BookkeepingTransaction | null {
    try {
        if (!db) throw new Error('Database not initialized');
        const stmt = (db as any).prepare('SELECT * FROM transactions WHERE id = ?');
        const row: any = stmt.get(id);
        if (!row) return null;
        return {
            id: row.id,
            source: row.source,
            data: JSON.parse(row.data) as (BankTransactionData | NavInvoiceData),
            status: row.status as BookkeepingTransaction['status'],
            matchedInvoice: row.matchedInvoice || undefined
        };
    } catch (error) {
        logError("bookkeeping_db", `Failed to get transaction: ${id}`, error);
        throw error;
    }
}

export function getPendingTransactions(source?: string): BookkeepingTransaction[] {
    try {
        if (!db) throw new Error('Database not initialized');
        let query = "SELECT * FROM transactions WHERE status = 'PENDING_MATCH'";
        const params: any[] = [];
        if (source) {
            query += ' AND source = ?';
            params.push(source);
        }
        const rows: any[] = (db as any).prepare(query).all(...params);
        return rows.map(row => ({
            id: row.id,
            source: row.source,
            data: JSON.parse(row.data) as (BankTransactionData | NavInvoiceData),
            status: row.status as BookkeepingTransaction['status'],
            matchedInvoice: row.matchedInvoice || undefined
        }));
    } catch (error) {
        logError("bookkeeping_db", "Failed to get pending transactions:", error);
        throw error;
    }
}

export function updateTransaction(id: string, updates: Partial<BookkeepingTransaction>) {
    try {
        if (!db) throw new Error('Database not initialized');
        const setClauses: string[] = [];
        const params: any[] = [];

        if (updates.status) {
            setClauses.push('status = ?');
            params.push(updates.status);
        }
        if (updates.matchedInvoice) {
            setClauses.push('matchedInvoice = ?');
            params.push(updates.matchedInvoice);
        }

        if (setClauses.length === 0) return; // Nothing to update

        const query = `UPDATE transactions SET ${setClauses.join(', ')} WHERE id = ?`;
        params.push(id);

        db.prepare(query).run(...params);
    } catch (error) {
        logError("bookkeeping_db", `Failed to update transaction: ${id}`, error);
        throw error;
    }
}

export function getAllTransactions(): BookkeepingTransaction[] {
    try {
        if (!db) throw new Error('Database not initialized');
        const rows: any[] = (db as any).prepare('SELECT * FROM transactions').all();
        return rows.map(row => ({
            id: row.id,
            source: row.source,
            data: JSON.parse(row.data) as (BankTransactionData | NavInvoiceData),
            status: row.status as BookkeepingTransaction['status'],
            matchedInvoice: row.matchedInvoice || undefined
        }));
    } catch (error) {
        logError("bookkeeping_db", "Failed to get all transactions:", error);
        throw error;
    }
}

// Main entry point for MCP Brunella Core
// This file must remain compatible with both Node.js and Cloudflare Workers environments.
// All Node.js-specific dependencies must be imported dynamically.

async function main() {
  // Conditional execution for Node.js environment
  if (
    typeof process !== "undefined" &&
    process.versions &&
    process.versions.node
  ) {
    // Dynamic imports to prevent bundling Node-native modules in Worker builds
    await import("dotenv/config");

    // Initialize OpenTelemetry tracing BEFORE other imports
    const { initOtelTracing } = await import("./utils/otelTracing.js");
    initOtelTracing();
    const { McpServer } =
      await import("@modelcontextprotocol/sdk/server/mcp.js");
    const { StdioServerTransport } =
      await import("@modelcontextprotocol/sdk/server/stdio.js");
    const { startWebServer } = await import("./server/web.js");
    const { registerAllTools } = await import("./server/registry.js");
    const { initializeAgentManager } = await import("./agents/AgentManager.js"); // agentManager removed from destructuring
    const { socketService } = await import("./server/SocketService.js");
    const { validateSecrets } = await import("./utils/validateSecrets.js");
    const { readFileSync } = await import("fs");

    // Read version from package.json
    const pkgVersion = (() => {
      try {
        const pkg = JSON.parse(readFileSync("package.json", "utf-8"));
        return typeof pkg.version === "string" ? pkg.version : "1.0.0";
      } catch {
        return "1.0.0";
      }
    })();

    // Create server instance
    const server = new McpServer({
      name: "mcp-brunella-core",
      version: pkgVersion,
    });

    validateSecrets();

    // Start web server first to initialize socketService and agentManager
    await startWebServer();
    const initializedAgentManager = initializeAgentManager(socketService); // Call the initializer and capture the returned instance

    // Register Tools - agentManager should now be initialized
    await registerAllTools(server);

    // Start Autonomous Worker Loop
    initializedAgentManager.startWorkerLoop();

    const transport = new StdioServerTransport();
    await server.connect(transport);
    console.error("MCP Brunella Core Server running on stdio");

    // Graceful shutdown handling
    const shutdown = async (signal: string) => {
      console.error(
        `\n[Shutdown] Received ${signal}, graceful shutdown initiated...`,
      );
      try {
        initializedAgentManager.stopWorkerLoop(); // Use the captured instance
        // Flush and shut down OpenTelemetry before exit
        const { shutdownOtelTracing } = await import("./utils/otelTracing.js");
        await shutdownOtelTracing();
        await server.close?.();
        console.error("[Shutdown] Cleanup complete.");
      } catch (e) {
        console.error("[Shutdown] Error during cleanup:", e);
      }
      process.exit(0);
    };

    process.on("SIGTERM", () => shutdown("SIGTERM"));
    process.on("SIGINT", () => shutdown("SIGINT"));
  } else {
    console.warn(
      "MCP Brunella Core: Non-Node.js environment detected. Skipping Node-specific initialization.",
    );
  }
}

main().catch((error: unknown) => {
  console.error("\n[FATAL ERROR] Server failed to start!");
  console.error("================================================");
  
  if (error instanceof Error) {
    console.error("Error Type: Error");
    console.error("Message:", error.message);
    console.error("Stack:", error.stack);
    console.error("Cause:", error.cause);
  } else if (typeof error === "string") {
    console.error("Error Type: String");
    console.error("Message:", error);
  } else if (typeof error === "object" && error !== null) {
    console.error("Error Type: Object");
    console.error("Keys:", Object.keys(error));
    console.error("Full object:", error);
    try {
      console.error("JSON:", JSON.stringify(error, null, 2));
    } catch (stringifyErr) {
      console.error("Could not stringify error:", stringifyErr instanceof Error ? stringifyErr.message : stringifyErr);
    }
  } else {
    console.error("Error Type: Other");
    console.error("Value:", error);
    console.error("Type:", typeof error);
  }
  
  console.error("================================================");
  console.error("\nTip: Check logs/ directory for more details");
  console.error("  - logs/error.log");
  console.error("  - logs/server.log");
  console.error("  - logs/health.log");
  
  if (typeof process !== "undefined" && process.exit) {
    process.exit(1);
  }
});

