/**
 * BrunellaKernel — Meta-level orchestration and system optimization
 * Phase 5: Adaptive Swarms & Workflow Intelligence
 *
 * The Kernel is the highest-level coordinator: it observes the entire
 * system (agents, mesh, swarms, flows) and makes meta-decisions about
 * optimization, healing, scaling, and resource allocation.
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn } from '../utils/logger.js';

export interface SystemSnapshot {
  timestamp: number;
  agents: { total: number; active: number; idle: number };
  mesh: { nodes: number; healthyNodes: number };
  swarms: { colonies: number; activeColonies: number };
  flows: { registered: number; avgDurationMs: number };
  cognition: { entries: number; avgConfidence: number };
  health: 'optimal' | 'good' | 'degraded' | 'critical';
}

export interface KernelDirective {
  id: string;
  type: 'optimize' | 'heal' | 'scale' | 'rebalance' | 'alert';
  target: string;           // what component to act on
  action: string;           // specific action description
  priority: 'low' | 'medium' | 'high' | 'critical';
  status: 'pending' | 'executing' | 'completed' | 'failed';
  createdAt: number;
  completedAt?: number;
  result?: string;
}

export interface KernelConfig {
  snapshotIntervalMs: number;
  autoOptimize: boolean;
  degradedThreshold: number;    // 0–1, ratio below which system is degraded
}

const DEFAULT_CONFIG: KernelConfig = {
  snapshotIntervalMs: 30_000,
  autoOptimize: true,
  degradedThreshold: 0.7,
};

export class BrunellaKernel extends EventEmitter {
  private config: KernelConfig;
  private snapshots: SystemSnapshot[] = [];
  private directives: KernelDirective[] = [];
  private directiveCounter = 0;
  private snapshotTimer: ReturnType<typeof setInterval> | null = null;
  private snapshotProvider: (() => SystemSnapshot) | null = null;

  constructor(config?: Partial<KernelConfig>) {
    super();
    this.config = { ...DEFAULT_CONFIG, ...config };
  }

  /** Set the snapshot provider function (injected by the system) */
  setSnapshotProvider(provider: () => SystemSnapshot): void {
    this.snapshotProvider = provider;
  }

  /** Start the kernel's observation loop */
  start(): void {
    if (this.snapshotProvider) {
      this.snapshotTimer = setInterval(() => {
        const snapshot = this.takeSnapshot();
        if (snapshot && this.config.autoOptimize) {
          this.evaluate(snapshot);
        }
      }, this.config.snapshotIntervalMs);
    }
    logInfo('BrunellaKernel', 'Kernel started (meta-orchestration active)');
    this.emit('kernel:started');
  }

  /** Stop the kernel */
  stop(): void {
    if (this.snapshotTimer) {
      clearInterval(this.snapshotTimer);
      this.snapshotTimer = null;
    }
    logInfo('BrunellaKernel', 'Kernel stopped');
    this.emit('kernel:stopped');
  }

  /** Take a system snapshot */
  takeSnapshot(): SystemSnapshot | null {
    if (!this.snapshotProvider) return null;

    const snapshot = this.snapshotProvider();
    this.snapshots.push(snapshot);

    // Keep only last 100 snapshots
    if (this.snapshots.length > 100) {
      this.snapshots.splice(0, this.snapshots.length - 100);
    }

    this.emit('snapshot', snapshot);
    return snapshot;
  }

  /** Evaluate a snapshot and generate directives */
  evaluate(snapshot: SystemSnapshot): KernelDirective[] {
    const newDirectives: KernelDirective[] = [];

    // Check mesh health
    if (snapshot.mesh.nodes > 0) {
      const healthRatio = snapshot.mesh.healthyNodes / snapshot.mesh.nodes;
      if (healthRatio < this.config.degradedThreshold) {
        newDirectives.push(this.createDirective(
          'heal', 'mesh', `Mesh health at ${(healthRatio * 100).toFixed(0)}% — trigger healing`, 'high'
        ));
      }
    }

    // Check agent utilization
    if (snapshot.agents.total > 0) {
      const idleRatio = snapshot.agents.idle / snapshot.agents.total;
      if (idleRatio > 0.8 && snapshot.swarms.activeColonies > 0) {
        newDirectives.push(this.createDirective(
          'rebalance', 'agents', `${(idleRatio * 100).toFixed(0)}% agents idle — suggest rebalance`, 'medium'
        ));
      }
    }

    // Check system health
    if (snapshot.health === 'critical') {
      newDirectives.push(this.createDirective(
        'alert', 'system', 'System in CRITICAL state — immediate attention required', 'critical'
      ));
    }

    for (const d of newDirectives) {
      this.directives.push(d);
      this.emit('directive', d);
    }

    return newDirectives;
  }

  /** Create a directive */
  createDirective(
    type: KernelDirective['type'],
    target: string,
    action: string,
    priority: KernelDirective['priority']
  ): KernelDirective {
    return {
      id: `kd-${++this.directiveCounter}-${Date.now()}`,
      type,
      target,
      action,
      priority,
      status: 'pending',
      createdAt: Date.now(),
    };
  }

  /** Complete a directive */
  completeDirective(directiveId: string, result?: string): boolean {
    const d = this.directives.find(d => d.id === directiveId);
    if (!d) return false;
    d.status = 'completed';
    d.completedAt = Date.now();
    d.result = result;
    this.emit('directive:completed', d);
    return true;
  }

  /** Get latest snapshot */
  getLatestSnapshot(): SystemSnapshot | null {
    return this.snapshots.length > 0 ? this.snapshots[this.snapshots.length - 1] : null;
  }

  /** Get snapshot history */
  getSnapshotHistory(limit = 10): SystemSnapshot[] {
    return this.snapshots.slice(-limit);
  }

  /** Get all directives */
  getDirectives(status?: KernelDirective['status']): KernelDirective[] {
    if (!status) return [...this.directives];
    return this.directives.filter(d => d.status === status);
  }

  /** Get kernel stats */
  getStats(): { snapshots: number; directives: number; pending: number; health: string } {
    const latest = this.getLatestSnapshot();
    return {
      snapshots: this.snapshots.length,
      directives: this.directives.length,
      pending: this.directives.filter(d => d.status === 'pending').length,
      health: latest?.health ?? 'unknown',
    };
  }
}

import fs from 'fs-extra';
import { parseISO, differenceInCalendarDays } from 'date-fns';
import { logInfo, logError } from '../utils/logger.js';

type BankTx = { date: string; amount: number; currency?: string; description?: string; raw?: Record<string, unknown> };
type Invoice = { id?: string; invoice_number?: string; gross?: number; net?: number; issueDate?: string; partner?: string; source?: string };

export async function parseBankCsv(csvPath: string): Promise<BankTx[]> {
  try {
    const txt = await fs.readFile(csvPath, 'utf-8');
    const lines = txt.split(/\r?\n/).map((l: string) => l.trim()).filter(Boolean);
    const rows: string[][] = [];
    for (const line of lines) {
      // naive CSV split (handles simple CSV without embedded commas)
      const parts = line.split(',').map((p: string) => p.replace(/^"|"$/g, '').trim());
      rows.push(parts);
    }
    // Try to detect header
    const header = rows[0].map((h: string) => h.toLowerCase());
    const idxDate = header.findIndex((h) => h.includes('date'));
    const idxAmount = header.findIndex((h) => h.includes('amount') || h.includes('price') || h.includes('sum'));
    const idxDesc = header.findIndex((h) => h.includes('description') || h.includes('desc') || h.includes('partner'));
    const txs: BankTx[] = [];
    for (let i = 1; i < rows.length; i++) {
      const row = rows[i];
      const date = idxDate >= 0 ? row[idxDate] : row[0];
      const amountStr = idxAmount >= 0 ? row[idxAmount] : row[1] ?? '0';
      const description = idxDesc >= 0 ? row[idxDesc] : row.slice(2).join(' ');
      const amount = Number(amountStr.replace(/[^0-9.-]/g, ''));
      txs.push({ date, amount, description, raw: { row } });
    }
    logInfo('matcher', `Parsed ${txs.length} bank transactions from ${csvPath}`);
    return txs;
  } catch (e) {
    logError('matcher', `parseBankCsv error: ${String(e)}`);
    return [];
  }
}

export function matchTransactionsToInvoices(txs: BankTx[], invoices: Invoice[], opts?: { dateToleranceDays?: number; amountTolerance?: number }) {
  const dateTol = opts?.dateToleranceDays ?? 3;
  const amtTol = opts?.amountTolerance ?? 0.5; // tolerance in currency
  const matches: Array<{ tx: BankTx; invoice?: Invoice; score: number }> = [];

  for (const tx of txs) {
    let best: { invoice?: Invoice; score: number } = { invoice: undefined, score: 0 };
    for (const inv of invoices) {
      let score = 0;
      // amount match (gross or net)
      if (typeof inv.gross === 'number' && Math.abs(inv.gross - tx.amount) <= amtTol) score += 60;
      if (typeof inv.net === 'number' && Math.abs(inv.net - tx.amount) <= amtTol) score += 50;
      // date proximity
      if (inv.issueDate) {
        try {
          const d1 = parseISO(String(inv.issueDate));
          const d2 = parseISO(String(tx.date));
          if (!isNaN(d1.getTime()) && !isNaN(d2.getTime())) {
            const dd = Math.abs(differenceInCalendarDays(d1, d2));
            if (dd <= dateTol) score += Math.max(0, 30 - dd * 8);
            // penalize if date is in future far beyond tolerance
            if (d1.getTime() - d2.getTime() > 1000 * 60 * 60 * 24 * 30) score -= 20;
          }
        } catch (err) { /* ignore parse errors */ }
      }
      // partner name in description
      if (inv.partner && tx.description && tx.description.toLowerCase().includes(String(inv.partner).toLowerCase())) score += 15;
      // invoice id in description
      if (inv.invoice_number && tx.description && tx.description.includes(String(inv.invoice_number))) score += 20;

      if (score > best.score) best = { invoice: inv, score };
    }
    matches.push({ tx, invoice: best.invoice, score: best.score });
  }
  // sort matches by score desc
  matches.sort((a, b) => b.score - a.score);
  return matches;
}

/**
 * TopologyAI — AI-driven mesh topology optimization
 * Phase 6: Evolutionary Collective Intelligence
 *
 * Analyzes the mesh graph, detects bottlenecks, single-points-of-failure,
 * and over/under-utilized nodes. Proposes topology changes to improve
 * resilience, latency, and throughput.
 */

import { EventEmitter } from 'events';
import { logInfo, logWarn } from '../utils/logger.js';

export interface TopologyNode {
  nodeId: string;
  region: string;
  capabilities: string[];
  connections: string[];          // connected node IDs
  load: number;                   // 0–1
  latencyMs: number;              // avg round-trip
  uptime: number;                 // 0–1 ratio
}

export interface TopologyProposal {
  id: string;
  type: 'add_link' | 'remove_link' | 'rebalance' | 'add_node' | 'isolate_node';
  sourceNodeId?: string;
  targetNodeId?: string;
  reason: string;
  expectedImprovement: string;
  priority: 'low' | 'medium' | 'high';
  status: 'proposed' | 'accepted' | 'applied' | 'rejected';
  createdAt: number;
}

export interface TopologyAnalysis {
  totalNodes: number;
  totalLinks: number;
  avgConnectivity: number;        // avg connections per node
  avgLoad: number;
  bottlenecks: string[];          // node IDs with very high load or critical position
  isolatedNodes: string[];        // nodes with 0 or 1 connections
  proposals: TopologyProposal[];
  timestamp: number;
}

export class TopologyAI extends EventEmitter {
  private nodes = new Map<string, TopologyNode>();
  private proposals: TopologyProposal[] = [];
  private proposalCounter = 0;

  /** Register or update a topology node */
  upsertNode(node: TopologyNode): void {
    this.nodes.set(node.nodeId, node);
  }

  /** Remove a node from topology */
  removeNode(nodeId: string): void {
    this.nodes.delete(nodeId);
    // Clean connections referencing removed node
    for (const n of this.nodes.values()) {
      n.connections = n.connections.filter(c => c !== nodeId);
    }
  }

  /** Run a full topology analysis and generate proposals */
  analyze(): TopologyAnalysis {
    const allNodes = Array.from(this.nodes.values());
    if (allNodes.length === 0) {
      return {
        totalNodes: 0, totalLinks: 0, avgConnectivity: 0, avgLoad: 0,
        bottlenecks: [], isolatedNodes: [], proposals: [], timestamp: Date.now(),
      };
    }

    const totalLinks = allNodes.reduce((s, n) => s + n.connections.length, 0) / 2;
    const avgConnectivity = allNodes.reduce((s, n) => s + n.connections.length, 0) / allNodes.length;
    const avgLoad = allNodes.reduce((s, n) => s + n.load, 0) / allNodes.length;

    // Detect bottlenecks: high load + many connections (critical hub)
    const bottlenecks = allNodes
      .filter(n => n.load > 0.8 || (n.connections.length > avgConnectivity * 2 && n.load > 0.5))
      .map(n => n.nodeId);

    // Detect isolated nodes
    const isolatedNodes = allNodes
      .filter(n => n.connections.length <= 1)
      .map(n => n.nodeId);

    const newProposals: TopologyProposal[] = [];

    // Propose links for isolated nodes
    for (const nodeId of isolatedNodes) {
      const node = this.nodes.get(nodeId)!;
      const bestPeer = this.findBestPeer(node, allNodes);
      if (bestPeer) {
        newProposals.push(this.createProposal(
          'add_link', nodeId, bestPeer.nodeId,
          `Node ${nodeId} has only ${node.connections.length} connection(s)`,
          'Improved resilience and redundancy',
          'high'
        ));
      }
    }

    // Propose rebalancing for bottlenecks
    for (const nodeId of bottlenecks) {
      newProposals.push(this.createProposal(
        'rebalance', nodeId, undefined,
        `Node ${nodeId} is overloaded (load=${this.nodes.get(nodeId)!.load.toFixed(2)})`,
        'Reduced load and improved latency',
        'medium'
      ));
    }

    // Store proposals
    for (const p of newProposals) {
      this.proposals.push(p);
      this.emit('proposal', p);
    }

    const analysis: TopologyAnalysis = {
      totalNodes: allNodes.length,
      totalLinks,
      avgConnectivity,
      avgLoad,
      bottlenecks,
      isolatedNodes,
      proposals: newProposals,
      timestamp: Date.now(),
    };

    this.emit('analysis:complete', analysis);
    logInfo('TopologyAI', `Analysis: ${allNodes.length} nodes, ${totalLinks} links, ${bottlenecks.length} bottlenecks, ${newProposals.length} proposals`);
    return analysis;
  }

  /** Accept a proposal */
  acceptProposal(proposalId: string): boolean {
    const p = this.proposals.find(p => p.id === proposalId);
    if (!p || p.status !== 'proposed') return false;
    p.status = 'accepted';
    this.emit('proposal:accepted', p);
    return true;
  }

  /** Apply a proposal (simulate topology change) */
  applyProposal(proposalId: string): boolean {
    const p = this.proposals.find(p => p.id === proposalId);
    if (!p || (p.status !== 'accepted' && p.status !== 'proposed')) return false;

    if (p.type === 'add_link' && p.sourceNodeId && p.targetNodeId) {
      const src = this.nodes.get(p.sourceNodeId);
      const tgt = this.nodes.get(p.targetNodeId);
      if (src && tgt) {
        if (!src.connections.includes(p.targetNodeId)) src.connections.push(p.targetNodeId);
        if (!tgt.connections.includes(p.sourceNodeId)) tgt.connections.push(p.sourceNodeId);
      }
    } else if (p.type === 'isolate_node' && p.sourceNodeId) {
      this.removeNode(p.sourceNodeId);
    }

    p.status = 'applied';
    this.emit('proposal:applied', p);
    logInfo('TopologyAI', `Proposal ${proposalId} applied: ${p.type}`);
    return true;
  }

  /** Get all proposals */
  getProposals(status?: TopologyProposal['status']): TopologyProposal[] {
    if (!status) return [...this.proposals];
    return this.proposals.filter(p => p.status === status);
  }

  /** Get a specific node */
  getNode(nodeId: string): TopologyNode | undefined {
    return this.nodes.get(nodeId);
  }

  /** List all nodes */
  listNodes(): TopologyNode[] {
    return Array.from(this.nodes.values());
  }

  /** Find the best peer to connect an isolated node to */
  private findBestPeer(node: TopologyNode, allNodes: TopologyNode[]): TopologyNode | undefined {
    return allNodes
      .filter(n => n.nodeId !== node.nodeId && !node.connections.includes(n.nodeId))
      .sort((a, b) => {
        // Prefer same region, low load, high uptime
        const regionA = a.region === node.region ? 1 : 0;
        const regionB = b.region === node.region ? 1 : 0;
        const scoreA = regionA * 0.4 + (1 - a.load) * 0.3 + a.uptime * 0.3;
        const scoreB = regionB * 0.4 + (1 - b.load) * 0.3 + b.uptime * 0.3;
        return scoreB - scoreA;
      })[0];
  }

  private createProposal(
    type: TopologyProposal['type'],
    sourceNodeId: string,
    targetNodeId: string | undefined,
    reason: string,
    expectedImprovement: string,
    priority: TopologyProposal['priority']
  ): TopologyProposal {
    return {
      id: `tp-${++this.proposalCounter}-${Date.now()}`,
      type,
      sourceNodeId,
      targetNodeId,
      reason,
      expectedImprovement,
      priority,
      status: 'proposed',
      createdAt: Date.now(),
    };
  }
}

