/**
 * Gold Protocol G6: Audit API Routes
 *
 * RULE-UI4: Routes in separate *Routes.ts files (clean separation)
 *
 * Endpoints:
 *   GET /api/audit/log    → AuditEntry[] (paginated)
 *   GET /api/audit/denied → AuditEntry[] (denied only)
 *   GET /api/audit/stats  → Audit statistics
 */

import { Router } from 'express';
import { getAuditLog, getDeniedEntries, getAuditStats, cleanupOldEntries } from '../core/auditLog.js';

export function createAuditRouter(): Router {
  const router = Router();

  /**
   * GET /api/audit/log
   * Paginated audit log (newest first)
   */
  router.get('/log', async (req, res) => {
    try {
      const limit = Math.min(parseInt(req.query.limit as string) || 50, 500);
      const offset = parseInt(req.query.offset as string) || 0;
      const entries = await getAuditLog(limit, offset);
      res.json({ entries, limit, offset });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * GET /api/audit/denied
   * Only denied entries (newest first)
   */
  router.get('/denied', async (req, res) => {
    try {
      const limit = Math.min(parseInt(req.query.limit as string) || 50, 500);
      const entries = await getDeniedEntries(limit);
      res.json({ entries });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * GET /api/audit/stats
   * Audit statistics (totals, by agent)
   */
  router.get('/stats', async (_req, res) => {
    try {
      const stats = await getAuditStats();
      res.json(stats);
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * POST /api/audit/cleanup
   * Manual trigger for retention cleanup
   */
  router.post('/cleanup', async (req, res) => {
    try {
      const days = parseInt(req.body?.retentionDays as string) || 30;
      const removed = await cleanupOldEntries(days);
      res.json({ removed, retentionDays: days });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  return router;
}

/**
 * Guardrails API Routes
 * Track: guardrails_evaluation_20260323 Phase 4
 *
 * Endpoints:
 *   GET /api/v1/guardrails/stats   → Guardrails statisztikák
 *   POST /api/v1/guardrails/redact → Szöveg redakció tesztelés
 */

import { Router } from 'express';
import { redactText } from '../security/redactor.js';

// In-memory counters (reset on restart — later: persist to SQLite)
const guardrailsCounters = {
  validationsPassed: 0,
  validationsFailed: 0,
  redactionsTriggered: 0,
  confidenceSum: 0,
  confidenceCount: 0,
};

/**
 * Növeli a validáció számlálót (BaseAgent middleware hívja).
 */
export function recordValidation(passed: boolean, confidence?: number): void {
  if (passed) {
    guardrailsCounters.validationsPassed++;
  } else {
    guardrailsCounters.validationsFailed++;
  }
  if (confidence !== undefined) {
    guardrailsCounters.confidenceSum += confidence;
    guardrailsCounters.confidenceCount++;
  }
}

/**
 * Növeli a redakció számlálót.
 */
export function recordRedaction(): void {
  guardrailsCounters.redactionsTriggered++;
}

export function createGuardrailsRouter(): Router {
  const router = Router();

  router.get('/stats', (_req, res) => {
    try {
      const avgConfidence = guardrailsCounters.confidenceCount > 0
        ? guardrailsCounters.confidenceSum / guardrailsCounters.confidenceCount
        : 0;

      res.json({
        validationsPassed: guardrailsCounters.validationsPassed,
        validationsFailed: guardrailsCounters.validationsFailed,
        avgConfidence: Math.round(avgConfidence * 100) / 100,
        redactionsTriggered: guardrailsCounters.redactionsTriggered,
        strictMode: process.env.GUARDRAILS_STRICT === 'true',
        confidenceThreshold: parseFloat(process.env.CONFIDENCE_THRESHOLD || '0.6'),
      });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  router.post('/redact', (req, res) => {
    try {
      const { text } = req.body;
      if (!text || typeof text !== 'string') {
        res.status(400).json({ error: 'text mező szükséges (string)' });
        return;
      }
      const result = redactText(text);
      res.json(result);
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  return router;
}

import { Server } from '@modelcontextprotocol/sdk/server/index.js';
import { StdioServerTransport } from '@modelcontextprotocol/sdk/server/stdio.js';
import {
  CallToolRequestSchema,
  ListToolsRequestSchema,
  Tool,
  TextContent
} from '@modelcontextprotocol/sdk/types.js';
import fs from 'fs';
import path from 'path';
import { glob } from 'glob';
import { getSafeZoneValidator } from '../security/safe_zone_validator.js';
import { logInfo, logError, logWarn } from '../utils/logger.js';

/**
 * MCP Filesystem Server
 *
 * Provides secure filesystem operations for AI agents via MCP protocol.
 * All operations are validated against Safe Zone configuration.
 */
export class MCPFilesystemServer {
  private server: Server;
  private validator: ReturnType<typeof getSafeZoneValidator>;

  constructor() {
    this.validator = getSafeZoneValidator();

    this.server = new Server(
      {
        name: 'brunella-mcp-filesystem',
        version: '1.0.0'
      },
      {
        capabilities: {
          tools: {}
        }
      }
    );

    this.setupHandlers();
    logInfo('MCPFilesystemServer', 'MCP server initialized');
  }

  /**
   * Setup MCP request handlers
   */
  private setupHandlers(): void {
    // List available tools
    this.server.setRequestHandler(ListToolsRequestSchema, async () => {
      logInfo('MCPFilesystemServer', 'Listing tools');
      return {
        tools: this.getTools()
      };
    });

    // Call tool
    this.server.setRequestHandler(CallToolRequestSchema, async (request) => {
      const { name, arguments: args } = request.params;
      logInfo('MCPFilesystemServer', `Calling tool: ${name}`);

      try {
        switch (name) {
          case 'read_file':
            return await this.handleReadFile(args);
          case 'write_file':
            return await this.handleWriteFile(args);
          case 'list_directory':
            return await this.handleListDirectory(args);
          case 'search_files':
            return await this.handleSearchFiles(args);
          default:
            throw new Error(`Unknown tool: ${name}`);
        }
      } catch (error: any) {
        logError('MCPFilesystemServer', `Tool ${name} failed: ${error.message}`);
        return {
          content: [
            {
              type: 'text',
              text: `Error: ${error.message}`
            } as TextContent
          ],
          isError: true
        };
      }
    });
  }

  /**
   * Get tool definitions
   */
  private getTools(): Tool[] {
    return [
      {
        name: 'read_file',
        description: 'Read file content from Safe Zone directories. Returns file content as text. Validates path against Safe Zone configuration and blacklist.',
        inputSchema: {
          type: 'object',
          properties: {
            path: {
              type: 'string',
              description: 'File path (must be within Safe Zone). Can be relative or absolute.'
            }
          },
          required: ['path']
        }
      },
      {
        name: 'write_file',
        description: 'Write content to file in Safe Zone. Creates file if it doesn\'t exist. Validates path, extension, and file size limits.',
        inputSchema: {
          type: 'object',
          properties: {
            path: {
              type: 'string',
              description: 'File path (must be within Safe Zone)'
            },
            content: {
              type: 'string',
              description: 'File content to write'
            },
            create_dirs: {
              type: 'boolean',
              description: 'Create parent directories if they don\'t exist (default: true)'
            }
          },
          required: ['path', 'content']
        }
      },
      {
        name: 'list_directory',
        description: 'List directory contents in Safe Zone. Returns array of file/directory names with metadata (type, size, modified time).',
        inputSchema: {
          type: 'object',
          properties: {
            path: {
              type: 'string',
              description: 'Directory path (must be within Safe Zone)'
            },
            include_hidden: {
              type: 'boolean',
              description: 'Include hidden files (default: false)'
            }
          },
          required: ['path']
        }
      },
      {
        name: 'search_files',
        description: 'Search for files by glob pattern in Safe Zone. Returns array of matching file paths. Supports wildcards (*, **) and glob patterns.',
        inputSchema: {
          type: 'object',
          properties: {
            pattern: {
              type: 'string',
              description: 'Glob pattern (e.g., "**/*.ts", "data/*.json")'
            },
            directory: {
              type: 'string',
              description: 'Search root directory (default: current working directory). Must be within Safe Zone.'
            }
          },
          required: ['pattern']
        }
      }
    ];
  }

  /**
   * Handle read_file tool
   */
  private async handleReadFile(args: any): Promise<any> {
    const filePath = args.path as string;

    // Validate access
    if (!this.validator.validate(filePath, 'read')) {
      throw new Error(`Access denied: ${filePath} is outside Safe Zone or blacklisted`);
    }

    // Read file
    try {
      const resolvedPath = path.resolve(filePath);

      if (!fs.existsSync(resolvedPath)) {
        throw new Error(`File not found: ${filePath}`);
      }

      const stats = fs.statSync(resolvedPath);
      if (!stats.isFile()) {
        throw new Error(`Path is not a file: ${filePath}`);
      }

      const content = fs.readFileSync(resolvedPath, 'utf-8');

      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({
              success: true,
              path: filePath,
              size: stats.size,
              content: content,
              modified: stats.mtime.toISOString()
            }, null, 2)
          } as TextContent
        ]
      };
    } catch (error: any) {
      throw new Error(`Failed to read file: ${error.message}`, { cause: error });
    }
  }

  /**
   * Handle write_file tool
   */
  private async handleWriteFile(args: any): Promise<any> {
    const filePath = args.path as string;
    const content = args.content as string;
    const createDirs = args.create_dirs !== false; // Default true

    // Validate access
    if (!this.validator.validate(filePath, 'write')) {
      throw new Error(`Access denied: ${filePath} is outside Safe Zone or blacklisted`);
    }

    try {
      const resolvedPath = path.resolve(filePath);
      const dirPath = path.dirname(resolvedPath);

      // Create parent directories if needed
      if (createDirs && !fs.existsSync(dirPath)) {
        fs.mkdirSync(dirPath, { recursive: true });
      }

      // Write file
      fs.writeFileSync(resolvedPath, content, 'utf-8');

      const stats = fs.statSync(resolvedPath);

      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({
              success: true,
              path: filePath,
              size: stats.size,
              bytes_written: Buffer.byteLength(content, 'utf-8'),
              modified: stats.mtime.toISOString()
            }, null, 2)
          } as TextContent
        ]
      };
    } catch (error: any) {
      throw new Error(`Failed to write file: ${error.message}`, { cause: error });
    }
  }

  /**
   * Handle list_directory tool
   */
  private async handleListDirectory(args: any): Promise<any> {
    const dirPath = args.path as string;
    const includeHidden = args.include_hidden === true;

    // Validate access (list operation is treated as read)
    if (!this.validator.validate(dirPath, 'read')) {
      throw new Error(`Access denied: ${dirPath} is outside Safe Zone`);
    }

    try {
      const resolvedPath = path.resolve(dirPath);

      if (!fs.existsSync(resolvedPath)) {
        throw new Error(`Directory not found: ${dirPath}`);
      }

      const stats = fs.statSync(resolvedPath);
      if (!stats.isDirectory()) {
        throw new Error(`Path is not a directory: ${dirPath}`);
      }

      // Read directory
      const entries = fs.readdirSync(resolvedPath);

      // Filter hidden files if needed
      const filteredEntries = includeHidden
        ? entries
        : entries.filter(e => !e.startsWith('.'));

      // Get metadata for each entry
      const items = filteredEntries.map(entry => {
        const entryPath = path.join(resolvedPath, entry);
        const entryStat = fs.statSync(entryPath);

        return {
          name: entry,
          type: entryStat.isDirectory() ? 'directory' : 'file',
          size: entryStat.size,
          modified: entryStat.mtime.toISOString()
        };
      });

      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({
              success: true,
              path: dirPath,
              items: items,
              count: items.length
            }, null, 2)
          } as TextContent
        ]
      };
    } catch (error: any) {
      throw new Error(`Failed to list directory: ${error.message}`, { cause: error });
    }
  }

  /**
   * Handle search_files tool
   */
  private async handleSearchFiles(args: any): Promise<any> {
    const pattern = args.pattern as string;
    const directory = args.directory || process.cwd();

    // Validate directory access
    if (!this.validator.validate(directory, 'read')) {
      throw new Error(`Access denied: ${directory} is outside Safe Zone`);
    }

    try {
      const resolvedDir = path.resolve(directory);

      // Use glob to find matching files
      const matches = await glob(pattern, {
        cwd: resolvedDir,
        absolute: false,
        dot: false // Don't include hidden files
      });

      // Validate each match is in Safe Zone
      const validMatches = matches.filter(match => {
        const fullPath = path.join(resolvedDir, match);
        return this.validator.validate(fullPath, 'read');
      });

      return {
        content: [
          {
            type: 'text',
            text: JSON.stringify({
              success: true,
              pattern: pattern,
              directory: directory,
              matches: validMatches,
              count: validMatches.length
            }, null, 2)
          } as TextContent
        ]
      };
    } catch (error: any) {
      throw new Error(`Failed to search files: ${error.message}`, { cause: error });
    }
  }

  /**
   * Start MCP server
   */
  async start(): Promise<void> {
    const transport = new StdioServerTransport();
    await this.server.connect(transport);
    logInfo('MCPFilesystemServer', 'MCP Filesystem Server running on stdio');
  }
}

/**
 * Main entry point for MCP server
 */
if (import.meta.url === `file://${process.argv[1]}`) {
  const server = new MCPFilesystemServer();
  server.start().catch(error => {
    logError('MCPFilesystemServer', `Failed to start server: ${error.message}`);
    process.exit(1);
  });
}

