// Helper to run shell commands
const runCommand = (command: string): Promise<string> => {
  return new Promise((resolve, reject) => {
    exec(command, { cwd: process.cwd() }, (error, stdout, stderr) => {
      if (error) {
        logError("JulesRoutes", `Exec error: ${error.message}`);
        reject(error.message);
        return;
      }
      if (stderr && !stderr.includes("Created session")) {
        // Jules CLI might print info to stderr
        logWarn("JulesRoutes", `Stderr: ${stderr}`);
      }
      resolve(stdout);
    });
  });
};

function getGithubApiBase(): string {
  return process.env.GITHUB_API_BASE || "https://api.github.com";
}

function getGithubRepo(): string {
  // Prefer GitHub Actions env, then local .env, then repo default.
  return (
    process.env.GITHUB_REPOSITORY ||
    process.env.GITHUB_REPO ||
    "pohi99999/mcp-brunella-core"
  );
}

function getGithubToken(): string | undefined {
  return (
    process.env.GITHUB_TOKEN || process.env.GH_TOKEN || process.env.GITHUB_PAT
  );
}

async function githubFetchJson(url: string, init?: RequestInit): Promise<any> {
  const token = getGithubToken();
  if (!token) {
    const err = new Error("GitHub token missing (set GITHUB_TOKEN)");
    (err as any).statusCode = 503;
    throw err;
  }

  const response = await fetch(url, {
    ...init,
    headers: {
      Accept: "application/vnd.github+json",
      Authorization: `Bearer ${token}`,
      "X-GitHub-Api-Version": "2022-11-28",
      ...(init?.headers || {}),
    },
    signal: AbortSignal.timeout(15000),
  });

  const text = await response.text();
  const data = text
    ? (() => {
        try {
          return JSON.parse(text);
        } catch {
          return { raw: text };
        }
      })()
    : {};

  if (!response.ok) {
    const err = new Error(
      data && (data.message as string)
        ? `GitHub API error: ${data.message}`
        : `GitHub API error: HTTP ${response.status}`,
    );
    (err as any).statusCode = response.status;
    (err as any).data = data;
    throw err;
  }

  return data;
}

export function createJulesRoutes(): Router {
  const router = Router();
  const scriptPath = path.join(
    process.cwd(),
    "scripts",
    "jules_cli_wrapper.py",
  );

  // ------------------------------------------------------------------------
  // GitHub Actions (Async tests)
  // ------------------------------------------------------------------------

  // GET /workflow-runs?workflow=jules-async-tests.yml&limit=10
  router.get("/workflow-runs", async (req, res) => {
    try {
      const workflow =
        typeof req.query.workflow === "string" && req.query.workflow.trim()
          ? req.query.workflow.trim()
          : "jules-async-tests.yml";

      const limitRaw =
        typeof req.query.limit === "string" ? req.query.limit : "10";
      const limit = Math.max(
        1,
        Math.min(50, parseInt(limitRaw || "10", 10) || 10),
      );

      const repo = getGithubRepo();
      const base = getGithubApiBase();
      const url = `${base}/repos/${repo}/actions/workflows/${encodeURIComponent(workflow)}/runs?per_page=${limit}`;

      const data = await githubFetchJson(url);
      res.json({ workflow, runs: data.workflow_runs || [] });
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      const status = (e as any)?.statusCode || 500;
      res.status(status).json({ error: msg });
    }
  });

  // POST /dispatch { workflow?: string, ref?: string, inputs?: object }
  router.post("/dispatch", async (req, res) => {
    try {
      const workflow =
        typeof req.body?.workflow === "string" && req.body.workflow.trim()
          ? String(req.body.workflow).trim()
          : "jules-async-tests.yml";

      const ref =
        typeof req.body?.ref === "string" && req.body.ref.trim()
          ? String(req.body.ref).trim()
          : "main";

      const inputs = (req.body?.inputs ?? {}) as Record<string, unknown>;

      const repo = getGithubRepo();
      const base = getGithubApiBase();
      const url = `${base}/repos/${repo}/actions/workflows/${encodeURIComponent(workflow)}/dispatches`;

      logInfo("JulesRoutes", `Dispatch workflow: ${workflow} ref=${ref}`);

      await githubFetchJson(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ ref, inputs }),
      });

      res.json({ success: true, workflow, ref });
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      const status = (e as any)?.statusCode || 500;
      res.status(status).json({ error: msg });
    }
  });

  // GET /sessions - List all sessions
  router.get("/sessions", async (req, res) => {
    try {
      // Using the wrapper to list sessions.
      // Expecting JSON output or parsing text if wrapper doesn't support JSON flag yet.
      // Ideally assume wrapper outputs something parseable or we parse it here.
      // Let's assume the wrapper output is human readable for now and we send it raw
      // or we try to parse it if we can.

      // For now, let's just send the raw output or a mocked list if script fails
      const stdout = await runCommand(`python "${scriptPath}" list`);

      // Parse stdout to JSON if possible, otherwise return as raw text lines
      const lines = stdout.split("\n").filter((l) => l.trim().length > 0);
      const sessions = lines.map((line) => {
        // Simple parser attempt: "SessionID Status Task..."
        const parts = line.split(/\s+/);
        if (parts.length >= 2) {
          return {
            id: parts[0],
            status: parts[1],
            task: parts.slice(2).join(" "),
          };
        }
        return { id: "unknown", status: "unknown", task: line };
      });

      res.json({ sessions });
    } catch (error) {
      res.status(500).json({ error: String(error) });
    }
  });

  // POST /task - Create new task
  router.post("/task", async (req, res) => {
    const { task } = req.body;
    if (!task) {
      return res.status(400).json({ error: "Task is required" });
    }

    try {
      // Escape quotes in task to prevent shell injection issues (basic)
      const safeTask = task.replace(/"/g, '\\"');
      const stdout = await runCommand(
        `python "${scriptPath}" new "${safeTask}"`,
      );

      // Extract Session ID from output
      // Output example: "✅ Session created: 12345..."
      const match =
        stdout.match(/Session ID: (\d+)/) ||
        stdout.match(/Session created: (\d+)/);
      const sessionId = match ? match[1] : null;

      res.json({
        success: true,
        sessionId,
        output: stdout,
      });
    } catch (error) {
      res.status(500).json({ error: String(error) });
    }
  });

  // POST /sync - Sync/Pull a session
  router.post("/sync", async (req, res) => {
    const { sessionId } = req.body;
    if (!sessionId) {
      return res.status(400).json({ error: "Session ID is required" });
    }

    try {
      const stdout = await runCommand(
        `python "${scriptPath}" pull "${sessionId}"`,
      );
      res.json({ success: true, output: stdout });
    } catch (error) {
      res.status(500).json({ error: String(error) });
    }
  });

  // ------------------------------------------------------------------------
  // Jules automation rules (.jules.yml) -> scheduled_tasks
  // ------------------------------------------------------------------------

  // GET /automations/tasks - list imported Jules tasks
  router.get("/automations/tasks", async (_req, res) => {
    try {
      const db = getGlobalDb();
      const julesService = new JulesAutomationService(db);
      const tasks = julesService.getImportedTasks();
      res.json({ success: true, count: tasks.length, tasks });
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      res.status(500).json({ success: false, error: msg });
    }
  });

  // POST /automations/import - manually trigger import from .jules.yml
  router.post("/automations/import", async (req, res) => {
    try {
      const skipIfExists =
        typeof req.body?.skipIfExists === "boolean" ? req.body.skipIfExists : true;
      const enableImmediately =
        typeof req.body?.enableImmediately === "boolean"
          ? req.body.enableImmediately
          : true;

      const db = getGlobalDb();
      const julesService = new JulesAutomationService(db);
      const result = await julesService.importJulesAutomations({
        skipIfExists,
        enableImmediately,
      });

      res.json({ success: true, result });
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      res.status(500).json({ success: false, error: msg });
    }
  });

  return router;
}

/**
 * Machine Hunter API Routes
 * Track: industrial_machine_hunter_20260216 – Phase 3 (Alerting)
 *
 * Endpoints:
 *   POST /api/machines/hunt  – Hunt + valuate + broadcast BUY alerts
 *   GET  /api/machines/ping  – Health check
 *
 * Glass Box: A machine_hunter.py-t hívja, majd BUY eredményeket Socket.IO-n
 * broadcasts `machine_alert` event-ként a dashboardnak.
 */

import { Router, Request, Response } from "express";
import { spawn } from "child_process";
import path from "path";
import { fileURLToPath } from "url";
import { socketService } from "../SocketService.js";
import { logInfo, logError } from "../../utils/logger.js";
import { alertDispatcher } from "../../pipeline/alertDispatcher.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const WORKER_PATH = path.resolve(__dirname, "../../../myai/workers/machine_hunter.py");

export interface MachineHuntRequest {
  query: string;
  sources?: string[];
  limit?: number;
  mock?: boolean;
}

export interface ValuationResult {
  listing_id: string;
  title: string;
  price_eur: number;
  estimated_value_eur: number;
  arbitrage_score: number;
  confidence: number;
  recommendation: "BUY" | "WATCH" | "IGNORE";
  reasoning: string;
  discount_pct: number;
}

export interface MachineHuntResult {
  query: string;
  valuations: ValuationResult[];
  top_buys: ValuationResult[];
  total_scraped: number;
  after_filters: number;
  sources_used: string[];
  duration_seconds: number;
  success: boolean;
  error_message?: string;
}

export interface HuntResponse {
  success: boolean;
  query: string;
  total: number;
  buy_count: number;
  results: ValuationResult[];
  top_buys: ValuationResult[];
  broadcast_sent: boolean;
  duration_seconds: number;
}

function runMachineHunter(input: MachineHuntRequest): Promise<MachineHuntResult> {
  return new Promise((resolve, reject) => {
    const args = [
      WORKER_PATH,
      "--query", input.query,
      "--limit", String(input.limit ?? 20),
    ];
    if (input.mock) args.push("--mock");
    if (input.sources?.length) args.push("--sources", ...input.sources);

    const proc = spawn("python", args, { stdio: ["pipe", "pipe", "pipe"] });

    let stdout = "";
    let stderr = "";

    proc.stdout.on("data", (chunk: Buffer) => { stdout += chunk.toString(); });
    proc.stderr.on("data", (chunk: Buffer) => { stderr += chunk.toString(); });

    proc.on("close", (code) => {
      if (code !== 0) {
        const errMsg = stderr.slice(0, 500) || `Exit code ${code}`;
        return reject(new Error(errMsg));
      }
      try {
        const trimmed = stdout.trim();
        const parsed = JSON.parse(trimmed) as MachineHuntResult;
        resolve(parsed);
      } catch {
        reject(new Error(`JSON parse error. stdout: ${stdout.slice(0, 300)}`));
      }
    });

    proc.on("error", (err) => reject(err));
  });
}

export function createMachinesRouter(): Router {
  const router = Router();

  /**
   * GET /api/machines/ping
   */
  router.get("/ping", (_req: Request, res: Response) => {
    res.json({ ok: true, service: "machine_hunter", timestamp: Date.now() });
  });

  /**
   * POST /api/machines/hunt
   * Body: { query: string, sources?: string[], limit?: number, mock?: boolean }
   *
   * Runs machine_hunter.py, broadcasts BUY alerts via Socket.IO,
   * returns full valuation list.
   */
  router.post("/hunt", async (req: Request, res: Response) => {
    const body = req.body as Partial<MachineHuntRequest>;

    if (!body.query || typeof body.query !== "string" || !body.query.trim()) {
      res.status(400).json({ success: false, error: "query mező kötelező." });
      return;
    }

    const huntReq: MachineHuntRequest = {
      query: body.query.trim(),
      sources: body.sources,
      limit: typeof body.limit === "number" ? body.limit : 20,
      mock: body.mock ?? false,
    };

    logInfo("MachinesRoute", `Hunt indítva – query="${huntReq.query}" limit=${huntReq.limit} mock=${huntReq.mock}`);

    let huntResult: MachineHuntResult;
    try {
      huntResult = await runMachineHunter(huntReq);
    } catch (e: unknown) {
      const errMsg = e instanceof Error ? e.message : String(e);
      logError("MachinesRoute", `machine_hunter.py hiba: ${errMsg}`);
      res.status(500).json({ success: false, error: errMsg });
      return;
    }

    const buyResults = huntResult.top_buys ?? [];
    
    // 🔔 BUY ajánlások feldolgozása (riasztás + automata outreach)
    if (buyResults.length > 0) {
      await alertDispatcher.processHunterResults(huntResult);
      logInfo("MachinesRoute", `AlertDispatcher feldolgozás kész – ${buyResults.length} BUY ajánlás`);
    }

    const response: HuntResponse = {
      success: true,
      query: huntReq.query,
      total: huntResult.total_scraped,
      buy_count: buyResults.length,
      results: huntResult.valuations,
      top_buys: buyResults,
      broadcast_sent: buyResults.length > 0,
      duration_seconds: huntResult.duration_seconds,
    };

    res.json(response);
  });

  return router;
}

import express from 'express';
import { getBifrostGateway } from '../../core/bifrost_gateway.js';
import { getSafeZoneValidator } from '../../security/safe_zone_validator.js';
import { getE2BSandboxManager } from '../../security/e2b_sandbox_manager.js';
import { logInfo, logError } from '../../utils/logger.js';
import { MCPFilesystemServer } from '../mcp_server.js';

/**
 * MCP API Routes
 *
 * Endpoints:
 * - GET /api/mcp/providers - List all LLM providers + health
 * - POST /api/mcp/generate - Generate with Bifrost Gateway
 * - GET /api/mcp/tools - List MCP filesystem tools
 * - POST /api/mcp/tools/:toolName - Execute MCP tool
 * - GET /api/mcp/audit - Get Safe Zone audit log
 * - GET /api/mcp/safezones - List Safe Zone configs
 * - GET /api/mcp/stats - Get usage statistics
 */

const router = express.Router();

// Initialize services
const bifrost = getBifrostGateway();
const validator = getSafeZoneValidator();
const e2bManager = getE2BSandboxManager();
const mcpServer = new MCPFilesystemServer();

/**
 * GET /api/mcp/providers
 * List all LLM providers with health status
 */
router.get('/providers', async (req, res) => {
  try {
    const health = await bifrost.checkHealth();
    const enabled = bifrost.getEnabledProviders();
    const stats = bifrost.getStats();

    res.json({
      success: true,
      providers: health,
      enabled_providers: enabled,
      stats
    });
  } catch (e: unknown) {
    const error = e instanceof Error ? e.message : String(e);
    logError('MCP API', `GET /providers failed: ${error}`);
    res.status(500).json({ success: false, error });
  }
});

/**
 * POST /api/mcp/generate
 * Generate LLM response via Bifrost Gateway
 *
 * Body: { prompt, taskType?, provider?, temperature?, maxTokens? }
 */
router.post('/generate', async (req, res) => {
  try {
    const { prompt, taskType, provider, temperature, maxTokens, systemPrompt, userId } = req.body;

    if (!prompt || typeof prompt !== 'string') {
      return res.status(400).json({
        success: false,
        error: 'prompt is required and must be a string'
      });
    }

    logInfo('MCP API', `Generate request: ${prompt.slice(0, 50)}... (provider: ${provider || 'auto'})`);

    const result = await bifrost.generate({
      prompt,
      taskType,
      provider,
      temperature,
      maxTokens,
      systemPrompt,
      userId,
    });

    res.json(result);
  } catch (e: unknown) {
    const error = e instanceof Error ? e.message : String(e);
    logError('MCP API', `POST /generate failed: ${error}`);
    res.status(500).json({ success: false, error });
  }
});

/**
 * GET /api/mcp/tools
 * List all MCP filesystem tools
 */
router.get('/tools', (req, res) => {
  try {
    const tools = (mcpServer as any).getTools();

    res.json({
      success: true,
      tools: tools.map((t: any) => ({
        name: t.name,
        description: t.description,
        inputSchema: t.inputSchema
      })),
      count: tools.length
    });
  } catch (e: unknown) {
    const error = e instanceof Error ? e.message : String(e);
    logError('MCP API', `GET /tools failed: ${error}`);
    res.status(500).json({ success: false, error });
  }
});

/**
 * POST /api/mcp/tools/:toolName
 * Execute MCP tool with arguments
 *
 * Body: { args: {...} }
 */
router.post('/tools/:toolName', async (req, res) => {
  try {
    const { toolName } = req.params;
    const { args } = req.body;

    if (!args || typeof args !== 'object') {
      return res.status(400).json({
        success: false,
        error: 'args is required and must be an object'
      });
    }

    logInfo('MCP API', `Tool execution: ${toolName} with args: ${JSON.stringify(args).slice(0, 100)}`);

    // Route to appropriate handler
    let result;
    switch (toolName) {
      case 'read_file':
        result = await (mcpServer as any).handleReadFile(args);
        break;
      case 'write_file':
        result = await (mcpServer as any).handleWriteFile(args);
        break;
      case 'list_directory':
        result = await (mcpServer as any).handleListDirectory(args);
        break;
      case 'search_files':
        result = await (mcpServer as any).handleSearchFiles(args);
        break;
      default:
        return res.status(404).json({
          success: false,
          error: `Tool not found: ${toolName}`
        });
    }

    // Parse result content
    const parsed = JSON.parse(result.content[0].text);

    res.json(parsed);
  } catch (e: unknown) {
    const error = e instanceof Error ? e.message : String(e);
    logError('MCP API', `POST /tools/${req.params.toolName} failed: ${error}`);
    res.status(500).json({ success: false, error });
  }
});

/**
 * GET /api/mcp/audit
 * Get Safe Zone audit log (recent entries)
