        const response = await fetch(`${PYTHON_DEMO_FACTORY_URL}/generate-demo`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ domain, industry, company_name })
        });

        if (!response.ok) {
            const error = await response.text();
