export function createStudioRoutes(): Router {
    const router = Router();

    router.get('/projects', async (req, res) => {
        try {
            const projects = await getStudioProjects();
            res.json({ success: true, projects });
        } catch (e: any) {
            res.status(500).json({ success: false, error: e.message });
        }
    });

    router.post('/projects', async (req, res) => {
        try {
            const { name, description, tech_stack } = req.body;
            if (!name) {
                return res.status(400).json({ success: false, error: 'name is required' });
            }

            const id = uuidv4();
            const rootDir = path.join(process.cwd(), 'data', 'studio', id);

            await fs.mkdir(rootDir, { recursive: true });

            // 1. Scaffold minimal Vite React app (instant, no LLM needed)
            await scaffoldViteReact(rootDir, { name, description: description || '' });

            // 2. Save project to DB
            const project = { id, name, description, tech_stack: tech_stack || 'React + Vite', root_dir: rootDir, status: 'scaffolded' };
            await saveStudioProject(project);

            // 3. Start dev server via StudioRunner (npm install + npm run dev)
            //    Fire-and-forget: studio:log and studio:ready events will be emitted to Socket.IO
            studioRunner.startProject(id, rootDir).catch(() => { /* logged in StudioRunner */ });

            // 4. Trigger LLM agent swarm to generate real code into rootDir
            agentManager.queueTask(
                `Hozd létre a(z) "${name}" alkalmazást. Technológia: ${tech_stack || 'React + Vite + TypeScript'}. Leírás: ${description || ''}. A fájlokat a következő könyvtárba írj: ${rootDir}`,
                'orchestrator',
                { projectId: id, studioMode: true, rootDir }
            );

            res.json({ success: true, project });
        } catch (e: any) {
            res.status(500).json({ success: false, error: e.message });
        }
    });

    router.post('/projects/:id/iterate', async (req, res) => {
        try {
            const { instruction } = req.body;
            const projectId = req.params.id;

            const projects = await getStudioProjects();
            const project = projects.find((p: any) => p.id === projectId) as any;

            if (!project) {
                return res.status(404).json({ success: false, error: 'Project not found' });
            }

            updateProjectStatus(projectId, 'coding');

            agentManager.queueTask(
                `MÓDOSÍTÁS: ${instruction} a(z) "${project.name}" projektben (${project.root_dir}). Tartsd meg a meglévő funkciókat, de alkalmazd a változtatást. A fájlokat a következő könyvtárba írj: ${project.root_dir}`,
                'orchestrator',
                { projectId, studioMode: true, rootDir: project.root_dir, isIteration: true }
            );

            res.json({ success: true, message: 'Iteration started' });
        } catch (e: any) {
            res.status(500).json({ success: false, error: e.message });
        }
    });

    return router;
}

import { Router } from 'express';
import { getTasks, getTaskCount, getTaskById, getTaskStats } from '../../utils/tasksDb.js';
import { agentManager } from '../../agents/AgentManager.js';
import { decomposeToDAGAsync } from '../../agents/taskDecomposerCore.js';

export function createTaskRoutes(): Router {
    const router = Router();

    router.get('/', async (req, res) => {
        try {
            const limit = parseInt(req.query.limit as string) || 20;
            const offset = parseInt(req.query.offset as string) || 0;
            const status = typeof req.query.status === 'string' ? req.query.status : undefined;
            const tasks = await getTasks(limit, offset, status);
            const total = await getTaskCount(status);
            res.json({ tasks, total, limit, offset, status });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.get('/stats', async (req, res) => {
        try {
            const stats = await getTaskStats();
            res.json({ stats });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.get('/workflow/status', async (_req, res) => {
        try {
            res.json({ workflows: agentManager.listWorkflowExecutions() });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/workflow/preview', async (req, res) => {
        try {
            const { task, defaultAgent } = req.body as { task?: string; defaultAgent?: string };
            if (!task) {
                res.status(400).json({ error: 'task is required' });
                return;
            }

            const workflow = await decomposeToDAGAsync(task, { defaultAgent });
            res.json({ success: true, workflow });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/workflow/run', async (req, res) => {
        try {
            const { task, workflow, defaultAgent, initialContext } = req.body as {
                task?: string;
                workflow?: Parameters<typeof agentManager.executeWorkflow>[0];
                defaultAgent?: string;
                initialContext?: Record<string, unknown>;
            };

            const resolvedWorkflow = workflow ?? (task ? await decomposeToDAGAsync(task, { defaultAgent }) : undefined);
            if (!resolvedWorkflow) {
                res.status(400).json({ error: 'task or workflow is required' });
                return;
            }

            const result = await agentManager.executeWorkflow(resolvedWorkflow, initialContext);
            res.json({ success: true, workflow: resolvedWorkflow, result });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.get('/:id', async (req, res) => {
        try {
            const id = Number(req.params.id);
            if (Number.isNaN(id)) {
                res.status(400).json({ error: 'Invalid task id' });
                return;
            }
            const task = await getTaskById(id);
            if (!task) {
                res.status(404).json({ error: 'Task not found' });
                return;
            }

            // If the task result contains a traceId, fetch trace spans for deeper logs
            let logs: Array<{ timestamp: string; level: string; message: string; details?: any }> = [];
            try {
                if (task.result) {
                    let parsed: any = null;
                    try { parsed = JSON.parse(task.result); } catch { parsed = null; }
                    const traceId = parsed?.metadata?.traceId || parsed?.traceId || (parsed?.data && parsed.data.traceId);
                    if (traceId) {
                        const { getTraceSpans } = await import('../../utils/agentTracer.js');
                        const spans = getTraceSpans(traceId);
                        logs = spans.map(s => ({
                            timestamp: new Date(s.startTime).toISOString(),
                            level: s.status === 'error' ? 'error' : 'info',
                            message: `${s.agentName} ${s.operation}`,
                            details: s,
                        }));
                    }
                }
            } catch {
                // ignore tracing errors
            }

            res.json({ task: { ...task, logs } });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/', async (req, res) => {
        try {
            const { description, agentName, context, parentId } = req.body;

            if (!description || !agentName) {
                res.status(400).json({ error: 'Description and agentName are required' });
                return;
            }

            const taskId = agentManager.queueTask(description, agentName, context, parentId);
            res.json({ taskId, status: 'queued' });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/execute', async (req, res) => {
        try {
            const result = await agentManager.processPendingTasks();
            if (!result) {
                res.status(404).json({ error: 'No pending tasks' });
                return;
            }
            res.json({ result });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/cancel', async (req, res) => {
        try {
            const taskId = Number(req.body.taskId);
            if (Number.isNaN(taskId)) {
                res.status(400).json({ error: 'taskId is required' });
                return;
            }
            const ok = await agentManager.cancelTask(taskId);
            if (!ok) {
                res.status(404).json({ error: 'Task not found' });
                return;
            }
            res.json({ status: 'cancelled', taskId });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/retry', async (req, res) => {
        try {
            const taskId = Number(req.body.taskId);
            const debugMode = Boolean(req.body.debugMode);
            if (Number.isNaN(taskId)) {
                res.status(400).json({ error: 'taskId is required' });
                return;
            }
            const ok = await agentManager.retryTask(taskId, debugMode);
            if (!ok) {
                res.status(404).json({ error: 'Task not found' });
                return;
            }
            res.json({ status: 'pending', taskId, debugMode });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/pause', async (req, res) => {
        try {
            const taskId = Number(req.body.taskId);
            if (Number.isNaN(taskId)) {
                res.status(400).json({ error: 'taskId is required' });
                return;
            }
            const ok = await agentManager.pauseTask(taskId);
            if (!ok) {
                res.status(404).json({ error: 'Task not found or not resumable' });
                return;
            }
            res.json({ status: 'paused', taskId });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/resume', async (req, res) => {
        try {
            const taskId = Number(req.body.taskId);
            if (Number.isNaN(taskId)) {
                res.status(400).json({ error: 'taskId is required' });
                return;
            }
            const ok = await agentManager.resumeTask(taskId);
            if (!ok) {
                res.status(404).json({ error: 'Task not found or not resumable' });
                return;
            }
            res.json({ status: 'pending', taskId });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    router.post('/reorder', async (req, res) => {
        try {
            const { taskIds } = req.body;
            if (!Array.isArray(taskIds) || taskIds.some(isNaN)) {
                res.status(400).json({ error: 'taskIds must be an array of numbers' });
                return;
            }
            agentManager.updateTaskOrder(taskIds);
            res.json({ status: 'reordered', taskIds });
        } catch (e: unknown) {
            const msg = e instanceof Error ? e.message : String(e);
            res.status(500).json({ error: msg });
        }
    });

    return router;
}

/**
 * Tracks API Routes
 *
 * Endpoints for track management and TODO tracking
 */

import { Router } from 'express';
import { promises as fs } from 'fs';
import path from 'path';
import {
  parseTrackTodos,
  toggleTodoInContent,
  findTodoLineNumber,
  type TrackTodoView,
} from '../../utils/trackTodoParser.js';

const TRACKS_DIR = path.join(process.cwd(), 'conductor', 'tracks');

export function createTracksRoutes(): Router {
  const router = Router();

  /**
   * GET /api/v1/tracks/todos/active
   * Get TODO summaries for all active tracks
   */
  router.get('/todos/active', async (req, res) => {
    try {
      const trackDirs = await fs.readdir(TRACKS_DIR);
      const summaries = [];

      for (const dir of trackDirs) {
        const metaPath = path.join(TRACKS_DIR, dir, 'meta.json');
        const trackPath = path.join(TRACKS_DIR, dir, 'track.md');

        try {
          const metaContent = await fs.readFile(metaPath, 'utf-8');
          const meta = JSON.parse(metaContent);

          // Only include active/in_progress tracks
          if (!['active', 'in_progress'].includes(meta.status)) {
            continue;
          }

          // Try to read track.md for TODO parsing
          let todoView: TrackTodoView | null = null;
          try {
            await fs.access(trackPath);
            const content = await fs.readFile(trackPath, 'utf-8');
            todoView = parseTrackTodos(content, dir);
          } catch {
            // track.md doesn't exist, skip
            continue;
          }

          if (todoView && todoView.todos.length > 0) {
            summaries.push({
              trackId: dir,
              title: todoView.trackTitle,
              progress: todoView.progress,
              completedCount: todoView.todos.filter(t => t.completed).length,
              totalCount: todoView.todos.length,
              updatedAt: new Date().toISOString(),
            });
          }
        } catch {
          // Skip invalid tracks
        }
      }

      return res.json({ tracks: summaries });
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      console.error('[TracksRoutes] Error getting active TODO summaries:', message);
      return res.status(500).json({ error: 'Failed to get active tracks', details: message });
    }
  });

  /**
   * GET /api/v1/tracks/:id/todos
   * Get TODO checklist from track.md
   */
  router.get('/:id/todos', async (req, res) => {
    try {
      const { id } = req.params;

      // Security: validate track ID (no path traversal)
      if (!isValidTrackId(id)) {
        return res.status(400).json({ error: 'Invalid track ID' });
      }

      const trackPath = path.join(TRACKS_DIR, id, 'track.md');

      // Check if track.md exists
      try {
        await fs.access(trackPath);
      } catch {
        return res.status(404).json({ error: 'Track not found' });
      }

      // Read and parse track.md
      const content = await fs.readFile(trackPath, 'utf-8');
      const todoView = parseTrackTodos(content, id);

      // Return in TrackTodosResponse format
      const completedCount = todoView.todos.filter(t => t.completed).length;
      return res.json({
        success: true,
        trackId: todoView.trackId,
        title: todoView.trackTitle,
        todos: todoView.todos,
        progress: todoView.progress,
        completedCount,
        totalCount: todoView.todos.length,
        updatedAt: new Date().toISOString(),
      });
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      console.error('[TracksRoutes] Error getting TODOs:', message);
      return res.status(500).json({ error: 'Failed to get TODOs', details: message });
    }
  });

  /**
   * PATCH /api/v1/tracks/:id/todos/:todoId
   * Toggle TODO checkbox state
   */
  router.patch('/:id/todos/:todoId', async (req, res) => {
    try {
      const { id, todoId } = req.params;

      // Security: validate track ID
      if (!isValidTrackId(id)) {
        return res.status(400).json({ error: 'Invalid track ID' });
      }

      const trackPath = path.join(TRACKS_DIR, id, 'track.md');

      // Check if track.md exists
      try {
        await fs.access(trackPath);
      } catch {
        return res.status(404).json({ error: 'Track not found' });
      }

      // Read content
      let content = await fs.readFile(trackPath, 'utf-8');

      // Find TODO line number
      const lineNumber = findTodoLineNumber(content, todoId);

      // Toggle checkbox
      content = toggleTodoInContent(content, lineNumber);

      // Write back to file
      await fs.writeFile(trackPath, content, 'utf-8');

      // Parse updated content
      const updatedView = parseTrackTodos(content, id);

      // Return in TrackTodosResponse format
      const completedCount = updatedView.todos.filter(t => t.completed).length;
      const response = {
        success: true,
        trackId: updatedView.trackId,
        title: updatedView.trackTitle,
        todos: updatedView.todos,
        progress: updatedView.progress,
        completedCount,
        totalCount: updatedView.todos.length,
        updatedAt: new Date().toISOString(),
      };

      // Emit WebSocket event for real-time updates
      // (will be implemented when WebSocket is set up)
      // io?.emit('track:todo:updated', { trackId: id, todoView: response });

      return res.json(response);
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      console.error('[TracksRoutes] Error toggling TODO:', message);
      return res.status(500).json({ error: 'Failed to toggle TODO', details: message });
    }
  });

  /**
   * GET /api/v1/tracks
   * List all tracks with basic metadata
   */
  router.get('/', async (req, res) => {
    try {
      const trackDirs = await fs.readdir(TRACKS_DIR);
      const tracks = [];

      for (const dir of trackDirs) {
        const metaPath = path.join(TRACKS_DIR, dir, 'meta.json');
        try {
          const metaContent = await fs.readFile(metaPath, 'utf-8');
          const meta = JSON.parse(metaContent);
          tracks.push({
            id: dir,
            name: meta.name || dir,
            status: meta.status || 'unknown',
            priority: meta.priority || 'medium',
            progress: meta.progress || 0,
          });
        } catch {
          // Skip if meta.json doesn't exist or is invalid
        }
      }

      return res.json({ tracks });
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Unknown error';
      console.error('[TracksRoutes] Error listing tracks:', message);
      return res.status(500).json({ error: 'Failed to list tracks', details: message });
    }
  });

  return router;
}

/**
 * Validate track ID (prevent path traversal)
 */
function isValidTrackId(id: string): boolean {
  // Only allow alphanumeric, dash, underscore
  return /^[a-zA-Z0-9_-]+$/.test(id);
}

/**
 * TTS (Text-to-Speech) API Routes
 *
 * Provides Nova voice TTS for Brunella's responses
 */

import { Router } from 'express';
import { textToSpeech, VoiceOption, TTSModel } from '../../utils/tts.js';
import { logInfo, logError } from '../../utils/logger.js';

export function createTTSRoutes(): Router {
  const router = Router();

  /**
   * POST /api/tts
   *
   * Generate speech audio from text
   *
   * Body:
   * {
   *   "text": "Hello world",
   *   "voice": "nova",      // optional: alloy, echo, fable, onyx, nova, shimmer
   *   "model": "tts-1",     // optional: tts-1, tts-1-hd
   *   "speed": 1.0          // optional: 0.25 to 4.0
   * }
   *
   * Response: audio/mpeg (MP3 blob)
   */
  router.post('/', async (req, res) => {
    try {
      const { text, voice, model, speed } = req.body;

      if (!text || typeof text !== 'string' || text.trim().length === 0) {
        res.status(400).json({
          error: 'Invalid request: "text" is required and must be a non-empty string'
        });
        return;
      }

      logInfo('TTS API', `Request: "${text.slice(0, 50)}..." (voice: ${voice || 'nova'})`);

      const audioBlob = await textToSpeech(text, {
        voice: voice as VoiceOption,
        model: model as TTSModel,
        speed: speed ? parseFloat(speed) : undefined,
      });

      // Convert Blob to Buffer for Express response
      const arrayBuffer = await audioBlob.arrayBuffer();
      const buffer = Buffer.from(arrayBuffer);

      res.setHeader('Content-Type', 'audio/mpeg');
      res.setHeader('Content-Length', buffer.length.toString());
      res.setHeader('Cache-Control', 'public, max-age=3600'); // Cache for 1 hour
      res.send(buffer);

      logInfo('TTS API', `Response sent: ${buffer.length} bytes`);
    } catch (error: any) {
      logError('TTS API', `Error: ${error.message}`);
      res.status(500).json({
        error: error.message || 'TTS generation failed'
      });
    }
  });

  /**
   * GET /api/tts/voices
   *
   * List available voices
   */
  router.get('/voices', (req, res) => {
    res.json({
      voices: [
        { id: 'alloy', name: 'Alloy', description: 'Neutral and balanced' },
        { id: 'echo', name: 'Echo', description: 'Male, clear' },
        { id: 'fable', name: 'Fable', description: 'British, expressive' },
        { id: 'onyx', name: 'Onyx', description: 'Deep male voice' },
        { id: 'nova', name: 'Nova', description: 'Female, warm and sultry (Brunella default) 🎙️' },
        { id: 'shimmer', name: 'Shimmer', description: 'Soft female voice' },
      ],
      models: [
        { id: 'tts-1', name: 'Standard', description: 'Fast, lower quality' },
        { id: 'tts-1-hd', name: 'HD', description: 'Slower, higher quality' },
      ],
      default: {
        voice: 'nova',
        model: 'tts-1',
        speed: 1.0,
      }
    });
  });

  return router;
}

