      logInfo('WranglerRoutes', `Migration completed for database: ${databaseId}`);
      res.json({
        success: true,
        databaseId,
        message: 'Migration completed successfully',
      });
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError('WranglerRoutes', error);
      res.status(500).json({ error: 'Migration execution failed' });
    }
  });

  return router;
};

import cron from 'node-cron';
import { getGlobalDb } from '../../utils/globalDb.js';
import { logInfo, logError, logWarn } from '../../utils/logger.js';
import { agentManager } from '../../agents/AgentManager.js';
import { PythonShell } from 'python-shell';
import { JulesAutomationService } from '../../core/julesAutomationService.js';

interface ScheduledTask {
  id: string;
  title: string;
  prompt: string;
  cron_expression: string;
  handler: string;
  enabled: boolean;
  metadata?: string | null;
}

interface JulesAutomationAction {
  type: string;
  target: string;
  params?: Record<string, unknown>;
}

/**
 * ScheduledTasksRunner - Dynamically executes tasks from the database
 */
export class ScheduledTasksRunner {
  private activeJobs: Map<string, cron.ScheduledTask> = new Map();

  /**
   * Start the runner and schedule all enabled tasks
   */
  public async start() {
    logInfo('ScheduledTasksRunner', 'Initializing dynamic task scheduler...');
    await this.seedDefaults();
    await this.importJulesAutomations();
    await this.refreshSchedule();
  }

  /**
   * Import enabled Jules automation rules from .jules.yml into scheduled_tasks.
   * Safe and idempotent: existing tasks are skipped by title.
   */
  private async importJulesAutomations() {
    try {
      const db = getGlobalDb();
      const julesService = new JulesAutomationService(db);

      const result = await julesService.importJulesAutomations({
        skipIfExists: true,
        enableImmediately: true,
      });

      logInfo(
        'ScheduledTasksRunner',
        `Jules automations import complete: ${result.imported} imported, ${result.skipped} skipped, ${result.errors.length} errors`,
      );

      if (result.errors.length > 0) {
        for (const err of result.errors) {
          logError('ScheduledTasksRunner', `Jules automation import error: ${err}`);
        }
      }
    } catch (error) {
      logError('ScheduledTasksRunner', `Failed to import Jules automations: ${error}`);
    }
  }

  /**
   * Populate default tasks if the table is empty
   */
  private async seedDefaults() {
    try {
      const db = getGlobalDb();
      const count = (db.prepare('SELECT COUNT(*) as count FROM scheduled_tasks').get() as { count: number }).count;

      if (count === 0) {
        logInfo('ScheduledTasksRunner', 'Seeding default scheduled tasks...');
        const now = new Date().toISOString();
        
        const defaults = [
          {
            id: 'default-market-intel',
            title: 'Market Intel Update',
            prompt: 'Update market prices and intelligence reports',
            cron_expression: '0 8 * * *',
            handler: 'agent'
          },
          {
            id: 'default-sales-hunter',
            title: 'Daily Sales Lead Hunt',
            prompt: 'Find 5 new high-quality leads for automation services in Hungary',
            cron_expression: '0 9 * * *',
            handler: 'agent'
          },
          {
            id: 'default-evaluator-audit',
            title: 'System Health Audit',
            prompt: 'Perform a comprehensive system audit and report any anomalies',
            cron_expression: '0 12 * * *',
            handler: 'agent'
          },
          {
            id: 'data-flywheel-harvester',
            title: 'Tech Harvester - Daily Harvest',
            prompt: 'Run myai/agents/tech_harvester.py with --mode auto to collect new tech trends and competitor info.',
            cron_expression: '0 3 * * *',
            handler: 'python_script'
          },
          {
            id: 'data-flywheel-integrator',
            title: 'Knowledge Integrator - Daily Refine & Index',
            prompt: 'Run myai/tools/knowledge_integrator.py to refine collected data, generate embeddings, and save to LanceDB and golden_dataset.jsonl.',
            cron_expression: '30 3 * * *',
            handler: 'python_script'
          },
          {
            id: 'golden-dataset-verification',
            title: 'Golden Dataset Growth Verification',
            prompt: 'Verify if data/training/golden_dataset.jsonl has increased in size in the last 24 hours. Report status to dashboard/logs.',
            cron_expression: '0 4 * * *',
            handler: 'agent'
          }
        ];

        const insert = db.prepare(`
          INSERT INTO scheduled_tasks (id, title, prompt, cron_expression, handler, enabled, created_at, updated_at)
          VALUES (?, ?, ?, ?, ?, 1, ?, ?)
        `);

        for (const task of defaults) {
          insert.run(task.id, task.title, task.prompt, task.cron_expression, task.handler, now, now);
        }
        
        logInfo('ScheduledTasksRunner', 'Default tasks seeded successfully.');
      }
    } catch (error) {
      logError('ScheduledTasksRunner', `Failed to seed default tasks: ${error}`);
    }
  }

  /**
   * Refresh the schedule by reloading tasks from the database
   */
  public async refreshSchedule() {
    try {
      const db = getGlobalDb();
      const tasks = db.prepare('SELECT * FROM scheduled_tasks WHERE enabled = 1').all() as ScheduledTask[];

      logInfo('ScheduledTasksRunner', `Found ${tasks.length} enabled tasks in DB.`);

      // Stop all existing jobs
      this.stopAll();

      // Schedule each task
      for (const task of tasks) {
        this.scheduleTask(task);
      }

      logInfo('ScheduledTasksRunner', 'Schedule refresh complete.');
    } catch (error) {
      logError('ScheduledTasksRunner', `Failed to refresh schedule: ${error}`);
    }
  }

  /**
   * Stop all active cron jobs
   */
  public stopAll() {
    for (const [id, job] of this.activeJobs.entries()) {
      job.stop();
    }
    this.activeJobs.clear();
  }

  /**
   * Schedule a single task
   */
  private scheduleTask(task: ScheduledTask) {
    if (!cron.validate(task.cron_expression)) {
      logError('ScheduledTasksRunner', `Invalid cron expression for task ${task.id}: ${task.cron_expression}`);
      return;
    }

    const job = cron.schedule(task.cron_expression, async () => {
      await this.executeTask(task);
    });

    this.activeJobs.set(task.id, job);
    logInfo('ScheduledTasksRunner', `Task scheduled: ${task.title} (${task.cron_expression})`);
  }

  /**
   * Execute a task based on its handler
   */
  public async executeTask(task: ScheduledTask) {
    const startTime = new Date().toISOString();
    logInfo('ScheduledTasksRunner', `Executing task: ${task.title} (ID: ${task.id})`);

    try {
      let result: any = null;

      if (task.handler === 'agent') {
        // Execute via Agent Manager with auto-routing
        result = await agentManager.delegateTask({
          id: `scheduled-${task.id}-${Date.now()}`,
          instruction: task.prompt,
          source: 'scheduler',
          createdAt: new Date().toISOString()
        });
      } else if (task.handler === 'scan-todos') {
        // Trigger todo scanner via internal API call simulation
        const response = await fetch('http://localhost:3000/api/v1/suggested-tasks/scan', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ source: 'scheduled', taskId: task.id })
        });
        result = await response.json();
      } else if (task.handler === 'python_script') {
        const path = await import('path');
        const scriptPath = task.prompt.split(' ')[0];
        const absoluteScriptPath = path.default.resolve(process.cwd(), scriptPath);
        
        logInfo('ScheduledTasksRunner', `Executing Python script: ${absoluteScriptPath}`);
        const pythonShell = new PythonShell(absoluteScriptPath, {
          mode: 'text',
          pythonOptions: ['-u'],
          args: task.prompt.split(' ').slice(1),
        });

        result = await new Promise((resolve, reject) => {
          let scriptOutput = '';
          pythonShell.on('stdout', (message: string) => {
            scriptOutput += message;
          });
          pythonShell.end((err: Error | null, code: number | undefined, signal: string | undefined) => {
            if (err) return reject(err);
            resolve({ output: scriptOutput, code, signal });
          });
        });
      } else if (task.handler === 'jules_automation') {
        result = await this.executeJulesAutomation(task);
      } else {
        throw new Error(`Unknown handler: ${task.handler}`);
      }

      // Update DB with success
      this.updateTaskStatus(task.id, 'success', result);
      logInfo('ScheduledTasksRunner', `Task executed successfully: ${task.title}`);

    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      logError('ScheduledTasksRunner', `Task execution failed (${task.title}): ${errorMsg}`);
      this.updateTaskStatus(task.id, 'failed', { error: errorMsg });
    }
  }

  private parseTaskMetadata(task: ScheduledTask): Record<string, unknown> {
    if (!task.metadata) {
      return {};
    }

    try {
      return JSON.parse(task.metadata) as Record<string, unknown>;
    } catch (error) {
      logWarn('ScheduledTasksRunner', `Invalid metadata JSON for task ${task.id}: ${error}`);
      return {};
    }
  }

  private async executeJulesAutomation(task: ScheduledTask): Promise<Record<string, unknown>> {
    const metadata = this.parseTaskMetadata(task);
    const actions = Array.isArray(metadata.actions)
      ? (metadata.actions as JulesAutomationAction[])
      : [];

    if (actions.length === 0) {
      logWarn('ScheduledTasksRunner', `Jules task ${task.id} has no actions, skipping.`);
      return {
        handler: 'jules_automation',
        executed: 0,
        skipped: 0,
        failed: 0,
        details: ['No actions found in task metadata'],
      };
    }

    const details: string[] = [];
    let executed = 0;
    let skipped = 0;
    let failed = 0;

    for (const action of actions) {
      const label = `${action.type}:${action.target}`;

      // First useful integration: wire Jules "scan/suggested-tasks" to existing scanner endpoint.
      if (action.type === 'scan' && action.target === 'suggested-tasks') {
        try {
          const response = await fetch('http://localhost:3000/api/v1/suggested-tasks/scan', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
              source: 'jules_automation',
              taskId: task.id,
              ruleId: metadata.ruleId,
              params: action.params || {},
            }),
            signal: AbortSignal.timeout(30_000),
          });

          const payload = await response.json();
          executed++;
          details.push(`${label} -> ok (${response.status})`);
          details.push(`scan result: ${JSON.stringify(payload).slice(0, 400)}`);
        } catch (error) {
          failed++;
          details.push(`${label} -> failed (${error})`);
        }
        continue;
      }

      skipped++;
      details.push(`${label} -> skipped (no native executor yet)`);
      logWarn('ScheduledTasksRunner', `Jules action skipped for task ${task.id}: ${label}`);
    }

    return {
      handler: 'jules_automation',
      ruleId: metadata.ruleId,
      executed,
      skipped,
      failed,
      details,
    };
  }

  /**
   * Update task status in database
   */
  private updateTaskStatus(id: string, status: 'success' | 'failed', result: any) {
    try {
      const db = getGlobalDb();
      const now = new Date().toISOString();
      db.prepare(`
        UPDATE scheduled_tasks 
        SET last_run_at = ?, last_status = ?, last_result = ?
        WHERE id = ?
      `).run(now, status, JSON.stringify(result), id);
    } catch (error) {
      logError('ScheduledTasksRunner', `Failed to update task status in DB: ${error}`);
    }
  }
}

// Singleton instance
export const scheduledTasksRunner = new ScheduledTasksRunner();

import cron from 'node-cron';
import { spawn } from 'child_process';
import { v4 as uuidv4 } from 'uuid';
import { logInfo, logError } from '../../utils/logger.js';
import {
  saveTestRun,
  getTestStats,
  deleteOldTestRuns,
  type TestRun
} from '../../core/testResultsService.js';

export interface TestRunnerConfig {
  schedule: string;
  enabled: boolean;
  triggerType: 'scheduled' | 'manual' | 'api';
}

let schedulerTask: cron.ScheduledTask | null = null;

export async function runTests(triggerType: 'scheduled' | 'manual' | 'api' = 'manual'): Promise<TestRun> {
  const runId = uuidv4();
  const startedAt = new Date();

  const run: TestRun = {
    id: runId,
    scheduledTime: startedAt.toISOString(),
    startedAt: startedAt.toISOString(),
    status: 'running',
    triggerType,
    totalTests: 0,
    passed: 0,
    failed: 0,
    skipped: 0,
    duration: 0,
    output: '',
    errorLog: '',
    hostname: process.env.HOSTNAME || 'local',
    created_at: startedAt.toISOString()
  };

  try {
    logInfo('TestRunner', `Starting test run ${runId} (trigger: ${triggerType})...`);

    const { output, exitCode } = await executeTests();

    run.endedAt = new Date().toISOString();
    run.duration = new Date(run.endedAt).getTime() - new Date(run.startedAt).getTime();
    run.output = output;
    run.status = exitCode === 0 ? 'passed' : 'failed';

    // Parse vitest output for stats
    const stats = parseTestOutput(output);
    run.totalTests = stats.total;
    run.passed = stats.passed;
    run.failed = stats.failed;
    run.skipped = stats.skipped;

    await saveTestRun(run);
    logInfo('TestRunner', `Test run ${runId} completed. Status: ${run.status}, Passed: ${stats.passed}, Failed: ${stats.failed}`);

    return run;
  } catch (err: unknown) {
    const msg = err instanceof Error ? err.message : String(err);
    run.status = 'failed';
    run.errorLog = msg;
    run.endedAt = new Date().toISOString();
    run.duration = new Date(run.endedAt).getTime() - new Date(run.startedAt).getTime();
    await saveTestRun(run);
    logError('TestRunner', `Test run ${runId} failed: ${msg}`);
    return run;
  } finally {
    // Clean up old test runs (> 30 days)
    try {
      const deletedCount = await deleteOldTestRuns(30);
      if (deletedCount > 0) {
        logInfo('TestRunner', `Cleaned up ${deletedCount} old test runs`);
      }
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : String(e);
      logError('TestRunner', `Failed to clean up old test runs: ${msg}`);
    }
  }
}

export function startScheduler() {
  const schedule = process.env.TEST_SCHEDULE || '0 2 * * *'; // 2 AM daily
  const enabled = process.env.TEST_SCHEDULER_ENABLED !== 'false';

  if (!enabled) {
    logInfo('TestScheduler', 'Test scheduler is disabled (TEST_SCHEDULER_ENABLED=false)');
    return;
  }

  if (!cron.validate(schedule)) {
    logError('TestScheduler', `Invalid cron expression: ${schedule}`);
    return;
  }

  logInfo('TestScheduler', `Initializing test scheduler with cron expression: ${schedule}`);

  schedulerTask = cron.schedule(schedule, async () => {
    logInfo('TestScheduler', 'Scheduled test run triggered');
    try {
      const result = await runTests('scheduled');
      if (result.status === 'failed') {
        logError('TestScheduler', `Scheduled test run failed: ${result.errorLog}`);
      }
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : String(err);
      logError('TestScheduler', `Scheduled test run exception: ${msg}`);
    }
  });

  logInfo('TestScheduler', `Test scheduler active with schedule: ${schedule}`);
}

export function stopScheduler() {
  if (schedulerTask) {
    schedulerTask.stop();
    schedulerTask = null;
    logInfo('TestScheduler', 'Test scheduler stopped');
  }
}

export function getSchedulerStatus() {
  return {
    active: schedulerTask ? true : false,
    schedule: process.env.TEST_SCHEDULE || '0 2 * * *',
    enabled: process.env.TEST_SCHEDULER_ENABLED !== 'false'
  };
}

async function executeTests(): Promise<{ output: string; exitCode: number }> {
  return new Promise((resolve, reject) => {
    const proc = spawn('npm', ['test', '--run'], {
      cwd: process.cwd(),
      stdio: ['ignore', 'pipe', 'pipe'],
      timeout: 10 * 60 * 1000 // 10 minute timeout
    });

    let output = '';
    let errorOutput = '';

    const timeout = setTimeout(() => {
      proc.kill();
      reject(new Error('Test execution timeout (10 minutes)'));
    }, 10 * 60 * 1000);

    const handleClose = (code: number | null) => {
      clearTimeout(timeout);
      const exitCode = code ?? 1;
      const fullOutput = output + (errorOutput ? `\n\n=== STDERR ===\n${errorOutput}` : '');
      resolve({ output: fullOutput, exitCode });
    };

    proc.stdout?.on('data', (chunk) => {
      output += chunk.toString();
    });

    proc.stderr?.on('data', (chunk) => {
      errorOutput += chunk.toString();
    });

    proc.on('close', handleClose);

    proc.on('error', (err) => {
      clearTimeout(timeout);
      reject(err);
    });
  });
}

function parseTestOutput(output: string): { total: number; passed: number; failed: number; skipped: number } {
  // Parse vitest output format
  // Look for patterns like: "✓ 45 passed ... × 2 failed ... ⊙ 1 skipped"
  
  const passedMatch = output.match(/✓\s+(\d+)\s+pass/);
  const failedMatch = output.match(/×\s+(\d+)\s+fail/);
  const skippedMatch = output.match(/⊙\s+(\d+)\s+skip/);

  const passed = passedMatch ? parseInt(passedMatch[1], 10) : 0;
  const failed = failedMatch ? parseInt(failedMatch[1], 10) : 0;
  const skipped = skippedMatch ? parseInt(skippedMatch[1], 10) : 0;

  const total = passed + failed + skipped;

  return { total, passed, failed, skipped };
}

/**
 * Gold Protocol G7.1: Spec Management API Routes
 *
 * RULE-UI3: CLI és Dashboard ugyanazon API-t használja
 * RULE-UI4: Routes külön *Routes.ts fájlokban (clean separation)
 *
 * Endpoints:
 *   GET /api/specs - List all specs with status
 *   GET /api/specs/:trackId - Get spec details
 *   POST /api/specs/:trackId/approve - Approve spec
 *   POST /api/specs/:trackId/reject - Reject spec
 */

import { Router } from 'express';
import {
  listSpecStatuses,
  getSpecStatus,
  approveSpec,
  rejectSpec,
  isSpecApproved,
} from '../agents/specStatus.js';
import { logInfo } from '../utils/logger.js';
import { socketService } from './SocketService.js';
import fs from 'fs/promises';
import path from 'path';

export function createSpecRouter(): Router {
  const router = Router();

  /**
   * GET /api/specs
   * List all tracks with their spec statuses
   */
  router.get('/', async (_req, res) => {
    try {
      const specs = await listSpecStatuses();
      res.json({ specs });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * GET /api/specs/:trackId
   * Get detailed spec information for a specific track
   */
  router.get('/:trackId', async (req, res) => {
    try {
      const { trackId } = req.params;
      const status = await getSpecStatus(trackId);
      const approved = await isSpecApproved(trackId);

      // Try to read spec.md content
      const specPath = path.join(process.cwd(), 'conductor', 'tracks', trackId, 'spec.md');
      let content = '';
      try {
        content = await fs.readFile(specPath, 'utf-8');
      } catch {
        // spec.md not found
      }

      // Try to read plan.md content
      const planPath = path.join(process.cwd(), 'conductor', 'tracks', trackId, 'plan.md');
      let plan = '';
      try {
        plan = await fs.readFile(planPath, 'utf-8');
      } catch {
        // plan.md not found
      }

      res.json({
        trackId,
        status,
        approved,
        specContent: content,
        planContent: plan,
      });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * POST /api/specs/:trackId/approve
   * Approve a track specification
   */
  router.post('/:trackId/approve', async (req, res) => {
    try {
      const { trackId } = req.params;
      const success = await approveSpec(trackId);

      if (success) {
        logInfo('SpecRoutes', `Spec approved via API: ${trackId}`);
        socketService.emit('gold:spec_changed', { trackId, spec_status: 'approved', timestamp: new Date().toISOString() });
        res.json({ success: true, message: `Spec approved for track: ${trackId}` });
      } else {
        res.status(400).json({ success: false, message: 'Failed to approve spec' });
      }
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * POST /api/specs/:trackId/reject
   * Reject a track specification
   */
  router.post('/:trackId/reject', async (req, res) => {
    try {
      const { trackId } = req.params;
      const { reason } = req.body;
      const success = await rejectSpec(trackId, reason);

      if (success) {
        logInfo('SpecRoutes', `Spec rejected via API: ${trackId} (reason: ${reason || 'none'})`);
        socketService.emit('gold:spec_changed', { trackId, spec_status: 'rejected', reason, timestamp: new Date().toISOString() });
        res.json({ success: true, message: `Spec rejected for track: ${trackId}` });
      } else {
        res.status(400).json({ success: false, message: 'Failed to reject spec' });
      }
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  return router;
}

// FILE: src/server/telemetryRoutes.ts
// PURPOSE: G5.2 — Token Cost Dashboard API (RULE-OB1→OB4)
//
// Endpoints:
//   GET /api/telemetry/usage   → { today, week, month, byAgent, byModel }
//   GET /api/telemetry/traces  → recent trace list
//   GET /api/telemetry/traces/:traceId → TraceSpan[]
//   GET /api/telemetry/cost    → { totalCost, breakdown }
//   GET /api/telemetry/stats   → tracer health stats

import { Router } from 'express';
import {
  getTraceSpans,
  getRecentSpans,
  getActiveSpans,
  getTokenUsageSummary,
  getRecentTraceIds,
  getTracerStats,
  type TraceSpan,
} from '../utils/agentTracer.js';

// Cost rates per 1K tokens (USD) — configurable via env
const COST_PER_1K: Record<string, { input: number; output: number }> = {
  'gpt-4o':            { input: 0.005,  output: 0.015 },
  'gemini-2.5-flash':  { input: 0.00015, output: 0.0006 },
  'llama3.1:8b':       { input: 0,      output: 0 },       // Local — free
  'qwen2.5-coder:7b':  { input: 0,      output: 0 },       // Local — free
};

function calculateCost(spans: TraceSpan[]): { totalCost: number; breakdown: Record<string, number> } {
  const breakdown: Record<string, number> = {};
  let totalCost = 0;

  for (const span of spans) {
    if (!span.tokenUsage) continue;
    const model = (span.metadata.model as string) || 'unknown';
    const rates = COST_PER_1K[model] || { input: 0.001, output: 0.003 }; // default fallback

    const cost =
      (span.tokenUsage.input / 1000) * rates.input +
      (span.tokenUsage.output / 1000) * rates.output;

    totalCost += cost;
    breakdown[model] = (breakdown[model] || 0) + cost;
  }

  return { totalCost: Math.round(totalCost * 1_000_000) / 1_000_000, breakdown };
}

function filterByTimeRange(spans: TraceSpan[], sinceMs: number): TraceSpan[] {
  const cutoff = Date.now() - sinceMs;
  return spans.filter(s => s.startTime >= cutoff);
}

export function createTelemetryRouter(): Router {
  const router = Router();

  /**
   * GET /api/telemetry/usage
   * Token usage summary for today / week / month
   */
  router.get('/usage', (_req, res) => {
    try {
      const allSpans = getRecentSpans(2000);

      const todaySpans = filterByTimeRange(allSpans, 24 * 60 * 60 * 1000);
      const weekSpans  = filterByTimeRange(allSpans, 7 * 24 * 60 * 60 * 1000);

      const sumTokens = (spans: TraceSpan[]) => {
        let input = 0, output = 0;
        for (const s of spans) {
          if (s.tokenUsage) {
            input += s.tokenUsage.input;
            output += s.tokenUsage.output;
          }
        }
        return { input, output, total: input + output };
      };

      const summary = getTokenUsageSummary();

      res.json({
        today: sumTokens(todaySpans),
        week: sumTokens(weekSpans),
        month: { input: summary.totalInput, output: summary.totalOutput, total: summary.totalInput + summary.totalOutput },
        byAgent: summary.byAgent,
        byModel: summary.byModel,
      });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * GET /api/telemetry/traces
   * List of recent trace IDs with basic info
   */
  router.get('/traces', (req, res) => {
    try {
      const limit = parseInt(req.query.limit as string) || 20;
      const traceIds = getRecentTraceIds(limit);

      const traces = traceIds.map(traceId => {
        const spans = getTraceSpans(traceId);
        const rootSpan = spans[0]; // First span = root
        return {
          traceId,
          rootAgent: rootSpan?.agentName || 'unknown',
          operation: rootSpan?.operation || 'unknown',
          status: rootSpan?.status || 'unknown',
          startTime: rootSpan?.startTime,
          duration: rootSpan?.duration,
          spanCount: spans.length,
        };
      });

      res.json({ traces });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * GET /api/telemetry/traces/:traceId
   * Full span hierarchy for a specific trace
   */
  router.get('/traces/:traceId', (req, res) => {
    try {
      const { traceId } = req.params;
      const spans = getTraceSpans(traceId);

      if (spans.length === 0) {
        res.status(404).json({ error: 'Trace not found' });
        return;
      }

      res.json({ traceId, spans });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * GET /api/telemetry/cost
   * Estimated cost breakdown by model
   */
  router.get('/cost', (_req, res) => {
    try {
      const allSpans = getRecentSpans(2000);
      const cost = calculateCost(allSpans);
      res.json(cost);
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  /**
   * GET /api/telemetry/stats
   * Tracer health / status
   */
  router.get('/stats', (_req, res) => {
    try {
      const stats = getTracerStats();
      const active = getActiveSpans();
      res.json({
        ...stats,
        activeSpanDetails: active.map(s => ({
          spanId: s.spanId,
          agent: s.agentName,
          operation: s.operation,
          runningFor: Date.now() - s.startTime,
        })),
      });
    } catch (e: any) {
      res.status(500).json({ error: e.message });
    }
  });

  return router;
}

/**
 * Tracks Management API Routes
 *
 * EPP v2 Protocol: Track generation and management endpoints
 * RULE-UI3: CLI és Dashboard ugyanazon API-t használja
 * RULE-UI4: Routes külön *Routes.ts fájlokban (clean separation)
 *
 * Endpoints:
 *   POST /api/tracks/generate - Generate track from idea (3-stage LLM pipeline)
 *   GET /api/tracks - List all tracks with metadata
 *   GET /api/tracks/:trackId - Get specific track details
 */

import { Router } from "express";
import { agentManager } from "../agents/AgentManager.js";
import { logInfo, logError } from "../utils/logger.js";
import { socketService } from "./SocketService.js";
import chokidar, { type FSWatcher } from "chokidar";
import fs from "fs/promises";
import path from "path";

type TrackTodoItem = {
  id: string;
  text: string;
  completed: boolean;
};

type TrackTodosResponse = {
  trackId: string;
  title: string;
  todos: TrackTodoItem[];
  progress: number;
  completedCount: number;
  totalCount: number;
  updatedAt: string;
};

function getTracksDir(override?: string): string {
  const env = process.env.BRUNELLA_CONDUCTOR_TRACKS_DIR;
  const base =
    override ||
    (typeof env === "string" && env.trim() ? env.trim() : undefined);
  return base
    ? path.resolve(process.cwd(), base)
    : path.join(process.cwd(), "conductor", "tracks");
}

function isSafeTrackId(trackId: string): boolean {
  // Prevent path traversal, allow common IDs like: foo-bar_20260211
  return /^[a-z0-9][a-z0-9_-]*$/i.test(trackId);
}

function parseTrackTitle(markdown: string, fallback: string): string {
  const first = markdown.split("\n").find((l) => l.startsWith("# "));
  return first ? first.replace(/^#\s+/, "").trim() : fallback;
}

function parseTodosFromMarkdown(markdown: string): TrackTodoItem[] {
  const lines = markdown.split("\n");
  const items: TrackTodoItem[] = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const m = /^\s*[-*]\s+\[( |x|X)\]\s+(.*\S)\s*$/.exec(line);
    if (!m) continue;
    items.push({
      id: `line:${i}`,
      completed: m[1].toLowerCase() === "x",
      text: m[2].trim(),
    });
  }
  return items;
}

function toggleTodoLine(
  markdown: string,
  lineIndex: number,
  desired?: boolean,
): string {
  const lines = markdown.split("\n");
  if (lineIndex < 0 || lineIndex >= lines.length) {
    throw new Error(`Todo line out of range: ${lineIndex}`);
  }
  const line = lines[lineIndex];
  const m = /^(\s*[-*]\s+)\[( |x|X)\](\s+.*)$/.exec(line);
  if (!m) {
    throw new Error(`Line is not a checkbox todo: ${lineIndex}`);
  }
  const current = m[2].toLowerCase() === "x";
  const next = typeof desired === "boolean" ? desired : !current;
  lines[lineIndex] = `${m[1]}[${next ? "x" : " "}]${m[3]}`;
  return lines.join("\n");
}

async function readTrackMarkdown(
  tracksDir: string,
  trackId: string,
): Promise<string> {
  const trackPath = path.join(tracksDir, trackId, "track.md");
  return await fs.readFile(trackPath, "utf-8");
}

async function writeTrackMarkdown(
  tracksDir: string,
  trackId: string,
  markdown: string,
): Promise<void> {
  const trackPath = path.join(tracksDir, trackId, "track.md");
  await fs.writeFile(trackPath, markdown, "utf-8");
}

async function buildTodosResponse(
  tracksDir: string,
  trackId: string,
): Promise<TrackTodosResponse> {
  const content = await readTrackMarkdown(tracksDir, trackId);
  const title = parseTrackTitle(content, trackId);
  const todos = parseTodosFromMarkdown(content);
  const totalCount = todos.length;
  const completedCount = todos.filter((t) => t.completed).length;
  const progress =
    totalCount > 0 ? Math.round((completedCount / totalCount) * 100) : 0;
  return {
    trackId,
    title,
    todos,
    progress,
    completedCount,
    totalCount,
    updatedAt: new Date().toISOString(),
  };
}

type TrackTodoSummary = {
  trackId: string;
  title: string;
  status?: string;
  progress: number;
  completedCount: number;
  totalCount: number;
};

async function readTrackMeta(
  tracksDir: string,
  trackId: string,
): Promise<Record<string, unknown> | null> {
  const p = path.join(tracksDir, trackId, "meta.json");
  try {
    const raw = await fs.readFile(p, "utf-8");
    return JSON.parse(raw) as Record<string, unknown>;
  } catch {
    return null;
  }
}

async function listTrackTodoSummaries(
  tracksDir: string,
  filterStatus?: (s: string | undefined) => boolean,
): Promise<TrackTodoSummary[]> {
  const entries = await fs.readdir(tracksDir, { withFileTypes: true });
  const out: TrackTodoSummary[] = [];
  for (const e of entries) {
    if (!e.isDirectory()) continue;
    const trackId = e.name;
    if (!isSafeTrackId(trackId)) continue;

    const meta = await readTrackMeta(tracksDir, trackId);
    const status =
      typeof meta?.status === "string" ? (meta.status as string) : undefined;
    if (filterStatus && !filterStatus(status)) continue;

    try {
      const r = await buildTodosResponse(tracksDir, trackId);
      out.push({
        trackId,
        title: r.title,
        status,
        progress: r.progress,
        completedCount: r.completedCount,
        totalCount: r.totalCount,
      });
    } catch {
      // ignore tracks without track.md
    }
  }
  return out;
}

let watcherStarted = false;
let tracksWatcher: FSWatcher | null = null;

function toChokidarGlob(p: string): string {
  // chokidar globs are most reliable with forward slashes (esp. on Windows)
  return p.replaceAll("\\", "/");
}

function emitTrackChanged(trackId: string, reason?: string): void {
  socketService.emit("track:changed", {
    trackId,
    reason,
    timestamp: new Date().toISOString(),
  });
}

function startTrackWatcher(tracksDir: string): void {
  if (watcherStarted) return;
  watcherStarted = true;

  // Debounce bursty fs events (save can trigger multiple change events)
  const lastEmittedAt = new Map<string, number>();
  const shouldEmit = (key: string) => {
    const now = Date.now();
    const prev = lastEmittedAt.get(key) ?? 0;
    if (now - prev < 250) return false;
    lastEmittedAt.set(key, now);
    return true;
  };

  try {
    const trackGlob = toChokidarGlob(path.join(tracksDir, "*", "track.md"));
    const metaGlob = toChokidarGlob(path.join(tracksDir, "*", "meta.json"));

    tracksWatcher = chokidar.watch([trackGlob, metaGlob], {
      ignoreInitial: true,
      awaitWriteFinish: {
        stabilityThreshold: 200,
        pollInterval: 50,
      },
    });

    const onFsEvent = (event: string, filePath: string) => {
      const dir = path.basename(path.dirname(filePath));
      const base = path.basename(filePath);
      const trackId = dir;
      if (!trackId || !isSafeTrackId(trackId)) return;

      const key = `${trackId}:${base}`;
      if (!shouldEmit(key)) return;

      emitTrackChanged(trackId, `${event}:${base}`);
    };

    tracksWatcher
      .on("add", (p) => onFsEvent("add", p))
      .on("change", (p) => onFsEvent("change", p))
      .on("unlink", (p) => onFsEvent("unlink", p))
      .on("error", (err) => {
        logError(
          "TracksRoutes",
          `Track watcher error: ${err instanceof Error ? err.message : String(err)}`,
        );
      });

    logInfo("TracksRoutes", `Track watcher started (chokidar): ${tracksDir}`);
  } catch (e: unknown) {
    // If watcher cannot start, keep API functional (best-effort).
    logError(
      "TracksRoutes",
      `Track watcher failed to start: ${e instanceof Error ? e.message : String(e)}`,
    );
  }
}

export function createTracksRouter(opts?: {
  tracksDir?: string;
  enableWatcher?: boolean;
}): Router {
  const router = Router();
  const tracksDir = getTracksDir(opts?.tracksDir);
  const enableWatcher = opts?.enableWatcher !== false;
  if (enableWatcher) startTrackWatcher(tracksDir);

  /**
   * GET /api/tracks/todos
   * Returns todo summaries for all tracks.
   */
  router.get("/todos", async (_req, res) => {
    try {
      const tracks = await listTrackTodoSummaries(tracksDir);
      res.json({ success: true, count: tracks.length, tracks });
    } catch (e: any) {
      res.status(500).json({ success: false, error: e?.message ?? String(e) });
    }
  });

  /**
   * GET /api/tracks/todos/active
   * Returns todo summaries for active-ish tracks only.
   */
  router.get("/todos/active", async (_req, res) => {
    try {
      const active = await listTrackTodoSummaries(
        tracksDir,
        (s) => s === "active" || s === "in_progress" || s === "testing",
      );
      res.json({ success: true, count: active.length, tracks: active });
    } catch (e: any) {
      res.status(500).json({ success: false, error: e?.message ?? String(e) });
    }
  });

  /**
   * POST /api/tracks/generate
   * Generate EPP v2 compliant track from creative idea
   *
   * Request body:
   * {
   *   "idea": "Natural language idea (2-5 sentences, magyar OK)"
   * }
   *
   * Response:
   * {
   *   "success": true,
   *   "trackId": "track-name-20260211",
   *   "trackPath": "conductor/tracks/track-name-20260211",
   *   "preview": "# Track Title\n\n..."
   * }
   */
  router.post("/generate", async (req, res) => {
    try {
      const { idea } = req.body;

      if (!idea || typeof idea !== "string") {
        return res.status(400).json({
          success: false,
          error: 'Missing or invalid "idea" field in request body',
        });
      }

      logInfo(
        "TracksRoutes",
        `Generating track from idea: ${idea.slice(0, 60)}...`,
      );

      // Execute SpecWriterAgent with 3-stage pipeline
      const agent = agentManager.getAgent("SpecWriter");
      if (!agent) {
        return res.status(500).json({
          success: false,
          error: "SpecWriterAgent not registered in AgentManager",
        });
      }

      const result = (await agent.execute("Generate track", {
        metadata: { idea },
      })) as {
        status: "success" | "error";
        data?: any;
        error?: string;
      };

      if (result.status === "error") {
        logError("TracksRoutes", `Track generation failed: ${result.error}`);
        return res.status(500).json({
          success: false,
          error: result.error,
        });
      }

      const data = result.data as any;

      // Emit WebSocket event for real-time updates
      socketService.emit("track:generated", {
        trackId: data.trackId,
        timestamp: new Date().toISOString(),
      });

      logInfo("TracksRoutes", `✅ Track generated: ${data.trackId}`);

      res.json({
        success: true,
        trackId: data.trackId,
        trackPath: data.trackPath,
        trackFile: data.trackFile,
        preview: data.preview,
      });
    } catch (e: any) {
      logError("TracksRoutes", `Generate endpoint error: ${e.message}`);
      res.status(500).json({
        success: false,
        error: e.message,
      });
    }
  });

  /**
   * GET /api/tracks
   * List all tracks from conductor/tracks/ directory
   *
   * Response:
   * {
   *   "success": true,
   *   "tracks": [
   *     {
   *       "id": "track-name-20260211",
   *       "title": "Track Title",
   *       "priority": "P0",
   *       "progress": 0,
   *       "path": "conductor/tracks/track-name-20260211/track.md"
   *     }
   *   ]
   * }
   */
  router.get("/", async (_req, res) => {
    try {
      const agent = agentManager.getAgent("SpecWriter");
      if (!agent) {
        return res.status(500).json({
          success: false,
          error: "SpecWriterAgent not registered",
        });
      }

      // Call listTracks() method
      const result = (await (agent as any).listTracks()) as {
        success: boolean;
        message: string;
        data?: { tracks: any[] };
      };

      if (!result.success) {
        return res.status(500).json({
          success: false,
          error: result.message,
        });
      }

      const tracks = result.data?.tracks || [];

      res.json({
        success: true,
        count: tracks.length,
        tracks,
      });
    } catch (e: any) {
      logError("TracksRoutes", `List endpoint error: ${e.message}`);
      res.status(500).json({
        success: false,
        error: e.message,
      });
    }
  });

  /**
   * GET /api/tracks/:trackId
   * Get detailed track information (read track.md content)
   *
   * Response:
   * {
   *   "success": true,
   *   "trackId": "track-name-20260211",
   *   "content": "# Track Title\n\n...",
   *   "metadata": {
   *     "title": "Track Title",
   *     "priority": "P0",
   *     "progress": 0
   *   }
   * }
   */
  router.get("/:trackId", async (req, res) => {
    try {
      const { trackId } = req.params;

      if (!trackId || !isSafeTrackId(trackId)) {
        return res
          .status(400)
          .json({ success: false, error: "Invalid trackId" });
      }

      // Read track.md file
      const trackPath = path.join(tracksDir, trackId, "track.md");

      let content = "";
      try {
        content = await fs.readFile(trackPath, "utf-8");
      } catch (e: any) {
        logError("TracksRoutes", `Track not found: ${trackId}`);
        return res.status(404).json({
          success: false,
          error: `Track not found: ${trackId}`,
        });
      }

      // Extract metadata from track.md (first 20 lines)
      const lines = content.split("\n").slice(0, 20);
      const title =
        lines
          .find((l) => l.startsWith("# "))
          ?.replace("# ", "")
          .trim() || trackId;
      const priorityMatch = lines.find((l) => l.includes("**Priority:**"));
      const priority = priorityMatch?.match(/P[0-2]/)?.[0] || "P2";
      const progressMatch = lines.find((l) => l.includes("**Progress:**"));
      const progress = parseInt(progressMatch?.match(/\d+/)?.[0] || "0");
      const createdMatch = lines.find((l) => l.includes("**Created:**"));
      const created =
        createdMatch?.match(/\d{4}-\d{2}-\d{2}/)?.[0] || "unknown";

      res.json({
        success: true,
        trackId,
        content,
        metadata: {
          title,
          priority,
          progress,
          created,
          path: trackPath,
        },
      });
    } catch (e: any) {
      logError("TracksRoutes", `Get endpoint error: ${e.message}`);
      res.status(500).json({
        success: false,
        error: e.message,
      });
    }
  });

  /**
   * GET /api/tracks/:trackId/todos
   * Parse all checkbox TODOs from track.md.
   */
  router.get("/:trackId/todos", async (req, res) => {
    try {
      const { trackId } = req.params;
      if (!trackId || !isSafeTrackId(trackId)) {
        return res
          .status(400)
          .json({ success: false, error: "Invalid trackId" });
      }

      const data = await buildTodosResponse(tracksDir, trackId);
      res.json({ success: true, ...data });
    } catch (e: any) {
      const msg = e?.message ?? String(e);
      const status = /not found/i.test(msg) ? 404 : 500;
      res.status(status).json({ success: false, error: msg });
    }
  });

  /**
   * PATCH /api/tracks/:trackId/todos/:todoId
   * Toggle a specific checkbox line by id=line:<n>
   */
  router.patch("/:trackId/todos/:todoId", async (req, res) => {
    try {
      const { trackId, todoId } = req.params;
      if (!trackId || !isSafeTrackId(trackId)) {
        return res
          .status(400)
          .json({ success: false, error: "Invalid trackId" });
      }

      const m = /^line:(\d+)$/.exec(String(todoId || ""));
      if (!m) {
        return res
          .status(400)
          .json({ success: false, error: "Invalid todoId" });
      }
      const lineIndex = parseInt(m[1], 10);
      const desired =
        typeof req.body?.completed === "boolean"
          ? (req.body.completed as boolean)
          : undefined;

      const current = await readTrackMarkdown(tracksDir, trackId);
      const next = toggleTodoLine(current, lineIndex, desired);
      await writeTrackMarkdown(tracksDir, trackId, next);

      socketService.emit("track:todo_updated", {
        trackId,
        todoId,
        timestamp: new Date().toISOString(),
      });

      const data = await buildTodosResponse(tracksDir, trackId);
      res.json({ success: true, ...data });
    } catch (e: any) {
      const msg = e?.message ?? String(e);
      res.status(500).json({ success: false, error: msg });
    }
  });

  return router;
}

