export async function startWebServer() {
  const webUiEnabled =
    process.env.WEB_UI_ENABLED !== "0" &&
    process.env.WEB_UI_ENABLED !== "false";
  if (!webUiEnabled) {
    logInfo("Server", "WEB_UI_ENABLED=0 -> Web UI disabled for current process");
    return;
  }

  try {
    initDb();
  } catch (e: any) {
    logError("Server", `DB Init failed: ${e.message}`);
  }

  try {
    initTasksDb();
  } catch (e: any) {
    logError("Server", `Tasks DB Init failed: ${e.message}`);
  }

  try {
    await initTestResultsDb("data/brunella.db");
  } catch (e: any) {
    logError("Server", `Test Results DB Init failed: ${e.message}`);
  }

  try {
    await initSuggestedTasksDb("data/brunella.db");
  } catch (e: any) {
    logError("Server", `Suggested Tasks DB Init failed: ${e.message}`);
  }

  initMetrics();

  logInfo("Server", "🔄 Starting MCP Bridge...");
  try {
    await mcpProcessManager.loadConfig();
    const configured = mcpProcessManager.getServersStatus();
    logInfo("Server", `📋 ${configured.length} MCP server(s) configured`);
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    logError("Server", `MCP config load failed: ${msg}`);
  }

  const app = express();
  
  app.use(express.json());
  app.use(corsWhitelist);
  app.use(requestId);
  app.use(requestLogging);
  app.use("/api", apiRateLimit);

  app.get("/api/browser/snapshot", (req, res) => {
    const screenshot = persistentBrowser.getLastScreenshot();
    if (screenshot) {
      res.setHeader("Content-Type", "image/png");
      res.send(screenshot);
    } else {
      res.status(404).send("No active browser session or screenshot available.");
    }
  });

  app.get("/metrics", async (_req, res) => {
    try {
      res.set("Content-Type", getPrometheusContentType());
      const metrics = await getPrometheusMetrics();
      res.end(metrics);
    } catch (e: unknown) {
      const message = e instanceof Error ? e.message : String(e);
      res.status(500).json({ error: message });
    }
  });

  app.use("/api-docs", swaggerUi.serve, swaggerUi.setup(swaggerSpec));

  const v1Router = createV1Router();
  v1Router.use("/telemetry", createTelemetryRouter());
  v1Router.use("/guardrails", createGuardrailsRouter());
  v1Router.use("/audit", createAuditRouter());
  v1Router.use("/specs", createSpecRouter());
  v1Router.use("/phoenix", createPhoenixRouter());
  v1Router.use("/router", createRouterRouter());
  v1Router.use("/memory", createMemoryRouter());
  v1Router.use("/mcp", mcpRouter);
  v1Router.use("/tracks", createTracksRouter());
  v1Router.use(ceanRouter);
  v1Router.use(createWranglerRouter());
  const db = getGlobalDb();
  v1Router.use("/fleet", createFleetRouter(db));
  v1Router.use("/workers", createWorkersRouter(db));
  v1Router.use("/metrics", createMetricsRouter(db));
  v1Router.use("/scaling", createScalingRouter(db));
  v1Router.use("/robotkez", createRobotkezRoutes());
  v1Router.use("/agents", createAgentRoutes());
  v1Router.use("/chat", createChatRoutes());
  v1Router.use("/tasks", createTaskRoutes());
  v1Router.use("/tests", testSchedulerRoutes);
  v1Router.use("/suggested-tasks", suggestedTasksRouter);
  v1Router.use("/enterprise", createEnterpriseRouter());
  v1Router.use("/python-workers", createPythonWorkersRouter());
  v1Router.use("/scheduled-tasks", createScheduledTasksRoutes(db));
  v1Router.use("/dashboard", createDashboardRoutes());
  v1Router.use("/business-jobs", createBusinessJobsRoutes());
  v1Router.use("/studio", createStudioRoutes());
  v1Router.use("/sales", salesRouter);
  v1Router.use("/grants", grantsRouter);
  v1Router.use("/webhooks", createWebhookRoutes(db));
  v1Router.use("/voice", voiceRouter);
  v1Router.use("/contact", contactRouter);
  v1Router.use("/swarm", swarmRouter);
  v1Router.use("/harvest", harvestRouter);
  v1Router.use("/crawl4ai", createCrawl4aiRouter());
  v1Router.use("/preferences", createPreferencesRouter());
  v1Router.use("/observability", createObservabilityRouter());
  v1Router.use("/golden-dataset", createGoldenDatasetRouter());

  app.use("/api/v1", v1Router);
  app.use("/api", v1Router);
  app.use("/api/orchestrator", createUniversalOrchestratorRouter());
  app.use("/api/paios", paiosOrchestratorRouter);
  app.use("/api/github", githubWebhookRouter);

  const httpServer = createServer(app);
  const io = new Server(httpServer, {
    cors: {
      origin:
        corsOriginList.length > 0
          ? corsOriginList
          : ["http://localhost:5173", "http://localhost:3000", "*"],
      methods: ["GET", "POST"],
    },
  });
  socketService.init(io);
  initializeAgentManager(socketService);

  agentManager.registerAgent(new InnovationBridgeAgent());
  agentManager.registerAgent(new DigitalHeadhunterAgent());
  agentManager.registerAgent(new GrantHunter());
  agentManager.registerAgent(new LawDetectiveAgent());
  agentManager.registerAgent(new PropertyVisionaryAgent());

  const { phoenixEventBus } = await import('../core/phoenixEventBus.js');
  phoenixEventBus.connectSocketBroadcaster((event: string, data: unknown) => {
    socketService.emit(event, data);
  });

  // Bridge pipelineRunner progress events to Socket.IO (BrunellaStudio + developer dashboard)
  const { pipelineRunner } = await import('../agents/developerPipeline.js');
  pipelineRunner.on('progress', (event: unknown) => {
    socketService.emit('developer:progress', event);
  });

  io.on("connection", (socket) => {
    const statuses = agentManager.listAgentStatuses();
    socket.emit('agents:snapshot', statuses);
    socket.on("robotkez:abort", async () => {
      await persistentBrowser.close();
      persistentBrowser.forceKill();
      socket.emit("robotkez:aborted", { status: "success", message: "Munkamenet megszakítva." });
    });
  });

  io.of('/robotkez-overlay').on('connection', (socket) => {
    socket.on('user_message', async (msg) => {
      try {
        const { robotkezBridge } = await import('../orchestrator/robotkez_bridge.js');
        const response = await robotkezBridge.handleMessage(msg.text);
        socket.emit('message', { text: response });
      } catch (e: any) {
        socket.emit('message', { text: `Hiba történt: ${e.message}` });
      }
    });
  });

  registerEdgeWebSocketHandlers(io);
  registerCEANWebSocketHandlers(io);
  registerFleetWebSocketHandlers(io);

  const agentLogBuffer = new Map<string, LogEvent[]>();
  const MAX_AGENT_LOGS = 500;
  let requestCount = 0;
  let errorCount = 0;
  let lastMinuteRequests = 0;
  let lastMinuteErrors = 0;

  setInterval(() => {
    lastMinuteRequests = requestCount;
    lastMinuteErrors = errorCount;
    requestCount = 0;
    errorCount = 0;
  }, 60000);

  app.use((_req, res, next) => {
    const requestStart = Date.now();
    requestCount++;
    res.on("finish", () => {
      if (res.statusCode >= 400) errorCount++;
      const durationMs = Date.now() - requestStart;
      const method = _req.method || "UNKNOWN";
      const routePath = _req.route?.path ? String(_req.route.path) : _req.path || "unknown";
      recordHttpRequest(method, routePath, res.statusCode, durationMs);
    });
    next();
  });

  logEmitter.on("log", (entry: LogEvent) => {
    const source = entry.agent || entry.source;
    const type = entry.level === "error" ? "error" : entry.level === "success" ? "success" : "info";
    socketService.broadcastLog(entry.message, type, source);
    if (entry.agent) {
      const list = agentLogBuffer.get(entry.agent) || [];
      list.push(entry);
      if (list.length > MAX_AGENT_LOGS) list.splice(0, list.length - MAX_AGENT_LOGS);
      agentLogBuffer.set(entry.agent, list);
    }
  });

  logEmitter.on("agent_status", (entry: AgentStatusEvent) => {
    socketService.updateAgentStatus(entry.agent, entry.status as any, entry.task);
  });

  setInterval(() => {
    const totalMem = os.totalmem();
    const freeMem = os.freemem();
    const cpus = os.cpus();
    const cpuUsage = cpus.reduce((acc, cpu) => {
      const total = Object.values(cpu.times).reduce((a, b) => a + b, 0);
      return acc + ((total - cpu.times.idle) / total) * 100;
    }, 0) / cpus.length;
    io.emit("metrics_update", {
      requestsPerMinute: lastMinuteRequests,
      activeConnections: io.sockets.sockets.size,
      errorRate: lastMinuteRequests > 0 ? (lastMinuteErrors / lastMinuteRequests) * 100 : 0,
      averageResponseTime: 0,
      cpuUsage: Math.round(cpuUsage * 100) / 100,
      memoryUsage: ((totalMem - freeMem) / totalMem) * 100,
    });
    io.emit("mcp_servers_status", mcpProcessManager.getServersStatus());
    io.emit("agent_update", agentManager.listAgentDefinitions());
    io.emit("tools_update", toolManager.getToolDefinitions());
    io.emit("tasks_update", agentManager.getAllTasks());
  }, 5000);

  const mcpSessions = new Map<string, ActiveTransport>();

  app.get("/sse", async (req, res) => {
    const sessionId = uuidv4();
    const transport = new SSEServerTransport(`/messages?sessionId=${sessionId}`, res);
    const server = new McpServer({ name: "mcp-brunella-core-web", version: PACKAGE_VERSION });
    await registerAllTools(server);
    mcpSessions.set(sessionId, { transport, server });
    res.on("close", () => mcpSessions.delete(sessionId));
    await server.connect(transport);
  });

  app.post("/messages", async (req, res) => {
    const sessionId = req.query.sessionId as string;
    if (!sessionId || !mcpSessions.has(sessionId)) {
      res.status(404).send("Session not found");
      return;
    }
    const { transport } = mcpSessions.get(sessionId)!;
    await transport.handlePostMessage(req, res);
  });

  // STATIC ASSETS
  app.use(express.static(path.join(process.cwd(), "build", "public")));

  // ROOT FALLBACK
  app.get("/", (_req, res) => {
    const indexPath = path.join(process.cwd(), "build", "public", "index.html");
    if (existsSync(indexPath)) {
      res.sendFile(indexPath);
    } else {
      res.redirect("http://localhost:5173");
    }
  });

  // SPA FALLBACK (SAFE VERSION)
  app.use((req, res, next) => {
    if (req.path.startsWith("/api") || req.path.startsWith("/socket.io") || req.path.startsWith("/audio")) {
      return next();
    }
    const indexPath = path.join(process.cwd(), "build", "public", "index.html");
    if (existsSync(indexPath)) {
      res.sendFile(indexPath);
    } else {
      next();
    }
  });

  // Start Sync
  syncService.start();

  app.use(globalErrorHandler);

  startScheduler();
  startCronScheduler();
  scheduledTasksRunner.start();
  const { trackStateManager } = await import("../services/trackStateManager.js");
  await trackStateManager.fullSync();
  trackStateManager.startWatcher();
  heartbeatMonitor.start();

  httpServer.listen(config.port, () => {
    logInfo("Server", `🌐 Web UI: http://localhost:${config.port}`);
  });
}

import { Server, Socket } from "socket.io";
import { logInfo, logError } from "../utils/logger.js";
import { cloudflareClient } from "../agents/cloudflare/CloudflareClient.js";
import { agentManager } from "../agents/AgentManager.js";

/**
 * Register Cloudflare Edge WebSocket event handlers
 *
 * This function sets up real-time WebSocket communication between
 * the Dashboard and Cloudflare Workers AI.
 *
 * Events:
 * - edge:task:submit - Submit a task to the Worker
 * - edge:chat:message - Send a chat message to Worker LLM
 * - edge:status:query - Query task status by taskId
 *
 * @param io - Socket.IO Server instance
 */
export function registerEdgeWebSocketHandlers(io: Server) {
  io.on("connection", (socket: Socket) => {
    logInfo("EdgeWebSocket", `Client connected: ${socket.id}`);

    /**
     * Event: edge:task:submit
     * Client submits a task instruction to the Cloudflare Worker
     *
     * Payload: { instruction: string }
     * Response: edge:task:submitted { taskId, status }
     * Progress: edge:task:progress { taskId, progress, status }
     * Complete: edge:task:complete { taskId, result, status }
     */
    socket.on("edge:task:submit", async (data: { instruction: string }) => {
      try {
        logInfo("EdgeWebSocket", `Task submit: ${data.instruction}`);

        // Call Cloudflare Worker to submit task
        const { taskId } = await cloudflareClient.submitTask(data.instruction);

        // Emit task submitted confirmation
        socket.emit("edge:task:submitted", {
          taskId,
          status: "pending",
          instruction: data.instruction,
        });

        // Poll for progress updates (in future, Worker will push via WebSocket)
        const progressInterval = setInterval(async () => {
          try {
            const status = await cloudflareClient.checkStatus(taskId);

            // Emit progress update
            socket.emit("edge:task:progress", {
              taskId,
              progress: status.progress || 0,
              status: status.status,
              currentStep: status.currentStep,
            });

            // Stop polling when task completes or fails
            if (status.status === "success" || status.status === "error") {
              clearInterval(progressInterval);

              socket.emit("edge:task:complete", {
                taskId,
                result: status.result,
                status: status.status,
                error: status.error,
              });

              logInfo(
                "EdgeWebSocket",
                `Task ${taskId} completed: ${status.status}`,
              );
            }
          } catch (error: any) {
            clearInterval(progressInterval);
            logError("EdgeWebSocket", `Progress poll error: ${error.message}`);
            socket.emit("edge:task:error", {
              taskId,
              error: error.message,
            });
          }
        }, 2000); // Poll every 2 seconds

        // Cleanup interval on disconnect
        socket.on("disconnect", () => {
          clearInterval(progressInterval);
        });
      } catch (error: any) {
        logError("EdgeWebSocket", `Task submit error: ${error.message}`);
        socket.emit("edge:task:error", {
          error: error.message,
        });
      }
    });

    /**
     * Event: edge:chat:message
     * Client sends a chat message to the Cloudflare Worker LLM
     *
     * Payload: { instruction: string, history?: any[] }
     * Response: edge:chat:response { response }
     * Error: edge:chat:error { error }
     */
    socket.on(
      "edge:chat:message",
      async (data: { instruction: string; history?: any[] }) => {
        try {
          logInfo("EdgeWebSocket", `Chat message: ${data.instruction}`);

          // Call Cloudflare Worker to process chat
          const response = await cloudflareClient.chat(
            data.instruction,
            data.history,
          );

          // Emit chat response
          socket.emit("edge:chat:response", {
            response,
            timestamp: Date.now(),
          });
        } catch (error: any) {
          logError("EdgeWebSocket", `Chat error: ${error.message}`);
          socket.emit("edge:chat:error", {
            error: error.message,
          });
        }
      },
    );

    /**
     * Event: edge:status:query
     * Client queries the status of a specific task
     *
     * Payload: { taskId: string }
     * Response: edge:status:response { taskId, status, result, progress }
     * Error: edge:status:error { error }
     */
    socket.on("edge:status:query", async (data: { taskId: string }) => {
      try {
        logInfo("EdgeWebSocket", `Status query: ${data.taskId}`);

        // Query task status from Cloudflare Worker
        const status = await cloudflareClient.checkStatus(data.taskId);

        // Emit status response
        socket.emit("edge:status:response", {
          taskId: data.taskId,
          status: status.status,
          result: status.result,
          progress: status.progress,
          currentStep: status.currentStep,
          error: status.error,
        });
      } catch (error: any) {
        logError("EdgeWebSocket", `Status query error: ${error.message}`);
        socket.emit("edge:status:error", {
          taskId: data.taskId,
          error: error.message,
        });
      }
    });

    /**
     * Event: disconnect
     * Clean up resources when client disconnects
     */
    socket.on("disconnect", () => {
      logInfo("EdgeWebSocket", `Client disconnected: ${socket.id}`);
    });
  });

  logInfo("EdgeWebSocket", "Edge WebSocket handlers registered ✅");
}

/**
 * Register CEAN Orchestrator Chat WebSocket handlers
 *
 * Events:
 * - cean:orchestrator:prompt - User sends prompt to OrchestratorAgent
 * - cean:orchestrator:response - Agent sends response back to client
 *
 * @param io - Socket.IO Server instance
 */
export function registerCEANWebSocketHandlers(io: Server) {
  io.on("connection", (socket: Socket) => {
    /**
     * Event: cean:orchestrator:prompt
     * Client sends a prompt to the Orchestrator Agent
     *
     * Payload: { prompt: string, timestamp: number }
     * Response: cean:orchestrator:response { content, taskId?, error? }
     */
    socket.on(
      "cean:orchestrator:prompt",
      async (data: { prompt: string; timestamp: number }) => {
        try {
          logInfo("CEANChat", `Prompt received for Edge: ${data.prompt.slice(0, 50)}`);

          // Call Cloudflare Worker directly for global orchestration
          const response = await cloudflareClient.chat(data.prompt);

          logInfo("CEANChat", `Edge response received`);

          // Emit response back to client
          socket.emit("cean:orchestrator:response", {
            content: response.response,
            taskId: (response as any).taskId,
            timestamp: Date.now(),
          });
        } catch (error: unknown) {
          const errorMsg =
            error instanceof Error ? error.message : String(error);
          logError("CEANChat", `Edge Error: ${errorMsg}`);

          socket.emit("cean:orchestrator:response", {
            error: errorMsg,
            timestamp: Date.now(),
          });
        }
      },
    );
  });

  logInfo("CEANChat", "CEAN Orchestrator WebSocket handlers registered ✅");
}

/**
 * Register Fleet Management WebSocket handlers
 *
 * Events broadcasted to all connected clients:
 * - fleet_scaled - When a fleet is scaled up/down
 * - worker_status_changed - When a worker status changes
 * - metrics_updated - When metrics are updated
 *
 * @param io - Socket.IO Server instance
 */
export function registerFleetWebSocketHandlers(io: Server) {
  io.on("connection", (socket: Socket) => {
    logInfo("FleetWS", `Fleet client connected: ${socket.id}`);

    /**
     * Event: fleet_scaled
     * Emitted when a fleet scaling event occurs
     * Broadcasted to ALL clients
     *
     * Payload:
     * {
     *   fleet_id: string
     *   old_worker_count: number
     *   new_worker_count: number
     *   direction: 'up' | 'down'
     *   timestamp: number
     * }
     */
    socket.on(
      "broadcast:fleet_scaled",
      (data: {
        fleet_id: string;
        old_worker_count: number;
        new_worker_count: number;
        direction: "up" | "down";
        timestamp: number;
      }) => {
        logInfo(
          "FleetWS",
          `Fleet ${data.fleet_id} scaled ${data.direction}: ${data.old_worker_count} → ${data.new_worker_count} workers`
        );

        // Broadcast to all clients
        io.emit("fleet_scaled", data);
      }
    );

    /**
     * Event: worker_status_changed
     * Emitted when a worker status changes
     * Broadcasted to ALL clients
     *
     * Payload:
     * {
     *   worker_id: string
     *   fleet_id: string
     *   status: 'healthy' | 'degraded' | 'offline'
     *   latency_p95?: number
     *   error_rate?: number
     *   timestamp: number
     * }
     */
    socket.on(
      "broadcast:worker_status_changed",
      (data: {
        worker_id: string;
        fleet_id: string;
        status: "healthy" | "degraded" | "offline";
        latency_p95?: number;
        error_rate?: number;
        timestamp: number;
      }) => {
        logInfo("FleetWS", `Worker ${data.worker_id} status: ${data.status}`);

        // Broadcast to all clients
        io.emit("worker_status_changed", data);
      }
    );

    /**
     * Event: metrics_updated
     * Emitted when fleet or worker metrics are updated
     * Broadcasted to ALL clients
     *
     * Payload:
     * {
     *   fleet_id?: string
     *   worker_id?: string
     *   avg_latency?: number
     *   p95_latency?: number
     *   p99_latency?: number
     *   error_rate?: number
     *   rps?: number
     *   timestamp: number
     * }
     */
    socket.on(
      "broadcast:metrics_updated",
      (data: {
        fleet_id?: string;
        worker_id?: string;
        avg_latency?: number;
        p95_latency?: number;
        p99_latency?: number;
        error_rate?: number;
        rps?: number;
        total_workers?: number;
        healthy_workers?: number;
        timestamp: number;
      }) => {
        logInfo(
          "FleetWS",
          `Metrics updated${data.fleet_id ? ` (fleet: ${data.fleet_id})` : data.worker_id ? ` (worker: ${data.worker_id})` : ""}`
        );

        // Broadcast to all clients
        io.emit("metrics_updated", data);
      }
    );

    socket.on("disconnect", () => {
      logInfo("FleetWS", `Fleet client disconnected: ${socket.id}`);
    });
  });

  logInfo("FleetWS", "Fleet Management WebSocket handlers registered ✅");
}

import { RobotkezV2Agent } from '../agents/RobotkezV2Agent.js';
import { type AgentResponse } from '../agents/types.js';
import { socketService } from '../server/SocketService.js';
import { type ExecutionPlan, generateExecutionPlan } from '../utils/llmPlanner.js';
import { logError, logInfo, logWarn } from '../utils/logger.js';

export type BrowserCopilotMode = 'observe' | 'guide' | 'auto';
export type BrowserCopilotEnginePreference = 'auto' | 'chrome-acp' | 'robotkez';
export type BrowserCopilotStatus =
  | 'idle'
  | 'planning'
  | 'waiting-confirmation'
  | 'executing'
  | 'paused'
  | 'completed'
  | 'error';

export interface BrowserCopilotMessage {
  id: string;
  role: 'user' | 'assistant' | 'system';
  content: string;
  createdAt: number;
}

export interface BrowserCopilotSessionState {
  sessionId: string;
  status: BrowserCopilotStatus;
  mode: BrowserCopilotMode;
  enginePreference: BrowserCopilotEnginePreference;
  viewportEngine: 'chrome-acp' | 'robotkez';
  actionEngine: 'robotkez';
  chromeAcpReachable: boolean;
  overlayEnabled: boolean;
  paused: boolean;
  currentInstruction?: string;
  pendingInstruction?: string;
  plan?: ExecutionPlan;
  lastTaskId?: string;
  lastScreenshotUrl?: string;
  lastUpdatedAt: number;
  messages: BrowserCopilotMessage[];
}

interface ExecuteParams {
  instruction: string;
  history: BrowserCopilotMessage[];
}

export interface BrowserCopilotDependencies {
  executeInstruction: (params: ExecuteParams) => Promise<AgentResponse>;
  generatePlan: (instruction: string, history: BrowserCopilotMessage[]) => Promise<ExecutionPlan>;
  probeChromeAcp: () => Promise<boolean>;
  now: () => number;
}

async function defaultExecuteInstruction({ instruction, history }: ExecuteParams): Promise<AgentResponse> {
  const agent = new RobotkezV2Agent();
  return agent.execute(instruction, {
    backgroundEligible: true,
    swarm: {
      sessionId: 'browser-copilot-session',
      history: history.map((entry) => ({ role: entry.role, content: entry.content })),
      artifacts: {
        source: 'browser-copilot',
      },
    },
  });
}

async function defaultGeneratePlan(instruction: string, history: BrowserCopilotMessage[]): Promise<ExecutionPlan> {
  return generateExecutionPlan(instruction, {
    history: history.map((entry) => ({ role: entry.role, content: entry.content })),
  });
}

async function defaultProbeChromeAcp(): Promise<boolean> {
  try {
    const response = await fetch('http://localhost:9315', { method: 'GET' });
    return response.ok;
  } catch {
    return false;
  }
}

function createId(prefix: string, now: number): string {
  return `${prefix}-${now}-${Math.random().toString(36).slice(2, 8)}`;
}

function summarizePlan(plan: ExecutionPlan): string {
  const steps = plan.plan.slice(0, 3).map((step, index) => `${index + 1}. ${step.description}`).join(' | ');
  return `${plan.plan.length} lépéses terv készült. ${steps}${plan.plan.length > 3 ? ' | …' : ''}`;
}

export class BrowserCopilotSessionService {
  private readonly deps: BrowserCopilotDependencies;

  private state: BrowserCopilotSessionState;

  constructor(deps?: Partial<BrowserCopilotDependencies>) {
    this.deps = {
      executeInstruction: deps?.executeInstruction ?? defaultExecuteInstruction,
      generatePlan: deps?.generatePlan ?? defaultGeneratePlan,
      probeChromeAcp: deps?.probeChromeAcp ?? defaultProbeChromeAcp,
      now: deps?.now ?? (() => Date.now()),
    };

    const now = this.deps.now();
    this.state = {
      sessionId: `browser-copilot-${now}`,
      status: 'idle',
      mode: 'auto',
      enginePreference: 'auto',
      viewportEngine: 'robotkez',
      actionEngine: 'robotkez',
      chromeAcpReachable: false,
      overlayEnabled: true,
      paused: false,
      lastUpdatedAt: now,
      messages: [
        {
          id: createId('system', now),
          role: 'system',
          content: 'Browser Copilot session készen áll. Magyarul adhatsz megfigyelési, guide vagy teljesen automatikus utasításokat.',
          createdAt: now,
        },
      ],
    };
  }

  getState(): BrowserCopilotSessionState {
    return structuredClone(this.state);
  }

  reset(): BrowserCopilotSessionState {
    const now = this.deps.now();
    this.state = {
      sessionId: `browser-copilot-${now}`,
      status: 'idle',
      mode: this.state.mode,
      enginePreference: this.state.enginePreference,
      viewportEngine: this.state.viewportEngine,
      actionEngine: 'robotkez',
      chromeAcpReachable: this.state.chromeAcpReachable,
      overlayEnabled: this.state.overlayEnabled,
      paused: false,
      lastUpdatedAt: now,
      messages: [
        {
          id: createId('system', now),
          role: 'system',
          content: 'Új Browser Copilot session indult.',
          createdAt: now,
        },
      ],
    };
    this.emitUpdate();
    return this.getState();
  }

  async configure(config: Partial<Pick<BrowserCopilotSessionState, 'mode' | 'enginePreference' | 'overlayEnabled'>>): Promise<BrowserCopilotSessionState> {
    this.state.mode = config.mode ?? this.state.mode;
    this.state.enginePreference = config.enginePreference ?? this.state.enginePreference;
    this.state.overlayEnabled = config.overlayEnabled ?? this.state.overlayEnabled;
    await this.refreshViewport();
    this.touch('idle');
    this.appendMessage('system', `Beállítás frissítve: mód=${this.state.mode}, nézet=${this.state.viewportEngine}, overlay=${this.state.overlayEnabled ? 'on' : 'off'}.`);
    this.emitUpdate();
    return this.getState();
  }

  async pause(): Promise<BrowserCopilotSessionState> {
    this.state.paused = true;
    this.touch('paused');
    this.appendMessage('system', 'A Browser Copilot session szüneteltetve.');
    this.emitUpdate();
    return this.getState();
  }

  async resume(): Promise<BrowserCopilotSessionState> {
    this.state.paused = false;
    this.touch(this.state.pendingInstruction ? 'waiting-confirmation' : 'idle');
    this.appendMessage('system', 'A Browser Copilot session folytatva.');
    this.emitUpdate();
    return this.getState();
  }

  async sendMessage(instruction: string): Promise<BrowserCopilotSessionState> {
    const trimmed = instruction.trim();
    if (!trimmed) {
      throw new Error('Az instruction nem lehet üres.');
    }

    await this.refreshViewport();
    this.state.currentInstruction = trimmed;
    this.appendMessage('user', trimmed);

    if (this.state.paused) {
      this.touch('paused');
      this.appendMessage('assistant', 'A session éppen szünetel. Folytatáshoz nyomd meg a Resume gombot vagy használd a CLI resume parancsot.');
      this.emitUpdate();
      return this.getState();
    }

    this.touch('planning');
    this.emitUpdate();

    try {
      if (this.state.mode === 'observe') {
        const plan = await this.deps.generatePlan(trimmed, this.state.messages);
        this.state.plan = plan;
        this.state.pendingInstruction = undefined;
        this.touch('completed');
        this.appendMessage('assistant', `👀 Observe mód: ${summarizePlan(plan)}`);
        this.emitUpdate();
        return this.getState();
      }

      if (this.state.mode === 'guide') {
        const plan = await this.deps.generatePlan(trimmed, this.state.messages);
        this.state.plan = plan;
        this.state.pendingInstruction = trimmed;
        this.touch('waiting-confirmation');
        this.appendMessage('assistant', `🧭 Guide mód: ${summarizePlan(plan)} Ha mehet, kattints a Megerősítés gombra.`);
        this.emitUpdate();
        return this.getState();
      }

      await this.executeInstruction(trimmed);
      return this.getState();
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : String(error);
      logError('BrowserCopilotSession', `sendMessage error: ${message}`);
      this.touch('error');
      this.appendMessage('assistant', `❌ Browser Copilot hiba: ${message}`);
      this.emitUpdate();
      return this.getState();
    }
  }

  async confirmPending(): Promise<BrowserCopilotSessionState> {
    if (!this.state.pendingInstruction) {
      this.appendMessage('system', 'Nincs megerősítésre váró guide feladat.');
      this.emitUpdate();
      return this.getState();
    }

    if (this.state.paused) {
      this.appendMessage('assistant', 'A guide végrehajtás szünetel. Előbb folytasd a sessiont.');
      this.emitUpdate();
      return this.getState();
    }

    const pendingInstruction = this.state.pendingInstruction;
    this.state.pendingInstruction = undefined;
    await this.executeInstruction(pendingInstruction);
    return this.getState();
  }

  private async executeInstruction(instruction: string): Promise<void> {
    this.touch('executing');
    this.emitUpdate();

    const response = await this.deps.executeInstruction({
      instruction,
      history: this.state.messages,
    });

    this.state.lastScreenshotUrl = `/api/v1/robotkez/screenshot?t=${this.deps.now()}`;

    if (response.status === 'success') {
      const responseRecord = typeof response.data === 'object' && response.data !== null
        ? response.data as Record<string, unknown>
        : undefined;
      const taskId = typeof responseRecord?.taskId === 'string' ? responseRecord.taskId : undefined;
      this.state.lastTaskId = taskId;
      this.touch(taskId ? 'executing' : 'completed');
      this.appendMessage('assistant', response.message ?? 'A Robotkéz végrehajtotta a feladatot.');
      return;
    }

    const errorMessage = response.error ?? response.message ?? 'Ismeretlen végrehajtási hiba.';
    logWarn('BrowserCopilotSession', `Robotkez execution returned ${response.status}: ${errorMessage}`);
    this.touch('error');
    this.appendMessage('assistant', `❌ A végrehajtás nem sikerült: ${errorMessage}`);
  }

  private async refreshViewport(): Promise<void> {
    const chromeAcpReachable = await this.deps.probeChromeAcp();
    this.state.chromeAcpReachable = chromeAcpReachable;

    if (this.state.enginePreference === 'robotkez') {
      this.state.viewportEngine = 'robotkez';
      return;
    }

    if (this.state.enginePreference === 'chrome-acp') {
      this.state.viewportEngine = chromeAcpReachable ? 'chrome-acp' : 'robotkez';
      return;
    }

    this.state.viewportEngine = chromeAcpReachable ? 'chrome-acp' : 'robotkez';
  }

  private appendMessage(role: BrowserCopilotMessage['role'], content: string): void {
    const now = this.deps.now();
    this.state.messages = [
      ...this.state.messages,
      {
        id: createId(role, now),
        role,
        content,
        createdAt: now,
      },
    ].slice(-30);
    this.state.lastUpdatedAt = now;
  }

  private touch(status: BrowserCopilotStatus): void {
    this.state.status = status;
    this.state.lastUpdatedAt = this.deps.now();
  }

  private emitUpdate(): void {
    socketService.emit('browser-copilot:update', this.getState());
  }
}

export const browserCopilotSessionService = new BrowserCopilotSessionService();

import { logInfo, logError } from '../utils/logger.js';
import fetch from 'node-fetch';

export interface UIAction {
    action: 'click' | 'type' | 'navigate' | 'wait' | 'vision-click' | 'press';
    target?: string; // CSS selector or description for vision
    text?: string;
    url?: string;
    x?: number;
    y?: number;
    description: string; // Magyar description for logging/overlay
}

/**
 * RobotkezProService - Bridge to the Python Action Server (BVAB)
 */
export class RobotkezProService {
    private static instance: RobotkezProService;
    private baseUrl: string = process.env.PYTHON_API_URL || 'http://localhost:8000';

    public static getInstance(): RobotkezProService {
        if (!RobotkezProService.instance) {
            RobotkezProService.instance = new RobotkezProService();
        }
        return RobotkezProService.instance;
    }

    private async call(path: string, body?: any) {
        try {
            const response = await fetch(`${this.baseUrl}${path}`, {
                method: body ? 'POST' : 'GET',
                headers: { 'Content-Type': 'application/json' },
                body: body ? JSON.stringify(body) : undefined
            });
            return await response.json();
        } catch (error) {
            logError("RobotkezPro", `Call to ${path} failed: ${error}`);
            return { status: 'error', message: String(error) };
        }
    }

    /**
     * Executes a single UI action.
     */
    async executeAction(action: UIAction) {
        logInfo("RobotkezPro", `Executing: ${action.description}`);
        
        switch (action.action) {
            case 'navigate':
                return await this.call('/api/robotkez/action', { action: 'navigate', params: { url: action.url } });
            case 'click':
                if (action.x !== undefined && action.y !== undefined) {
                    return await this.call('/os/click', { x: action.x, y: action.y });
                }
                return await this.call('/api/robotkez/action', { action: 'click', params: { selector: action.target } });
            case 'type':
                return await this.call('/os/type', { text: action.text });
            case 'vision-click':
                return await this.call('/os/vision-click', { description: action.target });
            case 'press':
                return await this.call('/api/robotkez/action', { action: 'press', params: { key: action.text } });
            default:
                return { status: 'error', message: `Unknown action: ${action.action}` };
        }
    }

    /**
     * Executes a series of actions (a plan).
     */
    async executePlan(actions: UIAction[], onProgress?: (msg: string) => void) {
        const results = [];
        for (const action of actions) {
            if (onProgress) onProgress(action.description);
            const res = await this.executeAction(action) as Record<string, unknown>;
            results.push(res);
            if (res['status'] === 'error') break; // Halt on failure
            await new Promise(r => setTimeout(r, 1000)); // Adaptive delay
        }
        return results;
    }

    async getSnapshot() {
        return await this.call('/api/robotkez/snapshot');
    }
}

export const robotkezPro = RobotkezProService.getInstance();

/**
 * Fleet Service - Business logic for fleet operations
 * Path: src/services/fleetService.ts
 * 
 * Handles:
 * - Fleet creation, updates, deletion
 * - Worker management within fleets
 * - Fleet health status calculation
 */

import { Database } from 'better-sqlite3';
import { v4 as uuidv4 } from 'uuid';
import { logInfo, logError } from '../utils/logger.js';

export interface FleetData {
  id: string;
  name: string;
  environment: string;
  status: string;
  description?: string;
  created_at: string;
  updated_at: string;
}

export interface WorkerData {
  id: string;
  fleet_id: string;
  name: string;
  url: string;
  cloudflare_id?: string;
  status: string;
  last_heartbeat?: string;
  error_count: number;
  created_at: string;
  updated_at: string;
}

export interface FleetHealth {
  id: string;
  name: string;
  environment: string;
  status: string;
  worker_count: number;
  active_workers: number;
  avg_error_rate: number; // percentage
  avg_latency_p95: number; // milliseconds
  last_update: string;
}

export class FleetService {
  constructor(private db: Database) {}

  /**
   * Create a new fleet
   */
  createFleet(id: string, environment: string, name: string, description?: string): string {
    try {
      const now = new Date().toISOString();
      const stmt = this.db.prepare(`
        INSERT INTO cean_fleets (id, name, environment, status, description, created_at, updated_at)
        VALUES (?, ?, ?, 'active', ?, ?, ?)
      `);
      stmt.run(id, name, environment, description || '', now, now);
      logInfo('FleetService', `Fleet created: ${id}`);
      return id;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('FleetService', `createFleet error: ${msg}`);
      throw error;
    }
  }

  /**
   * Get a single fleet by ID
   */
  getFleet(id: string): FleetData | null {
    try {
      const stmt = this.db.prepare('SELECT * FROM cean_fleets WHERE id = ?');
      return (stmt.get(id) as FleetData) || null;
    } catch (error: unknown) {
      return null;
    }
  }

  /**
   * Get all fleets
   */
  getAllFleets(): FleetData[] {
    try {
      const stmt = this.db.prepare('SELECT * FROM cean_fleets ORDER BY created_at DESC');
      return stmt.all() as FleetData[];
    } catch (error: unknown) {
      return [];
    }
  }

  /**
   * Get a single worker by ID
   */
  getWorker(id: string): WorkerData | null {
    try {
      const stmt = this.db.prepare('SELECT * FROM cean_workers WHERE id = ?');
      return (stmt.get(id) as WorkerData) || null;
    } catch (error: unknown) {
      return null;
    }
  }

  /**
   * Get fleet health status
   */
  getFleetHealth(fleetId: string): FleetHealth | null {
    try {
      // Get fleet info
      const fleetStmt = this.db.prepare(`
        SELECT id, name, environment, status, created_at
        FROM cean_fleets
        WHERE id = ?
      `);

      const fleet = fleetStmt.get(fleetId) as FleetData | undefined;

      if (!fleet) {
        return null;
      }

      // Get worker stats
      const workerStmt = this.db.prepare(`
        SELECT 
          COUNT(*) as total,
          SUM(CASE WHEN status = 'active' THEN 1 ELSE 0 END) as active
        FROM cean_workers
        WHERE fleet_id = ?
      `);

      const workerStats = workerStmt.get(fleetId) as { total: number; active: number };

      // Get metrics aggregate
      const metricsStmt = this.db.prepare(`
        SELECT 
          AVG(error_rate) as avg_error_rate,
          AVG(latency_p95) as avg_latency_p95,
          MAX(timestamp) as last_update
        FROM cean_metrics_cache
        WHERE worker_id IN (
          SELECT id FROM cean_workers WHERE fleet_id = ?
        )
        AND timestamp >= datetime('now', '-5 minutes')
      `);

      const metrics = metricsStmt.get(fleetId) as {
        avg_error_rate: number | null;
        avg_latency_p95: number | null;
        last_update: string | null;
      };

      return {
        id: fleet.id,
        name: fleet.name,
        environment: fleet.environment,
        status: fleet.status,
        worker_count: workerStats.total || 0,
        active_workers: workerStats.active || 0,
        avg_error_rate: (metrics.avg_error_rate as number) || 0,
        avg_latency_p95: (metrics.avg_latency_p95 as number) || 0,
        last_update: (metrics.last_update as string) || new Date().toISOString()
      };
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('FleetService', `getFleetHealth error: ${msg}`);
      return null;
    }
  }

  /**
   * Get all fleets with health info
   */
  getAllFleetsWithHealth(): Array<FleetHealth & { description?: string }> {
    try {
      const stmt = this.db.prepare(`
        SELECT id, name, environment, status, description, created_at
        FROM cean_fleets
        ORDER BY created_at DESC
      `);

      const fleets = stmt.all() as (FleetData & { description?: string })[];

      return fleets.map((fleet) => {
        const health = this.getFleetHealth(fleet.id);
        return { ...health, description: fleet.description } as FleetHealth & {
          description?: string;
        };
      });
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('FleetService', `getAllFleetsWithHealth error: ${msg}`);
      return [];
    }
  }

  /**
   * Add worker to fleet
   */
  addWorkerToFleet(fleetId: string, identifier: string, workerName: string, workerUrl: string): string | null {
    try {
      const workerId = identifier || `worker-${Date.now()}-${uuidv4().slice(0, 8)}`;
      const now = new Date().toISOString();

      const stmt = this.db.prepare(`
        INSERT INTO cean_workers (id, fleet_id, name, url, status, created_at, updated_at)
        VALUES (?, ?, ?, ?, 'active', ?, ?)
      `);

      stmt.run(workerId, fleetId, workerName, workerUrl, now, now);

      logInfo('FleetService', `Worker added to fleet ${fleetId}: ${workerId}`);

      return workerId;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('FleetService', `addWorkerToFleet error: ${msg}`);
      return null;
    }
  }

  /**
   * Remove worker from fleet
   */
  removeWorkerFromFleet(workerId: string): boolean {
    try {
      const stmt = this.db.prepare('DELETE FROM cean_workers WHERE id = ?');
      const result = stmt.run(workerId);

      const resultObj = result as unknown as Record<string, unknown>;
      if (resultObj.changes === 0) {
        return false;
      }

      logInfo('FleetService', `Worker removed: ${workerId}`);
      return true;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('FleetService', `removeWorkerFromFleet error: ${msg}`);
      return false;
    }
  }

  /**
   * Update worker status
   */
  updateWorkerStatus(workerId: string, newStatus: string): boolean {
    try {
      const now = new Date().toISOString();

      const stmt = this.db.prepare(`
        UPDATE cean_workers
        SET status = ?, updated_at = ?, last_heartbeat = ?
        WHERE id = ?
      `);

      const result = stmt.run(newStatus, now, now, workerId);

      const resultObj = result as unknown as Record<string, unknown>;
      if (resultObj.changes === 0) {
        return false;
      }

      logInfo('FleetService', `Worker status updated: ${workerId} → ${newStatus}`);
      return true;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('FleetService', `updateWorkerStatus error: ${msg}`);
      return false;
    }
  }

  /**
   * Increment worker error count
   */
  incrementWorkerErrorCount(workerId: string, amount: number = 1): boolean {
    try {
      const now = new Date().toISOString();

      const stmt = this.db.prepare(`
        UPDATE cean_workers
        SET error_count = error_count + ?, updated_at = ?
        WHERE id = ?
      `);

      const result = stmt.run(amount, now, workerId);

      const resultObj = result as unknown as Record<string, unknown>;
      if (resultObj.changes === 0) {
        return false;
      }

      logInfo('FleetService', `Worker error count incremented by ${amount}: ${workerId}`);
      return true;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('FleetService', `incrementWorkerErrorCount error: ${msg}`);
      return false;
    }
  }
}

/**
 * Metrics Archive Service
 * Path: src/services/metricsArchiveService.ts
 *
 * Handle long-term metrics storage and retention for CEAN fleet monitoring
 * Archives metrics from Prometheus to D1 for historical analysis
 */

import { Database } from 'better-sqlite3';
import { v4 as uuidv4 } from 'uuid';
import { logInfo, logError, logWarn } from '../utils/logger.js';

export interface MetricRecord {
  metricName: string;
  metricValue: number;
  fleetId?: string;
  workerId?: string;
  labels?: Record<string, string>;
  timestamp?: string;
}

export interface MetricsHistoryQuery {
  fleetId?: string;
  workerId?: string;
  metricName?: string;
  startTime: string; // ISO-8601
  endTime: string; // ISO-8601
  limit?: number;
}

/**
 * Archive a metric with timestamp, labels, and fleet context
 */
export async function archiveMetric(
  db: Database,
  record: MetricRecord
): Promise<string> {
  try {
    const id = `metric-${uuidv4()}`;
    const timestamp = record.timestamp || new Date().toISOString();
    const labelsJson = record.labels ? JSON.stringify(record.labels) : null;

    const stmt = db.prepare(`
      INSERT INTO cean_metrics_archive (
        id, timestamp, fleet_id, worker_id, 
        metric_name, metric_value, labels, created_at
      ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
      id,
      timestamp,
      record.fleetId || null,
      record.workerId || null,
      record.metricName,
      record.metricValue,
      labelsJson,
      new Date().toISOString()
    );

    logInfo('metricsArchive', `Archived metric: ${record.metricName} = ${record.metricValue}`);
    return id;
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    logError('metricsArchive', `Failed to archive metric: ${msg}`);
    throw e;
  }
}

/**
 * Get metrics history for a fleet or worker
 */
export async function getMetricsHistory(
  db: Database,
  query: MetricsHistoryQuery
): Promise<any[]> {
  try {
    let sql = 'SELECT * FROM cean_metrics_archive WHERE 1=1';
    const params: any[] = [];

    if (query.fleetId) {
      sql += ' AND fleet_id = ?';
      params.push(query.fleetId);
    }

    if (query.workerId) {
      sql += ' AND worker_id = ?';
      params.push(query.workerId);
    }

    if (query.metricName) {
      sql += ' AND metric_name = ?';
      params.push(query.metricName);
    }

    // Time range filter
    sql += ' AND timestamp BETWEEN ? AND ?';
    params.push(query.startTime, query.endTime);

    sql += ' ORDER BY timestamp DESC';

    if (query.limit) {
      sql += ' LIMIT ?';
      params.push(query.limit);
    }

    const stmt = db.prepare(sql);
    const results = stmt.all(...params) as any[];

    logInfo('metricsArchive', `Retrieved ${results.length} metric records`);
    return results;
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    logError('metricsArchive', `Failed to retrieve metrics history: ${msg}`);
    throw e;
  }
}

/**
 * Delete metrics older than specified days (retention policy)
 * Default: 30 days
 */
export async function deleteOldMetrics(
  db: Database,
  daysToKeep: number = 30
): Promise<number> {
  try {
    const cutoffDate = new Date();
    cutoffDate.setDate(cutoffDate.getDate() - daysToKeep);
    const cutoffIso = cutoffDate.toISOString();

    const stmt = db.prepare(`
      DELETE FROM cean_metrics_archive 
      WHERE timestamp < ?
    `);

    const result = stmt.run(cutoffIso) as any;
    const deletedCount = result.changes || 0;

    logInfo(
      'metricsArchive',
      `Cleanup: deleted ${deletedCount} metrics older than ${daysToKeep} days`
    );

    return deletedCount;
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    logError('metricsArchive', `Retention policy failed: ${msg}`);
    throw e;
  }
}

/**
 * Aggregate metrics for a fleet in a time window
 * Returns average, min, max for each metric type
 */
export async function getMetricsAggregate(
  db: Database,
  fleetId: string,
  startTime: string,
  endTime: string
): Promise<Record<string, { avg: number; min: number; max: number; count: number }>> {
  try {
    const sql = `
      SELECT 
        metric_name,
        AVG(metric_value) as avg,
        MIN(metric_value) as min,
        MAX(metric_value) as max,
        COUNT(*) as count
      FROM cean_metrics_archive
      WHERE fleet_id = ?
        AND timestamp BETWEEN ? AND ?
      GROUP BY metric_name
    `;

    const stmt = db.prepare(sql);
    const results = stmt.all(fleetId, startTime, endTime) as any[];

    const aggregated: Record<string, any> = {};
    for (const row of results) {
      aggregated[row.metric_name] = {
        avg: row.avg,
        min: row.min,
        max: row.max,
        count: row.count,
      };
    }

    logInfo('metricsArchive', `Aggregated ${results.length} metric groups for fleet ${fleetId}`);
    return aggregated;
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    logError('metricsArchive', `Failed to aggregate metrics: ${msg}`);
    throw e;
  }
}

/**
 * Get latest metrics snapshot per worker (most recent values)
 */
export async function getLatestMetricsSnapshot(
  db: Database,
  fleetId: string
): Promise<Record<string, any>> {
  try {
    const sql = `
      SELECT 
        worker_id,
        metric_name,
        metric_value,
        timestamp,
        labels
      FROM cean_metrics_archive
      WHERE fleet_id = ? 
        AND timestamp = (
          SELECT MAX(timestamp) 
          FROM cean_metrics_archive 
          WHERE fleet_id = ? AND worker_id = cean_metrics_archive.worker_id
        )
      ORDER BY worker_id, metric_name
    `;

    const stmt = db.prepare(sql);
    const results = stmt.all(fleetId, fleetId) as any[];

    const snapshot: Record<string, any> = {};
    for (const row of results) {
      if (!snapshot[row.worker_id]) {
        snapshot[row.worker_id] = {};
      }
      snapshot[row.worker_id][row.metric_name] = {
        value: row.metric_value,
        timestamp: row.timestamp,
        labels: row.labels ? JSON.parse(row.labels) : null,
      };
    }

    logInfo('metricsArchive', `Got latest snapshot for ${Object.keys(snapshot).length} workers`);
    return snapshot;
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    logError('metricsArchive', `Failed to get latest snapshot: ${msg}`);
    throw e;
  }
}

/**
 * Initialize metrics archive on server startup
 * - Run retention cleanup
 * - Log statistics
 */
export async function initMetricsArchive(db: Database): Promise<void> {
  try {
    // Check table exists
    const tables = db
      .prepare(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='cean_metrics_archive'"
      )
      .all();

    if (tables.length === 0) {
      logWarn('metricsArchive', 'Table cean_metrics_archive does not exist - schema may not be initialized');
      return;
    }

    // Run cleanup (keep last 30 days)
    await deleteOldMetrics(db, 30);

    // Get current record count
    const countRow = db.prepare('SELECT COUNT(*) as count FROM cean_metrics_archive').get() as any;
    logInfo('metricsArchive', `Initialized - current archive size: ${countRow.count} records`);
  } catch (e: unknown) {
    const msg = e instanceof Error ? e.message : String(e);
    logError('metricsArchive', `Initialization failed: ${msg}`);
  }
}

import fs from 'fs/promises';
import path from 'path';
import { logInfo, logError } from '../utils/logger.js';
import nodemailer from 'nodemailer';

interface OutreachAccount {
    id: string;
    user: string;
    pass: string;
    host: string;
    port: number;
    daily_limit: number;
    sent_today: number;
    last_sent_at: string | null;
}

interface OutreachConfig {
    accounts: OutreachAccount[];
    global_settings: any;
}

const CONFIG_PATH = path.join(process.cwd(), 'config', 'outreach_accounts.json');

export class OutreachService {
    private config: OutreachConfig | null = null;

    async loadConfig() {
        try {
            const data = await fs.readFile(CONFIG_PATH, 'utf-8');
            this.config = JSON.parse(data);
        } catch (err) {
            logError("OutreachService", `Failed to load config: ${err}`);
        }
    }

    async saveConfig() {
        if (!this.config) return;
        try {
            await fs.writeFile(CONFIG_PATH, JSON.stringify(this.config, null, 4));
        } catch (err) {
            logError("OutreachService", `Failed to save config: ${err}`);
        }
    }

    private checkDailyReset() {
        if (!this.config) return;
        const today = new Date().toISOString().split('T')[0];
        
        for (const account of this.config.accounts) {
            if (account.last_sent_at) {
                const lastDate = account.last_sent_at.split('T')[0];
                if (lastDate !== today) {
                    account.sent_today = 0;
                }
            }
        }
    }

    async getNextAccount(): Promise<OutreachAccount | null> {
        await this.loadConfig();
        if (!this.config) return null;

        this.checkDailyReset();

        const available = this.config.accounts
            .filter(a => a.sent_today < a.daily_limit)
            .sort((a, b) => a.sent_today - b.sent_today);

        if (available.length === 0) {
            logError("OutreachService", "No accounts available under daily limit!");
            return null;
        }

        return available[0];
    }

    async markAsSent(accountId: string) {
        if (!this.config) return;
        
        const account = this.config.accounts.find(a => a.id === accountId);
        if (account) {
            account.sent_today += 1;
            account.last_sent_at = new Date().toISOString();
            await this.saveConfig();
            logInfo("OutreachService", `Account ${account.user} count updated: ${account.sent_today}/${account.daily_limit}`);
        }
    }

    /**
     * Generates a grant-aware outreach email.
     */
    async generateGrantOutreachEmail(lead: any, grantId: string = 'demjan-sandor-2026'): Promise<string> {
        const grantsData = await fs.readFile(path.join(process.cwd(), 'config', 'grants_2026.json'), 'utf-8');
        const { grants } = JSON.parse(grantsData);
        const grant = grants.find((g: any) => g.id === grantId) || grants[0];

        return `Tisztelt ${lead.company_name}!

${lead.icebreaker_text || 'Érdeklődéssel figyelem az Önök piaci tevékenységét.'}

Szeretném figyelmükbe ajánlani, hogy a Brunella AI Agent System bevezetése most a ${grant.name} keretében akár ${grant.support_rate}-os vissza nem térítendő támogatással is megvalósítható.

Készítettem Önöknek egy rövid, személyre szabott bemutatót, amely az Önök üzleti folyamataira reflektál:
${lead.demo_url || 'https://demo.brunella.ai/preview/generic'}

Amennyiben érdekli Önöket a technológia és a finanszírozási lehetőség, szívesen állok rendelkezésre egy rövid egyeztetésre.

Üdvözlettel,
${process.env.OUTREACH_SENDER_NAME || 'Pohánka Péter'}
Brunella AI Team`;
    }

    /**
     * Sends an outreach email using rotating SMTP accounts.
     */
    async sendEmail(to: string, subject: string, body: string): Promise<boolean> {
        const account = await this.getNextAccount();
        if (!account) {
            logError("OutreachService", `Cannot send email to ${to}: No available accounts.`);
            return false;
        }

        logInfo("OutreachService", `Sending email to ${to} via ${account.user}...`);

        const transporter = nodemailer.createTransport({
            host: account.host,
            port: account.port,
            secure: account.port === 465,
            auth: {
                user: account.user,
                pass: account.pass
            }
        });

        try {
            await transporter.sendMail({
                from: `"${process.env.OUTREACH_SENDER_NAME || 'Pohánka Péter'}" <${account.user}>`,
                to,
                subject,
                text: body, // Plain text is better for cold emails in 2026
                // html: `<div>${body.replace(/\n/g, '<br>')}</div>`
            });

            await this.markAsSent(account.id);
            logInfo("OutreachService", `Email successfully sent to ${to}`);
            return true;
        } catch (err: any) {
            logError("OutreachService", `Failed to send email to ${to}: ${err.message}`);
            return false;
        }
    }
}

export const outreachService = new OutreachService();

/**
 * Scaling Service - Business logic for auto-scaling
 * Path: src/services/scalingService.ts
 * 
 * Handles:
 * - Scale-up/down decisions based on metrics
 * - Scaling policy enforcement
 * - Cooldown management
 */

import { Database } from 'better-sqlite3';
import { v4 as uuidv4 } from 'uuid';
import { logInfo, logError } from '../utils/logger.js';

export interface ScalingPolicy {
  scaleUpThreshold: {
    latencyP95Ms: number;
    errorRatePercent: number;
  };
  scaleDownThreshold: {
    latencyP95Ms: number;
    errorRatePercent: number;
    durationMinutes: number;
  };
  cooldownMinutes: number;
  minWorkers: number;
  maxWorkers: number;
}

export interface ScalingDecision {
  should_scale: boolean;
  action: 'scale_up' | 'scale_down' | 'maintain' | null;
  reason: string;
  current_workers: number;
  target_workers: number;
}

export const DEFAULT_POLICY: ScalingPolicy = {
  scaleUpThreshold: {
    latencyP95Ms: 500,
    errorRatePercent: 5
  },
  scaleDownThreshold: {
    latencyP95Ms: 100,
    errorRatePercent: 1,
    durationMinutes: 5
  },
  cooldownMinutes: 5,
  minWorkers: 2,
  maxWorkers: 10
};

export class ScalingService {
  private policies: Map<string, ScalingPolicy> = new Map();
  private lastScalingTime: Map<string, number> = new Map();

  constructor(private db: Database) {
    // Initialize with default policies for all existing fleets
    this.initializePolicies();
  }

  /**
   * Initialize policies for all existing fleets
   */
  private initializePolicies(): void {
    try {
      const stmt = this.db.prepare('SELECT id FROM cean_fleets');
      const fleets = stmt.all() as Array<{ id: string }>;

      for (const fleet of fleets) {
        if (!this.policies.has(fleet.id)) {
          this.policies.set(fleet.id, { ...DEFAULT_POLICY });
        }
      }

      logInfo('ScalingService', `Initialized policies for ${fleets.length} fleets`);
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('ScalingService', `initializePolicies error: ${msg}`);
    }
  }

  /**
   * Get policy for fleet
   */
  getPolicy(fleetId: string): ScalingPolicy {
    return this.policies.get(fleetId) || { ...DEFAULT_POLICY };
  }

  /**
   * Set policy for fleet
   */
  setPolicy(fleetId: string, policy: ScalingPolicy): boolean {
    try {
      this.policies.set(fleetId, policy);
      logInfo('ScalingService', `Policy updated for fleet ${fleetId}`);
      return true;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('ScalingService', `setPolicy error: ${msg}`);
      return false;
    }
  }

  /**
   * Evaluate fleet and decide if scaling is needed
   */
  evaluateAndDecide(fleetId: string): ScalingDecision {
    try {
      const policy = this.getPolicy(fleetId);

      // Check cooldown
      const lastScaling = this.lastScalingTime.get(fleetId) || 0;
      const timeSinceLastScaling = Date.now() - lastScaling;
      const cooldownMs = policy.cooldownMinutes * 60 * 1000;

      if (timeSinceLastScaling < cooldownMs) {
        return {
          should_scale: false,
          action: null,
          reason: `Cooldown period active (${((cooldownMs - timeSinceLastScaling) / 1000 / 60).toFixed(1)}m remaining)`,
          current_workers: this.getCurrentWorkerCount(fleetId),
          target_workers: this.getCurrentWorkerCount(fleetId)
        };
      }

      // Get current fleet metrics
      const avgLatencyP95 = this.getFleetAverageLatency(fleetId);
      const avgErrorRate = this.getFleetAverageErrorRate(fleetId);
      const currentWorkers = this.getCurrentWorkerCount(fleetId);

      // Check scale-up conditions
      const shouldScaleUp =
        (avgLatencyP95 >= policy.scaleUpThreshold.latencyP95Ms ||
          avgErrorRate >= policy.scaleUpThreshold.errorRatePercent) &&
        currentWorkers < policy.maxWorkers;

      if (shouldScaleUp) {
        const reason =
          avgLatencyP95 >= policy.scaleUpThreshold.latencyP95Ms
            ? `High latency: ${avgLatencyP95.toFixed(2)}ms (threshold: ${policy.scaleUpThreshold.latencyP95Ms}ms)`
            : `High error rate: ${avgErrorRate.toFixed(2)}% (threshold: ${policy.scaleUpThreshold.errorRatePercent}%)`;

        return {
          should_scale: true,
          action: 'scale_up',
          reason,
          current_workers: currentWorkers,
          target_workers: Math.min(currentWorkers + 1, policy.maxWorkers)
        };
      }

      // Check scale-down conditions (more conservative)
      const shouldScaleDown =
        avgLatencyP95 <= policy.scaleDownThreshold.latencyP95Ms &&
        avgErrorRate <= policy.scaleDownThreshold.errorRatePercent &&
        currentWorkers > policy.minWorkers &&
        this.isLowMetricsDurationMet(fleetId, policy.scaleDownThreshold.durationMinutes);

      if (shouldScaleDown) {
        return {
          should_scale: true,
          action: 'scale_down',
          reason: `Low metrics for ${policy.scaleDownThreshold.durationMinutes}m - lat: ${avgLatencyP95.toFixed(2)}ms, err: ${avgErrorRate.toFixed(2)}%`,
          current_workers: currentWorkers,
          target_workers: Math.max(currentWorkers - 1, policy.minWorkers)
        };
      }

      return {
        should_scale: false,
        action: 'maintain',
        reason: `Metrics stable - lat: ${avgLatencyP95.toFixed(2)}ms, err: ${avgErrorRate.toFixed(2)}%`,
        current_workers: currentWorkers,
        target_workers: currentWorkers
      };
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('ScalingService', `evaluateAndDecide error: ${msg}`);

      return {
        should_scale: false,
        action: null,
        reason: `Evaluation error: ${msg}`,
        current_workers: 0,
        target_workers: 0
      };
    }
  }

  /**
   * Execute scaling decision
   */
  executeScaling(fleetId: string, decision: ScalingDecision): boolean {
    try {
      if (!decision.should_scale || !decision.action || decision.action === 'maintain') {
        return false;
      }

      const now = new Date().toISOString();
      const eventId = `scale-${Date.now()}-${uuidv4().slice(0, 8)}`;

      const stmt = this.db.prepare(`
        INSERT INTO cean_scaling_events
        (id, fleet_id, event_type, reason, instance_count_before, instance_count_after, status, created_at)
        VALUES (?, ?, ?, ?, ?, ?, 'completed', ?)
      `);

      stmt.run(
        eventId,
        fleetId,
        decision.action,
        decision.reason,
        decision.current_workers,
        decision.target_workers,
        now
      );

      // Update cooldown
      this.lastScalingTime.set(fleetId, Date.now());

      logInfo(
        'ScalingService',
        `Scaling executed: ${fleetId} ${decision.action} (${decision.current_workers} → ${decision.target_workers})`
      );

      return true;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('ScalingService', `executeScaling error: ${msg}`);
      return false;
    }
  }

  /**
   * Get current active worker count
   */
  private getCurrentWorkerCount(fleetId: string): number {
    try {
      const stmt = this.db.prepare(
        "SELECT COUNT(*) as count FROM cean_workers WHERE fleet_id = ? AND status = 'active'"
      );
      const result = stmt.get(fleetId) as { count: number };
      return result.count || 0;
    } catch (error: unknown) {
      logError('ScalingService', `getCurrentWorkerCount error`);
      return 0;
    }
  }

  /**
   * Get fleet average latency (p95)
   */
  private getFleetAverageLatency(fleetId: string): number {
    try {
      const stmt = this.db.prepare(`
        SELECT AVG(m.latency_p95) as avg_latency
        FROM cean_workers w
        LEFT JOIN cean_metrics_cache m ON w.id = m.worker_id
        WHERE w.fleet_id = ? AND m.timestamp >= datetime('now', '-5 minutes')
      `);
      const result = stmt.get(fleetId) as { avg_latency: number | null };
      return (result.avg_latency as number) || 0;
    } catch (error: unknown) {
      logError('ScalingService', `getFleetAverageLatency error`);
      return 0;
    }
  }

  /**
   * Get fleet average error rate
   */
  private getFleetAverageErrorRate(fleetId: string): number {
    try {
      const stmt = this.db.prepare(`
        SELECT AVG(m.error_rate) as avg_error_rate
        FROM cean_workers w
        LEFT JOIN cean_metrics_cache m ON w.id = m.worker_id
        WHERE w.fleet_id = ? AND m.timestamp >= datetime('now', '-5 minutes')
      `);
      const result = stmt.get(fleetId) as { avg_error_rate: number | null };
      return (result.avg_error_rate as number) || 0;
    } catch (error: unknown) {
      logError('ScalingService', `getFleetAverageErrorRate error`);
      return 0;
    }
  }

  /**
   * Check if low metrics have been sustained for duration
   */
  private isLowMetricsDurationMet(fleetId: string, durationMinutes: number): boolean {
    try {
      const stmt = this.db.prepare(`
        SELECT COUNT(*) as sample_count
        FROM (
          SELECT DISTINCT DATE_TRUNC('minute', m.timestamp) as minute
          FROM cean_workers w
          LEFT JOIN cean_metrics_cache m ON w.id = m.worker_id
          WHERE w.fleet_id = ?
            AND m.timestamp >= datetime('now', '-${durationMinutes} minutes')
            AND m.latency_p95 < 100
            AND m.error_rate < 1
        )
      `);

      const result = stmt.get(fleetId) as { sample_count: number };
      return (result.sample_count as number) >= durationMinutes;
    } catch (error: unknown) {
      logError('ScalingService', `isLowMetricsDurationMet error`);
      return false;
    }
  }

  /**
   * Get scaling history for fleet
   */
  getScalingHistory(fleetId: string, limit: number = 10): Record<string, unknown>[] {
    try {
      const stmt = this.db.prepare(`
        SELECT 
          id, event_type, reason, instance_count_before, instance_count_after, status, created_at
        FROM cean_scaling_events
        WHERE fleet_id = ?
        ORDER BY created_at DESC
        LIMIT ?
      `);

      const results = stmt.all(fleetId, limit) as Record<string, unknown>[];

      return results;
    } catch (error: unknown) {
      const msg = error instanceof Error ? error.message : String(error);
      logError('ScalingService', `getScalingHistory error: ${msg}`);
      return [];
    }
  }
}

/**
 * Track State Manager - Centralized Track Synchronization Service
 *
 * Automatically syncs all tracks (active + archived) to project_state.json
 * Watches for meta.json changes and updates state in realtime
 *
 * @version 2.0.0
 * @author Claude Sonnet 4.5
 */

import * as fs from 'fs';
import * as path from 'path';
import { logInfo, logError, logWarn } from '../utils/logger.js';
import chokidar, { FSWatcher } from 'chokidar';

// ============================================================================
// INTERFACES
// ============================================================================

export interface TrackMetadata {
  // Unified schema (supports both "id" and "track_id")
  id: string;
  name: string;
  status: 'proposed' | 'active' | 'paused' | 'completed' | 'archived';
  priority: 'low' | 'medium' | 'high' | 'critical';
  progress: number; // 0-100
  created?: string;
  updated?: string;
  completed?: string;
  assignee?: string;
  tags?: string[];
  dependencies?: string[];

  // Original path (active or archived)
  _sourcePath?: string;
  _isArchived?: boolean;
}

export interface ProjectState {
  lastUpdated: string;
  tracks: TrackMetadata[];
  stats: {
    total: number;
    active: number;
    completed: number;
    archived: number;
    proposed: number;
  };
}

// ============================================================================
// CONSTANTS
// ============================================================================

const PROJECT_ROOT = process.cwd();
const CONDUCTOR_PATH = path.join(PROJECT_ROOT, 'conductor');
const STATE_FILE = path.join(CONDUCTOR_PATH, 'project_state.json');
const TRACKS_DIR = path.join(CONDUCTOR_PATH, 'tracks');
const ARCHIVE_DIR = path.join(CONDUCTOR_PATH, 'archive');
const TRACKS_MD = path.join(CONDUCTOR_PATH, 'tracks.md');

// ============================================================================
// TRACK STATE MANAGER CLASS
// ============================================================================

export class TrackStateManager {
  private state: ProjectState;
  private watcher: FSWatcher | null = null;
  private syncInProgress = false;

  constructor() {
    this.state = this.loadState();
  }

  /**
   * Load state from project_state.json (or create new)
   */
  private loadState(): ProjectState {
    if (fs.existsSync(STATE_FILE)) {
      try {
        const raw = fs.readFileSync(STATE_FILE, 'utf-8');
        // Remove BOM or common zero-width characters at the start to avoid JSON.parse errors
        const rawClean = raw.replace(/^[\uFEFF\u200B\u200C\u200D\u200E\u200F]+/, '');
        const data = JSON.parse(rawClean);

        // Ensure tracks array exists
        if (!data.tracks || !Array.isArray(data.tracks)) {
          data.tracks = [];
        }

        return {
          lastUpdated: data.lastUpdated || new Date().toISOString(),
          tracks: data.tracks,
          stats: this.calculateStats(data.tracks),
        };
      } catch (e) {
        logError('TrackStateManager', `State load failed: ${e}. Creating new state.`);
      }
    }

    // Default empty state
    return {
      lastUpdated: new Date().toISOString(),
      tracks: [],
      stats: { total: 0, active: 0, completed: 0, archived: 0, proposed: 0 },
    };
  }

  /**
   * Save state to project_state.json
   */
  private saveState(): void {
    try {
      this.state.lastUpdated = new Date().toISOString();
      this.state.stats = this.calculateStats(this.state.tracks);

      fs.writeFileSync(STATE_FILE, JSON.stringify(this.state, null, 2), 'utf-8');
      logInfo('TrackStateManager', `State saved: ${this.state.tracks.length} tracks`);
    } catch (e) {
      logError('TrackStateManager', `State save failed: ${e}`);
    }
  }

  /**
   * Calculate stats from tracks
   */
  private calculateStats(tracks: TrackMetadata[]): ProjectState['stats'] {
    return {
      total: tracks.length,
      active: tracks.filter(t => t.status === 'active').length,
      completed: tracks.filter(t => t.status === 'completed').length,
      archived: tracks.filter(t => t._isArchived).length,
      proposed: tracks.filter(t => t.status === 'proposed').length,
    };
  }

  /**
   * Parse meta.json with unified schema support
   */
  private parseMetaJson(metaPath: string, trackDir: string, isArchived: boolean): TrackMetadata | null {
    try {
      const raw = fs.readFileSync(metaPath, 'utf-8');
      // Strip BOM / zero-width chars that may precede JSON content
      const rawClean = raw.replace(/^[\uFEFF\u200B\u200C\u200D\u200E\u200F]+/, '');
      const meta = JSON.parse(rawClean);

      // Unified ID extraction (supports both "id" and "track_id")
      const id = String(meta.id || meta.track_id || path.basename(trackDir));
      const name = String(meta.name || meta.title || id);

      // Status normalization
      let status: TrackMetadata['status'] = 'active';
      const statusRaw = String(meta.status || 'active').toLowerCase();
      if (['proposed', 'active', 'paused', 'completed', 'archived'].includes(statusRaw)) {
        status = statusRaw as TrackMetadata['status'];
      }

      // Priority mapping (P0/P1/P2/P3 → critical/high/medium/low)
      let priority: TrackMetadata['priority'] = 'medium';
      const priorityRaw = String(meta.priority || 'medium').toLowerCase();
      if (priorityRaw.includes('p0') || priorityRaw.includes('critical')) {
        priority = 'critical';
      } else if (priorityRaw.includes('p1') || priorityRaw.includes('high')) {
        priority = 'high';
      } else if (priorityRaw.includes('p2') || priorityRaw.includes('medium')) {
        priority = 'medium';
      } else if (priorityRaw.includes('p3') || priorityRaw.includes('low')) {
        priority = 'low';
      }

      // Progress validation (0-100)
      let progress = Number(meta.progress || 0);
      if (!Number.isFinite(progress) || progress < 0) {
        progress = 0;
      } else if (progress > 100) {
        progress = 100;
      }

      return {
        id,
        name,
        status,
        priority,
        progress,
        created: meta.created || meta.created_at,
        updated: meta.updated || meta.updated_at,
        completed: meta.completed,
        assignee: meta.assignee || meta.assigned_agent,
        tags: Array.isArray(meta.tags) ? meta.tags : [],
        dependencies: Array.isArray(meta.dependencies) ? meta.dependencies : [],
        _sourcePath: trackDir,
        _isArchived: isArchived,
      };
    } catch (e) {
      logError('TrackStateManager', `Failed to parse ${metaPath}: ${e}`);
      return null;
    }
  }

  /**
   * Scan all tracks (active + archived)
   */
  public async fullSync(): Promise<void> {
    if (this.syncInProgress) {
      logWarn('TrackStateManager', 'Sync already in progress, skipping');
      return;
    }

    this.syncInProgress = true;
    logInfo('TrackStateManager', 'Starting full sync (active + archived)...');

    const newTracks: TrackMetadata[] = [];

    try {
      // 1. Scan ACTIVE tracks
      if (fs.existsSync(TRACKS_DIR)) {
        const activeDirs = fs.readdirSync(TRACKS_DIR).filter(f => {
          const fullPath = path.join(TRACKS_DIR, f);
          return fs.statSync(fullPath).isDirectory();
        });

        for (const dir of activeDirs) {
          const metaPath = path.join(TRACKS_DIR, dir, 'meta.json');
          if (fs.existsSync(metaPath)) {
            const track = this.parseMetaJson(metaPath, path.join(TRACKS_DIR, dir), false);
            if (track) {
              newTracks.push(track);
            }
          } else {
            logWarn('TrackStateManager', `No meta.json in ${dir} (skipping)`);
          }
        }
      }

      // 2. Scan ARCHIVED tracks
      if (fs.existsSync(ARCHIVE_DIR)) {
        const archiveDirs = fs.readdirSync(ARCHIVE_DIR).filter(f => {
          const fullPath = path.join(ARCHIVE_DIR, f);
          return fs.statSync(fullPath).isDirectory();
        });

        for (const dir of archiveDirs) {
          const metaPath = path.join(ARCHIVE_DIR, dir, 'meta.json');
          if (fs.existsSync(metaPath)) {
            const track = this.parseMetaJson(metaPath, path.join(ARCHIVE_DIR, dir), true);
            if (track) {
              // Force archived status
              track.status = 'archived';
              track._isArchived = true;
              newTracks.push(track);
            }
          }
        }
      }

      // 3. Update state
      this.state.tracks = newTracks;
      this.saveState();

      // 4. Generate tracks.md
      await this.generateTracksMd();

      logInfo('TrackStateManager', `✅ Full sync complete: ${newTracks.length} tracks (${this.state.stats.active} active, ${this.state.stats.archived} archived)`);
    } catch (e) {
      logError('TrackStateManager', `Full sync failed: ${e}`);
    } finally {
      this.syncInProgress = false;
    }
  }

  /**
   * Generate tracks.md from state
   */
  private async generateTracksMd(): Promise<void> {
    try {
      const proposed = this.state.tracks.filter(t => t.status === 'proposed');
      const active = this.state.tracks.filter(t => t.status === 'active');
      const completed = this.state.tracks.filter(t => t.status === 'completed' && !t._isArchived);
      const archived = this.state.tracks.filter(t => t._isArchived);

      let content = `# Projekt Nyomkovetes (Tracks)\n\n`;
      content += `**Utolso frissites:** ${this.state.lastUpdated}\n`;
      content += `**Generator:** Track State Manager v2.0\n`;
      content += `**Auto-Sync:** Enabled (realtime)\n\n`;
      content += `**Stats:** ${this.state.stats.total} total | ${this.state.stats.active} active | ${this.state.stats.completed} completed | ${this.state.stats.archived} archived\n\n`;
      content += `---\n\n`;

      // Proposed
      content += `## Tervezett Szalak (Proposed) (${proposed.length})\n\n`;
      for (const t of proposed) {
        content += `- [ ] **${t.name}** [${t.priority.toUpperCase()}]\n`;
        content += `  - **ID:** \`${t.id}\`\n`;
        content += `  - **Progress:** ${t.progress}%\n`;
        if (t.assignee) content += `  - **Assignee:** ${t.assignee}\n`;
        content += `  - Mappa: ./tracks/${t.id}/\n\n`;
      }

      content += `---\n\n`;

      // Active
      content += `## Aktiv Szalak (Active) (${active.length})\n\n`;
      for (const t of active) {
        content += `- [${t.progress === 100 ? 'x' : ' '}] **${t.name}** [${t.priority.toUpperCase()}]\n`;
        content += `  - **ID:** \`${t.id}\`\n`;
        content += `  - **Progress:** ${t.progress}%\n`;
        if (t.assignee) content += `  - **Assignee:** ${t.assignee}\n`;
        if (t.updated) content += `  - **Updated:** ${t.updated}\n`;
        content += `  - Mappa: ./tracks/${t.id}/\n\n`;
      }

      content += `---\n\n`;

      // Completed (not archived yet)
      if (completed.length > 0) {
        content += `## Befejezett (Completed - Not Archived) (${completed.length})\n\n`;
        for (const t of completed) {
          content += `- [x] **${t.name}**\n`;
          content += `  - **ID:** \`${t.id}\`\n`;
          if (t.completed) content += `  - **Completed:** ${t.completed}\n`;
          content += `  - Mappa: ./tracks/${t.id}/\n\n`;
        }
        content += `---\n\n`;
      }

      // Archived
      content += `## Archivalt (Archived) (${archived.length})\n\n`;
      content += `> Archived tracks are hidden by default. View in \`conductor/archive/\`\n\n`;
      for (const t of archived.slice(0, 10)) {
        content += `- [x] **${t.name}** (${t.completed || t.updated || 'N/A'})\n`;
      }
      if (archived.length > 10) {
        content += `\n... and ${archived.length - 10} more archived tracks\n`;
      }

      content += `\n---\n\n`;
      content += `*Auto-generated by Track State Manager v2.0*\n`;

      fs.writeFileSync(TRACKS_MD, content, 'utf-8');
      logInfo('TrackStateManager', '✅ tracks.md generated');
    } catch (e) {
      logError('TrackStateManager', `Failed to generate tracks.md: ${e}`);
    }
  }

  /**
   * Start file watcher (realtime sync)
   */
  public startWatcher(): void {
    if (this.watcher) {
      logWarn('TrackStateManager', 'Watcher already running');
      return;
    }

    logInfo('TrackStateManager', 'Starting file watcher (meta.json changes)...');

    this.watcher = chokidar.watch(
      [
        path.join(TRACKS_DIR, '*/meta.json'),
        path.join(ARCHIVE_DIR, '*/meta.json'),
      ],
      {
        persistent: true,
        ignoreInitial: true,
        awaitWriteFinish: {
          stabilityThreshold: 1000,
          pollInterval: 100,
        },
      }
    );

    this.watcher.on('change', async (filePath: string) => {
      logInfo('TrackStateManager', `📝 meta.json changed: ${filePath}`);
      await this.fullSync();
    });

    this.watcher.on('add', async (filePath: string) => {
      logInfo('TrackStateManager', `➕ meta.json added: ${filePath}`);
      await this.fullSync();
    });

    this.watcher.on('unlink', async (filePath: string) => {
      logInfo('TrackStateManager', `➖ meta.json removed: ${filePath}`);
      await this.fullSync();
    });

    logInfo('TrackStateManager', '✅ File watcher active');
  }

  /**
   * Stop file watcher
   */
  public stopWatcher(): void {
    if (this.watcher) {
      this.watcher.close();
      this.watcher = null;
      logInfo('TrackStateManager', 'File watcher stopped');
    }
  }

  /**
   * Get current state (read-only)
   */
  public getState(): Readonly<ProjectState> {
    return this.state;
  }

  /**
   * Get active tracks only (filter for Dashboard)
   */
  public getActiveTracks(): TrackMetadata[] {
    return this.state.tracks.filter(t => t.status === 'active' || t.status === 'proposed');
  }
}

