export const trackStateManager = new TrackStateManager();

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { config } from "../config/index.js";

function getBaseUrl() {
  return config.anythingllmBaseUrl.trim().replace(/\/$/, "");
}

async function requestAnythingLLM(path: string, options: RequestInit = {}) {
  const baseUrl = getBaseUrl();
  const url = `${baseUrl}${path}`;

  const headers: Record<string, string> = {
    "Content-Type": "application/json"
  };

  if (config.anythingllmApiKey) {
    headers.Authorization = `Bearer ${config.anythingllmApiKey}`;
    headers["X-AnythingLLM-Api-Key"] = config.anythingllmApiKey;
  }

  const response = await fetch(url, {
    ...options,
    headers: {
      ...headers,
      ...(options.headers || {})
    }
  });

  const text = await response.text();
  let data: any = text;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    // keep raw text
  }

  if (!response.ok) {
    const message = typeof data === "string" ? data : JSON.stringify(data);
    throw new Error(`AnythingLLM error (${response.status}): ${message}`);
  }

  return data;
}

export function registerAnythingLLMTools(server: McpServer) {
  server.tool(
    "anythingllm_list_workspaces",
    "Lists available AnythingLLM workspaces.",
    {},
    async () => {
      try {
        const data = await requestAnythingLLM("/api/v1/workspaces");
        return {
          content: [{ type: "text", text: JSON.stringify(data, null, 2) }]
        };
      } catch (error: any) {
        return {
          isError: true,
          content: [{ type: "text", text: error.message }]
        };
      }
    }
  );

  server.tool(
    "anythingllm_chat",
    "Sends a chat message to an AnythingLLM workspace.",
    {
      message: z.string().describe("User message to send"),
      workspace: z.string().optional().describe("Workspace slug (optional)")
    },
    async ({ message, workspace }) => {
      const workspaceSlug = workspace || config.anythingllmWorkspace;
      if (!workspaceSlug) {
        return {
          isError: true,
          content: [{ type: "text", text: "Workspace not set. Provide 'workspace' or set ANYTHINGLLM_WORKSPACE." }]
        };
      }

      try {
        const data = await requestAnythingLLM(`/api/v1/workspace/${workspaceSlug}/chat`, {
          method: "POST",
          body: JSON.stringify({ message })
        });

        return {
          content: [{ type: "text", text: JSON.stringify(data, null, 2) }]
        };
      } catch (error: any) {
        return {
          isError: true,
          content: [{ type: "text", text: error.message }]
        };
      }
    }
  );
}

export async function listAnythingLLMWorkspaces() {
  return await requestAnythingLLM("/api/v1/workspaces");
}

export async function chatAnythingLLM(message: string, workspace?: string) {
  const workspaceSlug = workspace || config.anythingllmWorkspace;
  if (!workspaceSlug) throw new Error("Workspace not set");
  return await requestAnythingLLM(`/api/v1/workspace/${workspaceSlug}/chat`, {
      method: "POST",
      body: JSON.stringify({ message })
  });
}

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import type { Browser, Page } from 'playwright';
import { URL } from 'url';
import { PythonShell } from 'python-shell';
import path from 'path';
import fs from 'fs';
import { CloudflareBrowserAPI } from '../utils/browserRendering.js';

// Lazy singleton – won't throw at import time if env vars are missing
let _cfBrowser: CloudflareBrowserAPI | null = null;
function getCfBrowser(): CloudflareBrowserAPI {
  if (!_cfBrowser) _cfBrowser = new CloudflareBrowserAPI();
  return _cfBrowser;
}

// Security check for URLs (same as before)
function isUrlAllowed(urlStr: string): boolean {
  try {
    const url = new URL(urlStr);
    if (url.protocol === 'file:') return false;

    const hostname = url.hostname;
    if (hostname === 'localhost') return false;
    if (hostname.startsWith('127.')) return false;
    if (hostname.startsWith('192.168.')) return false;
    if (hostname.startsWith('10.')) return false;
    if (hostname.endsWith('.local')) return false;

    return true;
  } catch {
    return false;
  }
}

// Global browser instance
let browser: Browser | null = null;

async function getBrowser() {
  if (!browser) {
    // We use playwright-core which doesn't bundle browsers, 
    // but we assume the user has a way to get one or we installed 'playwright' which does.
    // Actually, 'playwright' package installs browsers.
    // Let's try to launch.
    try {
      const { chromium } = await import('playwright');
      browser = await chromium.launch({
        headless: true,
        args: ['--no-sandbox', '--disable-setuid-sandbox'] // Safer in some envs, standard for server-side
      });
    } catch (e: any) {
      throw new Error(`Failed to load playwright: ${e.message}. Browser tools are not available in this environment.`);
    }
  }
  return browser;
}

const PYTHON_API = process.env.PYTHON_API_URL || 'http://127.0.0.1:8000';

export function registerBrowserTools(server: McpServer) {

