          signal: AbortSignal.timeout(120000),
        });
        const data = await response.json() as any;
        return {
          content: [{ type: "text", text: JSON.stringify(data, null, 2) }]
        };
      } catch (error: any) {
        return {
          isError: true,
          content: [{ type: "text", text: `Extract error: ${error.message}` }]
        };
      }
