import { spawn } from 'child_process';
import path from 'path';

// Konfiguráció
const PYTHON_PATH = process.env.PYTHON_PATH || 'python'; // Vagy a venv útvonala!
const WORKER_SCRIPT = path.join(process.cwd(), 'myai', 'browser_worker.py');

interface BrowserResult {
    status: 'success' | 'error';
    data: { result?: string };
    message?: string;
}

export async function runBrowserTask(taskOrPayload: string | object): Promise<string> {
    return new Promise((resolve, reject) => {
        // Bemeneti adatok JSON-be csomagolva
        const inputArgs = typeof taskOrPayload === 'string' 
            ? JSON.stringify({ task: taskOrPayload, apiKey: process.env.GOOGLE_API_KEY })
            : JSON.stringify({ ...taskOrPayload, apiKey: process.env.GOOGLE_API_KEY });

        const pythonProcess = spawn(PYTHON_PATH, [WORKER_SCRIPT, inputArgs]);

        let outputData = '';
        let errorData = '';

        // Adatgyűjtés a Python kimenetéről
        pythonProcess.stdout.on('data', (data) => {
            outputData += data.toString();
        });

        pythonProcess.stderr.on('data', (data) => {
            errorData += data.toString();
        });

        // Folyamat lezárása
        pythonProcess.on('close', (code) => {
            if (code !== 0) {
                console.error(`Browser Worker Hiba (Exit Code ${code}):`, errorData);
                return reject(new Error(`A robotkéz hibára futott: ${errorData || 'Ismeretlen hiba'}`));
            }

            try {
                // Megpróbáljuk megtalálni az utolsó érvényes JSON blokkot a kimenetben
                const lines = outputData.trim().split('\n');
                let jsonResult = null;

                for (let i = lines.length - 1; i >= 0; i--) {
                    try {
                        const line = lines[i].trim();
                        if (line.startsWith('{') && line.endsWith('}')) {
                            const parsed = JSON.parse(line);
                            if (parsed && typeof parsed === 'object' && 'status' in parsed) {
                                jsonResult = parsed;
                                break;
                            }
                        }
                    } catch (e) {
                        continue;
                    }
                }

                if (!jsonResult) {
                    throw new Error(`Nem található érvényes JSON válasz a kimenetben. Nyers kimenet: ${outputData}`);
                }

                const result: BrowserResult = jsonResult;

                if (result.status === 'success') {
                    resolve(result.data.result || "Sikeres, de nincs szöveges válasz.");
                } else {
                    reject(new Error(result.message));
                }
            } catch (e: any) {
                reject(new Error(`Nem sikerült értelmezni a Python választ: ${e.message}`));
            }
        });
    });
}

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { Logger } from "../utils/logger.js";

const logger = new Logger('claude.log');

export function registerClaudeTool(server: McpServer) {
    server.tool(
        "claude_message",
        "Sends a message to the Anthropic Claude API.",
        {
            model: z.string().default("claude-3-opus-20240229").describe("The model to use"),
            messages: z.array(z.object({
                role: z.enum(["user", "assistant"]),
                content: z.string()
            })).describe("Conversation history"),
            system: z.string().optional().describe("System prompt"),
            max_tokens: z.number().default(1024)
        },
        async ({ model, messages, system, max_tokens }) => {
            const apiKey = process.env.CLAUDE_API_KEY;
            if (!apiKey) {
                return {
                    isError: true,
                    content: [{ type: "text", text: "Error: CLAUDE_API_KEY environment variable is not set." }]
                };
            }

            const endpoint = "https://api.anthropic.com/v1/messages";
            
            await logger.log(`Request: ${model}`, { messageCount: messages.length });

            try {
                const response = await fetch(endpoint, {
                    method: "POST",
                    headers: {
                        "x-api-key": apiKey,
                        "anthropic-version": "2023-06-01",
                        "content-type": "application/json"
                    },
                    body: JSON.stringify({
                        model,
                        messages,
                        system,
                        max_tokens
                    })
                });

                if (!response.ok) {
                    const errorText = await response.text();
                    throw new Error(`Claude API error: ${response.status} - ${errorText}`);
                }

                const data = await response.json();
                const textContent = data.content[0].text;
                
                await logger.log(`Response received`, { id: data.id });

                return {
                    content: [{
                        type: "text",
                        text: textContent
                    }]
                };

            } catch (error: any) {
                await logger.log(`Error`, { message: error.message });
                return {
                    isError: true,
                    content: [{ type: "text", text: `Claude error: ${error.message}` }]
                };
            }
        }
    );
}

import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { z } from "zod";
import { execCommand } from "../utils/exec.js";
import { config } from "../config/index.js";

const WHITELISTED_COMMANDS = ['suggest', 'explain', 'test', 'fix'];

export function registerCopilotCliTool(server: McpServer) {
    server.tool(
        "copilot_cli",
        "Executes GitHub Copilot CLI commands (suggest, explain, test, fix).",
        {
            subcommand: z.enum(['suggest', 'explain', 'test', 'fix']).describe("The copilot subcommand to run"),
            query: z.string().describe("The query or code snippet for Copilot"),
        },
        async ({ subcommand, query }) => {
            if (!WHITELISTED_COMMANDS.includes(subcommand)) {
                return {
                    isError: true,
                    content: [{ type: "text", text: `Command not allowed: ${subcommand}` }]
                };
            }

            try {
                // Construct args. Note: Copilot CLI structure might vary based on installation (alias vs direct).
                // Assuming 'gh copilot <subcommand> "<query>"' or 'copilot <subcommand> "<query>"'
                // We'll assume 'copilot' is in PATH or an alias. If it's 'gh copilot', we'd need to adjust.
                // Let's try 'gh copilot' as it's the standard extension way, or fall back to 'copilot' if user set alias.
                // Safe bet: 'gh copilot <subcommand> -- <query>' to avoid arg parsing issues.
                
                const args = ['copilot', subcommand, '--', query];
                
                const result = await execCommand('gh', args, {
                    cwd: config.workspaceRoot,
                    timeout: 60000 // Copilot might take a while
                });

                return {
                    content: [{
                        type: "text",
                        text: `Exit Code: ${result.exitCode}\n\nSTDOUT:\n${result.stdout}\n\nSTDERR:\n${result.stderr}`
                    }]
                };

            } catch (error: any) {
                return {
                    isError: true,
                    content: [{ type: "text", text: `Execution error: ${error.message}` }]
                };
            }
        }
    );
}

/**
 * Deployment Analyzer
 * 
 * Analyzes GitHub workflow failures:
 * 1. Parses error logs
 * 2. Identifies error type (build, test, lint, deploy)
 * 3. Extracts relevant context
 * 4. Generates fix prompt for Jules AI
 */

import { logInfo, logError } from '../utils/logger.js';

export type ErrorCategory = 'build' | 'test' | 'lint' | 'deploy' | 'deployment' | 'unknown';

export interface DeploymentAnalysis {
  type: ErrorCategory;
  summary: string;
  errorLocation?: {
    file: string;
    line?: number;
  };
  rawError: string;
  category: ErrorCategory;
  message: string;
  title: string;
  affectedFiles: string[];
  confidence: number;
  errors?: string[]; // Array of individual error messages
  suggestions?: string[]; // Suggested fixes
  errorCount?: number; // Number of errors found
}

export class DeploymentAnalyzer {
  /**
   * Analyzes CI/CD logs to identify the root cause of failure
   */
  static analyzeLogs(logs: string): DeploymentAnalysis {
    logInfo('DeploymentAnalyzer', 'Analyzing workflow logs');
    
    // 1. Detect error category
    const category = DeploymentAnalyzer.detectErrorCategory(logs);
    
    // 2. Extract error message
    const { title, message } = DeploymentAnalyzer.extractErrorMessage(logs);
    
    // 3. Extract location
    const errorLocation = DeploymentAnalyzer.extractErrorLocation(logs);
    
    // 4. Get affected files
    const affectedFiles = DeploymentAnalyzer.extractAffectedFiles(logs);
    
    // 5. Calculate confidence
    const confidence = DeploymentAnalyzer.calculateConfidence(category, errorLocation, message);

    // 6. Extract individual errors
    const errors = DeploymentAnalyzer.extractIndividualErrors(logs, category);

    // 7. Generate suggestions
    const suggestions = DeploymentAnalyzer.generateSuggestions(category, affectedFiles);

    logInfo('DeploymentAnalyzer', `Detected ${category} error with ${(confidence * 100).toFixed(0)}% confidence`);

    return {
      type: category,
      category,
      title,
      summary: message,
      message,
      errorLocation,
      rawError: logs.slice(0, 1000),
      affectedFiles,
      confidence,
      errors, // Individual error messages
      suggestions, // Suggested fixes
      errorCount: errors.length
    };
  }

  /**
   * Detect error category from log content
   */
  private static detectErrorCategory(logs: string): ErrorCategory {
    const patterns = {
      build: [
        /error TS\d+:/i,
        /SyntaxError/i,
        /failed to.*compile/i,
        /compilation failed/i,
        /module not found/i,
        /cannot find.*module/i
      ],
      deploy: [
        /deployment.*failed/i,
        /(push|pull|clone).*(failed|error)/i,
        /remote:.*error/i,
        /npm.*publish/i
      ],
      test: [
        /test failed/i,
        /assertion.*failed/i,
        / failing( test)?/i,
        /^\s*FAIL\s+/im,
        /mocha|jest|vitest/i,
        /expected.*to/i,
        /FAIL/i, // Added FAIL for Vitest output
        /failed/i // Generic failed
      ],
      lint: [
        /eslint|prettier|stylelint/i,
        /linting.*failed/i,
        /✖/i
      ]
    };

    for (const [category, categoryPatterns] of Object.entries(patterns)) {
      for (const pattern of categoryPatterns) {
        if (pattern.test(logs)) {
          return category as ErrorCategory;
        }
      }
    }
    return 'unknown';
  }

  /**
   * Extract error title and message from logs  
   */
  private static extractErrorMessage(logs: string): { title: string; message: string } {
    // 1. Check for TypeScript/Build errors
    if (logs.includes('error TS') || logs.includes('SyntaxError')) {
      const match = logs.match(/(?:error TS\d+:|SyntaxError:)(.+)/);
      const message = match ? match[1].trim() : 'Build failed with TypeScript errors';
      return { 
        title: 'Build Error', 
        message 
      };
    }

    // 2. Check for Test failures (Vitest/Jest)
    if (logs.includes('FAIL') || logs.includes('failing')) {
      return {
        title: 'Test Failed',
        message: 'Unit tests failed - see logs for details'
      };
    }

    // 3. Check for Lint errors (ESLint)
    if (logs.includes('eslint') || logs.includes('ESLint')) {
      return {
        title: 'Lint Error',
        message: 'Linting checks failed'
      };
    }

    // 4. Check for Deploy errors
    if (logs.includes('remote:') || logs.includes('push failed')) {
      return {
        title: 'Deployment Error',
        message: 'Deployment or git operation failed'
      };
    }

    // Default fallback
    return {
      title: 'Unknown Error',
      message: 'Unknown deployment error - see logs for details'
    };
  }

  /**
   * Extract error location (file and line number)
   */
  private static extractErrorLocation(logs: string): { file: string; line?: number } | undefined {
    // Match: file.ts:42:15 or file.ts(42,15)
    const match = logs.match(/([a-zA-Z0-9_/.-]+\.(?:ts|tsx|js|jsx|py))[:(](\d+)/);
    if (match) {
      return {
        file: match[1],
        line: parseInt(match[2], 10)
      };
    }
    return undefined;
  }

  /**
   * Extract affected files from logs
   */
  private static extractAffectedFiles(logs: string): string[] {
    const files = new Set<string>();
    const filePattern = new RegExp("(?:src|test|lib|app)\\/[^\\s:]+\\.(?:ts|tsx|js|jsx|py|go|rs)", "g");
    const matches = logs.match(filePattern);

    if (matches) {
      matches.forEach((match) => files.add(match));
    }

    return Array.from(files).slice(0, 5); // Top 5 files
  }

  /**
   * Calculate confidence score for the analysis
   */
  private static calculateConfidence(
    category: ErrorCategory,
    errorLocation: { file: string; line?: number } | undefined,
    message: string
  ): number {
    let score = 0.7; // Base score

    // Increase for clear categories
    if (category !== 'unknown') {
      score += 0.1;
    }

    // Increase if location found
    if (errorLocation) {
      score += 0.1;
    }

    // Decrease if message is vague
    if (message.includes('Unknown') || message.includes('unknown')) {
      score -= 0.1;
    }

    return Math.min(0.95, Math.max(0.3, score));
  }

  /**
   * Generates a prompt for Jules to fix the detected issue
   */
  static generateFixPrompt(analysis: DeploymentAnalysis, fileContent?: string): string {
    const errorCategory = analysis.category ? analysis.category.toUpperCase() : 'UNKNOWN';
    const basePrompt = `## Jules Continuous AI - Automated Fix Request

**Error Category:** ${errorCategory}
**Title:** ${analysis.title}  
**Confidence:** ${(analysis.confidence * 100).toFixed(0)}%

### Error Summary
${analysis.message}

### Raw Error Logs
\`\`\`
${analysis.rawError}
\`\`\`

${analysis.affectedFiles.length > 0 ? `### Affected Files\n${analysis.affectedFiles.map((f) => `- \`${f}\``).join('\n')}\n` : ''}`;

    if (analysis.errorLocation) {
      return `${basePrompt}

### Error Location
**File:** ${analysis.errorLocation.file}  
${analysis.errorLocation.line ? `**Line:** ${analysis.errorLocation.line}` : ''}

${fileContent ? `### File Content\n\`\`\`typescript\n${fileContent}\n\`\`\`` : ''}

### Task
1. Analyze the error and context
2. Identify root cause
3. Generate minimal fix (code changes only)
4. Create clear commit message
5. Return complete code diff

### Requirements
- Must resolve the ${analysis.category} error
- Preserve existing functionality
- Follow project code style
- Minimum test coverage: 80%
- No breaking changes
`;
    }

    return `${basePrompt}

### Task
1. Analyze the raw error logs above
2. Identify the likely root cause
3. Suggest the specific file and changes needed to fix
4. Provide detailed fix instructions

This is an automated request from the Jules Continuous AI Integration (JCAI).
`;
  }

  /**
   * Extract individual error messages from logs
   */
  private static extractIndividualErrors(logs: string, category: ErrorCategory): string[] {
    const errors: string[] = [];
    const lines = logs.split('\n');

    for (const line of lines) {
      const trimmed = line.trim();

      // Build errors
      if (category === 'build' && (trimmed.includes('[error]') || trimmed.includes('error'))) {
        errors.push(trimmed);
      }
      // Test errors
      else if (category === 'test' && (trimmed.includes('Expected') || trimmed.includes('Received'))) {
        errors.push(trimmed);
      }
      // Deployment errors
      else if (
        (category === 'deploy' || category === 'deployment') &&
        (trimmed.includes('[error]') || trimmed.includes('Error:'))
      ) {
        errors.push(trimmed);
      }

      if (errors.length >= 5) break; // Limit to 5 errors
    }

    return errors.length > 0 ? errors : [logs.split('\n')[0] || 'Unknown error'];
  }

  /**
   * Generate suggestions for fixing the error
   */
  private static generateSuggestions(category: ErrorCategory, affectedFiles: string[]): string[] {
    const suggestions: string[] = [];

    switch (category) {
      case 'build':
        suggestions.push('Check import statements and file paths');
        suggestions.push('Verify TypeScript configuration');
        suggestions.push('Ensure all dependencies are installed');
        break;

      case 'test':
        suggestions.push('Increase test timeout if needed');
        suggestions.push('Update mock data');
        suggestions.push('Review assertion logic');
        break;

      case 'lint':
        suggestions.push('Run eslint with --fix flag');
        suggestions.push('Check code formatting');
        suggestions.push('Verify style rules compliance');
        break;

      case 'deploy':
      case 'deployment':
        suggestions.push('Verify environment variables');
        suggestions.push('Check authentication credentials');
        suggestions.push('Review deployment configuration');
        break;

      default:
        suggestions.push('Review error logs carefully');
        suggestions.push('Check recent code changes');
        suggestions.push('Verify all dependencies are properly installed');
    }

    if (affectedFiles.length > 0) {
      suggestions.push(`Focus on: ${affectedFiles.slice(0, 3).join(', ')}`);
    }

    return suggestions;
  }
}

import { exec } from 'child_process';
import { promisify } from 'util';
import { logInfo, logError } from '../utils/logger.js';
import { config } from '../config/schema.js';

const execAsync = promisify(exec);

export interface GitOptions {
  cwd?: string;
}

export class GitAutomation {
  private workspaceRoot: string;

  constructor(workspaceRoot: string = process.cwd()) {
    this.workspaceRoot = workspaceRoot;
  }

  /**
   * Run a git command
   */
  async git(command: string): Promise<string> {
    try {
      const { stdout } = await execAsync(`git ${command}`, { cwd: this.workspaceRoot });
      return stdout.trim();
    } catch (error: any) {
      const msg = `Git command failed: git ${command} -> ${error.message}`;
      logError('GitAutomation', msg);
      throw new Error(msg);
    }
  }

  /**
   * Create a new branch for a fix
   */
  async createFixBranch(issueId: string): Promise<string> {
    const branchName = `fix/auto-${issueId}-${Date.now()}`;
    await this.git(`checkout -b ${branchName}`);
    logInfo('GitAutomation', `Created branch: ${branchName}`);
    return branchName;
  }

  /**
   * Commit changes
   */
  async commitChanges(message: string): Promise<void> {
    await this.git('add .');
    await this.git(`commit -m "${message}"`);
    logInfo('GitAutomation', `Committed changes: ${message}`);
  }

  /**
   * Push branch to remote
   */
  async pushBranch(branchName: string): Promise<void> {
    await this.git(`push origin ${branchName}`);
    logInfo('GitAutomation', `Pushed branch: ${branchName}`);
  }

  /**
   * Create a Pull Request (using GitHub API)
   */
  async createPullRequest(title: string, body: string, head: string, base: string = 'main'): Promise<string> {
    if (!config.githubToken) {
      throw new Error('GITHUB_TOKEN not configured');
    }

    // Get repo owner/name from remote origin
    const remoteUrl = await this.git('config --get remote.origin.url');
    // Extract owner/repo from URL (supports https and ssh)
    // HTTPS: https://github.com/owner/repo.git
    // SSH: git@github.com:owner/repo.git
    const match = remoteUrl.match(/github\.com[:/](.+?)\/(.+?)(\.git)?$/);
    
    if (!match) throw new Error('Could not parse repo name from remote');
    
    const owner = match[1];
    const repo = match[2];

    const url = `https://api.github.com/repos/${owner}/${repo}/pulls`;
    
    const response = await fetch(url, {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${config.githubToken}`,
        'Accept': 'application/vnd.github.v3+json',
        'Content-Type': 'application/json',
        'User-Agent': 'Brunella-GitAgent'
      },
      body: JSON.stringify({
        title,
        body,
        head,
        base
      })
    });

    if (!response.ok) {
      const errorText = await response.text();
      logError('GitAutomation', `Failed to create PR: ${errorText}`);
      throw new Error(`PR creation failed: ${response.statusText}`);
    }

    const data = await response.json();
    logInfo('GitAutomation', `Created PR: ${data.html_url}`);
    return data.html_url;
  }

  /**
   * Checkout main and pull latest
   */
  async resetToMain(): Promise<void> {
    await this.git('checkout main');
    await this.git('pull origin main');
  }
}

