import { spawn, ChildProcess } from 'child_process';
import { socketService } from '../server/SocketService.js';
import { logInfo, logError } from './logger.js';
import { updateProjectStatus } from './db.js';
import path from 'path';

interface ProjectProcess {
    process: ChildProcess;
    port: number;
    logs: string[];
}

class StudioRunner {
    private activeProjects: Map<string, ProjectProcess> = new Map();
    private nextPort = 5200;

    async startProject(projectId: string, rootDir: string): Promise<string> {
        if (this.activeProjects.has(projectId)) {
            return `http://localhost:${this.activeProjects.get(projectId)!.port}`;
        }

        const port = this.nextPort++;
        logInfo('StudioRunner', `Starting project ${projectId} on port ${port}`);

        // 1. Check if node_modules exists, if not run npm install
        const nmPath = path.join(rootDir, 'node_modules');
        try {
            await import('fs/promises').then(fs => fs.access(nmPath));
        } catch {
            logInfo('StudioRunner', `Installing dependencies for ${projectId}...`);
            socketService.emit('studio:log', { projectId, line: 'INSTALLING node_modules... (This may take a minute)', type: 'stdout' });
            
            try {
                // Synchronous install for now to ensure modules are there
                spawn('npm', ['install'], { cwd: rootDir, shell: true, stdio: 'inherit' });
                // Note: using sync might block, but spawn with 'inherit' is for debug. 
                // Let's use a promise wrapper for spawn instead.
                await this.runCommand('npm', ['install'], rootDir, projectId);
            } catch (err: any) {
                logError('StudioRunner', `Install failed: ${err.message}`);
            }
        }
        
        const child = spawn('npm', ['run', 'dev', '--', '--port', port.toString()], {
            cwd: rootDir,
            shell: true,
            env: { ...process.env, BROWSER: 'none' }
        });

        const projectProcess: ProjectProcess = {
            process: child,
            port,
            logs: []
        };

        this.activeProjects.set(projectId, projectProcess);

        child.stdout?.on('data', (data) => {
            const line = data.toString();
            projectProcess.logs.push(line);
            if (projectProcess.logs.length > 500) projectProcess.logs.shift();
            
            socketService.emit('studio:log', { projectId, line, type: 'stdout' });
            
            // Check if Vite is ready
            if (line.includes('Local:') || line.includes('ready in')) {
                updateProjectStatus(projectId, 'coding', `http://localhost:${port}`);
                socketService.emit('studio:ready', { projectId, url: `http://localhost:${port}` });
            }
        });

        child.stderr?.on('data', (data) => {
            const line = data.toString();
            projectProcess.logs.push(line);
            socketService.emit('studio:log', { projectId, line, type: 'stderr' });
        });

        child.on('close', (code) => {
            logInfo('StudioRunner', `Project ${projectId} stopped with code ${code}`);
            this.activeProjects.delete(projectId);
            updateProjectStatus(projectId, 'stopped');
            socketService.emit('studio:stopped', { projectId });
        });

        return `http://localhost:${port}`;
    }

    stopProject(projectId: string) {
        const project = this.activeProjects.get(projectId);
        if (project) {
            project.process.kill();
            this.activeProjects.delete(projectId);
        }
    }

    private runCommand(cmd: string, args: string[], cwd: string, projectId: string): Promise<void> {
        return new Promise((resolve, reject) => {
            const child = spawn(cmd, args, { cwd, shell: true });
            
            child.stdout?.on('data', (data) => {
                socketService.emit('studio:log', { projectId, line: data.toString(), type: 'stdout' });
            });

            child.stderr?.on('data', (data) => {
                socketService.emit('studio:log', { projectId, line: data.toString(), type: 'stderr' });
            });

            child.on('close', (code) => {
                if (code === 0) resolve();
                else reject(new Error(`${cmd} failed with code ${code}`));
            });
        });
    }

    getLogs(projectId: string): string[] {
        return this.activeProjects.get(projectId)?.logs || [];
    }
}

export const studioRunner = new StudioRunner();

/**
 * AI Gateway Wrapper (v3.0 - Pure Fetch API)
 *
 * Cloudflare AI Gateway + Workers AI integráció.
 * OpenAI SDK NÉLKÜL - egyszerű fetch API.
 *
 * Routing:
 * - AI_GATEWAY_ENABLED=true → CF Workers AI (llama-3.1)
 * - AI_GATEWAY_ENABLED=false → Local Ollama
 *
 * @author Brunella Core Team
 * @version 3.0.0
 */

import { logInfo, logError } from "./logger.js";

// ============================================================================
// CONFIGURATION
// ============================================================================

const AI_GATEWAY_ENABLED = process.env.AI_GATEWAY_ENABLED === "true";
const CF_ACCOUNT_ID =
  process.env.CF_ACCOUNT_ID || "dd107933ac970dac857f27cee7a7ff46";
const CF_GATEWAY_ID = process.env.CF_GATEWAY_ID || "brunella-gateway";
const CF_API_TOKEN = process.env.CF_AI_API_TOKEN || process.env.CF_API_TOKEN || process.env.CF_TOKEN;
const OLLAMA_BASE_URL = process.env.OLLAMA_BASE_URL || "http://127.0.0.1:11434";
const OLLAMA_MODEL = process.env.OLLAMA_MODEL || "llama3.1:8b";
const CF_MODEL = process.env.CF_MODEL || "@cf/meta/llama-3.1-8b-instruct";

// ============================================================================
// TYPES
// ============================================================================

export interface AIGatewayConfig {
  enabled: boolean;
  cfAccountId: string;
  cfGatewayId: string;
  cfApiToken?: string;
  cfModel: string;
  ollamaBaseUrl: string;
  ollamaModel: string;
}

export interface AIGatewayStats {
  totalRequests: number;
  cfRequests: number;
  ollamaRequests: number;
  errors: number;
  averageLatency: number;
}

export interface ChatMessage {
  role: "user" | "assistant" | "system";
  content: string;
}

// ============================================================================
// AI GATEWAY CLIENT (Pure Fetch)
// ============================================================================

export class AIGatewayClient {
  private config: AIGatewayConfig;
  private stats: AIGatewayStats;

  constructor(config?: Partial<AIGatewayConfig>) {
    this.config = {
      enabled: config?.enabled ?? AI_GATEWAY_ENABLED,
      cfAccountId: config?.cfAccountId || CF_ACCOUNT_ID,
      cfGatewayId: config?.cfGatewayId || CF_GATEWAY_ID,
      cfApiToken:
        config?.cfApiToken !== undefined ? config.cfApiToken : CF_API_TOKEN,
      cfModel: config?.cfModel || CF_MODEL,
      ollamaBaseUrl: config?.ollamaBaseUrl || OLLAMA_BASE_URL,
      ollamaModel: config?.ollamaModel || OLLAMA_MODEL,
    };

    this.stats = {
      totalRequests: 0,
      cfRequests: 0,
      ollamaRequests: 0,
      errors: 0,
      averageLatency: 0,
    };

    // Validate CF config
    if (this.config.enabled && !this.config.cfApiToken) {
      logError("AIGateway", "CF_API_TOKEN missing! Falling back to Ollama.");
      this.config.enabled = false;
    }

    const mode = this.config.enabled
      ? `CF Workers AI (${this.config.cfModel})`
      : `Ollama (${this.config.ollamaModel})`;
    logInfo("AIGateway", `✅ AI Gateway v3.0 initialized: ${mode}`);
  }

  // ========================================================================
  // PUBLIC API
  // ========================================================================

  /**
   * Chat completion (routing: CF Workers AI or Ollama)
   */
  async chat(
    messages: ChatMessage[],
    options?: {
      model?: string;
      temperature?: number;
      maxTokens?: number;
      forceLocal?: boolean;
    },
  ): Promise<string> {
    const startTime = Date.now();
    this.stats.totalRequests++;

    try {
      // Force local Ollama if requested
      if (options?.forceLocal || !this.config.enabled) {
        return await this.chatOllama(messages, options);
      }

      // Try CF Workers AI first
      try {
        return await this.callCFWorkerModel(options?.model || this.config.cfModel, messages, options);
      } catch (cfError) {
        logError("AIGateway", `CF failed, falling back to Ollama: ${cfError}`);
        return await this.chatOllama(messages, options);
      }
    } finally {
      this.updateLatency(Date.now() - startTime);
    }
  }

  /**
   * Simple generate (single prompt → response)
   */
  async generate(
    prompt: string,
    options?: {
      model?: string;
      temperature?: number;
      maxTokens?: number;
      forceLocal?: boolean;
    },
  ): Promise<string> {
    return this.chat([{ role: "user", content: prompt }], options);
  }

  /**
   * Generate embeddings (always Ollama - CF doesn't expose embeddings directly)
   */
  async embeddings(
    text: string,
    options?: { model?: string; expectedDimension?: number },
  ): Promise<number[]> {
    const startTime = Date.now();
    this.stats.totalRequests++;
    this.stats.ollamaRequests++;

    const expectedDimension = options?.expectedDimension ?? 768;

    try {
      const url = `${this.config.ollamaBaseUrl}/api/embeddings`;
      const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        signal: AbortSignal.timeout(5000),
        body: JSON.stringify({
          model: options?.model || "nomic-embed-text",
          prompt: text.slice(0, 8000),
        }),
      });

      if (!response.ok) {
        throw new Error(`Ollama embeddings error: ${response.status}`);
      }

      const data = (await response.json()) as { embedding?: number[] };
      this.updateLatency(Date.now() - startTime);

      return data.embedding || new Array(expectedDimension).fill(0);
    } catch (error) {
      this.stats.errors++;
      logError("AIGateway", `Embeddings failed: ${error}`);
      return new Array(expectedDimension).fill(0); // Zero vector fallback
    }
  }

  /**
   * List models (Ollama only)
   */
  async listModels(): Promise<string[]> {
    try {
      const response = await fetch(`${this.config.ollamaBaseUrl}/api/tags`);
      if (!response.ok) return [];

      const data = (await response.json()) as {
        models?: Array<{ name: string }>;
      };
      return data.models?.map((m) => m.name) || [];
    } catch {
      return [];
    }
  }

  // ========================================================================
  // CF WORKERS AI
  // ========================================================================

  /**
   * Call CF Workers AI with a specific model (public — used by BifrostGateway and ModelRouter).
   * Falls back to config.cfModel if model is empty.
   */
  async callCFWorkerModel(
    model: string,
    messages: ChatMessage[],
    options?: { temperature?: number; maxTokens?: number },
  ): Promise<string> {
    this.stats.cfRequests++;

    const resolvedModel = model || this.config.cfModel;
    const url = `https://gateway.ai.cloudflare.com/v1/${this.config.cfAccountId}/${this.config.cfGatewayId}/workers-ai/${resolvedModel}`;

    const response = await fetch(url, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${this.config.cfApiToken}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        messages,
        temperature: options?.temperature ?? 0.7,
        max_tokens: options?.maxTokens ?? 2048,
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`CF Workers AI error ${response.status}: ${errorText}`);
    }

    const data = (await response.json()) as {
      result?: { response?: string };
      response?: string;
    };

    // CF Workers AI response format
    const content = data.result?.response || data.response;
    if (!content) {
      throw new Error("Empty response from CF Workers AI");
    }

    logInfo("AIGateway", `CF response received (${resolvedModel})`);
    return content;
  }

  // ========================================================================
  // LOCAL OLLAMA
  // ========================================================================

  private async chatOllama(
    messages: ChatMessage[],
    options?: any,
  ): Promise<string> {
    this.stats.ollamaRequests++;

    const model = options?.model || this.config.ollamaModel;
    const url = `${this.config.ollamaBaseUrl}/api/chat`;

    const response = await fetch(url, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        model,
        messages,
        stream: false,
        options: {
          temperature: options?.temperature ?? 0.7,
          num_predict: options?.maxTokens ?? 2048,
        },
      }),
    });

    if (!response.ok) {
      throw new Error(`Ollama error: ${response.status}`);
    }

    const data = (await response.json()) as { message?: { content?: string } };
    const content = data.message?.content;

    if (!content) {
      throw new Error("Empty response from Ollama");
    }

    return content;
  }

  // ========================================================================
  // HELPERS
  // ========================================================================

  private updateLatency(latency: number): void {
    if (this.stats.averageLatency === 0) {
      this.stats.averageLatency = latency;
    } else {
      this.stats.averageLatency =
        this.stats.averageLatency * 0.9 + latency * 0.1;
    }
  }

  isUsingGateway(): boolean {
    return this.config.enabled;
  }

  getConfig(): AIGatewayConfig {
    return { ...this.config };
  }

  getStats(): AIGatewayStats {
    return { ...this.stats };
  }

  resetStats(): void {
    this.stats = {
      totalRequests: 0,
      cfRequests: 0,
      ollamaRequests: 0,
      errors: 0,
      averageLatency: 0,
    };
  }
}

