// FILE: src/utils/approvalManager.ts
// PURPOSE: Manage human-in-the-loop approvals for critical actions
// VERSION: 3.0

import { v4 as uuidv4 } from 'uuid';
import { logInfo, logWarn } from './logger.js';
import { activityFeed } from './activityFeed.js';

export interface ApprovalRequest {
    id: string;
    type: 'file_edit' | 'command_exec' | 'critical_action';
    description: string;
    metadata?: any;
    status: 'pending' | 'approved' | 'rejected' | 'expired';
    createdAt: number;
    expiresAt: number;
    response?: any;
    respondedAt?: number;
}

export type ApprovalAction = 'approve' | 'reject';

class ApprovalManager {
    private requests: Map<string, ApprovalRequest> = new Map();
    private readonly defaultTimeoutMs = 15 * 60 * 1000; // 15 minutes
    
    // Polling interval for waitForResponse
    private readonly pollIntervalMs = 500;

    /**
     * Create a new approval request.
     * Optionally waits for response if waitForResult is true.
     */
    async requestApproval(
        type: ApprovalRequest['type'],
        description: string,
        metadata?: any,
        timeoutMs: number = this.defaultTimeoutMs
    ): Promise<string> { // Returns ID immediately
        const id = uuidv4();
        const now = Date.now();
        
        const request: ApprovalRequest = {
            id,
            type,
            description,
            metadata,
            status: 'pending',
            createdAt: now,
            expiresAt: now + timeoutMs,
        };
        
        this.requests.set(id, request);
        logInfo('ApprovalManager', `New approval request [${id}]: ${type} - ${description}`);

        activityFeed.addActivity(
            'approval',
            'system',
            `Approval requested: ${type} - ${description}`,
            { requestId: id, type, description }
        );
        
        return id;
    }

    /**
     * Wait for a request to be resolved.
     */
    waitForResult(id: string): Promise<boolean> {
        return new Promise((resolve) => {
            const check = () => {
                const req = this.requests.get(id);
                if (!req) {
                    resolve(false);
                    return;
                }

                if (req.status === 'approved') {
                    resolve(true);
                } else if (req.status === 'rejected') {
                    resolve(false);
                } else if (Date.now() > req.expiresAt) {
                    if (req.status === 'pending') {
                        req.status = 'expired';
                        logWarn('ApprovalManager', `Request [${id}] expired`);
                        
                        activityFeed.addActivity(
                            'error',
                            'system',
                            `Approval request expired: ${req.description}`,
                            { requestId: id }
                        );
                    }
                    resolve(false);
                } else {
                    setTimeout(check, this.pollIntervalMs);
                }
            };
            check();
        });
    }

    /**
     * Respond to an approval request
     */
    respond(id: string, action: ApprovalAction, responsePayload?: any): boolean {
        const req = this.requests.get(id);
        if (!req) {
            logWarn('ApprovalManager', `Attempted to respond to unknown request [${id}]`);
            return false;
        }

        if (req.status !== 'pending') {
            logWarn('ApprovalManager', `Attempted to respond to non-pending request [${id}] (${req.status})`);
            return false;
        }

        if (Date.now() > req.expiresAt) {
            req.status = 'expired';
            logWarn('ApprovalManager', `Attempted to respond to expired request [${id}]`);
            return false;
        }

        req.status = action === 'approve' ? 'approved' : 'rejected';
        req.respondedAt = Date.now();
        req.response = responsePayload;
        
        logInfo('ApprovalManager', `Request [${id}] ${req.status}`);

        activityFeed.addActivity(
            action === 'approve' ? 'success' : 'warning',
            'user',
            `Approval request ${req.status}: ${req.description}`,
            { requestId: id, action, response: responsePayload }
        );

        return true;
    }

    /**
     * Get a specific request
     */
    getRequest(id: string): ApprovalRequest | undefined {
        return this.requests.get(id);
    }

    /**
     * List all requests, optionally filtered
     */
    listRequests(status?: ApprovalRequest['status']): ApprovalRequest[] {
        const all = Array.from(this.requests.values()).sort((a, b) => b.createdAt - a.createdAt);
        if (status) {
            return all.filter(r => r.status === status);
        }
        return all;
    }

    /**
     * Clean up old requests
     */
    cleanup(maxAgeMs: number = 24 * 60 * 60 * 1000): number {
        const now = Date.now();
        let count = 0;
        for (const [id, req] of this.requests) {
            if (now - req.createdAt > maxAgeMs && req.status !== 'pending') {
                this.requests.delete(id);
                count++;
            }
        }
        return count;
    }
}

export const approvalManager = new ApprovalManager();

/**
 * Background Task Manager
 *
 * Manages long-running browser automation tasks in the background.
 * Tasks > 30s estimated duration are executed asynchronously with:
 * - Progress tracking
 * - Checkpoint-based recovery (Phoenix Protocol)
 * - Real-time status updates (Socket.IO)
 *
 * @author Claude Code + Pohánka Péter
 * @track robotkezv2-full-comet-20260215
 * @phase Phase 4 - Background Task Manager
 */

import { persistentBrowser } from './persistentBrowser.js';
import { ExecutionPlan, ExecutionStep } from './llmPlanner.js';
import { logInfo, logWarn, logError } from './logger.js';
import {
    saveBackgroundTask,
    updateBackgroundTask,
    loadBackgroundTask,
    loadAllBackgroundTasks
} from './tasksDb.js';

/**
 * Background Task Status
 */
export type TaskStatus = 'running' | 'completed' | 'error' | 'cancelled';

/**
 * Task Step (completed step with status)
 */
export interface TaskStep extends ExecutionStep {
    status: 'completed' | 'error';
    error?: string;
    completedAt?: number; // timestamp
}

/**
 * Background Task Interface
 */
export interface BackgroundTask {
    id: string;
    instruction: string; // Original magyar instruction
    plan: ExecutionPlan;
    status: TaskStatus;
    progress: number; // 0-100
    startedAt: number; // timestamp
    completedAt?: number; // timestamp
    steps: TaskStep[]; // Completed steps
    currentStepIndex: number;
    error?: string;
    checkpoints: TaskCheckpoint[]; // Phoenix recovery checkpoints
}

/**
 * Task Checkpoint (Phoenix Protocol)
 * Created every 3 steps for recovery
 */
export interface TaskCheckpoint {
    stepIndex: number;
    timestamp: number;
    completedSteps: TaskStep[];
}

/**
 * Background Task Manager
 * Singleton class managing async browser automation tasks
 */
class BackgroundTaskManager {
    private tasks: Map<string, BackgroundTask> = new Map();
    private runningTasks: Set<string> = new Set();
    private initialized: boolean = false;

    /**
     * Initialize BackgroundTaskManager and recover tasks from database
     * Call this once on app startup
     */
    async initialize(): Promise<void> {
        if (this.initialized) return;

        logInfo('BackgroundTaskManager', 'Initializing and recovering tasks from database...');

        try {
            const dbTasks = await loadAllBackgroundTasks(100);

            for (const task of dbTasks) {
                this.tasks.set(task.id, task);

                // If task was running when app crashed, mark it for potential recovery
                if (task.status === 'running') {
                    logWarn('BackgroundTaskManager', `Found interrupted task ${task.id}: "${task.instruction}"`);
                    // Don't auto-restart, just load into memory
                    // User can manually replay via replaySteps()
                }
            }

            logInfo('BackgroundTaskManager', `Recovered ${dbTasks.length} tasks from database`);
            this.initialized = true;

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('BackgroundTaskManager', `Failed to initialize from DB: ${msg}`);
        }
    }

    /**
     * Start a new background task
     *
     * @param instruction - Original magyar instruction
     * @param plan - ExecutionPlan from LLM
     * @returns Task ID
     */
    async startTask(instruction: string, plan: ExecutionPlan): Promise<string> {
        const taskId = this.generateTaskId();

        const task: BackgroundTask = {
            id: taskId,
            instruction,
            plan,
            status: 'running',
            progress: 0,
            startedAt: Date.now(),
            steps: [],
            currentStepIndex: 0,
            checkpoints: []
        };

        this.tasks.set(taskId, task);
        this.runningTasks.add(taskId);

        // Persist to database
        await saveBackgroundTask(task).catch(err => {
            logWarn('BackgroundTaskManager', `Failed to save task ${taskId} to DB: ${err.message}`);
        });

        logInfo('BackgroundTaskManager', `▶️ Started task ${taskId}: "${instruction}" (${plan.plan.length} steps)`);

        // Execute in background (non-blocking)
        this.executeTaskInBackground(taskId).catch((error) => {
            logError('BackgroundTaskManager', `Task ${taskId} failed: ${error.message}`);
            this.updateTaskStatus(taskId, 'error', error.message);
        });

        return taskId;
    }

    /**
     * Get task status
     *
     * @param taskId - Task ID
     * @returns BackgroundTask or null if not found
     */
    getTaskStatus(taskId: string): BackgroundTask | null {
        return this.tasks.get(taskId) || null;
    }

    /**
     * Get all tasks (sorted by startedAt desc)
     *
     * @returns Array of BackgroundTask
     */
    getAllTasks(): BackgroundTask[] {
        return Array.from(this.tasks.values()).sort((a, b) => b.startedAt - a.startedAt);
    }

    /**
     * Cancel a running task
     *
     * @param taskId - Task ID
     * @returns boolean - true if cancelled, false if not running
     */
    cancelTask(taskId: string): boolean {
        const task = this.tasks.get(taskId);
        if (!task || task.status !== 'running') {
            return false;
        }

        task.status = 'cancelled';
        task.completedAt = Date.now();
        this.runningTasks.delete(taskId);

        logWarn('BackgroundTaskManager', `❌ Task ${taskId} cancelled by user`);
        return true;
    }

    /**
     * Execute task in background (async)
     * Non-blocking - runs independently of main thread
     *
     * @param taskId - Task ID
     */
    private async executeTaskInBackground(taskId: string): Promise<void> {
        const task = this.tasks.get(taskId);
        if (!task) {
            throw new Error(`Task ${taskId} not found`);
        }

        const { plan } = task;

        try {
            for (let i = 0; i < plan.plan.length; i++) {
                // Check if task was cancelled
                if (task.status === 'cancelled') {
                    logWarn('BackgroundTaskManager', `Task ${taskId} cancelled at step ${i}`);
                    break;
                }

                const step = plan.plan[i];
                task.currentStepIndex = i;

                logInfo('BackgroundTaskManager', `▶️ Task ${taskId} - Step ${i + 1}/${plan.plan.length}: ${step.description}`);

                try {
                    // Execute step
                    await this.executeStep(step);

                    // Mark step as completed
                    const completedStep: TaskStep = {
                        ...step,
                        status: 'completed',
                        completedAt: Date.now()
                    };
                    task.steps.push(completedStep);

                    // Update progress (percentage)
                    task.progress = Math.round(((i + 1) / plan.plan.length) * 100);

                    logInfo('BackgroundTaskManager', `✅ Task ${taskId} - Step ${i + 1} completed (${task.progress}%)`);

                    // Persist progress to database
                    await updateBackgroundTask(task).catch(err => {
                        logWarn('BackgroundTaskManager', `Failed to update task ${taskId} progress in DB: ${err.message}`);
                    });

                    // Create checkpoint every 3 steps (Phoenix Protocol)
                    if ((i + 1) % 3 === 0) {
                        this.createCheckpoint(taskId, i, task.steps);
                        // Persist checkpoint to database
                        await updateBackgroundTask(task).catch(err => {
                            logWarn('BackgroundTaskManager', `Failed to save checkpoint for task ${taskId}: ${err.message}`);
                        });
                    }

                } catch (stepError: unknown) {
                    const msg = stepError instanceof Error ? stepError.message : String(stepError);
                    logError('BackgroundTaskManager', `❌ Task ${taskId} - Step ${i + 1} failed: ${msg}`);

                    const errorStep: TaskStep = {
                        ...step,
                        status: 'error',
                        error: msg,
                        completedAt: Date.now()
                    };
                    task.steps.push(errorStep);

                    // Decide: continue or stop on error?
                    // For now: stop on critical errors (navigate, click, type)
                    if (['navigate', 'click', 'type'].includes(step.action)) {
                        throw new Error(`Critical step failed: ${step.description} - ${msg}`);
                    }
                    // Non-critical errors (screenshot, scroll): continue
                    logWarn('BackgroundTaskManager', `⚠️ Non-critical error, continuing...`);
                }
            }

            // All steps completed successfully
            this.updateTaskStatus(taskId, 'completed');
            logInfo('BackgroundTaskManager', `✅ Task ${taskId} completed (${task.steps.length} steps)`);

        } catch (error: unknown) {
            const msg = error instanceof Error ? error.message : String(error);
            logError('BackgroundTaskManager', `❌ Task ${taskId} failed: ${msg}`);
            this.updateTaskStatus(taskId, 'error', msg);
        }
    }

    /**
     * Execute a single step (browser action)
     *
     * @param step - ExecutionStep
     */
    private async executeStep(step: ExecutionStep): Promise<void> {
        switch (step.action) {
            case 'navigate':
                await persistentBrowser.sendCommand({
                    action: 'navigate',
                    url: step.url!
                });
                break;

            case 'click':
                await persistentBrowser.sendCommand({
                    action: 'click',
                    selector: step.selector!
                });
                break;

            case 'type':
                await persistentBrowser.sendCommand({
                    action: 'type',
                    selector: step.selector!,
                    text: step.text!
                });
                break;

            case 'scroll':
                await persistentBrowser.sendCommand({
                    action: 'scroll',
                    direction: step.direction || 'down',
                    amount: step.amount || 300
                });
                break;

            case 'wait':
                await persistentBrowser.sendCommand({
                    action: 'wait',
                    selector: step.selector!,
                    timeout: step.timeout || 5000
                });
                break;

            case 'screenshot':
                await persistentBrowser.sendCommand({
                    action: 'screenshot'
                });
                break;

            case 'extract':
                await persistentBrowser.sendCommand({
                    action: 'extract',
                    selector: step.selector!,
                    type: step.type || 'text',
                    attribute: step.attribute
                });
                break;

            default:
                throw new Error(`Unknown action: ${step.action}`);
        }
    }

    /**
     * Update task status
     *
     * @param taskId - Task ID
     * @param status - New status
     * @param error - Optional error message
     */
    private updateTaskStatus(taskId: string, status: TaskStatus, error?: string): void {
        const task = this.tasks.get(taskId);
        if (!task) return;

        task.status = status;
        task.completedAt = Date.now();
        if (error) {
            task.error = error;
        }

        this.runningTasks.delete(taskId);

        // Persist to database
        updateBackgroundTask(task).catch(err => {
            logWarn('BackgroundTaskManager', `Failed to update task ${taskId} in DB: ${err.message}`);
        });
    }

    /**
     * Create checkpoint (Phoenix Protocol)
     *
     * @param taskId - Task ID
     * @param stepIndex - Current step index
     * @param completedSteps - Completed steps so far
     */
    private createCheckpoint(taskId: string, stepIndex: number, completedSteps: TaskStep[]): void {
        const task = this.tasks.get(taskId);
        if (!task) return;

        const checkpoint: TaskCheckpoint = {
            stepIndex,
            timestamp: Date.now(),
            completedSteps: [...completedSteps] // Deep copy
        };

        task.checkpoints.push(checkpoint);
        logInfo('BackgroundTaskManager', `📌 Checkpoint created for task ${taskId} at step ${stepIndex + 1}`);
    }

    /**
     * Load last checkpoint (Phoenix recovery)
     *
     * @param taskId - Task ID
     * @returns TaskCheckpoint or null if no checkpoints
     */
    loadLastCheckpoint(taskId: string): TaskCheckpoint | null {
        const task = this.tasks.get(taskId);
        if (!task || task.checkpoints.length === 0) {
            return null;
        }

        return task.checkpoints[task.checkpoints.length - 1];
    }

    /**
     * Replay steps from last checkpoint (Phoenix recovery)
     *
     * @param taskId - Task ID
     * @returns boolean - true if replay started, false if no checkpoint
     */
    async replaySteps(taskId: string): Promise<boolean> {
        const checkpoint = this.loadLastCheckpoint(taskId);
        if (!checkpoint) {
            logWarn('BackgroundTaskManager', `No checkpoint found for task ${taskId}`);
            return false;
        }

        const task = this.tasks.get(taskId);
        if (!task) return false;

        logInfo('BackgroundTaskManager', `🔄 Replaying task ${taskId} from step ${checkpoint.stepIndex + 1}`);

        // Restore task state from checkpoint
        task.steps = [...checkpoint.completedSteps];
        task.currentStepIndex = checkpoint.stepIndex + 1; // Resume from next step
        task.status = 'running';
        task.progress = Math.round(((checkpoint.stepIndex + 1) / task.plan.plan.length) * 100);

        this.runningTasks.add(taskId);

        // Continue execution from checkpoint
        this.executeTaskInBackground(taskId).catch((error) => {
            logError('BackgroundTaskManager', `Replay failed for task ${taskId}: ${error.message}`);
            this.updateTaskStatus(taskId, 'error', error.message);
        });

        return true;
    }

    /**
     * Generate unique task ID
     *
     * @returns string - UUID-like task ID
     */
    private generateTaskId(): string {
        return `task_${Date.now()}_${Math.random().toString(36).substring(2, 9)}`;
    }
}

// Export singleton instance
export const backgroundTaskManager = new BackgroundTaskManager();

import fs from 'fs';
import path from 'path';
import os from 'os';

/** Flat legacy keys for backward compatibility */
export interface CliSettingsLegacy {
  serverUrl: string;
  apiKey?: string;
  theme?: 'dark' | 'light';
}

/** Gemini-style nested categories (subset for parity) */
export interface BrunellaSettingsSchema {
  general?: {
    preferredEditor?: string;
    vimMode?: boolean;
    previewFeatures?: boolean;
    language?: 'hu' | 'en';
  };
  ui?: {
    theme?: string;
    hideBanner?: boolean;
    hideTips?: boolean;
    hideFooter?: boolean;
  };
  output?: {
    format?: 'text' | 'json';
  };
  model?: {
    name?: string;
    maxSessionTurns?: number;
  };
  modelConfigs?: {
    aliases?: Record<string, { model?: string; extends?: string; modelConfig?: Record<string, unknown> }>;
  };
  context?: {
    fileName?: string | string[];
    includeDirectories?: string[];
    discoveryMaxDirs?: number;
  };
  tools?: {
    approvalMode?: 'default' | 'auto_edit' | 'plan' | 'yolo';
    autoAccept?: boolean;
    allowed?: string[];
    exclude?: string[];
    /** Sandbox: true/false or path to profile (e.g. "docker", ".brunella/sandbox.Dockerfile"). */
    sandbox?: boolean | string;
  };
  mcp?: {
    serverCommand?: string;
    allowed?: string[];
    excluded?: string[];
  };
  telemetry?: {
    enabled?: boolean;
    target?: 'local' | 'gcp';
    otlpEndpoint?: string;
    otlpProtocol?: 'grpc' | 'http';
    outfile?: string;
    logPrompts?: boolean;
    useCollector?: boolean;
    useCliAuth?: boolean;
  };
  privacy?: {
    usageStatisticsEnabled?: boolean;
  };
  skills?: {
    enabled?: boolean;
    disabled?: string[];
  };
  hooksConfig?: {
    enabled?: boolean;
    disabled?: string[];
  };
  admin?: {
    secureModeEnabled?: boolean;
    mcp?: { enabled?: boolean };
    skills?: { enabled?: boolean };
  };
  security?: {
    auth?: {
      selectedType?: 'api_key' | 'oauth' | 'cli';
      enforcedType?: string;
      useExternal?: boolean;
    };
  };
}

/** Combined: legacy flat + nested. Legacy keys take precedence when reading serverUrl/theme for compat. */
export type CliSettings = CliSettingsLegacy & BrunellaSettingsSchema;

const DEFAULT_LEGACY: CliSettingsLegacy = {
  serverUrl: 'http://localhost:3000',
  theme: 'dark'
};

const DEFAULT_NESTED: BrunellaSettingsSchema = {
  general: { vimMode: false, previewFeatures: false, language: 'hu' },
  ui: { theme: 'dark', hideBanner: false, hideTips: false, hideFooter: false },
  output: { format: 'text' },
  model: { maxSessionTurns: -1 },
  context: { fileName: ['BRUNELLA.md', 'GEMINI.md'], discoveryMaxDirs: 200 },
  tools: { approvalMode: 'default', autoAccept: false, allowed: [], exclude: [] },
  telemetry: {
    enabled: false,
    target: 'local',
    otlpEndpoint: 'http://localhost:4317',
    otlpProtocol: 'grpc',
    logPrompts: true,
    useCollector: false
  },
  privacy: { usageStatisticsEnabled: true },
  skills: { enabled: true, disabled: [] },
  hooksConfig: { enabled: true, disabled: [] },
  admin: { secureModeEnabled: false, mcp: { enabled: true }, skills: { enabled: true } }
};

const ENV_MAP: Array<{ env: string; key: string }> = [
  { env: 'BRUNELLA_SERVER_URL', key: 'serverUrl' },
  { env: 'BRUNELLA_API_KEY', key: 'apiKey' },
  { env: 'BRUNELLA_THEME', key: 'theme' },
  { env: 'BRUNELLA_TELEMETRY_ENABLED', key: 'telemetry.enabled' },
  { env: 'BRUNELLA_TELEMETRY_TARGET', key: 'telemetry.target' },
  { env: 'BRUNELLA_TELEMETRY_OTLP_ENDPOINT', key: 'telemetry.otlpEndpoint' },
  { env: 'BRUNELLA_TELEMETRY_OTLP_PROTOCOL', key: 'telemetry.otlpProtocol' },
  { env: 'BRUNELLA_TELEMETRY_OUTFILE', key: 'telemetry.outfile' },
  { env: 'BRUNELLA_TELEMETRY_LOG_PROMPTS', key: 'telemetry.logPrompts' },
  { env: 'BRUNELLA_TELEMETRY_USE_COLLECTOR', key: 'telemetry.useCollector' },
  { env: 'BRUNELLA_TELEMETRY_USE_CLI_AUTH', key: 'telemetry.useCliAuth' },
  { env: 'BRUNELLA_MODEL', key: 'model.name' },
  { env: 'BRUNELLA_OUTPUT_FORMAT', key: 'output.format' },
  { env: 'BRUNELLA_SANDBOX', key: 'tools.sandbox' }
];

function deepMerge<T extends Record<string, unknown>>(target: T, source: Partial<T>): T {
  const out = { ...target };
  for (const k of Object.keys(source) as (keyof T)[]) {
    const v = source[k];
    if (v === undefined) continue;
    if (typeof v === 'object' && v !== null && !Array.isArray(v) && typeof (out as Record<string, unknown>)[k as string] === 'object') {
      (out as Record<string, unknown>)[k as string] = deepMerge(
        (out as Record<string, unknown>)[k as string] as Record<string, unknown>,
        v as Record<string, unknown>
      );
    } else {
      (out as Record<string, unknown>)[k as string] = v;
    }
  }
  return out;
}

function setByPath(obj: Record<string, unknown>, keyPath: string, value: unknown): void {
  const parts = keyPath.split('.');
  let cur: Record<string, unknown> = obj;
  for (let i = 0; i < parts.length - 1; i++) {
    const p = parts[i];
    if (!(p in cur) || typeof cur[p] !== 'object') cur[p] = {};
    cur = cur[p] as Record<string, unknown>;
  }
  cur[parts[parts.length - 1]] = value;
}

function getByPath(obj: Record<string, unknown>, keyPath: string): unknown {
  const parts = keyPath.split('.');
  let cur: Record<string, unknown> = obj;
  for (const p of parts) {
    if (cur == null || typeof cur !== 'object') return undefined;
    cur = cur[p] as Record<string, unknown>;
  }
  return cur;
}

function parseEnvBool(v: string | undefined): boolean {
  if (v === undefined) return false;
  const lower = String(v).toLowerCase();
  return lower === 'true' || lower === '1';
}

function getSystemDefaultsPath(): string | null {
  const env = process.env.BRUNELLA_CLI_SYSTEM_DEFAULTS_PATH;
  if (env) return env;
  const plat = process.platform;
  if (plat === 'win32') return path.join(process.env.PROGRAMDATA || 'C:/ProgramData', 'brunella-cli', 'system-defaults.json');
  if (plat === 'darwin') return path.join(os.homedir(), 'Library', 'Application Support', 'BrunellaCli', 'system-defaults.json');
  return '/etc/brunella-cli/system-defaults.json';
}

function getSystemSettingsPath(): string | null {
  const env = process.env.BRUNELLA_CLI_SYSTEM_SETTINGS_PATH;
  if (env) return env;
  const plat = process.platform;
  if (plat === 'win32') return path.join(process.env.PROGRAMDATA || 'C:/ProgramData', 'brunella-cli', 'settings.json');
  if (plat === 'darwin') return path.join(os.homedir(), 'Library', 'Application Support', 'BrunellaCli', 'settings.json');
  return '/etc/brunella-cli/settings.json';
}

/** Detect legacy flat format (only serverUrl/apiKey/theme at top level, no nested categories). */
function isLegacyFlat(obj: Record<string, unknown>): boolean {
  const keys = Object.keys(obj).filter((k) => obj[k] !== undefined);
  const legacy = ['serverUrl', 'apiKey', 'theme'];
  if (keys.length === 0) return false;
  const hasNested = keys.some((k) => !legacy.includes(k));
  return !hasNested && keys.some((k) => legacy.includes(k));
}

/** Migrate flat { serverUrl, apiKey, theme } into nested shape and return merged with defaults. */
function migrateLegacyToNested(flat: Record<string, unknown>): Record<string, unknown> {
  const out: Record<string, unknown> = { ...DEFAULT_LEGACY, ...DEFAULT_NESTED } as unknown as Record<string, unknown>;
  if (flat.serverUrl !== undefined) out.serverUrl = flat.serverUrl;
  if (flat.apiKey !== undefined) out.apiKey = flat.apiKey;
  if (flat.theme !== undefined) {
    out.theme = flat.theme;
    if (!out.ui) out.ui = {};
    (out.ui as Record<string, unknown>).theme = flat.theme;
  }
  return out;
}

export class ConfigManager {
  private userConfigPath: string;
  private projectConfigPath: string | null;
  private settings: CliSettings;
  private cwd: string;

  constructor(cwd: string = process.cwd()) {
    this.cwd = cwd;
    const homeDir = os.homedir();
    const configDir = path.join(homeDir, '.brunella');
    if (!fs.existsSync(configDir)) {
      fs.mkdirSync(configDir, { recursive: true });
    }
    this.userConfigPath = path.join(configDir, 'settings.json');
    this.projectConfigPath = this.findProjectSettings();
    this.settings = this.loadSettings();
  }

  private findProjectSettings(): string | null {
    let dir = this.cwd;
    const projectFile = path.join(dir, '.brunella', 'settings.json');
    if (fs.existsSync(projectFile)) return projectFile;
    const root = path.parse(dir).root;
    while (dir !== root) {
      dir = path.dirname(dir);
      const p = path.join(dir, '.brunella', 'settings.json');
      if (fs.existsSync(p)) return p;
    }
    return null;
  }

  private loadJson(filePath: string): Record<string, unknown> {
    if (!fs.existsSync(filePath)) return {};
    try {
      const data = fs.readFileSync(filePath, 'utf-8');
      return JSON.parse(data) as Record<string, unknown>;
    } catch {
      return {};
    }
  }

  private loadSettings(): CliSettings {
    let base = { ...DEFAULT_LEGACY, ...DEFAULT_NESTED } as CliSettings;

    const sysDefaultsPath = getSystemDefaultsPath();
    if (sysDefaultsPath && fs.existsSync(sysDefaultsPath)) {
      const raw = this.loadJson(sysDefaultsPath);
      base = deepMerge(base as any, raw as any) as CliSettings;
    }

    let userRaw = this.loadJson(this.userConfigPath) as any;
    if (userRaw && Object.keys(userRaw).length > 0 && isLegacyFlat(userRaw)) {
      const migrated = migrateLegacyToNested(userRaw);
      try {
        fs.writeFileSync(this.userConfigPath, JSON.stringify(migrated, null, 2), 'utf-8');
      } catch {
        /* migration write best-effort */
      }
      userRaw = migrated;
    }

    let merged = deepMerge(base as any, userRaw as any) as CliSettings;

    if (this.projectConfigPath) {
      const projRaw = this.loadJson(this.projectConfigPath);
      merged = deepMerge(merged as any, projRaw as any) as CliSettings;
    }

    const sysSettingsPath = getSystemSettingsPath();
    if (sysSettingsPath && fs.existsSync(sysSettingsPath)) {
      const sysRaw = this.loadJson(sysSettingsPath);
      merged = deepMerge(merged as any, sysRaw as any) as CliSettings;
    }

    const mergedObj = merged as unknown as Record<string, unknown>;
    for (const { env, key } of ENV_MAP) {
      const v = process.env[env];
      if (v === undefined) continue;
      if (key === 'telemetry.enabled' || key === 'telemetry.logPrompts' || key === 'telemetry.useCollector' || key === 'telemetry.useCliAuth') {
        setByPath(mergedObj, key, parseEnvBool(v));
      } else {
        setByPath(mergedObj, key, v);
      }
    }

    if (merged.theme === undefined) merged.theme = DEFAULT_LEGACY.theme;
    if (merged.serverUrl === undefined) merged.serverUrl = DEFAULT_LEGACY.serverUrl;
    return merged;
  }

  /** Get by dot path (e.g. "general.vimMode") or legacy key ("serverUrl"). */
  public get<K extends keyof CliSettings>(key: K): CliSettings[K];
  public get(key: string): unknown;
  public get(key: string): unknown {
    if (key in this.settings && !key.includes('.')) {
      return this.settings[key as keyof CliSettings];
    }
    return getByPath(this.settings as unknown as Record<string, unknown>, key);
  }

  public getAll(): CliSettings {
    return JSON.parse(JSON.stringify(this.settings)) as CliSettings;
  }

  /** Set by dot path or legacy key. Persists to user file only; nested keys are merged. */
  public set(key: string, value: unknown): void {
    if (key in this.settings && !key.includes('.') && (key === 'serverUrl' || key === 'apiKey' || key === 'theme')) {
      (this.settings as any)[key] = value;
    } else {
      setByPath(this.settings as unknown as Record<string, unknown>, key, value);
    }
    this.saveUser();
  }

  public setAll(updates: Partial<CliSettings>): void {
    this.settings = deepMerge(this.settings as any, updates as any) as CliSettings;
    this.saveUser();
  }

  private saveUser(): void {
    const dir = path.dirname(this.userConfigPath);
    if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
    fs.writeFileSync(this.userConfigPath, JSON.stringify(this.settings, null, 2), 'utf-8');
  }

  get userSettingsPath(): string {
    return this.userConfigPath;
  }

  get projectSettingsPath(): string | null {
    return this.projectConfigPath;
  }
}

