export interface CloudflareTaskResponse {
  success: boolean;
  taskId: string;
  type: string;
  result?: unknown;
  message: string;
}

type CloudflareHistoryResponse = {
  tasks?: unknown[];
};

export class CloudflareClient {
  private baseUrl: string;
  private apiToken?: string;
  private ceanApiKey?: string;

  constructor(url?: string) {
    this.baseUrl =
      url ||
      process.env.CLOUDFLARE_D1_WORKER_URL ||
      process.env.CLOUDFLARE_WORKER_URL ||
      "https://cean-orchestrator.iam-dd1.workers.dev";
    this.apiToken = process.env.CLOUDFLARE_API_TOKEN || process.env.CF_API_TOKEN;
    this.ceanApiKey = process.env.CEAN_API_KEY;
  }

  getResolvedBaseUrl(): string {
    return this.baseUrl;
  }

  private getAuthHeaders(): Record<string, string> {
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    if (this.apiToken) {
      headers.Authorization = `Bearer ${this.apiToken}`;
      headers["X-BAS-API-Key"] = this.apiToken;
    }

    if (this.ceanApiKey) {
      headers["X-CEAN-API-Key"] = this.ceanApiKey;
    }

    return headers;
  }

  private getAxiosErrorMessage(error: unknown): string {
    if (typeof error === "object" && error !== null) {
      const maybeResponse = (error as { response?: { data?: { error?: unknown } } }).response;
      const responseError = maybeResponse?.data?.error;
      if (typeof responseError === "string" && responseError.trim().length > 0) {
        return responseError;
      }

      const maybeMessage = (error as { message?: unknown }).message;
      if (typeof maybeMessage === "string" && maybeMessage.trim().length > 0) {
        return maybeMessage;
      }
    }

    return String(error);
  }

  async submitTask(
    instruction: string,
    context: Record<string, unknown> = {},
  ): Promise<CloudflareTaskResponse> {
    try {
      const response = await axios.post<CloudflareTaskResponse>(
        `${this.baseUrl}/task`,
        {
          instruction,
          context,
        },
        {
          headers: this.getAuthHeaders(),
          timeout: 60000, // A kódgenerálás eltarthat egy ideig
        },
      );

      return response.data;
    } catch (error: unknown) {
      const message = this.getAxiosErrorMessage(error);
      throw new Error(`Cloudflare submission failed: ${message}`);
    }
  }

  async checkStatus(taskId: string): Promise<unknown> {
    try {
      const response = await axios.get(`${this.baseUrl}/status/${taskId}`);
      return response.data;
    } catch (error: unknown) {
      const message = this.getAxiosErrorMessage(error);
      throw new Error(`Status check failed: ${message}`);
    }
  }

  async fetchHistory(limit: number = 20): Promise<CloudflareHistoryResponse> {
    try {
      const response = await axios.get<CloudflareHistoryResponse>(`${this.baseUrl}/history?limit=${limit}`);
      return response.data;
    } catch (error: unknown) {
      const message = this.getAxiosErrorMessage(error);
      throw new Error(`History fetch failed: ${message}`);
    }
  }
}

export const cloudflareClient = new CloudflareClient();

/**
 * dagSort.ts — Kahn-algoritmus topológiai rendezéshez
 * Track: bas_orchestration_chain_20260221 / Phase 2
 *
 * A DFS-alapú detectCycle() mellé ez a BFS-alapú Kahn-sort garantálja
 * a determinisztikus végrehajtási sorrendet DAG-okban.
 */

import type { MicroTask } from '../agents/taskDecomposerCore.js';

/**
 * Kahn-algoritmus: topológiai rendezés irányított aciklikus gráfon.
 *
 * @param tasks - MicroTask[] ahol minden task tartalmaz `dependencies: string[]`
 * @returns Topológiailag rendezett MicroTask[] (dependencies előbb, dependensek később)
 * @throws Error ha kör van a gráfban
 */
export function kahnSort(tasks: MicroTask[]): MicroTask[] {
  if (tasks.length === 0) return [];

  const byId = new Map<string, MicroTask>(tasks.map(t => [t.id, t]));

  // In-degree: hány bejövő él van minden csomópontnak
  const inDegree = new Map<string, number>();
  for (const t of tasks) {
    if (!inDegree.has(t.id)) inDegree.set(t.id, 0);
  }
  for (const t of tasks) {
    for (const dep of t.dependencies) {
      // dep → t él: t in-degree-je nő
      inDegree.set(t.id, (inDegree.get(t.id) ?? 0) + 1);
    }
  }

  // Kezdőpont: 0 in-degree csomópontok (nincs függőségük)
  const queue: string[] = [];
  for (const [id, deg] of inDegree) {
    if (deg === 0) queue.push(id);
  }

  const sorted: MicroTask[] = [];

  while (queue.length > 0) {
    const id = queue.shift()!;
    const task = byId.get(id);
    if (task) sorted.push(task);

    // Csökkentjük az erre a csomópontra támaszkodó taskok in-degree-jét
    for (const t of tasks) {
      if (t.dependencies.includes(id)) {
        const newDeg = (inDegree.get(t.id) ?? 0) - 1;
        inDegree.set(t.id, newDeg);
        if (newDeg === 0) queue.push(t.id);
      }
    }
  }

  // Ha nem minden csomópontot rendeztünk → kör van
  if (sorted.length !== tasks.length) {
    const remaining = tasks
      .filter(t => !sorted.some(s => s.id === t.id))
      .map(t => t.id);
    throw new Error(
      `DAG kör detektálva (Kahn): érintett csomópontok → ${remaining.join(', ')}`,
    );
  }

  return sorted;
}

import { config } from '../config/index.js';
