/**
 * Graceful Degradation Policy — Phoenix Protocol v2 (Phase 4)
 *
 * Defines how the system operates when services are unavailable.
 * Ensures partial functionality instead of complete failure.
 *
 * @version 1.0.0
 */

import { logInfo, logWarn, logError } from './logger.js';
import { phoenixEventBus } from '../core/phoenixEventBus.js';

// ---------------------------------------------------------------------------
// TYPES
// ---------------------------------------------------------------------------

export type DegradationLevel = 'full' | 'partial' | 'minimal' | 'offline';

export interface DegradationState {
  level: DegradationLevel;
  availableServices: string[];
  unavailableServices: string[];
  message: string;
  timestamp: string;
  affectedAgents: string[];
}

export interface ServiceDependency {
  service: string;
  requiredFor: string[];
  fallback?: string;
}

// ---------------------------------------------------------------------------
// DEGRADATION LEVELS
// ---------------------------------------------------------------------------

const DEGRADATION_LEVELS: Record<string, DegradationState> = {
  all_healthy: {
    level: 'full',
    availableServices: ['ollama', 'fastapi', 'dashboard', 'agents', 'tools', 'mcp'],
    unavailableServices: [],
    message: 'All services operational',
    timestamp: '',
    affectedAgents: [],
  },
  ollama_down: {
    level: 'partial',
    availableServices: ['fastapi', 'dashboard', 'agents', 'tools', 'file_ops', 'mcp'],
    unavailableServices: ['ollama', 'llm_generation'],
    message: 'LLM service unavailable - basic operations only',
    timestamp: '',
    affectedAgents: ['OrchestratorAgent', 'DeveloperAgent', 'ResearcherAgent'],
  },
  fastapi_down: {
    level: 'partial',
    availableServices: ['ollama', 'dashboard', 'agents', 'tools', 'mcp'],
    unavailableServices: ['fastapi', 'python_execution', 'browser_automation'],
    message: 'Python backend restarting - TypeScript agents available',
    timestamp: '',
    affectedAgents: ['DataScientistAgent', 'RobotkezAgent', 'VoiceAgent'],
  },
  dashboard_down: {
    level: 'partial',
    availableServices: ['ollama', 'fastapi', 'agents', 'tools', 'mcp'],
    unavailableServices: ['dashboard', 'ui'],
    message: 'Dashboard unavailable - CLI and MCP access working',
    timestamp: '',
    affectedAgents: [],
  },
  backend_critical: {
    level: 'minimal',
    availableServices: ['dashboard', 'health_check'],
    unavailableServices: ['ollama', 'fastapi', 'agents', 'tools'],
    message: 'Critical backend failure - monitoring only',
    timestamp: '',
    affectedAgents: ['*'],
  },
  total_failure: {
    level: 'offline',
    availableServices: [],
    unavailableServices: ['*'],
    message: 'System offline - all services down',
    timestamp: '',
    affectedAgents: ['*'],
  },
};

// ---------------------------------------------------------------------------
// SERVICE DEPENDENCIES
// ---------------------------------------------------------------------------

const SERVICE_DEPENDENCIES: ServiceDependency[] = [
  {
    service: 'ollama',
    requiredFor: ['LLM generation', 'Agent planning', 'Code generation'],
  },
  {
    service: 'fastapi',
    requiredFor: ['Python execution', 'Browser automation', 'Data processing'],
  },
  {
    service: 'dashboard',
    requiredFor: ['UI', 'Real-time monitoring'],
  },
];

// ---------------------------------------------------------------------------
// DEGRADATION MANAGER
// ---------------------------------------------------------------------------

class DegradationPolicyManager {
  private currentState: DegradationState = {
    ...DEGRADATION_LEVELS.all_healthy,
    timestamp: new Date().toISOString(),
  };

  /**
   * Assess system degradation level based on failed services.
   */
  assessDegradation(failedServices: string[]): DegradationState {
    const failed = failedServices.map((s) => s.toLowerCase());

    // Determine degradation level
    let newState: DegradationState;

    if (failed.length === 0) {
      newState = { ...DEGRADATION_LEVELS.all_healthy };
    } else if (failed.length >= 3) {
      // 3+ services down = total failure (offline)
      newState = { ...DEGRADATION_LEVELS.total_failure };
    } else if (failed.includes('ollama') && failed.includes('fastapi')) {
      // Both critical backends down = minimal
      newState = { ...DEGRADATION_LEVELS.backend_critical };
    } else if (failed.includes('ollama')) {
      newState = { ...DEGRADATION_LEVELS.ollama_down };
    } else if (failed.includes('fastapi')) {
      newState = { ...DEGRADATION_LEVELS.fastapi_down };
    } else if (failed.includes('dashboard')) {
      newState = { ...DEGRADATION_LEVELS.dashboard_down };
    } else {
      // Unknown failure - partial degradation
      newState = {
        level: 'partial',
        availableServices: ['dashboard', 'health_check'],
        unavailableServices: failed,
        message: `Services down: ${failed.join(', ')}`,
        affectedAgents: [],
        timestamp: new Date().toISOString(),
      };
    }

    // Update timestamp and unavailable list
    newState.timestamp = new Date().toISOString();
    newState.unavailableServices = failed;

    // Update available services list (remove failed services)
    newState.availableServices = newState.availableServices.filter(
      (svc) => !failed.includes(svc.toLowerCase())
    );

    // Log degradation change
    if (newState.level !== this.currentState.level) {
      this.logDegradationChange(this.currentState, newState);
    }

    this.currentState = newState;
    return newState;
  }

  /**
   * Check if a specific service is available in current degradation state.
   */
  isServiceAvailable(serviceName: string): boolean {
    return this.currentState.availableServices.includes(serviceName);
  }

  /**
   * Check if an agent can operate in current degradation state.
   */
  canAgentOperate(agentName: string): boolean {
    const affected = this.currentState.affectedAgents;

    // If all agents affected
    if (affected.includes('*')) {
      return false;
    }

    // Check if this specific agent is affected
    return !affected.some((a) => agentName.includes(a));
  }

  /**
   * Get current degradation state.
   */
  getCurrentState(): DegradationState {
    return { ...this.currentState };
  }

  /**
   * Get user-friendly message for current state.
   */
  getUserMessage(): string {
    const state = this.currentState;

    switch (state.level) {
      case 'full':
        return '🟢 All systems operational';
      case 'partial':
        return `🟡 Partial functionality: ${state.message}`;
      case 'minimal':
        return `🟠 Limited operations: ${state.message}`;
      case 'offline':
        return `🔴 System offline: ${state.message}`;
      default:
        return '⚪ Unknown state';
    }
  }

  /**
   * Get service dependencies for a given service.
   */
  getServiceDependencies(serviceName: string): ServiceDependency | undefined {
    return SERVICE_DEPENDENCIES.find((dep) => dep.service === serviceName);
  }

  /**
   * Log degradation level change.
   */
  private logDegradationChange(
    oldState: DegradationState,
    newState: DegradationState
  ): void {
    const direction = this.getLevelSeverity(newState.level) >
      this.getLevelSeverity(oldState.level)
      ? 'DEGRADED'
      : 'RECOVERED';

    logWarn(
      'DegradationPolicy',
      `${direction}: ${oldState.level} → ${newState.level}`
    );
    logInfo('DegradationPolicy', newState.message);

    // Publish to Phoenix Event Bus
    phoenixEventBus.publish('phoenix:degraded', {
      level: newState.level,
      services: newState.unavailableServices,
      message: newState.message,
      timestamp: newState.timestamp,
    });
  }

  /**
   * Get numeric severity for degradation level (higher = worse).
   */
  private getLevelSeverity(level: DegradationLevel): number {
    const severity: Record<DegradationLevel, number> = {
      full: 0,
      partial: 1,
      minimal: 2,
      offline: 3,
    };
    return severity[level] || 0;
  }

  /**
   * Reset to healthy state (for testing).
   */
  reset(): void {
    this.currentState = {
      ...DEGRADATION_LEVELS.all_healthy,
      timestamp: new Date().toISOString(),
    };
  }
}

// ---------------------------------------------------------------------------
// SINGLETON EXPORT
// ---------------------------------------------------------------------------

export const degradationPolicy = new DegradationPolicyManager();

// ---------------------------------------------------------------------------
// HELPER FUNCTIONS
// ---------------------------------------------------------------------------

/**
 * Quick check if system can handle a specific operation type.
 */
export function canPerformOperation(operationType: string): boolean {
  const state = degradationPolicy.getCurrentState();

  const operationRequirements: Record<string, string[]> = {
    llm_generation: ['ollama'],
    python_execution: ['fastapi'],
    browser_automation: ['fastapi'],
    file_operations: [], // Always available
    health_check: [], // Always available
    agent_delegation: ['ollama', 'fastapi'],
  };

  const required = operationRequirements[operationType] || [];

  // Check if all required services are available
  return required.every((service) => state.availableServices.includes(service));
}

/**
 * Get fallback message for unavailable operation.
 */
export function getFallbackMessage(operationType: string): string {
  const state = degradationPolicy.getCurrentState();

  const fallbacks: Record<string, string> = {
    llm_generation: 'LLM unavailable - please use cached responses or retry later',
    python_execution: 'Python backend unavailable - use TypeScript alternatives',
    browser_automation: 'Browser automation unavailable - manual intervention required',
    agent_delegation: 'Agent system degraded - limited functionality available',
  };

  return (
    fallbacks[operationType] ||
    `Operation unavailable in ${state.level} mode: ${state.message}`
  );
}

// FILE: src/utils/developerMetrics.ts
// PURPOSE: Persistent metrics collection for Developer Agent (P10)
// VERSION: 1.0

import path from 'path';
import fs from 'fs/promises';
import { logError, logInfo } from './logger.js';
import { config } from '../config/index.js';

interface MetricsData {
    builds: {
        total: number;
        success: number;
        fail: number;
        lastStatus: 'success' | 'fail' | 'unknown';
        lastDurationMs: number;
        lastTimestamp?: number;
    };
    tests: {
        totalRuns: number;
        lastPassRate: number; // 0-100
        lastDurationMs: number;
        lastTimestamp?: number;
    };
    tasks: {
        total: number;
        success: number;
        error: number;
        avgDurationMs: number;
    };
    ai: {
        totalTokenUsage: number; // Placeholder for now
        estimatedCost: number;  // Placeholder
    };
    history: Array<{
        type: 'task' | 'build' | 'test';
        status: 'success' | 'fail' | 'error';
        details: string; // Task ID or Build/Test Label
        durationMs: number;
        timestamp: number;
    }>;
}

const DEFAULT_METRICS: MetricsData = {
    builds: { total: 0, success: 0, fail: 0, lastStatus: 'unknown', lastDurationMs: 0 },
    tests: { totalRuns: 0, lastPassRate: 0, lastDurationMs: 0 },
    tasks: { total: 0, success: 0, error: 0, avgDurationMs: 0 },
    ai: { totalTokenUsage: 0, estimatedCost: 0 },
    history: []
};

class DeveloperMetrics {
    private dataFile: string;
    private data: MetricsData;
    private loaded = false;

    constructor() {
        this.dataFile = path.join(process.cwd(), 'data', 'developer_metrics.json');
        this.data = JSON.parse(JSON.stringify(DEFAULT_METRICS));
    }

    private async ensureLoaded() {
        if (this.loaded) return;
        
        try {
            await fs.mkdir(path.dirname(this.dataFile), { recursive: true });
            try {
                const content = await fs.readFile(this.dataFile, 'utf-8');
                this.data = JSON.parse(content);
                // Merge with default to ensure new fields exists
                this.data = { ...DEFAULT_METRICS, ...this.data };
            } catch (error: any) {
                if (error.code !== 'ENOENT') {
                    logError('DeveloperMetrics', `Failed to load metrics: ${error.message}`);
                }
                // Use default if file doesn't exist
            }
        } catch (error: any) {
            logError('DeveloperMetrics', `Failed to init metrics dir: ${error.message}`);
        }
        this.loaded = true;
    }

    private async save() {
        try {
            // Keep history limited to 100 items
            if (this.data.history.length > 100) {
                this.data.history = this.data.history.slice(0, 100);
            }
            await fs.writeFile(this.dataFile, JSON.stringify(this.data, null, 2), 'utf-8');
        } catch (error: any) {
            logError('DeveloperMetrics', `Failed to save metrics: ${error.message}`);
        }
    }

    async recordTask(taskId: string, success: boolean, durationMs: number) {
        await this.ensureLoaded();
        this.data.tasks.total++;
        if (success) {
            this.data.tasks.success++;
        } else {
            this.data.tasks.error++;
        }

        // Rolling average for duration
        const oldAvg = this.data.tasks.avgDurationMs;
        const count = this.data.tasks.total;
        this.data.tasks.avgDurationMs = Math.round(((oldAvg * (count - 1)) + durationMs) / count);

        this.data.history.unshift({
            type: 'task',
            status: success ? 'success' : 'error',
            details: taskId,
            durationMs,
            timestamp: Date.now()
        });

        await this.save();
    }

    async recordBuild(success: boolean, durationMs: number) {
        await this.ensureLoaded();
        this.data.builds.total++;
        if (success) {
            this.data.builds.success++;
            this.data.builds.lastStatus = 'success';
        } else {
            this.data.builds.fail++;
            this.data.builds.lastStatus = 'fail';
        }
        this.data.builds.lastDurationMs = durationMs;
        this.data.builds.lastTimestamp = Date.now();

        this.data.history.unshift({
            type: 'build',
            status: success ? 'success' : 'fail',
            details: 'build',
            durationMs,
            timestamp: Date.now()
        });

        await this.save();
    }

    async recordTest(passRate: number, durationMs: number) {
        await this.ensureLoaded();
        this.data.tests.totalRuns++;
        this.data.tests.lastPassRate = passRate;
        this.data.tests.lastDurationMs = durationMs;
        this.data.tests.lastTimestamp = Date.now();

        this.data.history.unshift({
            type: 'test',
            status: passRate === 100 ? 'success' : 'fail',
            details: `Rate: ${passRate}%`,
            durationMs,
            timestamp: Date.now()
        });

        await this.save();
    }

    async getMetrics(): Promise<MetricsData> {
        await this.ensureLoaded();
        return this.data;
    }
}

export const developerMetrics = new DeveloperMetrics();

import fs from "fs";
import path from "path";
import { logInfo, logError } from "./logger.js";

const FIX_QUEUE_FILE = path.join(process.cwd(), "data", "fix_queue.json");

export interface FixItem {
  id: string;
  source: string; // Who reported it (e.g., 'User', 'HealthCheck')
  description: string; // What is broken
  priority: "critical" | "high" | "normal";
  status: "pending" | "in-progress" | "resolved" | "failed";
  createdAt: string;
  attempts: number;
  lastError?: string;
}

/**
 * Ensures the fix queue file exists.
 */
function ensureQueueFile() {
  const dir = path.dirname(FIX_QUEUE_FILE);
  if (!fs.existsSync(dir)) {
    fs.mkdirSync(dir, { recursive: true });
  }
  if (!fs.existsSync(FIX_QUEUE_FILE)) {
    fs.writeFileSync(FIX_QUEUE_FILE, JSON.stringify([], null, 2), "utf-8");
  }
}

/**
 * Adds a new item to the Fix Queue.
 */
export function addToFixQueue(
  description: string,
  source: string = "System",
  priority: FixItem["priority"] = "normal",
): string {
  ensureQueueFile();
  try {
    const queue: FixItem[] = JSON.parse(
      fs.readFileSync(FIX_QUEUE_FILE, "utf-8"),
    );
    const id = `fix-${Date.now()}-${Math.random().toString(36).substr(2, 5)}`;

    // Avoid duplicates (simple check based on description)
    if (
      queue.some(
        (i) => i.description === description && i.status !== "resolved",
      )
    ) {
      return "duplicate";
    }

    const newItem: FixItem = {
      id,
      source,
      description,
      priority,
      status: "pending",
      createdAt: new Date().toISOString(),
      attempts: 0,
    };

    queue.push(newItem);
    fs.writeFileSync(FIX_QUEUE_FILE, JSON.stringify(queue, null, 2), "utf-8");
    logInfo("FixQueue", `New issue added: ${description} [${id}]`);
    return id;
  } catch (e) {
    logError("FixQueue", `Failed to add item: ${(e as Error).message}`);
    return "error";
  }
}

/**
 * Gets all pending items sorted by priority.
 */
export function getPendingFixes(): FixItem[] {
  ensureQueueFile();
  try {
    const queue: FixItem[] = JSON.parse(
      fs.readFileSync(FIX_QUEUE_FILE, "utf-8"),
    );
    return queue
      .filter((i) => i.status === "pending" || i.status === "in-progress")
      .sort((a, b) => {
        const pMap = { critical: 3, high: 2, normal: 1 };
        return pMap[b.priority] - pMap[a.priority];
      });
  } catch (e) {
    return [];
  }
}

/**
 * Updates the status of a fix item.
 */
export function updateFixStatus(
  id: string,
  status: FixItem["status"],
  lastError?: string,
) {
  ensureQueueFile();
  try {
    const queue: FixItem[] = JSON.parse(
      fs.readFileSync(FIX_QUEUE_FILE, "utf-8"),
    );
    const idx = queue.findIndex((i) => i.id === id);
    if (idx !== -1) {
      queue[idx].status = status;
      if (lastError) queue[idx].lastError = lastError;
      if (status === "in-progress" || status === "failed")
        queue[idx].attempts++;

      fs.writeFileSync(FIX_QUEUE_FILE, JSON.stringify(queue, null, 2), "utf-8");
    }
  } catch (e) {
    logError("FixQueue", `Update failed: ${(e as Error).message}`);
  }
}

/**
 * fsInspector.ts - File System Anomaly Detection
 *
 * Part of ProjectConductor 2.0 "Chief-of-Staff" upgrade.
 * Detects file anomalies, outdated documentation, and structural issues.
 *
 * @module utils/fsInspector
 */

import fs from 'fs/promises';
import path from 'path';
import { config } from '../config/index.js';
import { logInfo, logError } from './logger.js';

const SOURCE = 'fsInspector';

// ============================================================================
// Types
// ============================================================================

export interface FileInfo {
    path: string;
    name: string;
    size: number;
    mtime: Date;
    isDirectory: boolean;
}

export interface Anomaly {
    type: AnomalyType;
    severity: 'low' | 'medium' | 'high' | 'critical';
    path: string;
    message: string;
    suggestion?: string;
    detectedAt: Date;
}

export type AnomalyType =
    | 'orphaned_file'      // File not referenced anywhere
    | 'duplicate_file'     // Same content, different name
    | 'large_file'         // Unusually large file
    | 'stale_doc'          // Documentation older than code
    | 'empty_dir'          // Empty directory
    | 'temp_file'          // Leftover temp files
    | 'naming_violation'   // Naming convention violation
    | 'missing_index'      // Directory without index file
    | 'circular_ref'       // Circular reference detected
    | 'outdated_track';    // Track older than 30 days without update

export interface ScanOptions {
    rootDir?: string;
    includePatterns?: string[];
    excludePatterns?: string[];
    maxDepth?: number;
    checkDocs?: boolean;
    checkTracks?: boolean;
    checkOrphans?: boolean;
    checkDuplicates?: boolean;
    checkLargeFiles?: boolean;
    largeFileSizeThreshold?: number; // bytes
    staleDocThresholdDays?: number;
}

export interface ScanResult {
    scannedAt: Date;
    rootDir: string;
    totalFiles: number;
    totalDirs: number;
    anomalies: Anomaly[];
    summary: {
        critical: number;
        high: number;
        medium: number;
        low: number;
    };
}

// ============================================================================
// Default Configuration
// ============================================================================

const DEFAULT_EXCLUDE_PATTERNS = [
    'node_modules',
    '.git',
    'build',
    'dist',
    '.venv',
    '__pycache__',
    '.pytest_cache',
    '.mypy_cache',
    'coverage',
    '.next',
    '.turbo'
];

const DEFAULT_TEMP_PATTERNS = [
    /\.tmp$/,
    /\.bak$/,
    /\.swp$/,
    /~$/,
    /\.orig$/,
    /\.DS_Store$/,
    /Thumbs\.db$/,
    /\.log\.old$/
];

const LARGE_FILE_THRESHOLD = 10 * 1024 * 1024; // 10MB
const STALE_DOC_THRESHOLD_DAYS = 30;

// ============================================================================
// Core Functions
// ============================================================================

/**
 * Recursively scan directory and collect file info
 */
async function scanDirectory(
    dir: string,
    options: ScanOptions,
    depth: number = 0
): Promise<FileInfo[]> {
    const results: FileInfo[] = [];

    if (options.maxDepth !== undefined && depth > options.maxDepth) {
        return results;
    }

    try {
        const entries = await fs.readdir(dir, { withFileTypes: true });

        for (const entry of entries) {
            const fullPath = path.join(dir, entry.name);
            const relativePath = path.relative(options.rootDir || config.workspaceRoot, fullPath);

            // Check exclude patterns
            const shouldExclude = (options.excludePatterns || DEFAULT_EXCLUDE_PATTERNS)
                .some(pattern => relativePath.includes(pattern) || entry.name === pattern);

            if (shouldExclude) continue;

            try {
                const stat = await fs.stat(fullPath);

                results.push({
                    path: fullPath,
                    name: entry.name,
                    size: stat.size,
                    mtime: stat.mtime,
                    isDirectory: entry.isDirectory()
                });

                if (entry.isDirectory()) {
                    const subResults = await scanDirectory(fullPath, options, depth + 1);
                    results.push(...subResults);
                }
            } catch {
                // Skip files we can't stat (permission issues, etc.)
            }
        }
    } catch (error) {
        logError(SOURCE, `Failed to scan directory: ${dir}`);
    }

    return results;
}

/**
 * Detect orphaned files (files not imported/referenced anywhere)
 */
async function detectOrphanedFiles(files: FileInfo[]): Promise<Anomaly[]> {
    const anomalies: Anomaly[] = [];
    const tsFiles = files.filter(f => /\.(ts|tsx|js|jsx)$/.test(f.name) && !f.isDirectory);

    // Collect all imports
    const importedFiles = new Set<string>();

    for (const file of tsFiles) {
        try {
            const content = await fs.readFile(file.path, 'utf-8');
            const importMatches = content.matchAll(/from\s+['"]([^'"]+)['"]/g);

            for (const match of importMatches) {
                const importPath = match[1];
                if (importPath.startsWith('.')) {
                    const resolvedPath = path.resolve(path.dirname(file.path), importPath);
                    importedFiles.add(resolvedPath);
                    importedFiles.add(resolvedPath + '.ts');
                    importedFiles.add(resolvedPath + '.tsx');
                    importedFiles.add(resolvedPath + '.js');
                    importedFiles.add(resolvedPath + '/index.ts');
                    importedFiles.add(resolvedPath + '/index.js');
                }
            }
        } catch {
            // Skip unreadable files
        }
    }

    // Check which files are not imported
    for (const file of tsFiles) {
        if (!file.name.includes('.test.') &&
            !file.name.includes('.spec.') &&
            !file.name.includes('index.') &&
            !file.name.endsWith('.d.ts') &&
            !importedFiles.has(file.path) &&
            !importedFiles.has(file.path.replace(/\.(ts|tsx)$/, ''))) {

            // Additional check: is it an entry point or agent?
            if (!file.path.includes('agents') &&
                !file.path.includes('cli.ts') &&
                !file.path.includes('index.ts')) {
                anomalies.push({
                    type: 'orphaned_file',
                    severity: 'low',
                    path: file.path,
                    message: `File "${file.name}" is not imported by any other file`,
                    suggestion: 'Consider removing if unused, or add to exports',
                    detectedAt: new Date()
                });
            }
        }
    }

    return anomalies;
}

/**
 * Detect large files that may need attention
 */
function detectLargeFiles(files: FileInfo[], threshold: number): Anomaly[] {
    return files
        .filter(f => !f.isDirectory && f.size > threshold)
        .map(f => ({
            type: 'large_file' as AnomalyType,
            severity: f.size > threshold * 10 ? 'high' as const : 'medium' as const,
            path: f.path,
            message: `File size ${(f.size / 1024 / 1024).toFixed(2)}MB exceeds threshold`,
            suggestion: 'Consider compression, splitting, or moving to external storage',
            detectedAt: new Date()
        }));
}

/**
 * Detect temp/backup files that should be cleaned up
 */
function detectTempFiles(files: FileInfo[]): Anomaly[] {
    return files
        .filter(f => !f.isDirectory && DEFAULT_TEMP_PATTERNS.some(p => p.test(f.name)))
        .map(f => ({
            type: 'temp_file' as AnomalyType,
            severity: 'low' as const,
            path: f.path,
            message: `Temporary/backup file found: ${f.name}`,
            suggestion: 'Clean up temp files before commit',
            detectedAt: new Date()
        }));
}

/**
 * Detect empty directories
 */
async function detectEmptyDirs(files: FileInfo[]): Promise<Anomaly[]> {
    const anomalies: Anomaly[] = [];
    const dirs = files.filter(f => f.isDirectory);

    for (const dir of dirs) {
        try {
            const entries = await fs.readdir(dir.path);
            if (entries.length === 0) {
                anomalies.push({
                    type: 'empty_dir',
                    severity: 'low',
                    path: dir.path,
                    message: `Empty directory: ${dir.name}`,
                    suggestion: 'Remove empty directory or add .gitkeep',
                    detectedAt: new Date()
                });
            }
        } catch {
            // Skip unreadable directories
        }
    }

    return anomalies;
}

/**
 * Detect stale documentation (docs older than related code)
 */
async function detectStaleDocs(
    files: FileInfo[],
    thresholdDays: number
): Promise<Anomaly[]> {
    const anomalies: Anomaly[] = [];
    const now = new Date();
    const thresholdMs = thresholdDays * 24 * 60 * 60 * 1000;

    const docFiles = files.filter(f =>
        !f.isDirectory &&
        (/\.md$/i.test(f.name) || /\.txt$/i.test(f.name)) &&
        !f.path.includes('node_modules')
    );

    for (const doc of docFiles) {
        const age = now.getTime() - doc.mtime.getTime();

        if (age > thresholdMs) {
            // Check if there's related code that's newer
            const docDir = path.dirname(doc.path);
            const relatedCode = files.filter(f =>
                !f.isDirectory &&
                f.path.startsWith(docDir) &&
                /\.(ts|tsx|js|jsx|py)$/.test(f.name)
            );

            const newerCode = relatedCode.filter(c => c.mtime > doc.mtime);

            if (newerCode.length > 0) {
                anomalies.push({
                    type: 'stale_doc',
                    severity: age > thresholdMs * 2 ? 'high' : 'medium',
                    path: doc.path,
                    message: `Documentation "${doc.name}" is ${Math.floor(age / 86400000)} days old, but related code was updated`,
                    suggestion: 'Review and update documentation to match current code',
                    detectedAt: new Date()
                });
            }
        }
    }

    return anomalies;
}

/**
 * Detect outdated conductor tracks
 */
async function detectOutdatedTracks(
    tracksDir: string,
    thresholdDays: number = 30
): Promise<Anomaly[]> {
    const anomalies: Anomaly[] = [];
    const now = new Date();
    const thresholdMs = thresholdDays * 24 * 60 * 60 * 1000;

    try {
        const trackDirs = await fs.readdir(tracksDir, { withFileTypes: true });

        for (const trackDir of trackDirs) {
            if (!trackDir.isDirectory()) continue;

            const trackPath = path.join(tracksDir, trackDir.name);
            const specPath = path.join(trackPath, 'spec.md');
            const planPath = path.join(trackPath, 'plan.md');

            try {
                // Check spec.md mtime
                const specStat = await fs.stat(specPath);
                const age = now.getTime() - specStat.mtime.getTime();

                if (age > thresholdMs) {
                    // Read spec to check status
                    const specContent = await fs.readFile(specPath, 'utf-8');
                    const isCompleted = /status:\s*(completed|done|closed)/i.test(specContent);

                    if (!isCompleted) {
                        anomalies.push({
                            type: 'outdated_track',
                            severity: age > thresholdMs * 2 ? 'high' : 'medium',
                            path: trackPath,
                            message: `Track "${trackDir.name}" has not been updated for ${Math.floor(age / 86400000)} days`,
                            suggestion: 'Update track status or archive if completed',
                            detectedAt: new Date()
                        });
                    }
                }
            } catch {
                // No spec.md - might be missing
            }
        }
    } catch {
        logError(SOURCE, `Failed to scan tracks directory: ${tracksDir}`);
    }

    return anomalies;
}

// ============================================================================
// Main API
// ============================================================================

/**
 * Run full file system anomaly scan
 */
export async function scanForAnomalies(options: ScanOptions = {}): Promise<ScanResult> {
    const rootDir = options.rootDir || config.workspaceRoot;
    logInfo(SOURCE, `Starting anomaly scan in: ${rootDir}`);

    const startTime = Date.now();

    // Scan all files
    const files = await scanDirectory(rootDir, {
        ...options,
        rootDir,
        excludePatterns: options.excludePatterns || DEFAULT_EXCLUDE_PATTERNS
    });

    const totalFiles = files.filter(f => !f.isDirectory).length;
    const totalDirs = files.filter(f => f.isDirectory).length;

    // Collect anomalies
    const anomalies: Anomaly[] = [];

    // Always check temp files
    anomalies.push(...detectTempFiles(files));

    // Conditional checks
    if (options.checkLargeFiles !== false) {
        anomalies.push(...detectLargeFiles(
            files,
            options.largeFileSizeThreshold || LARGE_FILE_THRESHOLD
        ));
    }

    if (options.checkOrphans !== false) {
        anomalies.push(...await detectOrphanedFiles(files));
    }

    if (options.checkDocs !== false) {
        anomalies.push(...await detectStaleDocs(
            files,
            options.staleDocThresholdDays || STALE_DOC_THRESHOLD_DAYS
        ));
    }

    // Check empty directories
    anomalies.push(...await detectEmptyDirs(files));

    // Check conductor tracks
    if (options.checkTracks !== false) {
        const tracksDir = path.join(rootDir, 'conductor', 'tracks');
        anomalies.push(...await detectOutdatedTracks(tracksDir));
    }

    // Count by severity
    const summary = {
        critical: anomalies.filter(a => a.severity === 'critical').length,
        high: anomalies.filter(a => a.severity === 'high').length,
        medium: anomalies.filter(a => a.severity === 'medium').length,
        low: anomalies.filter(a => a.severity === 'low').length
    };

    const duration = Date.now() - startTime;
    logInfo(SOURCE, `Scan completed in ${duration}ms. Found ${anomalies.length} anomalies.`);

    return {
        scannedAt: new Date(),
        rootDir,
        totalFiles,
        totalDirs,
        anomalies,
        summary
    };
}

/**
 * Quick check for critical issues only
 */
export async function quickHealthCheck(): Promise<{
    healthy: boolean;
    criticalIssues: Anomaly[];
}> {
    const result = await scanForAnomalies({
        maxDepth: 3,
        checkOrphans: false,
        checkDocs: false,
        checkDuplicates: false
    });

    const criticalIssues = result.anomalies.filter(a =>
        a.severity === 'critical' || a.severity === 'high'
    );

    return {
        healthy: criticalIssues.length === 0,
        criticalIssues
    };
}

/**
 * Generate markdown report from scan results
 */
export function generateReport(result: ScanResult): string {
    const lines: string[] = [
        '# File System Anomaly Report',
        '',
        `**Scanned:** ${result.scannedAt.toISOString()}`,
        `**Root:** ${result.rootDir}`,
        `**Files:** ${result.totalFiles} | **Directories:** ${result.totalDirs}`,
        '',
        '## Summary',
        '',
        `| Severity | Count |`,
        `|----------|-------|`,
        `| Critical | ${result.summary.critical} |`,
        `| High | ${result.summary.high} |`,
        `| Medium | ${result.summary.medium} |`,
        `| Low | ${result.summary.low} |`,
        '',
    ];

    if (result.anomalies.length === 0) {
        lines.push('No anomalies detected.');
    } else {
        lines.push('## Anomalies', '');

        // Group by type
        const byType = new Map<AnomalyType, Anomaly[]>();
        for (const anomaly of result.anomalies) {
            const list = byType.get(anomaly.type) || [];
            list.push(anomaly);
            byType.set(anomaly.type, list);
        }

        for (const [type, anomalies] of byType) {
            lines.push(`### ${type.replace(/_/g, ' ').toUpperCase()} (${anomalies.length})`, '');

            for (const a of anomalies) {
                const severityIcon = {
                    critical: '🔴',
                    high: '🟠',
                    medium: '🟡',
                    low: '🟢'
                }[a.severity];

                lines.push(`${severityIcon} **${a.message}**`);
                lines.push(`  - Path: \`${path.relative(result.rootDir, a.path)}\``);
                if (a.suggestion) {
                    lines.push(`  - Suggestion: ${a.suggestion}`);
                }
                lines.push('');
            }
        }
    }

    return lines.join('\n');
}

