/**
 * Generate Execution Plan from magyar instruction
 *
 * @param instruction - Magyar nyelvű utasítás (pl. "Keress rá az AI hírekre")
 * @param options - Contextual options (history, browser state)
 * @returns ExecutionPlan - Multi-step browser automation plan
 * @throws Error if LLM response is invalid or cannot be parsed
 */
export async function generateExecutionPlan(
    instruction: string, 
    options?: { 
        history?: Array<{ role: string, content: string }>,
        browserState?: { url: string, title?: string }
    }
): Promise<ExecutionPlan> {
    logInfo('LLMPlanner', `Generating plan for: "${instruction}"`);

    let contextPrompt = '';
    if (options?.browserState) {
        contextPrompt += `\nJELENLEGI BÖNGÉSZŐ ÁLLAPOT:\n- URL: ${options.browserState.url}\n- Cím: ${options.browserState.title || 'N/A'}\n`;
    }

    if (options?.history && options.history.length > 0) {
        contextPrompt += `\nKORÁBBI BESZÉLGETÉS:\n${options.history.map(h => `${h.role}: ${h.content}`).join('\n')}\n`;
    }

    const userPrompt = `${contextPrompt}\nÚJ UTASÍTÁS: ${instruction}

Készíts részletes execution plan-t a fenti utasítás végrehajtásához, figyelembe véve a kontextust.`;

    try {
        // Call LLM (using Model Router to pick brain model, or env var override)
        const fullPrompt = `${SYSTEM_PROMPT}\n\n${userPrompt}`;
        let response: string;

        if (PLANNER_LLM_OVERRIDE === 'cloudflare') {
            logInfo('LLMPlanner', `CF AI override aktív (ROBOTKEZ_LLM_PROVIDER=cloudflare), modell: ${CF_PLANNER_MODEL}`);
            response = await generateResponse(fullPrompt, 'cloudflare', CF_PLANNER_MODEL);
        } else if (PLANNER_LLM_OVERRIDE) {
            logInfo('LLMPlanner', `LLM override aktív: ${PLANNER_LLM_OVERRIDE}`);
            response = await generateResponse(fullPrompt, PLANNER_LLM_OVERRIDE);
        } else {
            const routed = await generateRouted(fullPrompt, instruction, { category: 'planning' });
            response = routed.response;
        }

        logInfo('LLMPlanner', `Raw LLM response: ${response.slice(0, 200)}...`);

        // Clean up response: extract JSON between first { and last }
        const firstBrace = response.indexOf('{');
        const lastBrace = response.lastIndexOf('}');

        if (firstBrace === -1 || lastBrace === -1 || firstBrace >= lastBrace) {
            throw new Error('No valid JSON object found in LLM response');
        }

        const cleaned = response.slice(firstBrace, lastBrace + 1);

        // Parse JSON
        let plan: ExecutionPlan;
        try {
            plan = JSON.parse(cleaned) as ExecutionPlan;
        } catch (parseError: unknown) {
            const msg = parseError instanceof Error ? parseError.message : String(parseError);
            logError('LLMPlanner', `JSON parse error: ${msg}`);
            logError('LLMPlanner', `Attempted to parse: ${cleaned.slice(0, 500)}`);
            throw new Error(`Invalid JSON from LLM: ${msg}`);
        }

        // Validation
        if (!plan.plan || !Array.isArray(plan.plan)) {
            throw new Error('Invalid plan structure: missing or non-array "plan" field');
        }

        if (plan.plan.length === 0) {
            throw new Error('Invalid plan: empty plan array');
        }

        // Validate each step has required fields
        for (let i = 0; i < plan.plan.length; i++) {
            const step = plan.plan[i];
            if (!step.action) {
                throw new Error(`Invalid step ${i}: missing action`);
            }
            if (!step.description) {
                logWarn('LLMPlanner', `Step ${i} missing description, adding default`);
                step.description = `Lépés ${i + 1}: ${step.action}`;
            }
        }

        // Set defaults
        if (typeof plan.estimatedDuration !== 'number') {
            plan.estimatedDuration = plan.plan.length * 3000; // 3s/step default
            logWarn('LLMPlanner', `Missing estimatedDuration, defaulting to ${plan.estimatedDuration}ms`);
        }

        if (typeof plan.backgroundEligible !== 'boolean') {
            plan.backgroundEligible = plan.estimatedDuration > 30000;
        }

        // POST-PROCESSING: Override short wait timeouts (LLM often generates too short timeouts)
        for (const step of plan.plan) {
            if (step.action === 'wait') {
                if (!step.timeout || step.timeout < 10000) {
                    const oldTimeout = step.timeout || 0;
                    step.timeout = 10000; // Force 10s minimum for wait actions
                    logWarn('LLMPlanner', `⚠️ Overriding wait timeout ${oldTimeout}ms → 10000ms for selector: ${step.selector}`);
                }
            }
        }

        logInfo('LLMPlanner', `✅ Plan generated: ${plan.plan.length} steps, ${plan.estimatedDuration}ms`);

        return plan;

    } catch (error: unknown) {
        const msg = error instanceof Error ? error.message : String(error);
        logError('LLMPlanner', `Failed to generate plan: ${msg}`);
        throw error;
    }
}

/**
 * Validate Execution Plan structure
 * (Additional runtime validation beyond LLM generation)
 *
 * @param plan - ExecutionPlan to validate
 * @returns boolean - true if valid
 * @throws Error with detailed message if invalid
 */
export function validateExecutionPlan(plan: ExecutionPlan): boolean {
    if (!plan.plan || !Array.isArray(plan.plan)) {
        throw new Error('Invalid plan: missing or non-array "plan" field');
    }

    const validActions = ['navigate', 'click', 'type', 'scroll', 'wait', 'screenshot', 'extract'];

    for (let i = 0; i < plan.plan.length; i++) {
        const step = plan.plan[i];

        // Validate action
        if (!validActions.includes(step.action)) {
            throw new Error(`Invalid step ${i}: unknown action "${step.action}"`);
        }

        // Validate required fields per action type
        switch (step.action) {
            case 'navigate':
                if (!step.url) {
                    throw new Error(`Invalid step ${i}: navigate requires "url"`);
                }
                break;
            case 'click':
            case 'wait':
                if (!step.selector) {
                    throw new Error(`Invalid step ${i}: ${step.action} requires "selector"`);
                }
                break;
            case 'type':
                if (!step.selector || step.text === undefined) {
                    throw new Error(`Invalid step ${i}: type requires "selector" and "text"`);
                }
                break;
            case 'extract':
                if (!step.selector) {
                    throw new Error(`Invalid step ${i}: extract requires "selector"`);
                }
                break;
            // scroll and screenshot have no required fields
        }
    }

    return true;
}

// src/utils/logger.ts

import { EventEmitter } from 'events';

const LOG_LEVELS = {
  error: 0,
  warn: 1,
  info: 2,
  debug: 3,
};

// In a real app, this would come from env vars
const CURRENT_LOG_LEVEL = 'debug';

function getTimestamp(): string {
  return new Date().toISOString();
}

export type LogLevel = 'error' | 'warn' | 'info' | 'debug' | string;
export type LogEvent = Record<string, any>;
export type AgentStatusEvent = Record<string, any>;

export const logEmitter = new EventEmitter();

function emitLog(level: LogLevel, message: string, details?: any) {
  const event: LogEvent = { timestamp: getTimestamp(), level, message, details };
  try {
    logEmitter.emit('log', event);
  } catch (e) {
    // best effort
  }
}

export function logError(message: string, ...args: any[]) {
  if (LOG_LEVELS.error <= LOG_LEVELS[CURRENT_LOG_LEVEL]) {
    console.error(`[${getTimestamp()}] [ERROR]`, message, ...args);
    emitLog('error', String(message), args.length ? args : undefined);
  }
}

export function logWarn(message: string, ...args: any[]) {
  if (LOG_LEVELS.warn <= LOG_LEVELS[CURRENT_LOG_LEVEL]) {
    console.warn(`[${getTimestamp()}] [WARN]`, message, ...args);
    emitLog('warn', String(message), args.length ? args : undefined);
  }
}

export function logInfo(message: string, ...args: any[]) {
  if (LOG_LEVELS.info <= LOG_LEVELS[CURRENT_LOG_LEVEL]) {
    console.log(`[${getTimestamp()}] [INFO]`, message, ...args);
    emitLog('info', String(message), args.length ? args : undefined);
  }
}

export function logDebug(message: string, ...args: any[]) {
  if (LOG_LEVELS.debug <= LOG_LEVELS[CURRENT_LOG_LEVEL]) {
    console.debug(`[${getTimestamp()}] [DEBUG]`, message, ...args);
    emitLog('debug', String(message), args.length ? args : undefined);
  }
}

export function setAgentStatus(agentName: string, status: string, message?: string) {
  const ev: AgentStatusEvent = { agentName, status, message, timestamp: getTimestamp() };
  try {
    logEmitter.emit('agentStatus', ev);
  } catch (e) {
    // ignore
  }
  logInfo(`[AgentStatus] ${agentName} -> ${status} ${message ?? ''}`);
}

export class Logger {
  prefix: string;
  constructor(prefix = '') {
    this.prefix = prefix;
  }
  info(msg: string, ...args: any[]) { logInfo(`${this.prefix} ${msg}`, ...args); }
  warn(msg: string, ...args: any[]) { logWarn(`${this.prefix} ${msg}`, ...args); }
  error(msg: string, ...args: any[]) { logError(`${this.prefix} ${msg}`, ...args); }
  debug(msg: string, ...args: any[]) { logDebug(`${this.prefix} ${msg}`, ...args); }
  async log(msg: string, meta?: any) { logInfo(`${this.prefix} ${msg}`, meta); return Promise.resolve(); }
  structured(level: LogLevel, msg: string, meta?: any) { emitLog(level, `${this.prefix} ${msg}`, meta); }
}

export const cliLogger = {
  info: async (m: string, ...a: any[]) => { logInfo(m, ...a); return Promise.resolve(); },
  warn: async (m: string, ...a: any[]) => { logWarn(m, ...a); return Promise.resolve(); },
  error: async (m: string, ...a: any[]) => { logError(m, ...a); return Promise.resolve(); },
  debug: async (m: string, ...a: any[]) => { logDebug(m, ...a); return Promise.resolve(); },
  log: async (m: string, meta?: any) => { logInfo(m, meta); return Promise.resolve(); },
  structured: async (level: LogLevel, m: string, meta?: any) => { emitLog(level, m, meta); return Promise.resolve(); }
};

import { Client } from "@modelcontextprotocol/sdk/client/index.js";
import { StdioClientTransport } from "@modelcontextprotocol/sdk/client/stdio.js";
import path from "path";
import fs from "fs";
import { fileURLToPath } from "url";
import { logError, logInfo } from "./logger.js";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

interface McpServerConfig {
  name: string;
  command: string;
  args: string[];
  env?: Record<string, string>;
  disabled?: boolean;
}

interface ConnectOptions {
  coreOnly?: boolean;
  timeoutMs?: number;
}

export class BrunellaClient {
  private clients: Map<string, Client> = new Map();
  private transports: Map<string, any> = new Map();
  private toolCache: Map<string, string> = new Map(); // tool name -> server name

  async connect(options: ConnectOptions = {}) {
    if (process.env.BRUNELLA_MCP_DISABLED === '1') {
      throw new Error('MCP connections disabled (BRUNELLA_MCP_DISABLED=1)');
    }
    // Load config from mcp_servers.json
    const configPath = path.resolve(process.cwd(), "mcp_servers.json");
    if (!fs.existsSync(configPath)) {
      throw new Error(`MCP config not found at ${configPath}`);
    }

    const allServers: McpServerConfig[] = JSON.parse(
      fs.readFileSync(configPath, "utf-8"),
    );

    const servers = options.coreOnly
      ? allServers.filter((server) => server.name === "brunella-core")
      : allServers;

    const defaultTimeout = Number(process.env.BRUNELLA_MCP_CONNECT_TIMEOUT_MS || "8000");
    const timeoutMs = options.timeoutMs ?? defaultTimeout;

    const activeServers = servers.filter((s) => !s.disabled);
    for (const s of servers.filter((s) => s.disabled)) {
      logInfo("MCP", `Skipping disabled server: ${s.name}`);
    }

    const connectOne = async (server: McpServerConfig): Promise<void> => {
      let transport: StdioClientTransport | undefined;
      try {
        const command = server.command;
        const args = [...server.args];

        if (server.name === "brunella-core" && args[0] === "./build/index.js") {
          args[0] = path.resolve(process.cwd(), "build", "index.js");
        }

        const resolvedEnv: Record<string, string> = {};
        if (server.env) {
          for (const [key, val] of Object.entries(server.env)) {
            resolvedEnv[key] = val === "xxxxx" ? (process.env[key] ?? "") : val;
          }
        }

        transport = new StdioClientTransport({
          command,
          args,
          env: {
            ...process.env,
            ...resolvedEnv,
            WEB_UI_ENABLED: "false",
            BRUNELLA_QUIET_LOGS: "true",
          },
        });

        const client = new Client(
          { name: `brunella-cli-${server.name}`, version: "1.0.0" },
          { capabilities: {} },
        );

        await Promise.race([
          client.connect(transport),
          new Promise<never>((_, reject) => {
            setTimeout(() => {
              reject(new Error(`Connect timeout (${timeoutMs}ms)`));
            }, timeoutMs);
          }),
        ]);
        this.clients.set(server.name, client);
        this.transports.set(server.name, transport);
      } catch (e: any) {
        if (transport && transport.close) {
          try { await transport.close(); } catch { /* best effort */ }
        }
        logError("MCP", `Failed to connect to ${server.name}: ${e.message}`);
      }
    };

    await Promise.allSettled(activeServers.map(connectOne));
  }

  async listTools() {
    const allTools: any[] = [];
    for (const [name, client] of this.clients) {
      const result = await client.listTools();
      // Cache tool -> server mapping
      for (const tool of result.tools) {
        this.toolCache.set(tool.name, name);
      }
      allTools.push(...result.tools);
    }
    return { tools: allTools };
  }

  async callTool(name: string, args: any) {
    // Try cache first
    if (this.toolCache.has(name)) {
      const serverName = this.toolCache.get(name)!;
      const client = this.clients.get(serverName);
      if (client) {
        try {
          return await client.callTool({ name, arguments: args });
        } catch (error: any) {
          // If cached lookup fails, fall through to full search
          logError(
            "MCP",
            `Tool '${name}' failed on cached server '${serverName}', retrying...`,
          );
          this.toolCache.delete(name);
        }
      }
    }

    // Fallback: Search for which client has this tool
    for (const [serverName, client] of this.clients) {
      const result = await client.listTools();
      const tool = result.tools.find((t) => t.name === name);
      if (tool) {
        this.toolCache.set(name, serverName); // Update cache
        return client.callTool({ name, arguments: args });
      }
    }
    throw new Error(`Tool '${name}' not found on any connected MCP server.`);
  }

  async close() {
    for (const [name, transport] of this.transports) {
      if (transport && transport.close) {
        await transport.close();
      }
    }
  }
}

import type { ChildProcess } from 'child_process';
import { logInfo, logError } from './logger.js';
import { exec } from 'child_process';

export interface BrowserCommand {
    action: 'launch' | 'navigate' | 'click' | 'type' | 'screenshot' | 'content' | 'scroll' | 'wait' | 'extract' | 'close' | 'press' | 'state' | 'query';
    url?: string;
    selector?: string;
    description?: string;
    text?: string;
    key?: string; // NEW: for press action
    headless?: boolean;
    // NEW: scroll parameters
    direction?: 'up' | 'down' | 'left' | 'right';
    amount?: number;
    // NEW: wait parameters
    timeout?: number;
    // NEW: extract parameters
    type?: 'text' | 'attribute' | 'html';
    attribute?: string;
}

export interface BrowserResponse {
    status: 'success' | 'error';
    message?: string;
    url?: string;
    title?: string; // NEW: for state results
    screenshot?: string; // base64
    content?: string;
    data?: unknown; // NEW: for extract results
    count?: number; // NEW: number of extracted elements
}

export class PersistentBrowser {
    private process: ChildProcess | null = null; 
    private lastScreenshot: Uint8Array | null = null;
    private pendingCommands: { resolve: (value: BrowserResponse) => void; reject: (reason?: unknown) => void }[] = [];
    private buffer: string = '';
    private startPromise: Promise<void> | null = null;

    constructor() {}

    private async getPythonPath(): Promise<string> {
        if (typeof process === 'undefined' || !process.versions?.node) return 'python';
        const fs = await import('fs');
        const venvPath = process.platform === 'win32' ? '.venv/Scripts/python.exe' : '.venv/bin/python';
        if (fs.existsSync(venvPath)) {
            return venvPath;
        }
        return 'python';
    }

    private async startProcess() {
        if (this.process) return;
        if (typeof process === 'undefined' || !process.versions?.node) {
             throw new Error("Browser agent only supported in Node.js environment");
        }

        const path = (await import('path')).default;
        const { spawn } = await import('child_process');

        const scriptPath = path.resolve(process.cwd(), 'myai/interactive_browser.py');
        const pythonExec = await this.getPythonPath();

        logInfo('PersistentBrowser', `Starting browser process: ${pythonExec} ${scriptPath}`);

        this.process = spawn(pythonExec, [scriptPath], {
            stdio: ['pipe', 'pipe', 'pipe']
        });

        this.process.stdout?.on('data', (data: Buffer | string) => {
            this.buffer += data.toString();

            const lines = this.buffer.split('\n');
            this.buffer = lines.pop() || ''; // Keep the last partial line

            for (const line of lines) {
                if (!line.trim()) continue;
                try {
                    const response = JSON.parse(line);
                    this.handleResponse(response);
                } catch {
                    logError('PersistentBrowser', `Failed to parse response: ${line}`);
                }
            }
        });

        this.process.stderr?.on('data', (data: Buffer | string) => {
            logError('PersistentBrowser', `Python stderr: ${data.toString()}`);
        });

        this.process.on('close', (code: number | null) => {
            logInfo('PersistentBrowser', `Browser process exited with code ${code}`);
            this.process = null;
            // Reject all pending
            while (this.pendingCommands.length > 0) {
                const { reject } = this.pendingCommands.shift()!;
                reject(new Error('Browser process exited'));
            }
        });
    }

    private handleResponse(response: BrowserResponse) {
        if (this.pendingCommands.length > 0) {
            const { resolve, reject } = this.pendingCommands.shift()!;

            if (response.status === 'success') {
                if (response.screenshot) {
                    try {
                        this.lastScreenshot = Buffer.from(response.screenshot, 'base64');
                        // Remove base64 from object to keep it light
                        delete response.screenshot;
                    } catch {
                        logError('PersistentBrowser', 'Failed to decode screenshot');
                    }
                }
                resolve(response);
            } else {
                reject(new Error(response.message || 'Unknown error'));
            }
        }
    }

    public async sendCommand(command: BrowserCommand): Promise<BrowserResponse> {
        if (!this.process) {
            if (!this.startPromise) {
                this.startPromise = this.startProcess();
            }
            try {
                await this.startPromise;
            } catch (e) {
                this.startPromise = null;
                throw new Error("Failed to start browser process: " + String(e));
            }
        }

        return new Promise((resolve, reject) => {
            this.pendingCommands.push({ resolve, reject });
            const jsonCmd = JSON.stringify(command) + '\n';
            if (this.process && this.process.stdin) {
                this.process.stdin.write(jsonCmd);
            } else {
                reject(new Error("Process failed to start or is not running"));
            }
        });
    }

    public getLastScreenshot(): Uint8Array | null {
        return this.lastScreenshot;
    }

    public async close() {
        if (this.process) {
            await this.sendCommand({ action: 'close' }).catch(() => {}); // Ignore error if already closed
            if (this.process) this.process.kill();
            this.process = null;
            this.lastScreenshot = null;
        }
    }

    public isConnected(): boolean {
        return this.process !== null;
    }

    public forceKill() {
        if (this.process) {
            this.process.kill('SIGKILL');
            this.process = null;
        }
        
        // OS-level cleanup for chromium

        if (process.platform === 'win32') {
            exec('taskkill /F /IM chrome.exe /T');
            exec('taskkill /F /IM chromedriver.exe /T');
        } else {
            exec('pkill -f chromium');
            exec('pkill -f chrome');
        }
    }
}

export const persistentBrowser = new PersistentBrowser();

/**
 * Python Bridge — Zod sémák a Node.js ↔ Python határ típusbiztonságához.
 *
 * Minden Python API válaszhoz definiál egy Zod sémát, és safeParse-t
 * használ a validációhoz. Silent failure helyett explicit hibajelzés.
 */

import { z } from "zod";

// ── Python /execute válasz ──────────────────────────────────────────
export const ExecuteResultSchema = z.object({
  stdout: z.string(),
  error: z.string().optional(),
});
export type ExecuteResult = z.infer<typeof ExecuteResultSchema>;

// ── Crawl4AI /crawl4ai/crawl válasz ─────────────────────────────────
export const CrawlResultSchema = z.object({
  url: z.string(),
  markdown: z.string().default(""),
  title: z.string().default(""),
  description: z.string().default(""),
  language: z.string().default(""),
  extracted_data: z.unknown().nullable().optional(),
  links: z.array(z.string()).default([]),
  status: z.enum(["success", "blocked", "failed"]),
  error: z.string().nullable().optional(),
});
export type CrawlResult = z.infer<typeof CrawlResultSchema>;

// ── Harvest /harvest válasz ─────────────────────────────────────────
export const HarvestResultSchema = z.object({
  status: z.string(),
  data: z.unknown().optional(),
  error: z.string().optional(),
  steps_completed: z.number().optional(),
});
export type HarvestResult = z.infer<typeof HarvestResultSchema>;

// ── Harvest Extract /harvest/extract válasz ─────────────────────────
export const HarvestExtractResultSchema = z.object({
  status: z.string(),
  extracted: z.unknown().optional(),
  raw_text: z.string().optional(),
  error: z.string().optional(),
});
export type HarvestExtractResult = z.infer<typeof HarvestExtractResultSchema>;

// ── Refine /refine válasz ───────────────────────────────────────────
export const RefineResultSchema = z.object({
  status: z.string(),
  refined: z.unknown().optional(),
  original: z.unknown().optional(),
  error: z.string().optional(),
});
export type RefineResult = z.infer<typeof RefineResultSchema>;

// ── Generic Python error válasz ─────────────────────────────────────
export const PythonErrorSchema = z.object({
  error: z.string(),
});
export type PythonError = z.infer<typeof PythonErrorSchema>;

// ── Validáló segédfüggvények ────────────────────────────────────────

/**
 * Validálja a Python választ egy Zod sémával.
 * Sikertelen validáció esetén a nyers adatot adja vissza
 * warning log-gal, nem dob hibát (graceful degradation).
 */
export function validatePythonResponse<T>(
  schema: z.ZodType<T>,
  data: unknown,
  endpoint: string,
): { success: true; data: T } | { success: false; data: unknown; errors: string[] } {
  const result = schema.safeParse(data);
  if (result.success) {
    return { success: true, data: result.data };
  }
  const errors = result.error.issues.map(
    (issue) => `${issue.path.join(".")}: ${issue.message}`,
  );
  return { success: false, data, errors };
}

/**
 * JSON string parse + Zod validáció egylépésben.
 * Ha a JSON parse vagy a séma validáció sikertelen, hibaüzenetet ad.
 */
export function parseAndValidate<T>(
  schema: z.ZodType<T>,
  jsonString: string,
  endpoint: string,
): { success: true; data: T } | { success: false; raw: string; errors: string[] } {
  let parsed: unknown;
  try {
    parsed = JSON.parse(jsonString);
  } catch {
    return { success: false, raw: jsonString, errors: [`JSON parse hiba (${endpoint}): invalid JSON`] };
  }
  const result = schema.safeParse(parsed);
  if (result.success) {
    return { success: true, data: result.data };
  }
  const errors = result.error.issues.map(
    (issue) => `${issue.path.join(".")}: ${issue.message}`,
  );
  return { success: false, raw: jsonString, errors };
}

import path from "path";
import fs from "fs/promises";
import { config } from "../config/index.js";
import { E2BSandboxManager } from "../security/e2b_sandbox_manager.js";
import { ExecuteResultSchema, validatePythonResponse } from "./pythonBridge.js";

export class PythonShell {
  private scriptPath: string;
  private pythonPath: string;
  private apiUrl: string;
  private useApi: boolean = true;

  constructor(scriptRelativePath: string) {
    this.scriptPath = path.resolve(config.workspaceRoot, scriptRelativePath);
    const venvRel =
      process.platform === "win32"
        ? ".venv/Scripts/python.exe"
        : ".venv/bin/python";
    const candidatePath = path.resolve(config.workspaceRoot, venvRel);
    this.apiUrl =
      process.env.BRUNELLA_PYTHON_API_URL ?? "http://127.0.0.1:8000";
    this.useApi = this.apiUrl !== "" && this.apiUrl !== "disabled";

    this.pythonPath = "python"; // Default fallback

    // Validate python path for legacy fallback - ONLY in Node environment
    if (typeof process !== 'undefined' && process.versions?.node) {
       this.validatePythonPath(candidatePath);
    }
  }

  private async validatePythonPath(candidatePath: string) {
    try {
      const { execSync } = await import("child_process");
      execSync(`"${candidatePath}" --version`, { stdio: "ignore" });
      this.pythonPath = candidatePath;
    } catch (e) {
      this.pythonPath = "python"; // Fallback
    }
  }

  /** Zone IV: Phoenix Protocol – retry on failure, then fallback. */
  async run(code: string, context?: any): Promise<string> {
    // E2B Sandbox mode: isolated cloud execution (highest security)
    if (process.env.E2B_ENABLED === 'true') {
      return this.runViaE2B(code);
    }

    if (this.useApi) {
      try {
        return await this.runViaApi(code, context);
      } catch (e) {
        // Phoenix: retry once after short delay
        await new Promise((r) => setTimeout(r, 1500));
        try {
          return await this.runViaApi(code, context);
        } catch (e2) {
          // Fallback to legacy subprocess
        }
      }
    }
    return this.runLegacy(code, context);
  }

  private async runViaE2B(code: string): Promise<string> {
    const sandbox = new E2BSandboxManager();
    const result = await sandbox.executeCode(code, { export_artifacts: false });
    if (!result.success) {
      return JSON.stringify({ error: result.error ?? 'E2B execution failed' });
    }
    return result.output ?? '';
  }

  private async runViaApi(code: string, context?: any): Promise<string> {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 60000);

    try {
      const response = await fetch(`${this.apiUrl}/execute`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ code, context }),
        signal: controller.signal,
      });

      if (!response.ok) {
        throw new Error(
          `API returned ${response.status}: ${await response.text()}`,
        );
      }

      const data = (await response.json()) as Record<string, unknown>;

      // Zod validáció — típusbiztos Python válasz
      const validated = validatePythonResponse(ExecuteResultSchema, data, "/execute");
      if (validated.success) {
        const typed = validated.data;
        if (typed.error) {
          return JSON.stringify({ error: typed.error });
        }
        return typed.stdout;
      }
      // Graceful degradation: ha a séma nem stimmel, fallback a régi logikára
      const fallback = data as { stdout?: string; error?: string };
      if (fallback.error) {
        return JSON.stringify({ error: fallback.error });
      }
      return String(fallback.stdout ?? "");
    } finally {
      clearTimeout(timeout);
    }
  }

  private async runLegacy(code: string, context?: any): Promise<string> {
    if (typeof process === 'undefined' || !process.versions?.node) {
        throw new Error("Legacy Python execution is only supported in Node.js environment");
    }

    const { exec } = await import("child_process");
    const root = config.workspaceRoot.replace(/\\/g, "/");
    const tempIn = path.join(config.systemLogDir, `py_in_${Date.now()}.json`);
    const tempPy = path.join(config.systemLogDir, `py_run_${Date.now()}.py`);

    try {
      await fs.mkdir(config.systemLogDir, { recursive: true });
    } catch (e) { /* non-critical */ } // Ignore if dir exists

    try {
      await fs.writeFile(tempIn, JSON.stringify(context || {}), "utf-8");

      // Indent the code to fit inside the try block
      const indentedCode = code
        .split("\n")
        .map((line) => "    " + line)
        .join("\n");

      const wrapperCode = `
import sys, json, os
import traceback

sys.path.append('${root}')

try:
    with open('${tempIn.replace(/\\/g, "/")}', 'r', encoding='utf-8') as f:
        context = json.load(f)
${indentedCode}
except Exception as e:
    traceback.print_exc()
    print(json.dumps({"error": str(e)}))
`;
      await fs.writeFile(tempPy, wrapperCode, "utf-8");

      return new Promise((resolve, reject) => {
        exec(
          `"${this.pythonPath}" "${tempPy}"`,
          { timeout: 60000, maxBuffer: 4 * 1024 * 1024 },
          async (error, stdout, stderr) => {
            await fs.unlink(tempIn).catch(() => {});
            await fs.unlink(tempPy).catch(() => {});
            if (error) {
              // If output contains JSON error, prefer that
              if (stdout.trim().startsWith("{") && stdout.includes('"error"')) {
                resolve(stdout.trim());
                return;
              }
              reject(stderr || error.message);
              return;
            }
            resolve(stdout.trim());
          },
        );
      });
    } catch (e: any) {
      return JSON.stringify({ error: e.message });
    }
  }
}

export const globalPythonShell = new PythonShell("interactive.py");

/**
 * Runs a specific Python worker script with JSON arguments.
 */
export async function runPythonWorker(scriptName: string, args: any): Promise<any> {
  const code = `
import asyncio
import json
import sys
from importlib import import_module

# Add project root to path
sys.path.append('.')

async def main():
    module_name = "${scriptName.replace('.py', '').replace('/', '.')}"
    # Try different locations
    try:
        module = import_module(module_name)
    except ImportError:
        try:
            module = import_module("myai.workers." + module_name)
        except ImportError:
            module = import_module("myai.refiners." + module_name)
            
    # Look for common entry points
    if hasattr(module, 'scrape_page_data'):
        res = await module.scrape_page_data(**context)
    elif hasattr(module, 'evaluate_product_potential'):
        res = await module.evaluate_product_potential(context)
    elif hasattr(module, 'parse_invoice_text'):
        res = await module.parse_invoice_text(context.get('text', ''))
    else:
        raise AttributeError(f"No valid entry point found in {module_name}")
        
    print(json.dumps(res))

if __name__ == "__main__":
    asyncio.run(main())
`;
  const output = await globalPythonShell.run(code, args);
  try {
    const parsed: unknown = JSON.parse(output);
    // Zod validáció: ha error objektum, explicit jelezzük
    const errCheck = validatePythonResponse(
      ExecuteResultSchema,
      typeof parsed === "object" && parsed !== null && "stdout" in parsed ? parsed : { stdout: output },
      "runPythonWorker",
    );
    // A worker eredményt parseoljuk, nem ExecuteResult-ot
    return parsed;
  } catch (e) {
    throw new Error(`Failed to parse Python worker output: ${output}. Error: ${e}`);
  }
}

// FILE: src/utils/rag.ts
// PURPOSE: Zone II: Hibrid memória rendszer (LanceDB) valós idejű íráshoz Node.js-ben.
// Zone IV: Dual Storage (LanceDB + JSONL backup).
// Zone V: Vector Embeddings via Ollama nomic-embed-text model.

import fs from "fs/promises";
import path from "path";
import { logInfo, logError, logWarn } from "./logger.js";
import { aiGateway } from "./aiGateway.js";
import { vectorizeClient } from "./vectorize.js";

const DB_PATH = "./data/brunella_lancedb";
const HARVEST_BACKUP_PATH = "./logs/harvest_backup.jsonl";

let _lancedbModule: any = null;
let _lancedbConnected: any = null;

async function loadLanceDBModule(): Promise<any | null> {
  if (_lancedbModule) return _lancedbModule;
  try {
    _lancedbModule = await import("@lancedb/lancedb");
    logInfo("RAG", "LanceDB module loaded dynamically.");
    return _lancedbModule;
  } catch (e: unknown) {
    logWarn("RAG", `LanceDB module not available: ${e instanceof Error ? e.message : String(e)}`);
    _lancedbModule = null;
    return null;
  }
}

async function connectToLanceDB(): Promise<any | null> {
  if (_lancedbConnected) return _lancedbConnected;
  const mod = await loadLanceDBModule();
  if (!mod) return null;
  try {
    const connector = mod.connect ?? mod.default?.connect;
    if (typeof connector !== "function") {
      logError("RAG", "@lancedb/lancedb module does not expose a connect() function. LanceDB disabled.");
      _lancedbConnected = null;
      return null;
    }
    _lancedbConnected = await connector(DB_PATH);
    logInfo("RAG", "Connected to LanceDB.");
    return _lancedbConnected;
  } catch (e: unknown) {
    logError("RAG", `Failed to connect to LanceDB: ${e instanceof Error ? e.message : String(e)}`);
    _lancedbConnected = null;
    return null;
  }
}

// Ollama embedding configuration (dual-index transition)
const PRIMARY_EMBEDDING_MODEL =
  process.env.RAG_EMBEDDING_MODEL_PRIMARY ||
  process.env.EMBEDDING_MODEL ||
  "mxbai-embed-large";
const PRIMARY_EMBEDDING_DIMENSION = Number(
  process.env.RAG_EMBEDDING_DIM_PRIMARY || 1024,
);
const LEGACY_EMBEDDING_MODEL =
  process.env.RAG_EMBEDDING_MODEL_LEGACY || "nomic-embed-text";
const LEGACY_EMBEDDING_DIMENSION = Number(
  process.env.RAG_EMBEDDING_DIM_LEGACY || 768,
);
const DUAL_INDEX_WRITE_ENABLED =
  (process.env.RAG_DUAL_INDEX_WRITE || "true").toLowerCase() === "true";
const PRIMARY_TABLE = process.env.RAG_PRIMARY_TABLE || "memory_v2_mxbai";
const LEGACY_TABLE = process.env.RAG_LEGACY_TABLE || "memory";

type EmbeddingConfig = {
  model: string;
  dimension: number;
  tableName: string;
};

type EmbeddingResult = {
  vector: number[];
  available: boolean;
};

const PRIMARY_EMBEDDING_CONFIG: EmbeddingConfig = {
  model: PRIMARY_EMBEDDING_MODEL,
  dimension: PRIMARY_EMBEDDING_DIMENSION,
  tableName: PRIMARY_TABLE,
};

const LEGACY_EMBEDDING_CONFIG: EmbeddingConfig = {
  model: LEGACY_EMBEDDING_MODEL,
  dimension: LEGACY_EMBEDDING_DIMENSION,
  tableName: LEGACY_TABLE,
};

const ZERO_VECTOR_RATIO_THRESHOLD = 0.95;
const modelAvailability = new Map<string, boolean>();

function zeroVector(size: number): number[] {
  return new Array(size).fill(0);
}

function normalizeEmbedding(
  raw: number[] | null | undefined,
  expectedDimension: number,
): number[] {
  if (!raw || !Array.isArray(raw) || raw.length === 0) {
    return zeroVector(expectedDimension);
  }

  if (raw.length === expectedDimension) {
    return raw;
  }

  if (raw.length > expectedDimension) {
    return raw.slice(0, expectedDimension);
  }

  return [...raw, ...zeroVector(expectedDimension - raw.length)];
}

function isMostlyZeroVector(vector: number[]): boolean {
  if (!vector.length) return true;
  const zeroCount = vector.filter((v) => v === 0).length;
  return zeroCount / vector.length >= ZERO_VECTOR_RATIO_THRESHOLD;
}

/**
 * Get embedding vector from Ollama API (via AI Gateway if enabled)
 * Uses configurable embedding model and enforces expected vector dimension.
 */
async function getEmbedding(
  text: string,
  config: EmbeddingConfig,
): Promise<EmbeddingResult> {
  if (modelAvailability.get(config.model) === false) {
    return {
      vector: zeroVector(config.dimension),
      available: false,
    };
  }

  try {
    const rawEmbedding = await aiGateway.embeddings(text.slice(0, 8000), {
      model: config.model,
      expectedDimension: config.dimension,
    });

    const vector = normalizeEmbedding(rawEmbedding, config.dimension);
    const available = !isMostlyZeroVector(vector);
    modelAvailability.set(config.model, available);

    return { vector, available };
  } catch (error: any) {
    modelAvailability.set(config.model, false);
    logError("RAG", `Embedding error (${config.model}): ${error.message}`);
    return {
      vector: zeroVector(config.dimension),
      available: false,
    };
  }
}

export class HybridMemory {
  private dbPath: string;

  constructor(dbPath: string = DB_PATH) {
    this.dbPath = dbPath;
  }

  private async addDocumentToTable(
    db: any,
    tableNames: string[],
    tableName: string,
    record: Record<string, unknown>,
  ): Promise<void> {
    if (tableNames.includes(tableName)) {
      const table = await db.openTable(tableName);
      try {
        await table.add([record]);
        return;
      } catch (e: any) {
        const msg = e instanceof Error ? e.message : String(e);
        logWarn("RAG", `Failed to add to table ${tableName}: ${msg}. Attempting to recreate table with new schema.`);
        try {
          if (typeof db.deleteTable === "function") {
            await db.deleteTable(tableName);
            logInfo("RAG", `Deleted table ${tableName} to recreate schema.`);
          } else if (typeof db.dropTable === "function") {
            await db.dropTable(tableName);
            logInfo("RAG", `Dropped table ${tableName} to recreate schema.`);
          } else {
            logWarn("RAG", "DB does not support deleteTable/dropTable; attempting createTable which may fail if table exists.");
          }
        } catch (ee: any) {
          logWarn("RAG", `Error deleting table ${tableName}: ${ee?.message ?? String(ee)}`);
        }
        try {
          await db.createTable(tableName, [record]);
          return;
        } catch (ee: any) {
          logError("RAG", `Failed to recreate table ${tableName}: ${ee?.message ?? String(ee)}`);
          throw e;
        }
      }
    }

    await db.createTable(tableName, [record]);
  }

  private async searchTable(
    db: any,
    tableName: string,
    query: string,
    limit: number,
    config: EmbeddingConfig,
  ): Promise<Array<{ text: string; path?: string; score?: number }>> {
    const table = await db.openTable(tableName);
    const embedding = await getEmbedding(query, config);
    const queryVector = embedding.vector;

    if (embedding.available && !isMostlyZeroVector(queryVector)) {
      const results = await table
        .vectorSearch(queryVector)
        .limit(limit)
        .toArray();

      return results.map((r: any) => ({
        text: r.text || "",
        path: r.path,
        score: r._distance,
      }));
    }

    logInfo(
      "RAG",
      `Embedding unavailable for ${config.model}, using text fallback on ${tableName}`,
    );
    const results: Array<{ text: string; path?: string }> = [];
    const q = query.toLowerCase();

    for await (const batch of table.query().limit(limit * 3)) {
      const textCol = batch.getChild("text");
      const pathCol = (batch.schema.fields as Array<{ name?: string }>).find((f) => f.name === "path")
        ? batch.getChild("path")
        : null;
      const n = batch.numRows;
      for (let i = 0; i < n; i++) {
        const text = String(textCol?.get(i) ?? "");
        if (text.toLowerCase().includes(q)) {
          results.push({
            text,
            path: pathCol ? String(pathCol.get(i) ?? "") : undefined,
          });
          if (results.length >= limit) return results;
        }
      }
    }

    // Fallback: some LanceDB table implementations expose row arrays via toArray()/query().toArray() or simple toArray
    if (results.length === 0) {
      try {
        // try table.toArray()
        if (typeof (table as any).toArray === "function") {
          const rows = await (table as any).toArray();
          for (const r of rows) {
            const text = String(r?.text ?? r?.get?.("text") ?? "");
            const pathVal = r?.path ?? (typeof r?.get === "function" ? r.get("path") : undefined);
            if (text.toLowerCase().includes(q)) {
              results.push({ text, path: pathVal });
              if (results.length >= limit) return results;
            }
          }
        } else if (typeof table.query === "function" && typeof (table.query() as any).toArray === "function") {
          const rows = await (table.query() as any).toArray();
          for (const r of rows) {
            const text = String(r?.text ?? "");
            const pathVal = r?.path;
            if (text.toLowerCase().includes(q)) {
              results.push({ text, path: pathVal });
              if (results.length >= limit) return results;
            }
          }
        } else if (typeof (table as any).getRows === "function") {
          const rows = await (table as any).getRows();
          for (const r of rows) {
            const text = String(r?.text ?? "");
            const pathVal = r?.path;
            if (text.toLowerCase().includes(q)) {
              results.push({ text, path: pathVal });
              if (results.length >= limit) return results;
            }
          }
        }
      } catch (ee: any) {
        logWarn('RAG', `Fallback table enumeration failed: ${ee?.message ?? String(ee)}`);
      }
    }

    return results;
  }

  async addDocument(content: string, metadata: object) {
    const db = await connectToLanceDB();
    if (!db) {
      logWarn('RAG', 'LanceDB not available; skipping local index write.');
      return;
    }
    const tableNames = await db.tableNames();

    const createdAt = new Date().toISOString();
    const primaryEmbedding = await getEmbedding(content, PRIMARY_EMBEDDING_CONFIG);
    let wroteAnyIndex = false;

    if (primaryEmbedding.available) {
      await this.addDocumentToTable(
        db,
        tableNames,
        PRIMARY_EMBEDDING_CONFIG.tableName,
        {
          vector: primaryEmbedding.vector,
          text: content,
          embeddingModel: PRIMARY_EMBEDDING_CONFIG.model,
          embeddingDimension: PRIMARY_EMBEDDING_CONFIG.dimension,
          ...metadata,
          createdAt,
        },
      );
      wroteAnyIndex = true;
    }

    if (DUAL_INDEX_WRITE_ENABLED || !primaryEmbedding.available) {
      const legacyEmbedding = await getEmbedding(content, LEGACY_EMBEDDING_CONFIG);
      await this.addDocumentToTable(
        db,
        tableNames,
        LEGACY_EMBEDDING_CONFIG.tableName,
        {
          vector: legacyEmbedding.vector,
          text: content,
          embeddingModel: LEGACY_EMBEDDING_CONFIG.model,
          embeddingDimension: LEGACY_EMBEDDING_CONFIG.dimension,
          ...metadata,
          createdAt,
        },
      );
      wroteAnyIndex = true;
    }

    if (!wroteAnyIndex) {
      logWarn('RAG', 'No embedding index was written; both primary and legacy embeddings were unavailable');
    }

    logInfo("RAG", `Document indexed: ${(metadata as any).path || "unknown"}`);
  }

  async getTableCount(): Promise<number> {
    try {
      const db = await connectToLanceDB();
      if (!db) {
        logWarn('RAG', 'LanceDB not available; getTableCount() returning 0.');
        return 0;
      }
      const tableNames = await db.tableNames();

      const selectedTable = tableNames.includes(
        PRIMARY_EMBEDDING_CONFIG.tableName,
      )
        ? PRIMARY_EMBEDDING_CONFIG.tableName
        : LEGACY_EMBEDDING_CONFIG.tableName;

      if (!tableNames.includes(selectedTable)) return 0;

      const table = await db.openTable(selectedTable);
      return await table.countRows();
    } catch (e) {
      return 0;
    }
  }

  async search(
    query: string,
    limit = 20,
  ): Promise<Array<{ text: string; path?: string; score?: number }>> {
    try {
      const db = await connectToLanceDB();
      if (!db) {
        logWarn('RAG', 'LanceDB not available; search() returning empty results.');
        return [];
      }
      const tableNames = await db.tableNames();
      if (tableNames.length === 0) return [];

      if (
        tableNames.includes(PRIMARY_EMBEDDING_CONFIG.tableName) &&
        modelAvailability.get(PRIMARY_EMBEDDING_CONFIG.model) !== false
      ) {
        const primaryResults = await this.searchTable(
          db,
          PRIMARY_EMBEDDING_CONFIG.tableName,
          query,
          limit,
          PRIMARY_EMBEDDING_CONFIG,
        );

        if (primaryResults.length > 0) {
          return primaryResults;
        }
      }

      if (tableNames.includes(LEGACY_EMBEDDING_CONFIG.tableName)) {
        logInfo(
          "RAG",
          `Primary index empty, falling back to legacy index (${LEGACY_EMBEDDING_CONFIG.tableName})`,
        );
        return await this.searchTable(
          db,
          LEGACY_EMBEDDING_CONFIG.tableName,
          query,
          limit,
          LEGACY_EMBEDDING_CONFIG,
        );
      }

      return [];
    } catch (error: any) {
      logError("RAG", `Search error: ${error.message}`);
      return [];
    }
  }
}

const memory = new HybridMemory();

/** Add content to the RAG index (path/id stored in metadata). */
export async function addToIndex(
  pathOrId: string,
  content: string,
): Promise<void> {
  // 1. Vectorize (cloud, elsődleges)
  if (process.env.CF_VECTORIZE_ENABLED === 'true' || vectorizeClient.getStatus().enabled) {
    try {
      await vectorizeClient.upsertText(pathOrId, content, { source: pathOrId });
    } catch (e: any) {
      logWarn('RAG', `Vectorize upsert failed: ${e.message}`);
    }
  }

  // 2. LanceDB fallback (lokális)
  await fs.mkdir(path.dirname(DB_PATH), { recursive: true }).catch(() => {});
  await memory.addDocument(content, { path: pathOrId });
}

/** Get total number of records in the RAG index. */
export async function getRAGCount(): Promise<number> {
  return await memory.getTableCount();
}

/** Search RAG using vector similarity (cosine distance via LanceDB). */
export async function searchRAG(
  query: string,
  limit = 20,
): Promise<Array<{ text: string; path?: string; score?: number }>> {
  // 1. Vectorize (cloud, elsődleges)
  if (process.env.CF_VECTORIZE_ENABLED === 'true' || vectorizeClient.getStatus().enabled) {
    try {
      const results = await vectorizeClient.searchText(query, limit);
      if (results.length > 0) {
        return results.map(r => ({
          text: (r.metadata?.text as string) || '',
          path: (r.metadata?.source as string) || r.id,
          score: r.score
        }));
      }
    } catch (e: any) {
      logWarn('RAG', `Vectorize search failed, fallback LanceDB: ${e.message}`);
    }
  }

  // 2. LanceDB fallback (lokális)
  return await memory.search(query, limit);
}

/** Zone IV: Dual Storage – LanceDB + JSONL backup (antifragilitás). */
export class DualStorageManager {
  private backupPath = HARVEST_BACKUP_PATH;
  private dbPath = DB_PATH;

  async saveWithBackup(
    table: string,
    data: Record<string, unknown>,
  ): Promise<void> {
    const entry = { ...data, savedAt: new Date().toISOString(), table };
    const line = JSON.stringify(entry) + "\n";

    // 1. JSONL backup (biztonsági mentés)
    await fs
      .mkdir(path.dirname(this.backupPath), { recursive: true })
      .catch(() => {});
    await fs.appendFile(this.backupPath, line, "utf-8").catch((e) => {
      logWarn("RAG", `Backup write failed: ${e.message}`);
    });

    // 2. LanceDB (ha van text mező)
    const text = (data.text as string) ?? JSON.stringify(data);
    await addToIndex((data.path as string) ?? `harvest_${Date.now()}`, text);
  }
}

/**
 * Response Formatter - Magyar nyelvű, emberi olvasható válaszok
 *
 * Minden ügynök válaszát természetes magyar nyelvű szöveggé alakítja
 * JSON/kód formátum helyett.
 *
 * @version 1.0.0
 * @created 2026-02-16
 */

import type { AgentResponse } from '../agents/types.js';
import type { AgentResult } from '../agents/BaseAgent.js';

/**
 * Formázási opciók
 */
export interface FormatterOptions {
  /** Emoji használat (alapértelmezett: true) */
  useEmojis?: boolean;
  /** Részletes mód (több technikai info) */
  verbose?: boolean;
  /** Nyelv (jelenleg csak 'hu') */
  language?: 'hu';
}

/**
 * Sikeres műveletet formáz magyar nyelvre
 */
function formatSuccess(
  message: string,
  data?: unknown,
  options: FormatterOptions = {}
): string {
  const { useEmojis = true, verbose = false } = options;
  const emoji = useEmojis ? '✅ ' : '';

  let response = `${emoji}**Sikeresen végrehajtva!**\n\n${message}`;

  // Ha van adat és verbose mód, akkor hozzáadunk részleteket
  if (verbose && data) {
    response += '\n\n**Részletek:**\n';
    if (typeof data === 'object' && data !== null) {
      response += formatDataObject(data);
    } else {
      response += `${data}`;
    }
  }

  return response;
}

/**
 * Hibás műveletet formáz magyar nyelvre
 */
function formatError(
  error: string,
  options: FormatterOptions = {}
): string {
  const { useEmojis = true } = options;
  const emoji = useEmojis ? '❌ ' : '';

  return `${emoji}**Nem sikerült a művelet**\n\n${error}\n\nKérlek, próbáld újra vagy adj más utasítást!`;
}

/**
 * Delegált műveletet formáz magyar nyelvre
 */
function formatDelegated(
  targetAgent: string,
  message?: string,
  options: FormatterOptions = {}
): string {
  const { useEmojis = true } = options;
  const emoji = useEmojis ? '🔄 ' : '';

  const msg = message || `Átadom a feladatot a **${targetAgent}** ügynöknek`;
  return `${emoji}${msg}`;
}

/**
 * Handoff műveletet formáz magyar nyelvre
 */
function formatHandoff(
  targetAgent: string,
  reason: string,
  options: FormatterOptions = {}
): string {
  const { useEmojis = true } = options;
  const emoji = useEmojis ? '🤝 ' : '';

  return `${emoji}**Feladatátadás:** ${targetAgent}\n\n**Indok:** ${reason}`;
}

/**
 * Data objektumot formáz olvasható formára
 */
function formatDataObject(data: unknown): string {
  if (!data || typeof data !== 'object') {
    return String(data);
  }

  const lines: string[] = [];

  for (const [key, value] of Object.entries(data)) {
    // Kihagyjuk a belső technikai mezőket
    if (key.startsWith('_') || key === 'thoughts' || key === 'contextUsed') {
      continue;
    }

    const formattedKey = formatKey(key);

    if (Array.isArray(value)) {
      lines.push(`- **${formattedKey}:** ${value.length} elem`);
      if (value.length > 0 && value.length <= 5) {
        value.forEach((item, idx) => {
          lines.push(`  ${idx + 1}. ${formatValue(item)}`);
        });
      }
    } else if (typeof value === 'object' && value !== null) {
      lines.push(`- **${formattedKey}:**`);
      const nested = formatDataObject(value);
      lines.push(nested.split('\n').map(line => `  ${line}`).join('\n'));
    } else {
      lines.push(`- **${formattedKey}:** ${formatValue(value)}`);
    }
  }

  return lines.join('\n');
}

/**
 * Kulcs nevét formázza magyar olvasható formára
 */
function formatKey(key: string): string {
  // CamelCase -> Szóköz + Nagybetű
  return key
    .replace(/([A-Z])/g, ' $1')
    .replace(/^./, str => str.toUpperCase())
    .trim();
}

/**
 * Értéket formáz olvasható formára
 */
function formatValue(value: unknown): string {
  if (value === null || value === undefined) {
    return '-';
  }
  if (typeof value === 'boolean') {
    return value ? 'Igen' : 'Nem';
  }
  if (typeof value === 'number') {
    return value.toLocaleString('hu-HU');
  }
  if (typeof value === 'string') {
    return value;
  }
  if (typeof value === 'object') {
    return JSON.stringify(value, null, 2);
  }
  return String(value);
}

/**
 * AgentResponse-t formáz magyar nyelvű szöveggé
 */
export function formatAgentResponse(
  response: AgentResponse,
  agentName?: string,
  options: FormatterOptions = {}
): string {
  const { useEmojis = true } = options;

  // Agent név prefix (ha van)
  const prefix = agentName && useEmojis ? `🤖 **${agentName}:**\n\n` : '';

  switch (response.status) {
    case 'success': {
      const successMsg = response.message || 'A művelet sikeres volt';
      return prefix + formatSuccess(successMsg, response.data, options);
    }

    case 'error': {
      const errorMsg = response.error || 'Ismeretlen hiba történt';
      return prefix + formatError(errorMsg, options);
    }

    case 'delegated': {
      const targetAgent = response.delegatedTo || 'másik ügynök';
      return prefix + formatDelegated(targetAgent, response.message, options);
    }

    case 'handoff':
      if (response.handoff) {
        return prefix + formatHandoff(
          response.handoff.targetAgent,
          response.handoff.reason,
          options
        );
      }
      return prefix + formatDelegated(response.delegatedTo || 'másik ügynök', response.message, options);

    default:
      return prefix + (response.message || JSON.stringify(response));
  }
}

/**
 * BaseAgent AgentResult-ot formáz magyar nyelvű szöveggé
 */
export function formatAgentResult(
  result: AgentResult,
  agentName?: string,
  options: FormatterOptions = {}
): string {
  const { useEmojis = true } = options;

  // Agent név prefix (ha van)
  const prefix = agentName && useEmojis ? `🤖 **${agentName}:**\n\n` : '';

  if (result.success) {
    return prefix + formatSuccess(result.message, result.data, options);
  } else {
    return prefix + formatError(result.message, options);
  }
}

/**
 * Automatikus formázás - bármilyen válasz típust kezel
 */
export function formatResponse(
  response: AgentResponse | AgentResult | unknown,
  agentName?: string,
  options: FormatterOptions = {}
): string {
  // Ha már string, visszaadjuk
  if (typeof response === 'string') {
    return response;
  }

  // Ha AgentResponse
  if (response && typeof response === 'object' && 'status' in response) {
    return formatAgentResponse(response as AgentResponse, agentName, options);
  }

  // Ha BaseAgent AgentResult (success + message)
  if (response && typeof response === 'object' && 'success' in response && 'message' in response) {
    return formatAgentResult(response as AgentResult, agentName, options);
  }

  // Fallback: JSON stringify
  const prefix = agentName ? `🤖 **${agentName}:**\n\n` : '';
  return prefix + JSON.stringify(response, null, 2);
}

/**
 * Speciális formázók különböző ügynök típusokhoz
 */
export const specialFormatters = {
  /**
   * Robotkéz V2 válasz formázás
   */
  robotkez(result: AgentResult, options: FormatterOptions = {}): string {
    const { useEmojis = true } = options;
    const emoji = useEmojis ? '🤖 ' : '';

    if (!result.success) {
      return formatError(result.message, options);
    }

    const data = result.data as any;
    let response = `${emoji}**Robotkéz V2 - Végrehajtva**\n\n`;

    // Plan steps
    if (data?.plan && Array.isArray(data.plan)) {
      response += `**Végrehajtott lépések:**\n`;
      data.plan.forEach((step: any, idx: number) => {
        const status = step.status === 'completed' ? '✅' : step.status === 'error' ? '❌' : '⏳';
        response += `${idx + 1}. ${status} ${step.description}\n`;
      });
      response += '\n';
    }

    response += result.message;

    // Completed steps summary
    if (data?.completedSteps && Array.isArray(data.completedSteps)) {
      const successful = data.completedSteps.filter((s: any) => s.status === 'completed').length;
      response += `\n\n**Összesítés:** ${successful}/${data.completedSteps.length} lépés sikeres`;
    }

    return response;
  },

  /**
   * Developer Agent válasz formázás
   */
  developer(result: AgentResult, options: FormatterOptions = {}): string {
    const { useEmojis = true } = options;
    const emoji = useEmojis ? '👨‍💻 ' : '';

    if (!result.success) {
      return formatError(result.message, options);
    }

    const data = result.data as any;
    let response = `${emoji}**Developer Agent - Kód írva**\n\n`;

    response += result.message;

    if (data?.filesModified) {
      response += `\n\n**Módosított fájlok:** ${data.filesModified}`;
    }

    if (data?.linesAdded || data?.linesRemoved) {
      response += `\n**Változtatások:** +${data.linesAdded || 0} / -${data.linesRemoved || 0} sor`;
    }

    return response;
  },

  /**
   * Researcher Agent válasz formázás
   */
  researcher(result: AgentResult, options: FormatterOptions = {}): string {
    const { useEmojis = true } = options;
    const emoji = useEmojis ? '🔍 ' : '';

    if (!result.success) {
      return formatError(result.message, options);
    }

    const data = result.data as any;
    let response = `${emoji}**Researcher Agent - Kutatás kész**\n\n`;

    response += result.message;

    if (data?.sources && Array.isArray(data.sources)) {
      response += `\n\n**Források (${data.sources.length}):**\n`;
      data.sources.slice(0, 5).forEach((source: any, idx: number) => {
        response += `${idx + 1}. ${source.title || source.url || source}\n`;
      });
    }

    return response;
  }
};

/**
 * Default export - egyszerű használat
 */
export default {
  format: formatResponse,
  formatAgentResponse,
  formatAgentResult,
  specialFormatters
};

import type { ChildProcess } from 'child_process';
import net from 'net';
import path from 'path';

export async function checkServerRunning(port: number = 3000): Promise<boolean> {
  return new Promise((resolve) => {
    const socket = new net.Socket();
    socket.setTimeout(1000);
    socket.on('connect', () => {
      socket.destroy();
      resolve(true);
    });
    socket.on('timeout', () => {
      socket.destroy();
      resolve(false);
    });
    socket.on('error', () => {
      socket.destroy();
      resolve(false);
    });
    socket.connect(port, '127.0.0.1');
  });
}

export async function startServer(): Promise<ChildProcess> {
  const { spawn } = await import('child_process');
  const serverPath = path.join(__dirname, '../../build/index.js');
  
  // We spawn the server. It will use stdio for MCP, but also start the web server on port 3000.
  // The CLI might want to use the stdio connection immediately if it spawned it?
  // But the requirement says "Hybrid": connect to running, OR start new.
  
  // If we start it, we can pipe stdio.
  const child = spawn('node', [serverPath], {
    stdio: ['pipe', 'pipe', 'pipe'], // We can use this for MCP communication if we want
    env: { ...process.env, WEB_UI_ENABLED: 'true' }
  });

  child.stderr?.on('data', (data) => {
    // Log server stderr?
  });

  return child;
}

import axios from "axios";
import { logInfo, logError } from "./logger.js";
import { generateResponse } from "../core/llm_client.js";

const CLOUDFLARE_CHAT_SYNC_URL = (
  process.env.CLOUDFLARE_CHAT_SYNC_URL ||
  process.env.CLOUDFLARE_CHAT_URL ||
  process.env.CLOUDFLARE_WORKER_URL ||
  "https://bas-orchestrator.peterpohankapersonal.workers.dev"
).replace(/\/+$/, "");
const SYNC_INTERVAL_MS = 5000;

interface ChatMessage {
  id: number;
  role: "user" | "assistant" | "system";
  content: string;
  model: string;
  timestamp: string;
  synced: number;
}

class SyncService {
  private isRunning = false;
  private lastProcessedId = 0;

  private buildHeaders(): Record<string, string> {
    const token = (process.env.CLOUDFLARE_API_TOKEN || "").replace(/"/g, "").trim();
    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    if (token) {
      headers.Authorization = `Bearer ${token}`;
      headers["X-CEAN-API-Key"] = token; // legacy support
    }

    return headers;
  }

  async start() {
    if (this.isRunning) return;
    this.isRunning = true;
    logInfo("SyncService", `Cloudflare chat sync started. URL: ${CLOUDFLARE_CHAT_SYNC_URL}`);
    this.poll();
  }

  private async poll() {
    while (this.isRunning) {
      try {
        const response = await axios.get<ChatMessage[]>(`${CLOUDFLARE_CHAT_SYNC_URL}/chat/messages`, {
          headers: this.buildHeaders(),
        });
        const messages = response.data;

        for (const msg of messages) {
          if (msg.id > this.lastProcessedId) {
            this.lastProcessedId = msg.id;

            if (msg.role === "user") {
              logInfo("SyncService", `New remote message: ${msg.content.slice(0, 30)}...`);
              
              const aiResponse = await generateResponse(msg.content); 
              
              await axios.post(`${CLOUDFLARE_CHAT_SYNC_URL}/chat/messages`, {
                role: "assistant",
                content: aiResponse,
                model: "local-sync",
                timestamp: new Date().toISOString()
              }, {
                headers: this.buildHeaders(),
              });
              
              logInfo("SyncService", "Response synced back to Cloudflare");
            }
          }
        }
      } catch (error: any) {
        const errorDetail = error.response?.data ? JSON.stringify(error.response.data) : error.message;
        logError("SyncService", `Sync error: ${errorDetail}`);
      }
      
      await new Promise(resolve => setTimeout(resolve, SYNC_INTERVAL_MS));
    }
  }

  stop() {
    this.isRunning = false;
  }
}

export const syncService = new SyncService();

let db: any = null;
let path: any = null;
let fs: any = null;

interface TaskRow {
    id: number;
    agent: string;
    task: string;
    status: string;
    context?: string | null;
    result?: string | null;
    created_at: string;
    completed_at?: string | null;
}

async function ensureDeps() {
    if (typeof process !== 'undefined' && process.versions?.node) {
        if (!path) path = await import('path');
        if (!fs) fs = await import('fs');
    }
}

async function getDb() {
    if (db) return db;

    await ensureDeps();
    if (!path || !fs) return null;

    const dbPath = path.join(process.cwd(), 'data', 'tasks.db');

    if (!fs.existsSync(path.dirname(dbPath))) {
        fs.mkdirSync(path.dirname(dbPath), { recursive: true });
    }

    const Database = (await import('better-sqlite3')).default;
    db = new Database(dbPath);

    db.exec(`
        CREATE TABLE IF NOT EXISTS tasks (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            agent TEXT,
            task TEXT,
            status TEXT DEFAULT 'pending',
            context TEXT,
            result TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            completed_at DATETIME
        )
    `);

    // RobotkezV2 Background Tasks table
    db.exec(`
        CREATE TABLE IF NOT EXISTS robotkez_background_tasks (
            id TEXT PRIMARY KEY,
            instruction TEXT NOT NULL,
            plan TEXT NOT NULL,
            status TEXT NOT NULL,
            progress INTEGER DEFAULT 0,
            started_at INTEGER NOT NULL,
            completed_at INTEGER,
            steps TEXT,
            current_step_index INTEGER DEFAULT 0,
            error TEXT,
            checkpoints TEXT,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP
        )
    `);

    // Create index for faster status queries
    db.exec(`
        CREATE INDEX IF NOT EXISTS idx_robotkez_status
        ON robotkez_background_tasks(status)
    `);

    db.exec(`
        CREATE INDEX IF NOT EXISTS idx_robotkez_started_at
        ON robotkez_background_tasks(started_at DESC)
    `);

    return db;
}

export async function initTasksDb() {
    await getDb();
}

export async function saveTask(task: { agent: string; task: string; context?: string | null }) {
    const database = await getDb();
    if (!database) return null;

    const stmt = database.prepare('INSERT INTO tasks (agent, task, context) VALUES (?, ?, ?)');
    const result = stmt.run(task.agent, task.task, task.context || null);
    return result.lastInsertRowid as number;
}

export async function updateTaskStatus(id: number | bigint, status: string, result?: string) {
    const database = await getDb();
    if (!database) return;

    const isFinal = ['done', 'error', 'cancelled'].includes(status);
    const completedAt = isFinal ? new Date().toISOString() : null;
    const stmt = database.prepare('UPDATE tasks SET status = ?, result = ?, completed_at = ? WHERE id = ?');
    stmt.run(status, result || null, completedAt, id);
}

export async function getTasks(limit: number = 20, offset: number = 0, status?: string): Promise<TaskRow[]> {
    const database = await getDb();
    if (!database) return [];

    if (status) {
        const stmt = database.prepare('SELECT * FROM tasks WHERE status = ? ORDER BY created_at DESC LIMIT ? OFFSET ?');
        return stmt.all(status, limit, offset) as TaskRow[];
    }

    const stmt = database.prepare('SELECT * FROM tasks ORDER BY created_at DESC LIMIT ? OFFSET ?');
    return stmt.all(limit, offset) as TaskRow[];
}

export async function getTaskCount(status?: string): Promise<number> {
    const database = await getDb();
    if (!database) return 0;

    if (status) {
        const stmt = database.prepare('SELECT COUNT(*) as count FROM tasks WHERE status = ?');
        return (stmt.get(status) as any).count;
    }

    const stmt = database.prepare('SELECT COUNT(*) as count FROM tasks');
    return (stmt.get() as any).count;
}

export async function getTaskById(id: number): Promise<TaskRow | null> {
    const database = await getDb();
    if (!database) return null;

    const stmt = database.prepare('SELECT * FROM tasks WHERE id = ?');
    return (stmt.get(id) as TaskRow) || null;
}

export async function getTaskStats(): Promise<{
    total: number;
    successCount: number;
    errorCount: number;
    pendingCount: number;
    runningCount: number;
    cancelledCount: number;
    successRate: number;
    avgDurationMs: number;
    failedByAgent: Array<{ agent: string; count: number }>;
}> {
    const database = await getDb();
    if (!database) {
        return {
            total: 0,
            successCount: 0,
            errorCount: 0,
            pendingCount: 0,
            runningCount: 0,
            cancelledCount: 0,
            successRate: 0,
            avgDurationMs: 0,
            failedByAgent: []
        };
    }

    const counts = database.prepare(`
        SELECT
            COUNT(*) as total,
            SUM(CASE WHEN status = 'done' THEN 1 ELSE 0 END) as successCount,
            SUM(CASE WHEN status = 'error' THEN 1 ELSE 0 END) as errorCount,
            SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) as pendingCount,
            SUM(CASE WHEN status = 'running' THEN 1 ELSE 0 END) as runningCount,
            SUM(CASE WHEN status = 'cancelled' THEN 1 ELSE 0 END) as cancelledCount,
            AVG(CASE WHEN completed_at IS NOT NULL THEN (julianday(completed_at) - julianday(created_at)) * 86400000 ELSE NULL END) as avgDurationMs
        FROM tasks
    `).get() as any;

    const failedByAgent = database.prepare(`
        SELECT agent, COUNT(*) as count
        FROM tasks
        WHERE status = 'error'
        GROUP BY agent
        ORDER BY count DESC
    `).all() as Array<{ agent: string; count: number }>;

    const total = counts.total || 0;
    const successCount = counts.successCount || 0;
    const errorCount = counts.errorCount || 0;
    const successRate = total > 0 ? Math.round((successCount / total) * 1000) / 10 : 0;

    return {
        total,
        successCount,
        errorCount,
        pendingCount: counts.pendingCount || 0,
        runningCount: counts.runningCount || 0,
        cancelledCount: counts.cancelledCount || 0,
        successRate,
        avgDurationMs: Math.round(counts.avgDurationMs || 0),
        failedByAgent
    };
}

