/**
 * BackgroundTask interface (from backgroundTaskManager.ts)
 * Replicated here to avoid circular imports
 */
interface BackgroundTaskRow {
    id: string;
    instruction: string;
    plan: string; // JSON
    status: string;
    progress: number;
    started_at: number;
    completed_at?: number | null;
    steps: string; // JSON
    current_step_index: number;
    error?: string | null;
    checkpoints: string; // JSON
}

/**
 * Save a new background task to database
 *
 * @param task - BackgroundTask object
 */
export async function saveBackgroundTask(task: {
    id: string;
    instruction: string;
    plan: any;
    status: string;
    progress: number;
    startedAt: number;
    completedAt?: number;
    steps: any[];
    currentStepIndex: number;
    error?: string;
    checkpoints: any[];
}): Promise<void> {
    const database = await getDb();
    if (!database) return;

    const stmt = database.prepare(`
        INSERT INTO robotkez_background_tasks (
            id, instruction, plan, status, progress, started_at, completed_at,
            steps, current_step_index, error, checkpoints
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    stmt.run(
        task.id,
        task.instruction,
        JSON.stringify(task.plan),
        task.status,
        task.progress,
        task.startedAt,
        task.completedAt || null,
        JSON.stringify(task.steps),
        task.currentStepIndex,
        task.error || null,
        JSON.stringify(task.checkpoints)
    );
}

/**
 * Update an existing background task
 *
 * @param task - BackgroundTask object with updated fields
 */
export async function updateBackgroundTask(task: {
    id: string;
    status: string;
    progress: number;
    completedAt?: number;
    steps: any[];
    currentStepIndex: number;
    error?: string;
    checkpoints: any[];
}): Promise<void> {
    const database = await getDb();
    if (!database) return;

    const stmt = database.prepare(`
        UPDATE robotkez_background_tasks
        SET status = ?, progress = ?, completed_at = ?, steps = ?,
            current_step_index = ?, error = ?, checkpoints = ?
        WHERE id = ?
    `);

    stmt.run(
        task.status,
        task.progress,
        task.completedAt || null,
        JSON.stringify(task.steps),
        task.currentStepIndex,
        task.error || null,
        JSON.stringify(task.checkpoints),
        task.id
    );
}

/**
 * Load a background task by ID
 *
 * @param id - Task ID
 * @returns BackgroundTask object or null
 */
export async function loadBackgroundTask(id: string): Promise<any | null> {
    const database = await getDb();
    if (!database) return null;

    const stmt = database.prepare('SELECT * FROM robotkez_background_tasks WHERE id = ?');
    const row = stmt.get(id) as BackgroundTaskRow | undefined;

    if (!row) return null;

    return {
        id: row.id,
        instruction: row.instruction,
        plan: JSON.parse(row.plan),
        status: row.status,
        progress: row.progress,
        startedAt: row.started_at,
        completedAt: row.completed_at || undefined,
        steps: JSON.parse(row.steps),
        currentStepIndex: row.current_step_index,
        error: row.error || undefined,
        checkpoints: JSON.parse(row.checkpoints)
    };
}

/**
 * Load all background tasks (sorted by started_at desc)
 *
 * @param limit - Max tasks to return (default: 50)
 * @param status - Filter by status (optional)
 * @returns Array of BackgroundTask objects
 */
export async function loadAllBackgroundTasks(limit: number = 50, status?: string): Promise<any[]> {
    const database = await getDb();
    if (!database) return [];

    let stmt;
    let rows: BackgroundTaskRow[];

    if (status) {
        stmt = database.prepare('SELECT * FROM robotkez_background_tasks WHERE status = ? ORDER BY started_at DESC LIMIT ?');
        rows = stmt.all(status, limit) as BackgroundTaskRow[];
    } else {
        stmt = database.prepare('SELECT * FROM robotkez_background_tasks ORDER BY started_at DESC LIMIT ?');
        rows = stmt.all(limit) as BackgroundTaskRow[];
    }

    return rows.map(row => ({
        id: row.id,
        instruction: row.instruction,
        plan: JSON.parse(row.plan),
        status: row.status,
        progress: row.progress,
        startedAt: row.started_at,
        completedAt: row.completed_at || undefined,
        steps: JSON.parse(row.steps),
        currentStepIndex: row.current_step_index,
        error: row.error || undefined,
        checkpoints: JSON.parse(row.checkpoints)
    }));
}

/**
 * Delete a background task by ID
 *
 * @param id - Task ID
 */
export async function deleteBackgroundTask(id: string): Promise<void> {
    const database = await getDb();
    if (!database) return;

    const stmt = database.prepare('DELETE FROM robotkez_background_tasks WHERE id = ?');
    stmt.run(id);
}

/**
 * Get background task statistics
 *
 * @returns Stats object
 */
export async function getBackgroundTaskStats(): Promise<{
    total: number;
    running: number;
    completed: number;
    error: number;
    cancelled: number;
    avgProgress: number;
}> {
    const database = await getDb();
    if (!database) {
        return { total: 0, running: 0, completed: 0, error: 0, cancelled: 0, avgProgress: 0 };
    }

    const counts = database.prepare(`
        SELECT
            COUNT(*) as total,
            SUM(CASE WHEN status = 'running' THEN 1 ELSE 0 END) as running,
            SUM(CASE WHEN status = 'completed' THEN 1 ELSE 0 END) as completed,
            SUM(CASE WHEN status = 'error' THEN 1 ELSE 0 END) as error,
            SUM(CASE WHEN status = 'cancelled' THEN 1 ELSE 0 END) as cancelled,
            AVG(progress) as avgProgress
        FROM robotkez_background_tasks
    `).get() as any;

    return {
        total: counts.total || 0,
        running: counts.running || 0,
        completed: counts.completed || 0,
        error: counts.error || 0,
        cancelled: counts.cancelled || 0,
        avgProgress: Math.round(counts.avgProgress || 0)
    };
}

/**
 * Text-to-Speech Service
 *
 * Uses OpenAI TTS API with "nova" voice (same as AnythingLLM)
 * to provide Brunella's signature sultry voice experience.
 */

import { logInfo, logError } from './logger.js';

export type VoiceOption = 'alloy' | 'echo' | 'fable' | 'onyx' | 'nova' | 'shimmer';
export type TTSModel = 'tts-1' | 'tts-1-hd';

export interface TTSOptions {
  voice?: VoiceOption;
  model?: TTSModel;
  speed?: number; // 0.25 to 4.0
}

const DEFAULT_OPTIONS: Required<TTSOptions> = {
  voice: 'nova', // Brunella's signature voice! 🎙️
  model: 'tts-1',
  speed: 1.0,
};

/**
 * Generate speech audio from text using OpenAI TTS API
 *
 * @param text - Text to convert to speech (max ~4096 chars)
 * @param options - TTS configuration options
 * @returns Audio blob (MP3 format)
 */
export async function textToSpeech(
  text: string,
  options: TTSOptions = {}
): Promise<Blob> {
  const { voice, model, speed } = { ...DEFAULT_OPTIONS, ...options };

  const openaiApiKey = process.env.OPENAI_API_KEY;

  if (!openaiApiKey) {
    throw new Error('OpenAI API key not configured (OPENAI_API_KEY)');
  }

  if (!text || text.trim().length === 0) {
    throw new Error('Text cannot be empty');
  }

  // Truncate if too long (OpenAI TTS limit ~4096 chars)
  const maxLength = 4096;
  const truncatedText = text.length > maxLength
    ? text.slice(0, maxLength) + '...'
    : text;

  logInfo('TTS', `Generating speech: "${truncatedText.slice(0, 50)}..." (voice: ${voice}, model: ${model})`);

  try {
    const response = await fetch('https://api.openai.com/v1/audio/speech', {
      method: 'POST',
      headers: {
        'Authorization': `Bearer ${openaiApiKey}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        model,
        input: truncatedText,
        voice,
        speed,
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`OpenAI TTS API error (${response.status}): ${errorText}`);
    }

    const audioBlob = await response.blob();
    logInfo('TTS', `Speech generated successfully (${audioBlob.size} bytes)`);

    return audioBlob;
  } catch (error: any) {
    logError('TTS', `Failed to generate speech: ${error.message}`);
    throw error;
  }
}

/**
 * Play audio blob in browser
 *
 * @param audioBlob - Audio blob to play
 * @returns Promise that resolves when audio finishes playing
 */
export function playAudio(audioBlob: Blob): Promise<void> {
  return new Promise((resolve, reject) => {
    const audioUrl = URL.createObjectURL(audioBlob);
    const audio = new Audio(audioUrl);

    audio.onended = () => {
      URL.revokeObjectURL(audioUrl);
      resolve();
    };

    audio.onerror = (e) => {
      URL.revokeObjectURL(audioUrl);
      reject(new Error('Audio playback failed'));
    };

    audio.play().catch(reject);
  });
}

/**
 * Text-to-Speech convenience function
 * Generates speech and plays it immediately
 *
 * @param text - Text to speak
 * @param options - TTS options
 */
export async function speak(text: string, options: TTSOptions = {}): Promise<void> {
  const audioBlob = await textToSpeech(text, options);
  await playAudio(audioBlob);
}

// Export for backend API endpoint
export default {
  textToSpeech,
  playAudio,
  speak,
};

/**
 * Wrangler CLI Helper - Cloudflare deployment utilities
 * - D1 database initialization & migration
 * - Worker deployment
 * - Resource management
 */

import { execSync } from 'child_process';
import { existsSync, readFileSync } from 'fs';
import path from 'path';
import { logInfo, logError } from './logger.js';

export interface WranglerConfig {
  projectName: string;
  accountId: string;
  apiToken: string;
  d1DatabaseId?: string;
  workerScript?: string;
}

export class WranglerHelper {
  private config: WranglerConfig;
  private wranglerConfigPath: string;

  constructor(config: WranglerConfig) {
    this.config = config;
    this.wranglerConfigPath = path.join(process.cwd(), 'wrangler.toml');
  }

  /**
   * Check if Wrangler CLI is installed
   */
  async checkWranglerInstalled(): Promise<boolean> {
    try {
      execSync('wrangler --version', { stdio: 'pipe' });
      logInfo('WranglerHelper', 'Wrangler CLI is installed');
      return true;
    } catch (e: unknown) {
      logError('WranglerHelper', 'Wrangler CLI not installed. Run: npm install -g wrangler');
      return false;
    }
  }

  /**
   * Authenticate Wrangler with Cloudflare API token
   */
  async authenticate(apiToken: string): Promise<boolean> {
    try {
      process.env.CLOUDFLARE_API_TOKEN = apiToken;
      logInfo('WranglerHelper', 'Cloudflare API token set in environment');
      return true;
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError('WranglerHelper', `Authentication failed: ${error}`);
      return false;
    }
  }

  /**
   * Initialize D1 database
   * Command: wrangler d1 create <database-name>
   */
  async initializeD1(databaseName: string): Promise<string | null> {
    try {
      logInfo('WranglerHelper', `Initializing D1 database: ${databaseName}`);
      const output = execSync(`wrangler d1 create ${databaseName}`, {
        encoding: 'utf-8',
        env: { ...process.env, CLOUDFLARE_API_TOKEN: this.config.apiToken },
      });
      logInfo('WranglerHelper', `D1 database created: ${databaseName}`);
      return output;
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError('WranglerHelper', `D1 initialization failed: ${error}`);
      return null;
    }
  }

  /**
   * Run D1 migrations (applies schema)
   * Command: wrangler d1 execute <database-id> < schema.sql
   */
  async runD1Migration(databaseId: string, schemaPath: string): Promise<boolean> {
    try {
      if (!existsSync(schemaPath)) {
        logError('WranglerHelper', `Schema file not found: ${schemaPath}`);
        return false;
      }

      logInfo('WranglerHelper', `Running D1 migration from: ${schemaPath}`);
      const schemaContent = readFileSync(schemaPath, 'utf-8');
      
      // Write schema to temp file and execute
      execSync(
        `wrangler d1 execute ${databaseId} --file="${schemaPath}"`,
        {
          encoding: 'utf-8',
          env: { ...process.env, CLOUDFLARE_API_TOKEN: this.config.apiToken },
        }
      );

      logInfo('WranglerHelper', 'D1 migration completed successfully');
      return true;
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError('WranglerHelper', `D1 migration failed: ${error}`);
      return false;
    }
  }

  /**
   * Execute a D1 query
   * Command: wrangler d1 execute <database-id> --command="SELECT ..."
   */
  async executeD1Query(databaseId: string, query: string): Promise<unknown | null> {
    try {
      logInfo('WranglerHelper', `Executing D1 query: ${query.slice(0, 50)}...`);
      const output = execSync(
        `wrangler d1 execute ${databaseId} --command="${query}"`,
        {
          encoding: 'utf-8',
          env: { ...process.env, CLOUDFLARE_API_TOKEN: this.config.apiToken },
        }
      );
      return JSON.parse(output);
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError('WranglerHelper', `D1 query failed: ${error}`);
      return null;
    }
  }

  /**
   * Publish Cloudflare Worker
   * Command: wrangler publish
   */
  async publishWorker(): Promise<boolean> {
    try {
      logInfo('WranglerHelper', 'Publishing Cloudflare Worker...');
      
      if (!existsSync(this.wranglerConfigPath)) {
        logError('WranglerHelper', `wrangler.toml not found at ${this.wranglerConfigPath}`);
        return false;
      }

      execSync('wrangler publish', {
        cwd: process.cwd(),
        env: { ...process.env, CLOUDFLARE_API_TOKEN: this.config.apiToken },
      });

      logInfo('WranglerHelper', 'Worker published successfully');
      return true;
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError('WranglerHelper', `Worker publishing failed: ${error}`);
      return false;
    }
  }

  /**
   * Get list of D1 databases
   */
  async listD1Databases(): Promise<unknown | null> {
    try {
      logInfo('WranglerHelper', 'Listing D1 databases...');
      const output = execSync('wrangler d1 list', {
        encoding: 'utf-8',
        env: { ...process.env, CLOUDFLARE_API_TOKEN: this.config.apiToken },
      });
      return JSON.parse(output);
    } catch (e: unknown) {
      const error = e instanceof Error ? e.message : String(e);
      logError('WranglerHelper', `Listing D1 databases failed: ${error}`);
      return null;
    }
  }
}

/**
 * Singleton instance
 */
let instance: WranglerHelper | null = null;

export function initializeWrangler(config: WranglerConfig): WranglerHelper {
  if (!instance) {
    instance = new WranglerHelper(config);
  }
  return instance;
}

export function getWrangler(): WranglerHelper | null {
  return instance;
}
